comms.text:
@1 אִלֵין פִּתְגָמַיָא דִי מַלִיל מֹשֶׁה עִם כָּל יִשְׂרָאֵל בְּעִבְרָא דְיַרְדְנָא אוֹכַח יָתְהוֹן עַל דְחָבוּ בְמַדְבְּרָא וְעַל דְאַרְגִיזוּ בְמֵישְׁרָא לָקֳבֵל יַם סוּף בְּפָארָן אִתַּפָּלוּ עַל מַנָא וּבַחֲצֵרוֹת אַרְגִיזוּ עַל בִּשְׂרָא וְעַל דַעֲבָדוּ עֵגַל דִדְהָב:
@2 מַהֲלַךְ חָד עֲשַׂר יוֹמִין מֵחוֹרֵב אוֹרַח טּוּרָא דְשֵׂעִיר עַד רְקַם גֵיאָה:
@3 וַהֲוָה בְּאַרְבְּעִין שְׁנִין בְּחַד עֲשַׂר יַרְחָא בְּחַד לְיַרְחָא מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל כְּכֹל דִי פַקִיד יְיָ יָתֵהּ לְוָתְהוֹן:
@4 בָּתַר דִמְחָא יָת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה דְיָתֵב בְּחֶשְׁבּוֹן וְיָת עוֹג מַלְכָּא דְמַתְנָן דְיָתֵב בְּעַשְׁתָּרוֹת בְּאֶדְרֶעִי:
@5 בְּעִבְרָא דְיַרְדְנָא בְּאַרְעָא דְמוֹאָב שָׁרֵי מֹשֶׁה פָּרֵשׁ יָת אוּלְפַן אוֹרַיְתָא הָדָא לְמֵימָר:
@6 יְיָ אֱלָהָנָא מַלִיל עִמָנָא בְּחוֹרֵב לְמֵימָר סַגִי לְכוֹן דִיתֶבְתּוּן בְּטוּרָא הָדֵין:
@7 אִתְפְּנוּ וְטוּלוּ לְכוֹן וְעוּלוּ לְטּוּרָא דֶאֱמוֹרָאָה וּלְכָל מָגִירוֹהִי בְּמֵישְׁרַיָא בְטוּרָא וּבִשְׁפֶלְתָּא וּבִדְרוֹמָא וּבִסְפַר יַמָא אַרְעָא דִכְנַעֲנָאָה וְלִבְנָן עַד נַהֲרָא רַבָּא נַהֲרָא פְרָת:
@8 חֲזֵי דִיהָבִית קֳדָמֵיכוֹן יָת אַרְעָא עוּלוּ וְאַחֲסִינוּ יָת אַרְעָא דִי קַיַם יְיָ לַאֲבָהָתְכוֹן לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן בַּתְרֵיהוֹן:
@9 וַאֲמָרִית לְכוֹן בְּעִדָנָא הַהִיא לְמֵימָר לֵית אֲנָא יָכִיל בִּלְחוֹדִי לְסוֹבָרָא יָתְכוֹן:
@10 יְיָ אֱלָהָכוֹן אַסְגֵי יָתְכוֹן וְהָא אִיתֵיכוֹן יוֹמָא דֵין כְּכוֹכְבֵי שְׁמַיָא לִסְגֵי:
@11 יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יוֹסֵף עֲלֵיכוֹן כְּוָתְכוֹן אֲלַף זִמְנִין וִיבָרֵךְ יָתְכוֹן כְּמָא דִי מַלִיל לְכוֹן:
@12 אֶכְדֵין אֵסוֹבַר בִּלְחוֹדִי טָרְחֲכוֹן וְעִסְקֵיכוֹן וְדִינְכוֹן:
@13 הָבוּ לְכוֹן גֻבְרִין חַכִּימִין וְסוּכְלְתָנוּן וּמַדְעָן לְשִׁבְטֵיכוֹן וֶאֱמַנִנוּן רֵישִׁין עֲלֵיכוֹן:
@14 וַאֲתֶבְתּוּן יָתִי וַאֲמַרְתּוּן תַּקִין פִּתְגָמָא דִי מַלֶלְתָּא לְמֶעְבָּד:
@15 וּדְבָרִית יָת רֵישֵׁי שִׁבְטֵיכוֹן גֻבְרִין חַכִּימִין וּמַדְעָן וּמַנֵתִי יָתְהוֹן רֵישִׁין עֲלֵיכוֹן רַבָּנֵי אַלְפִין וְרַבָּנֵי מָאוָתָא וְרַבָּנֵי חַמְשִׁין וְרַבָּנֵי עִשׂוֹרְיָתָא וְסָרְכִין לְשִׁבְטֵיכוֹן:
@16 וּפַקֵדִית יָת דַיָנֵיכוֹן בְּעִדָנָא הַהִיא לְמֵימָר שְׁמָעוּ בֵּין אַחֵיכוֹן וּתְדוּנוּן קוּשְׁטָא בֵּין גַבְרָא וּבֵין אֲחוּהִי וּבֵין גִיוֹרֵהּ:
@17 לָא תִשְׁתְּמוֹדְעוּן אַפִּין בְּדִינָא מִלֵי זְעֵירָא כְרַבָּא תִּשְׁמְעוּן לָא תִדְחֲלוּן מִן קֳדָם גַבְרָא אֲרֵי דִינָא דַיְיָ הוּא וּפִתְגָמָא דִי יִקְשֵׁי מִנְכוֹן תְּקָרְבוּן לְוָתִי וְאֶשְׁמְעִנֵהּ:
@18 וּפַקֵדִית יָתְכוֹן בְּעִדָנָא הַהִיא יָת כָּל פִּתְגָמַיָא דִי תַעְבְּדוּן:
@19 וּנְטַלְנָא מֵחוֹרֵב וְהַלִיכְנָא יָת כָּל מַדְבְּרָא רַבָּא וּדְחִילָא הַהוּא דִי חֲזֵיתוּן אוֹרַח טוּרָא דֶאֱמוֹרָאָה כְּמָא דִי פַקִיד יְיָ אֱלָהָנָא יָתָנָא וַאֲתֵינָא עַד רְקַם גֵיאָה:
@20 וַאֲמָרִית לְכוֹן אֲתֵיתוּן עַד טוּרָא דֶאֱמוֹרָאָה דַיְיָ אֱלָהָנָא יָהֵיב לָנָא:
@21 חֲזֵי יְהַב יְיָ אֱלָהָךְ קֳדָמָךְ יָת אַרְעָא סַק אַחֲסֵין כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ לָא תִדְחַל וְלָא תִתְּבָּר:
@22 וּקְרֶבְתּוּן לְוָתִי כֻּלְכוֹן וַאֲמַרְתּוּן נִשְׁלַח גֻבְרִין קֳדָמָנָא וִיאַלְלוּן לָנָא יָת אַרְעָא וִיתִיבוּן יָתָנָא פִּתְגָמָא יָת אָרְחָא דִי נִסֵק בַּהּ וְיָת קִרְוַיָא דִי נֵעוֹל לְהֵן:
@23 וּשְׁפַר בְּעֵינַי פִּתְגָמָא וּדְבָרִית מִנְכוֹן תְּרֵין עֲשַׂר גֻבְרִין גַבְרָא חַד לְשִׁבְטָא:
@24 וְאִתְפְּנִיוּ וּסְלִיקוּ לְטוּרָא וַאֲתוֹ עַד נַחֲלָא דְאַתְכָּלָא וְאַלִילוּ יָתַהּ:
@25 וּנְסִיבוּ בִידֵיהוֹן מֵאִבָּא דְאַרְעָא וְאַחִיתוּ לָנָא וַאֲתִיבוּ יָתָנָא פִּתְגָמָא וַאֲמָרוּ טָבָא אַרְעָא דַיְיָ אֱלָהָנָא יָהֵיב לָנָא:
@26 וְלָא אֲבִיתוּן לְמִסַק וְסָרֶבְתּוּן עַל מֵימְרָא דַיְיָ אֱלָהֲכוֹן:
@27 וְאִתְרַעַמְתּוּן בְּמַשְׁכְּנֵיכוֹן וַאֲמַרְתּוּן בִּדְסָנֵי יְיָ יָתָנָא אַפְּקָנָא מֵאַרְעָא דְמִצְרָיִם לְמִמְסַר יָתָנָא בִּידָא דֶאֱמוֹרָאָה לְשֵׁיצָיוּתָנָא:
@28 לְאָן אֲנַחְנָא סָלְקִין אֲחָנָא תְבָרוּ יָת לִבָּנָא לְמֵימַר עַם רַב וְתַקִיף מִנָנָא קִרְוִין רַבְרְבָן וּכְרִיכָן עַד צֵית שְׁמַיָא וְאַף בְּנֵי גִבָּרָאֵי חֲזֵינָא תַמָן:
@29 וַאֲמָרִית לְכוֹן לָא תִתָּבְרוּן וְלָא תִדְחֲלוּן מִנְהוֹן:
@30 יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן הוּא יְגִיחַ לְכוֹן כְּכֹל דִי עֲבַד עִמְכוֹן בְּמִצְרַיִם לְעֵינֵיכוֹן:
@31 וּבְמַדְבְּרָא דִי חֲזֵיתָא דִי סוֹבְרָךְ יְיָ אֱלָהָךְ כְּמָא דִי מִסוֹבַר גַבְרָא יָת בְּרֵהּ בְּכָל אָרְחָא דִי הַלֶכְתּוּן עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין:
@32 וּבְפִתְגָמָא הָדֵין לֵיתֵיכוֹן מְהֵימְנִין בְּמֵ ימְ רָא דַיְיָ אֱלָהֲכוֹן:
@33 דִי מְדַבֵּר קֳדָמֵיכוֹן בְּאָרְחָא לְאַתְקְנָאָה לְכוֹן אֲתַר בֵּית מֵישְׁרִי לְאַשְׁרָיוּתְכוֹן בְּעַמוּדָא דְאֶשָׁתָא בְּלֵילְיָא לְאַחֲזָיוּתְכוֹן בְּאָרְחָא דִי תְהָכוּן בַּהּ וּבְעַמוּדָא דַעֲנָנָא בִּימָמָא:
@34 וּשְׁמִיעַ קֳדָם יְיָ יָת קַל פִּתְגָמֵיכוֹן וּרְגֵז וְקַיַם לְמֵימָר:
@35 אִם יֶחֱזֵי גְבַר בְּגֻבְרַיָא הָאִלֵין דָרָא בִישָׁא הָדֵין יָת אַרְעָא טַבְתָא דִי קַיֵמִית לְמִתַּן לַאֲבָהָתְכוֹן:
@36 אֱלָהֵן כָּלֵב בַּר יְפֻנֶה הוּא יֶחְזִנַהּ וְלֵהּ אֶתֵּן יָת אַרְעָא דִי דְרַךְ בַּהּ וְלִבְנוֹהִי חֲלַף דִי אַשְׁלִים בָּתַר דַחַלְתָּא דַיְיָ:
@37 אַף עֲלַי הֲוָה רְגַז מִן קֳדָם יְיָ בְּדִילְכוֹן לְמֵימָר אַף אַתְּ לָא תֵיעוֹל תַּמָן:
@38 יְהוֹשֻׁעַ בַּר נוּן דְקָאֵים קֳדָמָךְ הוּא יֵיעוֹל תַּמָן יָתֵהּ תַּקֵף אֲרֵי הוּא יַחְסְנִנַהּ לְיִשְׂרָאֵל:
@39 וְטַפְלְכוֹן דִי אֲמַרְתּוּן לְבִזָא יְהוֹן וּבְנֵיכוֹן דִי לָא יְדָעוּ יוֹמָא דֵין טַב וּבִישׁ אִנוּן יַעֲלוּן לְתַמָן וּלְהוֹן אֶתְּנִנַהּ וְאִנוּן יֵירְתֻנַהּ:
@40 וְאַתּוּן אִתְפְּנִיוּ לְכוֹן וְטוּלוּ לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף:
@41 וַאֲתֶבְתּוּן וַאֲמַרְתּוּן לִי חַבְנָא קֳדָם יְיָ אֲנַחְנָא נִיסַק וּנְגִיחַ קְרָב כְּכֹל דִי פַקְדָנָא יְיָ אֱלָהָנָא וְזָרֶזְתּוּן גְבַר יָת מָנֵי קְרָבֵהּ וְשָׁרֵיתוּן לְמֵיסַק לְטּוּרָא:
@42 וַאֲמַר יְיָ לִי אֱמַר לְהוֹן לָא תִסְקוּן וְלָא תְגִחוּן קְרָב אֲרֵי לֵית שְׁכִינְתִּי שָׁרְיָא בֵינֵיכוֹן וְלָא תִּתָּבְרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@43 וּמַלֵלִית עִמְכוֹן וְלָא קַבֶּלְתּוּן וְסָרֶבְתּוּן עַל גְזֵרַת מֵימְרָא דַיְיָ וְאַרְשַׁעְתּוּן וּסְלֶקְתּוּן לְטוּרָא:
@44 וּנְפַק אֱמֹרָאָה דְיָתֵב בְּטוּרָא הַהוּא לְקַדָמוּתְכוֹן וּרְדָפוּ יָתְכוֹן כְּמָא דִי נַתְּזָן דַבַּרְיָתָא וּטְרָדוּ יָתְכוֹן בְּשֵׂעִיר עַד חָרְמָה:
@45 וְתַבְתּוּן וּבְכִיתוּן קֳדָם יְיָ וְלָא קַבִּיל יְיָ צְלוֹתְכוֹן וְלָא אַצֵית לְמִלֵיכוֹן:
@46 וִיתֶבְתּוּן בִּרְקָם יוֹמִין סַגִיאִין כְּיוֹמַיָא דִי יְתֶבְתּוּן:
@47 וְאִתְפְּנֵינָא וּנְטַלְנָא לְמַדְבְּרָא אוֹרַח יַמָא דְסוּף כְּמָא דִי מַלִיל יְיָ עִמִי וְאַקֵפְנָא יָת טוּרָא דְשֵׂעִיר יוֹמִין סַגִיאִין:
@48 וַאֲמַר יְיָ לִי לְמֵימָר:
@49 סַגִי לְכוֹן דְאַקֶפְתּוּן יָת טוּרָא הָדֵין אִתְפְּנִיוּ לְכוֹן צִפּוּנָא:
@50 וְיָת עַמָא פַּקֵד לְמֵימַר אַתּוּן עָבְרִין בִּתְחוּם אֲחוּכוֹן בְּנֵי עֵשָׂו דְיָתְבִין בְּשֵׂעִיר וְיִדְחֲלוּן מִנְכוֹן וְתִסְתַּמְרוּן לַחֲדָא:
@51 לָא תִתְגָרוּן בְּהוֹן אֲרֵי לָא אֶתֵּן לְכוֹן מֵאַרְעֲהוֹן עַד מִדְרַךְ פַּרְסַת רִגְלָא אֲרֵי יְרֻתָּא לְעֵשָׂו יְהָבִית יָת טוּרָא דְשֵׂעִיר:
@52 עִבּוּרָא תִזְבְּנוּן מִנְהוֹן בְּכַסְפָּא וְתֵיכְלוּן וְאַף מַיָא תִּכְרוּן מִנְהוֹן בְּכַסְפָּא וְתִשְׁתּוּן:
@53 אֲרֵי יְיָ אֱלָהָךְ בֵּרְכָךְ בְּכָל עֹבַד יְדָךְ סַפֶּק לָךְ צָרְכָּךְ בְּמֶהָכָךְ יָת מַדְבְּרָא רַבָּא הָדֵין דְנַן אַרְבְּעִין שְׁנִין מֵימְרָא דַיְיָ אֱלָהָךְ בְּסַעֲדָךְ לָא מְנַעְתָּא מִדָעַם:
@54 וַעֲבַרְנָא מִלְוַת אֲחוּנָא בְנֵי עֵשָׂו דְיָתְבִין בְּשֵׂעִיר מֵאוֹרַח מֵישְׁרָא מֵאֵילַת וּמֶעְצְיוֹן גָבֶר וְאִתְפְּנֵינָא וַעֲבַרְנָא אוֹרַח מַדְבְּרָא דְמוֹאָב:
@55 וַאֲמַר יְיָ לִי לָא תְצוּר עַל מוֹאַבָאֵי וְלָא תִתְגָרֵי לְמֶעְבַּד עִמְהוֹן קְרָב אֲרֵי לָא אֶתֵּן לָךְ מֵאַרְעֵהּ יְרֻתָּא אֲרֵי לִבְנֵי לוֹט יְהָבִית יָת לְחָיָת יְרֻתָּא:
@56 אֵימְתָנֵי מִלְקַדְמִין יְתִיבוּ בַהּ עַם רַב וְסַגִי וְתַקִיף כְּגִבָּרַיָא:
@57 גִבָּרִין מִתְחַשְׁבִין אַף אִנוּן כְּגִבָּרַיָא וּמוֹאַבָאֵי קְרַן לְהוֹן אֵימְתָנֵי:
@58 וּבְשֵׂעִיר יְתִיבוּ חֹרָאֵי מִלְקַדְמִין וּבְנֵי עֵשָׂו תָּרֵכֻנוּן וְשֵׁצָיֻנוּן מִקֳדָמֵיהוֹן וִיתִיבוּ בְּאַתְרֵהוֹן כְּמָא דִי עֲבַד יִשְׂרָאֵל לְאַרְעָא יְרֻתָּתֵהּ דִיהַב יְיָ לְהוֹן:
@59 כְּעַן קוּמוּ וְעִבָרוּ לְכוֹן יָת נַחֲלָא דְזָרֶד וַעֲבַרְנָא יָת נַחֲלָא דְזָרֶד:
@60 וְיוֹמַיָא דִי הַלֶכְנָא מֵרְקַם גֵיאָה עַד דִי עֲבַרְנָא יָת נַחֲלָא דְזֶרֶד תְּלָתִין וְתַמְנֵי שְׁנִין עַד דְסַף כָּל דָרָא גֻבְרֵי מְגִיחֵי קְרָבָא מִגוֹ מַשְׁרִיתָא כְּמָא דִי קַיִים יְיָ לְהוֹן:
@61 וְאַף מָחָא מִן קֳדָם יְיָ הֲוַת בְּהוֹן לְשֵׁצָיוּתְהוֹן מִגוֹ מַשְׁרִיתָא עַד דִשְׁלִימוּ:
@62 וַהֲוָה כַּד שְׁלִימוּ כָּל גֻבְרֵי מְגִיחֵי קְרָבָא לִמְמַת מִגוֹ עַמָא:
@63 וּמַלִיל יְיָ עִמִי לְמֵימָר:
@64 אַתְּ עָבֵר יוֹמָא דֵין יָת תְּחוּם מוֹאָב יָת לְחָיָת:
@65 וְתִקְרַב לָקֳבֵל בְּנֵי עַמוֹן לָא תְצוּר עֲלֵיהוֹן וְלָא תִתְגָרֵי לְמֶעְבַּד עִמְהוֹן קְרָב אֲרֵי לָא אֶתֵּן מֵאַרְעָא בְנֵי עַמוֹן לָךְ יְרֻתָּא אֲרֵי לִבְנֵי לוֹט יְהָבִיתַּהּ יְרֻתָּא:
@66 אַרְעָא גִבָּרַיָא מִתְחַשְׁבָא אַף הִיא גִבָּרִין יָתִיבוּ בַהּ מִלְקַדְמִין וְעַמוֹנָאֵי קְרַן לְהוֹן חֻשְׁבָּנֵי:
@67 עַם רַב וְסַגִי וְתַקִיף כְּגִבְּרַיָא וְשֵׁצִנוּן יְיָ מִקֳדָמֵ יהוֹן וְתָרֵכֻנוּן וִיתִיבוּ בְאַתְרֵיהוֹן:
@68 כְּמָא דִי עֲבַד לִבְנֵי עֵשָׂו דְיָתְבוּן בְּשֵׂעִיר דִי שֵׁצֵי יָת חוֹרָאֵי מִקֳדָמֵיהוֹן וְתָרֵכִנוּן וִיתִיבוּ בְאַתְרֵיהוֹן עַד יוֹמָא הָדֵין:
@69 וְעַוָאֵי דְיָתְבִין בִּדְפִיחַ עַד עַזָה קַפּוּטְּקָאֵי דִנְפָקוּ מִקַפּוּטְקַיָא שֵׁצָיוּנוּן וִיתִיבוּ בְאַתְרֵיהוֹן:
@70 קוּמוּ טוּלוּ וְעִבָרוּ יָת נַחֲלָא דְאַרְנוֹן חֲזִי דִמְסָרִית בִּידָךְ יָת סִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן אֱמוֹרָאָה וְיָת אַרְעֵהּ שְׁרֵי לְתָרָכוּתֵהּ וְאִתְגָרֵי לְמֶעְבַּד עִמֵהּ קְרָבָא:
@71 יוֹמָא הָדֵין אֱשָׁרֵי לְמִתַּן זְעֻתָּךְ וְדַחַלְתָּךְ עַל אַפֵּי עַמְמַיָא דִי תְחוֹת כָּל שְׁמַיָא דִי יִשְׁמְעוּן שִׁמְעָךְ וִיזוּעוּן וְיִדְחֲלוּן מִן קֳדָמָךְ:
@72 וּשְׁלָחִית אִזְגַדִין מִמַדְבְּרָא דִקְדֵמוֹת לְוָת סִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן פִתְגָמֵי שְׁלָמָא לְמֵימָר:
@73 אֵעִבַר בְּאַרְעָךְ בְּאָרְחָא בְּאָרְחָא אֵזֵל לָא אֶסְטֵי יַמִינָא וּשְׂמָאלָא:
@74 עִבוּרָא בְּכַסְפָּא תְּזַבֶּן לִי וְאֵיכוּל וּמַיָא בְּכַסְפָּא תִּתֶּן לִי וְאֶשְׁתֵּי לְחוֹד אֵעִבַר בְּרַגְלָי:
@75 כְּמָא דִי עֲבָדוּ לִי בְּנֵי עֵשָׂו דְיָתְבִין בְּשֵׂעִיר וּמוֹאָבָאֵי דְיָתְבִין בִּלְחָיָת עַד דְאֵעִבַר יָת יַרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָנָא יָהֵב לָנָא:
@76 וְלָא אָבֵי סִיחֹן מַלְכָּא דְחֶשְׁבּוֹן לְמִשְׁבְּקָנָא לְמֶעְבַּר בִּתְחוּמֵהּ אֲרֵי אַקְשִׁי יְיָ אֱלָהָךְ יָת רוּחֵהּ וְתַקִיף יָת לִבֵּהּ בְּדִיל לְמִמְסְרֵהּ בִּידָךְ כְּיוֹמָא הָדֵין:
@77 וַאֲמַר יְיָ לִי חֲזֵי שָׁרֵיתִי לְמִמְסַר קֳדָמָךְ יָת סִיחֹן וְיָת אַרְעֵהּ שְׁרֵי לְתָרָכוּתֵהּ לְמֵירַת יָת אַרְעֵהּ:
@78 וּנְפַק סִיחֹן לְקַדָמוּתָנָא הוּא וְכָל עַמֵהּ לַאֲגָחָא קְרָבָא לְיָהַץ:
@79 וּמָסְרֵהּ יְיָ אֱלָהָנָא קֳדָמָנָא וּמְחֵנָא יָתֵהּ וְיָת בְּנוֹהִי וְיָת כָּל עַמֵהּ:
@80 וּכְבַשְׁנָא יָת כָּל קִרְווֹהִי בְּעִדָנָא הַהִיא וְגַמַרְנָא יָת כָּל קִרְוֵי גֻבְרַיָא וּנְשַׁיָא וְטַפְלָא לָא אַשְׁאַרְנָא מְשֵׁזִבִ:
@81 לְחוֹד בְּעִירָא בַּזָנָא לָנָא וַעֲדִי קִרְוַיָא דִי כְבַשְׁנָא:
@82 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְקַרְתָּא דִי בְנַחֲלָא וְעַד גִלְעָד לָא הֲוַת קַרְתָּא דִי תְקֵפַת מִנָנָא יָת כֹּלָא מְסַר יְיָ אֱלָהָנָא קֳדָמָנָא:
@83 לְחוֹד לְאַרְעָא בְנֵי עַמוֹן לָא קְרֶבְתָּא כָּל כֵּיף נַחֲלָא יוּבְקָא וְקִרְוֵי טוּרָא וְכֹל דִי פַקִיד יְיָ אֱלָהָנָא:
@84 וְאִתְפְּנֵינָא וּסְלֶקְנָא אֹרַח דְמַתְנָן וּנְפַק עוֹג מַלְכָּא דְמַתְנָן לְקַדָמוּתָנָא הוּא וְכָל עַמֵהּ לַאֲגָחָא קְרָבָא אֶדְרֶעִי:
@85 וַאֲמַר יְיָ לִי לָא תִדְחַל מִנֵיהּ אֲרֵי בִידָךְ מְסָרִית יָתֵהּ וְיָת כָּל עַמֵהּ וְיָת אַרְעֵהּ ותַעְבֶּד לֵהּ כְּמָא דִי עֲבַדְתָּא לְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן:
@86 וּמְסַר יְיָ אֱלָהָנָא בִּידָנָא אַף יָת עוֹג מַלְכָּא דְמַתְנָן וְיָת כֹּל עַמֵהּ וּמְחִנוֹהִי עַד דְלָא אִשְׁתָּאַר לֵהּ מְשֵׁזֵב:
@87 וּכְבַשְׁנָא יָת כָּל קִרְווֹהִי בְּעִדָנָא הַהִיא לָא הֲוַת קַרְתָּא דִי לָא נְסִבְנָא מִנְהוֹן שִׁתִּין קִרְוִין כָּל בֵּית פָּלָךְ טְרָכוֹנָא מַלְכוּתָא דְעוֹג בְּמַתְנָן:
@88 כָּל אִלֵין קִרְוִין כְּרִיכָן מַקְפָן שׁוּר רָם דִילְהֶן דָשִׁין וְעַבְּרִין בַּר מִקִרְוֵי פַּצְחַיָא סַגִי לַחֲדָא:
@89 וְגַמַרְנָא יָתְהוֹן כְּמָא דִי עֲבַדְנָא לְסִיחוֹן מַלְכָּא דְחֶשְׁבּוֹן גַמַר כָּל קִרְוֵי גֻבְרַיָא נְשַׁיָא וְטַפְלָא:
@90 וְכָל בְּעִירָא וַעֲדִי קִרְוַיָא בַּזָנָא לָנָא:
@91 וּנְסִבְנָא בְּעִדָנָא הַהִיא יָת אַרְעָא מִיַד תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִנַחֲלָא דְאַרְנֹן עַד טוּרָא דְחֶרְמוֹן:
@92 צִידֹנָאֵי קְרָאָן לְחֶרְמוֹן סִרְיֹן וֶאֱמֹרָאֵי קְרָאָן לֵהּ טוּר תַּלְגָא:
@93 כֹּל קִרְוֵי מֵישְׁרָא וְכָל גִלְעָד וְכָל מַתְנָן עַד סַלְכָה וְאֶדְרֶעִי קִרְוֵי מַלְכוּתָא דְעוֹג בְּמַתְנָן:
@94 אֲרֵי לְחוֹד עוֹג מַלְכָּא דְמַתְנָן אִשְׁתָּאַר מִשְׁאָר גִבָּרַיָא הָא עַרְסֵהּ עַרְסָא דְפַרְזְלָא הֲלָא הִיא בְּרַבַּת בְּנֵי עַמוֹן תְּשַׁע אַמִין אָרְכַּהּ וְאַרְבַּע אַמִין פְּתָיַהּ בְּאַמַת מְלַךְ:
@95 וְיָת אַרְעָא הָדָא יְרִיתְנָא בְּעִדָנָא הַהִיא מֵעֲרֹעֵר דִי עַל נַחֲלָא דְאַרְנֹן וּפַלְגוּת טּוּרָא דְגִלְעָד וְקִרְווֹהִי יְהָבִית לְשִׁבְטָא דִרְאוּבֵן וּלְשִׁבְטָא דְגָד:
@96 וּשְׁאָר גִלְעָד וְכָל מַתְנָן מַלְכוּתָא דְעוֹג יְהָבִית לְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה כֹּל בֵּית פָּלַךְ טְרָכוֹנָא לְכָל מַתְנָן הַהוּא מִתְקְרֵי אַרְעָא גִבָּרַיָא:
@97 יָאִיר בַּר מְנַשֶׁה נְסִיב יָת כָּל בֵּית פְּלַךְ טְרָכוֹנָא עַד תְּחוּם גְשׁוּרָאָה וְאַפְקֵירוֹס וּקְרָא יָתְהוֹן עַל שְׁמֵהּ יָת מַתְנָן כַּפְרָנֵי יָאִיר עַד יוֹמָא הָדֵין:
@98 וּלְמָכִיר יְהָבִית יָת גִלְעָד:
@99 וּלְשִׁבְטָא דִרְאוּבֵן וּלְשִׁבְטָּא דְגָד יְהָּבִית מִן גִלְעָד וְעַד נַחֲלָא דְאַרְנֹן גוֹ נַחֲלָא וּתְחוּם וְעַד יוּבְקָא דְנַחֲלָא תְּחוּם בְּנֵי עַמוֹן:
@100 וּמֵישְׁרָא וְיַרְדְנָא וּתְחוּמֵהּ מִגֵנוֹסַר וְעַד יַמָא דְמֵישְׁרָא יַמָא דְמִלְחָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא מָדִינְחָא:
@101 וּפַקֵדִית יָתְכוֹן בְּעִדָנָא הַהִיא לְמֵימָר יְיָ אֱלָהֲכוֹן יְהַב לְכוֹן יָת אַרְעָא הָדָא לְמֵירְתַהּ מְזָרְזִין תַּעְבְּרוּן קֳדָם אֲחֵיכוֹן בְּנֵי יִשְׂרָאֵל כָּל מְזָרְזֵי חֵילָא:
@102 לְחוֹד נְשֵׁיכוֹן וְטַפְלְכוֹן וּבְעִירְכוֹן יְדַעְנָא אֲרֵי בְעִיר סַגִי לְכוֹן יֵתְבוּן בְּקִרְוֵיכוֹן דִי יְהָבִית לְכוֹן:
@103 עַד דִי יְנִיחַ יְיָ לַאֲחֵיכוֹן כְּוָתְכוֹן וְיֵרְתוּן אַף אִנוּן יָת אַרְעָא דַיְיָ אֱלָהֲכוֹן יָהֵב לְהוֹן בְּעִבְרָא דְיַרְדְנָא וּתְתוּבוּן גְבַר לִירֻתְּתֵהּ דִי יְהָבִית לְכוֹן:
@104 וְיָת יְהוֹשׁוּעַ פַּקֵדִית בְּעִדָנָא הַהִיא לְמֵימָר עֵינָיךְ חֲזָאָן יָת כָּל דִי עֲבַד יְיָ אֱלָהֲכוֹן לִתְרֵין מַלְכַיָא הָאִלֵין כֵּן יַעְבֵּד יְיָ לְכָל מַלְכְּוָתָא דִי אַתְּ עָבֵר לְתַמָן:
@105 לָא תִדְחֲלוּן מִנְהוֹן אֲרֵי יְיָ אֱלָהָכוֹן מֵימְרֵהּ מְגִיחַ לְכוֹן: ססס:
@106 וְצַלֵיתִי קֳדָם יְיָ בְּעִדָנָא הַהִיא לְמֵימָר:
@107 יְיָ אֱלֹהִים אַתְּ שָׁרֵיתָא לְאַחֲזָאָה יָת עַבְדָךְ יָת רְבוּתָךְ וְיָת יְדָךְ תַּקֶפְתָּא דִי אַתְּ הוּא אֱלָהָא דִשְׁכִנְתָּךְ בִּשְׁמַיָא מִלְעֵלָא וְשַׁלִיט בְּאַרְעָא וְלֵית דְיַעְבֵּד כְּעוֹבְדָיךְ וּכְגִבָּרְתָּךְ:
@108 אֵעִבַר כְּעַן וְאֶחֱזֵי יָת אַרְעָא טַבְתָא דִּי בְּעִבְרָא דְיַרְדְנָא טוּרָא טָּבָא הָדֵין וּבֵית מַקְדָשָׁא:
@109 וַהֲוָה רְגַז מִן קֳדָם יְיָ עֲלַי בְּדִילְכוֹן וְלָא קַבִּיל מִנִי וַאֲמַר יְיָ לִי סַגִי לָךְ לָא תוֹסֵף לְמַלָלָא קֳדָמַי עוֹד בְּפִתְגָמָא הָדֵין:
@110 סַק לְרֵישׁ רָמָתָא וּזְקוֹף עֵינָיךְ לְמַעֲרָבָא וּלְצִפּוּנָא וְלִדְרוֹמָא וּלְמָדִינְחָא וַחֲזֵי בְעֵינָיךְ אֲרֵי לָא תְעִבַר יָת יַרְדְנָא הָדֵין:
@111 וּפַקֵד יָת יְהוֹשֻׁעַ וְתַקֶפְהִי וְאַלֶמְהִי אֲרֵי הוּא יֵעִבַר קֳדָם עַמָא הָדֵין וְהוּא יַחְסֵן יָתְהוֹן יָת אַרְעָא דִי תֶחֱזֵי:
@112 וִיתֵבְנָא בְחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר:
@113 וּכְעַן יִשְׂרָאֵל שְׁמַע לִקְיָמַיָא וּלְדִינַיָא דִי אֲנָא מְאַלֵף יָתְכוֹן לְמֶעְבַּד בְּדִיל דְתֵיחוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יָהֵב לְכוֹן:
@114 לָא תוֹסְפוּן עַל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן וְלָא תִמְנְעוּן מִנֵהּ לְמִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן:
@115 עֵינֵיכוֹן חָזָן יָת דִי עֲבַד יְיָ בְּבַעַל פְּעוֹר אֲרֵי כָּל גַבְרָא דִי אֲזַל בָּתַר בַּעַל פְּעוֹר שֵׁצְיֵהּ יְיָ אֱלָהָךְ מִבֵּינָךְ:
@116 וְאַתּוּן דְאַדְבֶּקְתּוּן בְּדַחַלְתָּא דַיְיָ אֱלָהֲכוֹן קַיָמִין כֻּלְכוֹן יוֹמָא דֵין:
@117 חֲזוֹ דְאַלֵפִית יָתְכוֹן קְיָמַיָא וְדִינַיָא כְּמָא דִי פַקְדַנִי יְיָ אֱלָהָי לְמֶעְבַּד כֵּן בְּגוֹ אַרְעָא דִי אַתּוּן עַלִין תַּמָן לְמֵירְתַהּ:
@118 וְתִטְרוּן וְתַעְבְּדוּן אֲרֵי הִיא חָכְמַתְכוֹן וְסוּכְלְתָנוּתְכוֹן לְעֵינֵי עַמְמַיָא דִי יִשְׁמְעוּן יָת כָּל קְיָמַיָא הָאִלֵין וְיֵימְרוּן לְחוֹד עַם חַכִּים וְסוּכְלְתָן עַמָא רַבָּא הָדֵין:
@119 אֲרֵי מָן עַם רַב דִי לֵהּ אֱלָהָא קָרִיב לֵהּ לְקַבָּלָא צְלוֹתֵהּ בְּעִדַן עַקְתֵהּ כַּייָ אֱלָהָנָא בְּכָל עִדָן דַאֲנַחְנָא מְצַלִין קֳדָמוֹהִי:
@120 וּמָן עַם רַב דִי לֵהּ קְיָמִין וְדִינִין קַשִׁיטִין כְּכֹל אוֹרַיְתָא הָדָא דִי אֲנָא יָהֵב קֳדָמֵכוֹן יוֹמָא דֵין:
@121 לְחוֹד אִסְתַּמַר לָךְ וְטַר נַפְשָׁךְ לַחֲדָא דִילְמָא תִנְשֵׁי יָת פִּתְגָמַיָא דִי חֲזוֹ עֵינָיִךְ וְדִילְמָא יְעִדוּן מִלִבָּךְ כֹּל יוֹמֵי חַיָיךְ וּתְהוֹדְעִנוּן לִבְנָיךְ וְלִבְנֵי בְנָיִךְ:
@122 יוֹמָא דִי קַמְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב כַּד אֲמַר יְיָ לִי כְּנוֹשׁ קֳדָמַי יָת עַמָא וְאַשְׁמְעִנוּן יָת פִּתְגָמָי דִי יֵלְפוּן לְמִדְחַל קֳדָמַי כָּל יוֹמַיָא דִי אִנוּן קַיָמִין עַל אַרְעָא וְיָת בְּנֵיהוֹן יְאַלְפוּן:
@123 וּקְרֶבְתּוּן וְקַמְתּוּן בְּשִׁפּוֹלֵי טוּרָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא עַד צֵית שְׁמַיָא חֲשׁוֹכָא עֲנָנָא וַאֲמִיטְתָא:
@124 וּמַלִיל יְיָ עִמְכוֹן מִגוֹ אֶשְׁתָא קַל פִּתְגָמִין אַתּוּן שָׁמְעִין וּדְמוּת לֵיתֵיכוֹן חָזָן אֱלָהֵן קָלָא:
@125 וְחַוִי לְכוֹן יָת קְיָמֵהּ דִי פַקִיד יָתְכוֹן לְמֶעְבַּד עַשְׂרָא פִּתְגָמִין וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא:
@126 וְיָתִי פַּקִיד יְיָ בְּעִדְנָא הַהִיא לְאַלָפָא יַתְכוֹן קְיָמִין וְדִינִין לְמֶעְבָּדְכוֹן יָתְהוֹן בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@127 וְתִסְתַּמְרוּן לַחֲדָא לְנַפְשָׁתֵיכוֹן אֲרֵי לָא חֲזֵיתוּן כָּל דְמוּת בְּיוֹמָא דִי מַלִיל יְיָ עִמְכוֹן בְּחֹרֵב מִגוֹ אֶשָׁתָא:
@128 דִילְמָא תְּחַבְּלוּן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כָּל צוּרָא דְמוּת דְכַר אוֹ נֻקְבָא:
@129 דְמוּת כָּל בְּעִירָא דִי בְאַרְעָא דְמוּת כָּל צִפַּר גַדְפָא דִי פָּרַח בַּאֲוֵר רְקִיע שְׁמַיָא:
@130 דְמוּת כָּל רִחֲשָׁא דִי בְאַרְעָא דְמוּת כָּל נוּנֵי דִי בְמַיָא מִלְרַע לְאַרְעָא:
@131 וְדִילְמָא תִזְקוֹף עֵינָיךְ לִשְׁמַיָא וְתֶחֱזֵי יָת שִׁמְשָׁא וְיָת סִיהֲרָא וְיָת כּוֹכְבַיָא כֹּל חֵילֵי שְׁמַיָא וְתִטְעֵי וְתִסְגוּד לְהוֹן וְתִפְלְחִנוּן דִי זַמִין יְיָ אֱלָהָךְ יָתְהוֹן לְכֹל עַמְמַיָא תְּחוֹת כָּל שְׁמַיָא:
@132 וְיָתְכוֹן קָרִיב יְיָ לְדַחַלְתֵּהּ וְאַפֵּק יָתְכוֹן מִכּוּרָא דְפַרְזְלָא מִמִצְרָיִם לְמֶהֱוֵי לֵהּ לְעַמָא אַחֲסָנָא כְּיוֹמָא הָדֵין:
@133 וּמִן קֳדָם יְיָ הֲוָה רְגַז עֲלַי עַל פִּתְגָמֵיכוֹן וְקַיִים בְּדִיל דְלָא לְמֵעֲבַר יָת יַרְדְנָא וּבְדִיל דְלָא לְמֵיעַל לְאַרְעָא טָבָא דִי יְיָ אֱלָהָךְ יָהֵבּ לָךְ אַחֲסָנָא:
@134 אֲרֵי אֲנָא מָאִית בְּאַרְעָא הָדָא לֵית אֲנָא עָבֵר יָת יַרְדְנָא וְאַתּוּן עָבְרִין וְתֵירְתוּן יָת אַרְעָא טָבָא הָדָא:
@135 אִסְתַּמָרוּ לְכוֹן דִילְמָא תִתְנְשׁוּן יָת קְיָמָא דַיְיָ אֱלָהֲכוֹן דִי גְזַר עִמְכוֹן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כֹּלָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@136 אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא אֵל קַנָא:
@137 אֲרֵי תוֹלְדוּן בְּנִין וּבְנֵי בְנִין וְתִתְעַתְּקוּן בְּאַרְעָא וּתְחַבְּלוּן וְתַעְבְּדוּן צֶלֶם דְמוּת כֹּלָא וְתַעְבְּדוּן דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְאַרְגָזָא קֳדָמוֹהִי:
@138 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא אֲרֵי מֵיבַד תֵּיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא לְתַמָן לְמֵירְתַהּ לָא תוֹרְכוּן יוֹמִין עֲלַהּ אֲרֵי אִשְׁתְּצָאָה תִּשְׁתֵּצוּן:
@139 וִיבַדַר יְיָ יָתְכוֹן בְּעַמְמַיָא וְתִשְׁתָּאֲרוּן עַם דְמִנְיָן בְּעַמְמַיָא דִי יְדַבַּר יְיָ יָתְכוֹן לְתַמָן:
@140 וְתִפְלְחוּן תַּמָן לְעַמְמַיָא פָלְּחֵי טַעֲוָתָא עֹבַד יְדֵי אֱנָשָׁא אָעָא וְאַבְנָא דִי לָא יֶחֱזוּן וְלָא שָׁמְעִין וְלָא אָכְלִין וְלָא מְרִיחִין:
@141 וְתִתְבְּעוּן מִתַּמָן יָת דַחֲלְתָּא דַייָ אֱלָהָךְ וְתִשְׁכָּח אֲרֵי תִבְעֵי מִן קֳדָמוֹהִי בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@142 כַּד יֵיעוֹק לָךְ וְיַשְׁכְּחֻנָךְ כֹּל פִּתְגָמַיָא הָאִלֵין בְּסוֹף יוֹמַיָא וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ:
@143 אֲרֵי אֱלָהָא רַחֲמָנָא יְיָ אֱלָהָךְ לָא יִשְׁבְּקִנָךְ וְלָא יְחַבְּלִנָךְ וְלָא יִתִּנְשֵׁי יָת קְיָמָא דַאֲבָהָתָךְ דִי קַיִים לְהוֹן:
@144 אֲרֵי שְׁאֵל כְּעַן לְיוֹמַיָא קַדְמָאֵי דַהֲווֹ קֳדָמָךְ לְמִן יוֹמָא דִי בְרָא יְיָ אָדָם עַל אַרְעָא וּלְמִסְיָפֵי שְׁמַיָא וְעַד סְיָפֵי שְׁמַיָא הַהֲוָה כְּפִתְגָמָא רַבָּא הָדֵין אוֹ הַאִשְׁתְּמַע כְּוָתֵהּ:
@145 הַשְׁמַע עַמָא קַל מֵימְרָא דַיְיָ מְמַלֵל מִגוֹ אֶשָׁתָא כְּמָא דִי שְׁמַעַתְּ אַתְּ וְיִתְקַיָם:
@146 אוֹ נִסִין דִי עֲבַד יְיָ לְאִתְגַלָאָה לְמִפְרַק לֵהּ עַם מִגוֹ עַם בְּנִסִין בְּאָתִין וּבְמוֹפְתִין וּבִקְרָבָא וּבִידָא תַקִיפָא וּבִדְרָעָא מְרָמָא וּבְחֶזְוָנִין רַבְרְבִין כְּכֹל דִי עֲבַד לְכוֹן יְיָ אֱלָהֲכוֹן בְּמִצְרַיִם לְעֵינָיךְ:
@147 אַתְּ אִתְחֲזֵיתָא לְמִדַע אֲרֵי יְיָ הוּא אֱלֹהִים לֵית עוֹד בַּר מִנֵהּ:
@148 מִן שְׁמַיָא אַשְׁמְעָךְ יָת קָל מֵימְרֵהּ לְאַלָפוּתָךְ וְעַל אַרְעָא אַחְזְיָךְ יָת אֶשָׁתֵהּ רַבְּתָא וּפִתְגָמוֹהִי שְׁמַעַתְּ מִגוֹ אֶשָׁתָא:
@149 וָחֳלַף אֲרֵי רְחִים יָת אֲבָהָתָךְ וְאִתִּרְעֵי בִּבְנוֹהִי בַּתְרוֹהִי וְאַפְּקָךְ בְּמֵימְרֵהּ בְּחֵילֵהּ רַבָּא מִמִצְרָיִם:
@150 לְתָרָכָא עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ מִן קֳדָמָךְ לְאָעָלוּתָךְ לְמִתַּן לָךְ יָת אַרְעֲהוֹן אַחֲסָנָא כְּיוֹמָא הָדֵין:
@151 וְתִדַע יוֹמָא דֵין וּתְתוּב לְלִבָּךְ אֲרֵי יְיָ הוּא אֱלָהָא דִשְׁכִנְתֵּהּ בִּשְׁמַיָא מִ לְעֵלָא וְשַׁלִיט עַל אַרְעָא מִלְרָע לֵית עוֹד:
@152 וְתִטַר יָת קְיָמוֹהִי וְיָת פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין דִי יֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ וּבְדִיל דְתוֹרִיךְ יוֹמִין עַל אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ כָּל יוֹמַיָא:
@153 בְּכֵן יַפְרֵשׁ מֹשֶׁה תְּלַת קִרְוִין בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@154 לְמֵעִירוֹק תַּמָן קָטוֹלָא דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵי וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקַמוֹהִי וְיֵעִרוֹק לְחַד מִן קִרְוַיָא הָאִלֵין וְיִתְקַיָם:
@155 יָת בֶּצֶר בְּמַדְבְּרָא בְּאַרְעָא מֵישְׁרָא לְשִׁבְטָּא דִרְאוּבֵן וְיָת רָאמוֹת בַּגִלְעָד לְשִׁבְטָא דְגָד וְיָת גוֹלָן בְּמַתְנָן לְשִׁבְטָא דִמְנַשֶׁה:
@156 וְדָא אוֹרַיְתָא דִי סַדַר מֹשֶׁה קֳדָם בְּנֵי יִשְׂרָאֵל:
@157 אִלֵין סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@158 בְּעִבְרָא דְיַרְדְנָא בְּחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר בְּאַרְעָא דְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן דִי מְחָא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@159 וִירִיתוּ יָת אַרְעֵהּ וְיָת אַרְעָא דְעוֹג מַלְכָּא דְמַתְנָן תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@160 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְעַד טוּרָא דְשִׂיאֹן הוּא חֶרְמוֹן:
@161 וְכָל מֵישְׁרָא עִבְרָא דְיַרְדְנָא לְמָדִינְחָא וְעַד יַמָא דְמֵישְׁרָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא:
@162 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן שְׁמַע יִשְׂרָאֵל יָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְמַלֵל קֳדָמֵיכוֹן יוֹמָא דֵין וְתַלְפוּן יָתְהוֹן וְתִטְרוּן לְמֶעְבָּדְהוֹן:
@163 יְיָ אֱלָהָנָא גְזַר עִמָנָא קְיָם בְּחֹרֵב:
@164 לָא עִם אֲבְהָתָנָא גְזַר יְיָ יָת קְיָמָא הָדָא אֶלָהֵן עִמָנָא אֲנַחְנָא אִלֵין הָכָא יוֹמָא דֵין כֻּלָנָא קַיָמִין:
@165 מַמְלָל עִם מַמְלָל מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא:
@166 אֲנָא הֲוֵיתִי קָאֵם בֵּין מֵימְרָא דַיְיָ וּבֵינֵיכוֹן בְּעִדָנָא הַהִיא לְחַוָאָה לְכוֹן יָת פִּתְגָמָא דַיְיָ אֲרֵי דְחֶלְתּוּן מִקֳדָם אֵשָׁתָא וְלָא סְלֶקְתּוּן בְּטוּרָא לְמֵימָר:
@167 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּקְתָּךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עֲבְדוּתָא:
@168 לָא יְהֵא לָךְ אֱלָהּ אָחָרָן בַּר מִנִי:
@169 לָא תַעְבֵּד לָךְ צֶלֶם כָּל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@170 לָא תִסְגוּד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשַׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵּי בָּתַר אֲבָהָתְהוֹן:
@171 וְעָבֵד טֵּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְּרֵי פִקוֹדָי:
@172 לָא תֵימֵי בִּשְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יְזַכֵּי יְיָ יָת דִי יֵמֵי בִשְׁמֵהּ לְשִׁקְרָא:
@173 טַר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@174 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@175 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עֲבִידָא אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְתוֹרָךְ וַחֲמָרָךְ וְכָל בְּעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ בְּדִיל דִי יְנוּחַ עַבְדָךְ וְאַמְתָךְ כְּוָתָךְ:
@176 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וְאַפְּקָךְ יְיָ אֱלָהָךְ מִתַּמָן בִּידָא תַקִיפָא וּבִדְרָעָא מְרָמְמָא עַל כֵּן פַּקְדָךְ יְיָ אֱלָהָךְ לְמֶעְבַּד יָת יוֹמָא דְשַׁבְּתָא:
@177 יַקַר יָת אֲבוּךְ וְיָת אִמָךְ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ וּבְדִיל דְיֵיטַב לָךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@178 לָא תִקְטוֹל נְפָשׁ וְלָא תְגוּף וְלָא תִגְנוֹב (נַפְשָׁא) וְלָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@179 וְלָא תַחְמֵד אִתַּת חַבְרָךְ וְלָא תֵרוֹג בֵּית חַבְרָךְ חַקְלֵהּ וְעַבְדֵהּ וְאַמְתֵהּ תּוֹרֵה וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@180 יָת פִּתְגָמַיָא הָאִלֵין מַלִיל יְיָ עִם כָּל קְהָלְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא עֲנָנָא וַאֲמִיטְתָא קָל רַב וְלָא פְסַק וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא וִיהָבִנָן לִי:
@181 וַהֲוָה כַּד שְׁמַעֲכוֹן יָת קָלָא מִגוֹ חֲשׁוֹכָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא וְקָרֶבְתּוּן לְוָתִי כָּל רֵישֵׁי שִׁבְטֵיכוֹן וְסָבֵיכוֹן:
@182 וַאֲמַרְתּוּן הָא אַחְזְיָנָא יְיָ אֱלָהָנָא יָת יְקָרֵהּ וְיָת רְבוּתֵהּ וְיָת קָל מֵימְרֵהּ שְׁמַעְנָא מִגוֹ אֶשָׁתָא יוֹמָא הָדֵין חֲזֵינָא אֲרֵי יְמַלֵל יְיָ עִם אֲנָשָׁא וְיִתְקַיָם:
@183 וּכְעַן לְמָא נְמוּת אֲרֵי תֵיכְלִנָנָא אֶשָׁתָא רַבְּתָא הָדָא אִם מוֹסְפִין אֲנַחְנָא לְמִשְׁמַע יָת קָל מֵימְרָא דַייָ אֱלָהָנָא עוֹד וּמָיְתִין אֲנַחְנָא:
@184 אֲרֵי מָן כָּל בִּשְׂרָא דִי שְׁמַע קָל מֵימְרָא דַיְיָ קַיָמָא מְמַלֵל מִגוֹ אֶשָׁתָא כְּוָתָנָא וְאִתְקַיָם:
@185 קְרַב אַתְּ וּשְׁמַע יָת כָּל דִי יֵימַר יְיָ אֱלָהָנָא וְאַתְּ תְּמַלֵל עִמָנָא יָת כָּל דִי מַלֵל יְיָ אֱלָהָנָא עִמָךְ וּנְקַבֵּל וְנַעְבֵּד:
@186 וּשְׁמִיעַ קֳדָם יְיָ יָת קָל פִּתְגָמֵיכוֹן בְּמַלָלוּתְכוֹן עִמִי וַאֲמַר יְיָ לִי שְׁמִיעַ קֳדָמַי יָת קָל פִּתְגָמֵי עַמָא הָדֵין דִי מַלִילוּ עִמָךְ אַתְקִינוּ כָּל דִי מַלִילוּ:
@187 לְוַי דִי יְהֵי לִבָּא הָדֵין לְהוֹן לְמִדְחַל קֳדָמַי וּלְמִטַר יָת כָּל פִּקוּדַי כָּל יוֹמַיָא בְּדִיל דִיֵיטַב לְהוֹן וְלִבְנֵיהוֹן לְעָלָם:
@188 אִזֵל אֱמַר לְהוֹן תּוּבוּ לְכוֹן לְמַשְׁכְּנֵיכוֹן:
@189 וְאַתְּ הָכָא קִים קֳדָמַי וֶאֱמַלֵל עִמָךְ יָת כָּלּ תַּפְקֶדְתָּא וּקְיָמַיָא וְדִינַיָא דִי תַלְפִנוּן וְיַעְבְּדוּן בְּאַרְעָא דִי אֲנָא יָהֵב לְהוֹן לְמֵירְתַהּ:
@190 וְתִטְרוּן לְמֶעְבַּד כְּמָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן לָא תִסְטוּן יַמִינָא וּשְׂמָאלָא:
@191 בְּכָל אָרְחָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן תְּהָכוּן בְּדִיל דְתֵיחוּן וְיֵיטַב לְכוֹן וְתוֹרְכוּן יוֹמִין בְּאַרְעָא דִי תֵירְתוּן:
@192 וְדָא תַפְקֶדְתָּא קְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהֲכוֹן לְאַלָפָא יָתְכוֹן לְמֶעְבַּד בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@193 בְּדִיל דְתִדְחַל קֳדָם יְיָ אֱלָהָךְ לְמִטַר יָת כָּל קְיָמוֹהִי וּפִקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ אַתְּ וּבְרָךְ וּבַר בְּרָךְ כָּל יוֹמֵי חַיָיךְ וּבְדִיל דְיוֹרְכוּן יוֹמָיךְ:
@194 וּתְקַבֵּל יִשְׂרָאֵל וְתִטַר לְמֶעְבַּד דִי יֵיטַב לָךְ וְדִי תִסְגוּן לַחֲדָא כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@195 שְׁמַע יִשְׂרָאֵל יְיָ אֱלָהָנָא יְיָ חָד:
@196 וְתִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ וּבְכָל נִכְסָךְ:
@197 וִיהוֹן פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין עַל לִבָּךְ:
@198 וּתְתָנִנוּן לִבְנָיךְ וּתְמַלֵל בְּהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@199 וְתִקְטְרִנוּן לְאָת עַל יְדָךְ וִיהוֹן לִתְפִלִין בֵּין עֵינָיךְ:
@200 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@201 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לָךְ קִרְוִין רַבְרְבָן וְטָבָן דִי לָא בְנֵיתָא:
@202 וּבָתִּין מְלָן כָּל טוּב דִי לָא מְלֵיתָא וְגֻבִּין פְּסִילָן דִי לָא פְּסַלְתָּא כַּרְמִין וְזֵיתִין דִי לָא נְצֶבְתָּא וְתֵיכוּל וְתִשְׂבָּע:
@203 אִסְתַּמַר לָךְ דִילְמָא תִנְשֵׁי יָת (דַחַלְתָּא דַ) יְיָ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@204 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִּפְלָח וּבִשְׁמֵהּ תְּקַיַם:
@205 לָא תְהָכוּן בָּתַר טַעֲוַת עַמְמַיָא מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן:
@206 אֲרֵי אֵל קַנָא יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ דִילְמָא יִתְקֵף רָגְזָא דַיְיָ אֱלָהָךְ בָּךְ וִישֵׁצָךְ מֵעַל אַפֵּי אַרְעָא:
@207 לָא תְנַסוּן קֳדָם יְיָ אֱלָהֲכוֹן כְּמָא דִי נַסֵתוּן בְנִסֵיתָא:
@208 מִטַּר תִּטְרוּן יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן וּסְהֶדְוָתֵהּ וּקְיָמוֹהִי דִי פַקְדָךְ:
@209 וְתַעְבֵּד דְכָשַׁר וּדְתַקֵן קֳדָם יְיָ בְּדִיל דְיֵיטַב לָךְ וְתֵעוּל וְתֵירַת יָת אַרְעָא טַבְתָא דִי קַיִים יְיָ לַאֲבָהָתָךְ:
@210 לְמִתְּבַר יָת כָּל בַּעֲלֵי דְבָבָךְ מֵקָדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@211 אֲרֵי יִשְׁאֲלִנָךְ בְּרָךְ מְחָר לְמֵימָר מָא סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהָנָא יָתְכוֹן:
@212 וְתֵימַר לִבְרָךְ עַבְדִין הֲוֵינָא לְפַרְעֹה בְּמִצְרָיִם וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא:
@213 וִיהַב יְיָ אָתִין וּמוֹפְתִין רַבְרְבִין וּבִישִׁין בְּמִצְרַיִם בְּפַרְעֹה וּבְכָל אֱנַשׁ בֵּיתֵהּ לְעֵינָנָא:
@214 וְיָתָנָא אַפֵּק מִתַּמָן בְּדִיל לְאַעֲלָא יָתָנָא לְמִתַּן לָנָא יָת אַרְעָא דִי קַיִים לַאֲבָהָתָנָא:
@215 וּפַּקְדָנָא יְיָ לְמֶעְבַּד יָת כָּל קְיָמַיָא הָאִלֵין לְמִדְחַל יָת יְיָ אֱלָהָנָא לְטַב לָנָא כָּל יוֹמַיָא לְקַיָמוּתָנָא כְּיוֹמָא הָדֵין:
@216 וְזָכוּתָא תְּהֵא לָנָא אֲרֵי נִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא קֳדָם יְיָ אֱלָהָנָא כְּמָא דִי פַקְדָנָא:
@217 אֲרֵי יְעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ וִיתָרֵךְ עַמְמִין סַגִיאִין מִן קֳדָמָךְ חִתָּאֵי וְגִרְגָשָׁאֵי וֶאֱמֹרָאֵי וּכְנַעֲנָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי שִׁבְעָא עַמְמִין סַגִיאִין וְתַקִיפִין מִנָךְ:
@218 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וְתִמְחִנוּן גַמָרָא תְגַמַר יָתְהוֹן לָא תִגְזַר לְהוֹן קְיָם וְלָא תְרַחַם עֲלֵיהוֹן:
@219 וְלָא תִתְחַתַּן בְּהוֹן בְּרַתָּךְ לָא תִתֵּן לִבְרֵהּ וּבְרַתֵּהּ לָא תִסַב לִבְרָךְ:
@220 אֲרֵי יַטְעֲיַן יָת בְּרָךְ מִבָּתַר פָּלְחָנִי וְיִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְיִתְקֵף רָגְזָא דַיְיָ בְּכוֹן וִישֵׁצָךְ בִּפְרִיעַ:
@221 אֲרֵי אִם כְּדֵין תַּעַבְּדוּן לְהוֹן אֱגוֹרֵיהוֹן תְּתָרְעוּן וְקָמָתְהוֹן תְּתַבְּרוּן וַאֲשֵׁרֵיהוֹן תְּקוֹצְצוּן וְצַלְמֵי טַּעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא:
@222 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ בָּךְ אִתִּרְעֵי יְיָ אֱלָהָךְ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכֹּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@223 לָא מִדְסַגִיאִין אַתּוּן מִכָּל עַמְמַיָא צָבֵי יְיָ בְּכוֹן וְאִתִּרְעֵי בְכוֹן אֲרֵי אַתּוּן זְעֵרִין מִכָּל עַמְמַיָא:
@224 אֲרֵי מִדְרַחַם יְיָ יָתְכוֹן וּמִדִנְטַר יָת קְיָמָא דִי קַיִים לַאֲבָהָתְכוֹן אַפֵּיק יְיָ יָתְכוֹן בִּידָא תַקִיפָא וּפָרְקָךְ מִבֵּית עַבְדוּתָא מִידָא דְפַרְעֹה מַלְכָּא דְמִצְרָיִם:
@225 וְתִדַע אֲרֵי יְיָ אֱלָהָךְ הוּא אֱלֹהִים אֱלָהָא מְהֵימְנָא נָטֵר קְיָמָא וְחִסְדָא לְרַחֲמוֹהִי וּלְנָטְרֵי פִקוֹדוֹהִי לְאַלְפֵי דָרִין:
@226 וּמְשַׁלֵם לְסָנְאוֹהִי טָבָן דִי אִנוּן עָבְדִין קֳדָמוֹהִי בְּחַיֵיהוֹן לְאוֹבָדֵיהוֹן לָא מְאַחַר עֹבַד טָב לְסָנְאוֹהִי טַבְוָן דִי אִנוּן עָבְדִין קָדָמוֹהִי בְּחַיֵיהוֹן מְשַׁלֵם לְהוֹן:
@227 וְתִטַר יָת תַּפְקֶדְתָּא וְיָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבָּדְהוֹן: פפפ:
@228 וִיהֵי חֳלַף דִי תְקַבְּלוּן יָת דִינַיָא הָאִלֵין וְתִטְרוּן וְתַעְבְּדוּן יָתְהוֹן וְיִטַר יְיָ אֱלָהָךְ לָךְ יָת קְיָמָא וְיָת חִסְדָא דִי קַיִים לַאֲבָהָתָךְ:
@229 וְיִרְחֲמִנָךְ וִיבָרֵכִנָךְ וְיַסְגִינָךְ וִיבָרֵךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַל אַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@230 בְּרִיךְ תְּהֵי מִכָּל עַמְמַיָא לָא יְהֵי בָךְ עֲקַר וְעַקְרָא וּבִבְעִירָךְ:
@231 וְיֶעְדֵי יְיָ מִנָךְ כָּל מַרְעִין וְכָל מַכְתְּשֵׁי מִצְרַיִם בִּישַׁיָא דִי יְדַעַתְּ לָא יְשַׁוִּנוּן בָּךְ וְיִתְּנִנוּן בְּכָל סָנְאָךְ:
@232 וּתְגַמַר יָת כָּל עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לָא תְחוּס עֵינָךְ עֲלֵיהוֹן וְלָא תִפְלַח יָת טַּעֲוָתְהוֹן אֲרֵי לְתַקְלָא הוּא לָךְ:
@233 דִילְמָא תֵימַר בְּלִבָּךְ סַגִיאִין עַמְמַיָא הָאִלֵין מִנִי אֶכְדֵין אִכּוּל לְתָרָכוּתְהוֹן:
@234 לָא תִדְחַל מִנְהוֹן מִדְכַּר תִּדְכַּר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְפַרְעֹה וּלְכָל מִצְרָיִם:
@235 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ וְאָתַיָא וּמוֹפְתַיָא וִידָא תַקֶפְתָּא וּדְרָעָא מְרָמְמָא דִי אַפְּקָךְ יְיָ אֱלָהָךְ כֵּן יַעְבֵּד יְיָ אֱלָהָךְ לְכָל עַמְמַיָא דִי אַתְּ דָחֵל מִקֳדָמֵיהוֹן:
@236 וְאַף יָת עֲרָעִיתָא יְגָרֵי יְיָ אֱלָהָךְ בְּהוֹן עַד דְיֵבַדוּן דְאִשְׁתָּאָרוּ וּדְאִטַמָרוּ מֵקֳדָמָךְ:
@237 לָא תִתְּבַר מִקֳדָמֵיהוֹן אֲרֵי יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ אֱלָהָא רַבָּא וּדְחִילָא:
@238 וִיתָרַךְ יְיָ אֱלָהָךְ יָת עַמְמַיָא הָאִלֵין מִקֳדָמָךְ זְעֵר זְעֵר לָא תִכּוּל לְשֵׁצָי וּתְהוֹן בִּפְרִי עַ דִי לְמָא תִסְגֵּי עֲלָךְ חֵיוַת בָּרָא:
@239 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וִישַׁגֵשִׁנוּן שִׁגוּשׁ רַב עַד דְיִשְׁתֵּצוּן:
@240 וְיִמְסַר מַלְכֵיהוֹן בִּידָךְ וְתוֹבַד יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא לָא יִתְעַתַּד אֱנַשׁ קֳדָמָךְ עַד דִתְשֵׁיצֵי יָתְהוֹן:
@241 צַלְמֵי טַעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא לָא תַחְמֵד כַּסְפָּא וְדַהֲבָא דִי עֲלֵיהוֹן וְתִסַב לָךְ דִילְמָא תִּתָּקַל בֵּהּ אֲרֵי מְרָחָקָא דַיְיָ אֱלָהָךְ הוּא:
@242 וְלָא תָעֵל דִמְרָחָק לְבֵיתָךְ וּתְהֵי חֶרְמָא כְּוָתֵהּ שַׁקָצָא תְשַׁקְצִנֵהּ וְרַחָקָא תְּרַחֲקִנֵהּ אֲרֵי חֶרְמָה הוּא:
@243 כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין תִּטְרוּן לְמֶעְבָּד בְּדִיל דְתֵיחוּן וְתִסְגוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן:
@244 וְתִדְכַּר יָת כָּל אָרְחָא דִי דַבְּרָךְ יְיָ אֱלָהָךְ דְנַן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא בְּדִיל לְעַנָיוּתָךְ לְנַסָיוּתָךְ לְמִדַע יָת דִי בְלִבָּךְ הֲתִטַר פִּקוּדוֹהִי אִם לָא:
@245 וְעַנְיָךְ וְאַכְפָּנָךְ וְאוֹכָלָךְ יָת מַנָא דִי לָא יְדַעְתְּ וְלָא יָדְעוּן אֲבָהָתָיךְ בְּדִיל לְאוֹדָעוּתָךְ אֲרֵי לָא עַל לַחְמָא בִלְחוֹדוֹהִי מִתְקַיַם אֱנָשָׁא אֲרֵי עַל כָּל אַפָּקוּת מֵימְרָא דַיְיָ יִתְקַיַם אֱנָשָׁא:
@246 כְּסוּתָךְ לָא אִבְלִיאַת מִנָךְ וּמְסָנָךְ לָא יְחֵפוּ דְנַן אַרְבְּעִין שְׁנִין:
@247 וְתִדַע עִם לִבָּךְ אֲרֵי כְּמָא דִי מְאַלֵף גַבְרָא יָת בְּרֵהּ יְיָ אֱלָהָךְ מְאַלֵף לָךְ:
@248 וְתִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחַן דְתַקְנָן קֳדָמוֹהִי וּלְמִדְחַל יָתֵהּ:
@249 אֲרֵי יְיָ אֱלָהָךְ מַעֲלָךְ לְאַרְעָא טַבְתָא אַרְעָא נָגְדָא נַחֲלִין דְמַיִין מַבּוּעֵי עֵינַוָן וּתְהוֹמִין נָפְקִין בְּבִקְעָן וּבְטוּרִין:
@250 אַרְעָא חִטִּין וְסַעֲרִין וְגוּפְנִין וּתְאֵנִין וְרִמוֹנִין אַרְעָא דְזֵיתָהָא עָבְדִין מִשְׁחָא וְהִיא עָבְדָא דְבָשׁ:
@251 אַרְעָא דִי לָא בְעִצוּרִין (נ''א בְמִסְכֵּנוּ) תֵּיכוּל בַּהּ לַחֲמָא לָא תֶחְסַר כָּל מִדַעַם בַּהּ אַרְעָא דִי אַבְנָהָא פַרְזְלָא וּמִטוּרָהָא תִּפְסוּל נְחָשָׁא:
@252 וְתֵיכוּל וְתִשְׂבַּע וּתְבָרַךְ יָת יְיָ אֱלָהָךְ עַל אַרְעָא טַבְתָא דִיהַב לָךְ:
@253 אִסְתַּמַר לָךְ דִילְמָא תִתְנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ בְּדִיל דְלָא לְמִטַר פִּקּוֹדוֹהִי וְדִינוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@254 דִילְמָא תֵיכוּל וְתִשְׂבַּע וּבָתִּין שַׁפִּירִין תִּבְנֵי וְתֵיתֵב:
@255 וְתוֹרָךְ וְעָנָךְ יִסְגוּן וְכַסְפָּא וְדַהֲבָא יִסְגֵא לָךְ וְכֹל דִי לָךְ יִסְגֵא:
@256 וִירִים לִבָּךְ וְתִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@257 דְדַבְּרָךְ בְּמַדְבְּרָא רַבָּא וּדְחִילָא אֲתַר חֵיוָן קָלָן וְעַקְרַבִּין וּבֵית צַחֲוָנָא אֲתַר דִי לֵית מַיָא דְאַפֵּק לָךְ מַיָא מִטִּנָרָא תַּקִיפָא:
@258 דְאוֹכָלָךְ מַנָא בְּמַדְבְּרָא דִי לָא יָדְעוּן אֲבָהָתָךְ בְּדִיל לְעַנָיוּתָךְ וּבְדִיל לְנַסָיוּתָךְ לְאוֹטָבָא לָךְ בְּסוֹפָךְ:
@259 וְתֵימַר בְּלִבָּךְ חֵילִי וּתְקֵף יְדִי קְנוֹ לִי יָת נִכְסַיָא הָאִלֵין:
@260 וְתִדְכַּר יָת יְיָ אֱלָהָךְ אֲרֵי הוּא יָהֵב לָךְ עֵצָה לְמִקְנֵי נִכְסִין בְּדִיל לְקַיָמָא יָת קְיָמֵהּ דִי קַיִים לְאֲבָהָתָךְ כְּיוֹמָא הָדֵין:
@261 וִיהֵי אִם מִנְשָׁאָה תִנְשֵׁי יָת דַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְהַךְ בָּתַר טַעְוַת עַמְמַיָא וְתִפְלְחִנוּן וְתִסְגוּד לְהוֹן אַסְהֵדִית בְּכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן:
@262 כְּעַמְמַיָא דִי יְיָ מֹאבִיד מִקֳדָמֵיכוֹן כֵּן תֵּיבְדוּן חֳלַף דְלָא קַבֶּלְתּוּן בְּמֵימְרָא דַיְיָ אֱלָהֲכוֹן:
@263 שְׁמַע יִשְׂרָאֵל אַתְּ עָבֵר יוֹמָא דֵין יָת יַרְדְנָא לְמֵיעַל לְמֵירַת עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ קִרְוִין רַבְרְבָן וּכְרִיכָן עַד צֵית שְׁמַיָא:
@264 עַם רַב וְתַקִיף בְּנֵי גִבָּרַיָא דִי אַתְּ יְדַעַתְּ וְאַתְּ שְׁמַעְתְּ מָן יִכּוּל לְמֵיקַם קֳדָם בְּנֵי גִבָּרַיָא:
@265 וְתִדַע יוֹמָא דֵין אֲרֵי יְיָ אֱלָהָךְ הוּא דְעֲבַר קֳדָמָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא יְשֵׁצִנוּן וְהוּא יְתָרֵכִנוּן קֳדָ מָךְ וּתְתָרֵ כִנוּן וְתוֹבְדִנוּן בִּפְרִיעַ כְּמָא דִי מַלִיל יְיָ לָךְ:
@266 לָא תֵימַר בְּלִבָּךְ בִּדְיִתְּבַר יְיָ אֱלָהָךְ יָתְהוֹן מִקֳדָמָךְ לְמֵימַר בְּזָכוּתִי אַעֲלַנִי יְיָ לְמֵירַת יָת אַרְעָא הָדָא וּבְחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ מְתָרֶכְהוֹן מֵקֳדָמָךְ:
@267 לָא בְזָכוּתָךְ וּבְקַשִׁיטּוּת לִבָּךְ אַתְּ עָלֵל לְמֵירַת יָת אַרְעֲהוֹן אֲרֵי בְּחוֹבֵי עַמְמַיָא הָאִלֵין יְיָ אֱלָהָךְ מתָרֶכְהוֹן מִקָדָמָךְ וּבְדִיל לַאֲקָמָא יָת פִּתְגָמָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@268 וְתִדַע אֲרֵי לָא בְזָכוּתָךְ יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעָא טַבְתָא הָדָא לְמֵירְתַהּ אֲרֵי עַם קְשֵׁי קְדַל אַתְּ:
@269 הֱוֵי דְכִיר לָא תִנְשֵׁי יָת דִי אַרְגֶזְתָּא קֳדָם יְיָ אֱלָהָךְ בְּמַדְבְּרָא לְמִן יוֹמָא דִי נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ:
@270 וּבְחוֹרֵב אַרְגֶזְתּוּן קֳדָם יְיָ וַהֲוָה רְגַז מִן קֳדָם יְיָ בְּכוֹן לְשֵׁיצָאָה יַתְכוֹן:
@271 בְּמִסְקִי לְטוּרָא לְמִסַב לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא דִי גְזַר יְיָ עִמְכוֹן וִיתֵבִית בְּטוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחֲמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי:
@272 וִיהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא כְּתִיבִין בְּאֶצְבְּעָא דַיְיָ וַעֲלֵיהוֹן כְּכָל פִּתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא בְּיוֹמָא דִקְהָלָא:
@273 וַהֲוָה מִסוֹף אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן יְהַב יְיָ לִי יָת תְּרֵין לוּחֵי אַבְנַיָא לוּחֵי קְיָמָא:
@274 וַאֲמַר יְיָ לִי קוּם חוּת בִּפְרִיעַ מִכָּא אֲרֵי חַבִּיל עַמָךְ דִי אַפֶּקְתָּא מִמִצְרָיִם סָטוּ בִּפְרִיעַ מִן אָרְחָא דִי פַקֶדְתִּנוּן עֲבָדוּ לְהוֹן מַתְּכָא:
@275 וַאֲמַר יְיָ לִי לְמֵימָר גְלֵי קֳדָמַי יָת עַמָא הָדֵין וְהָא עַם קְשֵׁי קְדַל הוּא:
@276 אַנַח בָּעוּתָךְ מִקֳדָמַי וֶאֱשֵׁצִנוּן וְאֶמְחֵי יָת שִׁמְהוֹן מִתְּחוֹת שְׁמַיָא וְאֶעְבֵּד יָתָךְ לְעַם תַּקִיף וְסַגִי מִנְהוֹן:
@277 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְטּוּרָא בָּעֵר בְּאֶשָׁתָא וּתְרֵין לוּחֵי קְיָמָא עַל תַּרְתֵּין יְדָי:
@278 וַחֲזֵיתִי וְהָא חַבְתּוּן קֳדָם יְיָ אֱלָהֲכוֹן עֲבַדְתּוּן לְכוֹן עֵגֶל מַתְּכָא סְטֵיתוּן בִּפְרִיעַ מִן אָרְחָא דִי פַקִיד יְיָ יָתְכוֹן:
@279 וַאֲחָדִית בִּתְרֵין לוּחַיָא וּרְמִיתִנוּן מֵעַל תַּרְתֵּין יְדָי וּתְבַרְתִּנוּן לְעֵינֵיכוֹן:
@280 וְאִשְׁתַּטָחִית קֳדָם יְיָ כְּקַדְמֵיתָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן לַחְמָא לָא אֲכָלִית וּמַיָא לָא אִשְׁתֵּיתִי עַל כָּל חוֹבֵיכוֹן דִי חַבְתּוּן לְמֶעְבַּד דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹהִי:
@281 אֲרֵי דְחֵלִית מִקָדָם רָגְזָא וְחֵמְתָא דִי רְגַז יְיָ עֲלֵיכוֹן לְשֵׁצָאָה יָתְכוֹן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהִיא:
@282 וְעַל אַהֲרֹן הֲוָה רְגַז מִן קֳדָם יְיָ לַחֲדָא לְשֵׁצָיוּתֵהּ וְצַלֵיתִי אַף עַל אַהֲרֹן בְּעִדָנָא הַהִיא:
@283 וְיָת חוֹבָתְכוֹן דִי עֲבַדְתּוּן יָת עֶגְלָא נְסֵבִית וְאוֹקֵדִית יָתֵהּ בְּנוּרָא וְשָׁפִית יָתֵהּ בְּשׁוּפִינָא יָאוּת עַד דִי הֲוָה דַקִיק לְעַפְרָא וּרְמֵת יָת עַפְרֵהּ לְנַחֲלָא דְנָחֵת מִן טוּרָא:
@284 וּבִדְלֶקְתָּא וּבְנִסֵתָא וּבְקִבְרֵי דִמְשַׁאֲלֵי מַרְגְזִין הֲוֵיתוּן קֳדָם יְיָ:
@285 וְכַד שְׁלַח יְיָ יָתְכוֹן מֵרְקַם גֵיאָה לְמֵימַר סְקוֹ וְאַחֲסִינוּ יָת אַרְעָא דִי יְהָבִית לְכוֹן וְסָרֶבְתּוּן עַל גְזֵרַת מֵימְרָא דַיְיָ אֱלָהֲכוֹן וְלָא הֵימַנְתּוּן לֵהּ וְלָא קַבֶּלְתּוּן לְמֵימְרֵהּ:
@286 מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ מִיוֹמָא דִידָעִית יָתְכוֹן:
@287 וְאִשְׁתַּטָחִית קֳדָם יְיָ יָת אַרְבְּעִין יְמָמִין וְיָת אַרְבְּעִין לֵילָוָן דִי אִשְׁתַּטָחִית אֲרֵי אֲמַר יְיָ לְשֵׁצָאָה יָתְכוֹן:
@288 וְצַלֵיתִי קֳדָם יְיָ וַאֲמָרִית יְיָ אֱלֹהִים לָא תְחַבֵּל עַמָךְ וְאַחֲסַנְתָּךְ דִי פְרַקְתָּא בְּתָקְפָּךְ דִי אַפֶּקְתָּא מִמִצְרַיִם בִּידָא תַקִיפָא:
@289 אִדְכַר לְעַבְדָיךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לָא תִתְפְּנֵי לְקַשְׁיוּת עַמָא הָדֵין וּלְחוֹבֵיהוֹן וְלַחֲטָאֵיהוֹן:
@290 דִילְמָא יֵימְרוּן דָיְרֵי אַרְעָא דִי אַפֶּקְתָּנָא מִתַּמָן מִדְלֵית יוּכְלָא דַיְיָ לְאָעָלוּתְהוֹן לְאַרְעָא דִי מַלִיל לְהוֹן וּמִדְסָנֵי יָתְהוֹן אַפֵּקִנוּן לְקַטָלוּתְהוֹן בְּמַדְבְּרָא:
@291 וְאִנוּן עַמָךְ וְאַחֲסַנְתָּךְ דִי אַפֶּקְתָּא בְּחֵילָךְ רַבָּא וּבִדְרָעָךְ מְרָמְמָא:
@292 בְּעִדָנָא הַהִיא אֲמַר יְיָ לִי פְּסַל לָךְ תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וְסַק לָקֳדָמַי לְטּוּרָא וְתַעְבֵּד לָךְ אֲרוֹנָא דְאָעָא:
@293 וְאֶכְתּוֹב עַל לוּחַיָא יָת פִּתְגָמַיָא דִי הֲווֹ עַל לוּחַיָא קַדְמָאֵי דִי תְבַרְתָּא וּתְשַׁוִנוּן בַּאֲרוֹנָא:
@294 וַעֲבָדִית אֲרוֹנָא דְאָעֵי שִׁטִּין וּפְסָלִית תְּרֵין לוּחֵי אַבְנַיָא כְּקַדְמָאֵי וּסְלֵקִית לְטוּרָא וּתְרֵין לוּחַיָא בִּידִי:
@295 וּכְתַב עַל לוּחַיָא כִּכְתָבָא קַדְמָאָה יָת עַשְׂרָא פִתְגָמַיָא דִי מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשְׁתָא בְּיוֹמָא דִקְהָלָא וִיהָבִנוּן יְיָ לִי:
@296 וְאִתְפְּנֵיתִי וּנְחָתִית מִן טוּרָא וְשַׁוֵיתִי יָת לוּחַיָא בַּאֲרוֹנָא דִי עֲבָדִית וַהֲווֹ תַמָן כְּמָא דִי פַקְדַנִי יְיָ:
@297 וּבְנֵי יִשְׂרָאֵל נְטָלוּ מִבְּאֵרוֹת בְּנֵי יַעֲקָן לְמוֹסֵרָה תַּמָן מִית אַהֲרֹן וְאִתְקְבַר תַּמָן וְשַׁמֵשׁ אֶלְעָזָר בְּרֵהּ תְּחוֹתוֹהִי:
@298 מִתַּמָן נְטָּלוּ לְגֻדְגֹד וּמִן גֻדְגֹד לְיָטְבָת אַרְעָא נָגְדָא נַחֲלִין דְמַיִין:
@299 בְּעִדָנָא הַהִיא אַפְרֵשׁ יְיָ יָת שִׁבְטָּא דְלֵוִי לְמִטַל יָת אֲרוֹן קְיָמָא דַיְיָ לְמֵיקַם קֳדָם יְיָ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִשְׁמֵהּ עַד יוֹמָא הָדֵין:
@300 עַל כֵּן לָא הֲּוָה לְלֵוִי חֳלָק וְאַחֲסָנָא עִם אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל יְיָ אֱלָהָךְ לֵהּ:
@301 וַאֲנָא הֲוֵיתִי קָאֵם בְּטוּרָא כְּיוֹמִין קַדְמָאִין אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן וְקַבִּיל יְיָ צְלוֹתִי אַף בְּזִמְנָא הַהוּא לָא אָבֵי יְיָ לְחַבָּלוּתָךְ:
@302 וַאֲמַר יְיָ לִי קוּם זִיל לְמִטוּל קֳדָם עַמָא וְיֵעֲלוּן וְיֵרְתוּן יָת אַרְעָא דִי קַיֵמִית לַאֲבָהָתְהוֹן לְמִתַּן לְהוֹן:
@303 וּכְעַן יִשְׂרָאֵל מָה יְיָ אֱלָהָךְ תָּבַע מִנָךְ אֱלָהֵן לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ לִמְהַךְ בְּכָל אָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִרְחַם יָתֵהּ וּלְמִפְלַח קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@304 לְמִטַר יָת פִּקוֹדַיָא דַיְיָ וְיָת קְיָמוֹהִי דַאֲנָא מְפַקְדָךְ יוֹמָא דֵין לִדְיֵיטַב לָךְ:
@305 הָא דַיְיָ אֱלָהָךְ שְׁמַיָא וּשְׁמֵי שְׁמַיָא אַרְעָא וְכָל דִי בַהּ:
@306 לְחוֹד בַּאֲבָהָתָךְ צָבֵי יְיָ לְמִרְחַם יָתְהוֹן וְאִתִּרְעֵי בִּבְנֵיהוֹן בַּתְרֵיהוֹן בְּכוֹן מִכָּל עַמְמַיָא כְּיוֹמָא הָדֵין:
@307 וְתֶעְדוּן יָת טַפְשׁוּת לִבְּכוֹן וּקְדָלְכוֹן לָא תַקְשׁוּן עוֹד:
@308 אֲרֵי יְיָ אֱלָהֲכוֹן הוּא אֱלָהָא דַיָנִין וּמָרֵי מַלְכִין אֱלָהָא רַבָּא גִבָּרָא וּדְחִילָא דִי לֵית קֳדָמוֹהִי מִסַב אַפִּין וְאַף לָא לְקַבָּלָא שָׁחְדָא:
@309 עָבֵד דִין יִתַּם וְאַרְמְלָא וְרָחֵם גִיוֹרָא לְמִתַּן לֵהּ מְזוֹנָא וּכְסוּ:
@310 וְתִרְחֲמוּן יָת גִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@311 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִפְלָח וּלְדַחַלְתֵּהּ תִּקְרַב וּבִשְׁמֵהּ תְּקַיַם:
@312 הוּא תֻשְׁבַּחְתָּךְ וְהוּא אֱלָהָךְ דַעֲבַד עִמָךְ יָת רַבְרְבָתָא וְיָת חֲסִינָתָא הָאִלֵין דִי חֲזוֹ עֵינָיךְ:
@313 בְּשַׁבְעִין נַפְשָׁן נְחָתוּ אֲבָהָתָךְ לְמִצְרָיִם וּכְעַן שַׁוְיָךְ יְיָ אֱלָהָךְ כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי:
@314 וְתִרְחַם יָת יְיָ אֱלָהָךְ וְתִטַּר מַטְרַת מֵימְרֵהּ וּקְיָמוֹהִי וְדִינוֹהִי וּפִקוֹדוֹהִי כָּל יוֹמַיָא:
@315 וְתִדְעוּן יוֹמָא דֵין אֲרֵי לָא יָת בְּנֵיכוֹן דִי לָא יְדָעוּ וְדִי לָא חֲזוֹ יָת אֻלְפָנָא דַיְיָ אֱלָהֲכוֹן יָת רְבוּתֵהּ יָת יְדֵהּ תַּקִיפָא וּדְרָעֵהּ מְרָמְמָא:
@316 וְיָת אַתְוָתֵהּ וְיָת עוֹבָדוֹהִי דִי עֲבַד בְּגוֹ מִצְרָיִם לְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּלְכָל אַרְעֵהּ:
@317 וְדִי עֲבַד לְמַשִׁרְיַת מִצְרַיִם לְסוּסְוָתֵהּ וְלִרְתִיכוֹהִי דִי אַטִיף יָת מֵי יַמָא דְסוּף עַל אַפֵּיהוֹן בְּמִרְדָפְהוֹן בַּתְרֵיכוֹן וְאוֹבָדִנוּן יְיָ עַד יוֹמָא הָדֵין:
@318 וְדִי עֲבַד לְכוֹן בְּמַדְבְּרָא עַד מֵיתֵיכוֹן עַד אַתְרָא הָדֵין:
@319 וְדִי עֲבַד לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב בַּר רְאוּבֵן דִי פְתָחַת אַרְעָא יָת פּוּמַהּ וּבְלָעָתְנוּן וְיָת אֱנַשׁ בָּתֵּיהוֹן וְיָת מַשְׁכְּנֵיהוֹן וְיָת כָּל יְקוּמָא דִי עִמְהוֹן בְּגוֹ כָּל יִשְׂרָאֵל:
@320 אֲרֵי עֵינֵיכוֹן חֲזָאָן יָת כָּל עוֹבָדָא דַיְיָ רַבָּא דִי עֲבָד:
@321 וְתִטְרוּן יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין בְּדִיל דְתִתְקְפוּן וְתֵעֲלוּן וְתֵירְתוּן יָת אַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@322 וּבְדִיל דְתוֹרְכוּן יוֹמִין עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן וְלִבְנֵיהוֹן אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@323 אֲרֵי אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ לָא כְאַרְעָא דְמִצְרַיִם הִיא דִי נְפַקְתּוּן מִתַּמָן דִי תִזְרַע יָת זַרְעָךְ וּמַשְׁקַת לֵהּ בְּרַגְלָךְ כְּגִנְתָא יַרְקָא:
@324 וְאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ אֲרַע טוּרִין וּבִקְעָן לִּמְטַּר שְׁמַיָא תִּשְׁתֵּי מַיָא:
@325 אַרְעָא דַיְיָ אֱלָהָךְ תָּבַע יָתַהּ תְּדִירָא עֵינֵי דַיְיָ אֱלָהָךְ בַּהּ מֵרֵישָׁא דְשַׁתָּא וְעַד סוֹפָא דְשַׁתָּא:
@326 וִיהֵי אִם קַבָּלָא תְקַבְּלוּן לְפִקוּדַי דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן וּלְמִפְלַח קֳדָמוֹהִי בְּכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@327 וְאֶתֵּן מְטַר אַרְעֲכוֹן בְּעִדָנֵהּ בַּכִּיר וְלַקִישׁ וְתִכְנוֹשׁ עִבוּרָךְ וְחַמְרָךְ וּמִשְׁחָךְ:
@328 וְאֶתֵּן עִשְׂבָּא בְחַקְלָךְ לִבְעִירָךְ וְתֵיכוּל וְתִשְׂבָּע:
@329 אִסְתַּמָרוּ לְכוֹן דִילְמָא יִטְעוּן לִבְּכוֹן וְתִסְטוּן וְתִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְתִסְגְדוּן לְהוֹן:
@330 וְיִתְקוֹף רָגְזָא דַיְיָ בְּכוֹן וְיֵחוֹד יָת שְׁמַיָא וְלָא יְהֵי מִטְרָא וְאַרְעָא לָא תִתֵּן יָת עֲלַלְתַּהּ וְתֵיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא טַבְתָא דַיְיָ יָהֵב לְכוֹן:
@331 וּתְשַׁווּן יָת פִּתְגָמַי אִלֵין עַל לִבְּכוֹן וְעַל נַפְשְׁכוֹן וְתִקְטְרוּן יָתְהוֹן לְאָת עַל יֶדְכוֹן וִיהוֹן לִתְפִלִין בֵּין עֵינֵיכוֹן:
@332 וְתַלְפוּן יָתְהוֹן יָת בְּנֵיכוֹן לְמַלָלָא בְהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@333 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@334 בְּדִיל דְיִסְגוּן יוֹמֵיכוֹן וְיוֹמֵי בְנֵיכוֹן עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתְכוֹן לְמִתַּן לְהוֹן כְּיוֹמֵי שְׁמַיָא עַל אַרְעָא:
@335 אֲרֵי אִם מִטַר תִּטְרוּן יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקֵד יָתְכוֹן לְמֶעְבְּדַהּ לְמִרְחַם יָת יְיָ אֱלָהֲכוֹן לִמְהַךְ בְּכָל אָרְחָן דְתַקְנָן קֳדָמוֹהִי וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ:
@336 וִיתָרֵךְ יְיָ יָת כָּל עַמְמַיָא הָאִלֵין מִקֳדָמֵיכוֹן וְתֵירְתוּן עַמְמִין רַבְרְבִין וְתַקִיפִין מִנְכוֹן:
@337 כָּל אַתְרָא דִי תִדְרוֹךְ פַּרְסַת רַגְלְכוֹן בֵּהּ דִלְכוֹן יְהֵי מִן מַדְבְּרָא וְלִבְנָן מִן נַהֲרָא נְהַר פְּרָת וְעַד יַמָא מַעַרְבָא יְהֵי תְחוּמְכוֹן:
@338 לָא יִתְעַתַּד אֱנָשׁ קֳדָמֵיכוֹן דַחֲלָתְכוֹן וְאֵימָתְכוֹן יִתֵּן יְיָ אֱלָהֲכוֹן עַל אַפֵּי כָל אַרְעָא דִי תִדְרְכוּן בַּהּ כְּמָה דִי מַלִיל לְכוֹן: ססס:
@339 חֲזֵי דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין בִּרְכָן וּלְוָטִין:
@340 יָת בִּרְכָן דִי תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֳלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@341 וּלְוָטִין אִם לָא תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֱלָהֲכוֹן וְתִסְטוּן מִן אָרְחָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@342 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל תַּמָן לְמֵירְתַהּ וְתִתֵּן יָת מְבָרְכַיָא עַל טוּרָא דִגְרִזִין וְיָת מְלַטְטַיָא עַל טוּרָא דְעֵיבָל:
@343 הֲלָא אִנוּן בְּעִבְרָא דְיַרְדְנָא אֲחוֹרֵי אֹרַח מַעֲלָנֵי שִׁמְשָׁא בְּאַרְעָא כְּנַעְנָאָה דְיָתֵב בְּמֵישְׁרָא לָקֳבֵל גִלְגְלָא בִּסְטַר מֵישְׁרֵי מֹרֶה:
@344 אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְמֵעַל לְמֵירַת יָת אַרְעָא דַיְיָ אֱלָהֲכוֹן יָהֵב לְכוֹן וְתֵירְתוּן יָתַהּ וְתֵיתְבוּן בַּהּ:
@345 וְתִטְרוּן לְמֶעְבַּד יָת כָּל קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין:
@346 אִלֵין קְיָמַיָא וְדִינַיָא דִי תִטְרוּן לְמֶעְבַּד בְּאַרְעָא דִיהַב יְיָ אֱלָהָא דַאֲבְהָתָךְ לָךְ לְמֵירְתַהּ כָּל יוֹמַיָא דִי אַתּוּן קַיָמִין עַל אַרְעָא:
@347 אַבָּדָא תְאַבְּדוּן יָת כָּל אַתְרַיָא דִי פְלָחוּ תַמָן עַמְמַיָא דִי אַתּוּן יָרְתִין יָתְהוֹן יָת טַעֲוָתְהוֹן עַל טוּרַיָא רָמַיָא וְעַל רָמָתָא וּתְחוֹת כָּל אִילַן עַבּוֹף:
@348 וּתְתָרְעוּן יָת אֱגוֹרֵיהוֹן וּתְתַבְּרוּן יָת קָמָתְהוֹן וַאֲשֵׁרֵיהוֹן תּוֹקְדוּן בְּנוּרָא וְצַלְמֵי טַעֲוָתְהוֹן תְּקוֹצְצוּן וְתוֹבְדוּן יָת שִׁמְהוֹן מִן אַ:תרָא הַהוּא:
@349 לָא תַעְבְּדוּן כֵּן קֳדָם יְיָ אֱלָהָכוֹן:
@350 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן מִכָּל שִׁבְטֵּיכוֹן לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְבֵית שְׁכִנְתֵּהּ תִּתְבְּעוּן וְתֵיתוּן לְתַמָן:
@351 וְתַיְתוּן לְתַמָן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן וְיָת מַעְשְׂרָתֵיכוֹן וְיָת אַפְרָשׁוּת יֶדְכוֹן וְנִדְרֵיכוֹן וְנִדְבָתֵיכוֹן וּבְכוֹרֵי תוֹרְכוֹן וְעָנְכוֹן:
@352 וְתֵיכְלוּן תַּמָן קֳדָם יְיָ אֱלָהֲכוֹן וְתֶחֱדוּן בְכֹל אוֹשָׁטוּת יֶדְכוֹן אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן דִי בָרְכָךְ יְיָ אֱלָהָךְ:
@353 לָא תַעְבְּדוּן כְּכֹל דִי אֲנַחְנָא עָבְדִין הָכָא יוֹמָא דֵין גְבַר כָּל מָן דְכָשַׁר קֳדָמוֹהִי:
@354 אֲרֵי לָא אֲתֵיתוּן עַד כְּעָן לְבֵית נְיָחָא וּלְאַחֲסָנָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@355 וְתַעְבְּרוּן יָת יַרְדְנָא וְתֵיתְבוּן בְּאַרְעָא דַיְיָ אֱלָהֲכוֹן מַחְסֵן יָתְכוֹן וִינִיחַ לְכוֹן מִכָּל בַּעֲלֵי דְבָבֵיכוֹן מִסְחוֹר סְחוֹר וְתֵיתְבוּן לְרָחְצָן:
@356 וִיהֵי אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן בֵּהּ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְתַמָן תַּיְתוּן יָת כָּל דִי אֲנָא מְפַקֵד יָתְכוֹן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן מַעְשְׂרָתֵיכוֹן וְאַפְרָשׁוּת יֶדְכוֹן וְכֹל שְׁפַר נִדְרֵיכוֹן דִי תִדְרוּן קֳדָם יְיָ:
@357 וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהָתֵיכוֹן וְלֵוָאָה דִי בְקִרְוֵיכוֹן אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמְכוֹן:
@358 אִסְתַּמַר לָךְ דִילְמָא תַסֵק עֲלָוָתָךְ בְּכָל אַתְרָא דִי תֶחֱזֵי:
@359 אֶלָהֵן בְּאַתְרָא דִי יִתִּרְעֵי יְיָ בְּחַד מִן שִׁבְטָיךְ תַּמָן תַּסֵק עֲלָוָתָךְ וְתַמָן תַּעְבֵּד כֹּל דִי אֲנָא מְפַקְדָךְ:
@360 לְחוֹד בְּכָל רְעוּת נַפְשָׁךְ תִּכּוֹס וְתֵיכוּל בִּשְׂרָא כְּבִרְכְּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ בְּכָל קִרְוָיךְ מְסָאָבָא וְדַכְיָא יֵכְלֻנֵהּ כִּבְשַׂר טַבְיָא וְאַיְלָא:
@361 לְחוֹד דְמָא לָא תֵיכְלוּן עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@362 לֵית לָךְ רְשׁוּ לְמֵיכַל בְּקִרְוָיךְ מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ וְכָל נִדְרָךְ דִי תִדַר וְנִדְבָתָיךְ וְאַפְרָשׁוּת יְדָךְ:
@363 אֱלָהֵן קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ בְּכָל אוֹשָׁטּוּת יְדָךְ:
@364 אִסְתַּמַר לָךְ דִילְמָא תִשְׁבּוֹק יָת לֵוָאֵי כָּל יוֹמָיךְ עַל אַרְעָךְ:
@365 אֲרֵי יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי מַלִיל לָךְ וְתֵימַר אֵיכוּל בִּשְׂרָא אֲרֵי תִתִּרְעֵי נַפְשָׁךְ לְמֵיכַל בִּשְׂרָא בְּכָל רְעוּת נַפְשָׁךְ תֵּיכוּל בִּשְׂרָא:
@366 אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן וְתִכּוֹס מִתּוֹרָךְ וּמֵעָנָךְ דִי יְהַב יְיָ לָךְ כְּמָא דִי פַּקֵדִתָּךְ וְתֵיכוּל בְּקִרְוָיךְ בְּכֹל רְעוּת נַפְשָׁךְ:
@367 בְּרַם כְּמָא דִי מִתְאֲכֵל בְּשַׂר טַבְיָא וְאַיְלָא כֵּן תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא יֵכְלִנֵהּ:
@368 לְחוֹד תְּקֵף בְּדִיל דְלָא לְמֵיכַל דְּמָא אֲרֵי דְמָא הוּא נַפְשָׁא וְלָא תֵיכוּל נַפְשָׁא עִם בִּשְׂרָא:
@369 לָא תֵּיכְלִנֵהּ עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@370 לָא תֵּיכְלִנֵהּ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ אֲרֵי תַעְבֵּד דְכָשָׁר קֳדָם יְיָ:
@371 לְחוֹד מַעְשַׂר קוּדְשָׁיךְ דִיהוֹן לָךְ וְנִדְרָךְ תִּטוֹל וְתֵיתֵי לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@372 וְתַעְבֵּד עֲלָוָתָךְ בִּשְׂרָא וּדְמָא עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וְדַם נִכְסַת קוּדְשָׁיךְ יִתָּשַׁד עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וּבִשְׂרָא תֵּיכוּל:
@373 טַר וּתְקַבֵּל יָת כָּל פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ עַד עֳלָם אֲרֵי תַעְבֵּד דְתָקֵן וּדְכָשַׁר קֳדָם יְיָ אֱלָהָךְ:
@374 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי אַתְּ עָלֵל לְתַמָן לְתָרָכָא יָתְהוֹן מִקֳדָמָךְ וְתֵירַת יָתְהוֹן וְתֵיתַב בְּאַרְעֲהוֹן:
@375 אִסְתַּמַר לָךְ דִילְמָא תִתָּקַל בַּתְרֵיהוֹן בָּתַר דְיִשְׁתֵּצוּן מִקֳדָמָךְ וְדִילְמָא תִתְבַּע לְטַעֲוָתְהוֹן לְמֵימַר אֶכְדֵין פָּלְחִין עַמְמַיָא הָאִלֵין יָת טַעֲוָתְהוֹן וְאֶעְבֵּד כֵּן אַף אֲנָא:
@376 לָא תַעְבֵּד כֵּן קֳדָם יְיָ אֱלָהָךְ אֲרֵי כָּל דִמְרָחָק קֳדָם יְיָ דִי סָנֵי עֲבָדוּ לְטַעֲוָתְהוֹן אֲרֵי אַף יָת בְּנֵיהוֹן וְיָת בְּנָתֵיהוֹן מוֹקְדִין בְּנוּרָא לְטַּעֲוָתְהוֹן:
@377 יָת כָּל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן יָתֵהּ תִּטְרוּן לְמֶעְבָּד לָא תוֹסְפוּן עֲלוֹהִי וְלָא תִמְנְעוּן מִנֵהּ:
@378 אֲרֵי יְקוּם בֵּינָךְ נְבִיָא אוֹ חָלֵם חֶלְמָא וְיִתֶּן לָךְ אָת אוֹ מוֹפְתָא:
@379 וְיֵיתֵי אָתָא וּמוֹפְתָא דִי מַלִיל עִמָךְ לְמֵימָר נְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתָּנוּן וְנִפְלְחִנוּן:
@380 לָא תְקַבֵּל לְפִתְגָמֵי נְבִיָא הַהוּא אוֹ לְחָלֵם חֶלְמָא הַהוּא אֲרֵי מְנַסֵי יְיָ אֱלָהֲכוֹן יָתְכוֹן לְמִדַע הַאִיתֵיכוֹן רָחֲמִין יָת יְיָ אֱלָהֲכוֹן בְכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@381 בָּתַר דַחַלְתָּא דַיְיָ אֱלָהֲכוֹן תְהָכוּן וְיָתֵהּ תִּדְחֲלוּן וְיָת פִּקוּדוֹהִי תִטְּרוּן וּלְמֵימְרֵהּ תְּקַבְּלוּן וְקָדָמוֹהִי תִפְלְחוּן וּבְדַחַלְתֵּהּ תִּתְקָרְבוּן:
@382 וּנְבִיָא הַהוּא אוֹ חָלֵם חֶלְמָא הַהוּא יִתְקְטֵּל אֲרֵי מַלִיל סַטְיָא עַל יְיָ אֱלָהֲכוֹן דִי אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם וּדְפָרְקָךְ מִבֵּית עַבְדוּתָא לְאַטְעֲיוּתָךְ מִן אָרְחָא דִי פַקְדָךְ יְיָ אֱלָהָךְ לִמְהַךְ בַּהּ וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@383 אֲרֵי יְמַלְכִנָךְ אֲחוּךְ בַּר אִמָךְ אוֹ בְרָךְ אוֹ בְרַתָּךְ אוֹ אִתַּת קְיָמָךְ אוֹ חַבְרָךְ דִי כְנַפְשָׁךְ בְּסִתְרָא לְמֵימַר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ:
@384 מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן דִקְרִיבִין לָךְ אוֹ דִרְחִיקִין מִנָךְ מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא:
@385 לָא תֵיבֵי לֵהּ וְלָא תְקַבֵּל מִנֵהּ וְלָא תְחוּס עֵינָךְ עֲלוֹהִי וְלָא תְרַחַם וְלָא תְכַסֵי עֲלוֹהִי:
@386 אֲרֵי מִקְטַל תִּקְטְּלִנֵהּ יְדָךְ תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְבַתְרֵיתָא:
@387 וְתִרְגְמִנֵהּ בְּאַבְנַיָא וִימוּת אֲרֵי בָעָא לְאַטְעֲיוּתָךְ מִדַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@388 וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@389 אֲרֵי תִשְׁמַע בְּחַד מִקִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמִתַּב תַּמָן לְמֵימָר:
@390 נְפָקוּ גֻבְרִין בְּנֵי רִשְׁעָא מִבֵּינָךְ וְאַטְעָיוּ יָת יָתְבֵי קַרְתְּהוֹן לְמֵימָר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@391 וְתִתְבַּע וְתִבְדוֹק וְתִשְׁאַל יָאוּת וְהָא קֻשְׁטָּא כֵּוַן פִּתְגָמָא אִתְעֲבִידָא תּוֹעֶבְתָּא הָדָא בֵּינָךְ:
@392 מִמְחָא תִמְחֵי יָת יָתְבֵי קַרְתָּא הַהִיא לְפִתְגַם דְחָרֶב גַמַר יָתַהּ וְיָת כָּל דִי בַהּ וְיָת בְּעִירַהּ לְפִתְגַם דְחָרֶב:
@393 וְיָת כָּל עֲדָאַהּ תִּכְנוֹשׁ לְגוֹ פְתָיַהּ וְתוֹקֵד בְּנוּרָא יָת קַרְתָּא וְיָת כָּל עֲדָאַהּ גְמִיר קֳדָם יְיָ אֱלָהָךְ וּתְהֵי תֵּל חָרִיב לְעָלָם לָא תִתְבְּנֵי עוֹד:
@394 וְלָא יִדְבַּק בִּידָךְ מִדַעַם מִן חֶרְמָא בְּדִיל דִיתוּב יְיָ מִתְּקוֹף רוּגְזֵהּ וִיהַב לָךְ רַחֲמִין וִירַחַם עֲלָךְ וְיַסְגִנָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ:
@395 אֲרֵי תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבַּד דְכָשָׁר קֳדָם יְיָ אֱלָהָךְ:
@396 בְּנִין אַתּוּן קֳדָם יְיָ אֱלָהֲכוֹן לָא תִתְחַמְמוּן וְלָא תְשַׁווּן מְרָט בֵּין עֵינֵיכוֹן עַל מִית:
@397 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ וּבָךְ אִתִּרְעֵי יְיָ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכָּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@398 לָא תֵיכוּל כָּל דִמְרָחָק:
@399 דֵין בְּעִירָא דְתֵיכְלוּן תּוֹרִין אִמְרִין דִרְחֵלִין וְגָדְיָן דְעִזִין:
@400 אַיָלָא וְטַבְיָא וְיַחְמוּרָא וְיַעְלָא וְרֵימָא וְתוֹרְבָּלָא וְדִיצָא:
@401 וְכָל בְּעִירָא דִסְדִיקָא פַרְסָתָא וּמַטִלְפָא טִלְפִין תַּרְתֵּין פַּרְסָתָא מַסְקָא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@402 בְּרַם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַרְסָתָא מַטִלְפֵי טִלְפַיָא יָת גַמְלָא וְיָת אַרְנְבָא וְיָת טַּפְזָא אֲרֵי מַסְקֵי פִּשְׁרָא אִנוּן וּפַרְסָתְהוֹן לָא סְדִיקָא מְסָאֲבִין אִנוּן לְכוֹן:
@403 וְיָת חֲזִירָא אֲרֵי מַסְדִיק פַּרְסָתָא הוּא וְלָא פָשַׁר מְסָאָב הוּא לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבֵלְתְּהוֹן לָא תִקְרְבוּן:
@404 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין תֵּיכְלוּן:
@405 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין לָא תֵיכְלוּן מְסָאָב הוּא לְכוֹן:
@406 כָּל צִפַּר דַכְיָא תֵּיכְלוּן:
@407 וְדֵין דִי לָא תֵיכְלוּן מִנְהוֹן נִשְׁרָא וְעָר וְעַזְיָא:
@408 וּבַת כַּנְפָא וְטָרָפִיתָא וְדַיְתָא לִזְנַהּ:
@409 וְיָת כָּל עֹרְבָא לִזְנֵהּ:
@410 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָּא וְנָצָא לִזְנוֹהִי:
@411 וְקַדְיָא וְקִפוֹפָא וּבַוְתָא:
@412 וְקָתָא וִירַקְרֵקָא וְשָׁלֵי נוּנָא:
@413 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַּלֵפָא:
@414 וְכֹל רִחֲשָׁא דְעוֹפָא מְסָאָב הוּא לְכוֹן לָא יִתְאָכְלוּן:
@415 כָּל עוֹפָא דְכֵי תֵּיכְלוּן:
@416 לָא תֵיכְלוּן כָּל נְבִילָא לְתוֹתָב עָרֵל דִי בְקִרְוָיךְ תִּתְּנִנַהּ וְיֵיכְלִנַהּ אוֹ תְזַבְּנִנַהּ לְבַר עַמְמִין אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ לָא תֵיכוּל בְּשַׂר בַּחֲלָב:
@417 עַשְׂרָא תְעַשַׂר יָת כָּל עֲלָלַת זַרְעָךְ דְיִפּוֹק חַקְלָא שַׁתָּא בְשַׁתָּא:
@418 וְתֵיכוּל קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ בְּדִיל דְתֵילַף לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ כָּל יוֹמַיָא:
@419 וַאֲרֵי יִסְגֵי מִנָךְ אָרְחָא אֲרֵי לָא תִכּוּל לְמִטְלֵהּ אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@420 וְתִתֵּן בְּכַסְפָּא וּתְצוּר כַּסְפָּא בִּידָךְ וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@421 וְתִתֵּן כַּסְפָּא בְּכֹל דִי יִתִּרְעֵי נַפְשָׁךְ בְּתוֹרֵי וּבְעָנָא וּבַחֲמַר חֲדַת וְעַתִּיק וּבְכֹל דִי תִשְׁאֲלִנָךְ נַפְשָׁךְ וְתֵיכוּל תַּמָן קֳדָם יְיָ אֱלָהָךְ וְתֶחֱדֵי אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@422 וְלֵוָאָה דִי בְקִרְוָיךְ לָא תִשְׁבְּקִנֵהּ אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ:
@423 מִסוֹף תְּלַת שְׁנִין תַּפֵק יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא הַהִיא וְתַצְנַע בְּקִרְוָיךְ:
@424 וְיֵיתֵי לֵוָאָה אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ וְיֵיכְלוּן וְיִשְׂבְּעוּן בְּדִיל דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדֵי יְדָךְ דִי תַעְבֵּד:
@425 מִסוֹף שְׁבַע שְׁנִין תַּעְבֵּד שְׁמִטְתָא:
@426 וְדֵין פִּתְגַם שְׁמִטְתָא דְתַשְׁמֵט כָּל גְבַר מַרֵי רְשׁוּ דִי יַרְשֵׁי בְּחַבְרֵהּ לָא יִתְבַּע מִן חַבְרֵהּ וּמִן אֲחוּהִי אֲרֵי קְרָא שְׁמִטְתָא קֳדָם יְיָ:
@427 מִן בַּר עַמְמִין תִּתְבַּע וְדִי יְהֵי לָךְ עִם אָחוּךְ תַּשְׁמֵט יְדָךְ:
@428 לְחוֹד אֲרֵי לָא יְהֵי בָךְ מִסְכֵּנָא אֲרֵי בָרָכָא יְבָרֵכִנָךְ יְיָ בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ:
@429 לְחוֹד אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@430 אֲרֵי יְיָ אֱלָהָךְ בָּרְכָךְ כְּמָא דִי מַלִיל לָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף וְתִשְׁלוֹט בְּעַמְמִין סַגִיאִין וּבָךְ לָא יִשְׁלְטוּן:
@431 אֲרֵי יְהֵי בָךְ מִסְכֵּנָא מֵחַד מֵאַחָיךְ בַּחֲדָא מִקִרְוָיךְ בְּאַרְעָךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תַתְקֵף יָת לִבָּךְ וְלָא תִקְפֹּץ יָת יְדָךְ מֵאֲחוּךְ מִסְכֵּנָא:
@432 אֶלָא מִפְתַּח תִּפְתַּח יָת יְדָךְ לֵהּ וְאוֹזָפָא תּוֹזְפִנֵהּ כְּמִסַת חֶסְרוֹנֵהּ דְיַחֲסִיר לֵהּ:
@433 אִסְתַּמַר לָךְ דִילְמָא יְהֵי פִתְגָם עִם לִבָּךְ בִּרְשַׁע לְמֵימַר קְרִיבָא שַׁתָּא שְׁבִיעֲתָא שַׁתָּא דִשְׁמִטְתָא וְתַבְאֵשׁ עֵינָךְ בְּאָחוּךְ מִסְכֵּנָא וְלָא תִתֵּן לֵהּ וְיִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@434 מִתַּן תִתֵּן לֵהּ וְלָא יַבְאֵשׁ לִבָּךְ בְּמִתְּנָךְ לֵהּ אֲרֵי בְּדִיל פִּתְגָמָא הָדֵין יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ:
@435 אֲרֵי לָא יִפְסוֹק מִסְכֵּנָא מִגוֹ אַרְעָא עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימַר מִפְתַּח תִּפְתַּח יָת יְדָךְ לַאֲחוּךְ לְעַנְיָךְ וּלְמִסְכֵּנָךְ בְּאַרְעָךְ:
@436 אֲרֵי יִזְדַבַּן לָךְ אֲחוּךְ בַּר יִשְׂרָאֵל אוֹ בַּת יִשְׂרָאֵל וְיִפְלְחִנָךְ שִׁית שְׁנִין וּבְשַׁתָּא שְׁבִיעֲתָא תִּפְטְרִנֵהּ בַּר חוֹרִין מֵעִמָךְ:
@437 וַאֲרֵי תִפְטְרִנֵה בַּר חוֹרִין מֵעִמָךְ לָא תִפְטְּרִנֵה רֵיקָן:
@438 אַפְרָשָׁא תַפְרֵשׁ לֵהּ מֵעָנָךְ וּמֵאִדְרָךְ וּמִמַעֲצַרְתָּךְ דִי בָרְכָךְ יְיָ אֱלָהָךְ תִּתֶּן לֵהּ:
@439 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ עַל כֵּן אֲנָא מְפַקְדָךְ יָת פִּתְגָמָא הָדֵין יוֹמָא דֵין:
@440 וִיהֵי אֲרֵי יֵימַר לָךְ לָא אֶפוֹק מֵעִמָךְ אֲרֵי רָחֲמָךְ וְיָת אֱנַשׁ בֵּיתָךְ אֲרֵי טַב לֵהּ עִמָךְ:
@441 וְתִסַב יָת מַרְצְעָא וְתִתֵּן בְּאֻדְנֵהּ וּבְדָשָׁא וִיהֵי לָךְ עִבֵד פָּלַח לְעָלָם וְאַף לְאַמְתָךְ תַּעְבֶּד כֵּן:
@442 לָא יִקְשֵׁי בְעֵינָךְ בְּמִפְטְרָךְ יָתֵהּ בַּר חוֹרִין מֵעִמָךְ אֲרֵי עַל חַד תְּרֵין כַּאֲגַר אֲגִירָא פָּלְחָךְ שִׁית שְׁנִין וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל דִי תַעְבֵּד:
@443 כָּל בּוּכְרָא דִי יִתְיְלִיד בְּתוֹרָךְ וּבְעָנָךְ דִכְרִין תַּקְדֵשׁ קָדָם יְיָ אֱלָהָךְ לָא תִפְלַח בְּבוּכְרָא דְתוֹרָךְ וְלָא תֵגוֹז בּוּכְרָא דְעָנָךְ:
@444 קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ שַׁתָּא בְשַׁתָּא בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@445 וַאֲרֵי יְהֵי בֵהּ מוּמָא חֲגִיר אוֹ עֲוִיר כֹּל מוּם בִּישׁ לָא תִכְּסִנֵהּ קֳדָם יְיָ אֱלָהָךְ:
@446 בְּקִרְוָיךְ תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא כִּבְסַר טַבְיָא וְאַיְלָא:
@447 לְחוֹד יָת דְמֵהּ לָא תֵיכוּל עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@448 טַר יָת יַרְחָא דַאֲבִיבָא וְתַעְבֵּד פִּסְחָא קֳדָם יְיָ אֱלָהָךְ אֲרֵי בְּיַרְחָא דַאֲבִיבָא אַפְּקָךְ יְיָ אֱלָהָךְ מִמִצְרַיִם וַעֲבַד לָךְ נִסִין בְּלֵילְיָא:
@449 וְתִכּוֹס פִּסְחָא קֳדָם יְיָ אֱלָהָךְ מִן בְּנֵי עָנָא וְנִכְסַת קוּדְשַׁיָא מִן תּוֹרֵי בְּאַתְרָא דִי יִתִּרְעֵי יְיָ לְאַשְׁרָאָה שְׁכִנְתֵּה תַּמָן:
@450 לָא תֵיכוּל עֲלוֹהִי חֲמִיעַ שִׁבְעָא יוֹמִין תֵּיכוּל עֲלוֹהִי פַטִיר לְחֵם עֹנִי אֲרֵי בִּבְהִילוּ נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם בְּדִיל דְתִדְכַּר יָת יוֹמָא מִפְּקָךְ מֵאַרְעָא דְמִצְרַיִם כָּל יוֹמֵי חַיָיךְ:
@451 וְלָא יִתְחֲזֵי לָךְ חֲמִר בְּכָל תְּחוּמָךְ שִׁבְעָא יוֹמִין וְלָא יְבִית מִן בִּסְרָא דִי תִכּוֹס בְּרַמְשָׁא בְּיוֹמָא קַדְמָאָה לְצַפְרָא:
@452 לֵית לָךְ רְשׁוּ לְמִכֹּס יָת פִּסְחָא בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@453 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן תִּכּוֹס יָת פִּסְחָא בְּרַמְשָׁא כְּמֵעַל שִׁמְשָׁא זְמַן מִפְקָךְ מִמִצְרָיִם:
@454 וּתְבַשֵׁל וְתֵיכוּל בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ וְתִתְפְּנֵי בְצַפְרָא וּתְהַךְ לְקִרְוָיךְ:
@455 שִׁתָּא יוֹמִין תֵּיכוּל פַּטִירָא וּבְיוֹמָא שְׁבִיעָאָה כְּנֵשׁ קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד עִבִידָא:
@456 שִׁבְעָא שָׁבוּעִין תִּמְנֵי לָךְ מִדְשַׁרְיוּת מַגְלָא בַּחֲצַד עוּמְרָא דַאֲרָמוּתָא תִּשְׁרֵי לְמִמְנֵּי שִׁבְעָא שָׁבוּעִין:
@457 וְתַעְבֵּד חַגָא דְשָׁבוּעַיָא קֳדָם יְיָ אֱלָהָךְ מִסַת נִדְבַת יְדָךְ דִי תִתֵּן כְּמָא דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@458 וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בֵינָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@459 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרָיִם וְתִטַר וְתַעְבֵּד יָת קְיָמַיָא הָאִלֵין:
@460 חַגָא דִמְטָלַיָא תַּעְבֵּד לָךְ שִׁבְעָא יוֹמִין בְּמִכְנְשָׁךְ מֵאִדְרָךְ וּמִמַעְצַרְתָּךְ:
@461 וְתֶחֱדֵי בְּחַגָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ:
@462 שִׁבְעָא יוֹמִין תֵּחוֹג קָדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עֲלַלְתָּךְ וּבְכָל עוֹבָדֵי יְדָיךְ וּתְהֵי בְּרַם חָדֵי:
@463 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזֵי כָל דְכוּרָךְ קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי בְּחַגָא דְפַטִירַיָא וּבְחַגָא דְשָׁבוּעַיָא וּבְחַגָא דִמְטָּלַיָא וְלָא יִתְחֲזֵי קֳדָם יְיָ רֵיקָנוּן:
@464 גְבַר כְּמַתְּנַת יְדֵהּ כְּבִרְכָּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ: ססס:
@465 דַיָנִין וּפֻרְעָנִין תְּמַנֵי לָךְ בְּכֹל קִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְשִׁבְטָיךְ וִידוּנוּן יָת עַמָא דִין דִקְשׁוֹט:
@466 לָא תַצְלֵי דִין לָא תִשְׁתְּמוֹדַע אַפִּין וְלָא תְקַבֵּל שֹׁחֲדָא אֲרֵי שֹׁחֲדָא מְעַוֵּר עֵינֵי חַכִּימִין וּמְקַלְקַל פִּתְגָמִין תְּרִיצִין:
@467 קֻשְׁטָא קֻשְׁטָא תְּהֵי רָדִיף בְּדִיל דְתֵיחֵי וְתֵירַת יָת אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@468 לָא תִצוֹב לָךְ אֲשֵׁרַת כָּל אִילָן בִּסְטַר מַדְבְּחָא דַיְיָ אֱלָהָךְ דִי תַעְבֶּד לָךְ:
@469 וְלָא תְקִים לָךְ קָמָא דִי סָנֵי יְיָ אֱלָהָךְ:
@470 לָא תִכּוֹס קֳדָם יְיָ אֱלָהָךְ תּוֹר וְאִמָר דִי יְהֵי בֵהּ מוּמָא כֹּל מִדַעַם בִּישׁ אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ הוּא:
@471 אֲרֵי יִשְׁתְּכַח בֵּינָךְ בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ גְבַר אוֹ אִתְּתָא דִי יַעְבֵּד יָת דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְמֶעְבַּר עַל קְיָמֵהּ:
@472 וַאֲזַל וּפְלַח לְטַעֲוַת עַמְמַיָא וּסְגִיד לְהוֹן וּלְשִׁמְשָׁא אוֹ לְסִיהֲרָא אוֹ לְכָל חֵילֵי שְׁמַיָא דִי לָא פַקֵדִית:
@473 וְיִתְחַוֵי לָךְ וְתִשְׁמַע וְתִתְבַּע יָאוּת וְהָא קֻשְׁטָא כֵּוַן פִּתְגָמָא אִתְעֲבִידַת תּוֹעֶבְתָּא הָדָא בְּיִשְׂרָאֵל:
@474 וְתַפֵּק יָת גַבְרָא הַהוּא אוֹ יָת אִתְּתָא הַהִיא דִי עֲבָדוּ יָת פִּתְגָמָא בִישָׁא הָדֵין לִתְרַע בֵּית דִינָךְ יָת גַבְרָא אוֹ יָת אִתְּתָא וְתִרְגְמִנוּן בְּאַבְנַיָא וִימוּתוּן:
@475 עַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקְטִל דְחַיַב קְטוֹל לָא יִתְקְטֵל עַל מֵימַר סָהִיד חָד:
@476 יְדָא דְסַהֲדַיָא תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְּבַתְרֵיתָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@477 אֲרֵי יִתְכַסֵי מִנָךְ פִּתְגָמָא לְדִינָא בֵּין דְמָא לִדְמָא בֵּין דִינָא לְדִינָא וּבֵין מַכְתַּשׁ סְגִירוּ לְמַכְתַּשׁ סְגִירוּ פִּתְגָמֵי פְלֻגְתָּא דִינָא בְּקִרְוָיךְ וּתְקוּם וְתִסַק לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@478 וְתֵיתֵי לְוָת כָּהֲנַיָא לֵוָאֵי וּלְוָת דַיָנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתִתְבַּע וִיחַוּוּן לָךְ יָת פִּתְגָמָא דְדִינָא:
@479 וְתַעְבֵּד עַל מֵימַר פִּתְגָמָא דִי יְחַוּוּן לָךְ מִן אַתְרָא הַהוּא דִי יִתִּרְעֵי יְיָ וְתִטַר לְמֶעְבַּד כְּכֹל דִי יַלְפֻנָךְ:
@480 עַל מֵימַר אוֹרַיְתָא דִי יַלְפֻנָךְ וְעַל דִינָא דִי יֵימְרוּן לָךְ תַּעְבֵּד לָא תִסְטֵּי מִן פִּתְגָמָא דִי יְחַוּוּן לָךְ יַמִינָא וּשְׂמָאלָא:
@481 וּגְבַר דִי יַעְבֵּד בִּרְשַׁע בְּדִיל דְלָא לְקַבָּלָא מִן כַּהֲנָא דְקָאֵם לְשַׁמָשָׁא תַמָן קֳדָם יְיָ אֱלָהָךְ אוֹ מִן דַיָנָא וְיִתְקְטֵל גַבְרָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@482 וְכָל עַמָא יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יַרְשִׁיעוּן עוֹד:
@483 אֲרֵי תֵעוֹל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וְתֵירְתַהּ וְתֵיתֵב בַּהּ וְתֵימַר אֱמַנִי עֲלַי מַלְכָּא כְּכָל עַמְמַיָא דִי בְסַחֲרָנָי:
@484 מַנָאָה תְמַנֵי עֲלָךְ מַלְכָּא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ מִגוֹ אַחָיךְ תְּמַנֵי עֲלָךְ מַלְכָּא לֵת לָךְ רְשׁוּ לְמַנָאָה עֲלָךְ גְבַר נוּכְרַי דִי לָא אֲחוּךְ הוּא:
@485 לְחוֹד לָא יַסְגֵי לֵהּ סוּסָוָן וְלָא יָתֵב יָת עַמָא לְמִצְרָיִם בְּדִיל לְאַסְגָּאָה לֵהּ סוּסָוָן וַיְיָ אֲמַר לְכוֹן לָא תוֹסְפוּן לְמִתוּב בְּאֹרַח הָדֵין עוֹד:
@486 וְלָא יַסְגֵי לֵהּ נְשִׁין וְלָא יִטְעֵי לִבֵּהּ וְכַסְפָּא וְדַהַבָא לָא יַסגֵי לֵהּ לַחֲדָא:
@487 וִיהֵי:כְמִתְּבֵהּ עַל כָּרְסָא מַלְכוּתֵהּ וְיִכְתּוֹב לֵהּ יָת פַּתְשֶׁגֶן אוֹרַיְתָא הָדָא עַל סִפְרָא מִן קֳדָם כָּהֲנַיָא לֵוָאֵי:
@488 וּתְהֵי עִמֵהּ וִיהֵי קָרֵי בֵהּ כָּל יוֹמֵי חַיוֹהִי בְּדִיל דְיֵלַף לְמִדְחַל קֳדָם יְיָ אֱלָהֵהּ לְמִטַּר יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא וְיָת קְיָמַיָא הָאִלֵין לְמֶעְבָּדְהוֹן:
@489 בְּדִיל דְלָא יְרִים לִבֵּהּ מֵאֲחוֹהִי וּבְדִיל דְלָא יִסְטֵּי מִן תַּפְקֶדְתָּא יַמִינָא וּשְׂמָאלָא בְּדִיל דְיוֹרֵךְ יוֹמִין עַל מַלְכוּתֵהּ הוּא וּבְנוֹהִי בְּגוֹ יִשְׂרָאֵל:
@490 לָא יְהֵי לְכָהֲנַיָא לֵוָאֵי כָּל שִׁבְטָא דְלֵוִי חֳלָק וְאַחֲסָנָא עִם יִשְׂרָאֵל קֻרְבָּנַיָא דַיְיָ וְאַחֲסַנְתֵּהּ יֵיכְלוּן:
@491 וְאַחֲסָנָא לָא יְהֵי לֵהּ בְּגוֹ אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל לֵהּ:
@492 וְדֵין יְהֵי דְחָזֵי לְכָהֲנַיָא מִן עַמָא מִן נָכְסֵי נִכְסָתָא אִם תּוֹר אִם אִמָר וְיִתֵּן לְכַהֲנָא דְרוֹעָא וְלוֹעָא וְקֻבְתָא:
@493 רֵישׁ עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וְרֵישׁ גִזָא דְעָנָךְ תַּפְרֵשׁ לֵהּ:
@494 אֲרֵי בֵהּ יִתִּרְעֵי יְיָ אֱלָהָךְ מִכָּל שִׁבְטָיךְ לְמֵקַם לְשַׁמָשָׁא בִשְׁמָא דַיְיָ הוּא וּבְנוֹהִי כָּל יוֹמַיָא:
@495 וַאֲרֵי יֵיתֵי לֵוָאָה מֵחֲדָא מִקִרְוָיךְ מִכָּל יִשְׂרָאֵל דִי הוּא דָר תַּמָן וְיֵיתֵי בְּכָל רְעוּת נַפְשֵׁהּ לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@496 וִישַׁמַשׁ בִּשְׁמָא דַיְיָ אֱלָהֵהּ כְּכָל אֲחוֹהִי לֵוָאֵי דִמְשַׁמְשִׁין תַּמָן (בִּצְלוֹ) קֳדָם יְיָ:
@497 חֳלָק כָּחֳלָק יֵיכְלוּן בַּר מִמַטַרְתָּא דְיֵיתֵי בְּשַׁבַּתָּא דְכֵן אַתְקִינוּ אֲבָהָתָא:
@498 אֲרֵי אַתְּ עָלֵל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תֵילַף לְמֶעְבַּד כְּתֹעֲבַת עַמְמַיָא הָאִנוּן:
@499 לָא יִשְׁתְּכַח בָּךְ מַעֲבַר בְּרֵהּ וּבְרַתֵּהּ בְּנוּרָא קָסֵם קֻסְמִין מְעָנֵן וּמְנַחֵשׁ וְחָרָשׁ:
@500 וְרָטִין רְטָן וְשָׁאֵל בִּדִין וּדְכוּרוּ וְתָבַע מִן מֵתַיָא:
@501 אֲרֵי מְרָחָק יְיָ כָּל דְיַעְבֵּד אִלֵין וּבְדִיל תּוֹעֲבָתָא הָאִלֵין יְיָ אֱלָהָךְ מְתָרַךְ יָתְהוֹן מִקֳדָמָךְ:
@502 שְׁלִים תְּהֵי בְּדַחַלְתָּא דַיְיָ אֱלָהָךְ:
@503 אֲרֵי עַמְמַיָא הָאִלֵין דִי אַתְּ יָרֵת יָתְהוֹן מִן מְעָנְנַיָא וּמִן קַסָמַיָא שָׁמְעִין וְאַתְּ לָא כֵן יְהַב לָךְ יְיָ אֱלָהָךְ:
@504 נְבִיָא מִבֵּינָךְ מֵאַחָיךְ כְּוָתִי יְקִים לָךְ יְיָ אֱלָהָךְ מִנֵהּ תְּקַבְּלוּן:
@505 כְּכֹל דִי שְׁאֶלְתָּא מִקֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב בְּיוֹמָא דִקְהָלָא לְמֵימָר לָא אוֹסֵף לְמִשְׁמָע יָת קָל מֵימְרָא דַיְיָ אֱלָהַי וְיָת אֶשָׁתָא רַבְּתָא הָדָא לָא אֶחֱזֵי עוֹד וְלָא אֵמוּת:
@506 וַאֲמַר יְיָ לִי אוֹטִיבוּ דִי מַלִילוּ:
@507 נְבִיָא אֲקִים לְהוֹן מִגוֹ אֲחֵיהוֹן כְּוָתָךְ וְאֶתֵּן פִּתְגָמֵי נְבוּאָתִי בְּפוּמֵהּ וִימַלֵל עִמְהוֹן יָת כָּל דִי אֲפַקְדִנֵהּ:
@508 וִיהֵי גַבְרָא דִי לָא יְקַבֵּל לְפִתְגָמַי דִי יְמַלֵל בִּשְׁמִי מֵימְרִי יִתְבַּע מִנֵהּ:
@509 בְּרַם נְבִיָא דִי יַרְשַׁע לְמַלָלָא פִתְגָמָא בִּשְׁמִי יָת דִי לָא פַקֵדִתֵּה לְמַלָלָא וְדִי יְמַלֵיל בְּשׁוּם טַעֲוַת עַמְמַיָא וְיִתְקְטֵל נְבִיָא הַהוּא:
@510 וַאֲרֵי תֵימַר בְּלִבָּךְ אֶכְדֵן נִדַע יָת פִּתְגָמָא דִי לָא מַלְלֵהּ יְיָ:
@511 דִי יְמַלֵל נְבִיָא בִּשְׁמָא דַיְיָ וְלָא יְהֵי פִתְגָמָא וְלָא יִתְקַיַם הוּא פִתְגָמָא דִי לָא מַלְלֵהּ יְיָ בִּרְשַׁע מַלְלֵהּ נְבִיָא לָא תִדְחַלּ מִנֵהּ:
@512 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעֲהוֹן וְתֵרְתִנוּן וְתֵיתֵב בְּקִרְוֵיהוֹן וּבְבָתֵּיהוֹן:
@513 תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@514 תְּתַקֵן לָךְ אָרְחָא וּתְתַלַת יָת תְּחוּם אַרְעָךְ דִי יַחְסְנִנָךְ יְיָ אֱלָהָךְ וִיהֵי לְמֵעִירוֹק תַּמָן כָּל קָטוֹלָא:
@515 וְדֵין פִּתְגַם קָטוֹלָא דְיֵעִרוֹק תַּמָן וְיִתְקַיַם דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵהּ וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקָמוֹהִי:
@516 וְדִי יֵעוֹל עִם חַבְרֵהּ בְּחֻרְשָׁא לְמִקַץ אָעִין וְתִתְמְרֵיג יְדֵהּ בְּפַרְזְלָא לְמִקַץ אָעָא וְיִשְׁתְּלֵף פַּרְזְלָא מִן אָעָא וְיַשְׁכַּח יָת חַבְרֵהּ וִימוּת הוּא יֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין וְיִתְקַיַם:
@517 דִילְמָא יִרְדוֹף גָאֵל דְמָא בָּתַר קָטוֹלָא אֲרֵי יֵחַם לִבֵּה וְיַדְבְּקִנֵהּ אֲרֵי תִסְגֵי אָרְחָא וְיִקְטְלִנֵהּ נְפַשׁ וְלֵהּ לֵית חוֹבַת דִין דִקְטוֹל אֲרֵי לָא סָנֵי הוּא לֵהּ מִתְּמַלֵי וּמִדְקָמוֹהִי:
@518 עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימָר תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ:
@519 וְאִם יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ וְיִתֶּן לָךְ יָת כָּל אַרְעָא דִי מַלִיל לְמִתַּן לַאֲבָהָתָךְ:
@520 אֲרֵי תִטַר יָת כָּל תַּפְקֶדְתָּא הָדָא לְמֶעְבְּדַהּ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ וְלִמְהַךְ בְּאָרְחָן דְתַקְנָן קֳדָמוֹהִי כָּל יוֹמַיָא וְתוֹסֵף לָךְ עוֹד תְּלַת קִרְוִין עַל תְּלַת אִלֵין:
@521 וְלָא יִשְׁתְּפֵךְ דָם זַכַּי בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וִיהֵי עֲלָךְ חוֹבַת דִין דִקְטוֹל:
@522 וַאֲרֵי יְהֵי גְבַר סָנֵי לְחַבְרֵהּ וְיִכְמַן לֵהּ וִיקוּם עֲלוֹהִי וְיִמְחִנֵהּ נְפָשׁ וִימוּת וְיֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין:
@523 וִישַׁלְחוּן סָבֵי קַרְתֵּהּ וְיִדְבְּרוּן יָתֵהּ מִתַּמָן וְיִתְּנוּן יָתֵהּ בְּיַד גָאֵל דְמָא וִימוּת:
@524 לָא תְחוּס עֵינָךְ עֲלוֹהִי וּתְפַלֵי אַשְׁדִי דָם זַכַּי מִיִשְׂרָאֵל וְיֵיטַב לָךְ:
@525 לָא תַשְׁנֵי תְּחוּמָא דְחַבְרָךְ דִי תְחִימוּ קַדְמָאֵי בְּאַחֲסַנְתָּךְ דִי תַחֲסֵן בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@526 לָא יְקוּם סָהִיד חַד בִּגְבַר לְכָל עַוָיָן וּלְכָל חוֹבִין בְּכָל חֵט דִי יֶחְטֵי עַל מֵימַר תְּרֵין סָהֲדִין אוֹ עַל מֵימַר תְּלָתָא סָהֲדִין יִתְקַיַם פִּתְגָמָא:
@527 אֲרֵי יְקוּם סָהִיד שְׁקַר בִּגְבָר לְאַסְהָדָא בֵהּ סַטְּיָא:
@528 וִיקוּמוּן תְרֵין גֻבְרִין דִי לְהוֹן דִינָא קֳדָם יְיָ קֳדָם כָּהֲנַיָא וְדַיָנַיָא דִי יְהוֹן בְּיוֹמַיָא הָאִנוּן:
@529 וְיִתְבְּעוּן דַיָנַיָא יָאוּת וְהָא סָהִיד שְׁקַר סָהֲדָא שִׁקְרָא אַסְהַד בַּאֲחוֹהִי:
@530 וְתַעְבְּדוּן לֵהּ כְּמָא דִי חַשִׁיב לְמֶעְבַּד לַאֲחוֹהִי וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@531 וּדְיִשְׁתַּאֲרוּן יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד עוֹד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@532 וְלָא תְחוּס עֵינָךְ נַפְשָׁא חֳלַף נַפְשָׁא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא יְדָא חֳלַף יְדָא רַגְלָא חֳלַף רַגְלָא:
@533 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְתֶחֱזֵי סוּסָוָן וּרְתִכִּין עַם סַגִי מִנָךְ לָא תִדְחַל מִנְהוֹן אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ בְּסַעְדָךְ דְאַסְקָךְ מֵאַרְעָא דְמִצְרָיִם:
@534 וִיהֵי כְּמִקְרָבְכוֹן לַאֲגָחָא קְרָבָא וְיִתְקְרִיב כַּהֲנָא וִימַלֵל עִם עַמָא:
@535 וְיֵימַר לְהוֹן שְׁמַע יִשְׂרָאֵל אַתּוּן קְרִיבִין יוֹמָא דֵין לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן לָא יְזוּעַ לִבְּכוֹן לָא תִדְחֲלוּן וְלָא תִתְבַּהֲתוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן:
@536 אֲרֵי יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן לַאֲגָחָא לְכוֹן קְרָב עִם בַּעֲלֵי דְבָבֵיכוֹן לְמִפְרַק יָתְכוֹן:
@537 וִימַלְלוּן סָרְכַיָא קֳדָם עַמָא לְמֵימָר מָן גַבְרָא דִי בְנָא בֵיתָא חַדְתָּא וְלָא חָנְכֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יַחְנְכִנֵהּ:
@538 וּמָן גַבְרָא דִי נְצִיב כַּרְמָא וְלָא אַחֲלֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יְחַלִנֵהּ:
@539 וּמָן גַבְרָא דִי אֵרַס אִתְּתָא וְלָא נָסְבַהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחֳרָן יִסְבִנַהּ:
@540 וְיוֹסְפוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וְיֵימְרוּן מָן גַבְרָא דְדָחֵל וּתְבִיר לִבָּא יְהַךְ וִיתוּב לְבֵיתֵהּ וְלָא יִתְּבַר יָת לִבָּא דַאַחוֹהִי כְּלִבֵּהּ:
@541 וִיהֵי כַּד יְשֵׁצוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וִימַנוּן רַבָּנֵי חֵילָא בְּרֵישׁ עַמָא:
@542 אֲרֵי תִקְרַב לְקַרְתָּא לַאֲגָחָא (קְרָבָא) עֲלַהּ וְתִקְרֵי לַהּ מִלִין דִשְׁלָם:
@543 וִיהֵי אִם שְׁלַם תַּעֲנִנָךְ וְתִפְתַּח לָךְ וִיהֵי כָּל עַמָא דְיִשְׁתְּכַח בַּהּ יְהוֹן לָךְ מַסְקֵי מִסִין וְיִפְלְחֻנָךְ:
@544 וְאִם לָא תַשְׁלֵם עִמָךְ וְתַעְבֵּד עִמָךְ קְרָב וּתְצוּר עֲלַהּ:
@545 וְיִמְסְרִנַהּ יְיָ אֱלָהָךְ בִּידָךְ וְתִמְחֵי יָת כָּל דְכוּרַהּ לְפִתְגַם דְחָרֶב:
@546 לְחוֹד נְשַׁיָא וְטַפְלָא וּבְעִירָא וְכֹל דִי יְהֵי בְקַרְתָּא כָּל עֲדָאַהּ תֵּבוֹז לָךְ וְתֵיכוּל יָת עֲדָאָה דְסַנְאָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@547 כֵּן תַּעְבֵד לְכָל קִרְוַיָא דִי רְחִיקִין מִנָךְ לַחֲדָא דִי לָא מִקִרְוֵי עַמְמַיָא הָאִלֵין אִנוּן:
@548 לְחוֹד מִקִרְוֵי עַמְמַיָא הָאִלֵין דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לָא תְקַיַם כָּל נִשְׁמָתָא:
@549 אֲרֵי גַמָרָא תְגַמְרִנוּן חִתָּאֵי וֶאֱמֹרָאֵי כְּנַעֲנָאֵי וּפְרִזָאֵי חִוָאֵי וִיבוּסָאֵי כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@550 בְּדִיל דִי לָא יַלְפוּן יָתְכוֹן לְמֶעְבַּד כְּכָל תּוֹעֲבָתְהוֹן דִי עֲבָדוּ לְטַעֲוָתְהוֹן וּתְחוֹבוּן קֳדָם יְיָ אֱלָהֲכוֹן:
@551 אֲרֵי תְצוּר לְקַרְתָּא יוֹמִין סַגִיאִין לַאֲגָחָא עֲלַהּ לְמִכְבְּשַׁהּ לָא תְחַבֵּל יָת אִילָנַהּ לַאֲרָמָא עֲלוֹהִי פַּרְזְלָא אֲרֵי מִנֵה תֵּיכוּל וְיָתֵהּ לָא תְקוּץ אֲרֵי לָא כַאֲנָשָׁא אִילַן חַקְלָא לְמֵיעַל מְקָדָמָךְ בִּצְיָרָא:
@552 לְחוֹד אִילָן דְתִדַע אֲרֵי לָא אִילַן דְמַאֲכָל הוּא יָתֵהּ תְּחַבַּל וּתְקוּץ וְתִבְנֵי כַרְקוֹמִין עַל קַרְתָּא דִי הִיא עָבְדָא עִמָךְ קְרָבָא עַד דְתִכְבְּשַׁהּ:
@553 אֲרֵי יִשְׁתְּכַח קְטִּילָא בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ רָמֵי בְּחַקְלָא לָא אִתְיְדַע מַן קָטְּלֵהּ:
@554 וְיִפְּקוּן סָבָיךְ וְדַיָנָיךְ וְיִמְשְׁחוּן לְקִרְוַיָא דִי סַחֲרָנוּת קְטִילָא:
@555 וּתְהֵי קַרְתָּא דִקְרִיבָא לִקְטִילָא וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא עֶגְלַת תּוֹרֵי דִי לָא אִתְפְּלַח בַּהּ דִי לָא נְגִידַת בְּנוּר:
@556 וְיֶחֱתוּן סָבֵי קַרְתָּא הַהִיא יָת עֲגַלְתָּא לְנַחֲלָא בַיָר דִי לָא יִתְפְּלַח בֵּהּ וְלָא יִזְדְרַע וְיִנְקְפוּן תַּמָן יָת עֲגַלְתָּא בְּנַחֲלָא:
@557 וְיִתְקָרְבוּן כָּהֲנַיָא בְּנֵי לֵוִי אֲרֵי בְהוֹן יִתִּרְעֵי יְיָ אֱלָהָךְ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִּשְׁמָא דַיְיָ וְעַל מֵימְרֵהוֹן יְהֵי כָּל דִין וְכָל מַכְתַּשׁ סְגִירוּ:
@558 וְכֹל סָבֵי קַרְתָּא הַהִיא דִקְרִיבִין לִקְטִילָא יַסְחוּן יָת יְדֵיהוֹן עַל עֲגַלְתָּא דִנְקֶפְתָּא בְנַחֲלָא:
@559 וִיתִיבוּן וְיֵימְרוּן יְדָנָא לָא אַשְׁדוֹ יָת דְמָא הָדֵין וְעֵינָנָא לָא חֲזָאָה:
@560 כָּהֲנַיָא יֵימְרוּן כַּפַּר לְעַמָךְ יִשְׂרָאֵל דִי פְרַקְתָּא יְיָ וְלָא תִתֵּן חוֹבַת דַם זַכַּי בְּגוֹ עַמָךְ יִשְׂרָאֵל וְיִתְכַּפַּר לְהוֹן עַל דְמָא:
@561 וְאַתְּ תְּפַלֵי אַשְׁדִי דַם זַכַּי מִבֵּינָךְ אֲרֵי תַעְבֵּד דְכָשַׁר קֳדָם יְיָ: ססס:
@562 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִמְסְרִנוּן יְיָ אֱלָהָךְ בִּידָךְ וְתִשְׁבֵּי שִׁבְיְהוֹן:
@563 וְתֶחֱזֵי בְּשִׁבְיָה אִתְּתָא שַׁפִּירַת חֵזוּ וְתִתִּרְעֵי בַהּ וְתִסְבַהּ לָךְ לְאִנְתּוּ:
@564 וְתָעֵלִנַהּ לְגוֹ בֵיתָךְ וּתְגַלַח יָת רֵישַׁהּ וּתְרַבִּי יָת טוּפְרָנָהָא:
@565 וְתֶעְדֵי יָת כְּסוּת שִׁבְיַהּ מִנַהּ וְתֵיתַב בְּבֵיתָךְ וְתִבְכֵּי יָת אֲבוּהָא וְיָת אִמַהּ יְרַח יוֹמִין וּבָתַר כֵּן תֵּיעוּל לְוָתַהּ וְתִבְעֲלִנַהּ וּתְהֵי לָךְ לְאִנְתּוּ:
@566 וִיהֵי אִם לָא תִתִּרְעֵי בַהּ וְתִפְטְּרִנַהּ לְנַפְשַׁהּ וְזַבָּנָא לָא תְזַבְּנִנַהּ בְּכַסְפָּא לָא תִתָּגַר בַּהּ חֳלַף דִי עִינִיתַהּ:
@567 אֲרֵי תְהֶוְיָן לִגְבַר תַּרְתֵּין נְשִׁין חֲדָא רְחֶמְתָּא וַחֲדָא שְׂנִיאֲתָא וִילִידָן לֵהּ בְּנִין רְחֶמְתָּא וּשְׂנִיאֲתָא וִיהֵי בְּרָא בוּכְרָא לִשְׂנִיאֲתָא:
@568 וִיהֵי בְּיוֹמָא דְיַחְסֵן לִבְנוֹהִי יָת דִי יְהֵי לֵהּ לֵית לֵהּ רְשׁוּ לְבַכָּרָא יָת בַּר רְחֶמְתָּא עַל אַפֵּי בַר שְׂנִיאֲתָא בּוּכְרָא:
@569 אֲרֵי יָת בּוּכְרָא בַר שְׂנִיאֲתָא יַפְרַשׁ לְמִתַּן לֵהּ תַּרְתֵּין חָלָקִין בְּכֹל דִי יִשְׁתְּכַח לֵהּ אֲרֵי הוּא רֵישׁ תָּקְפֵּהּ לֵהּ חָזְיָא בְכֵרוּתָא:
@570 אֲרֵי יְהֵי לִגְבַר בַּר סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבַּל לְמֵימַר אֲבוּהִי וּלְמֵימַר אִמֵהּ וּמַלְפָן יָתֵהּ וְלָא יְקַבֵּל מִנְהוֹן:
@571 וְיֶחֱדוּן בֵּהּ אֲבוּהִי וְאִמֵּהּ וְיַפְּקוּן יָתֵהּ לָקֳדָם סָבֵי קַרְתֵּהּ וְלִתְרַע בֵּית דִין אַתְרֵהּ:
@572 וְיֵימְרוּן לְסָבֵי קַרְתֵּהּ בְּנָנָא דֵין סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבֵּל לְמֵימְרָנָא זָלֵל בְּסָר וְסָבֵי חֲמַר:
@573 וְיִרְגְמֻנֵהּ כָּל אֶנָשֵׁי קַרְתֵּהּ בְּאַבְנַיָא וִימוּת וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן:
@574 וַאֲרֵי יְהֵי בִגְבַר חוֹבַת דִין דִקְטוֹל וְיִתְקְטֵל וְתִצְלוֹב יָתֵהּ עַל צְלִיבָא:
@575 לָא תְבִית נְבִלְתֵּהּ עַל צְלִיבָא אֲרֵי מִקְבַּר תִּקְבְּרִנֵהּ בְּיוֹמָא הַהוּא אֲרֵי עַל דְחָב קֳדָם יְיָ אִצְטְלַב וְלָא תְסָאֵב יָת אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@576 לָא תֶחֱזֵי יָת תּוֹרָא דְאָחוּךְ אוֹ יַת אִמְרֵהּ דְטָעָן וְתִתְכְּבֵשׁ מִנְהוֹן אָתָבָא תָתֵבִנוּן לְאָחוּךְ:
@577 וְאִם לָא קָרֵב אֲחוּךְ לְוָתָךְ וְלָא יְדַעַתְּ לֵהּ וְתַכְנְשִׁנֵהּ לְגוֹ בֵיתָךְ וִיהֵי עִמָךְ עַד דְיִתְבַּע אֲחוּךְ יָתֵהּ וְתָתֵיבִנֵהּ לֵהּ:
@578 וְכֵן תַּעְבֵּד לַחֲמָרֵהּ וְכֵן תַּעְבֵּד לִכְסוּתֵהּ וְכֵן תַּעְבֵּד לְכָל אֲבֵדַת אֲחוּךְ דִי תֵיבַד מִנֵהּ וְתַשְׁכְּחִנַהּ לֵית לָךְ רְשׁוּ לְאִתְכַּסָאָה:
@579 לָא תֶחֱזֵי יָת חֲמָרָא דְאָחוּךְ אוֹ תוֹרֵהּ רָמָן בְּאָרְחָא וְתִתְכְּבֵשׁ מִנְהוֹן אֲקָמָא תְקִים עִמֵהּ:
@580 לָא יְהֵי תִקוּן זֵין דִגְבַר עַל אִתְּתָא וְלָא יְתַקֵן גְבַר בְּתִקוּנֵי אִתְּתָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ כָּל עָבֵד אִלֵין:
@581 אֲרֵי יְעָרַע קִנָא דְצִפְּרָא קֳדָמָךְ בְּאָרְחָא בְּכָל אִילָן אוֹ עַל אַרְעָא אֶפְרוֹחִין אוֹ בֵיעִין וְאִמָא רְבֵעָא עַל אֶפְרֹחִין אוֹ עַל בֵּיעִין לָא תִסַב אִמָא עַל בְּנַיָא:
@582 שַׁלָחָא תְשַׁלַח יָת אִמָא וְיָת בְּנַיָא תִּסַב לָךְ בְּדִיל דְיֵיטַב לָךְ וְתוֹרִיפךְ יוֹמִין:
@583 אֲרֵי תִבְנֵי בֵּיתָא חַדְתָּא וְתַעְבֵּד תְּיָקָא לְאִגְרָךְ וְלָא תְשַׁוִי חוֹבַת דִין דִקְטוֹל בְּבֵיתָךְ אֲרֵי יִפֵּל דְנָפֵל מִנֵהּ:
@584 לָא תִזְרַע כַּרְמָךְ עֵרוּבִין דִילְמָא תִסְתָּאַב דִמְעַת זַרְעָא דִי תִזְרַע וַעֲלָלַת כַּרְמָא:
@585 לָא תִרְדֵי בְתוֹרָא וּבַחֲמָרָא כַּחֲדָא:
@586 לָא תִלְבַּשּׁ שַׁעַטְנֵזָא עֲמַר וְכִתָּן מְחֻבַּר כַּחֲדָא:
@587 כְּרֻסְפְּדִין תַּעְבֶּד לָךְ עַל אַרְבַּע כַּנְפֵי כְסוּתָךְ דִי תְכַסֵי בַהּ:
@588 אֲרֵי יִסַב גְבַר אִתְּתָא וְיֵעוּל לְוָתַהּ וְיִסְנִנַהּ:
@589 וִישַׁוִי לַהּ תַּסְקוֹפֵי מִלִין וְיַפֵּק עֲלַהּ שׁוּם בִּישׁ וְיֵימַר יָת אִתְּתָא הָדָא נְסֵבִית וְעַלִית לְוָתַהּ וְלָא אַשְׁכָּחִית לַהּ בְּתוּלִין:
@590 וְיִסַב אֲבוּהָא (נ''א אֲבוּהִי) דְעוּלֶמְתָּא וְאִמַהּ וְיַפְּקוּן יָת בְּתוּלֵי עוּלֶמְתָּא לָקֳדָם סָבֵי קַרְתָּא לִתְרַע בֵּית דִין אַתְרָא:
@591 וְיֵימַר אֲבוּהָא דְעוּלֶמְתָּא לְסָבַיָא יָת בְּרַתִּי יְהָבִית לְגַבְרָא הָדֵין לְאִנְתּוּ וּסְנִנַהּ:
@592 וְהָא הוּא שַׁוִי תַּסְקוֹפֵי מִלִין לְמֵימַר לָא אַשְׁכָּחִית לִבְרַתָּךְ בְּתוּלִין וְאִלֵין בְּתוּלֵי בְרַתִּי וְיִפְרְסוּן שׁוֹשִׁיפָא קֳדָם סָבֵי קַרְתָּא:
@593 וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא יָת גַבְרָא וְיַלְקוּן יָתֵהּ:
@594 וְיִגְבּוּן מִנֵהּ מְאָה סִלְעִין דִכְסָף וְיִתְּנוּן לַאֲבוּהָא דְעוּלֶמְתָּא אֲרֵי אַפֵּק שׁוּם בִּישׁ עַל בְּתוּלְתָּא דְיִשְׂרָאֵל וְלֵהּ תְּהֵי לְאִנְתּוּ לֵית לֵהּ רְשׁוּ לְמִפְטְּרַהּ כָּל יוֹמוֹהִי:
@595 וְאִם קֻשְׁטָא הֲוָה פִּתְגָמָא הָדֵין לָא אִשְׁתְּכָחוּ בְתוּלִין לְעוּלֶמְתָּא:
@596 וְיַפְּקוּן יָת עוּלֶמְתָּא לִתְרַע בֵּית אָבוּהָא וְיִרְגְמֻנַהּ אֱנָשֵׁי קַרְתַּהּ בְּאַבְנַיָא וּתְמוּת אֲרֵי עָבְדַת קְלָנָא בְּיִשְׂרָאֵל לְזַנָאָה בֵּית אֲבוּהָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@597 אֲרֵי יִשְׁתְּכַח גְבַר דְשָׁכֵב עִם אִתְּתָא אִתַּת גְבַר וְיִתְקַטְלוּן אַף תַּרְוֵיהוֹן גַבְרָא דְשָׁכֵב עִם אִתְּתָא וְאִתְּתָא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@598 אֲרֵי תְהֵי עוּלֶמְתָּא בְתֻלְתָּא דִמְאָרְסָא לִגְבַר וְיַשְׁכְּחִנַהּ גְבַר בְּקַרְתָּא וְיִשְׁכּוּב עִמַהּ:
@599 וְתַפְּקוּן יָת תַּרְוֵיהוֹן לִתְרַע קַרְתָּא הַהִיא וְתִרְגְמוּן יָתְהוֹן בְּאַבְנַיָא וִימוּתוּן יָת עוּלֶמְתָּא עַל עֵסַק דִי לָא צְוָחַת בְּקַרְתָּא וְיָת גַבְרָא עַל עֵסַק דְעַנִי יָת אִתַּת חַבְרֵהּ וּתְפַלֵי עָבֵד דְבִּישׁ מִבֵּינָךְ:
@600 וְאִם בְּחַקְלָא יַשְׁכַּח גְבַר יָת עוּלֶמְתָּא דִמְאָרְסָא וְיִתְקֶף בַּהּ גַבְרָא וְיִשְׁכּוּב עִמַהּ וְיִתְקְטֵּל גַבְרָא דְשָׁכֵב עִמַהּ בִּלְחוֹדוֹהִי:
@601 וּלְעוּלֶמְתָּא לָא תַעְבֵּד מִדַעַם לֵית לְעוּלֶמְתָּא חוֹבַת דִין דִקְטוֹל אֲרֵי כְּמָא דִיקוּם גַבְרָא עַל חַבְרֵהּ וְיִקְטְּלִנֵהּ נְפַשׁ כֵּן פִּתְגָמָא הָדֵין:
@602 אֲרֵי בְחַקְלָא אַשְׁכְּחַהּ צְוָחַת עוּלֶמְתָּא דִמְאָרְסָא וְלֵית דְפָרִיק לַהּ:
@603 אֲרֵי יַשְׁכַּח גְבַר עוּלֶמְתָּא בְתֻלְתָּא דִי לָא מְאָרְסָא וְיֶחֱדִנַהּ וְיִשְׁכּוּב עִמַהּ וְיִשְׁתַּכְּחוּן:
@604 וְיִתֵּן גַבְרָא דְיִשְׁכֻּב עִמַהּ לַאֲבוּהָא דְעוּלֶמְתָּא חַמְשִׁין סִלְעִין דִכְסַף וְלֵהּ תְּהֵי לְאִנְתּוּ חֳלַף דִי עַנְיַהּ לֵית לֵהּ רְשׁוּ לְמִפְטְרַהּ כָּל יוֹמוֹהִי:
@605 לָא יִסַב גְבַר יָת אִתַּת אֲבוּהִי וְלָא יְגַלֵי כַּנְפָא דַאֲבוּהִי:
@606 לָא יִדְכֵּי דְפָסִיק וְדִמְחַבַּל לְמֵעַל בִּקְהָלָא דַיְיָ:
@607 לָא יִדְכֵּי מַמְזֵרָא לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לֵהּ לְמֵעַל בִּקְהָלָא דַיְיָ:
@608 לָא יִדְכּוּן עַמוֹנָאֵי וּמוֹאָבָאֵי לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָא דַיְיָ עַד עָלָם:
@609 עַל עֵסַק דִי לָא עֲרָעוּ יָתְכוֹן בְּלַחְמָא וּבְמַיָא בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם וְדִי אֲגַר עֲלָךְ יָת בִּלְעָם בַּר בְּעוֹר מִפְּתוֹר אֲרַם דִי עַל פְּרָת לְלַטָּיוּתָךְ:
@610 וְלָא אָבֵי יְיָ אֱלָהָךְ לְקַבָּלָא מִן בִּלְעָם וַהֲפַךְ יְיָ אֱלָהָךְ לָךְ יָת לְוָטִין לְבִרְכָן אֲרֵי רָחֲמָךְ יְיָ אֱלָהָךְ:
@611 לָא תִתְבַּע שְׁלָמְהוֹן וְטָבָתְהוֹן כָּל יוֹמָיךְ לְעָלָם:
@612 לָא תְרַחַק אֱדוֹמָאָה אֲרֵי אֲחוּךְ הוּא לָּא תְרַחַק מִצְרָאָה אֲרֵי דַיָר הֲוֵיתָא בְאַרְעֵהּ:
@613 בְּנִין דִי יִתְיְלִידוּ לְהוֹן דָרָא תְלִיתָאָה יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָה דַיְיָ:
@614 אֲרֵי תִפּוֹק מַשְׁרִיתָא עַל בַּעֲלֵי דְבָבָךְ וְתִסְתַּמַר מִכֹּל מִדַעַם בִּישׁ:
@615 אֲרֵי יְהֵי בָךְ גְבַר דִי לָא יְהֵּי דְכֵי מִקְרֵהּ לֵילְיָא וְיִפּוֹק לְמִבָּרָא לְמַשְׁרִיתָא לָא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@616 וִיהֵי לְמִפְנֵי רַמְשָׁא יַסְחֵי בְמַיָא וּכְמֵעַל שִׁמְשָׁא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@617 וַאֲתַר מְתַקֵן יְהֵי לָךְ מִבָּרָא לְמַשְׁרִיתָא וְתִפּוֹק תַּמָן לְבָרָא:
@618 וְסִכְּתָא תְּהֵי לָךְ עַל זֵינָךְ וִיהֵי בְּמִיתְבָךְ לְבָרָא וְתַחְפַּר בַּהּ וּתְתוּב וּתְכַסֵי יָת מִפְּקָתָךְ:
@619 אֲרֵי יְיָ אֱלָהָךְ שְׁכִינְתֵּהּ מְהַלְכָא בְּגוֹ מַשְׁרִיתָךְ לְשֵׁזָבוּתָךְ וּלְמִמְסַר בַּעֲלֵי דְבָבָךְ קֳדָמָךְ וּתְהֵי מַשְׁרִיתָךְ קַדִישָׁא וִלָא יִתְחֲזֵי בָךְ עֲבֵרַת פִּתְגָם וִיתוּב מֵימְרֵהּ מִלְאוֹטָבָא לָךְ:
@620 לָא תִמְסַר עֶבֶד עַמְמִין לְיַד רִבּוֹנֵהּ דְיִשְׁתֵּזֵב לְוָתָךְ מִלְוָת רִבּוֹנֵהּ:
@621 עִמָךְ יִתֵּב בֵּינָךְ בְּאַתְרָא דִי יִתִּרְעֵי בַּחֲדָא מִן קִרְוָיךְ בִּדְיֵיטַּב לֵהּ לָא תוֹנִנֵהּ:
@622 לָא תְהֵי אִתְּתָא מִבְּנַת יִשְׂרָאֵל לִגְבָר עָבֵד וְלָא יִסַב גַבְרָא מִבְּנֵי יִשְׂרָאֵל אִתְּתָא אָמָא:
@623 לָא תָעֵל אֲגַר זַנִיתָא וְחוּלְפַן כַּלְבָא לְבֵית מַקְדְשָׁא דַיְיָ אֱלָהָךְ לְכָל נִדְרָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ אַף תַּרְוֵיהוֹן:
@624 לָא תְרַבֵּי לַאֲחוּךְ רִבִּית כְּסַף רִבִּית עִבוּר רִבִּית כָּל מִדַעַם דְמִתְרַבֵּי:
@625 לְבַר עַמְמִין תְּרַבֵּי וְלַאֲחוּךְ לָא תְרַבֵּי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל אוֹשָׁטוּת יְדָךְ עַל אַרְעָא דִי אַתְּ עָלֵל:לתַמָן לְמֵירְתַהּ:
@626 אֲרֵי תִדַר נְדַר קֳדָם יְיָ אֱלָהָךְ לָא תְאַחַר לְשַׁלָמוּתֵהּ אֲרֵי מִתְבַּע יִתְבְּעִנֵהּ יְיָ אֱלָהָךְ מִנָךְ וִיהֵי בָךְ חוֹבָא:
@627 וַאֲרֵי תִתִּמְנַע לְמִנְדַר לָא יְהֵי בָךְ חוֹבָא:
@628 אַפָּקוּת סִפְוָתָךְ תִּטַר וְתַעְבֵּד כְּמָא דִי נְדַרְתָּא קֳדָם יְיָ אֱלָהָךְ נְדַבְתָּא דִי מַלֶלְתָּא בְּפוּמָךְ:
@629 אֲרֵי תִתָּגַר בְּכַרְמָא דְחַבְרָךְ וְתֵיכוּל עִנְבִין כְּנַפְשָׁךְ שִׂבְעָךְ וּלְמָאנָךְ לָא תִתֵּן:
@630 אֲרֵי תִתָּגַר בְּקַמְתָא דְחַבְרָךְ וְתִקְטוֹף מְלִילָן בִּידָךְ וּמַגְלָא לָא תְרִים עַל קַמְתָא דְחַבְרָךְ:
@631 אֲרֵי יִסַב גְבַר אִתְּתָא וְיִבְעֲלִנַהּ וִיהֵי אִם לָא תַשְׁכַּח רַחֲמִין בְּעֵינוֹהִי אֲרֵי אַשְׁכַּח בַּהּ עֲבֵרַת פִתְגָם וְיִכְתּוֹב לַהּ גֵט פִּטוּרִין וִיהַב בִּידַהּ וְיִפְטְּרִנַהּ מִבֵּיתֵהּ:
@632 וְתִפּוֹק מִבֵּיתֵהּ וּתְהַךְ וּתְהֵי לִגְבַר אָחֳרָן:
@633 וְיִסְנִנַהּ גַבְרָא בַתְרָאָה וְיִכְתּוֹב לַהּ גֵטּ פִטּוּרִין וְיִתֵּן בִּידַהּ וְיִפְטְרִנַהּ מִבֵּיתֵהּ אוֹ אֲרֵי יְמוּת גַבְרָא בַתְרָאָה דְנָסְבַהּ לֵה לְאִנְתּוּ:
@634 לֵית לֵהּ רְשׁוּ לְבַעֲלַהּ קַדְמָאָה דִי פָטְרַהּ לְמִתֻּב לְמִסְבַהּ לְמֶהֱוֵי לֵה לְאִנְתּוּ בָּתַר דִי אִסְתָּאָבַת אֲרֵי מְרָחָקָא הִיא קֳדָם יְיָ וְלָא תְחַיַב יָת אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@635 אֲרֵי יִסַב גְבַר אִתְּתָא חַדְתָּא לָא יִפּוֹק בְּחֵילָא וְלָא יֵעִבַר עֲלוֹהִי לְכָל מִדָעַם פָּנֵי יְהֵי לְבֵיתֵהּ שַׁתָּא חֲדָא וְיַחְדֵי יָת אִתְּתֵהּ דִי נְסַב:
@636 לָא יִסַב מַשְׁכּוֹנָא רֵחַיָא וְרִכְבָּא אֲרֵי בְהוֹן מִתְעֲבֵד מָזוֹן לְכָל נְפַשׁ:
@637 אֲרֵי יִשְׁתְּכַח גְבַר גָנֵב נַפְשָׁא מֵאֲחוֹהִי מִבְּנֵי יִשְׂרָאֵל וְיִתָּגַר בֵּהּ וִיזַבְּנִנֵהּ וְיִתְקְטֵל גַנָבָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@638 אִסְתַּמַר בְּמַכְתַּשׁ סְגִירוּ לְמִטַּר לַחֲדָא וּלְמֶעְבָּד כְּכֹל דִי יַלְפוּן יָתְכוֹן כָּהֲנַיָא לֵוָאֵי כְּמָא דִי פַקֶדְתִּנוּן תִּטְרוּן לְמֶעְבָּד:
@639 הֱוֵי דְכִיר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְמִרְיָם בְּאָרְחָא בְּמִפָקְכוֹן מִמִצְרָיִם:
@640 אֲרֵי תַרְשֵׁי בְחַבְרָךְ רְשׁוּ מִדָעַם לָא תֵעוּל לְבֵיתֵהּ לְמִסַב מַשְׁכּוֹנֵהּ:
@641 בְּבָרָא תְּקוּם וְגַבְרָא דִי אַתְּ רָשֵׁי בֵהּ יַפֵק לְוָתָךְ יָת מַשְׁכּוֹנָא לְבָרָא:
@642 וְאִם גְבַר מִסְכֵּן הוּא לָא תִשְׁכּוּב בְּמַשְׁכּוֹנֵהּ:
@643 אָתָבָא תָתֵב לֵהּ יָת מַשְׁכּוֹנָא כְּמֵעַל שִׁמְשָׁא וְיִשְׁכּוּב בִּכְסוּתֵהּ וִיבָרֵכִנָךְ וְלָךְ תְּהֵי זְכוּתָא קֳדָם יְיָ אֱלָהָךְ:
@644 לָא תַעֲשׁוֹק אֲגִירָא עַנְיָא וּמִסְכֵּנָא מֵאַחָיךְ אוֹ מִגִיוֹרָךְ דִי בְאַרְעָךְ בְּקִרְוָיךְ:
@645 בְּיוֹמֵהּ תִּתֵּן אַגְרֵהּ וְלָא תֵעוּל עֲלוֹהִי שִׁמְשָׁא אֲרֵי עַנְיָא הוּא וְלֵהּ הוּא מְסַר יָת נַפְשֵׁהּ וְלָא יִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@646 לָא יְמוּתוּן אֲבָהָן עַל פּוּם בְּנִין וּבְנִין לָא יְמוּתוּן עַל פּוּם אֲבָהָן אֱנַשׁ בְּחוֹבֵהּ יְמוּתוּן:
@647 לָא תַצְלֵי דִין גִיוֹרָא וְיִתַּמָא וְלָא תִסַב מַשְׁכּוֹנָא לְבוּשׁ אַרְמְלָא:
@648 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ מִתַּמָן עַל כֵּן אֲנָא מְפַקְדָךְ לְמֶעְבַּד יָת פִּתְגָמָא הָדֵין:
@649 אֲרֵי תַחְצוֹד חֲצָדָךְ בְּחַקְלָךְ וְתִנְשֵׁי עֻמְרָא בְחַקְלָא לָא תְתוּב לְמִסְבֵהּ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ:
@650 אֲרֵי תַחְבּוֹט זֵיתָךְ לָא תְפַלֵי בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@651 אֲרֵי תִקְטוֹף כַּרְמָךְ לָא תְעָלֵל בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@652 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרָיִם עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵעְבַּד יָת פִּתְגָמָא הָדֵין:
@653 אֲרֵי יְהֵי דִין בֵּין גֻבְרַיָא וְיִתְקָרְבוּן לְדִינָא וִידוּנֻנוּן וִיזַכּוּן יָת זַכָּאָה וִיחַיְבוּן יָת חַיָבָא:
@654 וִיהֵי אִם בַּר חַיָבָא לְאַלְקָאָה חַיָבָא וְיִרְמִנֵהּ דַיָנָא וְיַלְקִנֵהּ קֳדָמוֹהִי כְּמִסַת חוֹבְתֵהּ בְּמִנְיָן:
@655 אַרְבְּעִין יַלְקִנֵהּ לָא יוֹסֵף דִילְמָא יוֹסֵף לְאַלְקָיוּתֵהּ עַל אִלֵין מָחָא רַבָּא וְיֵקַל אֲחוּךְ לְעֵינָיךְ:
@656 לָא תֵחוֹד פּוּם תּוֹרָא בִּדְיָשֵׁהּ:
@657 אֲרֵי יֵתְבוּן אַחִין כַּחֲדָא וִימוּת חַד מִנְהוֹן וּבַר לֵית לֵהּ לָא תְהֵי אִתַּת מֵתָנָא לְבָרָא לִגְבַר אוֹחֲרָן יְבָמַהּ יֵעוּל עֲלַהּ וְיִסְבַהּ לֵהּ לְאִנְתּוּ וְיִבְּמַהּ:
@658 וִיהֵי בּוּכְרָא דִי תְלִיד יְקוּם עַל שְׁמָא דַאֲחוּהִי מֵתָנָא וְלָא יִתִּמְחֵי שְׁמֵהּ מִיִשְׂרָאֵל:
@659 וְאִם לָא יִצְבֵי גַבְרָא לְמִסַב יָת יְבִמְתֵּהּ וְתִסַק יְבִמְתֵהּ לִתְרַע בֵּית דִינָא לָקֳדָם סָבַיָא וְתֵימַר לָא צָבֵי יְבָמִי לַאֲקָמָא לַאֲחוּהִי שְׁמָא בְּיִשְׂרָאֵל לָא אָבֵי לְיַבָּמוּתִי:
@660 וִיקְרוּן לֵהּ סָבֵי קַרְתֵּהּ וִימַלְלוּן עִמֵהּ וִיקוּם וְיֵימַר לָא רְעֵנָא לְמִסְבַהּ:
@661 וְתִתְקְרַב יְבִמְתֵּהּ לְוָתֵה לָקֳדָם סָבַיָא וְתַשְׁרֵי סֵינֵהּ מֵעַל רַגְלֵהּ וְתֵרוֹק בְּאַנְפּוֹהִי וְתָתֵב וְתֵימַר כְּדֵין יִתְעֲבֵד לִגְבַר דִי לָא יִבְנֵי יָת בֵּיתָא דַאֲחוּהִי:
@662 וְיִתְקְרֵי שְׁמֵהּ בְּיִשְׂרָאֵל בֵּית שְׁרִי סֵינָא:
@663 אֲרֵי יִנְצוּן גֻבְרִין כַּחֲדָא גְבַר וַאֲחוּהִי וְתִתְקְרֵב אִתַּת חַד לְשֵׁזָבָא יָת בַּעֲלַהּ מִיַד מָחוּהִי וְתוֹשֵׁט יְדַהּ וְתִתְקֵף בְּבֵית בַּהֲתְּתֵהּ:
@664 וּתְקוּץ יָת יְדַהּ לָא תְחוּס עֵינָךְ:
@665 לָא יְהֵי לָךְ בְּכִיסָךְ מַתְקַל וּמַתְקָל רַבְּתָא וּזְעֶרְתָּא:
@666 לָא יְהֵי לָךְ בְּבֵיתָךְ מְכִילָא וּמְכִילָא רַבְּתָא וּזְעֶרְתָּא:
@667 מַתְקִלִין שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ מְכִילָן שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@668 אֲרֵי מְרָחָק קֳדָם יְיָ אֱלהָךְ כָּל עָבֵד אִלֵין כֹּל עָבֵד שְׁקַר:
@669 הֲוֵי דְכִיר יָת דִי עֲבַד לָךְ עֲמָלֵק בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם:
@670 דִי עָרְעָךְ בְּאָרְחָא וְקָטֵל בָּךְ כָּל דַהֲווֹ מִתְאַחֲרִין בַּתְרָךְ וְאַתְּ מְשַׁלְהֵי וְלָאֵי וְלָא דָחֵיל מִן קֳדָם יְיָ:
@671 וִיהֵי כַּד יְנִיחַ יְיָ אֱלָהָךְ לָךְ מִכָּל בַּעֲלֵי דְבָבָךְ מִסְחוֹר סְחוֹר בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ תִּמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא לָא תִּתִּנְשֵׁי: פפפ:
@672 וִיהֵי אֲרֵי תֵעוּל לְאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וְתֵירְתַהּ וְתֵיתֵב בַּהּ:
@673 וְתִסַב מֵרֵישׁ כָּל אִבָּא דְאַרְעָא דִי תָעֵל מֵאַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ וּתְשַׁוֵי בְסַלָא וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@674 וְתֵיתֵי לְוָת כַּהֲנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתֵימַר לֵהּ חַוֵיתִי יוֹמָא דֵין קֳדָם יְיָ אֱלָהָךְ אֲרֵי עַלִית לְאַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָנָא לְמִתַּן לָנָא:
@675 וְיִסַב כַּהֲנָא סַלָא מִידָךְ וְיַחְתִנֵהּ קֳדָם מַדְבְּחָא דַיְיָ אֱלָהָךְ:
@676 וְתָתֵיב וְתֵימַר קֳדָם יְיָ אֱלָהָךְ לָבָן אֲרָמָאָה בָּעָא לְאוֹבָדָא יָת אַבָּא וּנְחַת לְמִצְרַיִם וְדָר תַּמָן בְּעַם זְעֵר וַהֲוָה תַמָן לְעַם רַב תַּקִיף וְסַגִי:
@677 וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְעַנְיָנָא וִיהָבוּ עֲלָנָא פָּלְחָנָא קַשְׁיָא:
@678 וְצַלֵינָא קֳדָם יְיָ אֱלָהָא דַאֲבָהָתָנָא וְקַבִּיל יְיָ צְלוֹתָנָא וּגְלֵי קֳדָמוֹהִי עַמְלָנָא וְלֵאוּתָנָא וְדוּחֲקָנָא:
@679 וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא וּבִדְרָעָא מְרַמְמָא וּבְחֶזְוָנָא רַבָּא וּבְאָתִין וּבְמוֹפְתִין:
@680 וְאַיְתָנָא לְאַתְרָא הָדֵין וִיהַב לָנָא יָת אַרְעָא הָדָא אַרְעָא עָבְדָא חֲלַב וּדְבָש:
@681 וּכְעַן הָא אַיְתֵתִי יָת רֵישׁ אִבָּא דְאַרְעָא דִיהַבְתְּ לִי יְיָ וְתַחְתִנֵהּ קֳדָם יְיָ אֱלָהָךְ וְתִסְגוּד קֳדָם יְיָ אֱלָהָךְ:
@682 וְתֶחֱדֵי בְכָל טַבְתָא דִי יְהַב לָךְ יְיָ אֱלָהָךְ וְלֶאֱנַשׁ בֵּיתָךְ אַתְּ וְלֵוָאֵי וְגִיוֹרָא דִי בֵינָךְ:
@683 אֲרֵי תְשֵׁצֵי לְעַשָׂרָא יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא תְלִיתָאָה שְׁנַת מַעְשְׂרָא וְתִתֵּן לְלֵוָאֵי לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא וְיֵכְלוּן בְּקִרְוָיךְ וְיִשְׂבְּעוּן:
@684 וְתֵימַר קֳדָם יְיָ אֱלָהָךְ פַּלֵתִי קֹדֶשׁ מַעְשְׂרָא מִן בֵּיתָא וְאַף יְהָבִתֵּהּ לְלֵוָאֵי וּלְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא כְּכָל פִּקוּדָךְ דִי פַקִדְתַּנִי לָא עֲבָרִית מִפִּקוּדָיךְ וְלָא אִתִּנְשֵׁיתִי:
@685 לָא אֲכָלִית בְּאֶבְלִי מִנֵהּ וְלָא פַלֵתִי מִנֵהּ בִּמְסָאָב וְלָא יְהָבִית מִנֵהּ לְמִית קַבֵּלִית לְמֵימְרָא דַיְיָ אֱלָהָי עֲבָדִית כְּכֹלּ דִי פַקִדְתַּנִי:
@686 אִסְתְּכִי מִמְדוֹר קוּדְשָׁךְ מִן שְׁמַיָא וּבָרֵךְ יָת עַמָךְ יָת יִשְׂרָאֵל וְיָת אַרְעָא דִי יְהַבְתְּ לָנָא כְּמָא דִי קַיֶמְתָּא לַאֲבָהָתָנָא אֲרַע עָבְדָא חֲלַב וּדְבָשׁ:
@687 יוֹמָא הָדֵין יְיָ אֱלָהָךְ מְפַקְדָךְ לְמֶעְבַּד יָת קְיָמַיָא הָאִלֵין וְיָת דִינַיָא וְתִטַר וְתַעְבֵּד יָתְהוֹן בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@688 יָת יְיָ חֲטַּבְתָּ יוֹמָא דֵין לְמֶהֱוֵי לָךְ לֶאֱלָהּ וְלִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר קְיָמוֹהִי וּפִקוּדוֹהִי וְדִינוֹהִי וּלְקַבָּלָא לְמֵימְרֵהּ:
@689 וַיְיָ חָטְבָךְ יוֹמָא דֵין לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב כְּמָא דִי מַלִיל לָךְ וּלְמִטַר כָּל פִּקוּדוֹהִי:
@690 וּלְמִתְּנָךְ עִלָאָה עַל כָּל עַמְמַיָא דִי עֲבַד לְתֻשְׁבָּחָא וּלְשׁוּם וְלִרְבוּ וּלְמֶהֱוָךְ עַם קַדִישׁ קֳדָם יְיָ אֱלָהָךְ כְּמָא דִי מַלִיל:
@691 וּפַקִיד מֹשֶׁה וְסָבֵי יִשְׂרָאֵל יָת עַמָא לְמֵימָר טַר יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@692 וִיהֵי בְּיוֹמָא דִי תַעְבְּרוּן יָת יַרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וּתְקִים לָךְ אַבְנִין רַבְרְבִין וּתְסוּד יָתְהוֹן בְּסִידָא:
@693 וְתִכְתּוֹב עֲלֵיהוֹן יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא בְּמֶעְבְּרָךְ בְּדִיל דִי תֵעוּל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבַשׁ כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ:
@694 וִיהֵי בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא תְּקִימוּן יָת אַבְנַיָא הָאִלֵין דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין בְּטּוּרָא דְעֵיבָל וּתְסוּד יָתְהוֹן בְּסִידָא:
@695 וְתִבְנֵי תַמָן מַדְבְּחָא קֳדָם יְיָ אֱלָהָךְ מַדְבַּח אַבְנִין לָא תְרִים עֲלֵיהוֹן פַּרְזְלָא:
@696 אַבְנִין שָׁלְמִין תִּבְנֵי יָת מַדְבְּחָא דַיְיָ אֱלָהָךְ וְתַסֵק עֲלוֹהִי עֲלָוָן קֳדָם יְיָ אֱלָהָךְ:
@697 וְתִכּוֹס נִכְסַת קוּדְשִׁין וְתֵיכוּל תַּמָן וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ:
@698 וְתִכְתּוֹב עַל אַבְנַיָא יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא פָּרַשׁ יָאוּת:
@699 וּמַלִיל מֹשֶׁה וְכָהֲנַיָא לֵוָאֵי לְכָל יִשְׂרָאֵל לְמֵימָר אֲצֵית וּשְׁמַע יִשְׂרָאֵל יוֹמָא הָדֵין הֲוֵיתָא לְעַמָא קֳדָם יְיָ אֱלָהָךְ:
@700 וּתְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וְתַעְבֵּד יָת פִּקוּדוֹהִי וְיָת קְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@701 וּפַקִיד מֹשֶׁה יָת עַמָא בְּיוֹמָא הַהוּא לְמֵימָר:
@702 אִלֵין יְקוּמוּן לְבָרָכָא יָת עַמָא עַל טוּרָא דִגְרִזִים בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא שִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשכָר וְיוֹסֵף וּבִנְיָמִין:
@703 וְאִלֵין יְקוּמוּן עַל לְוָטַיָא בְּטוּרָא דְעֵיבָל רְאוּבֵן גָד וְאָשֵׁר וּזְבוּלֻן דָן וְנַפְתָּלִי:
@704 וִיתִיבוּן לֵוָאֵי וְיֵימְרוּן לְכָל אֱנַשׁ יִשְׂרָאֵל קָלָא רָמָא:
@705 לִיט גַבְרָא דִי יַעְבֵּד צֶלֶם וּמַתְּכָא מְרָחָקָא קֳדָם יְיָ עֹבַד יְדֵי אֳמָן וְשַׁוִי בְסִתְרָא וִיתִיבוּן כָּל עַמָא וְיֵימְרוּן אָמֵן:
@706 לִיטּ דְיִקְלֵי אֲבוּהִי וְאִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@707 לִיטּ דְיַשְׁנֵי תְּחוּמָא דְחַבְרֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@708 לִיט דְיַטְעֵי עַוִירָא בְּאָרְחָא וְיֵימַר כָּל עַמָא אָמֵן:
@709 לִיטּ דְיַצְלֵי דִין דַיַר יִתַּמָא וְאַרְמְלָא וְיֵימַר כָּל עַמָא אָמֵן:
@710 לִיט דְיִשְׁכּוּב עִם אִתַּת אֲבוּהִי אֲרֵי גַלִי כַּנְפָא דַאֲבוּהִי וְיֵימַר כָּל עַמָא אָמֵן:
@711 לִיט דְיִשְׁכּוּב עִם כָּל בְּעִירָא וְיֵימַר כָּל עַמָא אָמֵן:
@712 לִיט דְיִשְׁכּוּב עִם אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@713 לִיט דְיִשְׁכּוּב עִם חֲמוֹתֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@714 לִיט דְיִמְחֵי לְחַבְרֵהּ בְּסִתְרָא וְיֵימַר כָּל עַמָא אָמֵן:
@715 לִיטּ דִי מְקַבֵּל שׂחֲדָא לְמִקְטַל נְפַשׁ דַם זַכַּי וְיֵימַר כָּל עַמָא אָמֵן:
@716 לִיט דִי לָא יְקַיַם יָת פִּתְגָמֵי אוֹרַיְתָא הָדָא לְמֶעְבַּד יָתְהוֹן וְיֵימַר כָּל עַמָא אָמֵן:
@717 וִיהֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיִתְּנִנָךְ יְיָ אֱלָהָךְ עִלָאָה עַל כָּל עַמְמֵי אַרְעָא:
@718 וְיֵיתוּן עֲלָךְ כָּל בִּרְכְּתָא הָאִלֵין וְיִדְבְּקֻנָךְ אֲרֵי תְקַבַּל לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@719 בְּרִיךְ אַתְּ בְּקַרְתָּא וּבְרִיךְ אַתְּ בְּחַקְלָא:
@720 בְּרִיךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ וּוַלְדָא דִבְעִירָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@721 בְּרִיךְ סַלָךְ וְאַצְוָתָךְ:
@722 בְּרִיךְ אַתְּ בְּמֵעֲלָךְ וּבְרִיךְ אַתְּ בְּמִפְּקָךְ:
@723 יִתֵּן יְיָ יָת בַּעֲלֵי דְבָבָךְ דְקָיְמִין עֲלָךְ תְּבִירִין קֳדָמָךְ בְּאָרְחָא חַדָא יִפְּקוּן לְוָתָךְ וּבְשִׁבְעָא אָרְחָן יֵעִרְקוּן מִקֳדָמָךְ:
@724 יְפַקֵד יְיָ עִמָךְ יָת בִּרְכְּתָא בְּאוֹצָרָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ וִיבָרְכִנָךְ בְּאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@725 יְקִימִנָךְ יְיָ לֵהּ לְעַם קַדִישׁ כְּמָא דִי קַיִים לָךְ אֲרֵי תִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ וּתְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי:
@726 וְיֶחֱזוּן כָּל עַמְמֵי אַרְעָא אֲרֵי שְׁמָא דַיְיָ אִתְקְרֵי עֲלָךְ וְיִדְחֲלוּן מִנָךְ:
@727 וְיוֹתְרִנָךְ יְיָ לְטָבָא בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@728 יִפְתַּח יְיָ לָךְ יָת אוֹצָרֵהּ טָבָא יָת שְׁמַיָא לְמִתַּן מְטַר אַרְעָךְ בְּעִדָנֵהּ וּלְבָרָכָא יָת כָּל עוֹבָדֵי יְדָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף:
@729 וְיִתְּנִנָךְ יְיָ לְתַקִיף וְלָא לְחַלָשׁ וּתְהֵי בְּרַם לְעֵלָא וְלָא תְהֵי לְתַחְתָּא אֲרֵי תְקַבֵּל לְפִקוּדַיָא דַיְיָ אֱלָהָךְ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִטַר וּלְמֶעְבָּד:
@730 וְלָא תִסְטוּן מִכָּל פִּתְגָמַיָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין יַמִינָא וּשְׂמָאלָא לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא לְמִפְלְחִנוּן:
@731 וִיהֵי אִם לָא תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיֵיתוּן עֲלָךְ כָּל לְוָטַיָא הָאִלֵין וְיִדְבְּקֻנָךְ:
@732 לִיטּ אַתְּ בְּקַרְתָא וְלִיט אַתְּ בְּחַקְלָא:
@733 לִיט סַלָךְ וְאַצְוָתָךְ:
@734 לִיטּ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@735 לִיט אַתְּ בְּמֵעֲלָךְ וְלִיט אַתְּ בְּמִפְּקָךְ:
@736 יְגָרֵי יְיָ בָּךְ יָת מֵאַרְתָּא וְיָת שִׁגוּשַׁיָא וְיָת מְזוֹפִיתָא בְּכָל אוֹשָׁטוּת יְדָךְ דִי תַעְבֵּד עַד דְתִשְׁתֵּצֵי וְעַד דְתֵיבַד בִּפְרִיעַ מִן קֳדָם בִּישׁוּת עוֹבָדָיךְ דִשְׁבַקְתָּא דַחַלְתִּי:
@737 יַדְבֵּק יְיָ בָּךְ יָת מוֹתָא עַד דִישֵׁיצֵי יָתָךְ מֵעַל אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמִירְתַהּ:
@738 יִמְחִנָךְ יְיָ בְּשַׁחֶפְתָּא וּבְקַדַחְתָּא וּבִדְלֶקְתָּא וּבְחַרְחוּרָא וּבְחַרְבָּא וּבְשִׁדְפוֹנָא וּבְיַרְקוֹנָא וְיִרְדְפֻנָךְ עַד דְתֵיבָד:
@739 וִיהוֹן שְׁמַיָךְ דִי עִלָוֵי רֵישָׁךְ חֲסִינִין כִּנְחָשָׁא מִלְאֲחָתָא מִטְרָא וְאַרְעָא דִי תְחוֹתָךְ תַּקִיפָא כְפַרְזְלָא מִלְמֶעְבַּד פֵּרִין:
@740 יִתֵּן יְיָ יָת מְטַר אַרְעָךְ אַבְקָא וְעַפְרָא מִן שְׁמַיָא יֵחוּת עֲלָךְ עַד דְתִשְׁתֵּצֵי:
@741 יִתְּנִנָךְ יְיָ תְּבִיר קֳדָם סָנְאָךְ בְּאָרְחָא חֲדָא תִּפּוֹק לְוָתֵהּ וּבְשִׁבְעָא אָרְחָן תֵּעִרוֹק מִקָדָמוֹהִי וּתְהֵי לְזִיעַ לְכָל מַלְכְּוַת אַרְעָא:
@742 וּתְהֵי נְבִלְתָּךְ מְשַׁגְרָא לְמֵיכַל לְכָל עוֹפָא דִשְׁמַיָא וְלִבְעִירַת אַרְעָא וְלֵית דְמָנִיד:
@743 יִמְחִנָךְ יְיָ בְּשִׁחֲנָא דְמִצְרַיִם וּבִטְּחוֹרִין וּבְגַרְבָּא וּבַחֲרִיס יַבִּישׁ דִי לָא תִכּוּל לְאִתַּסָאָה:
@744 יִמְחִנָךְ יְיָ בְּטַפְשׁוּתָא וּבְסַמְיוּתָא וּבְשַׁעֲמָמוּת לִבָּא:
@745 וּתְהֵי מְמַשֵׁשׁ בְּטִּהֲרָא כְּמָא דִי מַשֵׁשׁ עַוִירָא בְּקַבְלָא וְלָא תַצְלַח יָת אָרְחָתָיךְ וּתְהֵי בְּרַם עָשִׁיק וְאָנִיס כָּל יוֹמַיָא וְלֵית דְפָרִיק:
@746 אִתְּתָא תֵירוֹס וּגְבַר אָחֳרָן יִשְׁכְּבִנַהּ בֵּיתָא תִבְנֵי וְלָא תֵיתֵב בֵּהּ כַּרְמָא תִצוֹב וְלָא תְחַלִנֵהּ:
@747 תּוֹרָךְ יְהֵי נָכֵס לְעֵינָיךְ וְלָא תֵיכוּל מִנֵהּ חֲמָרָךְ יְהֵי אָנֵס מִקֳדָמָךְ וְלָא יְתוּב לָךְ עָנָךְ מְסִירִין לְבַעֲלֵי דְבָבָךְ וְלֵית לָךְ פָּרִיק:
@748 בְּנָיךְ וּבְנָתָיךְ מְסִירִין לְעַמָא אָחָרָן וְעֵינָךְ חֲזָן וִיסוּפָן בִּגְלָלְהֵן כָּל יוֹמָא וְלֵית חֵילָא בִּידָךְ:
@749 אִבָּא דְאַרְעָךְ וְכָל לֵאוּתָךְ יֵכוּל עַמָא דִי לָא יְדַעַתְּ וּתְהֵי בְּרַם עָשִׁיק וּרְעִיעַ כָּל יוֹמַיָא:
@750 וּתְהֵי מִשְׁתַּטֵה מֵחֵזוּ עֵינָיךְ דִי תֶחֱזֵי:
@751 יִמְחִנָךְ יְיָ בְשִׁחֲנָא בִישָׁא עַל רְכֻבַיָא וְעַל שָׁקַיָא דִי לָא תִכּוּל לְאִתַּסָאָה מִפַּרְסַת רַגְלָךְ וְעַד מוֹחָךְ:
@752 יַגְלֵי יְיָ יָתָךְ וְיָת מַלְכָּךְ דִי תְקִים עֲלָךְ לְעַם דִי לָא יְדַעַתְּ אַתְּ וְאַבָהָתָיךְ וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא אָעָא וְאַבְנָא:
@753 וּתְהֵי לְצָדוּ לִמְתַל וּלְשׁוֹעֵי בְכֹל עַמְמַיָא דִי יִדְבְּרִנָךְ יְיָ לְתַמָן:
@754 בַּר זְרַע סַגִי תַּפֵּק לְחַקְלָא וּזְעֵר תִּכְנוֹשׁ אֲרֵי יַחְסְלִנֵהּ גוֹבָא:
@755 כַּרְמִין תִּצוּב וְתִפְלַח וְחַמְרָא לָא תִשְׁתֵּי וְלָא תִכְנוֹשׁ אֲרֵי תֵיכְלִנֵהּ תֹּלַעְתָּא:
@756 זֵיתִין יְהוֹן לָךְ בְּכָל תְּחוּמָךְ וּמִשְׁחָא לָא תְסוּךְ אֲרֵי יִתְּרוּן זֵיתָיךְ:
@757 בְּנִין וּבְנָן תּוֹלִיד וְלָא יְהוֹן לָךְ אֲרֵי יְהָכוּן בְּשִׁבְיָא:
@758 כָּל אִילָנָךְ וְאִבָּא דְאַרְעָךְ יַחְסְנִנֵהּ סַקָאָה:
@759 תּוֹתַב עָרֵל דִי בֵינָךְ יְהֵי סְלִיק עֵיל מִנָךְ לְעֵלָא לְעֵלָא וְאַתְּ תְּהֵי נָחֵת לְתַחְתָּא לְתַחְתָּא:
@760 הוּא יוֹזְפִנָךְ וְאַתְּ לָא תוֹזְפִנֵהּ הוּא יְהֵי לְתַקִיף וְאַתְּ תְּהֵי לְחַלָשׁ:
@761 וְיֵיתוּן עֲלָךְ כָּל לְוָטַּיָא הָאִלֵין וְיִרְדְפֻנָךְ וְיִדְבְּקֻנָךְ עַד דְתִשְׁתֵּצֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִי פַקְדָךְ:
@762 וִיהוֹן בָּךְ לְאָת וּלְמוֹפֵת וּבִבְנָיךְ עַד עֳלָם:
@763 חֳלָף דִי לָא פְלַחְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֶדְוָא וּבְשַׁפִּירוּת לִבָּא מִסְגֵי כֹּלָא:
@764 וְתִפְלַח יָת בַּעֲלֵי דְבָבָךְ דִי יְגָרִנֵהּ יְיָ בָּךְ בְּכַפְנָא וּבְצַחוּתָא וּבְעַרְטִּלְיָתָא וּבַחֲסִירוּת כֹּלָא וְיִתֵּן נִיר פַּרְזְלָא עַל צַוְארָךְ עַד דִישֵׁיצֵי יָתָךְ:
@765 יַיְתִי יְיָ עֲלָךְ עַם מֵרָחִיק מִסְיָפֵי אַרְעָא כְּמָא דִי מִשְׁתְּדִי נִשְׁרָא עַמָא דִי לָא תִשְׁמַע לִישָׁנֵהּ:
@766 עַם תַּקִיף אַפִּין דִי לָא יִסַב אַפִּין לְסָבָא וְעַל יָנְקָא לָא מְרַחֵם:
@767 וְיֵיכוּל וַלְדָא דִבְעִירָךְ וְאִבָּא דְאַרְעָךְ עַד דְתִשְׁתֵּצֵי דִי לָא יַשְׁאַר לָךְ עִבוּרָא חַמְרָא וּמִשְׁחָא בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַד דְיוֹבֵד יָתָךְ:
@768 וְיָעֵק לָךְ בְּכָל קִרְוָיךְ עַד דְיִכְבַּשׁ שׁוּרָיךְ רָמַיָא וּכְרִיכַיָא דִי אַתְּ רָחֵץ לְאִשְׁתֵּזָבָא בְּהֵן בְּכָל אַרְעָךְ וְיָעֵק לָךְ בְּכָל קִרְוָיךְ בְּכָל אַרְעָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@769 וְתֵיכוּל וַלְדָא דִמְעָךְ בְּשַׂר בְּנָיךְ וּבְנָתָיךְ דִי יְהַב לָךְ יְיָ אֱלָהָךְ בִּצְיָרָא וּבְעַקְתָא דְיָעֵק לָךְ סַנְאָךְ:
@770 גַבְרָא דְרַכִּיךְ בָּךְ וְדִמְפַנַק לַחֲדָא תַּבְאֵשׁ עֵינֵהּ בְּאָחוּהִי וּבְאִתַּת קְיָמֵהּ וּבִשְׁאָר בְּנוֹהִי דִי יַשְׁאַר:
@771 מִלְמִתַּן לְחַד מִנְהוֹן מִבְּשַׂר בְּנוֹהִי דִי יֵיכוּל מִדְלָא אִשְׁתָּאַר לֵהּ כֹּלָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְכָל קִרְוָיךְ:
@772 דְרַכִּיכָא בָךְ וְדִמְפַנְקָא דִי לָא נַסִיאַת פַּרְסַת רַגְלַהּ לַאֲחָתָא עַל אַרְעָא מִמְפַנְקוּ וּמֵרַכִּיכוּ תַּבְאֵשׁ עֵינַהּ בִּגְבַר קְיָמַהּ וּבִבְרַהּ וּבִבְרַתַּהּ:
@773 וּבִזְעֵר בְּנָהָא דְיִפְּקוּן מִנַהּ וּבִבְנָהָא דִי תְלִיד אֲרֵי תֵיכְלִנוּן בַּחֲסֵירוּת כֹּלָא בְּסִתְרָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְּקִרְוָיךְ:
@774 אִם לָא תִטַר לְּמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא דִכְתִיבִין בְּסִפְרָא הָדֵין לְמִדְחַל יָת שְׁמָא יַקִירָא וּדְחִילָא הָדֵין יָת יְיָ אֱלָהָךְ:
@775 וְיַפְרַשׁ יְיָ יָת מְחָתָךְ וְיָת מָחַת בְּנָיךְ מָחָן רַבְרְבָן וּמְהֵימְנָן וּמַכְתְּשִׁין בִּישִׁין וּמְהֵימְנִין:
@776 וְיָתֵב בָּךְ יָת כָּל מַכְתְּשֵׁי מִצְרַיִם דִי דְחֶלְתָּא מִקֳדָמֵיהוֹן וְיִדְבְּקוּן בָּךְ:
@777 אַף כָּל מְרַע וְכָל מָחָא דִי לָא כְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדָא יַיְתִנוּן יְיָ עֲלָךְ עַד דְיִשְׁתֵּצָךְ:
@778 וְתִשְׁתַּאֲרוּן בְּעַם זְעֵר חֳלָף דִי הֲוֵיתוּן כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@779 וִיהֵי כְּמָא דְחַדֵי יְיָ עֲלֵיכוֹן לְאוֹטָבָא יָתְכוֹן וּלְאַסְגָאָה יָתְכוֹן כֵּן יֶחֱדֵי יְיָ עֲלֵיכוֹן לְאוֹבָדָא יָתְכוֹן וּלְשֵׁצָאָה יָתְכוֹן וְתִטַלְטְלוּן מֵעַל אַרְעָא דְאַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@780 וִיבַדְרִנָךְ יְיָ בְּכָל עַמְמַיָא מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ אָעָא וְאַבְנָא:
@781 וּבְעַמְמַיָא הָאִנוּן לָא תְנוּחַ וְלָא יְהֵי מְנָח לְפַרְסַת רַגְלָךְ וְיִתֵּן יְיָ לָךְ תַּמָן לֵב דָחֵל וְחַשְׁכַת עַיְנִין וּמַפְּחַן נְפָשׁ:
@782 וִיהוֹן חַיָיךְ תְּלָן לָךְ מִקָבֵל וּתְהֵי תָוֵה לֵילְיָא וִימָמָא וְלָא תְהֵימִין בְּחַיָיךְ:
@783 בְּצַפְרָא תֵימַר מָן יִתֵּן רַמְשָׁא וּבְרַמְשָׁא תֵימַר מָן יִתֵּן צַפְרָא מִתַּוְהוּת לִבָּךְ דִי תְהֵי תָוֵה וּמֵחֵזוּ עֵינָיךְ דִי תְהֵי חָזֵי:
@784 וְיָתֵיבִנָךְ יְיָ מִצְרַיִם בִּסְפִינָן בְּאָרְחָא דִי אֲמָרִית לָךְ לָא תוֹסֵף עוֹד לְמֶחְזְיַהּ וְתִזְדַבְּנוּן תַּמָן לְבַעֲלֵי דְבָבָךְ לְעַבְדִין וּלְאַמְהָן וְלֵית דְקָנֵהּ:
@785 אִלֵין פִּתְגָמֵי קְיָמָא דִי פַקִיד יְיָ יָת מֹשֶׁה לְמִגְזַר עִם בְּנֵי יִשְׂרָאֵל בְּאַרְעָא דְמוֹאָב בַּר מִקְיָמָא דִי גְזַר עִמְהוֹן בְּחֹרֵב:
@786 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן אַתּוּן חֲזֵיתוּן יָת כָּל דִי עֲבַד יְיָ לְעֵינֵיכוֹן בְּאַרְעָא דְמִצְרַיִם לְפַרְעֹה וּלְכָל עַבְדוֹהִי וּלְכָל אַרְעֵהּ:
@787 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ אָתַיָא וּמוֹפְתַיָא רַבְרְבַיָא הָאִנוּן:
@788 וְלָא יְהַב יְיָ לְכוֹן לִבָּא לְמִדַע וְעַיְנִין לְמֶחֱזֵי וְאֻדְנִין לְמִשְׁמַע עַד יוֹמָא הָדֵין:
@789 וְדַבָּרִית יָתְכוֹן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא לָא בְלִיאַת כְּסוּתְכוֹן מִנְכוֹן וּמְסָנָךְ לָא:עַדוֹ מֵעַל רַגְלָךְ:
@790 לַחְמָא לָא אֲכַלְתּוּן וַחֲמַר חֲדַת וְעַתִּיק לָא שְׁתֵיתוּן בְּדִיל דְתִדְעוּן אֲרֵי אֲנָא יְיָ אֶלָהֲכוֹן:
@791 וַאֲתֵתוּן לְאַתְרָא הָדֵין וּנְפַק סִיחוֹן מַ לְכָּא דְחֶשְׁבּוֹן וְעוֹג מַ לְכָּא דְמַתְנָן לָקֳדָמוּתָנָא לַאֲגָחָא קְרָבָא וּמְחוֹנוּן:
@792 וּנְסִבְנָא יָת אַרְעֲהוֹן וִיהָבִנַהּ לְאַחֲסָנָא לְשִׁבְטָּא דִרְאוּבֵן וּלְשִׁבְטָא דְגָד וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה:
@793 וְתִטְרוּן יָת פִּתְגָמֵי קְיָמָא הָדָא וְתַעְבְּדוּן יָתְהוֹן בְּדִיל דְתִצְלְחוּן יָת כָּל דִי תַּעְבְּדוּן: פפפ:
@794 אַתּוּן קָיְמִין יוֹמָא דֵין כֻּלְכוֹן קֳדָם יְיָ אֱלָהֲכוֹן רֵישֵׁיכוֹן שִׁבְטֵיכוֹן סָבֵיכוֹן וְסָרְכֵיכוֹן כָּל אֱנַשׁ יִשְׂרָאֵל:
@795 טַפְלְכוֹן נְשֵׁיכוֹן וְגִיוֹרָךְ דִי בְּגוֹ מַשְׁרִיתָךְ מִלָקֵטּ אָעָיךְ עַד מְלֵי מַיָיךְ:
@796 לְאָעָלוּתָךְ בִּקְיָמָא דַיְיָ אֱלָהָךְ וּבְמוֹמָתֵהּ דִי יְיָ אֱלָהָךְ גְזַר עִמָךְ יוֹמָא דֵין:
@797 בְּדִיל לַאֲקָמָא יָתָךְ יוֹמָא דֵין קֳדָמוֹהִי לְעַמָא וְהוּא יְהֵי לָךְ לֶאֶלָהּ כְּמָא דִי מַלִיל לָךְ וּכְמָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@798 וְלָא עִמְכוֹן בִּלְחוֹדֵיכוֹן אֲנָא גְזַר יָת קְיָמָא הָדָא וְיָת מוֹמָתָא הָדָא:
@799 אֲרֵי יָת מָן דְאִיתוֹהִי הָכָא עִמָנָא קָאֵם יוֹמָא דֵין קֳדָם יְיָ אֱלָהָנָא וְיָת מָן דְלֵיתוֹהִי הָכָא עִמָנָא יוֹמָא דֵין:
@800 אֲרֵי אַתּוּן יְדַעְתּוּן יָת דִיתֵבְנָא בְּאַרְעָא דְמִצְרָיִם וְיָת דִי עֲבַרְנָא בְּגוֹ עַמְמַיָא דִי עֲבַרְתּוּן:
@801 וַחֲזֵיתוּן יָת שִׁקוּצֵיהוֹן וְיָת טַעֲוָתְהוֹן אָעָא וְאַבְנָא כַּסְפָּא וְדַהֲבָא דִי עִמְהוֹן:
@802 דִילְמָא אִית בְּכוֹן גְבַר אוֹ אִתְּתָא אוֹ זַרְעִית אוֹ שִׁבְטָא דִי לִבֵּהּ פָּנֵי יוֹמָא דֵין מִדַחַלְתָּא דַייָ אֱלָהָנָא לִמְהַךְ לְמִפְלַח יָת טַעֲוַת עַמְמַיָא הָאִנוּן דִילְמָא אִית בְּכוֹן גְבַר מְהַרְהַר חֶטְאִין אוֹ זָדוֹן:
@803 וִיהֵי בְּמִשְׁמְעֵהּ יָת פִּתְגָמֵי מוֹמָתָא הָדָא וִיחַשַׁב בְּלִבֵּהּ לְמֵימַר שְׁלָמָא יְהֵי לִי אֲרֵי בְּהַרְהוֹר לִבִּי אֲנָא אָזֵל בְּדִיל לְאוֹסָפָא לֵהּ חֶטְאֵי שָׁלוּתָא עַל זְדָנוּתָא:
@804 לָא יֵיבֵי יְיָ לְמִשְׁבַּק לֵהּ אֲרֵי בְּכֵן יִתְקֵף רָגְזָא דַיְיָ וְחֶמְתֵהּ בְּגַבְרָא הַהוּא וְיִדְבְּקוּן בֵּהּ כָּל לְוָטַּיָא דִכְתִיבִין בְּסִפְרָא הָדֵין וְיִמְחֵי יְיָ יָת שְׁמֵהּ מִתְּחוֹת שְׁמַיָא:
@805 וְיַפְרְשִׁנֵהּ יְיָ לְבִישָׁא מִכֹּל שִׁבְטַיָא דְיִשְׂרָאֵל כְּכֹל לְוָטֵי קְיָמָא דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין:
@806 וְיֵימַר דָרָא בַתְרָאָה בְּנֵיכוֹן דִי יְקוּמוּן מִבַּתְרֵיכוֹן וּבַר עַמְמִין דִי יֵיתֵי מֵאַרְעָא רְחִיקָא וְיֶחֱזוּן יָת מְחָתָא דְאַרְעָא הַהִיא וְיָת מַרְעָהָא דִי אַמְרַע יְיָ בַּהּ:
@807 גָפְרֵתָא וּמִלְחָא יְקִידַת כָּל אַרְעַהּ לָא תִזְרַע וְלָא תַצְמַח וְלָא יִסַק בַּהּ כָּל עֶסְבָּא כְּמַהְפֶּכְתָּא דִסְדֹם וַעֲמֹרָה אַדְמָה וּצְבוֹיִם דִי הֲפַךְ יְיָ בְּרָגְזֵהּ וּבְחֶמְתֵהּ:
@808 וְיֵימְרוּן כָּל עַמְמַיָא עַל מֶה עֲבַד יְיָ כְּדֵין לְאַרְעָא הָדָא מָא תְקוֹף רָגְזָא רַבָּא הָדֵין:
@809 וְיֵימְרוּן עַל דִשְׁבָקוּ יָת קְיָמָא דַיְיָ אֱלָהָא דַאֲבָהָתְהוֹן דִי גְזַר עִמְהוֹן בְּאַפָּקוּתֵהּ יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם:
@810 וַאֲזָלוּ וּפְלָחוּ לְטַעֲוַת עַמְמַיָא וּסְגִידוּ לְהוֹן דַחֲלָן דִי לָא יְדָעֻנוּן וְלָא אוֹטִיבָא לְהוֹן:
@811 וּתְקֵף רָגְזָא דַיְיָ בְּאַרְעָא הַהִיא לְאַיְתָאָה עֲלַהּ יָת כָּל לְוָטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין:
@812 וְטַּלְטְּלִנוּן יְיָ מֵעַל אַרְעֲהוֹן בִּרְגַז וּבְחֵמְתָא וּבִתְקוֹף רְגַז וְאַגְלִנוּן לְאַרְעָא אָחֳרִי כְּיוֹמָא הָדֵין:
@813 דְמִטַמְרָן קֳדָם יְיָ אֱלָהָנָא וּדְמִגַלְיָן לָנָא וְלִבְנָנָא עַד עֳלָם לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@814 וִיהֵי אֲרֵי יֵיתוּן עֲלָךְ כָּל פִּתְגָמַיָא הָאִלֵין בִּרְכָן וּלְוָטִין דִי יְהָבִית קֳדָמָךְ וּתְתוּב לְלִבָּךְ בְּכָל עַמְמַיָא דִי אַגְלָךְ יְיָ אֱלָהָךְ לְתַמָן:
@815 וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ כְּכֹל דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין אַתְּ וּבְנָיךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@816 וִיתוּב יְיָ אֱלָהָךְ יָת שְׁבִי גַלְוָתָךְ וִירַחַם עֲלָךְ וִיתוּב וְיִכְנְשִׁנָךְ מִכָּל עַמְמַיָא דִי בַדְרָךְ יְיָ אֱלָהָךְ לְתַמָן:
@817 אִם יְהֵי גַלְוָתָךְ בִּסְיָפֵי שְׁמַיָא מִתַּמָן יִכְנְשִׁנָךְ יְיָ אֱלָהָךְ וּמִתַּמָן יְקָרְבִנָךְ:
@818 וְיָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִירִיתוּ אֲבָהָתָךְ וְתֵרְתַהּ וְיוֹטֶב לָךְ וְיַסְגִנָךְ מֵאֲבְהָתָךְ:
@819 וְיֶעְדֵי יְיָ אֱלָהָךְ יָת טַפְשׁוּת לִבָּךְ וְיָת טַּפְשׁוּת לִבָּא דִבְנָיךְ לְמִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ בְּדִיל חַיָיךְ:
@820 וְיִתֵּן יְיָ אֱלָהָךְ יָת כָּל לְוָטַיָא הָאִלֵין עַל בַּעֲלֵי דְבָבָךְ וְעַל סָנְאָךְ דִי רְדָפוּךְ:
@821 וְאַתְּ תְּתוּב וּתְקַבַּל לְמֵימְרָא דַיְיָ וְתַעְבֵּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@822 וְיוֹתְרִינָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ לְטָּבָא אֲרֵי יְתוּב יְיָ לְמֶחֱדֵי עֲלָךְ לְטָב כְּמָא דִי חֲדִי עַל אֲבָהָתָךְ:
@823 אֲרֵי תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין אֲרֵי תְתוּב קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@824 אֲרֵי תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לָא מַפְרְשָׁא הִיא מִנָךְ וְלָא רְחִיקָא הִיא:
@825 לָא בִשְׁמַיָא הִיא לְמֵימָר מָן יִסַק לָנָא לִשְׁמַיָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@826 וְלָא מֵעִבְרָא לְיַמָא הִיא לְמֵימַר מָן יֵעִבַר לָנָא לְעִבְרָא דְיַמָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@827 אֲרֵי קָרִיב לָךְ פִּתְגָמָא לַחֲדָא בְּפוּמָךְ וּבְלִבָּךְ לְמֶעְבְּדֵהּ:
@828 חֲזֵי דִיהָבִית קֳדָמָךְ יוֹמָא דֵין יָת חַיֵי וְיָת טַבְתָא וְיָת מוֹתָא וְיָת בִּישָׁא:
@829 דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי וְדִינוֹהִי וְתֵיחֵי וְתִסְגֵי וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@830 וְאִם יִפְנֵי לִבָּךְ וְלָא תְקַבֵּל וְתִטְּעֵי וְתִסְגוּד לְטַּעֲוַת עַמְמַיָא וְתִפְלְחִנוּן:
@831 חַוֵיתִי לְכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן לָא תוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתְּ עָבֵר יָת יַרְדְנָא לְמֵעַל לְתַמָן לְמֵירְתַהּ:
@832 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא חַיֵי וּמוֹתָא יְהָבִית קֳדָמָךְ בִּרְכָן וּלְוָטִין וְתִתִּרְעֵי בְּחַיֵי בְּדִיל דְתֵיחֵי אַתְּ וּבְנָיךְ:
@833 לְמִרְחַם יָת יְיָ אֱלָהָךְ לְקַבָּלָא לְמֵימְרֵהּ וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ אֲרֵי הוּא חַיָיךְ וְאוֹרָכוּת יוֹמָיךְ לְמִתַּב עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן: פפפ:
@834 וַאֲזַל מֹשֶׁה וּמַלִיל יָת פִּתְגָמַיָא הָאִלֵין עִם כָּל יִשְׂרָאֵל:
@835 וַאֲמַר לְהוֹן בַּר מְאָה וְעֶשְׂרִין שְׁנִין אֲנָא יוֹמָא דֵין לֵית אֲנָא יָכִיל עוֹד לְמִפַּק וּלְמֵעָל וַיְיָ אֲמַר לִי לָא תֵעִבַר יָת יַרְדְנָא הָדֵין:
@836 יְיָ אֱלָהָךְ מֵימְרֵהּ עֲבַר קֳדָמָךְ הוּא יְשֵׁצֵי יָת עַמְמַיָא הָאִלֵין מִקֳדָמָךְ וְתֵירְתִנוּן יְהוֹשֻׁעַ הוּא עֲבַר קֳדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@837 וְיַעְבֵּד יְיָ לְהוֹן כְּמָא דִי עֲבַד לְסִיחוֹן וּלְעוֹג מַלְכֵי אֱמוֹרָאָה וּלְאַרְעֲהוֹן דִי שֵׁצִי יָתְהוֹן:
@838 וְיִמְסְרִנוּן יְיָ קֳדָמֵיכוֹן וְתַעְבְּדוּן לְהוֹן כְּכָל תַּפְקֶדְתָּא דִי פַקֵדִית יָתְכוֹן:
@839 תְּקִיפוּ וְאַלִימוּ לָא תִדְחֲלוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן אֲרֵי יְיָ אֱלָהָךְ הוּא דִמְדַבַּר קֳדָמָךְ לָא יִשְׁבְּקִנָךְ וְלָא יַרְטֵשִׁנָךְ:
@840 וּקְרָא מֹשֶׁה לִיהוֹשֻׁעַ וַאֲמַר לֵהּ לְעֵינֵי כָל יִשְׂרָאֵל תְּקַף וְאַלִים אֲרֵי אַתְּ תֵּעוּל עִם עַמָא הָדֵין לְאַרְעָא דִי קַיִים יְיָ לַאֲבְהָתְהוֹן לְמִתַּן לְהוֹן וְאַתְּ תַּחְסְנִנַהּ יָתְהוֹן:
@841 וַיְיָ הוּא דִמְדַבַּר קֳדָמָךְ מֵימְרֵהּ יְהֵי בְסַעְדָךְ לָא יִשְׁבְּקִנָךְ וְלָא יַרְחֵקִנָךְ לָא תִדְחַל וְלָא תִתְּבַר:
@842 וּכְתַב מֹשֶׁה יָת אוֹרַיְתָא הָדָא וִיהָבַהּ לְכָהֲנַיָא בְּנֵי לְוֵי דְנָטְלִין יָת אֲרוֹן קְיָמָא דַיְיָ וּלְכָל סָבֵי יִשְׂרָאֵל:
@843 וּפַקִיד מֹשֶׁה יָתְהוֹן לְמֵימָר מִסוֹף שְׁבַע שְׁנִין בִּזְמַן שַׁתָּא דִשְׁמִטְתָא בְּחַגָא דְמְטַלַיָא:
@844 בְּמֵיתֵי כָל יִשְׂרָאֵל לְאִתְחֲזָאָה קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי תִּקְרֵי יָת אוֹרַיְתָא הָדָא קֳדָם כָּל יִשְׂרָאֵל וְתַשְׁמְעִנוּן:
@845 כְּנוֹשׁ יָת עַמָא גֻבְרַיָא וּנְשַׁיָא וְטַּפְלָא וְגִיוֹרָךְ דִי בְקִרְוָיךְ בְּדִיל דְיִשְׁמְעוּן וּבְדִיל דְיַלְפוּן (נ''א דְיֵלְפוּן) וְיִדְחֲלוּן מֵקֳדָם יְיָ אֱלָהֲכוֹן וְיִטְרוּן לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@846 וּבְנֵיהוֹן דִי לָא יָדְעוּן יִשְׁמְעוּן וְיַלְפוּן (נ''א וְיֵלְפוּן) לְמִדְחַל יָת יְיָ אֱלָהֲכוֹן כֹּל יוֹמַיָא דִי אַתּוּן קְיָמִין עַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא תַּמָן לְמֵירְתַהּ:
@847 וַאֲמַר יְיָ לְמֹשֶׁה הָא קְרִיבוּ יוֹמָיךְ לִמְמַת קְרָא יָת יְהוֹשֻׁעַ וְאִתְעֲתָּדוּ בְּמַשְׁכַּן זִמְנָא וֶאֱפַקְדִנֵהּ וַאֲזַל מֹשֶׁה וִיהוֹשֻׁעַ וְאִתְעַתָּדוּ בְּמַשְׁכַּן זִמְנָא:
@848 וְאִתְגְלִי יְיָ בְּמַשְׁכְּנָא בְּעַמוּדָא דַעֲנָנָא וְקָם עַמוּדָא דַעֲנָנָא עַל תְּרַע מַשְׁכְּנָא:
@849 וַאֲמַר יְיָ לְמֹשֶׁה הָא אַתְּ שָׁכֵב עִם אֲבָהָתָךְ וִיקוּם עַמָא הָדֵין וְיִטְּעֵי בָּתַר טַעֲוַת עַמְמֵי אַרְעָא דִי הוּא עַל תַּמָן בֵּינֵיהוֹן וְיִשְׁבְּקוּן דַחַלְתִּי וְיַשְׁנוּן יָת קְיָמִי דִי גְזָרִית עִמְהוֹן:
@850 וְיִתְקוֹף רָגְזִי בְהוֹן בְּיוֹמָא הַהוּא וְאַרְחֵקִנוּן וֶאֱסַלֵק שְׁכִנְתִּי מִנְהוֹן וִיהוֹן לְמִבַּז וִיעָרְעַן יָתְהוֹן בִּישָׁן סַגִיאָן וְעָקָן וְיֵימַר בְּיוֹמָא הַהוּא הֲלָא מִדְלֵית שְׁכִינַת אֱלָהַי בֵּינִי עָרְעוּנִי בִּישַׁיָא הָאִלֵין:
@851 וַאֲנָא סַלָקָא אֶסַלֵק שְׁכִנְתִּי מִנְהוֹן בְּיוֹמָא הַהוּא עַל כָּל בִּישָׁא דִי עֲבָדוּ אֲרֵי אִתְפְּנִיוּ לְטַעֲוַת עַמְמַיָא:
@852 וּכְעַן כְּתִיבוּ לְכוֹן יָת תֻּשְׁבַּחְתָּא הָדָא וְאַלְפַהּ יָת בְּנֵי יִשְׂרָאֵל שַׁוְיַהּ בְּפוּמְהוֹן בְּדִיל דִתְהֵי קֳדָמַי תֻּשְׁבַּחְתָּא הָדָא לְסָהִיד בִּבְנֵי יִשְׂרָאֵל:
@853 אֲרֵי אָעֵלִנוּן לְאַרְעָא דִי קַיֵמִית לַאֲבָהָתְהוֹן עָבְדָא חֲלַב וּדְבַשׁ וְיֵיכְלוּן וְיִשְׂבְּעוּן וְיִתְפַּנְקוּן וְיִתְפְּנוּן בָּתַר טַּעֲוַת עַמְמַיָא וְיִפְלְחֻנוּן וְיִרְגְזוּן קֳדָמַי וְיַשְׁנוּן יָת קְיָמִי:
@854 וִיהֵי אֲרֵי יְעָרְעָן יָתֵהּ בִּישָׁן סַגִיאָן וְעָקָן וְתָתֵב תֻּשְׁבַּחְתָּא הָדָא קֳדָמוֹהִי לְסָהִיד אֲרֵי לָא תִתְנְשֵׁי מִפּוּם בֵּנֵיהוֹן ארֵי גִלֵי קֳדָמַי יָת יִצְרְהוֹן דִי אִנוּן עָבְדִין יוֹמָא דֵין עַד לָא אָעֵלִנוּן לְאַרְעָא דִי קַיֵמִית:
@855 וּכְתַב מֹשֶׁה יָת תּוּשְׁבַּחְתָּא הָדָא בְּיוֹמָא הַהוּא וְאַלֵפִנַהּ לִבְנֵי יִשְׂרָאֵל:
@856 וּפַקִיד יָת יְהוֹשֻׁעַ בַּר נוּן וַאֲמַר תְּקֵף וְאַלִים אֲרֵי אַתְּ תָּעֵל יָת בְּנֵי יִשְׂרָאֵל לְאַרְעָא דִי קַיֵמִית לְהוֹן וּמֵימְרִי יְהֵי בְסַעְדָךְ:
@857 וַהֲוָה כַּד שֵׁצֵי מֹשֶׁה לְמִכְתַּב יָת פִּתְגָמֵי אוֹרַיְתָא הָדָא עַל סִפְרָא עַד דִשְׁלִימוּ:
@858 וּפַקִיד מֹשֶׁה יָת לֵוָאֵי נָטְלֵי אֲרוֹן קְיָמָא דַיְיָ לְמֵימָר:
@859 סִיבוּ יָת סִפְרָא דְאוֹרַיְתָא הָדֵין וּתְשַׁוּוּן יָתֵהּ מִסְטַר אֲרוֹן קְיָמָא דַיְיָ אֱלָהֲכוֹן וִיהֵי תַמָן בָּךְ לְסָהִיד:
@860 אֲרֵי אֲנָא יְדַעְנָא יָת סַרְבָנוּתָךְ וְיָת קְדָלָךְ דְקַשְׁיָא הָא בְעַד אֲנָא קַיָם עִמְכוֹן יוֹמָא דֵין מְסָרְבִין הֲוֵיתוּן קֳדָם יְיָ וְאַף אֲרֵי בָּתַר דְאֵמוּת:
@861 כְּנִישׁוּ לְוָתִי יָת כָּל סָבֵי שִׁבְטֵיכוֹן וְסָ רְכֵיכוֹן וֶאֱמַ לֵל קֳדָמֵיהוֹן יָת פִּתְגָמַיָא הָאִלֵין וְאַסְהֵד בְּהוֹן יָת שְׁמַיָא וְיָת אַרְעָא:
@862 אֲרֵי יְדַעְנָא בָּתַר דְאֵמוּת אֲרֵי חֲבָּלָא תְחַבְּלוּן וְתִסְטוּן מִן אָרְחָא דִי פַקֵדִית יָתְכוֹן וּתְעָרַע יָתְכוֹן בִּשְׁתָּא בְּסוֹף יוֹמַיָא אֲרֵי תַעְבְּדוּן יָת דְבִישׁ קֳדָם יְיָ לְאַרְגָזָא קֳדָמוֹהִי בְּעוֹבָדֵי יְדֵיכוֹן:
@863 וּמַלִיל מֹשֶׁה קֳדָם כָּל קְהָלָא דְיִשְׂרָאֵל יָת פִּתְגָמֵי תּוּשְׁבַּחְתָּא הָדָא עַד דִשְׁלִימוּ: פפפ:
@864 אַצִיתוּ שְׁמַיָא וֶאֱמַלֵל וְתִשְׁמַע אַרְעָא מֵימְרֵי פֻמִי:
@865 יְבַסַם כְּמִטְרָא אוּלְפָּנִי יִתְקַבַּל כְּטַלָא מֵימְרִי כְּרוּחֵי מִטְרָא דְנָשְׁבִין עַל דִתְאָה וְכִרְסִיסֵי מַלְקוֹשָׁא דִי עַל עִשְׂבָּא:
@866 אֲרֵי בִּשְׁמָא דַיְיָ אֲנָא מְצַלֵי הָבוּ רְבוּתָא קֳדָם אֱלָהָנָא:
@867 תַּקִיפָא דְשָׁלְמִין עוֹבָדוֹהִי אֲרֵי כָּל אֹרְחָתֵהּ דִינָא אֱלָהָא מְהֵימְנָא דְמִן קֳדָמוֹהִי עַוְלָה לָא נָפֵק מִן קֳדָם דְזַכַּי וְקַשִׁיט הוּא:
@868 חַבִּילוּ לְהוֹן לָא לֵהּ בְּנַיָא דִי פְלָחוּ לְטַעֲוָתָא דָרָא דְאַשְׁנִיוּ עוֹבָדוֹהִי וְאִשְׁתַּנִיוּ:
@869 הָא קֳדָם יְיָ אַתּוּן גָמְלִין דָא עַמָא דְקַבִּילוּ אוֹרַיְתָא וְלָא חַכִּימוּ הֲלָא הוּא אֲבוּךְ וְאַתְּ דִי לֵהּ הוּא עָבְדָךְ וְאַתְקְנָךְ:
@870 אִדְכַּר יוֹמִין דְמִן עָלְמָא אִסְתַּכַּל בִּשְׁנֵי דַר וְדַר שְׁאַל אֲבוּךְ וִיחַוִּי לָךְ סָבָיךְ וְיֵימְרוּן לָךְ:
@871 בְּאַחֲסָנָא עִלָאָה עַמְמַיָא בְּפָרָשׁוּתֵהּ בְּנֵי אֲנָשָׁא קַיִים תְּחוּמֵי עַמְמַיָא לְמִנְיַן בְּנֵי יִשְׂרָאֵל:
@872 אֲרֵי חֳלָקָא דַיְיָ עַמֵהּ יַעֲקֹב עֲדַב אַחֲסַנְתֵּהּ:
@873 סַפִּיק צָרְכֵּיהוֹן בְּאַרְעָא מַדְבְּרָא וּבֵית צַחֲוָנָא אֲתַר דִי לֵית מַיָא אַשְׁרִנוּן סְחוֹר סְחוֹר לִשְׁכִנְתֵּהּ אַלֵפִנוּן פִּתְגָמֵי אוֹרַיְתָא נְטָרִנוּן כְּבָבַת עֵינֵיהוֹן:
@874 כְּנִשְׁרָא דִמְחִישׁ לְקִנֵהּ עַל בְּנוֹהִי מִתְחוֹפֵף פָּרִיס גַדְפּוֹהִי מְקַבֶּלְהוֹן מְנַטֶלְהוֹן עַל תְּקוֹף אֵבָרוֹהִי:
@875 יְיָ בִּלְחוֹדוֹהִי עֲתִיד לְאַשְׁרָיוּתְהוֹן בְּעָלְמָא דְּהוּא עָתִיד לְאִתְחַדָתָא וְלָא יִתְקַיַם קֳדָמוֹהִי פָּלְחַן טַּעֲוָן:
@876 אַשְׁרִנוּן עַל תָּקְפֵּי אַרְעָא וְאוֹכָלִנוּן בִּזַת סָנְאֵיהוֹן וִיהַב לְהוֹן בִּזַת שַׁלִיטֵי קִרְוִין וְנִכְסֵי יָתְבֵי כְּרַכִּין תַּקִיפִין:
@877 יְהַב לְהוֹן בִּזַת מַלְכֵיהוֹן וְשַׁלִיטֵיהוֹן עִם עוֹתַר רַבְרְבֵיהוֹן וְתַקִפֵיהוֹן עַמָא דְאַרְעֲהוֹן וְאַחֲסַנְתְּהוֹן עִם בִּזַת חֵילֵיהוֹן וּמַשִׁרְיָתְהוֹן וְדַם גִבָּרֵיהוֹן יִתָּשַׁד כְּמַיָא:
@878 וְעַתַּר יִשְׂרָאֵל וּבְעַט אַצְלַח תְּקוֹף קְנָא נִכְסִין וּשְׁבַק פָּלְחַן אֱלָהָא דְעָבְדֵהּ וְאַרְגֵז קֳדָם תַּקִיפָא דְפָרְקֵהּ:
@879 אַקְנִיאוּ קֳדָמוֹהִי בְּפָלְחַן טַעֲוָן בְּתוֹעֶבְתָּא אַרְגִיזוּ קֳדָמוֹהי:
@880 דבָּחוּ לשֵׁדין דִלֵית בְּהוֹן צְרוֹךְ דַחֲלָן דְלָא יְדָעֻנוּן חַדְתִּין דִי מִקָרִיב אִתְעֲבִידוּ לָא אִתְעַסְקוּ בְהוֹן אֲבָהָתְכוֹן:
@881 דַחֲלַת תַקִיפָא דִבְרָאָךְ אִתְנְשֵׁתָא שְׁבַקְתָּא פָלְחַן אֱלָהָא דְעָבְדָךְ:
@882 וּגְלֵי קֳדָם יְיָ וּתְקֵף רָגְזֵהּ מִדְאַרְגִיזוּ קֳדָמוֹהִי בְּנִין וּבְנָן:
@883 וַאֲמַר אֶסַלֵק שְׁכִנְתִּי מִנְהוֹן גְלֵי קֳדָמַי מָה יְהֵי בְסוֹפֵיהוֹן אֲרֵי דָרָא דְאַשְׁנִיוּ אִנוּן בְנַיָא דִלֵית בְּהוֹן הֵימָנוּ:
@884 אִנוּן אַקְנִיאוּ קֳדָמַי בְּלָא דַחֲלָא אַרְגִיזוּ קֳדָמַי בְּפָלְחַן טַעֲוָן וַאֲנָא אַקְנִנוּן בְּלָא עַם בְּעַמָא טַּפְּשָׁא אַרְגֵזִנוּן:
@885 אֲרֵי קִדוּם תַּקִיף כְּאֶשָׁא נְפַק מִקָדָמַי בִּרְגַז וְשֵׁצֵי עַד שְׁאוֹל אֲרָעִית וְאָסֵף אַרְעָא וַעֲלַלְתַּהּ וְשֵׁצְיַת עַד סְיָפֵי טוּרַיָא:
@886 אָסֵף עֲלֵיהוֹן בִּישִׁין מַכְתָּשַׁי אֱשֵׁצֵי בְהוֹן:
@887 נְפִיחֵי כָפָן וַאֲכוּלֵי עוּף וּכְתִישֵׁי רוּחִין בִּישָׁן וְשֵׁן חֵיוַת בָּרָא אֱגָרֵי בְהוֹן עִם חֲמַת תַּנִינַיָא דְזָחֲלִין בְּעַפְרָא:
@888 מִבָּרָא תְּתַכֵּל חַרְבָּא וּמִתְּוָנַיָא חַרְגַת מוֹתָא אַף עוּלֵמֵיהוֹן אַף עוּלֵמָתְהוֹן יָנְקֵיהוֹן עִם אֱנַשׁ סָבֵיהוֹן:
@889 אֲמָרִית יֵחוֹל רוּגְזִי עֲלֵיהוֹן וֶאֱשֵׁצִנוּן אֱבַטַל מִבְּנֵי אֲנָשָׁא דוּכְרָנֵיהוֹן:
@890 אִלוּלָפוֹן רָגְזָא דְסָנְאָה כְּנִישׁ דִילְמָא יִתְרַבְרַב בְּעֵל דְבָבָא דִילְמָא יֵימְרוּן יְדָנָא תְקִיפַת לָנָא וְלָא מִן קֳדָם יְיָ הֲוַת כָּל דָא:
@891 אֲרֵי עַם מְאַבְּדֵי עֵצָה אִנוּן וְלֵית בְּהוֹן סוּכְלְתָנוּ:
@892 אִלוּ חַכִּימוּ אִסְתַּכָּלוּ בְדָא סְבָרוּ מָה יְהֵי בְסוֹפֵיהוֹן:
@893 אֶכְדֵין יִרְדוֹף חַד אַלְפָא וּתְרֵין יֶעֶרְקוּן לְרִבּוֹתָא אֶלָהֵן (אֲרֵי) תַּקִיפְהוֹן מְסָרִנוּן וַייָ אַשְׁלֵמִנוּן:
@894 אֲרֵי לָא כְתָקְפָּנָא תָּקְפְהוֹן וּבַעֲלֵי דְבָבָנָא הֲווֹ דַיָנָנָא:
@895 אֲרֵי כְפֻרְעֲנוּת עַמָא דִסְדוֹם פֻּרְעֲנוּתְהוֹן וְלָקוּתְהוֹן כְּעַם עֲמֹרָה מָחָתְהוֹן בִּישִׁין כְּרֵישֵׁי חֶוְיָן וְתֻשְׁלָמַת עוֹבָדֵיהוֹן כִּמְרָרוּתְהוֹן:
@896 הָא כְמָרַת תַּנִינַיָא כַּס פֻּרְעֲנוּתְהוֹן וּכְרֵישׁ פְּתָנֵי חֶוְיָן אַכְזְרָאִין:
@897 הֲלָא כָל עוֹבָדֵיהוֹן גְלָן קֳדָמַי גְנִיזִין לְיוֹם דִינָא בְּאוֹצְרָי:
@898 קֳדָמַי פֻּרְעֲנוּתָא וַאֲנָא אֲשַׁלֵם לְעִדָן דְיִגְלוּן מֵאַרְעֲהוֹן אֲרֵי קָרִיב יוֹם תְּבָרְהוֹן וּמַבַּע דְעָתִיד לְהוֹן:
@899 אֲרֵי יְדִין יְיָ דִינָא דְעַמֵהּ וּפֻרְעֲנוּת עֲבְדוֹהִי צַדִיקַיָא יִתְפְרַע אֲרֵי גְלֵי קֳדָמוֹהִי דִבְעִדָן דְתִתְקֵף עֲלֵיהוֹן מָחַת סָנְאָה יְהוֹן מִטַלְטְלִין וּשְׁבִיקִין:
@900 וְיֵימַר אָן דַחֲלָתְהוֹן תַּקִיפָא דַהֲווֹ רְחִיצִין בֵּהּ:
@901 דִי תְרַב נִכְסָתְהוֹן הֲווֹ אָכְלִין שָׁתָן חֲמַר נִסְכֵּיהוֹן יְקוּמוּן כְּעַן וִיסַעֲדוּנְכוֹן יְהוֹן עֲלֵיכוֹן מָגֵן:
@902 חֲזוֹ כְּעַן אֲרֵי אֲנָא אֲנָא הוּא וְלֵית אֱלָהּ בַּר מִנִי אֲנָא מֵמִית וּמְחַיֵה מָחֵינָא וְאַף מַסֵינָא וְלֵית מִן יְדִי מְשֵׁזֵב:
@903 אֲרֵי אַתְקֵנִית בִּשְׁמַיָא בֵּית שְׁכִנְתִּי וַאֲמָרִית קַיָם אֲנָא לְעָלְמִין:
@904 אִם עַל חַד תְּרֵין כְּחֵיזוּ בַרְקָא מִסוֹף שְׁמַיָא וְעַד סוֹף שְׁמַיָא תִּתְגְלִי חַרְבִּי וְתִתְקֵף בְּדִינָא יְדִי אָתֵב פֻּרְעֲנוּתָא לְסָנְאַי וּלְבַעֲלֵי דְבָבַי אֱשַׁלֵם:
@905 אֱרַוֵי גִירַי מִדְמָא וְחַרְבִּי תִּקְטוֹל בְּעַמְמַיָא מִדַם קְטִילָן וְשִׁבְיָן לְאַעְדָאָה כִתְרִין מֵרֵישׁ סָנְאָה וּבְעַל דְבָבָא:
@906 שַׁבָּחוּ עַמְמַיָא עַמֵהּ אֲרֵי פֻּרְעֲנוּת עַבְדוֹהִי צַדִיקַיָא יִתְפְּרַע וּפֻרְעֲנוּת יָתֵיב לְסָנְאוֹהִי וִיכַפֵּר עַל אַרְעֵהּ וְעַל עַמֵהּ:
@907 וַאֲתָא מֹשֶׁה וּמַלִּיל יָת כָּל פִּתְגָמֵי תֻשְׁבַּחְתָּא הָדָא קֳדָם עַמָא הוּא וְהוֹשֵׁעַ בַּר נוּן:
@908 וְשֵׁצִי מֹשֶׁה לְמַלָלָא יָת כָּל פִּתְגָמַיָא הָאִלֵין עִם כָּל יִשְׂרָאֵל:
@909 וַאֲמַר לְהוֹן שַׁווּ לִבְּכוֹן לְכָל פִּתְגָמַיָא דִי אֲנָא מַסְהֵד בְּכוֹן יוֹמָא דֵין דִי תְפַקְדִנוּן יָת בְּנֵיכוֹן לְמִטַר לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@910 אֲרֵי לָא פִתְגָם רֵקָא הוּא מִנְכוֹן אֲרֵי הוּא חַיֵיכוֹן וּבְפִתְגָמָא הָדֵין תּוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא תַּמָן לְמֵירְתַהּ:
@911 וּמַלִיל יְיָ עִם מֹשֶׁה בִּכְרַן יוֹמָא הָדֵין לְמֵימָר:
@912 סַק לְטוּרָא דַעֲבָרָאֵי הָדֵין טוּרָא דִנְבוֹ דִי בְּאַרְעָא דְמוֹאָב דִי עַל אַפֵּי יְרֵחוֹ וַחֲזֵי יָת אַרְעָא דִכְנַעַן דִי אֲנָא יָהֵב לִבְנֵי יִשְׂרָאֵל לְאַחֲסָנָא:
@913 וּמוּת בְּטוּרָא דִי אַתְּ סָלֵק לְתַמָן וְתִתְכְּנֵשׁ לְעַמָךְ כְּמָא דְמִית אַהֲרֹן אֲחוּךְ בְּהוֹר טוּרָא וְאִתְכְּנִישׁ לְעַמֵהּ:
@914 עַל דִי שַׁקַרְתּוּן בְּמֵי:מרִי בְּגוֹ בְּנֵי יִשְׂרָאֵל בְּמֵי מַצוּת רְקָם מַדְבְּרָא דְצִין עַל דִי לָא קַדִשְׁתּוּן יָתִי בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@915 אֲרֵי מִקֳבֵל תֶּחֱזֵי יָת אַרְעָא וּלְתַמָן לָא תֵעוּל לְאַרְעָא דִי אֲנָא יָהֵב לִבְנֵי יִשְׂרָאֵל: פפפ:
@916 וְדָא בִרְכְּתָא דִי בְרִיךְ מֹשֶׁה נְבִיָא דַיְיָ יָת בְּנֵי יִשְׂרָאֵל קֳדָם מוֹתֵהּ:
@917 וַאֲמַר יְיָ מִסִינַי אִתְגְלִי וְזֵהוֹר יְקָרֵהּ מִשֵׂעִיר אִתְחֲזֵי לָנָא אִתְגְלִי בִגְבֻרְתֵּהּ מִטוּרָא דְפָארָן וְעִמֵהּ רִבְבַת קַדִישִׁין כְּתַב יַמִינֵהּ מִגוֹ אֶשָׁתָא אוֹרַיְתָא יְהַב לָנָא:
@918 אַף חַבִּיבִנוּן לְשִׁבְטַיָא כָּל קַדִישׁוֹהִי בֵית יִשְׁרָאֵל בִּגְבוּרָא אַפֵּקִנוּן מִמִצְרָיִם וְאִנוּן מִדַבְּרִין תִּחוֹת עֲנָנָךְ נָטִלִין עַל מֵימְרָךְ:
@919 אוֹרַיְתָא יְהַב לָנָא מֹשֶׁה מְסָרַהּ יְרֻתָּא לְכִנְשַׁת יַעֲקֹב:
@920 וַהֲוָה בְיִשְׂרָאֵל מַלְכָּא בְּאִתְכַּנָשׁוּת רֵישֵׁי עַמָא כַּחֲדָא שִׁבְטַיָא דְיִשְׂרָאֵל:
@921 יְחִי רְאוּבֵן לְחַיֵי עַלְמָא וּמוֹתָא תִנְיָנָא לָא יְמוּת וִיקַבְּלוּן בְּנוֹהִי אַחֲסַנְתְּהוֹן בְּמִנְיָנְהוֹן:
@922 וְדָא לִיהוּדָה וַאֲמַר קַבֵּל יְיָ צְלוֹתֵהּ דִיהוּדָא בְּמִפְּקֵהּ לְאַגָחָא קְרָבָא וּלְעַמֵהּ תָּתֵיבִנֵהּ לִשְׁלָם יְדוֹהִי יַעְבְּדָן לֵהּ פֻּרְעֲנוּתָא מִסָנְאוֹהִי וְסָעִיד מִבַּעֲלֵי דְבָבוֹהִי הֲוֵי לֵהּ:
@923 וּלְלֵוִי אֲמַר תּוּמַיָא וְאוּרַיָא אַלְבֶּשְׁתָּא לִגְבַר דְאִשְׁתְּכַח חֲסִידָא קֳדָמָךְ דִי נַסִיתוֹהִי בְּנִסֵתָא וַהֲוָה שְׁלִים בְּחַנְתּוֹהִי עַל מֵי מַצוּתָא וְאִשְׁתְּכַח מְהֵימָן:
@924 דְעַל אֲבוֹהִי וְעַל אִמֵהּ לָא רַחֵם כַּד חָבוּ מִן דִינָא וְאַפֵּי אֲחוֹהִי וּבְנוֹהִי לָא נְסִיב אֲרֵי נְטָרוּ מַטְרַת מֵימְרָךְ וּקְיָמָךְ לָא אַשְׁנִיוּ:
@925 כָּשְׁרִין אִלֵין דְיַלְפוּן דִינָיךְ לְיַעֲקֹב וְאוֹרַיְתָךְ לְיִשְׂרָאֵל יְשַׁוּוּן קְטוֹרֶת בּוּסְמִין קֳדָמָךְ וּגְמִיר לְרַעֲוָא עַל מַדְבְּחָךְ:
@926 בָּרֵךְ יְיָ נִכְסוֹהִי וְקוּרְבַּן יְדוֹהִי תְּקַבֵּל בְּרַעֲוָא תְּבַר חַרְצָא דְסָנְאוֹהִי וּדְבֵעֲלֵי דְבָבוֹהִי דְלָא יְקוּמוּן:
@927 לְבִנְיָמִן אֲמַר רְחִימָא דַיְיָ יִשְׁרֵי לְרָחְצַן עֲלוֹהִי יְהֵי מָגֵן עֲלוֹהִי כָּל יוֹמַיָא וּבְאַרְעֵהּ תִּשְׁרֵי שְׁכִנְתָּא:
@928 וּלְיוֹסֵף אֲמַר מְבָרָכָא מִן קֳדָם יְיָ אַרְעֵהּ עָבְדָא מִגְדָנִין מִטַלָא דִשְׁמַיָא מִלְעֵלָא וּמִמַבּוּעֵי עֵינָוָן וּתְהוֹמִין דְנָגְדָן מִמַעֲמַקֵי אַרְעָא מִלְרָע:
@929 וְעָבְדָא מִגְדָנִין וַעֲלָלָן מִיבוּל שִׁמְשָׁא וְעָבְדָא מִגְדָנִין מֵרֵישׁ יְרַח בִּירַח:
@930 וּמֵרֵיש טוּרַיָא בַכִּירַיָא וּמִטוּב רָמָן דְלָא פָסְקָן:
@931 וּמִטוּב אַרְעָא וּמָלָאַהּ וְרָעֵי לֵהּ דִשְׁכִנְתֵּהּ בִּשְׁמַיָא וְעַל מֹשֶׁה אִתְגְלִי בַאֲסָנָא יֵיתוּן כָּל אִלֵין לְרֵישָׁא דְיוֹסֵף וּלְגַבְרָא פָּרִישָׁא דַאֲחוֹהִי:
@932 רַבָּא דִבְנוֹהִי זִיוָא לֵהּ וּגְבוּרָן דְאִתְעֲבִידָא לֵהּ מִקֳדָם דְתוּקְפָא וְרוּמָא דִילֵהּ בִּגְבֻרְתֵּהּ עַמְמַיָא יִקְטֵל כַּחֲדָא עַד סְיָפֵי אַרְעָא וְאִנוּן רִבְוָתָא דְבֵית אֶפְרַיִם וְאִנוּן אַלְפַיָא דְבֵית מְנַשֶׁה:
@933 וְלִזְבוּלֻן אֲמַר חֲדֵי זְבוּלֻן בְּמִפְּקָךְ לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִשָׂשׂכָר בִּמְהָכָךְ לְמֶעְבַּד זִמְנֵי מוֹעֲדַיָא בִּירוּשְׁלֵם:
@934 שִׁבְטַּיָא דְיִשְׂרָאֵל לְטוּר בֵּית מַקְדְשָׁא יִתְכַּנְשׁוּן תַּמָן יִכְסוּן נִכְסַת קוּדְשִׁין לְרַעֲוָא אֲרֵי נִכְסֵי עַמְמַיָא יֵיכְלוּן וְסִימָא דְמִטַמְרָא בְחָלָא מִתְגַלְיָא לְהוֹן:
@935 וּלְגָד אֲמַר בְּרִיךְ דְאַפְתֵּי לְגָד כְּלֵיתָא שָׁרֵי וְיִקְטוֹל שִׁלְטוֹנִין עִם מַלְכִין:
@936 וְאִתְקַבֵּל בְּקַדְמֵתָא דִילֵהּ אֲרֵי תַמָן בְּאַחֲסַנְתֵּהּ מֹשֶׁה סָפְרָא רַבָּא דְיִשְׂרָאֵל קְבִיר וְהוּא נָפֵק וְעַל בְּרֵישׁ עַמָא זַכְוָן קֳדָם יְיָ עֲבַד וְדִינוֹהִי עִם יִשְׂרָאֵל:
@937 וּלְדָן אֲמַר דָן תַּקִיף כְּגוּר אַרְיְוָן אַרְעֵהּ שָׁתְיָא מִן נַחֲלַיָא דְנָגְדָן מִן מַתְנָן:
@938 וּלְנַפְתָּלִי אֲמַר נַפְתָּלִי שְׂבַע רַעֲוָא וּמְלֵי בִּרְכָן מִן קֳדָם יְיָ מַעֲרָב יָם גִנוֹסַר וְדָרוֹמָא יֵרָת:
@939 וּלְאָשֵׁר אֲמַר בְּרִיךְ מִבִּרְכַּת בְּנַיָא אָשֵׁר יְהֵי רַעֲוָא לְאַחוֹהִי וְיִתְרַבֵּי בְּתַפְנוּקֵי מַלְכִין:
@940 תַּקִיף כְּפַרְזְלָא וּנְחָשָׁא מוֹתָבָךְ וּכְיוֹמֵי עוּלֵמָתָךְ תָּקְפָּךְ:
@941 לֵית אֱלָהּ כֶּאֱלָהָא דְיִשְׂרָאֵל דִשְׁכִנְתֵּהּ בִּשְׁמַ יָא בְּסַעְדָךְ וְתָקְפֵּהּ בִּשְׁמֵי שְׁמַיָא:
@942 מְדוֹר אֱלָהָא דִי מִלְקַדְמִין בְּמֵימְרֵהּ אִתְעֲבֵד עָלְמָא וְתָרִיךְ מִקֳדָמָךְ סָנְאָה וַאֲמַר שֵׁצִי:
@943 וּשְׁרָא יִשְׂרָאֵל לְרָחְצָן בִּלְחוֹדוֹהִי כְּעֵין בִּרְכְּתָא דְבָרֵכִנוּן יַעֲקֹב אֲבוּהוֹן לְאַרְעָא עָבְדָא עִבוּר וַחֲמָר אַף שְׁמַיָא דְעִלָוֵיהוֹן יְשַׁ מְשֻׁנוּן בְּטַלָא:
@944 טוּבָּךְ יִשְׂרָאֵל לֵית דִכְוָתָךְ עַמָא דְפֻרְקָנֵהּ מִן קֳדָם יְיָ תַּקִיף בְּסַעְדָךְ וּדְמִן קֳדָמוֹהִי נִצְחָן גִבַּרְוָתָךְ וִיכַדְבוּן סָנְאָךְ לָךְ וְאַתְּ עַל פְּרִיקַת צַוָארֵי מַלְכֵיהוֹן תִּדְרֹךְ:
@945 וּסְלֵיק מֹשֶׁה מִמֵישְׁרָא דְמוֹאָב לְטוּרָא דִנְבוֹ רֵישׁ רָמָתָא דִי עַל אַפֵּי יְרֵחוֹ וְאַחְזְיֵהּ יְיָ יָת כָּל אַרְעָא יָת גִלְעָד עַד דָן:
@946 וְיָת כָּל נַפְתָּלִי וְיָת אַרְעָא דְאֶפְרַיִם וּמְנַשֶׁה וְיָת כָּל אַרְעָא דִיהוּדָה עַד יַמָא מַעַרְבָא:
@947 וְיָת דָרוֹמָא וְיָת מֵישְׁרָא בִּקְעֲתָא דִירֵחוֹ קַרְתָּא דְדִקְלַיָא עַד צוֹעַר:
@948 וַאֲמַר יְיָ לֵהּ דָא אַרְעָא דִי קַיֵמִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמֵימָר לִבְנָיךְ אֶתְּנִנַהּ אַחֲזִיתָךְ בְּעֵינָיךְ וּלְתַמָן לָא תְעִבַּר:
@949 וּמִית תַּמָן מֹשֶׁה עַבְדָא דַיְיָ בְּאַרְעָא דְמוֹאָב עַל מֵימְרָא דַיְיָ:
@950 וּקְבַר יָתֵהּ בְּחֵילָתָא בְּאַרְעָא דְמוֹאָב לְקֳבֵל בֵּית פְּעוֹר וְלָא יְדַע אֱנַשׁ יָת קְבֻרְתֵּה עַד יוֹמָא הָדֵין:
@951 וּמֹשֶׁה בַּר מְאָה וְעַשְׂרִין שְׁנִין כַּד מִית לָא כְהַת עֵינוֹהִי וְלָא שְׁנָא זִיו יְקָרָא דְאַפּוֹהִי:
@952 וּבְכוֹ בְנֵי יִשְׂרָאֵל יָת מֹשֶׁה בְּמֵישְׁרַיָא דְמוֹאָב תְּלָתִין יוֹמִין וּשְׁלִימוּ יוֹמֵי בָכִיתָא אֶבְלָא דְמֹשֶׁה:
@953 וִיהוֹשֻׁעַ בַּר נוּן מְלֵי רוּחַ חָכְמְתָא אֲרֵי סְמַךְ מֹשֶׁה יָת יְדוֹהִי עֲלוֹהִי וְקַבִּילוּ מִנֵהּ בְּנֵי יִשְׂרָאֵל וַעֲבָדוּ כְּמָא דִי פַּקִיד יְיָ יָת מֹשֶׁה:
@954 וְלָא קָם נְבִיָא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה דִי אִתְגְלִי לֵהּ יְיָ אַפִּין בְּאַפִּין:
@955 לְכָל אָתַיָא וּמוֹפְתַיָא דִי שָׁלְחֵהּ יְיָ לְמֶעְבַּד בְּאַרְעָא דְמִצְרָיִם לְפַרְעֹה וּלְכָל עַבְדוֹהִי וּלְכָל אַרְעֵהּ:
@956 וּלְכֹל יְדָא תַקֶפְתָּא וּלְכֹל חֵזְוָנָא רַבָּא דִי עֲבַד מֹשֶׁה לְעֵינֵי כָּל יִשְׂרָאֵל: חזק:

@1 **אלה הדברים.** לפי שהן דברי תוכחות ומנה כאן כל המקומות שהכעיסו לפני המקום בהן, לפיכך סתם את הדברים והזכירם ברמז מפני כבודן של ישראל: **אל כל ישראל.** אלו הוכיח מקצתן, היו אלו שבשוק אומרים, אתם הייתם שומעים מבן עמרם ולא השיבותם דבר מכך וכך, אלו היינו שם היינו משיבים אותו, לכך כנסם כלם ואמר להם הרי כלכם כאן כל מי שיש לו תשובה ישיב: **במדבר.** לא במדבר היו אלא בערבות מואב, ומהו במדבר, אלא בשביל מה שהכעיסוהו במדבר שאמרו (שמות טז, ג) מי יתן מותנו וגו' : **בערבה.** בשביל הערבה שחטאו בבעל פעור בשטים בערבות מואב: **מול סוף.** על מה שהמרו בים סוף בבואם לים סוף שאמרו (שם יד, יא) המבלי אין קברים במצרים, וכן בנסעם מתוך הים, שנאמר (תהלים קו, ז) וימרו על ים בים סוף, כדאיתא בערכין (טו, א) : **בין פארן ובין תפל ולבן.** אמר רבי יוחנן [רשב''י] חזרנו על כל המקרא ולא מצינו מקום ששמו תפל ולבן, אלא הוכיחן על הדברים שתפלו על המן שהוא לבן, שאמרו (במדבר כא, ה) ונפשנו קצה בלחם הקלקל ועל מה שעשו במדבר פארן על ידי המרגלים: **וחצרות.** במחלקתו של קרח. דבר אחר אמר להם, היה לכם ללמוד ממה שעשיתי למרים בחצרות בשביל לשון הרע, ואתם נדברתם במקום: **ודי זהב.** הוכיחן על העגל שעשו בשביל רב זהב שהיה להם, שנאמר (הושע ב, י) וכסף הרביתי לה וזהב עשו לבעל:
@2 **אחד עשר יום מחרב.** אמר להם משה ראו מה גרמתם, אין לכם דרך קצרה מחורב לקדש ברנע כדרך הר שעיר ואף הוא מהלך אחד עשר יום, ואתם הלכתם אותו בשלשה ימים, שהרי בעשרים באיר נסעו מחורב שנאמר (במדבר י, יא) ויהי בשנה השנית בחדש השני בעשרים בחדש וגו' ובעשרים ותשעה בסיון שלחו את המרגלים מקדש ברנע, צא מהם שלשים יום שעשו בקברות התאוה, שאכלו הבשר חדש ימים, ושבעה ימים שעשו בחצרות להסגר שם מרים, נמצא בשלשה ימים הלכו כל אותו הדרך, וכל כך היתה שכינה מתלבטת בשבילכם למהר ביאתכם לארץ, ובשביל שקלקלתם הסב אתכם סביבות הר שעיר ארבעים שנה:
@3 **ויהי בארבעים שנה בעשתי עשר חדש באחד לחדש.** מלמד שלא הוכיחן אלא סמוך למיתה. ממי למד, מיעקב שלא הוכיח את בניו אלא סמוך למיתה. אמר, ראובן בני, אני אומר לך מפני מה לא הוכחתיך כל השנים הללו, כדי שלא תניחני ותלך ותדבק בעשו אחי. ומפני ארבעה דברים אין מוכיחין את האדם אלא סמוך למיתה, כדי שלא יהא מוכיחו וחוזר ומוכיחו, ושלא יהא חברו רואהו ומתבייש ממנו וכו' כדאיתא בספרי. וכן יהושע לא הוכיח את ישראל אלא סמוך למיתה, וכן שמואל, שנאמר (ש''א יב, ג) הנני ענו בי. וכן דוד את שלמה בנו:
@4 **אחרי הכתו.** אמר משה אם אני מוכיחם קודם שיכנסו לקצת הארץ, יאמרו מה לזה עלינו, מה היטיב לנו, אינו בא אלא לקנתר ולמצא עלה שאין בו כח להכניסנו לארץ, לפיכך המתין עד שהפיל סיחון ועוג לפניהם והורישם את ארצם ואחר כך הוכיחן: **סיחן** וגו' **אשר יושב** וגו' **.** אלו לא היה סיחון קשה והיה שרוי בחשבון, היה קשה, שהמדינה קשה, ואלו היתה עיר אחרת וסיחון שרוי בתוכה היתה קשה, שהמלך קשה, על אחת כמה וכמה שהמלך קשה והמדינה קשה: **אשר יושב בעשתרת.** המלך קשה והמדינה קשה: **עשתרת.** הוא לשון צוקין וקושי כמו (בראשית יד, ה) עשתרות קרנים, ועשתרות זה הוא עשתרות קרנים שהיו שם רפאים שהכה אמרפל, שנאמר (בראשית יד, ה) ויכו את רפאים בעשתרות קרנים, ועוג נמלט מהם והוא שנאמר (שם יד, יג) ויבא הפליט, ואומר (דברים ג, יא) כי רק עוג מלך הבשן נשאר מיתר הרפאים: **באדרעי.** שם המלכות:
@5 **הואיל.** התחיל כמו (בראשית יח, כז) הנה נא הואלתי: **באר את התורה.** בשבעים לשון פרשה להם:
@6 **רב לכם שבת.** כפשוטו. ויש מדרש אגדה הרבה לכם גדלה ושכר על ישיבתכם בהר הזה, עשיתם משכן מנורה וכלים, קבלתם תורה, מניתם לכם סנהדרין, שרי אלפים ושרי מאות:
@7 **פנו וסעו לכם.** זו דרך ערד וחרמה: **ובאו הר האמרי.** כמשמעו: **ואל כל שכניו.** עמון ומואב והר שעיר: **בערבה.** זה מישור של יער: **בהר.** זה הר המלך: **ובשפלה.** זו שפלת דרום: **ובנגב ובחוף הים.** אשקלון ועזה וקסרי וכו' כדאיתא בספרי: **עד הנהר הגדל.** מפני שנזכר עם ארץ ישראל, קראו גדול. משל הדיוט אומר עבד מלך מלך, הדבק לשחור וישתחוו לך, קרב לגבי דהנא ואדהן:
@8 **ראה נתתי.** בעיניכם אתם רואים. איני אומר לכם מאומד ומשמועה: **באו ורשו.** אין מערער בדבר ואינכם צריכים למלחמה, אלו לא שלחו מרגלים לא היו צריכים לכלי זין: **לאבתיכם.** למה הזכיר שוב לאברהם ליצחק וליעקב, אלא אברהם כדאי לעצמו, יצחק כדאי לעצמו, יעקב כדאי לעצמו:
@9 **ואמר אליכם בעת ההוא לאמר.** מהו לאמר, אמר להם משה, לא מעצמי אני אומר לכם, אלא מפי הקדוש ברוך הוא: **לא אוכל לבדי** וגו' **.** אפשר שלא היה משה יכול לדון את ישראל, אדם שהוציאם ממצרים וקרע להם את הים והוריד את המן והגיז את השלו לא היה יכול לדונם, אלא כך אמר להם, ה' אלהיכם הרבה אתכם, הגדיל והרים אתכם על דיניכם נטל את הענש מכם ונתנו על הדינין. וכן אמר שלמה (מלכים א' ג, ט) כי מי יוכל לשפט את עמך הכבד הזה, אפשר מי שכתוב בו (שם ה, יא) ויחכם מכל האדם, אומר מי יוכל לשפט, אלא כך אמר שלמה אין דיני אמה זו כדיני שאר האמות, שאם דן והרג ומכה וחונק ומטה את דינו וגוזל אין בכך כלום, אני אם חיבתי ממון שלא כדין, נפשות אני נתבע, שנאמר (משלי כב, כג) וקבע את קבעיהם נפש:
@10 **והנכם היום ככוכבי השמים.** וכי ככוכבי השמים היו באותו היום, והלא לא היו אלא ששים רבוא, מהו והנכם היום, הנכם משולים כיום, קימים כחמה וכלבנה וככוכבים:
@11 **יסף עליכם ככם אלף פעמים.** מהו שוב ויברך אתכם כאשר דבר לכם, אלא אמרו לו משה אתה נותן קצבה לברכתנו, כבר הבטיח הקדוש ברוך הוא את אברהם (בראשית יג, טז) אשר אם יוכל איש למנות וגו' , אמר להם זו משלי היא, אבל הוא יברך אתכם כאשר דבר לכם:
@12 **איכה אשא לבדי.** אם אומר לקבל שכר לא אוכל, זו היא שאמרתי לכם לא מעצמי אני אומר לכם, אלא מפי הקדוש ברוך הוא: **טרחכם.** מלמד שהיו ישראל טרחנין. היה אחד מהם רואה את בעל דינו נוצח בדין, אומר יש לי עדים להביא, יש לי ראיות להביא, מוסיף אני עליכם דינין: **ומשאכם.** מלמד שהיו אפיקורוסין. הקדים משה לצאת, אמרו, מה ראה בן עמרם לצאת, שמא אינו שפוי בתוך ביתו. אחר לצאת, אמרו, מה ראה בן עמרם שלא לצאת, מה אתם סבורים, יושב ויועץ עליכם עצות רעות וחושב עליכם מחשבות: **וריבכם.** מלמד שהיו רוגנים:
@13 **הבו לכם.** הזמינו עצמכם לדבר: **אנשים.** וכי תעלה על דעתך נשים, מה תלמוד לומר אנשים, צדיקים כסופים: **נבונים.** מבינים דבר מתוך דבר. זו היא ששאל אריוס את רבי יוסי, מה בין חכמים לנבונים. חכם דומה לשלחני עשיר, כשמביאין לו דינרין לראות רואה, וכשאין מביאין לו יושב ותוהא. נבון דומה לשלחני תגר, כשמביאין לו מעות לראות רואה, וכשאין מביאין לו מחזר ומביא משלו: **וידעים לשבטיכם.** שהם נכרים לכם, שאם בא לפני מעטף בטליתו איני יודע מי הוא ומאיזה שבט הוא ואם הגון הוא, אבל אתם מכירין בו, שאתם גדלתם אותו, לכך נאמר וידעים לשבטיכם: **בראשיכם.** ראשים ומכבדים עליכם שתהיו נוהגין בהם כבוד ויראה: **ואשימם.** חסר יו''ד, [לומר] למד שאשמותיהם של ישראל תלויות בראשי דיניהם, שהיה להם למחות ולכון אותם לדרך הישרה:
@14 **ותענו אתי** וגו' **.** החלטתם את הדבר להנאתכם, היה לכם להשיב, רבנו משה ממי נאה ללמוד ממך או מתלמידך לא ממך שנצטערת עליה. אלא ידעתי מחשבותיכם. הייתם אומרים, עכשיו יתמנו עלינו דינין הרבה, אם אין מכירנו אנו מביאין לו דורון והוא נושא לנו פנים: **לעשות.** אם הייתי מתעצל, אתם אומרים עשה מהרה:
@15 **ואקח את ראשי שבטיכם.** משכתים בדברים, אשריכם, על מי באתם להתמנות, על בני אברהם יצחק ויעקב, על בני אדם שנקראו אחים ורעים, חלק ונחלה וכל לשון חבה: **אנשים חכמים וידעים.** אבל נבונים לא מצאתי. זו אחת משבע מדות שאמר יתרו למשה ולא מצא אלא שלש, אנשים צדיקים, חכמים וידעים: **ראשים עליכם.** שתנהגו בהם כבוד. ראשים במקח, ראשים בממכר, ראשים במשא ומתן, נכנס אחרון ויוצא ראשון: **שרי אלפים.** אחד ממנה על אלף: **שרי מאות.** אחד ממנה על מאה: **ושטרים.** מניתי עליכם לשבטיכם. אלו הכופתין והמכין ברצועה על פי הדינין:
@16 **ואצוה את שפטיכם.** אמרתי להם הוו מתונים בדין, אם בא דין לפניך פעם אחת שתים ושלש אל תאמר כבר בא דין זה לפני פעמים הרבה אלא היו נושאים ונותנים בו: **בעת ההוא.** משמניתים אמרתי להם, אין עכשיו כלשעבר, לשעבר הייתם ברשות עצמכם, עכשיו הרי אתם משעבדים לצבור: **שמע.** לשון הוה [בהאזינכם] כמו (שמות כ, ז) זכור, (דברים ה, יא) שמור: **ובין גרו.** זה בעל דינו, שאוגר עליו דברים. דבר אחר ובין גרו, אף על עסקי דירה בין חלקת אחים אפלו בין תנור לכירים:
@17 **לא תכירו פנים במשפט.** זה הממנה להושיב הדינין, שלא יאמר איש פלוני נאה או גבור, אושיבנו דין, איש פלוני קרובי, אושיבנו דין בעיר, והוא אינו בקי בדינין נמצא מחיב את הזכאי ומזכה את החיב. מעלה אני על מי שמנהו כאלו הכיר פנים בדין: **כקטן כגדל תשמעון.** שיהא חביב עליך דין של פרוטה כדין של מאה מנה, שאם קדם ובא לפניך לא תסלקנו לאחרון [לאחריו] . דבר אחר כקטן כגדל תשמעון, כתרגומו, שלא תאמר, זה עני הוא וחברו עשיר ומצוה לפרנסו אזכה את העני ונמצא מתפרנס בנקיות. דבר אחר שלא תאמר היאך אני פוגם כבודו של עשיר זה בשביל דינר, אזכנו עכשיו, וכשיצא לחוץ אומר אני לו, תן לו שאתה חיב לו: **לא תגורו מפני איש.** לא תיראו. דבר אחר לא תגורו, לא תכניס דבריך מפני איש. לשון (משלי י, ה) אוגר בקיץ: **כי המשפט לאלהים הוא.** מה שאתה נוטל מזה שלא כדין, אתה מזקיקני להחזיר לו, נמצא שהטית עלי המשפט: **תקרבון אלי.** על דבר זה נסתלק ממנו משפט בנות צלפחד, וכן שמואל אמר לשאול (שמואל א' ט, יט) אנכי הראה, אמר לו הקדוש ברוך הוא, חייך שאני מודיעך שאין אתה רואה. ואימתי הודיעו, כשבא למשוח את דוד (שם טז, ו) וירא את אליאב ויאמר אך נגד ה' משיחו, אמר לו הקדוש ברוך הוא, ולא אמרת אנכי הראה (שם טז, ז) אל תבט אל מראהו:
@18 **את כל הדברים אשר תעשון.** אלו עשרת הדברים שבין דיני ממונות לדיני נפשות:
@19 **המדבר הגדול והנורא.** שהיו בו נחשים כקורות, ועקרבים כקשתות:
@22 **ותקרבון אלי כלכם.** בערבוביא, ולהלן הוא אומר (דברים ה, כ. כא) ותקרבון אלי כל ראשי שבטיכם וזקניכם ותאמרו הן הראנו וגו' , אותה קריבה היתה הוגנת. ילדים מכבדים את הזקנים ושלחום לפניהם, וזקנים מכבדים את הראשים ללכת לפניהם, אבל כאן, ותקרבון אלי כלכם, בערבוביא. ילדים דוחפין את הזקנים וזקנים דוחפין את הראשים: **וישבו אתנו דבר.** באיזה לשון הם מדברים: **את הדרך אשר נעלה בה.** אין דרך שאין בה עקמימות: **ואת הערים אשר נבא אליהן.** תחלה לכבוש:
@23 **וייטב בעיני הדבר.** בעיני ולא בעיני המקום. ואם בעיני משה היה טוב למה אמרה בתוכחות, משל לאדם שאומר לחברו מכור לי חמורך זה, אמר לו הן. נותנו אתה לי לנסיון, אמר לו הן. בהרים וגבעות, אמר לו הן. כיון שראה שאין מעכבו כלום, אמר הלוקח בלבו, בטוח הוא זה שלא אמצא בו מום. מיד אמר לו טול מעותיך ואיני מנסהו. מעתה אף אני הודיתי לדבריכם, שמא תחזרו בכם כשתראו שאיני מעכב, ואתם לא חזרתם בכם: **ואקח מכם.** מן הברורים שבכם מן המסלתים שבכם: **שנים עשר אנשים איש אחד לשבט.** מגיד שלא היה שבט לוי עמהם:
@24 **עד נחל אשכל.** מגיד שנקרא על שם סופו: **וירגלו אתה.** מלמד שהלכו בה ארבעה אומנין שתי וערב:
@25 **ויורדו אלינו.** מגיד שארץ ישראל גבוהה מכל הארצות: **ויאמרו טובה הארץ.** מי הם שאמרו טובתה, יהושע וכלב:
@26 **ותמרו.** לשון התרסה, התרסתם כנגד מאמרו:
@27 **ותרגנו.** לשון הרע, וכן (משלי יח, ח) דברי נרגן, אדם המוציא דבה: **בשנאת ה' אתנו.** והוא היה אוהב אתכם, אבל אתם שונאים אותו. משל הדיוט אומר, מה דבלבך על רחמך מה דבלביה עלך: **בשנאת ה' אתנו הוציאנו מארץ מצרים.** הוצאתו לשנאה היתה. משל למלך בשר ודם, שהיו לו שני בנים ויש לו שתי שדות אחת של שקיא ואחת של בעל, למי שהוא אוהב נותן של שקיא, ולמי שהוא שונא נותן לו של בעל. ארץ מצרים של שקיא היא, שנילוס עולה ומשקה אותה, וארץ כנען של בעל, והוציאנו ממצרים לתת לנו את ארץ כנען:
@28 **ערים גדלת ובצורת בשמים.** דברו הכתובים לשון הבאי:
@29 **לא תערצון.** לשון שבירה כתרגומו, ודומה לו (איוב ל, ו) בערוץ נחלים לשכן, לשבור נחלים:
@30 **ילחם לכם.** בשבילכם:
@31 **ובמדבר אשר ראית.** מוסב על מקרא שלמעלה המנו (פסוק ל) , ככל אשר עשה אתכם במצרים, ועשה אף במדבר אשר ראית אשר נשאך וגו' : **כאשר ישא איש את בנו.** כמו שפירשתי אצל (שמות יד, יט) ויסע מלאך האלהים ההולך לפני מחנה ישראל וגו' . משל למהלך בדרך ובנו לפניו באו לסטים לשבותו וכו' :
@32 **ובדבר הזה.** שהוא מבטיחכם להביאכם אל הארץ, אינכם מאמינים בו:
@33 **לראותכם.** כמו להראותכם. וכן (שמות יג, כא) לנחותם הדרך, וכן (תהלים כו, ז) לשמע בקול תודה, וכן (מלכים ב' ט, טו) ללכת לגיד [להגיד] ביזרעאל (לגיד כתיב, להגיד קרי) :
@36 **אשר דרך בה.** חברון, שנאמר (במדבר יג, כב) ויבא עד חברון:
@37 **התאנף.** נתמלא רוגז:
@40 **פנו לכם.** אמרתי להעביר אתכם דרך רוחב ארץ אדום לצד צפון לכנס לארץ, קלקלתם וגרמתם לכם עכוב: **פנו לכם.** לאחוריכם ותלכו במדבר לצד ים סוף. שהמדבר שהיו הולכים בו לדרומו של הר שעיר, היה מפסיק בין ים סוף להר שעיר, עתה המשכו לצד הים ותסבבו את הר שעיר כל דרומו מן המערב למזרח:
@41 **ותהינו.** לשון (במדבר יד, מ) הננו ועלינו אל המקום, זה הלשון שאמרתם, לשון הן, כלומר נזדמנתם:
@42 **לא תעלו.** לא עליה תהא לכם, אלא ירידה:
@44 **כאשר תעשינה הדברים.** מה הדבורה הזאת כשהיא מכה את האדם מיד מתה, אף הם כשהיו נוגעים בכם מיד מתים:
@45 **ולא שמע ה' בקלכם.** כביכול עשיתם מדת רחמיו, כאלו אכזרי:
@46 **ותשבו בקדש ימים רבים.** תשע עשרה שנה, שנאמר כימים אשר ישבתם בשאר המסעות והם היו שלשים ושמנה שנה, תשע עשרה מהם עשו בקדש ותשע עשרה שנה הולכים ומטורפים וחזרו לקדש, כמו שנאמר (במדבר לב, יג) ויניעם במדבר. כך מצאתי בסדר עולם:
@47 **ונפן ונסע המדברה.** אלו לא חטאו היו עוברים דרך הר שעיר לכנס לארץ מן דרומו לצפונו, ובשביל שקלקלו הפכו לצד המדבר שהוא בין ים סוף לדרומו של הר שעיר, והלכו אצל דרומו מן המערב למזרח דרך ים סוף. דרך יציאתן ממצרים שהוא במקצוע דרומית מערבית, משם היו הולכים לצד המזרח: **ונסב את הר שעיר.** כל דרומו עד ארץ מואב:
@49 **פנו לכם צפנה.** סובו לכם לרוח מזרחית מן הדרום לצפון, ופניכם לצפון, נמצאו הולכין את רוח מזרחית. וזהו שנאמר (שופטים יא, יח) ויבא ממזרח שמש לארץ מואב:
@50 **ונשמרתם מאד.** ומהו השמירה, (פסוק ה) אל תתגרו בם:
@51 **עד מדרך כף רגל.** אפלו מדרך כף רגל, כלומר אפלו דריסת הרגל איני מרשה לכם לעבור בארצם שלא ברשות. ומדרשי אגדה, עד שיבא יום דריסת כף רגל על הר הזיתים שנאמר (זכריה יד, ד) ועמדו רגליו וגו' : **ירשה לעשו.** מאברהם, עשרה עממים נתתי לו, שבעה לכם וקיני וקנזי וקדמוני הן עמון ומואב ושעיר, אחד מהם לעשו והשנים לבני לוט, בשכר שהלך אתו למצרים ושתק על מה שהיה אומר על אשתו, אחותי היא, עשאו כבנו:
@52 **תכרו.** לשון מקח. וכן (בראשית נ, ה) אשר כריתי לי, שכן בכרכי הים קורין למכירה כירה:
@53 **כי ה' אלהיך ברכך.** לפיכך לא תכפו את טובתו להראות כאלו אתם עניים, אלא הראו עצמכם עשירים:
@54 **ונפן ונעבר.** לצד צפון, הפכנו פנים להלוך רוח מזרחית:
@55 **ואל תתגר** וגו' **.** לא אסר להם על מואב אלא מלחמה, אבל מיראים היו אותם ונראים להם כשהם מזינים, לפיכך כתיב (במדבר כב, ג) ויגר מואב מפני העם שהיו שוללים ובוזזים אותם. אבל בבני עמון נאמר (פסוק יט) ואל תתגר בם, שום גרוי, בשכר צניעות אמם שלא פרסמה על אביה כמו שעשתה הבכירה, שקראה שם בנה, מואב: **ער.** שם המדינה:
@56 **האמים לפנים** וגו' **.** אתה סבור שזו ארץ רפאים שנתתי לו לאברהם לפי שהאמים שהם רפאים ישבו בה לפנים, אבל לא זו היא כי אותם רפאים הורשתי מפני בני לוט והושבתים תחתם:
@57 **רפאים יחשבו** וגו' **.** רפאים היו נחשבים אותם אמים כענקים הנקראים רפאים על שם שכל הרואה אותם ידיו מתרפות: **אמים.** על שם שאימתם מטלת על הבריות, וכן (פסוק יב) ובשעיר ישבו החרים ונתתים לבני עשו:
@58 **יירשום.** לשון הוה, כלומר נתתי בהם כח שהיו מורישים אותם והולכים:
@61 **היתה בם.** למהר ולהמם בתוך ארבעים שנה שלא יגרמו לבניהם עוד להתעכב במדבר:
@63 **ויהי כאשר תמו** וגו' **. וידבר ה' אלי** וגו' **.** אבל משלוח המרגלים עד כאן לא נאמר בפרשה זו, וידבר, אלא ויאמר, ללמדך, שכל שלשים ושמנה שנה שהיו ישראל נזופים לא נתיחד עמו הדבור בלשון חבה פנים אל פנים וישוב הדעת, ללמדך, שאין השכינה שורה על הנביאים אלא בשביל ישראל: **אנשי המלחמה.** מבן עשרים שנה היוצאים בצבא:
@65 **אתה עבר היום את גבול מואב** וגו' **וקרבת מול בני עמון** וגו' **.** מכאן שארץ עמון לצד צפון:
@66 **ארץ רפאים תחשב.** ארץ רפאים נחשבת אף היא לפי שהרפאים ישבו בה לפנים, אבל לא זו היא שנתתי לאברהם:
@69 **והעוים היושבים בחצרים** וגו' **.** עוים מפלשתים הם, שעמהם הם נחשבים בספר יהושע, שנאמר (יהושע יג, ג) חמשת סרני פלשתים העזתי והאשדודי האשקלוני הגתי והעקרוני והעוים. ומפני השבועה שנשבע אברהם לאבימלך לא יכלו ישראל להוציא ארצם מידם, והבאתי עליהם כפתורים והשמידום וישבו תחתם, ועכשיו אתם מתרים לקחתה מידם:
@71 **תחת כל השמים.** למד שעמדה חמה למשה ביום מלחמת עוג ונודע הדבר תחת כל השמים:
@72 **ממדבר קדמות.** אף על פי שלא צוני המקום לקרא לסיחון לשלום, למדתי ממדבר סיני מן התורה שקדמה לעולם. כשבא הקדוש ברוך הוא לתנה לישראל חזר אותה על עשו וישמעאל, וגלוי לפניו שלא יקבלוה ואף על פי כן פתח להם בשלום, אף אני קדמתי את סיחון בדברי שלום. דבר אחר ממדבר קדמות, ממך למדתי שקדמת לעולמך בדברים. יכול היית לשלוח ברק אחד ולשרוף את המצריים, אלא שלחתני מן המדבר אל פרעה לאמר (שמות ה, א) שלח את עמי, במתון:
@75 **כאשר עשו לי בני עשו.** לא לענין לעבור את ארצם אלא לענין מכר אוכל ומים: **עד אשר אעבר את הירדן.** מוסב על אעברה בארצך:
@77 **החלתי תת לפניך.** כפה שר של אמוריים של מעלה תחת רגליו של משה והדריכו על צוארו:
@78 **ויצא סיחן.** לא שלח בשביל עוג לעזור לו, ללמדך שלא היו צריכים זה לזה:
@79 **ואת בניו.** בנו כתיב, שהיה לו בן גבור כמותו:
@80 **מתם.** אנשים. בבזת סיחון נאמר בזזנו לנו לשון בזה, שהיתה חביבה עליהם ובוזזים איש לו, וכשבאו לבזת עוג כבר היו שבעים ומלאים והיתה בזויה בעיניהם ומקרעין ומשליכין בהמה ובגדים ולא נטלו כי אם כסף וזהב. לכך נאמר (דברים ג, ז) בזונו לנו, לשון בזיון. כך נדרש בספרי בפרשת (במדבר כה, א) וישב ישראל בשטים:
@83 **כל יד נחל יבק.** כל אצל נחל יבוק: **וכל אשר צוה ה' אלהינו.** שלא לכבוש, הנחנו:
@84 **ונפן ונעל.** כל צד צפון הוא עליה:
@85 **אל תירא אתו.** ובסיחון לא הצרך לומר אל תירא אתו, אלא מתירא היה משה שלא תעמוד לו זכות ששמש לאברהם שנאמר (בראשית יד, יג) ויבא הפליט, והוא עוג:
@87 **חבל ארגב.** מתרגמנן בית פלך טרכונא. וראיתי תרגום ירושלמי, במגלת אסתר קורא פלטין טרכונין. למדתי חבל ארגוב הפרכיא, היכל מלך, כלומר שהמלכות נקראת על שמה. וכן את הארגוב דמלכים (מלכים ב' טו, כה) אצל היכל מלך, הרגו פקח בן רמליהו לפקחיה בן מנחם:
@88 **מערי הפרזי.** פרוזות ופתוחות בלא חומה, וכן (זכריה ב, ח) פרזות תשב ירושלם:
@89 **החרם.** לשון הוה [כמו] הלוך וכלות:
@91 **מיד.** מרשות:
@92 **צידנים יקראו לחרמון** וגו' **.** ובמקום אחר הוא אומר (דברים ד, מח) ועד הר שיאון הוא חרמון, הרי לו ארבעה שמות למה הצרכו לכתב, להגיד שבח ארץ ישראל, שהיו ארבע מלכיות מתפארות בכך, זו אומרת על שמי יקרא, וזו אומרת על שמי יקרא: **שניר.** הוא שלג בלשון אשכנז [ שנעע ] ובלשון כנען:
@94 **מיתר הרפאים.** שהרגו אמרפל וחבריו בעשתרות קרנים והוא פלט מן המלחמה שנאמר (בראשית יד, יג) ויבא הפליט זהו עוג: **באמת איש.** באמת עוג:
@95 **ואת הארץ הזאת ירשנו בעת ההוא.** האמורה למעלה, (פסוק ח) מנחל ארנון ועד הר חרמון: **מערער אשר על נחל ארנון.** אינו מחבר לראשו של מקרא אלא לסופו, על נתתי לראובני ולגדי. אבל לענין ירשה עד הר חרמון היה:
@96 **ההוא יקרא ארץ רפאים.** היא אותה שנתתי לאברהם:
@99 **תוך הנחל וגבול.** כל הנחל ועוד מעבר לשפתו, כלומר עד ועד בכלל ויותר מכאן:
@100 **מכנרת.** מעבר הירדן המערבי הוא ונחלת בני גד מעבר הירדן המזרחי, ונפל בגורלם רוחב הירדן כנגדם ועוד מעבר שפתו עד כנרת וזהו שנאמר והירדן וגבול, הירדן ומעבר לו:
@101 **ואצו אתכם.** לבני ראובן ולבני גד היה מדבר: **לפני אחיכם.** הם היו הולכים לפני ישראל למלחמה, לפי שהיו גבורים, ואויבים נופלים לפניהם, שנאמר (דברים לג, כ) וטרף זרוע אף קדקד:
@106 **ואתחנן.** אין חנון בכל מקום אלא לשון מתנת חנם. אף על פי שיש להם לצדיקים לתלות במעשיהם הטובים, אין מבקשים מאת המקום אלא מתנת חנם. לפי שאמר לו (שמות לג, יט) וחנתי את אשר אחן, אמר לו בלשון ואתחנן. דבר אחר זה אחד מעשרה לשונות שנקראת תפלה, כדאיתא בספרי: **בעת ההיא.** לאחר שכבשתי ארץ סיחון ועוג דמיתי שמא התר הנדר: **לאמר.** זה אחד משלשה מקומות שאמר משה לפני המקום איני מניחך עד שתודיעני אם תעשה שאלתי אם לאו:
@107 **ה' אלהים.** רחום בדין: **אתה החלות להראות את עבדך.** פתח להיות עומד ומתפלל, אף על פי שנגזרה גזרה. אמר לו ממך למדתי, שאמרת לי (שמות לב, י) ועתה הניחה לי, וכי תופס הייתי בך, אלא לפתוח פתח, שבי תלוי להתפלל עליהם, כמו כן הייתי סבור לעשות עכשיו: **את גדלך.** זו מדת טובך וכן הוא אומר (במדבר יד, יז) ועתה יגדל נא כח ה': **ואת ידך.** זו ימינך, שהיא פשוטה לכל באי עולם: **החזקה.** שאתה כובש ברחמים את מדת הדין החזקה: **אשר מי אל** וגו' **.** אינך דומה למלך בשר ודם, שיש לו יועצין וסנקתדרין הממחין בידו כשרוצה לעשות חסד ולעבור על מדותיו, אתה אין מי ימחה בידך אם תמחול לי ותבטל גזרתך. ולפי פשוטו אתה החלות להראות את עבדך מלחמת סיחון ועוג, כדכתיב (דברים ב, לא) ראה החלתי תת לפניך, הראני מלחמת שלשים ואחד מלכים:
@108 **אעברה נא.** אין נא אלא לשון בקשה: **ההר הטוב הזה.** זו ירושלים: **והלבנון.** זה בית המקדש:
@109 **ויתעבר ה'.** נתמלא חמה: **למענכם.** בשבילכם, אתם גרמתם לי. וכן הוא אומר (תהלים קו, לב) ויקציפו על מי מריבה וירע למשה בעבורם: **רב לך.** שלא יאמרו הרב כמה קשה והתלמיד כמה סרבן ומפציר. דבר אחר רב לך הרבה מזה שמור לך, רב טוב הצפון לך:
@110 **וראה בעיניך.** בקשת ממני (פסוק כה) ואראה את הארץ הטובה, אני מראה לך את כלה שנאמר (דברים לד, א) ויראהו ה' את כל הארץ:
@111 **וצו את יהושע.** על הטרחות ועל המשאות ועל הריבות: **וחזקהו ואמצהו.** בדבריך, שלא ירך לבו לומר כשם שנענש רבי עליהם כך סופי לענש עליהם, מבטיחו אני כי הוא יעבור והוא ינחיל: **כי הוא יעבר.** אם יעבור לפניהם ינחלו, ואם לאו לא ינחלו. וכן אתה מוצא כששלח מן העם אל העי והוא ישב (יהושע ז, ה) ויכו מהם אנשי העי וגו' (שם ז, י) , וכיון שנפל על פניו אמר לו קום לך. קם לך כתיב, אתה הוא העומד במקומך ומשלח את בני למלחמה, למה זה אתה נפל על פניך, לא כך אמרתי למשה רבך אם הוא עובר, עוברין, ואם לאו, אין עוברין:
@112 **ונשב בגיא** וגו' **.** ונצמדתם לעבודה זרה ואף על פי כן (דברים ד, א) ועתה ישראל שמע אל החקים והכל מחול לך ואני לא זכיתי למחל לי:
@114 **לא תספו.** כגון חמש פרשיות בתפלין, חמשת מינין בלולב, וחמש ציציות, וכן ולא תגרעו:
@118 **ושמרתם.** זו משנה: **ועשיתם.** כמשמעו: **כי הוא חכמתכם ובינתכם** וגו' **.** בזאת תחשבו חכמים ונבונים לעיני העמים:
@120 **חקים ומשפטים צדיקם.** הגונים ומקבלים:
@121 **רק השמר לך** וגו' **פן תשכח את הדברים.** אז כשלא תשכחו אותם ותעשום על אמתתם תחשבו חכמים ונבונים ואם תעותו אותם מתוך שכחה תחשבו שוטים:
@122 **יום אשר עמדת.** מוסב על מקרא שלמעלה ממנו אשר ראו עיניך, יום אשר עמדת בחורב אשר ראיתם את הקולות ואת הלפידים: **ילמדון.** ילפון, לעצמם: **ילמדון.** יאלפון, לאחרים:
@126 **ואתי צוה ה' בעת ההוא ללמד אתכם.** תורה שבעל פה:
@128 **סמל.** צורה:
@131 **ופן תשא עיניך.** להסתכל בדבר ולתת לב לשוב לטעות אחריהם: **אשר חלק** וגו' **לכל העמים.** להאיר להם. דבר אחר לאלהות. לא מנען מלטעות אחריהם, אלא החליקם בדברי הבליהם לטרדם מן העולם. וכן הוא אומר (תהלים לו, ג) כי החליק אליו בעיניו למצא עונו לשנא:
@132 **מכור.** הוא כלי שמזקקים בו את הזהב:
@133 **התאנף.** נתמלא רוגז: **על דבריכם.** על אודותיכם על עסקיכם:
@134 **כי אנכי מת** וגו' **אינני עבר.** מאחר שמת מהיכן יעבר, אלא אף עצמותי אינם עוברין:
@135 **תמונת כל.** תמונת כל דבר: **אשר צוך ה'.** אשר צוך עליו שלא לעשות:
@136 **אל קנא.** מקנא לנקום אנפרנמנ''ט בלע''ז [חמה] מתחרה על רגזו להפרע מעובדי עבודה זרה:
@137 **ונושנתם.** רמז להם שיגלו ממנה לסוף שמונה מאות וחמשים ושתים שנה, כמנין ונושנתם. והוא הקדים והגלם לסוף שמונה מאות וחמשים והקדים שתי שנים לונושנתם, כדי שלא יתקים בהם (פסוק כו) כי אבד תאבדון וזהו שנאמר (דניאל ט, יד) וישקד ה' על הרעה ויביאה עלינו כי צדיק ה' אלהינו, צדקה עשה עמנו שמהר להביאה שתי שנים לפני זמנה:
@138 **העידתי בכם.** הנני מזמינם להיות עדים שהתריתי בכם:
@140 **ועבדתם שם אלהים.** כתרגומו. משאתם עובדים לעובדיהם כאלו אתם עובדים להם:
@143 **לא ירפך.** מלהחזיק בך בידיו. ולשון לא ירפך לשון לא יפעיל הוא, לא יתן לך רפיון, לא יפריש אותך מאצלו. וכן אחזתיו ולא ארפנו (שה''ש ג ד) , שלא ננקד ארפנו. כל לשון רפיון מוסב על לשון מפעיל ומתפעל, כמו (מלכים ב' ד, כז) הרפה לה, תן לה רפיון (דברים ט, יד) הרף ממני, התרפה ממני:
@144 **לימים ראשונים.** על ימים ראשונים: **ולמקצה השמים.** וגם שאל לכל הברואים אשר מקצה אל קצה זהו פשוטו. ומדרשו, מלמד על קומתו של אדם שהיתה מן הארץ עד השמים והוא השעור עצמו אשר מקצה אל קצה: **הנהיה כדבר הגדול הזה.** ומהו הדבר הגדול, השמע עם וגו' :
@146 **הנסה אלהים.** הכי עשה נסים שום אלוה, **לבא לקחת לו גוי** וגו' **.** כל ההי''ן הללו תמיהות הן, לכך נקודות הן בחט''ף פת''ח, הנהיה, הנשמע, הנסה, השמע: **במסות.** על ידי נסיונות הודיעם גבורותיו, כגון (שמות ח, ה) התפאר עלי, אם אוכל לעשות כן, הרי זה נסיון: **באותות.** בסימנין להאמין שהוא שלוחו של מקום, כגון (שמות ד, ב) מה זה בידך: **ובמופתים.** הם נפלאות שהביא עליהם מכות מפלאות: **ובמלחמה.** בים, שנאמר (שם יד, כה) כי ה' נלחם להם:
@147 **הראת.** כתרגומו אתחזיתא. כשנתן הקדוש ברוך הוא את התורה פתח להם שבעה רקיעים. וכשם שקרע את העליונים כך קרע את התחתונים. וראו שהוא יחידי, לכך נאמר אתה הראת לדעת:
@149 **ותחת כי אהב.** וכל זה תחת אשר אהב: **ויוצאך בפניו.** כאדם המנהיג בנו לפניו שנאמר (שמות יד, יט) ויסע מלאך האלהים ההולך וגו' וילך מאחריהם. דבר אחר ויוצאך בפניו בפני אבותיו, כמו שנאמר (תהלים עח, יב) נגד אבותם עשה פלא. ואל תתמה על שהזכירם בלשון יחיד, שהרי כתבם בלשון יחיד ויבחר בזרעו אחריו:
@150 **ממך מפניך.** סרסהו ודרשהו להוריש מפניך גוים גדולים ועצומים ממך: **כיום הזה.** כאשר אתה רואה היום:
@153 **אז יבדיל.** נתן לב להיות חרד לדבר שיבדילם. ואף על פי שאינן קולטות עד שיבדלו אותן שבארץ כנען, אמר משה, מצוה שאפשר לקימה אקימנה: **בעבר הירדן מזרחה שמש.** באותו עבר שבמזרחו של ירדן: **מזרחה שמש.** לפי שהוא דבוק, נקודה רי''ש בחטף, מזרח של שמש, מקום זריחת השמש:
@156 **וזאת התורה.** זו שהוא עתיד לסדר אחר פרשה זו:
@157 **אלה העדת** וגו' **אשר דבר.** הם הם אשר דבר בצאתם ממצרים חזר ושנאה להם בערבות מואב:
@159 **אשר בעבר הירדן.** שהוא במזרח, שהעבר השני היה במערב:
@164 **לא את אבתינו.** בלבד **כרת ה'** וגו' **כי אתנו:**
@165 **פנים בפנים.** אמר ר' ברכיה, כך אמר משה אל תאמרו אני מטעה אתכם על לא דבר, כדרך שהסרסור עושה בין המוכר ללוקח, הרי המוכר עצמו מדבר עמכם:
@166 **לאמר.** מוסב על (פסוק ד) דבר ה' עמכם בהר מתוך האש לאמר אנכי ה' וגו' ואנכי עומד בין ה' וביניכם:
@168 **על פני.** בכל מקום אשר אני שם וזהו כל העולם. דבר אחר כל זמן שאני קים. עשרת הדברות כבר פרשתים:
@176 **שמור.** ובראשונות הוא אומר (שמות כ) זכור. שניהם בדבור אחד ובתיבה אחת נאמרו ובשמיעה אחת נשמעו: **כאשר צוך.** קודם מתן תורה במרה: **וזכרת כי עבד היית** וגו' **.** על מנת כן פדאך שתהיה לו עבד ותשמר מצותיו:
@177 **כאשר צוך.** אף על כבוד אב ואם נצטוו במרה שנאמר (שמות טו, כה) שם שם לו חק ומשפט:
@178 **ולא תנאף.** אין לשון נאוף אלא באשת איש:
@179 **ולא תתאוה.** לא תרוג אף הוא לשון חמדה, כמו (בראשית ב, ט) נחמד למראה, דמתרגמנן דמרגג למחזי:
@180 **ולא יסף.** מתרגמנן ולא פסק. כי קולו חזק וקים לעולם. דבר אחר, ולא יסף, לא הוסיף להראות באותו פומבי:
@185 **ואת תדבר אלינו.** התשתם את כחי כנקבה שנצטערתי עליכם ורפיתם את ידי כי ראיתי שאינכם חרדים להתקרב אליו מאהבה. וכי לא היה יפה לכם ללמוד מפי הגבורה ולא ללמוד ממני:
@195 **ה' אלהינו ה' אחד.** ה' שהוא אלהינו עתה ולא אלהי האמות, הוא עתיד להיות ה' אחד, שנאמר (צפניה ג, ט) כי אז אהפך אל עמים שפה ברורה לקרא כלם בשם ה' ונאמר (זכריה יד, ט) ביום ההוא יהיה ה' אחד ושמו אחד:
@196 **ואהבת.** עשה דבריו מאהבה. אינו דומה עושה מאהבה לעושה מיראה. העושה אצל רבו מיראה כשהוא מטריח עליו מניחו והולך לו: **בכל לבבך.** בשני יצריך. דבר אחר בכל לבבך, שלא יהיה לבך חלוק על המקום: **ובכל נפשך.** אפלו הוא נוטל את נפשך: **ובכל מאדך.** בכל ממונך יש לך אדם שממונו חביב עליו מגופו לכך נאמר ובכל מאדך. דבר אחר ובכל מאדך בכל מדה ומדה שמודד לך בין במדה טובה בין במדת פרענות וכן דוד הוא אומר (תהלים קטז, יג) כוס ישועות אשא וגו' (שם קטז, יג) צרה ויגון אמצא וגו' :
@197 **והיו הדברים האלה.** ומהו האהבה והיו הדברים האלה, שמתוך כך אתה מכיר בהקדוש ברוך הוא ומדבק בדרכיו: **אשר אנכי מצוך היום.** לא יהיו בעיניך כדיוטגמא ישנה שאין אדם סופנה, אלא כחדשה שהכל רצין לקראתה. דיוטגמא, מצות המלך הבאה במכתב:
@198 **ושננתם.** לשון חדוד הוא, שיהיו מחדדים בפיך, שאם ישאלך אדם דבר לא תהא צריך לגמגם בו, אלא אמור לו מיד: **לבניך.** אלו התלמידים. מצינו בכל מקום שהתלמידים קרויים בנים, שנאמר (דברים יד, א) בנים אתם לה' אלהיכם, ואומר (מלכים ב' ב, ג) בני הנביאים אשר בבית אל, וכן בחזקיהו שלמד תורה לכל ישראל וקראם בנים שנאמר (ד''ה ב' כט, יא) בני עתה אל תשלו. וכשם שהתלמידים קרויים בנים, שנאמר בנים אתם לה' אלהיכם, כך הרב קרוי אב, שנאמר (מלכים ב' ב) אבי אבי רכב ישראל וגו' : **ודברת בם.** שלא יהא עיקר דבורך אלא בם. עשם עיקר ואל תעשם טפל: **ובשכבך.** יכול אפלו שכב בחצי היום, תלמוד לומר ובקומך. יכול אפלו עמד בחצי הלילה, תלמוד לומר בשבתך בביתך ובלכתך בדרך. דרך ארץ דברה תורה, זמן שכיבה וזמן קימה:
@199 **וקשרתם לאות על ידך.** אלו תפלין שבזרוע: **והיו לטטפת בין עיניך.** אלו תפלין שבראש ועל שם מנין פרשיותיהם נקראו טטפת. טט בכתפי שתים, פת באפריקי שתים:
@200 **מזזות ביתך.** מזוזת כתיב, שאין צריך אלא אחת: **ובשעריך.** לרבות שערי חצרות ושערי מדינות ושערי עירות:
@202 **חצובים.** לפי שהיו מקום טרשין וסלעים נופל בו לשון חציבה:
@203 **מבית עבדים.** כתרגומו מבית עבדותא, ממקום שהייתם שם עבדים:
@204 **ובשמו תשבע.** אם יש בך כל המדות הללו, שאתה ירא את שמו ועובד אותו, אז בשמו תשבע, שמתוך שאתה ירא את שמו תהא זהיר בשבועתך, ואם לאו לא תשבע:
@205 **מאלהי העמים אשר סביבותיכם.** הוא הדין לרחוקים, אלא לפי שאתה רואה את סביבותיך תועים אחריהם הצרך להזהיר עליהם ביותר:
@207 **במסה.** כשיצאו ממצרים שנסוהו במים, שנאמר (שמות יז, ז) היש ה' בקרבנו:
@209 **הישר והטוב.** זו פשרה, לפנים משורת הדין:
@210 **כאשר דבר.** והיכן דבר (שמות כג, כז) והמתי את כל העם וגו' :
@211 **כי ישאלך בנך מחר.** יש מחר שהוא אחר זמן:
@217 **ונשל.** לשון השלכה והתזה, וכן (דברים יט, ה) ונשל הברזל:
@218 **לא תחנם.** לא תתן להם חן. אסור לו לאדם לומר כמה נאה גוי זה. דבר אחר אל תתן להם חניה בארץ:
@220 **כי יסיר את בנך מאחרי.** בנו של גוי כשישא את בתך, יסיר את בנך אשר תלד לו בתך מאחרי. למדנו שבן בתך הבא מן הגוי קרוי בנך, אבל בן בנך הבא מן הגויה אינו קרוי בנך אלא בנה, שהרי לא נאמר על בתו לא תקח כי תסיר את בנך מאחרי:
@221 **מזבחתיהם.** של בנין: **מצבותם.** אבן אחת: **ואשירהם.** אילנות שעובדין אותן: **ופסיליהם.** צלמים:
@223 **לא מרבכם.** כפשוטו. ומדרשו לפי שאין אתם מגדילים עצמכם כשאני משפיע לכם טובה לפיכך חשקתי בכם: **כי אתם המעט.** הממעטין עצמכם, כגון אברהם, שאמר (בראשית יח, כז) ואנכי עפר ואפר, וכגון משה ואהרן שאמרו (שמות טז, ח) ונחנו מה, לא כנבוכדנצר שאמר (ישעיה יד, יד) אדמה לעליון, וסנחריב שאמר (שם לו, כ) מי בכל אלהי הארצות, וחירם שאמר (יחזקאל כח, ב) אל אני מושב אלהים ישבתי: **כי אתם המעט.** הרי כי משמש בלשון דהא:
@224 **כי מאהבת ה'.** הרי כי משמש בלשון אלא. לא מרבכם חשק ה' בכם, אלא מאהבת ה' אתכם: **ומשמרו את השבועה.** מחמת שמרו את השבועה:
@225 **לאלף דור.** ולהלן הוא אומר (דברים ה, ט) לאלפים, כאן שהוא סמוך אצל לשומרי מצותיו, העושין מיראה, הוא אומר לאלף, ולהלן שהוא סמוך אצל לאוהביו, העושין מאהבה, ששכרם יותר גדול, הוא אומר לאלפים: **לאוהביו.** אלו העושין מאהבה: **ולשומרי מצותיו.** אלו העושין מיראה:
@226 **ומשלם לשנאיו אל פניו.** בחייו משלם לו גמולו הטוב כדי להאבידו מן העולם הבא:
@227 **היום לעשותם.** ולמחר לעולם הבא לטול שכרם:
@228 **והיה עקב תשמעון.** אם המצות הקלות שאדם דש בעקביו תשמעון: **ושמר ה'** וגו' **.** ישמור לך הבטחתו:
@229 **שגר אלפיך.** ולדי בקרך, שהנקבה משגרת ממעיה: **ועשתרת צאנך.** מנחם פרש אבירי בשן (תהלים כב, יג) , מבחר הצאן. כמו (בראשית יד, ה) עשתרות קרנים, לשון חזק. ואונקלוס תרגם ועדרי ענך. ורבותינו אמרו למה נקרא שמם עשתרות שמעשירות את בעליהן:
@230 **עקר.** שאינו מוליד:
@233 **כי תאמר בלבבך.** על כרחך לשון דלמא הוא, שמא תאמר בלבבך מפני שהם רבים לא אוכל להורישם, אל תאמר כן, לא תירא מהם. ולא יתכן לפרשו באחת משאר לשונות של 'כי', שיפול עליו שוב לא תירא מהם:
@235 **המסות.** נסיונות: **והאותות.** כגון (שמות ד, ג) ויהי לנחש, (שמות ד, ט) והיו לדם ביבשת: **והמופתים.** המכות המפלאות: **והיד החזקה.** זה הדבר: **והזרוע הנטויה.** זה החרב של מכת בכורות:
@236 **הצרעה.** מין שרץ העוף, שהיתה זורקת בהם מרה ומסרסתן ומסמאה את עיניהם בכל מקום שהיו נסתרים שם:
@238 **פן תרבה עליך חית השדה.** והלא אם עושין רצונו של מקום אין מתיראין מן החיה, שנאמר (איוב ה, כג) וחית השדה השלמה לך, אלא גלוי היה לפניו שעתידין לחטוא:
@239 **והמם.** נקוד קמ''ץ כלו, לפי שאין מ''ם אחרונה מן היסוד, והרי הוא כמו והם אותם. אבל (ישעי' כח, כח) והמם גלגל עגלתו, כלו יסוד. לפיכך חציו קמ''ץ וחציו פת''ח, כשאר פעל של שלש אותיות:
@243 **כל המצוה.** כפשוטו. ומדרש אגדה אם התחלת במצוה גמור אותה, שאינה נקראת אלא על שם הגומרה, שנאמר (יהושע כד, לב) ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם, והלא משה לבדו נתעסק בהם להעלותם, אלא לפי שלא הספיק לגמרה וגמרוה ישראל, נקראת על שמם:
@244 **התשמר מצותיו.** שלא תנסהו ולא תהרהר אחריו:
@246 **שמלתך לא בלתה.** ענני כבוד היו שפים בכסותם ומגהצים אותם כמין כלים מגוהצים, ואף קטניהם כמו שהיו גדלים היה גדל לבושן עמהם, כלבוש הזה של חומט שגדל עמו: **לא בצקה.** לא נפחה כבצק, כדרך הולכי יחף שרגליהם נפוחות:
@250 **זית שמן.** זיתים העושים שמן:
@263 **גדלים ועצמים ממך.** אתה עצום, והם עצומים ממך:
@266 **אל תאמר בלבבך.** צדקתי ורשעת הגוים גרמו:
@267 **לא בצדקתך** וגו' **אתה בא לרשת** וגו' **כי ברשעת הגוים.** הרי כי משמש בלשון אלא:
@271 **ואשב בהר.** אין ישיבה אלא לשון עכבה:
@273 **לחת.** לחת כתיב, ששתיהם שוות:
@280 **ואתנפל לפני ה' כראשנה ארבעים יום.** שנאמר (שמות לב, ל) ועתה אעלה אל ה' אולי אכפרה. באותה עליה נתעכבתי ארבעים יום. נמצאו כלים בעשרים ותשעה באב. שהוא עלה בשמונה עשר בתמוז, בו ביום נתרצה הקדוש ברוך הוא לישראל ואמר לו למשה (דברים י, א) פסל לך שני לוחת, עשה עוד ארבעים יום, נמצאו כלים ביום הכפורים. בו ביום נתרצה הקדוש ברוך הוא לישראל בשמחה ואמר לו למשה (במדבר יד, כ) סלחתי כדברך. לכך הקבע למחילה ולסליחה. ומנין שנתרצה ברצון שלם, שנאמר בארבעים של לוחות אחרונות ואנכי עמדתי בהר כימים הראשונים (דברים י, י) , מה הראשונים ברצון אף אחרונים ברצון, אמור מעתה אמצעיים היו בכעס:
@282 **ובאהרן התאנף ה'.** לפי ששמע לכם: **להשמידו.** זה כלוי בנים. וכן הוא אומר (עמוס ב, ט) ואשמיד פריו ממעל: **ואתפלל גם בעד אהרן.** והועילה תפלתי לכפר מחצה, ומתו שנים ונשארו השנים:
@283 **טחון.** לשון הוה כמו (בראשית כו, יג) הלוך וגדל:
@287 **ואתנפל** וגו' **.** אלו הן עצמם האמורים למעלה (פסוק יח) וכפלן כאן, לפי שכתוב כאן סדר תפלתו, שנאמר (פסוק כו) ה' אלהים אל תשחת עמך וגו' :
@292 **בעת ההוא.** לסוף ארבעים יום נתרצה לי ואמר לי פסל לך, ואחר כך ועשית לך ארון עץ, ואני עשיתי ארון תחלה, שכשאבוא והלחות בידי היכן אתנם. ולא זה הוא הארון שעשה בצלאל, שהרי משכן לא נתעסקו בו עד לאחר יום הכפורים, כי ברדתו מן ההר צוה להם על מלאכת המשכן, ובצלאל עשה משכן תחלה ואחר כך ארון וכלים, נמצא זה ארון אחר היה. וזהו שהיה יוצא עמהם למלחמה. ואותו שעשה בצלאל לא יצא למלחמה אלא בימי עלי, ונענשו עליו ונשבה:
@297 **ובני ישראל נסעו מבארות בני יעקן מוסרה.** מה ענין זה לכאן. ועוד, וכי מבארות בני יעקן נסעו למוסרה, והלא ממוסרות באו לבני יעקן, שנאמר (במדבר לג, לא) ויסעו ממוסרות וגו' . ועוד, שם מת אהרן, והלא בהר ההר מת, צא וחשוב ותמצא שמונה מסעות ממוסרה להר ההר. אלא, אף זו מן התוכחה, ועוד זאת עשיתם כשמת אהרן בהר ההר לסוף ארבעים שנה ונסתלקו ענני כבוד, יראתם לכם ממלחמת מלך ערד ונתתם ראש לחזור למצרים, וחזרתם לאחוריכם שמונה מסעות עד בני יעקן ומשם למוסרה, שם נלחמו בכם בני לוי והרגו מכם ואתם מהם, עד שהחזירו אתכם בדרך חזרתכם, ומשם חזרתם הגדגדה הוא חור הגדגד:
@298 **ומן הגדגדה** וגו' **.** ובמוסרה עשיתם אבל כבד על מיתתו של אהרן שגרמה לכם זאת, ונדמה לכם כאלו מת שם. וסמך משה תוכחה זו לשבירת הלוחות, לומר שקשה מיתתן של צדיקים לפני הקדוש ברוך הוא, כיום שנשתברו בו הלוחות. ולהודיעך שהקשה לו מה שאמרו (במד' יד, ד) נתנה ראש לפרוש ממנו, כיום שעשו בו את העגל:
@299 **בעת ההוא הבדיל ה'** וגו' **.** מוסב לענין הראשון: **בעת ההוא.** בשנה הראשונה לצאתכם ממצרים וטעיתם בעגל ובני לוי לא טעו, הבדילם המקום מכם. וסמך מקרא זה לחזרת בני יעקן לומר שאף בזו לא טעו בה בני לוי, אלא עמדו באמונתם: **לשאת את ארון.** הלוים: **לעמד לפני ה' לשרתו ולברך בשמו.** הכהנים, והוא נשיאת כפים:
@300 **על כן לא היה ללוי חלק.** לפי שהבדלו לעבודת מזבח ואינן פנויין לחרוש ולזרוע: **ה' הוא נחלתו.** נוטל פרס מזמן מבית המלך:
@301 **ואנכי עמדתי בהר.** לקבל הלוחות האחרונות. ולפי שלא פרש למעלה כמה עמד בהר בעליה אחרונה זו, חזר והתחיל בה: **כימים הראשונים.** של לוחות הראשונות, מה הם ברצון אף אלו ברצון. אבל האמצעיים שעמדתי שם להתפלל עליכם היו בכעס:
@302 **ויאמר ה' אלי** וגו' **.** אף על פי שסרתם מאחריו וטעיתם בעגל, אמר לי (שמות לב, לד) לך נחה את העם:
@303 **ועתה ישראל.** אף על פי שעשיתם כל זאת, עודנו רחמיו וחבתו עליכם, ומכל מה שחטאתם לפניו אינו שואל מכם כי אם ליראה וגו' : **כי אם ליראה** וגו' **.** רבותינו דרשו מכאן, הכל בידי שמים חוץ מיראת שמים:
@304 **לשמר את מצות ה'.** ואף היא לא לחנם, אלא לטוב לך, שתקבלו שכר:
@305 **הן לה' אלהיך.** הכל, ואף על פי כן רק באבותיך חשק ה' מן הכל:
@306 **בכם.** כמו שאתם רואים אתכם חשוקים מכל העמים היום הזה:
@307 **ערלת לבבכם.** אוטם לבבכם וכסויו:
@308 **ואדני האדנים.** לא יוכל שום אדון להציל אתכם מידו: **לא ישא פנים.** אם תפרקו עלו: **ולא יקח שחד.** לפיסו בממון:
@309 **עשה משפט יתום ואלמנה.** הרי גבורה, ואצל גבורתו אתה מוצא ענותנותו: **ואהב גר לתת לו לחם ושמלה.** ודבר חשוב הוא זה, שכל עצמו של יעקב אבינו על זה נתפלל, (בראשית כח, כ) ונתן לי לחם לאכל ובגד ללבש:
@310 **כי גרים הייתם.** מום שבך אל תאמר לחברך:
@311 **את ה' אלהיך תירא.** ותעבוד לו ותדבק בו, ולאחר שיהיו בך כל המדות הללו, אז בשמו תשבע:
@315 **וידעתם היום.** תנו לב לדעת ולהבין ולקבל תוכחתי: **כי לא את בניכם.** אני מדבר עכשיו שיוכלו לומר אנו לא ידענו ולא ראינו בכל זה:
@319 **בקרב כל ישראל.** כל מקום שהיה אחד מהם בורח, הארץ נבקעת מתחתיו ובולעתו, אלו דברי רבי יהודה. אמר לו רבי נחמיה, והלא כבר נאמר (במדבר טז, לב) ותפתח הארץ את פיה, ולא פיותיה. אמר לו, ומה אני מקים בקרב כל ישראל. אמר לו שנעשית הארץ מדרון כמשפך, וכל מקום שהיה אחד מהם [בורח] , היה מתגלגל ובא עד מקום הבקיעה: **ואת כל היקום אשר ברגליהם.** זה ממונו של אדם שמעמידו על רגליו:
@320 **כי עיניכם הראת.** מוסב על מקרא האמור למעלה, (פסוק ב) כי לא את בניכם אשר לא ידעו וגו' כי אם עמכם אשר עיניכם הרואות וגו' :
@323 **לא כארץ מצרים הוא.** אלא טובה המנה. ונאמרה הבטחה זו לישראל ביציאתם ממצרים, שהיו אומרים שמא לא נבוא אל ארץ טובה ויפה כזו. יכול בגנותה הכתוב מדבר, וכך אמר להם, לא כארץ מצרים היא, אלא רעה המנה, תלמוד לומר (במדבר יג, כב) וחברון שבע שנים נבנתה וגו' , אדם אחד בנאן, וחם בנה צוען למצרים בנו, וחברון לכנען. דרך ארץ אדם בונה את הנאה ואחר כך בונה את הכעור שפסלתו של ראשון, הוא נותן בשני. ובכל מקום, החביב קודם. הא למדת שחברון יפה מצוען, ומצרים משבחת מכל הארצות, שנאמר (בראשית יג, י) כגן ה' כארץ מצרים, וצוען שבח מצרים היא, שהיתה מקום מלכות, שכן הוא אומר (ישעיה ל, ד) כי היו בצוען שריו. וחברון פסלתה של ארץ ישראל, לכך הקצוה לקבורת מתים, ואף על פי כן היא יפה מצוען. ובמסכת כתבות (קיב, א) דרשו בענין אחר, אפשר אדם בונה בית לבנו הקטן ואחר כך לבנו הגדול, אלא שמבנה על אחד משבעה בצוען: **אשר יצאתם משם.** אפלו ארץ רעמסס [וארץ גושן] אשר ישבתם בה והיא במיטב ארץ מצרים שנאמר (בראשית מז, יא) במיטב הארץ וגו' , אף היא אינה כארץ ישראל: **והשקית ברגלך.** ארץ מצרים היתה צריכה להביא מים מנילוס ברגלך ולהשקותה וצריך אתה לנדד משינתך ולעמול, והנמוך שותה ולא הגבוה, ואתה מעלה המים מן הנמוך לגבוה. אבל זו (פסוק יא) למטר השמים תשתה מים. אתה ישן על מטתך, והקדוש ברוך הוא משקה נמוך וגבוה, גלוי ושאינו גלוי, כאחת: **כגן הירק.** שאין די לו בגשמים ומשקין אותו ברגל ובכתף:
@324 **ארץ הרים ובקעת.** משבח ההר מן המישור, שהמישור, בבית כור אתה זורע כור, אבל ההר בבית כור ממנו חמשת כורין, ארבע מארבע שפועיו, ואחד בראשו: **ובקעת.** הן מישור:
@325 **אשר ה' אלהיך דרש אתה.** והלא אף כל הארצות הוא דורש, שנאמר (איוב לח, כו) להמטיר על ארץ לא איש, אלא כביכול אינו דורש אלא אותה, ועל ידי אותה דרישה שדורשה דורש את כל הארצות עמה: **תמיד עיני ה' אלהיך בה.** לראות מה היא צריכה ולחדש לה גזרות, עתים לטובה עתים לרעה וכו' , כדאיתא בראש השנה (יז, ב) : **מרשית השנה.** מראש השנה נדון מה יהא בסופה:
@326 **והיה אם שמע.** והיה, מוסב על האמור למעלה, (פסוק יא) למטר השמים תשתה מים: **והיה אם שמע תשמעו.** אם שמע בישן תשמעו בחדש. וכן (דברים ח, יט) והיה אם שכח תשכח, אם התחלת לשכח, סופך שתשכח כלה, שכן כתיב במגלה אם תעזבני יום, יומים אעזבך [ במגילת חסידים ] (ספרי מח) : **מצוה אתכם היום.** שיהיו עליכם חדשים, כאלו שמעתם בו ביום: **לאהבה את ה'.** שלא תאמר הרי אני לומד בשביל שאהיה עשיר, בשביל שאקרא רב, בשביל שאקבל שכר. אלא כל מה שתעשו עשו מאהבה וסוף הכבוד לבא: **ולעבדו בכל לבבכם.** עבודה שהיא בלב. וזו היא תפלה, שהתפלה קרויה עבודה, שנאמר (דניאל ו, יז) אלהך די אנת פלח לה בתדירא, וכי יש פלחן בבבל, אלא על שהיה מתפלל, שנאמר (שם ו, יא) וכוין פתיחן לה וגו' . וכן בדוד הוא אומר (תהלים קמא, ב) תכון תפלתי קטרת לפניך: **בכל לבבכם ובכל נפשכם.** והלא כבר הזהיר על כך (דברים ו, ה) בכל לבבך ובכל נפשך, אלא, אזהרה ליחיד אזהרה לצבור:
@327 **ונתתי מטר ארצכם.** עשיתם מה שעליכם, אף אני אעשה מה שעלי: **בעתו.** בלילות שלא יטריחו אתכם. דבר אחר בעתו, בלילי שבתות שהכל מצויין בבתיהם: **יורה.** היא רביעה הנופלת לאחר הזריעה שמרוה את הארץ ואת הזרעים: **ומלקוש.** רביעה היורדת סמוך לקציר למלאות התבואה בקשיה. ולשון מלקוש, דבר המאוחר. כדמתרגמינן (בראשית ל, מב) והיה העטופים ללבן, לקישיא. דבר אחר לכך נקראת מלקוש שיורדת על המלילות ועל הקשין: **ואספת דגנך.** אתה תאספנו אל הבית ולא אויביך. כענין שנאמר (ישעי' סב, ח. ט) אם אתן את דגנך וגו' כי מאספיו יאכלהו, ולא כענין שנאמר (שופטים ו, ג) והיה אם זרע ישראל וגו' :
@328 **ונתתי עשב בשדך.** שלא תצטרך להוליכה למדבריות. דבר אחר שתהיה גוזז תבואתך כל ימות הגשמים ומשליך לפני בהמתך ואתה מונע ידך ממנה שלשים יום קודם לקציר ואינה פוחתת מדגנה: **ואכלת ושבעת.** הרי זו ברכה אחרת, שתהא ברכה מצויה בפת בתוך המעים:
@329 **השמרו לכם.** כיון שתהיו אוכלים ושבעים, השמרו לכם שלא תבעטו, שאין אדם מורד בהקדוש ברוך הוא אלא מתוך שביעה, שנאמר (דברים ח, יב. יד) פן תאכל ושבעת ובקרך וצאנך ירבין, מה הוא אומר אחריו, ורם לבבך ושכחת: **וסרתם.** לפרוש מן התורה ומתוך כך ועבדתם אלהים אחרים. שכיון שאדם פורש מן התורה הולך ומדבק בעבודה זרה. וכן דוד אמר (שמואל א' כו, יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבד וגו' , ומי אמר לו כן, אלא כיון שאני מגרש מלעסוק בתורה, הריני קרוב לעבוד אלהים אחרים: **אלהים אחרים.** שהם אחרים לעובדיהם, צועק אליו ואינו עונהו, נמצא עשוי לו כנכרי:
@330 **את יבולה.** אף מה שאתה מוביל לה, כענין שנאמר (חגי א, ו) זרעתם הרבה והבא מעט: **ואבדתם מהרה.** על כל שאר היסורין אגלה אתכם מן האדמה, שגרמה לכם לחטוא. משל למלך ששלח בנו לבית המשתה והיה יושב ומפקידו [ומפקדו] אל תאכל יותר מצרכך שתבא נקי לביתך, ולא השגיח הבן ההוא. אכל ושתה יותר מצרכו והקיא וטנף את כל בני המסבה. נטלוהו בידיו וברגליו וזרקוהו אחורי פלטרין [פלטין] : **מהרה.** איני נותן לכם ארכא. ואם תאמרו והלא נתנה ארכא לדור המבול, שנאמר (בראשית ו, ג) והיו ימיו מאה ועשרים שנה, דור המבול לא היה להם ממי ללמוד ואתם יש לכם ממי ללמוד:
@331 **ושמתם את דברי.** אף לאחר שתגלו היו מצינים במצות, הניחו תפלין, עשו מזוזות כדי שלא יהיו לכם חדשים כשתחזרו. וכן הוא אומר (ירמיה לא, כ) הציבי לך צינים:
@332 **לדבר בם.** משעה שהבן יודע לדבר, למדהו תורה צוה לנו משה (דברים לג, ד) , שיהא זה למוד דבורו. מכאן אמרו, כשהתינוק מתחיל לדבר, אביו מסיח עמו בלשון הקדש ומלמדו תורה, ואם לא עשה כן הרי הוא כאלו קוברו, שנאמר ולמדתם אתם את בניכם לדבר בם וגו' למען ירבו ימיכם וימי בניכם:
@334 **למען ירבו ימיכם וימי בניכם.** אם עשיתם כן ירבו, ואם לאו לא ירבו, שדברי תורה נדרשין מכלל לאו הן, ומכלל הן לאו: **לתת להם.** לתת לכם אין כתיב כאן, אלא לתת להם, מכאן נמצינו למדים תחית המתים מן התורה:
@335 **שמר תשמרון.** אזהרת שמירות הרבה להזהר בתלמודו שלא ישתכח: **ללכת בכל דרכיו.** הוא רחום ואתה תהא רחום, הוא גומל חסדים ואתה גמול חסדים: **ולדבקה בו.** אפשר לומר כן, והלא אש אוכלה הוא, אלא הדבק בתלמידים ובחכמים ומעלה אני עליך כאלו נדבקת בו:
@336 **והוריש ה'.** עשיתם מה שעליכם אף אני אעשה מה שעלי: **ועצמים מכם.** אתם גבורים, והם גבורים מכם, שאם לא שישראל גבורים, מה השבח שמשבח את האמוריים לומר ועצמים מכם, אלא אתם גבורים משאר אמות והם גבורים מכם:
@338 **לא יתיצב איש** וגו' **.** אין לי אלא איש, אמה ומשפחה ואשה בכשפיה מנין, תלמוד לומר לא יתיצב מכל מקום. אם כן מה תלמוד לומר איש, אפלו כעוג מלך הבשן: **פחדכם ומוראכם.** והלא פחד הוא מורא, אלא פחדכם על הקרובים ומוראכם על הרחוקים. פחד לשון בעיתת פתאום. מורא לשון דאגה מימים רבים: **כאשר דבר לכם.** והיכן דבר (שמות כג, כז) את אימתי אשלח לפניך וגו' :
@339 **ראה אנכי נתן לפניכם היום ברכה וקללה.** האמורות בהר גרזים ובהר עיבל:
@340 **את הברכה.** על מנת אשר תשמעו:
@341 **מן הדרך אשר אנכי מצוה אתכם היום ללכת** וגו' **.** הא למדת שכל העובד עבודה זרה הרי הוא סר מכל הדרך שנצטוו ישראל. מכאן אמרו כל המודה בעבודה זרה ככופר בכל התורה כלה:
@342 **ונתתה את הברכה.** כתרגומו ית מברכיא, את המברכים: **על הר גרזים.** כלפי הר גרזים, הופכין פניהם ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' . כל הארורים שבפרשה אמרו תחלה בלשון ברוך, ואחר כך הפכו פניהם כלפי הר עיבל ופתחו בקללה:
@343 **הלא המה.** נתן בהם סימן: **אחרי.** אחרי העברת הירדן הרבה והלאה למרחוק. וזהו לשון אחרי. כל מקום שנאמר אחרי, מפלג הוא: **דרך מבוא השמש.** להלן מן הירדן לצד מערב. וטעם המקרא מוכיח שהם שני דברים, שננקדו בשני טעמים, אחרי, נקוד בפשטא, ודרך, נקוד במשפל והוא דגש, ואם היה אחרי דרך, דבור אחד, היה נקוד אחרי, במשרת, בשופר הפוך, ודרך, בפשטא ורפה: **מול הגלגל.** רחוק מן הגלגל: **אלוני מרה.** שכם הוא, שנאמר (בראשית יב, ו) עד מקום שכם עד אלון מרה:
@344 **כי אתם עברים את הירדן** וגו' **.** נסים של ירדן יהיו סימן בידכם שתבואו ותירשו את הארץ:
@347 **אבד תאבדון.** אבד ואחר כך תאבדון מכאן לעוקר עבודה זרה שצריך לשרש אחריה: **את כל המקומות אשר עבדו שם** וגו' **.** ומה תאבדון מהם, את אלהיהם אשר על ההרים:
@348 **מזבח.** של אבנים הרבה: **מצבה.** של אבן אחת, והוא בימוס ששנויה במשנה (ע''ז מז, ב) אבן שחצבה מתחלתה לבימוס: **אשרה.** אילן הנעבד: **ואבדתם את שמם.** לכנות להם שם לגנאי, בית גליא קורין לה בית כריא, עין כל עין קוץ:
@349 **לא תעשון כן.** להקטיר לשמים בכל מקום (פסוק ה) , כי אם במקום אשר יבחר. דבר אחר ונתצתם את מזבחתם ואבדתם את שמם לא תעשון כן, אזהרה למוחק את השם ולנותץ אבן מן המזבח או מן העזרה. אמר רבי ישמעאל וכי תעלה על דעתך שישראל נותצין את המזבחות, אלא שלא תעשו כמעשיהם, ויגרמו עונותיכם למקדש אבותיכם שיחרב:
@350 **לשכנו תדרשו.** זה משכן שילה:
@351 **וזבחיכם.** שלמים של חובה: **מעשרתיכם.** מעשר בהמה ומעשר שני לאכול לפנים מן החומה: **תרומת ידכם.** אלו הבכורים, שנאמר בהם (דברים כו, ד) ולקח הכהן הטנא מידך: **ובכורות בקרכם.** לתתם לכהן ויקריבם שם:
@352 **אשר ברכך ה'.** לפי הברכה הבא:
@353 **לא תעשון ככל אשר אנחנו עשים** וגו' **.** מוסב למעלה (דברים יא, לא) על כי אתם עברים את הירדן וגו' כשתעברו את הירדן, מיד מתרים אתם להקריב בבמה, כל ארבע עשרה שנה של כבוש וחלוק, ובבמה לא תקריבו כל מה שאתם מקריבים פה היום במשכן, שהוא עמכם ונמשח והוא כשר להקריב בו חטאות ואשמות נדרים ונדבות, אבל בבמה אין קרב אלא הנדר והנדב. וזהו איש כל הישר בעיניו, נדרים ונדבות שאתם מתנדבים על ידי שיישר בעיניכם להביאם ולא על ידי חובה, אותם תקריבו בבמה:
@354 **כי לא באתם.** כל אותן ארבע עשרה שנה: **אל המנוחה.** זו שילה: **הנחלה.** זו ירושלים: **עד עתה.** כמו עדין:
@355 **ועברתם את הירדן וישבתם בארץ.** משתחלקוה ויהא כל אחד מכיר את חלקו ואת שבטו: **והניח לכם.** לאחר כבוש וחלוק ומנוחה (שופטים ג, א) מן הגוים אשר הניח ה' לנסות בם את ישראל. ואין זאת אלא בימי דוד, אז:
@356 **והיה המקום** וגו' **.** בנו לכם בית הבחירה בירושלים. וכן הוא אומר בדוד (שמואל ב' ז, א. ב) ויהי כי ישב המלך בביתו, וה' הניח לו מסביב מכל אויביו. ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים, וארון האלהים ישב בתוך היריעה: **שמה תביאו** וגו' **.** למעלה אמרו (פסוק ו) לענין שילה וכאן אמור לענין ירושלים, ולכך חלקם הכתוב, לתן התר בין זו לזו, משחרבה שילה ובאו לנוב, וחרבה נוב ובאו לגבעון, היו הבמות מתרות עד שבאו לירושלים: **מבחר נדריכם.** מלמד שיביאו מן המבחר:
@358 **השמר לך.** לתן לא תעשה על הדבר. **בכל מקום אשר תראה.** אשר יעלה בלבך, אבל אתה מקריב על פי נביא, כגון אליהו בהר הכרמל:
@359 **באחד שבטיך.** בחלקו של בנימין. ולמעלה הוא אומר (פסוק ה) מכל שבטיכם. הא כיצד, כשקנה דוד את הגרן מארונה היבוסי גבה הזהב מכל השבטים, ומכל מקום הגרן בחלקו של בנימין היה:
@360 **רק בכל אות נפשך.** במה הכתוב מדבר, אם בבשר תאוה להתירה להם בלא הקרבת אמורים, הרי הוא אומר במקום אחר (פסוק כ) כי ירחיב ה' אלהיך את גבולך וגו' ואמרת אכלה בשר וגו', במה זה מדבר, בקדשים שנפל בהם מום, שיפדו ויאכלו בכל מקום. יכול יפדו על מום עובר, תלמוד לומר רק: **תזבח ואכלת.** אין לך בהם התר גזה וחלב, אלא אכילה על ידי זביחה: **הטמא והטהור.** לפי שבאו מכח קדשים, שנאמר בהם (ויקרא ז, יט) והבשר אשר יגע בכל טמא לא יאכל, הצרך להתיר בו, שטמא וטהור אוכלין בקערה אחת: **כצבי וכאיל.** שאין קרבן בא מהם: **כצבי וכאיל.** לפטרן מן הזרוע והלחיים והקבה:
@361 **רק הדם לא תאכלו.** אף על פי שאמרתי שאין לך בו זריקת דם במזבח, לא תאכלנו: **תשפכנו כמים.** לומר לך שאין צריך כסוי. דבר אחר הרי הוא כמים להכשיר את הזרעים:
@362 **לא תוכל.** בא הכתוב לתן לא תעשה על הדבר. רבי יהושע בן קרחה אומר יכול אתה, אבל אינך רשאי, כיוצא בו (יהושע טו, סג) ואת היבוסי יושבי ירושלים לא יכלו בני יהודה להורישם, יכולים היו, אלא שאינן רשאין, לפי שכרת להם אברהם ברית כשלקח מהם מערת המכפלה. ולא יבוסים היו אלא חתיים היו, אלא על שם העיר ששמה יבוס [נקראים יבוסים] . כך מפורש בפרקי דרבי אליעזר. והוא שנאמר (שמואל ב' ה, ו) כי אם הסירך העורים והפסחים, צלמים שכתבו עליהם את השבועה: **ובכרת בקרך.** אזהרה לכהנים: **ותרומת ידך.** אלו הבכורים:
@363 **לפני ה'.** לפנים מן החומה: **והלוי אשר בשעריך.** אם אין לך לתת לו מחלקו, כגון מעשר ראשון, תן לו מעשר עני. אין לך מעשר עני, הזמינהו על שלמיך:
@364 **השמר לך.** לתן לא תעשה על הדבר: **על אדמתך.** אבל בגולה אינך מזהר עליו יותר מעניי ישראל:
@365 **כי ירחיב** וגו' **.** למדה תורה דרך ארץ, שלא יתאוה אדם לאכול בשר, אלא מתוך רחבת ידים ועושר: **בכל אות נפשך** וגו' **.** אבל במדבר נאסר להם בשר חלין, אלא אם כן מקדישה ומקריבה שלמים:
@366 **כי ירחק ממך המקום.** ולא תוכל לבוא ולעשות שלמים בכל יום כמו עכשיו שהמשכן הולך עמכם: **וזבחת** וגו' **כאשר צויתך.** למדנו שיש צווי בזביחה היאך ישחוט, והן הלכות שחיטה שנאמרו למשה בסיני:
@367 **אך כאשר יאכל את הצבי** וגו' **.** אינך מזהר לאכלן בטהרה. אי מה צבי ואיל חלבן מתר, אף חלין חלבן מתר, תלמוד לומר אך:
@368 **רק חזק לבלתי אכל הדם.** ממה שנאמר חזק אתה למד שהיו שטופים בדם לאכלו, לפיכך הצרך לומר חזק, דברי רבי יהודה. רבי שמעון בן עזאי אומר, לא בא הכתוב אלא להזהירך וללמדך עד כמה אתה צריך להתחזק במצות, אם הדם, שהוא קל להשמר ממנו, שאין אדם מתאוה לו, הצרך לחזקך באזהרתו, קל וחמר לשאר מצות: **ולא תאכל הנפש עם הבשר.** אזהרה לאבר מן החי:
@369 **לא תאכלנו.** אזהרה לדם התמצית:
@370 **לא תאכלנו.** אזהרה לדם האיברים: **למען ייטב לך** וגו' **.** צא ולמד מתן שכרן של מצות, אם הדם שנפשו של אדם קצה ממנו, הפורש ממנו זוכה לו ולבניו אחריו, קל וחמר לגזל ועריות שנפשו של אדם מתאוה להם:
@371 **רק קדשיך.** אף על פי שאתה מתר לשחוט חלין, לא התרתי לך לשחוט את הקדשים ולאכלן בשעריך בלא הקרבה, אלא הביאם לבית הבחירה:
@372 **ועשית עלתיך.** אם עולות הם תן הבשר והדם על גבי המזבח, ואם זבחי שלמים הם, דם זבחיך ישפך על המזבח תחלה ואחר כך והבשר תאכל. ועוד דרשו רבותינו (פסוק כו) , רק קדשיך בא ללמד על הקדשים שבחוצה לארץ וללמד על התמורות ועל ולדות קדשים שיקריבו:
@373 **שמר.** זו משנה שאתה צריך לשמרה בבטנך שלא תשכח. כענין שנאמר (משלי כב) כי נעים כי תשמרם בבטנך, ואם שנית אפשר שתשמע ותקיים, הא כל שאינו בכלל משנה אינו בכלל מעשה: **את כל הדברים.** שתהא חביבה עליך מצוה קלה כמצוה חמורה: **הטוב.** בעיני השמים: **והישר.** בעיני אדם:
@375 **פן תנקש.** אנקלוס תרגם לשון מוקש. ואני אומר שלא חש לדקדק בלשון, שלא מצינו נו''ן בלשון יוקש ואפלו ליסוד הנופל ממנו, אבל בלשון טרוף וקשקוש מצינו נו''ן (דניאל ה, ו) וארכבתה דא לדא נקשן. ואף זה אני אומר, פן תנקש אחריהם פן תטרף אחריהם להיות כרוך אחר מעשיהם, וכן (תהלים קט, יא) ינקש נושה לכל אשר לו, מקלל את הרשע להיות עליו נושים רבים והיו מחזירין ומנקשין אחר ממונו: **אחרי השמדם מפניך.** אחר שתראה שאשמידם מפניך, יש לך לתת לב מפני מה נשמדו אלו, מפני מעשים מקלקלים שבידיהם, אף אתה לא תעשה כן שלא יבואו אחרים וישמידוך: **איכה יעבדו.** לפי שלא ענש על עבודת אלילים אלא על זבוח וקטור ונסוך והשתחואה, כמו שכתוב (שמות כב, יט) בלתי לה' לבדו, דברים הנעשים לגבוה, בא ולמדך כאן, שאם דרכה של עבודה זרה לעבדה בדבר אחר, כגון פוער לפעור, וזורק אבן למרקוליס, זו היא עבודתה וחיב. אבל זבוח וקטור ונסוך והשתחואה, אפלו שלא כדרכה חיב:
@376 **כי גם את בניהם.** גם, לרבות את אבותיהם ואמותיהם. אמר ר' עקיבא אני ראיתי נכרי שכפתו לאביו לפני כלבו ואכלו:
@377 **את כל הדבר.** קלה כחמורה: **תשמרו לעשות.** לתן לא תעשה על עשה האמורים בפרשה. שכל השמר לשון לא תעשה הוא, אלא שאין לוקין על השמר של עשה: **לא תסף עליו.** חמשה טוטפות בתפלין, חמשה מינין בלולב, ארבע ברכות בברכת כהנים:
@378 **ונתן אליך אות.** בשמים, כענין שנאמר בגדעון (שופטים ו, יז) ועשית לי אות, ואומר (שם ו, לט) יהי נא חרב אל הגזה וגו' : **או מופת.** בארץ. [ ס''א אות . בשמים , דכתיב (בראשית א, יד) והיו לאתת ולמועדים או מופת . בארץ . דכתיב (שופטים שם) אם טל יהיה על הגזה לבדה ועל כל הארץ חרב ] אף על פי כן לא תשמע לו. ואם תאמר מפני מה נותן לו הקדוש ברוך הוא ממשלה לעשות אות, כי מנסה ה' אלהיכם אתכם:
@381 **ואת מצותיו תשמרו.** תורת משה: **ובקולו תשמעו.** בקול הנביאים: **ואתו תעבדו.** במקדשו: **ובו תדבקון.** הדבק בדרכיו. גמול חסדים, קבור מתים, בקר חולים, כמו שעשה הקדוש ברוך הוא:
@382 **סרה.** דבר המוסר מן העולם שלא היה ולא נברא ולא צויתיו לדבר כן, דישטולוד''א בלע''ז : **והפדך מבית עבדים.** אפלו אין לו עליך אלא שפדאך, דיו:
@383 **כי יסיתך.** אין הסתה אלא גרוי, שנאמר (שמואל א' כו, יט) אם ה' הסיתך בי, אמיטר''א בלע''ז , שמשיאו לעשות כן: **אחיך.** מאב: **בן אמך.** מאם: **חיקך.** השוכבת בחיקך ומחקה בך אפיקייד''א בלע''ז , וכן (יחזקאל מג, יד) ומחיק הארץ, מיסוד התקוע בארץ: **אשר כנפשך.** זה אביך. פרש לך הכתוב את החביבין לך, קל וחמר לאחרים: **בסתר.** דבר הכתוב בהוה, שאין דברי מסית אלא בסתר. וכן שלמה הוא אומר (משלי ז, ט) בנשף בערב יום באישון לילה ואפלה: **אשר לא ידעת אתה ואבתיך.** דבר זה גנאי גדול הוא לך שאף האמות אין מניחין מה שמסרו להם אבותיהם, וזה אומר לך עזוב מה שמסרו לך אבתיך:
@384 **הקרבים אליך או הרחקים.** למה פרט קרובים ורחוקים, אלא כך אמר הכתוב, מטיבן של קרובים אתה למד טיבן של רחוקים, כשם שאין ממש בקרובים כך אין ממש ברחוקים: **מקצה הארץ.** זו חמה ולבנה וצבא השמים שהן מהלכין מסוף העולם ועד סופו:
@385 **לא תאבה לו.** לא תהא תאב לו. לא תאהבנו. לפי שנאמר (ויקרא יט, יח) ואהבת לרעך כמוך, את זה לא תאהב: **ולא תשמע אליו.** בהתחננו על נפשו למחול לו, לפי שנאמר (שמות כג, ה) עזב תעזב עמו, לזה לא תעזוב: **ולא תחוס עינך עליו.** לפי שנאמר (ויקרא יט, טז) לא תעמד על דם רעך, על זה לא תחוס: **ולא תחמול.** לא תהפך בזכותו: **ולא תכסה עליו.** אם אתה יודע לו חובה אינך רשאי לשתוק:
@386 **כי הרג תהרגנו.** אם יצא מבית דין זכאי, החזירהו לחובה. יצא מבית דין חיב, אל תחזירהו לזכות: **ידך תהיה בו בראשונה.** מצוה ביד הנסת להמיתו. לא מת בידו, ימות ביד אחרים, שנאמר ויד כל העם וגו' :
@389 **לשבת שם.** פרט לירושלים שלא נתנה לדירה: **כי תשמע** וגו' **לאמר.** אומרים כן, יצאו וגו' :
@390 **בני בליעל.** בלי עול. שפרקו עלו של מקום: **אנשים.** ולא נשים: **ישבי עירם.** ולא יושבי עיר אחרת. מכאן אמרו אין נעשית עיר הנדחת עד שידיחוה אנשים, ועד שיהיו מדיחיה מתוכה:
@391 **ודרשת וחקרת ושאלת היטב.** מכאן למדו שבע חקירות מרבוי המקרא. כאן יש שלש דרישה וחקירה והיטב. ושאלת, אינו מן המנין, וממנו למדו בדיקות. ובמקום אחר הוא אומר (דברים יט, יח) ודרשו השופטים היטב. ועוד במקום אחר הוא אומר (שם יז, ד) ודרשת היטב. ולמדו היטב היטב לגזרה שוה, לתן האמור של זה בזה:
@392 **הכה תכה.** אם אינך יכול להמיתם במיתה הכתובה בהם, המיתם באחרת:
@393 **לה' אלהיך.** לשמו ובשבילו:
@394 **למען ישוב ה' מחרון אפו.** שכל זמן שעבודה זרה בעולם, חרון אף בעולם:
@396 **לא תתגדדו.** לא תתנו גדידה ושרט בבשרכם על מת כדרך שהאמוריים עושין, לפי שאתם בניו של מקום ואתם ראויין להיות נאים ולא גדודים ומקורחים: **בין עיניכם.** אצל הפדחת. ובמקום אחר הוא אומר (ויקרא כא, ה) לא יקרחו קרחה בראשם, לעשות כל הראש כבין העינים:
@397 **כי עם קדוש אתה.** קדשת עצמך מאבותיך. ועוד, ובך בחר ה':
@398 **כל תועבה.** כל שתעבתי לך, שאם צרם אזן בכור כדי לשחטו במדינה, הרי דבר שתעבתי לך כל מום לא יהיה בו, ובא ולמד כאן שלא ישחט ויאכל על אותו המום. בשל בשר בחלב הרי דבר שתעבתי לך, והזהיר כאן על אכילתו:
@400 **זאת הבהמה** וגו'' **איל וצבי ויחמור.** למדנו שהחיה בכלל בהמה, ולמדנו שבהמה וחיה טמאה מרבה מן הטהורה, שבכל מקום פורט את המועט: **ואקו.** מתרגם יעלא (איוב לט, א) יעלי סלע הוא אשטנבו''ק : **ותאו.** תורבלא, שור היער. באלא יער, בלשון ארמי:
@401 **מפרסת.** סדוקה כתרגומו: **פרסה.** פלנט''א [כף רגל] : **ושסעת.** חלוקה בשתי צפרנים. שיש סדוקה ואינה חלוקה בצפרנים והיא טמאה: **בבהמה.** משמע מה שנמצא בבהמה אכל, מכאן אמרו שהשליל נתר בשחיטת אמו:
@402 **השסועה.** בריה היא שיש לה שני גבין ושתי שדראות. אמרו רבותינו למה נשנו, בבהמות מפני השסועה, ובעופות מפני הראה, שלא נאמרו בתורת כהנים:
@403 **ובנבלתם לא תגעו.** רבותינו פרשו, ברגל. שאדם חיב לטהר את עצמו ברגל. יכול יהיו מזהרים בכל השנה, תלמוד לומר (ויקרא כא, א) אמור אל הכהנים וגו' ומה טמאת המת חמורה, כהנים מזהרים ואין ישראל מזהרים, טמאת נבלה קלה לא כל שכן:
@406 **כל צפור טהורה תאכלו.** להתיר משלחת שבמצורע:
@407 **וזה אשר לא תאכלו מהם.** לאסר את השחוטה:
@408 **והראה ואת האיה** וגו' **.** היא ראה היא איה היא דיה. ולמה נקרא שמה ראה, שרואה ביותר. ולמה הזהיר בכל שמותיה, שלא לתן פתחון פה לבעל דין לחלוק, שלא יהא האוסרה קורא אותה ראה והבא להתיר אומר, זו דיה שמה או איה שמה, וזו לא אסר הכתוב. ובעופות פרט לך הטמאים, ללמד שהעופות הטהורים מרבים על הטמאים, לפיכך פרט את המועט:
@411 **והתנשמת.** קלב''א שורי''ץ :
@412 **שלך.** השולה דגים מן הים:
@413 **דוכיפת.** הוא תרנגול הבר ובלע''ז הרופ''א וכרבלתו כפולה:
@414 **שרץ העוף.** הם הנמוכים הרוחשים על הארץ, כגון זבובין וצרעים וחגבים טמאים, הם קרויים שרץ:
@415 **כל עוף טהור תאכלו.** ולא את הטמא. בא לתן עשה על לא תעשה. וכן בבהמה, אותה תאכלו ולא בהמה טמאה, לאו הבא מכלל עשה, עשה, לעבור עליהם בעשה ולא תעשה:
@416 **לגר אשר בשעריך.** גר תושב שקבל עליו שלא לעבוד עבודה זרה ואוכל נבלות: **כי עם קדוש אתה לה'.** קדש את עצמך במתר לך. דברים המתרים ואחרים נוהגים בהם אסור, אל תתירם בפניהם: **לא תבשל גדי.** שלש פעמים. פרט לחיה ולעופות ולבהמה טמאה: **לא תבשל גדי** וגו':
@417 **עשר תעשר.** מה ענין זה אצל זה, אמר להם הקדוש ברוך הוא לישראל, לא תגרמו לי לבשל גדיים של תבואה עד שהן במעי אמותיהן, שאם אין אתם מעשרים מעשרות כראוי, כשהוא סמוך להתבשל אני מוציא רוח קדים והיא משדפתן. שנאמר (מלכים ב' יט, כא) ושדפה לפני קמה, וכן לענין בכורים: **שנה שנה.** מכאן שאין מעשרין מן החדש על הישן:
@418 **ואכלת** וגו' **.** זה מעשר שני. שכבר למדנו לתן מעשר ראשון ללוים, שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל וגו' , ונתן להם רשות לאכלו בכל מקום, שנאמר (שם יח, לא) ואכלתם אתו בכל מקום, על כרחך זה מעשר אחר הוא:
@419 **כי יברכך.** שתהא התבואה מרבה לשאת:
@421 **בכל אשר תאוה נפשך.** כלל: **בבקר ובצאן וביין ובשכר.** פרט: **ובכל אשר תשאלך נפשך.** חזר וכלל. מה הפרט מפורש ולד ולדות הארץ וראוי למאכל אדם וכו' :
@422 **והלוי** וגו' **לא תעזבנו.** מלתן לו מעשר ראשון: **כי אין לו חלק ונחלה עמך.** יצאו לקט שכחה ופאה והפקר, שאף הוא יש לו חלק עמך בהן כמוך, ואינן חיבין במעשר:
@423 **מקצה שלש שנים.** בא ולמד שאם השהה מעשרותיו של שנה ראשונה ושניה לשמטה, שיבערם מן הבית בשלישית:
@424 **ובא הלוי.** ויטול מעשר ראשון: **והגר והיתום.** ויטלו מעשר שני, שהוא של עני של שנה זו, ולא תאכלנו אתה בירושלים כדרך שנזקקת לאכול מעשר שני של שתי שנים: **ואכלו ושבעו.** תן להם כדי שביעה. מכאן אמרו אין פוחתין לעני בגורן וכו' . ואתה הולך לירושלים למעשר של שנה ראשונה ושניה שהשהית ומתודה בערתי הקדש מן הבית (דברים כו, יג) , כמו שמפורש ב''כי תכלה לעשר'' (שם כו, יב) :
@425 **מקץ שבע שנים.** יכול שבע שנים לכל מלוה ומלוה, תלמוד לומר (פסוק ט) קרבה שנת השבע. ואם אתה אומר שבע שנים לכל מלוה ומלוה להלואת כל אחד ואחד, היאך היא קרבה, הא למדת שבע שנים למנין השמטות:
@426 **שמוט כל בעל משה ידו.** שמוט את ידו של כל בעל משה:
@427 **את הנכרי תגש.** זו מצות עשה:
@428 **אפס כי לא יהיה בך אביון.** ולהלן הוא אומר (פסוק יא) כי לא יחדל אביון, אלא בזמן שאתם עושים רצונו של מקום, אביונים באחרים ולא בכם, וכשאין אתם עושים רצונו של מקום אביונים בכם: **אביון.** דל מעני, ולשון אביון שהוא תאב לכל דבר:
@429 **רק אם שמוע תשמע.** אז לא יהיה בך אביון: **שמוע תשמע.** שמע קמעא משמיעין אותו הרבה:
@430 **כאשר דבר לך.** והיכן דבר, ברוך אתה בעיר: (דברים כח, ג) **והעבטת.** כל לשון הלואה כשנופל על המלוה, נופל בלשון מפעיל. כגון והלוית, והעבטת. ואם היה אומר ועבטת היה נופל על הלוה, כמו ולוית: **והעבטת גוים.** יכול שתהא לוה מזה ומלוה לזה, תלמוד לומר ואתה לא תעבט: **ומשלת בגוים רבים.** יכול גוים אחרים מושלים עליך, תלמוד לומר ובך לא ימשלו:
@431 **כי יהיה בך אביון.** התאב תאב קודם: **מאחד אחיך.** אחיך מאביך, קודם לאחיך מאמך: **שעריך.** עניי עירך קודמים לעניי עיר אחרת: **לא תאמץ.** יש לך אדם שמצטער אם יתן אם לא יתן, לכך נאמר לא תאמץ. יש לך אדם שפושט את ידו וקופצה, לכך נאמר ולא תקפץ: **מאחיך האביון.** אם לא תתן לו, סופך להיות אחיו בעניות [של אביון] :
@432 **פתח תפתח.** אפלו כמה פעמים: **כי פתח תפתח.** הרי כי משמש בלשון אלא: **והעבט תעביטנו.** אם לא רצה במתנה, תן לו בהלואה: **די מחסרו.** ואי אתה מצוה להעשירו: **אשר יחסר לו.** אפלו סוס לרכוב עליו ועבד לרוץ לפניו: **לו.** זו אשה. וכן הוא אומר (בראשית ב, יח) אעשה לו עזר כנגדו:
@433 **וקרא עליך.** יכול מצוה, תלמוד לומר (דברים כד, טו) ולא יקרא: **והיה בך חטא.** מכל מקום, אפלו לא יקרא. אם כן למה נאמר וקרא עליך, ממהר אני לפרע על ידי הקורא יותר ממי שאינו קורא:
@434 **נתון תתן לו.** אפלו מאה פעמים: **לו.** בינו ובינך: **כי בגלל הדבר.** אפלו אמרת לתן, אתה נוטל שכר האמירה עם שכר המעשה:
@435 **על כן.** מפני כן: **לאמר.** עצה לטובתך אני משיאך: **לאחיך לעניך.** לאיזה אח, לעני: **לעניך.** ביו''ד אחד, לשון עני אחד הוא. אבל ענייך בשני יודי''ן, שני עניים:
@436 **כי ימכר לך.** על ידי אחרים, שמכרוהו בית דין בגנבתו הכתוב מדבר. והרי כבר נאמר (שמות כא, ב) כי תקנה עבד עברי, ובמכרוהו בית דין הכתוב מדבר. אלא מפני שני דברים שנתחדשו כאן. אחד שכתוב או העבריה, אף היא תצא בשש. ולא שמכרוה בית דין, שאין האשה נמכרת בגנבתה, שנאמר בגנבתו ולא בגנבתה, אלא בקטנה שמכרה אביה, ולמד כאן שאם יצאו שש שנים קודם שתביא סימנין תצא. ועוד חדש כאן (פסוק יד) העניק תעניק:
@438 **העניק תעניק.** לשון עדי בגובה ובמראית העין, שיהא נכר שהטיבות לו. ויש מפרשים לשון הטענה על צוארו: **מצאנך ומגרנך ומיקבך.** יכול אין לי אלא אלו בלבד, תלמוד לומר אשר ברכך, מכל מה שברכך בוראך. ולמה נאמרו אלו, מה אלו מיוחדים שהם בכלל ברכה אף כל שהוא בכלל ברכה, יצאו פרדות. ולמדו רבותינו במסכת קדושין (יז, א) בגזרה שוה כמה נותן לו מכל מין ומין:
@439 **וזכרת כי עבד היית.** והענקתי ושניתי לך מבזת מצרים ובזת הים, אף אתה הענק ושנה לו:
@441 **עבד עולם.** יכול כמשמעו, תלמוד לומר (ויקרא כה, י) ושבתם איש אל אחזתו ואיש אל משפחתו תשובו, הא למדת שאין זה, אלא עולמו של יובל: **ואף לאמתך תעשה כן.** הענק לה. יכול אף לרציעה השוה הכתוב אותה, תלמוד לומר (שמות כא, ה) ואם אמר יאמר העבד, עבד נרצע, ואין אמה נרצעת:
@442 **כי משנה שכר שכיר.** מכאן אמרו עבד עברי עובד בין ביום ובין בלילה. וזהו כפלים שבעבודת שכירי יום. ומהו עבודתו בלילה, רבו מוסר לו שפחה כנענית והולדות לאדון:
@443 **כל הבכור** וגו' **תקדיש.** ובמקום אחר הוא אומר לא יקדיש, שנאמר (ויקרא כז, כו) אך בכור אשר יבכר לה' וגו' , הא כיצד, אינו מקדישו לקרבן אחר, וכאן למד שמצוה לומר הרי אתה קדוש לבכורה. דבר אחר אי אפשר לומר תקדיש שכבר נאמר לא יקדיש, ואי אפשר לומר לא יקדיש שהרי כבר נאמר תקדיש, הא כיצד, מקדישו אתה הקדש עלוי, ונותן להקדש כפי טובת הנאה שבו: **לא תעבד בבכור שורך ולא תגז** וגו' **.** אף החלוף למדו רבותינו שאסור, אלא שדבר הכתוב בהוה:
@444 **לפני ה' אלהיך תאכלנו.** לכהן הוא אומר, שכבר מצינו שהוא ממתנות כהנה אחד תם ואחד בעל מום, שנאמר (במדבר יח, יח) ובשרם יהיה לך וגו' : **שנה בשנה.** מכאן שאין משהין אותו יותר על שנתו. יכול יהא פסול משעברה שנתו, כבר הקש למעשר, שנאמר (לעיל יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך ובכרת בקרך וצאנך, מה מעשר שני אינו נפסל משנה לחברתה, אף בכור אינו נפסל, אלא שמצוה תוך שנתו: **שנה בשנה.** אם שחטו בסוף שנתו, אוכלו אותו היום ויום אחד משנה אחרת. למד שנאכל לשני ימים ולילה אחד:
@445 **מום.** כלל: **פסח או עור.** פרט: **כל מום רע.** חזר וכלל. מה הפרט מפורש מום הגלוי ואינו חוזר, אף כל מום שבגלוי ואינו חוזר:
@447 **רק את דמו לא תאכל.** שלא תאמר הואיל וכלו התר הבא מכלל אסור הוא, שהרי קדוש ונשחט בחוץ בלא פדיון ונאכל, יכול יהא אף הדם מתר, תלמוד לומר רק את דמו לא תאכל:
@448 **שמור את חדש האביב.** מקודם בואו שמור, שיהא ראוי לאביב להקריב בו את מנחת העמר, ואם לאו, עבר את השנה: **ממצרים לילה.** והלא ביום יצאו, שנאמר (במדבר לג, ג) ממחרת הפסח יצאו בני ישראל וגו' , אלא לפי שבלילה נתן להם פרעה רשות לצאת, שנאמר (שמות יב, לא) ויקרא למשה ולאהרן לילה וגו' :
@449 **וזבחת פסח לה' אלהיך צאן.** שנאמר (שמות יב, ה) מן הכבשים ומן העזים תקחו: **ובקר.** תזבח לחגיגה. שאם נמנו על הפסח חבורה מרבה, מביאים עמו חגיגה כדי שיהא נאכל על השובע, ועוד למדו רבותינו דברים הרבה מפסוק זה:
@450 **לחם עני.** לחם שמזכיר את העוני שנתענו במצרים: **כי בחפזון יצאת.** ולא הספיק בצק להחמיץ וזה יהיה לך לזכרון. וחפזון לא שלך היה אלא של מצרים, שכן הוא אומר (שמות יב, לג) ותחזק מצרים על העם וגו' : **למען תזכר.** על ידי אכילת הפסח והמצה, את יום צאתך:
@451 **ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר.** אזהרה למותיר בפסח דורות, לפי שלא נאמר אלא בפסח מצרים, ויום ראשון האמור כאן הוא ארבעה עשר בניסן, כמה דאתאמר (שמות יב, טו) אך ביום הראשון תשביתו שאר מבתיכם. ולפי שנסתלק הכתוב מענינו של פסח והתחיל לדבר בחקות שבעת ימים, כגון שבעת ימים תאכל עליו מצות ולא יראה לך שאור בכל גבולך, הצרך לפרש באיזו זביחה הוא מזהיר, שאם כתב ולא ילין מן הבשר אשר תזבח בערב לבקר הייתי אומר שלמים הנשחטים כל שבעה כלן בבל תותירו ואינן נאכלין אלא ליום ולילה, לכך כתב בערב ביום הראשון. דבר אחר בחגיגת ארבעה עשר הכתוב מדבר, ולמד עליה שנאכלת לשני ימים. והראשון האמור כאן, ביום טוב הראשון הכתוב מדבר. וכן משמעות המקרא, בשר חגיגה אשר תזבח בערב, לא ילין ביום טוב הראשון עד בקרו של שני, אבל נאכלת היא בארבעה עשר ובחמשה עשר, כך היא שנויה במסכת פסחים (עא ב) :
@453 **בערב כבוא השמש מועד צאתך ממצרים.** הרי שלשה זמנים חלוקים, בערב, משש שעות ולמעלה זבחהו. וכבוא השמש, תאכלהו. ומועד צאתך, אתה שורפהו. כלומר, נעשה נותר ויצא לבית השרפה:
@454 **ובשלת.** זהו צלי אש, שאף הוא קרוי בשול: **ופנית בבקר.** לבקרו של שני, מלמד שטעון לינה ליל של מוצאי יום טוב:
@455 **ששת ימים תאכל מצות.** ובמקום אחר הוא אומר (שמות יב, טו) שבעת ימים, שבעה מן הישן וששה מן החדש. דבר אחר למד על אכילת מצה בשביעי, שאינה חובה, ומכאן אתה למד לששת ימים. שהרי שביעי בכלל היה ויצא מן הכלל ללמד, שאין אכילת מצה בו חובה אלא רשות, ולא ללמד על עצמו יצא אלא ללמד על הכלל כלו יצא, מה שביעי רשות אף כלם רשות, חוץ מלילה הראשון שהכתוב קבעו חובה, שנאמר (שמות יב, יח) בערב תאכלו מצות: **עצרת לה' אלהיך.** עצור עצמך מן המלאכה. דבר אחר כנופיא של מאכל ומשתה, לשון (שופטים יג, טו) נעצרה נא אותך:
@456 **מהחל חרמש בקמה.** משנקצר העמר שהוא ראשית הקציר:
@457 **מסת נדבת ידך.** די נדבת ידך, הכל לפי הברכה, הבא שלמי שמחה, וקדש קרואים לאכול:
@458 **והלוי:. והגר והיתום והאלמנה.** ארבעה שלי כנגד ארבעה שלך, בנך ובתך ועבדך ואמתך, אם אתה משמח את שלי, אני משמח את שלך:
@459 **וזכרת כי עבד היית** וגו' **.** על מנת כן פדיתיך, שתשמור ותעשה את החקים האלה:
@460 **באספך.** בזמן האסיף שאתה מכניס לבית פרות הקיץ. דבר אחר באספך מגרנך ומיקבך, למד שמסככין את הסכה בפסולת גורן ויקב:
@462 **והיית אך שמח.** לפי פשוטו אין זה לשון צווי אלא לשון הבטחה, ולפי תלמודו למדו מכאן לרבות לילי יום טוב האחרון לשמחה:
@463 **ולא יראה את פני ה' ריקם.** אלא הבא עולות ראיה ושלמי חגיגה:
@464 **איש כמתנת ידו.** מי שיש לו אוכלין הרבה ונכסים מרבין יביא עולות מרבות ושלמים מרבים:
@465 **שפטים ושטרים.** שופטים, דינים הפוסקים את הדין. ושוטרים, הרודין את העם אחר מצותם. שמכין וכופתין במקל וברצועה עד שיקבל עליו את דין השופט: **בכל שעריך.** בכל עיר ועיר: **לשבטיך.** מוסב על תתן לך. שופטים ושוטרים תתן לך לשבטיך בכל שעריך אשר ה' אלהיך נתן לך: **לשבטיך.** מלמד שמושיבין דינין לכל שבט ושבט ובכל עיר ועיר: **ושפטו את העם** וגו' **.** מנה דינין מומחים וצדיקים לשפוט צדק:
@466 **לא תטה משפט.** כמשמעו: **לא תכיר פנים.** אף בשעת הטענות. אזהרה לדין שלא יהא רך לזה וקשה לזה, אחד עומד ואחד יושב. לפי שכשרואה שהדין מכבד את חברו מסתתמין טענותיו: **ולא תקח שחד.** אפלו לשפוט צדק: **כי השחד יעור.** משקבל שחד ממנו אי אפשר שלא יטה את לבו אצלו להפוך בזכותו: **דברי צדיקים.** דברים המצדקים, משפטי אמת:
@467 **צדק צדק תרדף.** הלך אחר בית דין יפה: **למען תחיה וירשת.** כדאי הוא מנוי הדינין הכשרים להחיות את ישראל ולהושיבן על אדמתן:
@468 **לא תטע לך אשרה.** לחייבו עליה משעת נטיעתה ואפלו לא עבדה עובר בלא תעשה על נטיעתה: **לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך.** אזהרה לנוטע אילן ולבונה בית בהר הבית:
@469 **ולא תקים לך מצבה.** מצבת אבן אחת, להקריב עליה אפלו לשמים: **אשר שנא.** מזבח אבנים ומזבח אדמה צוה לעשות, ואת זו שנא כי חק היתה לכנענים. ואף על פי שהיתה אהובה לו בימי האבות, עכשיו שנאה, מאחר שעשאוה אלו חק לעבודה זרה:
@470 **לא תזבח** וגו' **כל דבר רע.** אזהרה למפגל בקדשים על ידי דבור רע. ועוד נדרשו בו שאר דרשות בשחיטת קדשים:
@471 **לעבר בריתו.** אשר כרת אתכם שלא לעבוד עבודה זרה:
@472 **אשר לא צויתי.** לעבדם:
@473 **נכון.** מכון העדות:
@474 **והוצאת את האיש ההוא:. אל שעריך** וגו' **.** המתרגם אל שעריך, לתרע בית דינך, טועה, שכן שנינו אל שעריך זה שער שעבד בו, או אינו אלא שער שנדון בו, נאמר שעריך למטה ונאמר שעריך למעלה (פסוק ב) מה שעריך האמור למעלה שער שעבד בו אף שעריך האמור למטה שער שעבד בו. ותרגומו לקרוך:
@475 **שנים [עדים] או שלשה.** אם מתקימת עדות בשנים למה פרט לך בשלשה, להקיש שלשה לשנים, מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כלם:
@477 **כי יפלא.** כל הפלאה לשון הבדלה ופרישה, שהדבר נבדל ומכסה ממך: **בין דם לדם.** בין דם טמא לדם טהור: **בין דין לדין.** בין דין זכאי לדין חיב: **בין נגע לנגע.** בין נגע טמא לנגע טהור: **דברי ריבת.** שיהו חכמי העיר חולקים בדבר, זה מטמא וזה מטהר זה מחיב וזה מזכה: **וקמת ועלית.** מלמד שבית המקדש גבוה מכל המקומות:
@478 **הכהנים הלוים.** הכהנים שיצאו משבט לוי: **ואל השפט אשר יהיה בימים ההם.** ואפלו אינו כשאר שופטים שהיו לפניו אתה צריך לשמוע לו. אין לך אלא שופט שבימיך:
@480 **ימין ושמאל.** אפלו אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין, וכל שכן שאומר לך על ימין ימין ועל שמאל שמאל:
@482 **וכל העם ישמעו.** מכאן שממתינין לו עד הרגל וממיתין אותו ברגל:
@485 **לא ירבה לו סוסים.** אלא כדי מרכבתו, שלא ישיב את העם מצרימה, שהסוסים באים משם. כמה שנאמר בשלמה, ותעלה ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה (מלכים א' י, כט) :
@486 **ולא ירבה לו נשים.** אלא שמונה עשרה, שמצינו שהיו לו לדוד שש נשים, ונאמר לו ואם מעט ואספה לך כהנה וכהנה (שמואל ב' יב, ח) : **וכסף וזהב לא ירבה לו מאד.** אלא כדי לתן לאכסניא [לאפסניא] :
@487 **והיה כשבתו.** אם עשה כן, כדאי הוא שתתקיים מלכותו: **את משנה התורה.** שתי ספרי תורה. אחת שהיא מנחת בבית גנזיו ואחת שנכנסת ויוצאת עמו. ואונקלוס תרגם פתשגן, פתר משנה לשון שנון ודבור:
@488 **דברי התורה.** כמשמעו:
@489 **ולבלתי סור מן המצוה.** אפלו מצוה קלה של נביא: **למען יאריך ימים.** מכלל הן אתה שומע לאו. וכן מצינו בשאול שאמר לו שמואל שבעת ימים תוחל עד בואי אליך להעלות עלות (שמואל א' י, ח) וכתיב ויוחל שבעת ימים (שמואל א' יג, ח) ולא שמר הבטחתו לשמור כל היום, ולא הספיק להעלות העולה עד שבא שמואל ואמר לו נסכלת לא שמרת וגו' ועתה ממלכתך לא תקום (שם יג ז. יד) . הא למדת, שבשביל מצוה קלה של נביא נענש: **הוא ובניו.** מגיד שאם בנו הגון למלכות הוא קודם לכל אדם:
@491 **כל שבט לוי.** בין תמימין בין בעלי מומין: **חלק.** בבזה: **ונחלה.** בארץ: **אשי ה'.** קדשי המקדש [הקדשים] : **ונחלתו.** אלו קדשי הגבול תרומות ומעשרות. אבל נחלה גמורה לא יהיה לו בקרב אחיו. ובספרי דרשו, ונחלה לא יהיה לו. זו נחלת שאר: **בקרב אחיו.** זו נחלת חמשה. ואיני יודע מה היא. ונראה לי שארץ כנען שמעבר הירדן ואלך נקראת ארץ חמשה עממין, ושל סיחון ועוג, שני עממין אמורי וכנעני. ונחלת שאר לרבות קיני וקנזי וקדמוני. וכן דורש בפרשת מתנות שנאמרו לאהרן על כן לא היה ללוי וגו' (דברים י, ט) להזהיר על קיני וקנזי וקדמוני. שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי ונחלה לא יהיה לו אלו נחלת חמשה. בקרב אחיו אלו נחלת שבעה. נחלת חמשה שבטים ונחלת שבעה שבטים. ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד, שכן משה הנחיל לראובן וגד וחצי שבט מנשה, ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה, ושבעה האחרים נטלו מאליהן אחרי מות יהושע, מתוך כך הזכיר חמשה לבד ושבעה לבד: **כאשר דבר לו.** לאהרן, בארצם לא תנחל וגו' אני חלקך (במדבר יח, כ) :
@492 **מאת העם.** ולא מאת הכהנים: **אם שור אם שה.** פרט לחיה: **הזרוע.** מן הפרק של ארכבה עד כף של יד שקורין אשפלדו''ן [עצם השכם] : **והלחיים.** עם הלשון. דורשי רשומות היו אומרים, זרוע, תחת יד, שנאמר (במדבר כה, ז) ויקח רמח בידו. לחיים, תחת תפלה, שנאמר (תהל' קו, ל) ויעמד פינחס ויפלל: **והקבה.** תחת (במד' כה) האשה אל קבתה:
@493 **ראשית דגנך.** זו תרומה, ולא פרש בה שעור, אבל רבותינו נתנו בה שעור, עין יפה אחד מארבעים, עין רעה אחד מששים, בינונית אחד מחמשים. וסמכו על המקרא שלא לפחות מאחד מששים, שנאמר וששיתם האיפה מחמר השערים (יחזקאל מה, יג) ששית האיפה, חצי סאה. כשאתה נותן חצי סאה לכור, הרי אחד מששים, שהכור שלשים סאין: **וראשית גז צאנך.** כשאתה גוזז צאנך בכל שנה תן ממנה ראשית לכהן. ולא פרש בה שעור. ורבותינו נתנו בה שעור אחד מששים. וכמה צאן חיבות בראשית הגז, חמש רחלות, שנאמר (שמואל א' כה, יח) וחמש צאן עשויות. רבי עקיבא אומר ראשית גז שתים, גז צאנך ארבע, תתן לו הרי חמש:
@494 **לעמד לשרת.** מכאן שאין שרות אלא מעומד:
@496 **וכי יבא הלוי.** יכול בבן לוי ודאי הכתוב מדבר, תלמוד לומר ושרת, יצאו לויים שאין ראויין לשרות: **ובא בכל אות נפשו** וגו' **ושרת.** למד על הכהן שבא ומקריב קרבנות נדבתו או חובתו ואפלו במשמר שאינו שלו. דבר אחר עוד למד על הכהנים הבאים לרגל שמקריבין במשמר ועובדין בקרבנות הבאים מחמת הרגל, כגון מוספי הרגל, ואף על פי שאין המשמר שלהם:
@497 **חלק כחלק יאכלו.** מלמד שחולקין בעורות ובבשר שעירי חטאות. יכול אף בדברים הבאים שלא מחמת הרגל, כגון תמידין ומוספי שבת ונדרים ונדבות, תלמוד לומר לבד ממכריו על האבות, חוץ ממה שמכרו האבות בימי דוד ושמואל, שנקבעו המשמרות ומכרו זה לזה טול אתה שבתך ואני אטול שבתי:
@498 **לא תלמד לעשות.** אבל אתה למד להבין ולהורות, כלומר להבין מעשיהם כמה הם מקלקלים, ולהורות לבניך לא תעשה כך וכך, שזה הוא חק הגוים:
@499 **מעביר בנו ובתו באש.** היא עבודת המולך. עושה מדורות אש מכאן ומכאן ומעבירו בין שתיהם: **קסם קסמים.** איזהו קוסם, האוחז את מקלו ואומר אם אלך אם לא אלך. וכן הוא אומר, (הושע ד, יב) עמי בעצו ישאל ומקלו יגיד לו: **מעונן.** רבי עקיבא אומר אלו נותני עונות, שאומרים עונה פלונית יפה להתחיל. וחכמים אומרים אלו אוחזי העינים: **מנחש.** פתו נפלה מפיו, צבי הפסיקו בדרך, מקלו נפל מידו:
@500 **וחבר חבר.** שמצרף נחשים או עקרבים או שאר חיות למקום אחד: **ושאל אוב.** זה מכשפות ששמו פיתום ומדבר משחיו ומעלה את המת בבית השחי שלו: **וידעני.** מכניס עצם חיה ששמה ידוע, לתוך פיו, ומדבר העצם על ידי מכשפות: **ודרש אל המתים.** כגון המעלה בזכרותו והנשאל בגלגלת:
@501 **כל עשה אלה.** עשה כל אלה לא נאמר אלא כל עשה אלה, אפלו אחת מהן:
@502 **תמים תהיה עם ה' אלהיך.** התהלך עמו בתמימות ותצפה לו ולא תחקור אחר העתידות, אלא כל מה שיבא עליך קבל בתמימות ואז תהיה עמו ולחלקו:
@503 **לא כן נתן לך ה' אלהיך.** לשמוע אל מעוננים ואל קוסמים שהרי השרה שכינה על הנביאים ואורים ותמים:
@504 **מקרבך מאחיך כמני.** כמו שאני מקרבך מאחיך יקים לך תחתי, וכן מנביא לנביא:
@509 **אשר לא צויתיו לדבר.** אבל צויתיו לחברו: **ואשר ידבר בשם אלהים אחרים.** אפלו כון את ההלכה, לאסור את האסור ולהתיר את המתר: **ומת.** בחנק. שלשה מיתתן בידי אדם, המתנבא מה שלא שמע ומה שלא נאמר לו ונאמר לחברו, והמתנבא בשם עבודה זרה. אבל הכובש את נבואתו והעובר על דברי נביא והעובר על דברי עצמו מיתתן בידי שמים, שנאמר אנכי אדרש מעמו (פסוק יט) :
@510 **וכי תאמר בלבבך.** עתידין אתם לומר, כשיבא חנניה בן עזור ומתנבא (ירמיה כז, טז) הנה כלי בית ה' מושבים מבבלה עתה מהרה, וירמיהו עומד וצווח על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה, (שם כז, כב) בבלה יובאו עם גלות צדקיהו:
@511 **אשר ידבר הנביא.** ויאמר דבר זה עתיד לבא עליכם, ותראו שלא יבא, הוא הדבר אשר לא דברו ה' והרג אותו. ואם תאמר זו במתנבא על העתידות, הרי שבא ואמר עשו כך וכך ומפי הקדוש ברוך הוא אני אומר, כבר נצטוו שאם בא להדיחך מאחת מכל המצות לא תשמע לו, אלא אם כן ממחה הוא לך שהוא צדיק גמור, כגון אליהו בהר הכרמל שהקריב בבמה בשעת אסור הבמות כדי לגדור את ישראל. הכל לפי צורך השעה וסיג הפרצה, לכך נאמר אליו תשמעון: **לא תגור ממנו.** לא תמנע עצמך מללמד עליו חובה ולא תירא לענש עליו:
@514 **תכין לך הדרך.** מקלט מקלט היה כתוב על פרשת דרכים: **ושלשת את גבול ארצך.** שיהא מתחלת הגבול עד העיר הראשונה של עיר מקלט, כשעור מהלך שיש ממנה עד השניה. וכן משניה, לשלישית. וכן מן השלישית, עד הגבול השני של ארץ ישראל:
@516 **ונדחה ידו.** כשבא להפיל הגרזן על העץ, ותרגומו ותתמריג ידיה, לשון ונשמטה ידו להפיל מכת הגרזן על העץ. כי שמטו הבקר, תרגם יונתן (שמואל ב' ו, ו) ארי מרגוהי תוריא: **ונשל הברזל מן העץ.** יש מרבותינו אומרים נשמט הברזל מקתו, ויש מהם אומרים שישיל הברזל חתיכה מן העץ המתבקע, והיא נתזה והרגה:
@517 **פן ירדף גאל הדם.** לכך אני אומר להכין לך דרך, וערי מקלט רבים:
@519 **ואם ירחיב.** כאשר נשבע לתת לך ארץ קיני וקנזי וקדמוני:
@520 **ויספת לך עוד שלש.** הרי תשע. שלש שבעבר הירדן ושלש שבארץ כנען ושלש לעתיד לבא:
@522 **וכי יהיה איש שנא לרעהו.** על ידי שנאתו הוא בא לידי וארב לו. מכאן אמרו עבר אדם על מצוה קלה סופו לעבור על מצוה חמורה. לפי שעבר על לא תשנא, סופו לבא לידי שפיכת דמים. לכך נאמר כי יהיה איש שנא לרעהו וגו' , שהיה לו לכתוב וכי יקום איש וארב לרעהו והכהו נפש:
@524 **לא תחוס עינך.** שלא תאמר הראשון כבר נהרג, למה אנו הורגים את זה ונמצאו שני ישראלים הרוגים:
@525 **לא תסיג גבול.** לשון (ישעיה מב, יז) נסגו אחור, שמחזיר סימן חלקת הקרקע לאחור לתוך שדה חברו למען הרחיב את שלו. והלא כבר נאמר (ויקרא יט, יג) לא תגזל, מה תלמוד לומר לא תסיג, למד על העוקר תחום חברו שעובר בשני לאוין. יכול אף בחוצה לארץ, תלמוד לומר בנחלתך אשר תנחל וגו' , בארץ ישראל עובר בשני לאוין, בחוצה לארץ אינו עובר אלא משום לא תגזל:
@526 **עד אחד.** זה בנה אב. כל עד שבתורה שנים, אלא אם כן פרט לך בו אחד: **לכל עון ולכל חטאת.** להיות חברו נענש על עדותו, לא עונש גוף ולא עונש ממון, אבל קם הוא לשבועה. אמר לחברו תן לי מנה שהלויתיך, אמר לו אין לך בידי כלום, ועד אחד מעיד שיש לו, חיב להשבע לו: **על פי שני עדים.** ולא שיכתבו עדותם באגרת וישלחו לבית דין, ולא שיעמוד תרגמן בין העדים ובין הדינים:
@527 **לענות בו סרה.** דבר שאינו, שהוסר העד הזה מכל העדות הזאת, כגון, שאמרו להם והלא עמנו הייתם אותו היום במקום פלוני:
@528 **ועמדו שני האנשים.** בעדים הכתוב מדבר, ולמד שאין עדות בנשים, ולמד שצריכין להעיד עדותן מעומד: **אשר להם הריב.** אלו בעלי הדין: **לפני ה'.** יהי דומה להם כאלו עומדין לפני המקום, שנאמר (תהלים פב, א) בקרב אלהים ישפט: **אשר יהיו בימים ההם.** יפתח בדורו כשמואל בדורו, צריך אתה לנהוג בו כבוד:
@529 **ודרשו השופטים היטב.** על פי המזימין אותם, שבודקים וחוקרים את הבאים להזימם בדרישה ובחקירה: **והנה עד שקר.** כל מקום שנאמר עד, בשנים הכתוב מדבר:
@530 **כאשר זמם.** ולא כאשר עשה. מכאן אמרו, הרגו אין נהרגין: **לעשות לאחיו.** מה תלמוד לומר לאחיו, למד על זוממי בת כהן נשואה שאינן בשריפה, אלא כמיתת הבועל שהוא בחנק, שנאמר (ויקרא כא, ט) היא באש תשרף, היא ולא בועלה. לכך נאמר כאן לאחיו, כאשר זמם לעשות לאחיו, ולא כאשר זמם לעשות לאחותו. אבל בכל שאר מיתות השוה הכתוב אשה לאיש, וזוממי אשה נהרגין כזוממי איש. כגון שהעידוה שהרגה את הנפש, שחללה את השבת, נהרגין במיתתה. שלא מעט כאן אחותו אלא במקום שיש לקים בהן הזמה במיתת הבועל:
@531 **ישמעו ויראו.** מכאן שצריכין הכרזה, איש פלוני ופלוני נהרגין על שהוזמו בבית דין:
@532 **עין בעין.** ממון, וכן שן בשן וגו' :
@533 **כי תצא למלחמה.** סמך הכתוב יציאת מלחמה לכאן, לומר לך, שאין מחסר אבר יוצא למלחמה. דבר אחר לומר לך, אם עשית משפט צדק אתה מבטח שאם תצא למלחמה אתה נוצח. וכן דוד הוא אומר (תהלים קיט, קכא) עשיתי משפט וצדק בל תניחני לעשקי: **על איבך.** יהיו בעיניך כאויבים, אל תרחם עליהם כי לא ירחמו עליך: **סוס ורכב.** בעיני כלם כסוס אחד, וכן הוא אומר (שופטים ו, טז) והכית את מדין כאיש אחד. וכן הוא אומר (שמות טו, יט) כי בא סוס פרעה: **עם רב ממך.** בעיניך הוא רב, אבל בעיני אינו רב:
@534 **כקרבכם אל המלחמה.** סמוך לצאתכם מן הספר מגבול ארצכם: **ונגש הכהן.** המשוח לכך. והוא הנקרא משוח מלחמה: **ודבר אל העם.** בלשון הקדש:
@535 **שמע ישראל.** אפלו אין בכם זכות אלא קרית שמע בלבד, כדאי אתם שיושיע אתכם: **על איביכם.** אין אלו אחיכם, שאם תפלו בידם אינם מרחמים עליכם, אין זו כמלחמת יהודה עם ישראל, שנאמר (דה''י ב' כח, טו) ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה, וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל, ויביאום ירחו עיר התמרים אצל אחיהם, וישובו שמרון, אלא על אויביכם אתם הולכים, לפיכך התחזקו למלחמה: **אל ירך לבבכם אל תיראו ואל תחפזו ואל תערצו.** ארבע אזהרות כנגד ארבעה דברים שמלכי האמות עושים. מגיפים בתריסיהם כדי להקישן זה לזה כדי להשמיע קול שיחפזו אלו שכנגדם וינוסו, ורומסים בסוסיהם ומצהילין אותם להשמיע קול שעטת פרסות סוסיהם, וצווחין בקולם ותוקעין בשופרות ומיני משמיעי קול: **אל ירך לבבכם.** מצהלת סוסים: **אל תיראו.** מהגפת התריסין: **ואל תחפזו.** מקול הקרנות: **ואל תערצו.** מקול הצוחה:
@536 **כי ה' אלהיכם** וגו' **.** הם באים בנצחונו של בשר ודם ואתם באים בנצחונו של מקום. פלשתים באו בנצחונו של גלית, מה היה סופו, נפל ונפלו עמו: **ההלך עמכם.** זה מחנה הארון:
@537 **ולא חנכו.** לא דר בו. חנוך לשון התחלה: **ואיש אחר יחנכנו.** ודבר של עגמת נפש הוא זה:
@538 **ולא חללו.** לא פדאו בשנה הרביעית, שהפירות טעונין לאכלן בירושלים או לחללן בדמים ולאכל הדמים בירושלים:
@539 **פן ימות במלחמה.** ישוב פן ימות, שאם לא ישמע לדברי הכהן כדאי הוא שימות:
@540 **ויספו השטרים.** למה נאמר כאן ויספו, מוסיפין זה על דברי הכהן, שהכהן מדבר ומשמיע מן (פסוק ג, ד) שמע ישראל עד להושיע אתכם, ומי האיש ושני ושלישי כהן מדבר ושוטר משמיע, וזה שוטר מדבר ושוטר משמיע: **הירא ורך הלבב.** רבי עקיבא אומר כמשמעו, שאינו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה. רבי יוסי הגלילי אומר הירא מעבירות שבידו, ולכך תלתה לו תורה לחזור על בית וכרם ואשה לכסות על החוזרים בשביל עברות שבידם, שלא יבינו שהם בעלי עברה, והרואהו חוזר אומר שמא בנה בית או נטע כרם או ארש אשה:
@541 **שרי צבאות.** שמעמידין זקפין, מלפניהם ומלאחריהם וכשילין של ברזל בידיהם וכל מי שרוצה לחזור הרשות בידו לקפח את שוקיו. זקפין, בני אדם עומדים בקצה המערכה לזקוף את הנופלים ולחזקם בדברים שובו אל המלחמה ולא תנוסו, שתחלת נפילה ניסה:
@542 **כי תקרב אל עיר.** במלחמת הרשות הכתוב מדבר, כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחקת וגו' :
@543 **כל העם הנמצא בה.** אפלו אתה מוצא בה משבעה אמות שנצטוית להחרימם, אתה רשאי לקימם: **למס ועבדוך.** עד שיקבלו עליהם מסים ושעבוד:
@544 **ואם לא תשלים עמך ועשתה עמך מלחמה.** הכתוב מבשרך שאם לא תשלים עמך סופה להלחם בך אם תניחנה ותלך: **וצרת עליה.** אף להרעיבה ולהצמיאה ולהמיתה מיתת תחלואים:
@545 **ונתנה ה' אלהיך בידך.** אם עשית כל האמור בענין, סוף שה' נותנה בידך:
@546 **והטף.** אף טף של זכרים. ומה אני מקים (פסוק יג) והכית את כל זכורה, בגדולים:
@549 **כאשר צוך.** לרבות את הגרגשי:
@550 **למען אשר לא ילמדו.** הא אם עשו תשובה ומתגירים, אתה רשאי לקבלם:
@551 **ימים.** שנים: **רבים.** שלשה. מכאן אמרו אין צרין על עירות של נכרים פחות משלשה ימים קודם לשבת. ולמד שפותח בשלום שנים או שלשה ימים. וכן הוא אומר (שמואל ב' א, א) וישב דוד בצקלג ימים שנים, ובמלחמת הרשות הכתוב מדבר: **כי האדם עץ השדה.** הרי כי משמש בלשון דלמא. שמא האדם עץ השדה להכנס בתוך המצור מפניך להתיסר ביסורי רעב וצמא כאנשי העיר, למה תשחיתנו:
@552 **עד רדתה.** לשון רדוי, שתהא כפופה לך:
@554 **ויצאו זקניך.** מיחדים שבזקניך, אלו סנהדרי גדולה: **ומדדו.** ממקום שהחלל שוכב: **אל הערים אשר סביבת החלל.** לכל צד לידע איזו קרובה:
@556 **אל נחל איתן.** קשה, שלא נעבד: **וערפו.** קוצץ ערפה בקופיץ. אמר הקדוש ברוך הוא תבא עגלה בת שנתה שלא עשתה פרות ותערף במקום שאינו עושה פרות, לכפר על הריגתו של זה שלא הניחוהו לעשות פרות:
@559 **ידינו לא שפכה.** וכי עלתה על לב שזקני בית דין שופכי דמים הם, אלא לא ראינוהו ופטרנוהו בלא מזונות ובלא לויה. והכהנים אומרים כפר לעמך ישראל:
@560 **ונכפר להם הדם.** הכתוב מבשרם שמשעשו כן, יכפר להם העון:
@561 **ואתה תבער.** מגיד שאם נמצא ההורג אחר שנתערפה העגלה הרי זה יהרג, והוא הישר בעיני ה':
@562 **כי תצא למלחמה.** במלחמת הרשות הכתוב מדבר, שבמלחמת ארץ ישראל אין לומר ושבית שביו, שהרי כבר נאמר (לעיל כ, טז) לא תחיה כל נשמה: **ושבית שביו.** לרבות כנענים שבתוכה ואף על פי שהם משבעה אמות:
@563 **אשת.** אפלו אשת איש: **ולקחת לך לאשה.** לא דברה תורה אלא כנגד יצר הרע. שאם אין הקדוש ברוך הוא מתירה, ישאנה באסור. אבל אם נשאה, סופו להיות שונאה, שנאמר אחריו (פסוק טו) כי תהיין לאיש וגו' וסופו להוליד ממנה בן סורר ומורה, לכך נסמכו פרשיות הללו:
@564 **ועשתה את צפרניה.** תגדלם כדי שתתנול:
@565 **והסירה את שמלת שביה.** לפי שהם נאים, שהגוים בנותיהם מתקשטות במלחמה בשביל להזנות אחרים עמהם: **וישבה בביתך.** בבית שמשתמש בו, נכנס ונתקל בה, יוצא ונתקל בה, רואה בבכייתה, רואה בנוולה, כדי שתתגנה עליו: **ובכתה את אביה.** כל כך למה, כדי שתהא בת ישראל שמחה וזו עצבה, בת ישראל מתקשטת וזו מתנולת:
@566 **והיה אם לא חפצת בה.** הכתוב מבשרך שסופך לשנאותה: **לא תתעמר בה.** לא תשתמש בה, בלשון פרסי קורין לעבדות ושמוש, עימראה. מיסודו של רבי משה הדרשן למדתי כן:
@569 **פי שנים.** כנגד שני אחים: **בכל אשר ימצא לו.** מכאן שאין הבכור נוטל פי שנים בראוי לבא לאחר מיתת האב, כבמחזק:
@570 **סורר.** סר מן הדרך: **ומורה.** מסרב בדברי אביו, לשון ממרים: **ויסרו אותו.** מתרין בו בפני שלשה ומלקין אותו. בן סורר ומורה אינו חיב, עד שיגנוב ויאכל תרטימר בשר וישתה חצי לוג יין. שנאמר (פסוק כ) זולל וסבא, ונאמר (משלי כג, כ) אל תהי בסובאי יין בזוללי בשר למו. ובן סורר ומורה נהרג על שם סופו, הגיעה תורה לסוף דעתו, סוף שמכלה ממון אביו ומבקש למודו ואינו מוצא, ועומד בפרשת דרכים ומלסטם את הבריות, אמרה תורה ימות זכאי ואל ימות חיב:
@573 **וכל ישראל ישמעו ויראו.** מכאן שצריך הכרזה בבית דין, פלוני נסקל על שהיה בן סורר ומורה:
@574 **וכי יהיה באיש חטא משפט מות.** סמיכות הפרשיות מגיד, שאם חסים עליו אביו ואמו, סוף שיצא לתרבות רעה ויעבור עברות ויתחיב מיתה בבית דין: **ותלית אתו על עץ.** רבותינו אמרו, כל הנסקלין, נתלין, שנאמר (פסוק כג) כי קללת אלהים תלוי. והמברך ה', בסקילה:
@575 **כי קללת אלהים תלוי.** זלזולו של מלך הוא, שאדם עשוי בדמות דיקנו וישראל הם בניו. משל לשני אחים תאומים שהיו דומין זה לזה, אחד נעשה מלך, ואחד נתפס ללסטיות ונתלה, כל הרואה אותו אומר המלך תלוי. כל קללה שבמקרא לשון הקל וזלזול, כמו (מלכ' א' ב, ח) והוא קללני קללה נמרצת:
@576 **והתעלמת.** כובש עין כאלו אינו רואהו: **לא תראה' והתעלמת.** לא תראה אותו שתתעלם ממנו, זהו פשוטו. ורבותינו אמרו פעמים שאתה מתעלם וכו' :
@577 **עד דרש אחיך.** וכי תעלה על דעתך שיתנהו לו קודם שידרשהו, אלא דרשהו שלא יהא רמאי: **והשבתו לו.** שתהא בו השבה, שלא יאכל בביתך כדי דמיו ותתבעם ממנו. מכאן אמרו, כל דבר שעושה ואוכל יעשה ויאכל, ושאינו עושה ואוכל, ימכר:
@578 **לא תוכל להתעלם.** לכבוש עינך כאלו אינך רואה אותו:
@579 **הקם תקים.** זו טעינה. להטעין משאוי שנפל מעליו: **עמו.** עם בעליו, אבל אם הלך וישב לו, ואמר לו הואיל ועליך מצוה אם רצית לטעון טעון, פטור:
@580 **לא יהיה כלי גבר על אשה.** שתהא דומה לאיש כדי שתלך בין האנשים, שאין זו אלא לשם ניאוף: **ולא ילבש גבר שמלת אשה.** לילך ולישב בין הנשים. דבר אחר שלא ישיר שער הערוה ושער של בית השחי: **כי תועבת.** לא אסרה תורה אלא לבוש המביא לידי תועבה:
@581 **כי יקרא.** פרט למזמן: **לא תקח האם.** בעודה על בניה:
@582 **למען ייטב לך.** אם מצוה קלה שאין בה חסרון כיס, אמרה תורה למען ייטב לך והארכת ימים, קל וחמר למתן שכרן של מצות חמורות:
@583 **כי תבנה בית חדש.** אם קימת מצות שלוח הקן סופך לבנות בית חדש ותקיים מצות מעקה, שמצוה גוררת מצוה, ותגיע לכרם ושדה ולבגדים נאים. לכך נסמכו פרשיות הללו: **מעקה.** גדר סביב לגג, ואונקלוס תרגם תיקא כעין תיק שמשמר מה שבתוכו: **כי יפל הנפל.** ראוי זה לפול ואף על פי כן לא תתגלגל מיתתו על ידך, שמגלגלין זכות על ידי זכאי וחובה על ידי חיב:
@584 **כלאים.** חטה ושעורה וחרצן במפלת יד: **פן תקדש.** כתרגומו תסתאב. כל דבר הנתעב על האדם, בין לשבח כגון הקדש, בין לגנאי כגון אסור, נופל בו לשון קדש, כמו (ישעיה סה, ה) אל תגש בי כי קדשתיך: **המלאה.** זה מלוי ותוספת שהזרע מוסיף:
@585 **לא תחרש בשור ובחמור.** הוא הדין לכל שני מינים שבעולם, והוא הדין להנהיגם יחד קשורים זוגים בהולכת שום משא:
@586 **שעטנז.** לשון ערוב. ורבותינו פרשו שוע טווי ונווז:
@587 **גדלים תעשה לך.** אף מן הכלאים. לכך סמכן הכתוב:
@588 **ובא אליה ושנאה.** סופו:
@589 **ושם לה עלילת דברים.** עברה גוררת עברה, עבר על לא תשנא (ויקרא יט, יז) סופו לבא לידי לשון הרע: **את האשה הזאת.** מכאן שאין אומר דבר אלא בפני בעל דין:
@590 **אבי הנערה ואמה.** מי שגדלו גדולים הרעים יתבזו עליה:
@591 **ואמר אבי הנערה.** מלמד שאין רשות לאשה לדבר בפני האיש:
@592 **ופרשו השמלה.** הרי זה משל, מחורין הדברים כשמלה:
@593 **ויסרו אתו.** מלקות:
@595 **ואם אמת היה הדבר.** בעדים והתראה שזנתה לאחר ארוסין:
@596 **אל פתח בית אביה.** ראו גדולים שגדלתם: **וסקלוה אנשי עירה.** במעמד כל אנשי עירה: **לזנות בית אביה.** כמו בבית אביה:
@597 **ומתו גם שניהם.** להוציא מעשה חדודים שאין האשה נהנית מהם: **גם.** לרבות הבאים מאחריהם. דבר אחר גם שניהם לרבות את הולד, שאם היתה מעברת אין ממתינין לה עד שתלד:
@598 **ומצאה איש בעיר.** לפיכך שכב עמה, פרצה קוראה לגנב. הא אלו ישבה בביתה לא אירע לה:
@601 **כי כאשר יקום** וגו' **.** לפי פשוטו זהו משמעו, כי אנוסה היא ובחזקה עמד עליה כאדם העומד על חברו להרגו. ורבותינו דרשו בו הרי זה בא ללמד ונמצא למד וכו' :
@605 **לא יקח.** אין לו בה לקוחין ואין קדושין תופסין בה: **ולא יגלה כנף אביו.** שומרת יבם של אביו הראויה לאביו. והרי כבר הזהר עליה משום (ויקרא יח, יד) ערות אחי אביך, אלא לעבור על זו בשני לאוין ולסמוך לה (פסוק ג) לא יבא ממזר, ללמד שאין ממזר אלא מחיבי כריתות וקל וחמר מחיבי מיתות בית דין, שאין בעריות מיתת בית דין שאין בה כרת:
@606 **פצוע דכא.** שנפצעו או שנדכאו ביצים שלו: **וכרות שפכה.** שנכרת הגיד ושוב אינו יורה קלוח זרע אלא שופך ושותת ואינו מוליד:
@607 **לא יבא ממזר בקהל ה'.** לא ישא ישראלית:
@608 **לא יבא עמוני.** לא ישא ישראלית:
@609 **על דבר.** על העצה שיעצו אתכם להחטיאכם: **בדרך.** כשהייתם בטרוף:
@611 **לא תדרש שלמם.** מכלל שנאמר (פסוק יז) עמך ישב בקרבך יכול אף זה כן, תלמוד לומר לא תדרש שלמם:
@612 **לא תתעב אדמי.** לגמרי ואף על פי שראוי לך לתעבו שיצא בחרב לקראתך: **לא תתעב מצרי.** מכל וכל, אף על פי שזרקו זכוריכם ליאור. מה טעם, שהיו לכם אכסניא בשעת הדחק. לפיכך. ט **בנים אשר יולדו להם דור שלישי.** ושאר האמות מתרין מיד. הא למדת שהמחטיא לאדם קשה לו מן ההורגו, שההורגו הורגו בעולם הזה, והמחטיאו מוציאו מן העולם הזה ומן העולם הבא, לפיכך אדום שקדמם בחרב לא נתעב וכן מצרים שטבעום, ואלו שהחטיאום נתעבו:
@614 **כי תצא** וגו' **ונשמרת.** שהשטן מקטרג בשעת הסכנה:
@615 **מקרה לילה.** דבר הכתוב בהוה: **ויצא אל מחוץ למחנה.** זו מצות עשה: **לא יבא אל תוך המחנה.** זו מצות לא תעשה. ואסור לכנס למחנה לויה, וכל שכן למחנה שכינה:
@616 **והיה לפנות ערב.** סמוך להערב שמשו יטבול, שאינו טהור בלא הערב שמש:
@617 **ויד תהיה לך.** כתרגומו ואתר, כמו (במדבר ב, יז) איש על ידו: **מחוץ למחנה.** חוץ לענן:
@618 **על אזנך.** לבד משאר כלי תשמישך: **אזנך.** כמו כלי זינך:
@619 **ולא יראה בך.** הקדוש ברוך הוא ערות דבר:
@620 **לא תסגיר עבד.** כתרגומו. דבר אחר אפלו עבד כנעני של ישראל שברח מחוצה לארץ לארץ ישראל:
@622 **לא תהיה קדשה.** מפקרת, מקדשת ומזמנת לזנות: **ולא יהיה קדש.** מזמן למשכב זכור. ואונקלוס תרגם לא תהי אתתא מבנת ישראל לגבר עבד, שאף זו מפקרת לבעילת זנות היא, מאחר שאין קדושין תופסין לו בה, שהרי הקשו לחמור, שנאמר (בראשית כב, ה) שבו לכם פה עם החמור, עם הדומה לחמור. ולא יסב גברא מבני ישראל אתתא אמא, שאף הוא נעשה קדש על ידה, שכל בעילותיו בעילות זנות שאין קדושין תופסין לו בה:
@623 **אתנן זונה.** נתן לה טלה באתננה פסול להקרבה: **ומחיר כלב.** החליף שה בכלב: **גם שניהם.** לרבות שנוייהם, כגון חטים ועשאן סלת:
@624 **לא תשיך.** אזהרה ללוה שלא יתן רבית למלוה, ואחר כך אזהרה למלוה (ויקרא כה, לז) את כספך לא תתן לו בנשך:
@625 **לנכרי תשיך.** ולא לאחיך. לאו הבא מכלל עשה, עשה, לעבור עליו בשני לאוין ועשה:
@626 **לא תאחר לשלמו.** שלשה רגלים. ולמדוהו רבותינו מן המקרא:
@628 **מוצא שפתיך תשמר ועשית.** לתן עשה על לא תעשה:
@629 **כי תבא בכרם רעך.** בפועל הכתוב מדבר: **כנפשך.** כמה שתרצה: **שבעך.** ולא אכילה גסה: **ואל כליך לא תתן.** מכאן שלא דברה תורה אלא בשעת הבציר, בזמן שאתה נותן לכליו של בעל הבית, אבל אם שכרו לעדור ולקשקש, אינו אוכל:
@630 **כי תבא בקמת רעך.** אף זו בפועל הכתוב מדבר:
@631 **כי מצא בה ערות דבר.** מצוה עליו לגרשה שלא תמצא חן בעיניו:
@632 **לאיש אחר.** אין זה בן זוגו של ראשון, הוא הוציא רשעה מתוך ביתו וזה הכניסה:
@633 **ושנאה האיש האחרון.** הכתוב מבשרו שסופו לשנאותה, ואם לאו קוברתו, שנאמר או כי ימות:
@634 **אחרי אשר הטמאה.** לרבות סוטה שנסתרה:
@635 **אשה חדשה.** שהיא חדשה לו ואפלו אלמנה, פרט למחזיר גרושתו: **ולא יעבר עליו.** דבר הצבא: **לכל דבר.** שהוא צורך הצבא, לא לספק מים ומזון ולא לתקן דרכים, אבל החוזרים מעורכי המלחמה על פי כהן, כגון בנה בית ולא חנכו או ארס אשה ולא לקחה, מספיקין מים ומזון ומתקנין את הדרכים: **יהיה לביתו.** אף בשביל ביתו, אם בנה בית וחנכו ואם נטע כרם וחללו, אינו זז מביתו בשביל צרכי המלחמה: **לביתו.** זה ביתו: **יהיה.** לרבות את כרמו: **ושמח.** ישמח את אשתו. ותרגומו ויחדי ית אתתיה. והמתרגם ויחדי עם אתתיה, טועה הוא, שאין זה תרגום של ושמח אלא של ושמח:
@636 **לא יחבל.** אם בא למשכנו על חובו בבית דין, לא ימשכננו בדברים שעושים בהן אוכל נפש: **רחים.** היא התחתונה: **ורכב.** היא העליונה:
@637 **כי ימצא.** בעדים והתראה. וכן כל כי ימצא שבתורה: **והתעמר בו.** אינו חיב עד שישתמש בו:
@638 **השמר בנגע הצרעת.** שלא תתלוש סימני טמאה, ולא תקוץ את הבהרת: **ככל אשר יורו אתכם.** אם להסגיר אם להחליט אם לטהר:
@639 **זכור את אשר עשה ה' אלהיך למרים.** אם באת להזהר שלא תלקה בצרעת, אל תספר לשון הרע. זכור העשוי למרים שדברה באחיה ולקתה בנגעים:
@640 **כי תשה ברעך.** תחוב בחברך: **משאת מאומה.** חוב של כלום:
@642 **לא תשכב בעבוטו.** לא תשכב ועבוטו אצלך:
@643 **כבוא השמש.** אם כסות לילה הוא, ואם כסות יום החזירהו בבקר, וכבר כתוב בואלה המשפטים (שמות כב, כה) עד בא השמש תשיבנו לו, כל היום תשיבנו לו וכבוא השמש תקחנו: **וברכך.** ואם אינו מברכך, מכל מקום ולך תהיה צדקה:
@644 **לא תעשק שכיר.** והלא כבר כתוב, אלא לעבור על האביון בשני לאוין לא תעשוק שכר שכיר שהוא עני ואביון, ועל העשיר כבר הזהר (ויקרא יט, יג) לא תעשק את רעך: **אביון.** התאב לכל דבר: **מגרך.** זה גר צדק: **בשעריך.** זה גר תושב האוכל נבלות: **אשר בארצך.** לרבות שכר בהמה וכלים:
@645 **ואליו הוא נשא את נפשו.** אל השכר הזה הוא נושא את נפשו למות, עלה בכבש ונתלה באילן: **והיה בך חטא.** מכל מקום, אלא שממהרין להפרע על ידי הקורא:
@646 **לא יומתו אבות על בנים.** בעדות בנים. ואם תאמר בעון בנים, כבר נאמר איש בחטאו יומתו, אבל מי שאינו איש, מת בעון אביו, הקטנים מתים בעון אבותם בידי שמים:
@647 **לא תטה משפט גר יתום.** ועל העשיר כבר הזהר (דברים טז, יט) לא תטה משפט, ושנה בעני לעבור עליו בשני לאוין, לפי שנקל להטות משפט עני יותר משל עשיר, לכך הזהיר ושנה עליו: **ולא תחבל.** שלא בשעת הלואה:
@648 **וזכרת.** על מנת כן פדיתיך לשמור חקותי אפלו יש חסרון כיס בדבר:
@649 **ושכחת עמר.** ולא גדיש. מכאן אמרו עמר שיש בו סאתים ושכחו אינו שכחה: **בשדה.** לרבות שכחת קמה ששכח מקצתה מלקצור: **לא תשוב לקחתו.** מכאן אמרו, שלאחריו שכחה, שלפניו אינו שכחה, שאינו בבל תשוב: **למען יברכך.** ואף על פי שבאת לידו שלא במתכון, קל וחמר לעושה במתכון. אמור מעתה, נפלה סלע מידו ומצאה עני ונתפרנס בה הרי הוא מתברך עליה:
@650 **לא תפאר.** לא תטול תפארתו ממנו. מכאן שמניחין פאה לאילן: **אחריך.** זו שכחה:
@651 **לא תעולל.** אם מצאת בו עוללות לא תקחנה. ואיזו היא עוללות כל שאין לה לא כתף ולא נטף. יש לה אחד מהם הרי היא לבעל הבית. וראיתי בתלמוד ירושלמי איזו היא כתף, פסיגין זה על גב זה. נטף, אלו התלויות בשדרה ויורדות:
@653 **כי יהיה ריב.** סופם להיות נגשים אל המשפט. אמור מעתה אין שלום יוצא מתוך מריבה, מי גרם ללוט לפרוש מן הצדיק הוי אומר זו מריבה: **והרשיעו את הרשע.** יכול כל המתחיבין בדין לוקין, תלמוד לומר והיה אם בן הכות הרשע, פעמים לוקה ופעמים אינו לוקה. ומי הוא הלוקה, למוד מן הענין (פסוק ד) , לא תחסם שור בדישו, לאו שלא נתק לעשה:
@654 **והפילו השפט.** מלמד שאין מלקין אותו לא עומד ולא יושב אלא מטה: **לפניו כדי רשעתו.** ולאחריו כדי שתים. מכאן אמרו, מלקין אותו שתי ידות מלאחריו ושליש מלפניו: **במספר.** ואינו נקוד במספר, למד שהוא דבוק, לומר במספר ארבעים ולא ארבעים שלמים, אלא מנין שהוא סוכם ומשלים לארבעים, והן ארבעים חסר אחת:
@655 **לא יסיף.** מכאן אזהרה למכה את חברו: **ונקלה אחיך.** כל היום קוראו רשע ומשלקה קראו אחיך:
@656 **לא תחסם שור בדישו.** דבר הכתוב בהוה והוא הדין לכל בהמה חיה ועוף העושים במלאכה שהיא בדבר מאכל. אם כן למה נאמר שור, להוציא את האדם: **בדישו.** יכול יחסמנו מבחוץ, תלמוד לומר לא תחסם שור מכל מקום, ולמה נאמר דיש, לומר לך מה דיש מיוחד דבר שלא נגמרה מלאכתו וגדולו מן הארץ, אף כל כיוצא בו, יצא החולב והמגבן והמחבץ שאין גדולו מן הארץ, יצא הלש והמקטף שנגמרה מלאכתו לחלה, יצא הבודל בתמרים ובגרוגרות שנגמרה מלאכתן למעשר:
@657 **כי ישבו אחים יחדו.** שהיתה להם ישיבה אחת בעולם, פרט לאשת אחיו שלא היה בעולמו: **יחדו.** המיוחדים בנחלה, פרט לאחיו מן האם: **ובן אין לו.** עין עליו: בן או בת, או בן הבן, או בת הבן, או בן הבת, או בת הבת:
@658 **והיה הבכור.** גדול האחים הוא מיבם אותה: **אשר תלד.** פרט לאילונית שאינה יולדת: **יקום על שם אחיו.** זה שיבם את אשתו יטול נחלת המת בנכסי אביו: **ולא ימחה שמו.** פרט לאשת סריס ששמו מחוי:
@659 **השערה.** כתרגומו לתרע בית דינא:
@660 **ועמד.** בעמידה: **ואמר.** בלשון הקדש, ואף היא דבריה בלשון הקדש:
@661 **וירקה בפניו.** על גבי קרקע: **אשר לא יבנה.** מכאן למי שחלץ שלא יחזור וייבם, דלא כתיב אשר לא בנה, אלא אשר לא יבנה, כיון שלא בנה שוב לא יבנה:
@662 **ונקרא שמו** וגו' **.** מצוה על כל העומדים שם לומר חלוץ הנעל:
@663 **כי ינצו אנשים.** סופן לבא ליד מכות, כמו שנאמר מיד מכהו. אין שלום יוצא מתוך ידי מריבה:
@664 **וקצתה את כפה.** ממון דמי בשתו. הכל לפי המביש והמתביש. או אינו אלא ידה ממש, נאמר כאן לא תחוס, ונאמר להלן בעדים זוממין (לעיל יט, יג) לא תחוס, מה להלן ממון, אף כאן ממון:
@665 **אבן ואבן.** משקלות: **גדולה וקטנה.** גדולה שמכחשת את הקטנה, שלא יהא נוטל בגדולה ומחזיר בקטנה:
@666 **לא יהיה לך.** אם עשית כן, לא יהיה לך כלום:
@667 **אבן שלמה וצדק יהיה לך.** אם עשית כן יהיה לך הרבה:
@669 **זכור את אשר עשה לך.** אם שקרת במדות ובמשקלות הוי דואג מגרוי האויב, שנאמר (משלי יא, א) מאזני מרמה תועבת ה', וכתיב בתריה בא זדון ויבא קלון:
@670 **אשר קרך בדרך.** לשון מקרה. דבר אחר לשון קרי וטמאה, שהיה מטמאן במשכב זכור. דבר אחר לשון קור וחום, צננך והפשירך מרתיחתך, שהיו כל האמות יראים להלחם בכם ובא זה והתחיל והראה מקום לאחרים. משל לאמבטי רותחת שאין כל בריה יכולה לירד בתוכה, בא בן בליעל אחד קפץ וירד לתוכה. אף על פי שנכוה, הקרה אותה בפני אחרים: **ויזנב בך.** מכת זנב, חותך מילות וזורק כלפי מעלה: **כל הנחשלים אחריך.** חסרי כח מחמת חטאם, שהיה הענן פולטן: **ואתה עיף ויגע.** עיף בצמא, דכתיב (שמות יז, ג) ויצמא שם העם למים, וכתיב אחריו ויבא עמלק: **ויגע.** בדרך: **ולא ירא.** עמלק, **אלהים' מלהרע לך** :
@671 **תמחה את זכר עמלק.** מאיש ועד אשה מעולל ועד יונק משור ועד שה (שמואל א' טו, ג) . שלא יהא שם עמלק נזכר אפלו על הבהמה, לומר בהמה זו משל עמלק היתה:
@672 **והיה כי תבוא וירשתה וישבת בה.** מגיד שלא נתחיבו בבכורים עד שכבשו את הארץ וחלקוה:
@673 **מראשית.** ולא כל ראשית, שאין כל הפרות חיבין בבכורים אלא שבעת המינין בלבד. נאמר כאן ארץ, ונאמר להלן (לעיל ח, ח) ארץ חטה ושערה וגו' , מה להלן משבעת המינים שנשתבחה בהם ארץ ישראל, אף כאן שבח ארץ ישראל שהן שבעה מינין: **זית שמן.** זית אגורי ששמנו אגור בתוכו: **ודבש.** הוא דבש תמרים: **מראשית.** אדם יורד לתוך שדהו ורואה תאנה שבכרה כורך עליה גמי לסימן ואומר הרי זו בכורים:
@674 **אשר יהיה בימים ההם.** אין לך אלא כהן שבימיך, כמו שהוא: **ואמרת אליו.** שאינך כפוי טובה: **הגדתי היום.** פעם אחת בשנה ולא שתי פעמים:
@675 **ולקח הכהן הטנא מידך.** להניף אותו. כהן מניח ידו תחת יד הבעלים ומניף:
@676 **וענית.** לשון הרמת קול: **ארמי אבד אבי.** מזכיר חסדי המקום. ארמי אבד אבי, לבן, בקש לעקור את הכל, כשרדף אחר יעקב. ובשביל שחשב לעשות, חשב לו המקום כאלו עשה, שאמות העולם חושב להם הקדוש ברוך הוא מחשבה רעה כמעשה: **וירד מצרימה.** ועוד אחרים באו עלינו לכלותנו, שאחרי זאת ירד יעקב למצרים: **במתי מעט.** בשבעים נפש:
@680 **אל המקום הזה.** זה בית המקדש: **ויתן לנו את הארץ.** כמשמעו:
@681 **והנחתו.** מגיד שנוטלו אחר הנחת הכהן ואוחזו בידו כשהוא קורא, וחוזר ומניף:
@682 **ושמחת בכל הטוב.** מכאן אמרו אין קורין מקרא בכורים אלא בזמן שמחה, מעצרת ועד החג, שאדם מלקט תבואתו ופירותיו ויינו ושמנו, אבל מהחג ואלך, מביא ואינו קורא: **אתה והלוי.** אף הלוי חיב בבכורים אם נטעו בתוך עריהם: **והגר אשר בקרבך.** מביא ואינו קורא, שאינו יכול לומר לאבותינו:
@683 **כי תכלה לעשר את כל מעשר תבואתך בשנה השלישית.** כשתגמור להפריש מעשרות של שנה השלישית, קבע זמן הבעור והוידוי בערב הפסח של שנה הרביעית, שנאמר (דברים יד, כח) מקצה שלש שנים תוציא וגו' . נאמר כאן מקץ, ונאמר להלן (שם לא, י) מקץ שבע שנים, לענין הקהל מה להלן רגל אף כאן רגל, אי מה להלן חג הסכות אף כאן חג הסכות, תלמוד לומר כי תכלה לעשר, מעשרות של שנה השלישית רגל שהמעשרות כלין בו, וזהו פסח, שהרבה אילנות יש שנלקטין אחר הסכות, נמצאו מעשרות של שלישית כלין בפסח של רביעית, וכל מי ששיהה מעשרותיו הצריכו הכתוב לבערו מן הבית: **שנת המעשר.** שנה שאין נוהג בה אלא מעשר אחד משני מעשרות שנהגו בשתי שנים שלפניה, ששנה ראשונה של שמטה נוהג בה מעשר ראשון, כמו שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל את המעשר, ומעשר שני, שנאמר (דברים יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך, הרי שני מעשרות, ובא ולמדך כאן בשנה השלישית שאין נוהג מאותן שני מעשרות אלא אחד, ואיזה, זה מעשר ראשון. ותחת מעשר שני תן מעשר עני שנאמר כאן **ונתת ללוי.** את אשר לו, הרי מעשר ראשון. **לגר ליתום ולאלמנה.** זה מעשר עני: **ואכלו בשעריך ושבעו.** תן להם כדי שבען מכאן אמרו אין פוחתין לעני בגורן פחות מחצי קב חטים וכו' :
@684 **ואמרת לפני ה' אלהיך.** התודה שנתת מעשרותיך: **בערתי הקדש מן הבית.** זה מעשר שני ונטע רבעי, ולמדך שאם שיהה מעשרותיו של שתי שנים ולא העלם לירושלים, שצריך להעלותם עכשיו: **וגם נתתיו ללוי.** זה מעשר ראשון. וגם, לרבות תרומה ובכורים: **ולגר ליתום ולאלמנה.** זה מעשר עני: **ככל מצותך.** נתתים כסדרן ולא הקדמתי תרומה לבכורים, ולא מעשר לתרומה ולא שני לראשון, שהתרומה קרויה ראשית, שהיא ראשונה משנעשה דגן, וכתיב מלאתך ודמעך לא תאחר (שמות כב, כח) , לא תשנה את הסדר: **לא עברתי ממצותיך.** לא הפרשתי ממין על שאינו מינו ומן החדש על הישן: **ולא שכחתי.** מלברך על הפרשת מעשרות:
@685 **לא אכלתי באני ממנו.** מכאן שאסור לאונן: **ולא בערתי ממנו בטמא.** בין שאני טמא והוא טהור, בין שאני טהור והוא טמא. והיכן הזהר על כך (לעיל יב, יז) לא תוכל לאכל בשעריך. זו אכילת טמאה, כמו שנאמר בפסולי המקדשים (לעיל טו, כב) בשעריך תאכלנו הטמא והטהור וגו' , אבל זה, לא תוכל לאכול דרך אכילת שעריך האמור במקום אחר: **ולא נתתי ממנו למת.** לעשות לו ארון ותכריכין: **שמעתי בקול ה' אלהי.** הביאותיו לבית הבחירה: **עשיתי ככל אשר צויתני.** שמחתי ושמחתי בו:
@686 **השקיפה ממעון קדשך.** עשינו מה שגזרת עלינו, עשה אתה מה שעליך לעשות, שאמרת (ויקרא כו, ג) אם בחקתי תלכו ונתתי גשמיכם בעתם: **אשר נתתה לנו כאשר נשבעת לאבתינו.** לתת לנו וקימת ארץ זבת חלב ודבש:
@687 **היום הזה ה' אלהיך מצוך.** בכל יום יהיו בעיניך חדשים, כאלו בו ביום נצטוית עליהם: **ושמרת ועשית אותם.** בת קול מברכתו הבאת בכורים היום, תשנה לשנה הבאה:
@688 **האמרת.** והאמירך (פסוק יח) אין להם עד מוכיח במקרא. ולי נראה שהוא לשון הפרשה והבדלה. הבדלתי לך מאלהי הנכר להיות לך לאלהים, והוא הפרישך אליו מעמי הארץ להיות לו לעם סגלה. ומצאתי להם עד, והוא לשון תפארת, כמו (תהלים צ''ד) יתאמרו כל פועלי און:
@689 **כאשר דבר לך.** (שמות יט, ה) והייתם לי סגלה:
@690 **ולהיתך עם קדש** וגו' **כאשר דבר.** (ויקרא כ, כו) והייתם לי קדושים:
@691 **שמר את כל המצוה.** לשון הוה גרדנ''ט בלע''ז (בעאבאכטענד) :
@692 **והקמת לך.** בירדן ואחר כך תוציא משם אחרות ותבנה מהן מזבח בהר עיבל. נמצאת אתה אומר, שלשה מיני אבנים היו, שנים עשר בירדן, וכנגדן בגלגל, וכנגדן בהר עיבל, כדאיתא במסכת סוטה (ל''ה) :
@698 **באר היטב.** בשבעים לשון:
@699 **הסכת.** כתרגומו: **היום הזה נהיית לעם.** בכל יום יהיו בעיניך כאלו היום באת עמו בברית:
@702 **לברך את העם.** כדאיתא במסכת סוטה (לב, א) ששה שבטים עלו לראש הר גרזים, וששה לראש הר עיבל, והכהנים והלוים והארון למטה באמצע. הפכו לוים פניהם כלפי הר גרזים ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' ואלו ואלו עונין אמן. חזרו והפכו פניהם כלפי הר עיבל ופתחו בקללה ואומרים, (פסוק טו) ארור האיש אשר יעשה פסל וגו' , וכן כלם עד (פסוק כו) ארור אשר לא יקים:
@706 **מקלה אביו.** מזלזל, לשון (לעיל כ''ה) ונקלה אחיך:
@707 **מסיג גבול.** מחזירו לאחוריו וגונב את הקרקע, לשון (ישעיה נט) והסג אחור:
@708 **משגה עור.** הסומא בדבר ומשיאו עצה רעה:
@714 **מכה רעהו בסתר.** על לשון הרע הוא אומר. ראיתי ביסודו של רבי משה הדרשן, אחד עשר ארורים יש כאן, כנגד אחד עשר שבטים. וכנגד שמעון לא כתב ארור, לפי שלא היה בלבו לברכו לפני מותו כשברך שאר השבטים, לכך לא רצה לקללו:
@716 **אשר לא יקים.** כאן כלל את כל התורה כלה וקבלוה עליהם באלה ובשבועה:
@720 **שגר אלפיך.** ולדות בקרך שהבהמה משגרת ממעיה: **ועשתרות צאנך.** כתרגומו. ורבותינו אמרו למה נקרא שמם עשתרות, שמעשירות את בעליהן ומחזיקות אותם כעשתרות הללו שהן סלעים חזקים:
@721 **ברוך טנאך.** פירותיך. דבר אחר טנאך דבר לח שאתה מסנן בסלים: **ומשארתך.** דבר יבש שנשאר בכלי ואינו זב:
@722 **ברוך אתה בבאך וברוך אתה בצאתך.** שתהא יציאתך מן העולם בלא חטא כביאתך לעולם:
@723 **ובשבעה דרכים ינוסו לפניך.** כן דרך הנבהלים לברוח, מתפזרין לכל צד:
@736 **המארה.** חסרון כמו (ויקרא יג, נב) צרעת ממארת: **המהומה.** שגוש קול בהלות:
@738 **בשחפת.** שבשרו נשחף ונפוח: **ובקדחת.** לשון (דברים לב, כב) כי אש קדחה באפי והיא אש של חולים מלויי''ד בלע''ז (פיעבערהימצע) שהיא חמה מאד: **ובדלקת.** חמה יותר מקדחת, ומיני חלאים הם: **ובחרחר.** חולי המחממו תוך הגוף וצמא תמיד למים ובלע''ז אישרדימינ''ט לשון (איוב ל, ל) ועצמי חרה מני חרב (ירמי' ו, כט) נחר מפוח מאש: **ובחרב.** יביא עליך גיסות: **שדפון וירקון.** מכות תבואה שבשדות: **שדפון.** רוח קדים אשלי''דה בלע''ז (זאננפערבראננט) : **ירקון.** יובש ופני התבואה מכסיפין ונהפכין לירקון קמ''א בלע''ז : **עד אבדך.** תרגום עד דתיבד, כלומר עד אבוד אותך שתכלה מאליך:
@739 **והיו שמיך אשר על ראשך נחשת.** קללות הללו משה מפי עצמו אמרן, ושבהר סיני מפי הקדוש ברוך הוא אמרן כמשמען, ושם נאמר (ויקרא כו, יד) ואם לא תשמעו לי, (ויקרא כו, כא) ואם תלכו עמי קרי, וכן הוא אומר (פסוק טו) בקול ה' אלהיך (פסוק כא) ידבק ה' בך, (פסוק כב) יככה ה'. הקל משה בקללותיו לאמרן בלשון יחיד. וגם כן בקללה זו הקל, שבראשונות הוא אומר (ויקרא כו, יט) את שמיכם כברזל ואת ארצכם כנחושה, שלא יהיו השמים מזיעין כדרך שאין הברזל מזיע, ומתוך כך יהא חורב בעולם והארץ תהא מזיעה כדרך שהנחשת מזיע, והיא מרקבת פירותיה, וכאן הוא אומר שמיך נחשת וארצך ברזל, שיהיו שמים מזיעין אף על פי שלא יריקו מטר, מכל מקום לא יהיה חורב של אבדן בעולם, והארץ לא תהא מזיעה כדרך שאין הברזל מזיע, ואין הפרות מרקיבין. ומכל מקום קללה היא, בין שהיא כנחשת בין שהיא כברזל, לא תוציא פרות, וכן השמים לא יריקו מטר:
@740 **מטר ארצך אבק ועפר.** זיקא דבתר מטרא, מטר יורד ולא כל צרכו ואין בו כדי להרביץ את העפר, והרוח באה ומעלה את האבק ומכסה את עשב הזרעים שהן לחים מן המים, ונדבק בהם ונעשה טיט ומתיבש, ומרקיבין:
@741 **לזעוה.** לאימה ולזיע, שיזועו כל שומעי מכותיך ממך, ויאמרו אוי לנו, שלא יבוא עלינו כדרך שבא על אלו:
@743 **בשחין מצרים.** רע היה מאד, לח מבחוץ ויבש מבפנים, כדאיתא בבכורות (מא, א) : **גרב.** שחין לח: **חרס.** שחין יבש כחרס:
@744 **ובתמהון לבב.** אוטם הלב אשטורדישו''ן בלע''ז [תדהמה] :
@745 **עשוק.** בכל מעשיך יהיה ערעור:
@746 **ישגלנה.** לשון שגל, פלגש, והכתוב כנהו לשבח, ישכבנה, ותקון סופרים הוא זה: **תחללנו.** בשנה הרביעית לאכול פריו:
@748 **וכלות אליהם.** מצפות אליהם שישובו ואינם שבים. כל תוחלת שאינה באה, קרויה כליון עינים:
@753 **לשמה.** אשטורדישו''ן [תדהמה] כל הרואה אותך ישום עליך: **למשל.** כשתבא מכה רעה על אדם, יאמרו זו דומה למכת פלוני: **ולשנינה.** לשון (לעיל ו, ז) ושננתם, ידברו בך, וכן תרגומו ולשועי, לשון ספור, ואשתעי:
@754 **יחסלנו.** יכלנו, ועל שם כך נקרא חסיל, שמכלה את הכל:
@756 **כי ישל.** ישיר פירותיו, לשון (לעיל יט, ה) ונשל הברזל:
@758 **יירש הצלצל.** יעשנו הארבה רש מן הפרי: **יירש.** יעני: **צלצל.** מין ארבה. ואי אפשר לפרש יירש לשון ירשה, שאם כן היה לו לכתוב יירש, ולא לשון הורשה וגירושין, שאם כן היה לכתוב יוריש:
@763 **מרב כל.** בעוד שהיה לך כל טוב:
@765 **כאשר ידאה הנשר.** פתאום, ודרך מצלחת, ויקלו סוסיו: **לא תשמע לשונו.** לא תכיר לשונו, וכן (ברא' מא) תשמע חלום לפתר אותו. וכן (שם מב) כי שומע יוסף אינטינדר''י בלע''ז [להבין] :
@768 **עד רדת חמתיך.** לשון רדוי וכבוש:
@769 **ואכלת פרי בטנך בשר בניך** וגו' **במצור.** מחמת שיהיו צרין על העיר ויהיה שם מצוק, עקת רעבון:
@770 **הרך בך והענג.** הוא הרך הוא הענוג, לשון פנוק. ומהתענג ומרך מוכיח עליהם ששניהם אחד, אף על פי שהוא מפנק ודעתו קצה בדבר מאוס, ימתק לו לרעבונו בשר בניו ובנותיו עד כי תרע עינו בבניו הנותרים מתת לאחד מהם מבשר בניו אחיהם אשר יאכל. דבר אחר הרך בך הרחמני ורך הלבב, מרב רעבנותם, יתאכזרו ולא יתנו מבשר בניהם השחוטים לבניהם הנותרים:
@772 **תרע עינה באיש חיקה ובבנה ובבתה.** הגדולים:
@773 **ובשליתה.** בניה הקטנים. בכלן תהא עינה צרה כשתאכל את האחד מלתן לאשר אצלה מן הבשר. נט **והפלא ה' את מכתך.** מפלאות ומבדלות משאר מכות: **ונאמנות.** ליסרך לקים שליחותן:
@776 **אשר יגרת מפניהם.** מפני המכות, כשהיו ישראל רואים מכות משנות הבאות על מצרים, היו יראים מהם שלא יבואו גם עליהם, תדע, שכן כתיב (שמות טו, כו) אם שמע וגו' כל המחלה אשר שמתי במצרים לא אשים עליך, אין מיראין את האדם אלא בדבר שהוא יגור ממנו:
@777 **יעלם.** לשון עליה:
@778 **ונשארתם במתי מעט תחת** וגו' **.** מועטין חלף מרבין:
@779 **כן ישיש ה'.** את אויביכם עליכם להאביד וגו' : **ונסחתם.** לשון עקירה וכן (משלי טו, כה) בית גאים יסח ה':
@780 **ועבדת שם אלהים אחרים.** כתרגומו, לא עבודת אלהות ממש, אלא מעלים מס וגולגליות לכומרי עבודה זרה:
@781 **לא תרגיע.** לא תנוח, כמו (ישעיה כח, יב) וזאת המרגעה: **לב רגז.** לב חרד, כתרגומו דחל, כמו (שם יד, ט) שאול מתחת רגזה לך, (שמות טו, יד) שמעו עמים ירגזון, (שמואל ב' כב, ח) מוסדות השמים ירגזו: **וכליון עינים.** מצפה לישועה ולא תבא:
@782 **חייך תלאים לך.** על הספק, כל ספק קרוי תלוי, שמא אמות היום בחרב הבאה עלינו. ורבותינו דרשו זה הלוקח תבואה מן השוק: **ולא תאמין בחייך.** זה הסומך על הפלטר:
@783 **בבקר תאמר מי יתן ערב.** ויהיה הערב של אמש. **ובערב תאמר מי יתן בקר.** של שחרית, שהצרות מתחזקות תמיד, וכל שעה מרבה קללתה משלפניה:
@784 **באניות.** בספינות, בשביה: **והתמכרתם שם לאיביך.** אתם מבקשים להיות נמכרים להם לעבדים ולשפחות: **ואין קנה.** כי יגזרו עליך הרג וכליון: **והתמכרתם.** בלע''ז איפורוונדרי''ץ וו''ש [ותמכרו עצמכם] . ולא יתכן לפרש והתמכרתם לשון ונמכרתם על ידי מוכרים אחרים, מפני שנאמר אחריו ואין קונה:
@785 **לכרת את בני ישראל.** שיקבלו עליהם את התורה באלה ובשבועה: **מלבד הברית.** קללות שבתורת כהנים שנאמרו בסיני:
@788 **ולא נתן ה' לכם לב לדעת.** להכיר את חסדי הקדוש ברוך הוא ולדבק בו: **עד היום הזה.** שמעתי שאותו היום שנתן משה ספר התורה לבני לוי, כמו שכתוב (לקמן לא, ט) ויתנה אל הכהנים בני לוי, באו כל ישראל לפני משה ואמרו לו, משה רבינו, אף אנו עמדנו בסיני וקבלנו את התורה ונתנה לנו, ומה אתה משליט את בני שבטך עליה, ויאמרו לנו יום מחר לא לכם נתנה, לנו נתנה. ושמח משה על הדבר, ועל זאת אמר להם היום הזה נהיית לעם וגו' (לעיל כז, ט) , היום הזה הבנתי שאתם דבקים וחפצים במקום:
@791 **ותבאו אל המקום הזה.** עתה אתם רואים עצמכם בגדלה וכבוד, אל תבעטו במקום ואל ירום לבבכם, ושמרתם את דברי הברית הזאת. דבר אחר ולא נתן ה' לכם לב לדעת, שאין אדם עומד על סוף דעתו של רבו וחכמת משנתו עד ארבעים שנה, ולפיכך לא הקפיד עליכם המקום עד היום הזה, אבל מכאן ואלך יקפיד ולפיכך (פסוק ח) **ושמרתם את דברי הברית הזאת** וגו' :
@794 **אתם נצבים.** מלמד שכנסם משה לפני הקדוש ברוך הוא ביום מותו להכניסם בברית: **ראשיכם שבטיכם.** ראשיכם לשבטיכם: **זקניכם ושטריכם.** החשוב חשוב קודם, ואחר כך כל איש ישראל:
@795 **מחטב עציך.** מלמד שבאו כנענים להתגיר בימי משה, כדרך שבאו גבעונים בימי יהושע. וזהו האמור בגבעונים (יהושע ט, ד) ויעשו גם המה בערמה, ונתנם משה חוטבי עצים ושואבי מים:
@796 **לעברך.** להיותך עובר בברית. ולא יתכן לפרשו כמו להעבירך, אלא כמו (לעיל ד, יד) לעשותכם אותם: **לעברך בברית.** דרך העברה, כך היו כורתים ברית, עושין מחצה מכאן ומחצה מכאן ועוברים בנתים, כמו שנאמר (ירמיה לד, יח) העגל אשר כרתו לשנים ויעברו בין בתריו:
@797 **למען הקים אתך היום לו לעם.** כל כך הוא נכנס לטרוח למען קים אתך לפניו לעם: **והוא יהיה לך לאלהים.** לפי שדבר לך ונשבע לאבותיך שלא להחליף את זרעם באמה אחרת, לכך הוא אוסר אתכם בשבועות הללו, שלא תקניטוהו אחר שהוא אינו יכול להבדל מכם. עד כאן פרשתי לפי פשוטו של פרשה. ומדרש אגדה, למה נסמכה פרשת אתם נצבים לקללות, לפי ששמעו ישראל מאה קללות חסר שתים, חוץ ממ''ט שבתורת כהנים, הוריקו פניהם ואמרו מי יוכל לעמוד באלו, התחיל משה לפיסם אתם נצבים היום, הרבה הכעסתם למקום ולא עשה אתכם כליה והרי אתם קימים לפניו: **היום.** כיום הזה שהוא קים והוא מאפיל ומאיר, כך האיר לכם וכך עתיד להאיר לכם, והקללות והיסורין מקימין אתכם ומציבין אתכם לפניו. ואף הפרשה של מעלה מזו פיוסין הם (לעיל פסוק א') , אתם ראיתם את כל אשר עשה. דבר אחר, אתם נצבים. לפי שהיו ישראל יוצאין מפרנס לפרנס ממשה ליהושע, לפיכך עשה אותם מצבה כדי לזרזם. וכן עשה יהושע, וכן שמואל (שמואל א' יב, ז) התיצבו ואשפטה אתכם, כשיצאו מידו ונכנסו לידו של שאול:
@799 **ואת אשר איננו פה.** ואף עם דורות העתידים להיות:
@800 **כי אתם ידעתם** וגו' **ותראו את שקוציהם.** לפי שראיתם האמות עובדי עבודה זרה ושמא השיא לב אחד מכם אותו ללכת אחריהם, פן יש בכם וגו' (פסוק יז) לפיכך אני צריך להשביעכם:
@801 **ותראו את שקוציהם.** על שם שהם מאוסים כשקצים: **גלליהם.** שמסרחים ומאוסין כגלל: **עץ ואבן.** אותן של עצים ושל אבנים ראיתם בגלוי, לפי שאין הגוים יראים שמא יגנבו, אבל של כסף וזהב, עמהם, בחדרי משכיתם הם, לפי שהם יראים שמא יגנבו:
@802 **פן יש בכם.** שמא יש בכם: **אשר לבבו פנה היום.** מלקבל עליו הברית: **שרש פרה ראש ולענה.** שרש מגדל עשב מר כגידין, שהם מרים, כלומר מפרה ומרבה רשע בקרבכם:
@803 **והתברך בלבבו.** לשון ברכה, יחשב בלבו ברכת שלום לעצמו לאמר, לא יבואוני קללות הללו, אך שלום יהיה לי: **והתברך.** בינדיר''א שי''י בלע''ז [יברך את עצמו] , כמו והתגלח והתפלל: **בשררות לבי אלך.** במראית לבי, כמו (במדבר כד, יז) אשורנו ולא קרוב, כלומר מה שלבי רואה לעשות: **למען ספות הרוה.** לפי שאוסיף לו פרענות על מה שעשה עד הנה בשוגג והייתי מעביר עליהם, וגורם עתה שאצרפם עם המזיד ואפרע ממנו הכל. וכן תרגם אנקלוס בדיל לאוספא ליה חטאי שלותא על זדנותא, שאוסיף לו אני השגגות על הזדונות: **הרוה.** שוגג שהוא עושה כאדם שכור שלא מדעת: **הצמאה.** שהוא עושה מדעת ובתאוה:
@804 **יעשן אף ה'.** על ידי כעס הגוף מתחמם והעשן יוצא מן האף, וכן (ש''ב כב, ט) עלה עשן באפו, ואף על פי שאין זו לפני המקום, הכתוב משמיע את האזן כדרך שהיא רגילה ויכולה לשמוע, כפי דרך הארץ: **וקנאתו.** לשון חמה אנפרטמינ''ט [חמה] אחיזת לבישת נקמה, ואינו מעביר על המדה:
@805 **הכתובה בספר התורה הזה.** ולמעלה הוא אומר (לעיל כח, סא) בספר התורה הזאת גם כל חלי וכל מכה וגו' , הזאת, לשון נקבה, מוסב על התורה. הזה, לשון זכר, מוסב על הספר, ועל ידי פסוק הטעמים הן נחלקין לשתי לשונות, בפרשת הקללות הטפחא נתונה תחת בספר, והתורה הזאת דבוקים זה לזה, לכך אמר הזאת, וכאן הטפחה נתונה תחת התורה, נמצא ספר התורה דבוקים זה לזה, לפיכך לשון זכר נופל אחריו, שהלשון נופל על הספר:
@810 **לא ידעום.** לא ידעו בהם גבורת אלהות: **ולא חלק להם.** לא נתנם לחלקם. ואונקלוס תרגם ולא אוטיבא להון, לא הטיבו להם שום טובה, ולשון לא חלק אותו אלוה שבחרו להם, לא חלק להם שום נחלה ושום חלק:
@812 **ויתשם ה'.** כתרגומו וטלטלנון, וכן (ירמיה יב, יד) הנני נותשם מעל אדמתם:
@813 **הנסתרת לה' אלהינו.** ואם תאמרו מה בידינו לעשות, אתה מעניש את הרבים על הרהורי היחיד, שנאמר (פסוק יז) פן יש בכם איש וגו' , ואחר כך (פסוק כא) וראו את מכות הארץ ההיא, והלא אין אדם יודע טמונותיו של חברו, אין אני מעניש אתכם על הנסתרות, שהן לה' אלהינו והוא יפרע מאותו יחיד, אבל הנגלות' לנו ולבנינו לבער הרע מקרבנו, ואם לא נעשה דין בהם יענשו הרבים. נקוד על לנו ולבנינו, לדרוש, שאף על הנגלות לא ענש את הרבים עד שעברו את הירדן, משקבלו עליהם את השבועה בהר גרזים ובהר עיבל, ונעשו ערבים זה לזה:
@816 **ושב ה' אלהיך את שבותך.** היה לו לכתוב והשיב את שבותך, רבותינו למדו מכאן שהשכינה כביכול שרויה עם ישראל בצרת גלותם, וכשנגאלין הכתיב גאלה לעצמו, שהוא ישוב עמהם. ועוד יש לומר, שגדול יום קבוץ גליות ובקשי, כאלו הוא עצמו צריך להיות אוחז בידיו ממש איש איש ממקומו, כענין שנאמר (ישעיה כז, יב) ואתם תלקטו לאחד אחד בני ישראל, ואף בגליות שאר האמות מצינו כן (ירמיהו מח, מז) ושבתי שבות מואב:
@824 **לא נפלאת היא ממך.** לא מכסה היא ממך, כמו שנאמר (דברים יז, ח) כי יפלא, ארי יתכסי, (איכה א, ט) ותרד פלאים, (איוב מ, יג) ותרד במטמוניות. מכסה, חבוש בטמון:
@825 **לא בשמים היא.** שאלו היתה בשמים, היית צריך לעלות אחריה וללמדה:
@827 **כי קרוב אליך.** התורה נתנה לכם בכתב ובעל פה:
@828 **את החיים ואת הטוב.** זה תלוי בזה, אם תעשה טוב הרי לך חיים, ואם תעשה רע הרי לך המות. והכתוב מפרש והולך היאך:
@829 **אשר אנכי מצוך היום לאהבה.** הרי הטוב, ובו תלוי: **וחיית ורבית.** הרי החיים:
@830 **ואם יפנה לבבך.** הרי הרע:
@831 **כי אבד תאבדון.** הרי המות:
@832 **העדתי בכם היום את השמים ואת הארץ.** שהם קימים לעולם וכאשר תקרה אתכם הרעה יהיו עדים שאני התריתי בכם בכל זאת. דבר אחר, העידתי בכם היום את השמים וגו' , אמר להם הקדוש ברוך הוא לישראל, הסתכלו בשמים שבראתי לשמש אתכם, שמא שנו את מדתם, שמא לא עלה גלגל חמה מן המזרח והאיר לכל העולם, כענין שנאמר (קהלת א, ה) וזרח השמש ובא השמש, הסתכלו בארץ שבראתי לשמש אתכם, שמא שנתה מדתה, שמא זרעתם אותה ולא צמחה, או שמא זרעתם חטים והעלתה שעורים, ומה אלו שנעשו לא לשכר ולא להפסד אם זוכין אין מקבלין שכר ואם חוטאין אין מקבלין פרענות, לא שנו את מדתם, אתם, שאם זכיתם תקבלו שכר, ואם חטאתם תקבלו פרענות על אחת כמה וכמה: **ובחרת בחיים.** אני מורה לכם שתבחרו בחלק החיים, כאדם האומר לחברו בחר לך חלק יפה בנחלתי, ומעמידו על חלק היפה ואומר לו, את זה ברור לך, ועל זה נאמר (תהלים טז, ה) ה' מנת חלקי וכוסי אתה תומיך גורלי, הנחת ידי על גורל הטוב לומר את זה קח לך:
@834 **וילך משה.** וגו' :
@835 **אנכי היום.** היום מלאו ימי ושנותי ביום זה נלדתי וביום זה אמות: **לא אוכל עוד לצאת ולבא.** יכול שתשש כחו, תלמוד לומר (דברים לד, ז) לא כהתה עינו ולא נס לחה. אלא מהו לא אוכל, איני רשאי, שנטלה ממני הרשות ונתנה ליהושע. דבר אחר, לצאת ולבא בדברי תורה, מלמד שנסתמו ממנו מסורות ומעינות החכמה: **וה' אמר אלי.** זהו פרוש לא אוכל עוד לצאת ולבא, לפי שה' אמר אלי:
@839 **לא ירפך.** לא יתן לך רפיון להיות נעזב ממנו:
@840 **כי אתה תבוא את העם הזה.** ארי את תיעול עם עמא הדין. משה אמר לו ליהושע, זקנים שבדור יהיו עמך, הכל לפי דעתן ועצתן, אבל הקדוש ברוך הוא אמר ליהושע, כי אתה תביא את בני ישראל אל הארץ אשר נשבעתי להם (דברים לא, כג) , תביא על כרחם, הכל תלוי בך, טול מקל והך על קדקדן. דבר אחד לדור, ולא שני דברים לדור:
@842 **ויכתב משה** וגו' **ויתנה.** כשנגמרה כלה, נתנה לבני שבטו:
@843 **מקץ שבע שנים.** בשנה ראשונה של שמטה, בשמינית. ולמה קורא אותה שנת השמטה, שעדין שביעית נוהגת בה, בקציר של שביעית היוצא למוצאי שביעית:
@844 **תקרא את התורה הזאת.** המלך היה קורא מתחלת אלה הדברים, כדאיתא במסכת סוטה (מא, א) , על בימה של עץ שהיו עושין בעזרה:
@845 **האנשים.** ללמוד: **והנשים.** לשמוע: **והטף.** למה בא, לתת שכר למביאיהם:
@847 **ואצונו.** ואזרזנו:
@849 **נכר הארץ.** גויי הארץ:
@850 **והסתרתי פני.** כמו שאיני רואה בצרתם:
@852 **את השירה הזאת.** (לקמן לב, א) האזינו השמים עד (לב, מג) וכפר אדמתו עמו:
@853 **ונאצוני.** והכעיסוני, וכן כל נאוץ לשון כעס:
@854 **וענתה השירה הזאת לפניו לעד.** שהתריתי בו בתוכה על כל המוצאות אותן: **כי לא תשכח מפי זרעו.** הרי זו הבטחה לישראל, שאין תורה משתכחת מזרעם לגמרי:
@856 **ויצו את יהושע בן נון.** מוסב למעלה כלפי שכינה, כמו שמפורש (פסוק כא) אל הארץ אשר נשבעתי (להם) :
@859 **לקח.** כמו (שמות כ) זכור, (דב' ה) שמור, (שמו''ב ג) הלוך: **מצד ארון ברית ה'.** נחלקו בו חכמי ישראל בבבא בתרא (יד, ב) . יש מהם אומרים דף היה בולט מן הארון מבחוץ ושם היה מנח. ויש אומרים מצד הלוחות היה מנח, בתוך הארון:
@861 **הקהילו אלי.** ולא תקעו אותו היום בחצוצרות להקהיל את הקהל, לפי שנאמר (במדבר י, ב) עשה לך, ולא השליט יהושע עליהם בחייו של משה. ואף בחייו נגנזו קודם יום מותו, לקים מה שנאמר (קהלת ח, ח) ואין שלטון ביום המות: **ואעידה בם את השמים ואת הארץ.** ואם תאמר הרי כבר העיד למעלה (לעיל ל, יט) העידתי בכם היום וגו' , התם לישראל אמר, אבל לשמים ולארץ לא אמר, ועכשיו בא לומר האזינו השמים וגו' :
@862 **אחרי מותי כי השחת תשחתון.** והרי כל ימי יהושע לא השחיתו, שנאמר (יהושע כד, לא) ויעבדו בני ישראל את ה' כל ימי יהושע, מכאן שתלמידו של אדם חביב עליו כגופו, שכל זמן שיהושע חי נראה למשה כאלו הוא חי:
@864 **האזינו השמים.** שאני מתרה בהם בישראל ותהיו אתם עדים בדבר (לעיל ל, יט) שכך אמרתי להם שאתם תהיו עדים, וכן ותשמע הארץ. ולמה העיד בהם שמים וארץ, אמר משה אני בשר ודם, למחר אני מת, אם יאמרו ישראל לא קבלנו עלינו הברית מי בא ומכחישם, לפיכך העיד בהם שמים וארץ, עדים שהן קימים לעולם. ועוד, שאם יזכו, יבואו העדים ויתנו שכרם, הגפן תתן פריה, והארץ תתן יבולה, והשמים יתנו טלם. ואם יתחיבו, תהיה בהם יד העדים תחלה (לעיל יא, יז) , ועצר את השמים ולא יהיה מטר והאדמה לא תתן את יבולה, ואחר כך ואבדתם מהרה על ידי האמות:
@865 **יערף כמטר לקחי.** זו היא העדות שתעידו שאני אומר בפניכם, תורה נתתי לישראל שהיא חיים לעולם כמטר זה שהוא חיים לעולם, כאשר יערפו השמים טל ומטר: **יערף.** לשון נטיפה וכן (לקמן לג, כח) יערפו טל, (תהלים סה, יב) ירעפון דשן: **תזל כטל.** שהכל שמחים בו, לפי שהמטר יש שהן עצבים, כגון הולכי דרכים ומי שהיה בורו מלא יין: **כשעירם.** לשון (תהלים קמח, ח) רוח סערה, כתרגומו כרוחי מטרא. מה הרוחות הללו מחזיקים את העשבים ומגדלין אותם, אף דברי תורה מחזיקין את לומדיהן ומגדלין אותם: **וכרביבים.** טפי מטר. ונראה לי על שם שיורה כחץ נקרא רביב, כמה דאת אמר (בראשית כא) רובה קשת: **דשא.** אדברי''ץ עטיפת הארץ מכסה בירק: **עשב.** קלח אחד קרוי עשב, וכל מין ומין לעצמו קרוי עשב:
@866 **כי שם ה' אקרא.** הרי כי משמש בלשון כאשר, כמו (ויקרא כג) כי תבאו אל הארץ, כשאקרא ואזכיר שם ה', אתם הבו גדל לאלהינו וברכו שמו. מכאן אמרו שעונין ברוך שם כבוד מלכותו אחר ברכה שבמקדש:
@867 **הצור תמים פעלו.** אף על פי שהוא חזק, כשמביא פרענות על עוברי רצונו, לא בשטף הוא מביא, כי אם בדין, כי תמים פעלו: **אל אמונה.** לשלם לצדיקים צדקתם לעולם הבא. ואף על פי שמאחר את תגמולם, סופו לאמן את דבריו: **ואין עול.** אף לרשעים משלם שכר צדקתם בעולם הזה: **צדיק וישר הוא.** הכל מצדיקים עליהם את דינו, וכך ראוי וישר להם. צדיק מפי הבריות. וישר הוא וראוי להצדיקו:
@868 **שחת לו** וגו' **.** כתרגומו חבילו להון ולא ליה: **בניו מומם.** בניו היו, והשחתה שהשחיתו היא מומם: **בניו מומם.** מומם של בניו היה ולא מומו: **דור עקש.** עקום ומעקל, כמו (מיכה ג, ט) ואת כל הישרה יעקשו, ובלשון משנה חלדה ששניה עקומות ועקושות: **ופתלתל.** אנטורטיליי''ש כפתיל הזה שגודלין אותו ומקיפין אותו סביבות הגדיל. פתלתל מן התבות הכפולות, כמו (ויקרא יג, מט) ירקרק, אדמדם, (תהלים לח, יא) סחרחר, (מלכים א' ז, כג) סגלגל:
@869 **הלי''י תגמלו זאת.** לשון תמה, וכי לפניו אתם מעציבין, שיש בידו לפרע מכם ושהטיב לכם בכל הטובות: **עם נבל.** ששכחו את העשוי להם: **ולא חכם.** להבין את הנולדות שיש בידו להטיב ולהרע: **הלא הוא אביך קנך.** שקנאך, שקננך בקן הסלעים ובארץ חזקה, שתקנך בכל מיני תקנה: **הוא עשך.** אמה באמות: **ויכננך.** אחרי כן בכל מיני בסיס וכן. מכם כהנים מכם נביאים ומכם מלכים, כרך שהכל תלוי בו:
@870 **זכר ימות עולם.** מה עשה בראשונים שהכעיסו לפניו: **בינו שנות דר ודר.** דור אנוש שהציף עליהם מי אוקינוס ודור המבול ששטפם. דבר אחר לא נתתם לבבכם על שעבר. בינו שנות דר ודר להכיר להבא שיש בידו להטיב לכם ולהנחיל לכם ימות המשיח והעולם הבא: **שאל אביך.** אלו הנביאים שנקראים אבות, כמו שנאמר באליהו (מלכים ב' ב, יב) אבי אבי רכב ישראל: **זקניך.** אלו החכמים: **ויאמרו לך.** הראשונות:
@871 **בהנחל עליון גוים.** כשהנחיל הקדוש ברוך הוא למכעיסיו את חלק נחלתן הציפן ושטפם: **בהפרידו בני אדם.** כשהפיץ דור הפלגה היה בידו להעבירם מן העולם ולא עשה כן, אלא יצב גבלת עמים קימם ולא אבדם: **למספר בני ישראל.** בשביל מספר בני ישראל שעתידים לצאת מבני שם, ולמספר שבעים נפש של בני ישראל שירדו למצרים, הציב גבולות עמים שבעים לשון:
@872 **כי חלק ה' עמו.** למה כל זאת, לפי שהיה חלקו כבוש ביניהם ועתיד לצאת. ומי הוא חלקו, עמו. ומי הוא עמו **יעקב חבל נחלתו.** והוא השלישי באבות, המשלש בשלש זכיות, זכות אבי אביו וזכות אביו וזכותו, הרי שלשה, כחבל הזה שהוא עשוי בשלשה גדילים והוא ובניו היו לו לנחלה, ולא ישמעאל בן אברהם, ולא עשו בן יצחק:
@873 **ימצאהו בארץ מדבר.** אותם מצא לו נאמנים בארץ המדבר, שקבלו עליהם תורתו ומלכותו ועלו, מה שלא עשו ישמעאל ועשו, שנאמר (לקמן לג, ב) וזרח משעיר למו הופיע מהר פארן: **ובתהו ילל ישימן.** ארץ ציה ושממה, מקום יללת תנינים ובנות יענה, אף שם נמשכו אחר האמונה, ולא אמרו למשה היאך נצא למדברות מקום ציה ושממון, כענין שנאמר (ירמיה ב, ב) לכתך אחרי במדבר: **יסבבנהו.** שם סבבם והקיפם בעננים וסבבם בדגלים לארבע רוחות וסבבן בתחתית ההר, שכפהו עליהם כגגית: **יבוננהו.** שם בתורה ובינה: **יצרנהו.** מנחש שרף ועקרב ומן האמות: **כאישון עינו.** הוא השחור שבעין, שהמאור יוצא המנו. ואונקלוס תרגם ימצאהו יספיקהו כל צרכו במדבר, כמו (במדבר יא, כב) ומצא להם, (יהושע יז, טז) לא ימצא לנו ההר: **יסבבנהו.** אשרינון סחור סחור לשכינתיה, אהל מועד באמצע וארבעה דגלים לארבע רוחות:
@874 **כנשר יעיר קנו.** ניהגם ברחמים ובחמלה, כנשר הזה רחמני על בניו ואינו נכנס לקנו פתאום, עד שהוא מקשקש ומטרף על בניו בכנפיו, בין אילן לאילן בין שוכה לחברתה, כדי שיעורו בניו, ויהא בהם כח לקבלו: **יעיר קנו.** יעורר בניו: **על גוזליו ירחף.** אינו מכביד עצמו עליהם אלא מחופף, נוגע ואינו נוגע, אף הקדוש ברוך הוא (איוב לז, כג) שדי לא מצאנהו שגיא כח, כשבא לתן תורה לא נגלה עליהם מרוח אחת אלא מארבע רוחות, שנאמר (לקמן לג, ב) ה' מסיני בא וזרח משעיר למו הופיע מהר פארן ואתה מרבבות קדש, (חבקוק ג, ג) . אלוה מתימן יבא, זו רוח רביעית: **יפרש כנפיו יקחהו.** כשבא לטלן ממקום למקום אינו נוטלן ברגליו כשאר עופות, לפי ששאר עופות יראים מן הנשר, שהוא מגביה לעוף ופורח עליהם, לפיכך נושאן ברגליו מפני הנשר, אבל הנשר אינו ירא אלא מן החץ לפיכך נושאן על כנפיו. אומר מוטב שיכנס החץ בי ולא יכנס בבני, אף הקדוש ברוך הוא (שמות יט, ד) ואשא אתכם על כנפי נשרים, כשנסעו מצרים אחריהם והשיגום על הים היו זורקים בהם חצים ואבני בליסטראות, מיד (שמות יד, יט. כ) ויסע מלאך האלהים וגו' ויבא בין מחנה מצרים וגו' :
@875 **ה' בדד ינחנו.** ניהגם במדבר בטח ובדד: **ואין עמו אל נכר.** לא היה כח באחד מכל אלהי הגוים להראות כחו ולהלחם עמהם. ורבותינו דרשוהו על העתיד, וכן תרגם אנקלוס. ואני אומר דברי תוכחה הם, להעיד השמים והארץ, ותהא השירה להם לעד שסופן לבגד ולא יזכרו הראשונות שעשה להם, ולא הנולדות שהוא עתיד לעשות להם, לפיכך צריך לישב הדבר לכאן ולכאן. וכל הענין מוסב על (פסוק ז) זכר ימות עולם בינו שנות דר ודר, כן עשה להם, וכן עתיד לעשות, כל זה היה להם לזכור:
@876 **ירכבהו על במותי ארץ.** כל המקרא כתרגומו: **ירכבהו** וגו' **.** על שם שארץ ישראל גבוה מכל הארצות: **ויאכל תנובת שדי.** אלה פרות ארץ ישראל שקלים לנוב ולהתבשל מכל פרות הארצות: **וינקהו דבש מסלע.** מעשה באחד שאמר לבנו בסיכני הבא לי קציעות מן החבית. הלך ומצא הדבש צף על פיה. אמר לו זו של דבש היא. אמר לו השקע ידך לתוכה ואתה מעלה קציעות מתוכה: **ושמן מחלמיש צור.** אלו זיתים של גוש חלב: **במותי ארץ.** לשון גבוה: **שדי.** לשון שדה: **חלמיש צור.** תקפו וחזקו של סלע. כשאינו דבוק לתבה של אחריו, נקוד חלמיש, (תהלים קיד, ח) וכשהוא דבוק, נקוד חלמיש:
@877 **חמאת בקר וחלב צאן.** זה היה בימי שלמה, שנאמר (מלכים א' ה, ג) עשרה בקר בראים ועשרים בקר רעי ומאה צאן: **עם חלב כרים.** זה היה בימי עשרת השבטים, שנאמר (עמוס ו, ד) ואוכלים כרים מצאן: **חלב כליות חטה.** זה היה בימי שלמה, שנאמר (מלכים א' ה, ב) ויהי לחם שלמה וגו' : **ודם ענב תשתה חמר.** בימי עשרת השבטים, (עמוס ו, ו) השתים במזרקי יין: **חמאת בקר.** הוא שומן הנקלט מעל גבי החלב: **וחלב צאן.** חלב של צאן, וכשהוא דבוק נקוד חלב כמו (שמות כג, יט) בחלב אמו: **כרים.** כבשים: **ואילים.** כמשמעו: **בני בשן.** שמנים היו: **כליות חטה.** חטים שמנים כחלב כליות וגסין ככוליא: **ודם ענב.** היה שותה יין טוב וטועם יין חשוב: **חמר.** יין בלשון ארמי: **חמר.** אין זה שם דבר, אלא לשון משבח בטעם אינו''ש בלע''ז . ועוד יש לפרש שני מקראות הללו אחר תרגום של אנקלוס, אשרינון על תוקפי ארעא וגו' :
@878 **עבית.** לשון עובי: **כשית.** כמו כסית, לשון (איוב טו, כז) כי כסה פניו בחלבו, כאדם ששמן מבפנים וכסליו נכפלים מבחוץ, וכן הוא אומר (שם) ויעש פימה עלי כסל: **כשית.** יש לשון קל בלשון כסוי, כמו (משלי יב, טז) וכסה קלון ערום ואם כתב כשית דגוש היה נשמע כסית את אחרים, כמו (איוב טו, כז) כי כסה פניו: **וינבל צור ישעתו.** גנהו ובזהו, כמו שנאמר (יחזקאל ח, טז) אחוריהם אל היכל ה' וגו' , אין לך נבול גדול מזה:
@879 **יקנאהו.** הבעירו חמתו וקנאתו: **בתועבת.** במעשים תעובים, כגון משכב זכור (ויקרא יח, כב) וכשפים (ויקרא יח, יב) , שנאמר בהם תועבה:
@880 **לא אלה.** כתרגומו דלית בהון צרוך, אלו היה בהם צורך לא היתה קנאה כפולה כמו עכשיו: **חדשים מקרוב באו.** אפלו האמות לא היו רגילים בהם. גוי שהיה רואה אותם, היה אומר זה צלם יהודי: **לא שערום אבתיכם.** לא יראו מהם לא עמדה שערתם מפניהם. דרך שערות האדם לעמוד מחמת יראה, כך נדרש בספרי. ויש לפרש עוד שערום לשון (ישעיה יג, כא) ושעירים ירקדו שם, שעירים הם שדים. לא עשו אבותיכם שעירים הללו:
@881 **תשי.** תשכח. ורבותינו דרשו, כשבא להיטיב לכם אתם מכעיסין לפניו ומתישים כחו מלהיטיב לכם: **אל מחללך.** מוציאך מרחם, לשון (תהלים כט, ט) יחולל אילות, (שם מח, ז) חיל כיולדה:
@883 **מה אחריתם.** מה תעלה בהם בסופם: **כי דור תהפכת המה.** מהפכין רצוני לכעס: **לא אמן בם.** אין גדולי נכרים בהם, כי הוריתים דרך טובה וסרו ממנה: **אמן.** לשון (אסתר ב, ז) ויהי אמן נורריטור''ה בלע''ז . דבר אחר אמן לשון אמונה, כתרגומו. אמרו בסיני (שמות כד, ז) נעשה ונשמע, ובשעה קלה בטלו הבטחתם ועשו העגל:
@884 **קנאוני.** הבעירו חמתי: **בלא אל.** בדבר שאינו אלוה: **בלא עם.** באמה שאין לה שם, שנאמר (ישעיה כג, יג) הן ארץ כשדים זה העם לא היה, ובעשו הוא אומר (עובדיה א, ב) בזוי אתה מאד: **בגוי נבל אכעיסם.** אלו המינים, וכן הוא אומר (תהלים יד, א) אמר נבל בלבו אין אלהים:
@885 **קדחה.** בערה: **ותיקד.** בכם עד היסוד: **ותאכל ארץ ויבלה.** ארצכם ויבולה: **ותלהט.** ירושלים המיסדת על ההרים, שנאמר (שם קכה, ב) ירושלים הרים סביב לה:
@886 **אספה עלימו רעות.** אחביר רעה על רעה לשון (ישעיה כט, א) ספו שנה על שנה, (לעיל כט, יח) ספות הרוה, (ירמיה ז, כא) עלותיכם ספו על זבחיכם. דבר אחר, אספה אכלה, כמו (בראשית יט, טו) פן תספה: **חצי אכלה בם.** כל חצי אשלים בהם. וקללה זו לפי הפרענות לברכה היא, חצי כלים והם אינם כלים:
@887 **מזי רעב.** אנקלוס תרגם, נפיחי כפן, ואין לי עד מוכיח עליו. ומשמו של רבי משה הדרשן מטולושא שמעתי שעירי רעב, אדם כחוש מגדל שער על בשרו: **מזי.** לשון ארמי שער מזיא, דהוה מהפך במזיא: **ולחמי רשף.** השדים נלחמו בהם, שנאמר (איוב ה, ז) ובני רשף יגביהו עוף, והם שדים: **וקטב מרירי.** וכריתות שד ששמו מרירי. קטב, כריתה, כמו (הושע יג, יד) אהי קטבך שאול: **ושן בהמת.** מעשה היה והיו הרחלים נושכין וממיתין: **חמת זחלי עפר.** ארס נחשים המהלכים על גחונם על העפר, כמים הזוחלים על הארץ. זחילה לשון מרוצת המים על העפר, וכן כל מרוצת דבר המשפשף על העפר והולך:
@888 **מחוץ תשכל חרב.** מחוץ לעיר תשכלם חרב גיסות: **ומחדרים אימה.** כשבורח ונמלט מן החרב, חדרי לבבו נקופים עליו מחמת אימה והוא מת והולך בה. דבר אחר ומחדרים אימה, שבבית תהיה אימת דבר, כמו שנאמר (ירמיה ט, כ) כי עלה מות בחלונינו, וכן תרגם אנקלוס. דבר אחר, מחוץ תשכל חרב על מה שעשו בחוצות, שנאמר (ירמיה יא, יג) ומספר חצות ירושלים שמתם מזבחות לבשת. ומחדרים אימה. על מה שעשו בחדרי חדרים, שנאמר (יחזק' ח, יב) אשר זקני בית ישראל עושים בחטף איש בחדרי משכיתו:
@889 **אמרתי אפאיהם.** אמרתי בלבי אפאה אותם. ויש לפרש אפאיהם, אשיתם פאה, להשליכם מעלי הפקר. ודגמתו מצינו בעזרא (נחמיה ט, כב) ותתן להם ממלכות ועממים ותחלקם לפאה, להפקר. וכן חברו מנחם. ויש פותרים אותו כתרגומו יחול רגזי עליהון, ולא יתכן, שאם כן היה לו לכתוב אאפאיהם אחת לשמוש ואחת ליסוד, כמו (ישעיה מה, ה) אאזרך, (איוב טז, ה) אאמצכם במו פי, והאל''ף התיכונה אינה ראויה בו כלל. ואונקלוס תרגם אחר לשון הבריתא השנויה בספרי, החולקת תיבה זו לשלש תיבות. אמרתי אף אי הם, אמרתי באפי אתנם כאלו אינם, שיאמרו רואיהם עליהם איה הם:
@890 **לולי כעס אויב אגור.** אם לא שכעס האויב כנוס עליהם להשחית ואם יוכל להם וישחיתם יתלה הגדלה בו ובאלהיו ולא יתלה הגדלה בי, וזהו שנאמר פן ינכרו צרימו, ינכרו הדבר לתלות גבורתי בנכרי, שאין הגדלה שלו: **פן יאמרו ידנו רמה** וגו' **.** כי אותו גוי אבד עצות המה:
@891 **ואין בהם תבונה.** שאלו היו חכמים, ישכילו זאת, איכה ירדף וגו' :
@892 **יבינו לאחריתם.** יתנו לב להתבונן לסוף פרענותם של ישראל:
@893 **איכה ירדף אחד.** ממנו אלף מישראל: **אם לא כי צורם מכרם וה' הסגירם.** מכרם ומסרם בידינו. דילבר''ר בלע''ז :
@894 **כי לא כצורנו צורם.** כל זה היה להם לאויבים להבין שהשם הסגירם ולא להם ולאלהיהם הנצחון, שהרי עד הנה לא יכלו כלום אלהיהם כנגד צורנו, כי לא כסלענו סלעם. כל צור שבמקרא לשון סלע: **ואיבינו פלילים.** ועכשיו אויבינו שופטים אותנו, הרי שצורנו מכרנו להם:
@895 **כי מגפן סדם גפנם.** מוסב למעלה. אמרתי בלבי אפאיהם ואשבית זכרם, לפי שמעשיהם מעשה סדום ועמורה: **שדמת.** שדה תבואה, כמו (חבקוק ג, יז) ושדמות לא עשה אכל, (מלכים ב' כג, ד) בשדמות קדרון: **ענבי רוש.** עשב מר: **אשכלת מררת למו.** משקה מר ראוי להם, לפי מעשיהם פרענותם. וכן תרגם אנקלוס ותשלמת עובדיהון כמררותהון:
@896 **חמת תנינם יינם.** כתרגומו. הא כמרת תניניא כס פרענותהון, הנה כמרירות נחשים כוס משתה פרענותם: **וראש פתנים.** כוסם, שהוא אכזר לנשוך. אויב אכזרי יבא ויפרע מהם:
@897 **הלא הוא כמס עמדי.** כתרגומו. כסבורים הם ששכחתי מעשיהם, כלם גנוזים ושמורים לפני: **הלא הוא.** פרי גפנם ותבואת שדמותם כמוס עמדי:
@898 **לי נקם ושלם.** עמי נכון ומזמן פרענות נקם וישלם להם כמעשיהם, הנקם ישלם להם גמולם. ויש מפרשים ושלם, שם דבר, כמו ושלום, והיא מגזרת והדבר אין בהם (ירמיה ה, יג) , כמו והדבור. ואימתי אשלם להם: **לעת תמוט רגלם.** כשתתום זכות אבותם שהן סמוכין עליו: **כי קרוב יום אידם.** משארצה להביא עליהם יום אידם קרוב ומזמן לפני להביא על ידי שלוחים הרבה: **וחש עתדות למו.** ומהר יבואו העתידות להם: **וחש.** כמו (ישעיה ה, יט) ימהר יחישה. עד כאן העיד עליהם משה דברי תוכחה להיות השירה הזאת לעד, כשתבא עליהם הפרענות, ידעו שאני הודעתים מראש. מכאן ואלך העיד עליהם דברי תנחומין שיבואו עליהם ככלות הפרענות ככל אשר אמר למעלה (ל, א ג) והיה כי יבאו עליך וגו' כל הדברים האלה הברכה והקללה וגו' ושב ה' אלהיך את שבותך וגו' :
@899 **כי ידין ה' עמו.** כשישפוט אותן ביסורין הללו האמורים עליהם, כמו (איוב לו, לא) כי בם ידין, ייסר עמים. כי, זה, אינו משמש בלשון דהא, לתת טעם לדברים של מעלה, אלא לשון תחלת דבור, כמו (ויקרא כה, ב) כי תבאו אל הארץ, כשיבואו עליהם משפטים הללו ויתנחם הקדוש ברוך הוא על עבדיו לשוב ולרחם עליהם: **יתנחם.** לשון הפך המחשבה להיטיב או להרע: **כי יראה כי אזלת יד.** כשיראה כי יד האויב הולכת וחוזקת מאד עליהם, ואפס בהם עצור ועזוב: **עצור.** נושע על ידי עוצר ומושל שיעצור בהם: **עזוב.** על ידי עוזב. עוצר הוא המושל העוצר בעם שלא ילכו מפזרים בצאתם לצבא על האויב. בלשון לע''ז מיינטינדו''ר . עצור, הוא הנושע במעצור המושל. עזוב, מחזק, כמו (נחמיה ג, ח) ויעזבו את ירושלים עד החומה, (ירמיה מט, כה) איך לא עזבה עיר תהלה. עצור מיינטינו''ד [נשלט] . עזוב אינפורצדו''ר [מבצר] :
@900 **ואמר.** הקדוש ברוך הוא עליהם: **אי אלהימו.** עבודה זרה שעבדו: **צור חסיו בו.** הסלע שהיו מתכסין בו מפני החמה והצנה, כלומר שהיו בטוחין בו להגן עליהם מן הרעה:
@901 **אשר חלב זבחימו.** היו אותן אלהות אוכלים, שהיו מקריבין לפניהם ושותין יין נסיכם: **יהי עליכם סתרה.** אותו הצור יהי לכם מחסה ומסתור:
@902 **ראו עתה.** הבינו מן הפרענות שהבאתי עליכם ואין לכם מושיע ומן התשועה שאושיעכם ואין מוחה בידי: **אני אני הוא.** אני להשפיל ואני להרים: **ואין אלהים עמדי.** עומד כנגדי למחות: **עמדי.** דגמתי וכמוני: **ואין מידי מציל.** הפושעים בי:
@903 **כי אשא אל שמים ידי.** כי בחרון אפי אשא ידי אל עצמי בשבועה: **ואמרתי חי אנכי.** לשון שבועה היא, אני נשבע חי אנכי:
@904 **אם שנותי ברק חרבי.** אם אשנן את להב חרבי, כמו (יחזקאל כא, טו) למען היה לה ברק שפלנדו''ר : **ותאחז במשפט ידי.** להניח מדת רחמים באויבי שהרעו לכם, (זכריה א, טו) אשר אני קצפתי מעט והמה עזרו לרעה. דבר אחר ותאחז ידי את מדת המשפט להחזיק בה ולנקום נקם: **אשיב נקם** וגו' **.** למדו רבותינו באגדה מתוך לשון המקרא, שאמר ותאחז במשפט ידי, לא כמדת בשר ודם מדת הקדוש ברוך הוא, מדת בשר ודם זורק חץ ואינו יכול להשיבו, והקדוש ברוך הוא זורק חציו ויש בידו להשיבם, כאלו אוחזן בידו, שהרי ברק הוא חצו, ונאמר כאן ברק חרבי ותאחז במשפט ידי, והמשפט הזה לשון פרענות הוא. בלע''ז יושטיצי''א :
@905 **אשכיר חצי מדם.** האויב: **וחרבי תאכל בשר.** בשרם: **מדם חלל ושביה.** זאת תהיה להם מעון דם חללי ישראל ושביה ששבו מהם: **מראש פרעות אויב.** מפשע תחלת פרצות האויב, כי כשהקדוש ברוך הוא נפרע מן האמות, פוקד עליהם עונם ועונות אבותיהם מראשית פרצה שפרצו בישראל:
@906 **הרנינו גוים עמו.** לאותו הזמן ישבחו האמות את ישראל ראו מה שבחה של אמה זו שדבקו בהקדוש ברוך הוא בכל התלאות שעברו עליהם ולא עזבוהו, יודעים היו בטובו ובשבחו: **כי דם עבדיו יקום.** שפיכות דמיהם כמשמעו: **ונקם ישיב לצריו.** על הגזל ועל החמס, כענין שנאמר (יואל ד, יט) מצרים לשממה תהיה ואדום למדבר שממה תהיה מחמס בני יהודה, ואומר (עובדיה א, י) מחמס אחיך יעקב וגו' : **וכפר אדמתו עמו.** ויפיס אדמתו ועמו על הצרות שעברו עליהם ושעשה להם האויב: **וכפר.** לשון רצוי ופיוס, כמו (בראשית לב, כא) אכפרה פניו, אניחניה לרגזיה: **וכפר אדמתו.** ומה היא אדמתו, **עמו.** כשעמו מתנחמים ארצו מתנחמת, וכן הוא אומר (תהלים פה, ב) רצית ה' ארצך, במה רצית ארצך, שבת שבות יעקב: בפנים אחרים היא נדרשת בספרי, ונחלקו בה ר' יהודה ור' נחמיה. ר' יהודה דורש כלה כנגד ישראל, ור' נחמיה דורש כלה כנגד האמות. רבי יהודה דורשה כלפי ישראל. **אמרתי אפאיהם, כמו שפירשתי עד ולא ה' פעל כל זאת. כי גוי אבד עצות המה.** אבדו תורתי שהיא להם עצה נכונה. **ואין בהם תבונה.** להתבונן. **איכה ירדף אחד מן האמות אלף מהם אם לא כי צורם מכרם, כי לא כצורנו צורם, הכל כמו שפרשתי עד תכליתו.** ור' נחמיה דורשה כלפי האמות. **כי גוי אבד עצות המה, כמו שפרשתי תחלה עד ואויבינו פלילים. כי מגפן סדום גפנם.** של אמות. **ומשדמת עמורה** וגו' **.** ולא ישימו לבם לתלות הגדלה בי. **ענבמו ענבי רוש.** הוא שאמר **לולי כעס אויב אגור על ישראל להרעילם ולהמרירם, לפיכך אשכלות מררת למו להלעיט אותם על מה שעשו לבני. חמת תנינם יינם.** מוכן להשקותם על מה שעושין להם. **כמוס עמדי.** אותו הכוס, שנאמר (תהלים עה, ט) כי כוס ביד ה' וגו' . **לעת תמוט רגלם.** כענין שנאמר (ישעיה כו, ו) תרמסנה רגל. **כי ידין ה' עמו.** בלשון זה משמש כי ידין בלשון דהא, ואין ידין לשון יסורין, אלא כמו כי יריב את ריבם מיד עושקיהם, **כי יראה כי אזלת יד** וגו' **. ואמר אי אלהימו.** האויב יאמר אי אלהימו של ישראל, כמו שאמר טיטוס הרשע כשגדר את הפרכת, כענין שנאמר (מיכה ז, י) ותרא אויבתי ותכסה בושה האמרה אלי איו ה' אלהיך. **ראו עתה כי אני** וגו' **.** אז יגלה הקדוש ברוך הוא ישועתו ויאמר ראו עתה כי אני אני הוא, מאתי באת עליהם הרעה, ומאתי תבא עליהם הטובה. **ואין מידי מציל.** מי שיציל אתכם מן הרעה אשר אביא עליכם. **כי אשא אל שמים ידי.** כמו כי נשאתי, תמיד אני משרה מקום שכינתי בשמים, כתרגומו אפלו חלש למעלה וגבור למטה, אימת העליון על התחתון, וכל שכן שגבור למעלה וחלש מלמטה. **ידי.** מקום שכינתי, כמו (במדבר ב, יז) איש על ידו, והיה בידי להפרע מכם, אבל אמרתי שחי אנכי לעולם, איני ממהר לפרוע, לפי שיש לי שהות בדבר, כי אני חי לעולם, ובדורות אחרונים אני נפרע מהם, והיכולת בידי להפרע מן המתים ומן החיים. מלך בשר ודם שהוא הולך למות, ממהר נקמתו להפרע בחייו, כי שמא ימות הוא או אויבו ונמצא שלא ראה נקמתו ממנו, אבל אני חי לעולם, ואם ימותו הם ואיני נפרע בחייהם, אפרע במותם. **אם שנותי ברק חרבי.** הרבה ''אם'' יש שאינם תלויין, כשאשנן ברק חרבי ותאחז במשפט ידי וכו' , כמו שפרשתי למעלה:
@907 **הוא והושע בן נון.** שבת של דיוזגי היתה, נטלה רשות מזה ונתנה לזה, העמיד לו משה מתרגמן ליהושע, שיהא דורש בחייו, כדי שלא יאמרו ישראל בחיי רבך לא היה לך להרים ראש. ולמה קוראו כאן הושע, לומר שלא זחה דעתו עליו, שאף על פי שנתנה לו גדלה, השפיל עצמו כאשר מתחלתו:
@909 **שימו לבבכם.** צריך אדם שיהיו עיניו ולבו ואזניו מכונים לדברי תורה, וכן הוא אומר (יחזקאל מ, ד) בן אדם ראה בעיניך ובאזניך שמע ושים לבך וגו' , הרי דברים קל וחמר, ומה תבנית הבית שהוא נראה לעינים ונמדד בקנה צריך אדם שיהיו עיניו ואזניו ולבו מכונים להבין, דברי תורה שהן כהררין התלויין בשערה על אחת כמה וכמה:
@910 **כי לא דבר רק הוא מכם.** לא לחנם אתם יגעים בה, כי הרבה שכר תלוי בה, כי הוא חייכם. דבר אחר, אין לך דבר ריקן בתורה שאם תדרשנו שאין בו מתן שכר, תדע לך שכן אמרו (בראשית לו, כב) ואחות לוטן תמנע, (שם לו, יב) ותמנע היתה פלגש וגו' לפי שאמרה איני כדאי להיות לו לאשה הלואי ואהיה פילגשו, וכל כך למה, להודיע שבחו של אברהם שהיו שלטונים ומלכים מתאוים להדבק בזרעו:
@911 **וידבר ה' אל משה בעצם היום הזה.** בשלשה מקומות נאמר בעצם היום הזה, נאמר בנח (שם ז, יג) בעצם היום הזה בא נח וגו' , במראית אורו של יום, לפי שהיו בני דורו אומרים בכך וכך אם אנו מרגישין בו אין אנו מניחין אותו לכנס בתבה, ולא עוד אלא אנו נוטלין כשילין וקרדמות ומבקעין את התבה. אמר הקדוש ברוך הוא הריני מכניסו בחצי היום, וכל מי שיש בידו כח למחות יבא וימחה. במצרים נאמר (שמות יב, נא) בעצם היום הזה הוציא ה', לפי שהיו מצרים אומרים בכך וכך אם אנו מרגישין בהם אין אנו מניחים אותם לצאת, ולא עוד אלא אנו נוטלין סיפות וכלי זין והורגין בהם. אמר הקדוש ברוך הוא הריני מוציאן בחצי היום וכל מי שיש בו כח למחות יבא וימחה. אף כאן, במיתתו של משה, נאמר בעצם היום הזה, לפי שהיו ישראל אומרים בכך וכך אם אנו מרגישין בו אין אנו מניחין אותו, אדם שהוציאנו ממצרים וקרע לנו את הים והוריד לנו את המן והגיז לנו את השלו והעלה לנו את הבאר ונתן לנו את התורה אין אנו מניחין אותו. אמר הקדוש ברוך הוא הריני מכניסו בחצי היום וכו' :
@913 **כאשר מת אהרן אחיך.** באותה מיתה שראית וחמדת אותה, שהפשיט משה את אהרן בגד ראשון והלבישו לאלעזר וכן שני וכן שלישי וראה בנו בכבודו. אמר לו משה, אהרן אחי, עלה למטה, ועלה. פשוט ידיך, ופשט. פשוט רגליך, ופשט. עצום עיניך, ועצם. קמוץ פיך, וקמץ. והלך לו. אמר משה אשרי מי שמת במיתה זו:
@914 **על אשר מעלתם בי.** גרמתם למעול בי: **על אשר לא קדשתם אותי.** גרמתם לי שלא אתקדש, אמרתי לכם (במדבר כ, ח) ודברתם אל הסלע, והם הכוהו, והצרכו להכותו פעמים, ואלו דברו עמו ונתן מימיו בלא הכאה, היה מתקדש שם שמים, שהיו ישראל אומרים ומה הסלע הזה שאינו לשכר ולא לפרענות, אם זכה אין לו מתן שכר, ואם חטא אינו לוקה, כך מקים מצות בוראו, אנו לא כל שכן:
@915 **כי מנגד.** מרחוק: **תראה** וגו' **.** כי אם לא תראנה עכשיו לא תראנה עוד בחייך: **ושמה לא תבוא.** וידעתי כי חביבה היא לך, על כן אני אומר לך עלה וראה:
@916 **וזאת הברכה** וגו' **לפני מותו.** סמוך למיתתו שאם לא עכשיו, אימתי:
@917 **ויאמר ה' מסיני בא.** פתח תחלה בשבחו של מקום ואחר כך פתח בצרכיהם של ישראל. ובשבח שפתח בו, יש בו הזכרת זכות לישראל, וכל זה דרך רצוי הוא, כלומר כדאי הם אלו שתחול עליהם ברכה: **מסיני בא.** יצא לקראתם כשבאו להתיצב בתחתית ההר כחתן היוצא להקביל פני כלה, שנאמר (שמות יט, יז) לקראת האלהים, למדנו שיצא כנגדם: **וזרח משעיר למו.** שפתח לבני עשו שיקבלו את התורה ולא רצו: **הופיע.** להם: **מהר פארן.** שהלך שם ופתח לבני ישמעאל שיקבלוה, ולא רצו: **ואתה.** לישראל: **מרבבת קדש.** ועמו מקצת רבבות מלאכי קדש, ולא כלם ולא רבם, ולא כדרך בשר ודם שמראה כל כבוד עשרו ותפארתו ביום חפתו: **אש דת.** שהיתה כתובה מאז לפניו באש שחורה על גב אש לבנה, נתן להם בלוחות כתב יד ימינו. דבר אחר, אש דת כתרגומו, שנתנה להם מתוך האש:
@918 **אף חבב עמים.** גם חבה יתרה חבב את השבטים. כל אחד ואחד קרוי עם, שהרי בנימין לבדו היה עתיד להולד כשאמר הקדוש ברוך הוא ליעקב (בראשית לה, יא) גוי וקהל גוים יהיה ממך: **כל קדשיו בידך.** נפשות הצדיקים הגנוזות אתו, כענין שנאמר (שמואל א' כה, כט) והיתה נפש אדני צרורה בצרור החיים את ה' אלהיך: **והם תכו לרגלך.** והם ראוים לכך, שהרי תכו עצמן לתוך תחתית ההר לרגלך בסיני. תכו לשון פעלו, התוכו לתוך מרגלותיך: **ישא מדברתיך.** נשאו עליהם עול תורתך: **מדברתיך.** המ''ם בו קרוב ליסוד, כמו (במדבר ז, פט) וישמע את הקול מדבר אליו, (יחזקאל ב, ב) ואשמע את מדבר אלי, כמו מתדבר אלי, אף זה מדברותיך מה שהיית מדבר להשמיעני לאמר להם. טיי''ש פורפרלידורי''ש בלע''ז . ואונקלוס תרגם שהיו נוסעים על פי דבריך, והמ''ם בו שמוש משמשת לשון מן. דבר אחר, אף חבב עמים, אף בשעת חבתם של אמות העולם שהראית להם פנים שוחקות ומסרת את ישראל בידם: **כל קדשיו בידך.** כל צדיקיהם וטוביהם דבקו בך ולא משו מאחריך ואתה שומרם: **והם תכו לרגלך.** והם מתמצעים ומתכנסים לתחת צלך: **ישא מדברתיך.** מקבלים גזרותיך ודתותיך בשמחה. ואלה דבריהם:
@919 **תורה.** אשר צוה לנו משה מורשה היא לקהלת יעקב, אחזנוה ולא נעזבנה:
@920 **ויהי.** הקדוש ברוך הוא: **בישרון מלך.** תמיד עול מלכותו עליהם: **בהתאסף.** בכל התאסף ראשי חשבון אסיפתם: **ראשי.** כמו (שמות ל, יב) כי תשא את ראש, ראויין אלו שאברכם. דבר אחר, בהתאסף, בהתאספם יחד באגדה אחת ושלום ביניהם הוא מלכם, ולא כשיש מחלוקת ביניהם:
@921 **יחי ראובן.** בעולם הזה: **ואל ימת.** לעולם הבא, שלא יזכר לו מעשה בלהה: **ויהי מתיו מספר.** נמנין במנין שאר אחיו, דגמא היא זו, כענין שנאמר (בראשית לה, כב) וישכב את בלהה ויהיו בני יעקב שנים עשר, שלא יצא מן המנין:
@922 **וזאת ליהודה.** סמך יהודה לראובן, מפני ששניהם הודו על קלקול שבידם, שנאמר (איוב טו, יח. יט) אשר חכמים יגידו וגו' להם לבדם וגו' ולא עבר זר בתוכם. ועוד פרשו רבותינו, שכל ארבעים שנה שהיו ישראל במדבר היו עצמות יהודה מתגלגלים בארון מפני נדוי שקבל עליו, שנאמר (בראשית מד, לב) וחטאתי לאבי כל הימים, אמר משה, מי גרם לראובן שיודה יהודה וכו' : **שמע ה' קול יהודה.** תפלת דוד ושלמה ואסא מפני הכושים, ויהושפט מפני העמונים, וחזקיה מפני סנחריב: **ואל עמו תביאנו.** לשלום מפני המלחמה: **ידיו רב לו.** יריבו ריבו וינקמו נקמתו: **ועזר מצריו תהיה.** על יהושפט התפלל על מלחמת רמות גלעד, (דה''ב יח, לא) ויזעק יהושפט וה' עזרו. דבר אחר, שמע ה' קול יהודה, כאן רמז ברכה לשמעון מתוך ברכותיו של יהודה, ואף כשחלקו ארץ ישראל נטל שמעון מתוך גורלו של יהודה שנאמר (יהושע יט, ט) מחבל בני יהודה נחלת בני שמעון. ומפני מה לא יחד לו ברכה בפני עצמו, שהיה בלבו עליו על מה שעשה בשטים, כן כתוב באגדת תהלים:
@923 **וללוי אמר.** ועל לוי אמר: **תמיך ואוריך.** כלפי שכינה הוא מדבר: **אשר נסיתו במסה.** שלא נתלוננו עם שאר המלינים: **תריבהו** וגו' **.** כתרגומו. דבר אחר, תריבהו על מי מריבה, נסתקפת לו לבוא בעלילה, אם משה אמר (במדבר כ, י) שמעו נא המורים, אהרן ומרים מה עשו:
@924 **האמר לאביו ולאמו לא ראיתיו.** כשחטאו בעגל ואמרתי (שמות לב, כו) מי לה' אלי, נאספו אלי כל בני לוי וצויתים להרוג את אבי אמו והוא מישראל, או את אחיו מאמו, או את בן בתו, וכן עשו. ואי אפשר לפרש אביו ממש ואחיו מאביו וכן בניו ממש, שהרי לוים הם ומשבט לוי לא חטא אחד מהם שנאמר כל בני לוי: **כי שמרו אמרתך.** (שמות כ, ב) לא יהיה לך אלהים אחרים: **ובריתך ינצרו.** ברית מילה, שאותם שנלדו במדבר, וישראל לא מלו את בניהם, והם היו מולין ומלין את בניהם:
@925 **יורו משפטיך.** ראויין אלו לכך: **וכליל.** עולה:
@926 **מחץ מתנים קמיו.** מחץ קמיו, מכת מתנים, כענין שנאמר (תהלים סט, כד) ומתניהם תמיד המעד, ועל המעוררין על הכהנה אמר כן. דבר אחר, ראה שעתידין חשמנאי ובניו להלחם עם היונים והתפלל עליהם לפי שהיו מועטים, שנים עשר בני חשמנאי ואלעזר כנגד כמה רבבות, לכך נאמר ברך ה' חילו ופעל ידיו תרצה: **ומשנאיו מן יקומון.** מחץ קמיו ומשנאיו מהיות להם תקומה:
@927 **לבנימן אמר.** לפי שברכת לוי בעבודת הקרבנות, ושל בנימין בבנין בית המקדש בחלקו, סמכן זה לזה, וסמך יוסף אחריו, שאף הוא משכן שילה היה בנוי בחלקו, שנאמר (שם עח, סז) וימאס באהל יוסף וגו' . ולפי שבית עולמים חביב משילה לכך הקדים בנימין ליוסף **חפף עליו.** מכסה אותו ומגין עליו: **כל היום.** לעולם, משנבחרה ירושלים, לא שרתה שכינה במקום אחר: **ובין כתפיו שכן.** בגובה ארצו היה, בית המקדש בנוי אלא שנמוך עשרים ושלש אמה מעין עיטם, ושם היה דעתו של דוד לבנותו, כדאיתא בשחיטת קדשים (זבחים נד, ב) אמרי נחתי ביה פורתא משום דכתיב ובין כתפיו שכן, אין לך נאה בשור יותר מכתפיו:
@928 **מברכת ה' ארצו.** שלא היתה בנחלת השבטים ארץ מלאה כל טוב כארצו של יוסף: **ממגד.** לשון עדנים ומתק: **ומתהום.** שהתהום עולה ומלחלח אותה מלמטה, אתה מוצא בכל השבטים ברכתו של משה מעין ברכתו של יעקב:
@929 **וממגד תבואת שמש.** שהיתה ארצו פתוחה לחמה וממתקת הפרות: **גרש ירחים.** יש פרות שהלבנה מבשלתן ואלו הן, קשואין ודלועין. דבר אחר גרש ירחים. שהארץ מגרשת ומוציאה מחדש לחדש:
@930 **ומראש הררי קדם.** ומבורכת מראשית בשול הפרות שהרריה מקדימין לבכר בשול פירותיהם. דבר אחר מגיד שקדמה בריאתן לשאר הרים: **גבעות עולם.** גבעות העושות פרות לעולם ואינן פוסקות מעוצר הגשמים:
@931 **ורצון שכני סנה.** כמו שוכן סנה ותהא ארצו מבורכת מרצונו ונחת רוחו של הקדוש ברוך הוא הנגלה עלי תחלה בסנה: **רצון.** נחת רוח ופיוס, וכן כל רצון שבמקרא: **תבואתה.** ברכה זו לראש יוסף: **נזיר אחיו.** שהפרש מאחיו במכירתו:
@932 **בכור שורו.** יש בכור שהוא לשון גדלה ומלכות, שנאמר (תהלים פט, כח) אף אני בכור אתנהו, וכן (שמות ד, כה) בני בכורי ישראל: **בכור.** מלך היוצא ממנו והוא יהושע: **שורו.** שכחו קשה כשור לכבש כמה מלכים: **הדר לו.** נתון לו שנאמר (במדבר כז, כ) ונתתה מהודך עליו: **וקרני ראם קרניו.** שור, כחו קשה, ואין קרניו נאות, אבל ראם, קרניו נאות, ואין כחו קשה, נתן ליהושע כחו של שור ויופי קרני ראם: **אפסי ארץ.** שלשים ואחד מלכים אפשר שכלם מארץ ישראל היו, אלא אין לך כל מלך ושלטון שלא קנה לו פלטרין ואחזה בארץ ישראל, שחשובה לכלם היא, שנאמר (ירמיה ג, יט) נחלת צבי צבאות גוים: **והם רבבות אפרים.** אותם המנגחים הם הרבבות שהרג יהושע, שבא מאפרים: **והם אלפי מנשה.** הם האלפים שהרג גדעון במדין, שנאמר (שופטים ח, י) וזבח וצלמנע בקרקר וגו' :
@933 **ולזבולן אמר.** אלו חמשה שבטים שברך באחרונה. זבולן גד דן נפתלי ואשר, כפל שמותיהם לחזקם ולהגבירם, לפי שהיו חלשים שבכל השבטים, הם הם שהוליך יוסף לפני פרעה, שנאמר ומקצה אחיו לקח חמשה אנשים (בראשית מז, ב) , לפי שנראים חלשים ולא ישים אותם לו שרי מלחמתו: **שמח זבולן בצאתך ויששכר באהלך.** זבולן ויששכר עשו שותפות, זבולן לחוף ימים ישכון ויוצא לפרקמטיא בספינות ומשתכר, ונותן לתוך פיו של יששכר והם יושבים ועוסקים בתורה, לפיכך הקדים זבולן ליששכר, שתורתו של יששכר על ידי זבולן היתה: **שמח זבולן בצאתך.** הצלח בצאתך לסחורה: **ויששכר.** הצלח בישיבת אהליך לתורה לישב ולעבר שנים ולקבע חדשים, כמו שנאמר (דה''א יב, לג) ומבני יששכר יודעי בינה לעתים, ראשיהם מאתים, ראשי סנהדראות היו עוסקים בכך. ועל פי קביעות עתיהם ועבוריהם:
@934 **עמים.** של שבטי ישראל: **הר יקראו.** להר המוריה יאספו, כל אסיפה על ידי קריאה היא ושם יזבחו ברגלים זבחי צדק: **כי שפע ימים יינקו.** יששכר וזבולן, ויהא להם פנאי לעסוק בתורה: **ושפני טמוני חול.** כסויי טמוני חול, טרית וחלזון וזכוכית לבנה היוצאים מן הים ומן החול, ובחלקו של יששכר וזבולן היה, כמו שאמרו במסכת מגלה (ו, א) זבולן עם חרף נפשו למות (שופטים ה, יח) משום דנפתלי על מרומי שדה, שהיה מתרעם זבולן על חלקו, לאחי נתת שדות וכרמים וכו' : **ושפני.** לשון כסוי, כמו שנאמר (מ''א ו, ט) ויספן את הבית, (שם ז, ג) וספן בארז, ותרגומו ומטלל בכיורי ארזא. דבר אחר, עמים הר יקראו, על ידי פרקמטיא של זבולן, תגרי אמות העולם באים אל ארצו, והוא עומד על הספר והם אומרים הואיל ונצטערנו עד כאן, נלך עד ירושלים ונראה מה יראתה של אמה זו, ומה מעשיה, והם רואים כל ישראל עובדים לאלוה אחד, ואוכלים מאכל אחד, לפי שהגוים אלוהו של זה לא כאלוהו של זה, ומאכלו של זה לא כמאכלו של זה, והם אומרים אין אמה כשרה כזו ומתגיירין שם, שנאמר שם יזבחו זבחי צדק: **כי שפע ימים יינקו.** זבולן ויששכר, הים נותן להם ממון בשפע:
@935 **ברוך מרחיב גד.** מלמד שהיה תחומו של גד מרחיב ועולה כלפי מזרח: **כלביא שכן.** לפי שהיה סמוך לספר, לפיכך נמשל כאריות, שכל הסמוכים לספר צריכים להיות גבורים: **וטרף זרוע אף קדקד.** הרוגיהן היו נכרין, חותכים הראש עם הזרוע במכה אחת:
@936 **וירא ראשית לו.** ראה לטול לו חלק בארץ סיחון ועוג, שהיא ראשית כבוש הארץ: **כי שם חלקת מחקק.** כי ידע אשר שם בנחלתו חלקת שדה קבורת מחוקק והוא משה: **ספון.** אותה חלקה ספונה וטמונה מכל בריה, שנאמר (לקמן לד, ו) ולא ידע איש את קבורתו: **ויתא.** גד: **ראשי עם.** הם היו הולכים לפני החלוץ בכבוש הארץ לפי שהיו גבורים, וכן הוא אומר (דברים ג, יח) ואתם תעברו חלוצים לפני אחיכם וגו' : **צדקת ה' עשה.** שהאמינו דבריהם ושמרו הבטחתם לעבור את הירדן עד שכבשו וחלקו. דבר אחר ויתא משה ראשי עם. צדקת ה' עשה, על משה אמור:
@937 **דן גור אריה.** אף הוא היה סמוך לספר לפיכך מושלו באריות: **יזנק מן הבשן.** כתרגומו, שהיה הירדן יוצא מחלקו ממערת פמיאס, והיא לשם, שהיא בחלקו של דן, שנאמר (יהושע יט, מז) ויקראו ללשם דן וזנוקו וקלוחו מן הבשן. דבר אחר, מה זנוק זה יוצא ממקום אחד ונחלק לשני מקומות, כך שבטו של דן נטלו חלק בשני מקומות. תחלה נטלו בצפונית מערבית עקרון וסביבותיה, ולא ספקו להם, ובאו ונלחמו עם לשם שהיא פמיאס והיא בצפונית מזרחית, שהרי הירדן יוצא ממערת פמיאס והוא במזרחה של ארץ ישראל, ובא מהצפון לדרום וכלה בקצה ים המלח, שהוא במזרח יהודה, שנטל בדרומה של ארץ ישראל, כמו שמפורש בספר יהושע, והוא שנאמר (שם יט, מז) ויצא גבול בני דן מהם ויעלו בני דן וילחמו עם לשם וגו' , יצא גבולם מכל אתו הרוח שהתחילו לנחול בו:
@938 **שבע רצון.** שהיתה ארצו שבעה כל רצון יושביה: **ים ודרום ירשה.** ים כנרת נפלה בחלקו ונטל מלא חבל חרס בדרומה לפרוש חרמים ומכמורות: **ירשה.** לשון צווי, כמו (דברים א, כא) עלה רש, והטעם של מעלה ברי''ש מוכיח, כמו ירש, ידע, לקח, שמע, כשמוסיף בו ה''א יהיה הטעם למעלה שמעה, ידעה, סלחה, לקחה אף כאן ירשה לשון צווי. ובמסורת הגדולה מצינו באלפא ביתא לשון צווי דטעמיהון מלעיל:
@939 **ברוך מבנים אשר.** ראיתי בספרי, אין לך בכל השבטים שנתברך בבנים כאשר, ואיני יודע כיצד: **יהי רצוי אחיו.** שהיה מתרצה לאחיו בשמן אנפיקינון ובקפלאות והם מרצין לו בתבואה. דבר אחר, יהי רצוי אחיו שהיו בנותיו נאות והוא שנאמר (דברי הימים א' ז, לא) הוא אבי ברזית, שהיו בנותיו נשואות לכהנים גדולים הנמשחים בשמן זית: **וטבל בשמן רגלו.** שהיתה ארצו מושכת שמן כמעין. ומעשה שנצטרכו אנשי לודקיא לשמן מנו להם פולמוסטום אחד וכו' , כדאיתא במנחות (פה, ב) :
@940 **ברזל ונחשת מנעלך.** עכשיו הוא מדבר נגד כל ישראל, שהיו גבוריהם יושבים בערי הספר ונועלים אותה שלא יוכלו האויבים לכנס בה כאלו היא סגורה במנעולים ובריחים של ברזל ונחשת. דבר אחר ברזל ונחשת מנעלך, ארצכם נעולה בהרים שחוצבין מהם ברזל ונחשת, וארצו של אשר היתה מנעולה של ארץ ישראל: **וכימיך דבאך.** וכימים שהם טובים לך, שהן ימי תחלתך, ימי נעוריך, כן יהיו ימי זקנתך, שהם דואבים זבים ומתמוטטים. דבר אחר, וכימיך דבאך וכימיך שהם טובים לך כמנין ימיך, כל הימים אשר אתם עושים רצונו של מקום, יהיו דבאך, שכל הארצות יהיו דובאות כסף וזהב לארץ ישראל, שתהא מבורכת בפירות. וכל הארצות מתפרנסות המנה וממשיכות לה כספם וזהבם אישקורונ''ט . הכסף והזהב כלה מהם, שהן מזיבות אותם לארצכם:
@941 **אין כאל ישרון.** דע לך ישורון שאין כאל בכל אלהי העמים, ולא כצורך צורם: **רכב שמים.** הוא אותו אלוה שבעזרך ובגאותו הוא רוכב שחקים:
@942 **מענה אלהי קדם.** למעון, הם השחקים לאלהי קדם, שקדם לכל אלהים וברר לו שחקים לשבתו ומעונתו, ומתחת מעונתו כל בעלי זרוע שוכנים: **זרעת עולם.** סיחון ועוג ומלכי כנען, שהיו תקפו וגבורתו של עולם, לפיכך על כרחם יחרדו ויזועו וכחם חלש מפניו. לעולם אימת הגבוה על הנמוך, והוא שהכח והגבורה שלו בעזרך: **ויגרש מפניך אויב.** ואמר לך השמד אותם: **מענה.** כל תיבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה:
@943 **בטח בדד.** כל יחיד ויחיד איש תחת גפנו ותחת תאנתו, מפזרין ואין צריכים להתאסף ולישב יחד מפני האויב: **עין יעקב.** כמו (במדבר יא, ז) ועינו כעין הבדלח, כעין הברכה שברכם יעקב, לא כבדד שאמר ירמיה (ירמיה טו, יז) בדד ישבתי, אלא כעין הבטחה שהבטיחם יעקב (בראשית מח, כא) והיה אלהים עמכם והשיב אתכם אל ארץ אבותיכם: **יערפו.** יטיפו: **אף שמיו יערפו טל.** אף ברכתו של יצחק נוספת על ברכתו של יעקב (שם כז, כח) ויתן לך האלהים מטל השמים וגו' :
@944 **אשריך ישראל.** לאחר שפרט להם הברכות אמר להם מה לי לפרוט לכם, כלל דבר, הכל שלכם: **אשריך ישראל מי כמוך.** תשועתך בה' אשר הוא מגן עזרך ואשר הוא וחרב גאותך: **ויכחשו איביך לך.** כגון הגבעונים שאמרו (יהושע ט, ט) מארץ רחוקה באו עבדיך וגו' : **ואתה על במותימו תדרך.** כענין שנאמר (שם י, כד) שימו את רגליכם על צוארי המלכים האלה:
@945 **מערבות מואב אל הר נבו.** כמה מעלות היו ופסען משה בפסיעה אחת: **את כל הארץ.** הראהו את כל ארץ ישראל בשלותה והמציקין העתידים להיות מציקין לה: **עד דן.** הראהו בני דן עובדים עבודה זרה שנאמר (שופטים יח, ל) ויקימו להם בני דן את הפסל, והראהו שמשון שעתיד לצאת ממנו למושיע:
@946 **ואת כל נפתלי.** הראהו ארצו בשלותה וחרבנה, והראהו דבורה וברק מקדש נפתלי נלחמים עם סיסרא וחילותיו: **ואת ארץ אפרים ומנשה.** הראהו ארצם בשלותה ובחרבנה והראהו יהושע נלחם עם מלכי כנען שבא מאפרים, וגדעון שבא ממנשה נלחם עם מדין ועמלק: **ואת כל ארץ יהודה.** בשלותה ובחרבנה והראהו מלכות בית דוד ונצחונם: **עד הים האחרון.** ארץ המערב בשלותה ובחרבנה. דבר אחר, אל תקרי הים האחרון אלא היום האחרון, הראהו הקדוש ברוך הוא כל המאורעות שעתידין לארע לישראל עד שיחיו המתים:
@947 **ואת הנגב.** ארץ הדרום. דבר אחר, מערת המכפלה, שנאמר (במדבר יג, כב) ויעלו בנגב ויבא עד חברון: **ואת הככר.** הראהו שלמה יוצק כלי בית המקדש, שנאמר (מ''א א' ז, מו) בככר הירדן יצקם המלך במעבה האדמה:
@948 **לאמר לזרעך אתננה הראיתיך.** כדי שתלך ותאמר לאברהם ליצחק וליעקב שבועה שנשבע לכם הקדוש ברוך הוא קימה, וזהו לאמר, לכך הראיתיה לך, אבל גזרה היא מלפני ששמה לא תעבר, שאלולי כך, הייתי מקיימך עד שתראה אותם נטועים וקבועים בה ותלך ותגיד להם:
@949 **וימת שם משה.** אפשר משה מת וכתב וימת שם משה, אלא עד כאן כתב משה, מכאן ואלך כתב יהושע. רבי מאיר אומר אפשר ספר התורה חסר כלום, והוא אומר (לעיל לא, כו) לקח את ספר התורה הזה, אלא הקדוש ברוך הוא אומר ומשה כותב בדמע: **על פי ה'.** בנשיקה:
@950 **וקבר אתו.** הקדוש ברוך הוא בכבודו. רבי ישמעאל אומר הוא קבר את עצמו, וזהו אחד משלשה אתין שהיה רבי ישמעאל דורש כן. כיוצא בו (במדבר ו, יג) ביום מלאת ימי נזרו יביא אתו, הוא מביא את עצמו. כיוצא בו (ויקרא כב, טז) והשיאו אותם עון אשמה, וכי אחרים משיאים אותם, אלא הם משיאים את עצמם: **מול בית פעור.** קברו היה מוכן שם מששת ימי בראשית לכפר על מעשה פעור, וזה אחד מן הדברים שנבראו בערב שבת בין השמשות:
@951 **לא כהתה עינו.** אף משמת: **ולא נס לחה.** לחלוחית שבו, לא שלט בו רקבון ולא נהפך תאר פניו:
@952 **בני ישראל.** הזכרים, אבל באהרן מתוך שהיה רודף שלום ונותן שלום בין איש לרעהו ובין אשה לבעלה נאמר (במדבר כ, כט) כל בית ישראל, זכרים ונקבות:
@954 **אשר ידעו ה' פנים אל פנים.** שהיה לבו גס בו ומדבר אליו בכל עת שרוצה, כענין שנאמר (שמות לב, ל) ועתה אעלה אל ה', (במדבר ט, ח) עמדו ואשמעה מה יצוה ה' לכם:
@956 **ולכל היד החזקה.** שקבל את התורה בלוחות בידיו: **ולכל המורא הגדול.** נסים וגבורות שבמדבר הגדול והנורא: **לעיני כל ישראל.** שנשאו לבו לשבור הלוחות לעיניהם, שנאמר (לעיל ט, יז) ואשברם לעיניכם, והסכימה דעת הקדוש ברוך הוא לדעתו, שנאמר אשר שברת, יישר כחך ששברת (שמות לד, א) :

@1 **אלה הדברים אשר דבר משה אל כל ישראל** . על המצות אשר יזכיר בכל הספר מתחלת עשרת הדברות בפרשת ואתחנן כמו שאמר (פסוק ה) הואיל משה באר את התורה הזאת לאמר כי על התורה ידבר ויחסר מפסוק ה' אלהינו דבר אלינו (פסוק ו) מלת אמירה וכמוהו כי נשני אלהים את כל עמלי כי הפרני אלהים (בראשית מא נא נב) כי אמר ושיעור הכתובים האלה אלה המצות אשר דבר משה אל כל ישראל בעבר הירדן בארבעים שנה לצאתם ממצרים באחד לחדש העשתי עשר ככל אשר צוה ה' אותו אליהם והיה זה אחרי הכותו את סיחון ועוג בארץ מואב שם הואיל משה לבאר להם התורה הזאת לאמר ויאמר ה' אלהינו דבר אלינו בחורב לאמר רב לכם שבת וגו' והטעם כי כאשר הואיל משה לבאר להם המצות אמר להם בתחלת דבריו ה' אלהינו דבר אלינו בחורב אחרי שנתן לנו עשרת הדברים שנכבוש הארץ מיד ונעבור את הירדן וחטאתיכם גרמו לכם זה וזה ונמשכו דברי הפתיחה הזאת עד שהשלים בהם בפסוק ושמרת את חקיו ואת מצותיו אשר אנכי מצוך היום אשר ייטב לך ולבניך אחריך ולמען תאריך ימים על האדמה אשר ה' אלהיך נותן לך כל הימים (להלן ד מ) אז קרא משה אל כל ישראל אשר היו לפניו ואמר (להלן ה א) שמע ישראל את החקים ואת המשפטים אשר אנכי דובר באזניכם היום והתחיל בביאור התורה עשרת הדברות שישמעו אותם בביאור מפי המקבל אותם מפיו של הקב"ה ואחרי כן הודיעם יחוד השם שמע ישראל ה' אלהינו ה' אחד (להלן ו ד) וכל המצות שבספר הזה ולכך יפרש בכאן "אשר דבר משה אל כל ישראל" ושם "ויקרא משה אל כל ישראל" כי ביאור התורה ותשלום המצות צריך להיות במעמד כל ישראל כאשר היה במתן התורה ומפני שהאריך בדברי הפתיחה הזאת חזר הכתוב למקום שפסק בתחלת ביאור התורה ואמר (להלן ד מד מה) וזאת התורה אשר שם משה לפני בני ישראל אלה העדות החקים והמשפטים אשר דבר משה אל בני ישראל בצאתם ממצרים והזכיר (להלן ד מו) כי היה בעבר הירדן בגיא בארץ סיחון והיא ארץ מואב הנזכר בכאן כי ישראל לא נכנסו לארץ מואב רק באותו החלק שטהר אליהם בסיחון כמו שנתבאר בספר של מעלה (במדבר כא יג) והנה הזכיר בכאן שני דברים אמר שדבר משה אל בני ישראל ככל אשר צוה ה' אותו אליהם וזה רמז אל המצות שיאמר להם בספר הזה שלא נזכרו עד הנה בתורה ואמר שהם ככל אשר צוה אותו השם לא הוסיף ולא גרע על מה שנצטווה והזכיר זה בעבור שלא אמר בהם "וידבר ה' אל משה" ולכן כלל אותם עתה שהם כולם ככל אשר נצטווה מפי הקב"ה ואמר עוד כי הואיל משה באר את התורה וזה רמז במצות שנאמרו כבר שיחזור אותם לבאר אותם ולחדש בהם דברים וטעם "הואיל משה" שרצה לבאר להם את התורה והזכיר כן להודיע כי מעצמו ראה לעשות כן ולא צוהו השם בזה מלשון הואל נא ולין (שופטים יט ו) ולו הואלנו ונשב (יהושע ז ז) וכן רבים
@2 **וטעם אחד עשר יום מחרב** . יודיענו הכתוב שיעור המדבר כי מחורב שיצאו משם עד קדש ברנע מהלך אחד עשר יום בלבד כי קרוב הוא בדרך הר שעיר וקדש ברנע הוא סוף המדבר בגבול הר האמורי שהוא נחלת ישראל ושם ארץ סיחון ועוג אשר שם באר התורה בגיא מול בית פעור ואחרי כן אמר שהם הלכו דרך הר האמורי כל המדבר הגדול והנורא ואחרי כן יספר כי בקדש ברנע שהוא בתחום נחלתם בקשו מרגלים ונשתבש דרכם והלכו דרך ים סוף לאחור ולא לפנים עד מלאת ארבעים שנה ובעבור שלא היו ישראל עתה במדבר כי כבר נכנסו בארץ מואב הנזכרת דרש אונקלוס כי "במדבר בערבה" רמוזים הם לתוכחות ועוד כי מדוע יזכיר כל אלה המקומות ויתן סימנים ומצרים יותר מן המוכר שדה ושיעור הכתוב לדעתו אלה הדברים אשר דבר משה אל כל ישראל בעבר הירדן דבר במדבר בערבה ובמול סוף בין פארן ובין תפל ולבן וחצרות ודי זהב ואחד עשר יום מחורב כי הזכיר להם כל מה שעשו במקומות האלה ואחר כן אמר הכתוב כי שם בעבר הירדן הנזכר הואיל לבאר התורה אחר הוכיחו אותם ויען ויאמר ה' אלהינו דבר אלינו בחורב לאמר וכך הוא נדרש בספרי (דברים א) על דעת רבי יהודה אבל רבי יוסי בן דורמסקית עשה אותן מקומות שנקראו כן
@4 **אשר יושב בחשבון** . שלא היתה שלו אבל לכדה ממלך מואב ובנאה להיות לו בית מלכות וכן אשר יושב בעשתרות באדרעי שהיתה ארץ רפאים והוא מלך האמורי (להלן ג ח) כאשר אפרש בעה"י (להלן ב י ג יא) ומפני שאמר אשר יושב בעשתרות באדרעי יורה כי עשתרות שם מקום אשר בו אדרעי ולשון ספרי (דברים ד) בעשתרות שהיה קשה כעשתרות באדרעי זה מקום מלכות וכתב רש"י עשתרות לשון צוקין וקושי ועשתרות זהו עשתרות קרנים שהיו בה רפאים שנאמר (בראשית יד ה) ויכו את רפאים בעשתרות קרנים באדרעי שם מלכות וכן כתוב עשתרות צאנך (להלן ז יג) כתרגומו ורבותינו אמרו (חולין פד) למה נקרא שמן עשתרות שמעשרות את בעליהן ומחזקות אותן כעשתרות הללו שהם סלעים חזקים והרב מרכיב בו שתי לשונות ולא ידענו מאיזה מקום הוציא שיהיה עשתרות שם צוקין וסלעים אבל יתכן שנאמר שהוא שם עדרי הצאן מלשון עושר כדברי חכמים ועשתרות קרנים היו הרים גבוהים שעליהם מצודות סלעים ידמה אותם הכתוב לקרני הבהמות כמו שידמה אותם לשנים כענין שנאמר (איוב לט כח) על שן סלע ומצודה וכן על קרנות המזבח (שמות כט יב) וכן בקרן בן שמן (ישעיהו ה א) אמר התרגום בטור רם בארעא שמינא ושם יעלו עשתרות הצאן התיישים והעזים והיעלים וכיוצא בהן ולכך יקרא עשתרות קרנים וכן לבעל ולעשתרות (שופטים ב יג) הע"ז העשויה כצורת הצאן (או) להגין עליהם כפי סכלותם ובשפלות ההר בנו עיר ושמה אדרעי והוא שנאמר (להלן ג א) ויצא עוג מלך הבשן הוא וכל עמו למלחמה אדרעי כי אסף את כל חילו אל העיר אשר שם ארמון המלך וכסא המלכות וענין ספרי (שם) מדרשם אמרו ז"ל אשר יושב בעשתרות באדרעי אלו לא היה עוג קשה ושרוי בעשתרות קשה היה שהמדינה קשה וכו' ולפיכך ידרשו בעשתרות שהיה קשה כעשתרות כלומר שהיה מקום מושבו כמו עשתרות קרנים העיר החזקה שהיה הוא ומשפחתו משם כי עתה איננו יושב בעשתרות כי בארץ אמורי הוא יושב ומקום מלכות כלומר המדינה שהיה יושב בה אדרעי כי שם ארץ מלכותו הבשן
@6 **ה' אלהינו דבר אלינו בחרב לאמר** . על דעתי חורב שם מקום קרוב להר סיני ששם ישבו ישראל בשנה ההיא כי המדבר היה גדול ושם ההר אשר חמד אלהים ושמו סיני ועל כן נקרא כל המדבר מדבר סיני כאלו הוא מדבר הר סיני ואמר הכתוב (שמות יט ב) ויבאו מדבר סיני ויחנו במדבר ויחן שם ישראל נגד ההר שחנו במדבר במקום הנקרא חורב והוא נגד ההר ואפשר שגם ההר גם המדבר יקראו סיני כי שם אילני הסנה רבים ושם סמוך להר מקום או עיר מושב ששמו חורב ושם עמדו והכתוב שאמר (שם ג א) ויבא אל הר האלהים חרבה שבא אל חורב אשר שם הר האלהים והסנה היה בהר ומשה היה בחורב המקום אשר לפניו קרוב לו אשר עמד שם מחנה ישראל שנה ולפיכך אמר (שם פסוק ג) אסורה נא ואראה שיסור מחורב עד ההר ופעמים יקרא הכתוב ההר כן כמו שאמר (שם לג ו) ויתנצלו בני ישראל את עדים מהר חורב כלומר מן ההר אשר בחורב בתחומו או לפניו או ששם כל הארץ חורב וההר בתוכה וכן זכרו תורת משה עבדי אשר צויתי אותו בחורב על כל ישראל חקים ומשפטים (מלאכי ג כב) ירמוז לכל אשר נצטווה בהר ובאהל מועד אשר שם בחורב וראיתי בילמדנו מדרשם לא ידעת בסיני גם לא שמעת בחורב גם מאז לא פתחה אזנך (ישעיהו מח ח) בערבות מואב רמז כי חורב מקום אשר שם אהל מועד רק ר"א אמר (שמות ג א ב) כי חורב הוא הר סיני כי מפני החורב והיובש יהיה שם הסנה ויקרא בשני שמות ושניהם שוים בטעם
@7 **פנו וסעו לכם** . הזכיר להם הארץ והדרך שילכו בה למסעיהם ואחרי כן אמר ראה נתתי לפניכם את הארץ אשר נשבעתי לאבותיכם באו ורשו את הארץ מצוה לא יעוד והבטחה כאשר פירשתי (במדבר לג נג)
@8 **וטעם אשר נשבע ה'** . כמו ואל משה אמר עלה אל ה' (שמות כד א) ושם פירשתי
@9 **ואמר אלכם בעת ההיא לאמר** . קודם שאמר לנו ה' בחורב רב לכם שבת בהר הזה על דעת האומרים קודם מתן תורה בא יתרו וטעם "בעת ההיא" בשבתנו בחורב אבל הזכיר זה בכאן לומר הנה קבלנו את התורה והיו עליכם שופטים ושוטרים לשפוט ולהנהיג אתכם והנה היינו מוכנים ומזומנים לבא בארץ ונסע מחורב לדגלינו עם שופטינו וזקנינו ותקרבון אלי כלכם עם חכמיכם וראשיכם ובקשתם מרגלים ונתקלקל הענין
@12 **וטעם טרחכם ומשאכם וריבכם** . על דרך הפשט רמז משה רבינו להם שלשת הדברים שאמר ליתרו שהיה הוא עושה לעם כמו שפירשתי שם (שמות יח טו) והזכירן לישראל ברמז אמר "טרחכם" כנגד והודעתי את חוקי האלהים ואת תורותיו (שם שם טז) כי טורח גדול היה ללמד ליוצאי מצרים החוקים והתורות ופירושם וביאורם וסודם והזכיר "משאכם" כנגד לדרוש אלהים (שם פסוק טו) שהוא ענין תפלה שמתפלל עליהם והוא מלשון ונשאת תפלה (מלכים ב יט ד) ואל תשא בעדם רנה ותפלה (ירמיהו ז טז) "וריבכם" כפשוטו עניני המשפטים ואמר "הבו לכם אנשים חכמים ונבונים וידועים" על הדיינין בלבד אבל אמר סתם "ואשימם בראשיכם" דרך ענוה ולשון רש"י מספרי (דברים יב) טרחכם מלמד שהיו טרחנין היה אחד מהם רואה את בעל דינו נוצח בדין אומר יש לי עדים להביא יש לי ראיות להביא מוסיף אני עליכם דיינין והדין הזה לא ידעתי אותו שיהא בעל הדין יכול להוסיף דיינין יותר על שלשה בדיני ממונות וכל שכן לאחר שטען בפניהם וראה שחברו נוצח בדין שאלו קבל עליו קרוב או פסול יכול לחזור בו עד לאחר גמר דין אבל הכשרין לדון אינו יכול לחזור בו ושמא נלמוד מכאן שיכול אדם לומר שני דיינין אני בורר לי ותברור אתה שנים אחרים והם יבררו עוד אחד ויהא הדין נגמר בחמשה או ביותר כמו שאמרו אינו דומה דין הנגמר בה' לדין הנגמר בי' ואע"פ שג' כופין לדון בפניהם בשאינו רוצה לקבל עליו לדון אבל רוצה לברור יותר בורר דהוה ליה כאומר נלך למקום הועד ששומעין לו במקום שאין שם טורח שבכך נטוינו שנאמר (להלן טז כ) צדק צדק תרדוף הלך אחר ב"ד יפה (סנהדרין לב) ורבוי חכמים ב"ד יפה הוא והנה במדבר היו החכמים מצויין עמהם ויכולים לומר נלך לפני שרי האלפים
@13 **וידעים לשבטיכם** . "שיהיו ניכרים לכם, שאם בא לפני מעוטף בטליתו איני יודע מי הוא ומאי זה שבט הוא, אבל אתם מכירים אותו, שגדלתם אותו" לשון רש"י מספרי. ואם כן, יהיה "לשבטיכם" קשור עם "וידועים".
@13 אבל על דרך הפשט, טעמו הבו לכם לשבטיכם אנשים חכמים. ועל דעתי, טעם "וידועים" שהם ידועים לשופטים, כלומר, שמעלתם ידועה וניכרת למנותם בה שופטים.
@13 וכלל מעלות השופטים במלת "וידועים", כי השופטים צריכין להיות (שמות כא יח): "אנשי חיל יראי אלהים אנשי אמת שונאי בצע" כאשר אמר יתרו, ואלה היו ידועים לשופטים מתחלה, כי היו הכל אומרים "ראוי זה להיות שופט".
@17 **וטעם כי המשפט לאלהים הוא** . כטעם כי לא לאדם תשפטו כי לה' ועמכם בדבר משפט (דהי"ב יט ו) לומר כי לאלהים לעשות משפט בין יצוריו כי על כן בראם להיות ביניהם יושר וצדק ולהציל גזול מיד עושקו ונתן אתכם במקומו ואם תגורו ותעשו חמס הנה חטאתם לה' כי מעלתם בשליחותו
@18 **ואצוה אתכם בעת ההוא את כל הדברים אשר תעשון** . אלו עשרה דברים שבין דיני ממונות לדיני נפשות לשון רש"י מספרי (דברים יח) ואם כן עם השופטים הנזכרים ידבר ויקצר בעשרה הדברים שכולם נדרשים מן הכתובים ועל דרך הפשט הם החוקים והתורות הדרך אשר ילכו בה והמעשה אשר יעשון כי הכל יצוה ויזהיר וילמד לישראל מפיו והטעם להזכיר זה כאן כי בידוע שזה הענין עצת יתרו והוא אמר למשה (שמות יח יט) היה אתה לעם מול האלהים שיתפלל עליהם בעת צרתם ואמר לו (שם כ) והזהרת אתהם את החוקים ואת התורות וגו' שילמדם הוא התורה אך במשפט נתן לו עצה שימנה שופטים לסייעו וכבר פרשתיו שם (בפסוק כ) ולכן ספר בכאן כי כאשר מינה שרי האלפים והמאות לא מינה אותם רק על המשפט אבל הוא בעצמו ילמדם כל הדברים אשר יעשון על פי התורה כי שמע לעצת חותנו ויעש כל אשר אמר ולא הזכיר משה עצתו בכאן ולא אמר דבר בשם יתרו אשר אמר ונראה בעיני שלא רצה להזכירו במעמד כל ישראל לענוותו או שלא יהיה לכבוד לו שיזכיר לדור הזה כי אשה כושית לקח (במדבר יב א) ויתכן שהטעם מפני שנמלך בשכינה ועל פי הגבורה נעשה הענין ההוא
@22 **את הדרך אשר נעלה בה** . אין דרך שאין בה עקמימות ואת הערים אשר נבא אליהן תחלה לכבוש לשון רש"י וכן בספרי (דברים כב) אין לך דרך שאין בה עקמימות אין לך דרך שאין בה כמנות אין לך דרך שאין בה פרשות ואת הערים אשר נבא אליהן לידע באי זה דרך אנו באין כלומר מאין נכנס בארץ שנכבוש אותן הערים תחלה והוא מה שפירשתי בסדר שלח לך (במדבר יג ב) שלא בקשו ישראל מרגלים אלא להורות בפניהם הדרך
@23 **ואקח מכם שנים עשר אנשים** . לא שבח אותם בנשיאותם והיותם ראשי בני ישראל כי אחרי שהרשיעו לא יספר בשבח הרשעים
@25 **ויאמרו טובה הארץ אשר ה' אלהינו נתן לנו** . מי הם שאמרו טובתה יהושע וכלב לשון רש"י מספרי (דברים כה) ואני תמה אם כן מה הטענה הזאת עליהם וראוי שיאמינו לעשרה יותר מן השנים אולי טען עליהם כיון שהקב"ה הודיע אתכם שהיא ארץ טובה וגדולי השלוחים והצדיקים שבהם אף הם מעידין כן היה לכם להאמין כי האחרים מפני מורך לב אמרו מה שאמרו והנכון מה שפירשתי שם (במדבר יג לב) שכולם הודו לפני משה ואהרן וכל העדה ואמרו (שם יג כז) באנו אל הארץ אשר שלחתנו וגם זבת חלב ודבש היא וזה פריה והנה כלם בהסכמה אחת בטובת הארץ אבל בחוזק העמים ההם המסו את לבבם ואחרי כן בראותם כי יהושע וכלב יחזקו את לבם למלחמה באו שאר המרגלים אל בני ישראל שלא בפני משה והוציאו דבה על הארץ שהיא ארץ אוכלת יושביה וזהו ותרגנו באהליכם (פסוק כז) וגם העם לא יזכירו בפני משה הדבה הזאת כי יכחישם שלא אמרו כן בתחלה והודו שהיא טובה וגם זבת חלב ודבש אבל אמרו למשה (בפסוק כח) אנה אנחנו עולים אחינו המסו את לבבנו לאמר עם גדול ורם ממנו ועל כן יאמר להם משה עתה אמת הוא כדבריכם שהעם ההוא גדול ורם אבל ה' ילחם לכם ככל אשר עשה עמכם ממצרים ועד הנה וזה טעם ובדבר הזה אינכם מאמינים בה' אלהיכם שאין העכבה אלא ממיעוט אמנה הנה כל הפרשה כפשוטה ומשמעה
@37 **גם בי התאנף ה' בגללכם** . יאמר הנה חטאתיכם אשר עשיתם בעת ההיא במרגלים מנעו מכם הארץ הטובה ועוד הוספתם לחטוא בפעם אחרת עד שמנעתם גם אותי מלעבור כי רצה להזכיר יחד עונש כל הנמנעים מעבור אל הארץ כי הכל בגרמת עונותיהם וכדי שיזכיר כאן ענין יהושע כי הוא יעבור מפני שמלא אחרי ה' כחברו ויזכה עוד שינחיל הארץ לדור השני בעבור שנענש משה ונגזר עליו שלא יעבור והנה הזכיר כל המעשה ההוא זולתי מגיפת המרגלים עצמם וגם לא הזכיר הדבה כי לא ידבר בגנאי היחידים אבל יוכיח את הרבים שכולם חטאו וכולם נענשו וטעם בגללכם כי רבו בני ישראל את ה' וגו' (במדבר כ יג) ואירע כל זה בעבור מריבתכם או ירמוז שהיה הכעס על משה ועל אהרן כאשר הכו הסלע פעמים לפני העם ולא עשו כאשר נצטוו והעם הרהרו בדבר והוא מה שאמר (להלן לב נא) על אשר לא קדשתם אותי בתוך בני ישראל שלא היה העונש אלא מפני שהיה הדבר בתוך בני ישראל שלא נתקדש הכבוד לעיניהם וכך אמר בספרי (האזינו נ) על אשר מעלתם בי (שם) אתם גרמתם למעול על אשר לא קדשתם אותי אתם גרמתם שלא לקדש אותי כאשר מריתם פי (במדבר כז יד) אתם גרמתם למרות את פי עשו כל הלשונות יוצאים אל ישראל וכבר פירשתי הענין (שם כ ח)
@41 **וטעם אנחנו** . בעצמנו נעלה ונלחמנו לא נניח הדבר לבנינו אחרינו כאשר אמרת
@45 **ותשבו ותבכו לפני ה'** . לא הזכיר שם הכתוב הבכי הזה שאין צורך להזכירו אבל משה הזכיר זה עתה לשבח כי נחמו על חטאתם ולהגיד להם שהיה העון ההוא גדול מנשוא כי באה עליו השבועה הגדולה וגזר דין שיש עמו שבועה אינו נקרע (ר"ה יח)
@50 **וטעם אחיכם בני עשו** . שיחוס ישראל מן אברהם וכל זרעו אחים כי כולם הם נמולים וזה טעם לא תתעב אדומי כי אחיך הוא (להלן כג ח) רק בני הפלגשים ישמעאל ומדין וכל בני קטורה אינם באחוה מן הכתוב כי ביצחק יקרא לך זרע (בראשית כא יב)
@52 **אכל תשברו מאתם בכסף** . אם תתאוו לאכול מפירות ארצם לא תקחו מהם רק בכסף מלא לרצונם וזה טעם "מאתם" וגם מים לא תשתו מהם כלל רק בכסף לרצונם
@53 **כי ה' אלהיך ברכך** . לפיכך לא תכפרו את טובתו להראות כאלו אתם עניים אלא תראו עצמכם עשירים לשון רש"י ולא הבינותי מהו "בכל מעשה ידך" כי ברכותם ברכות שמים היו והם לא יעשו בידיהם דבר שיתברך ואולי ירמוז ב"מעשה ידך" שנתברך עמם צאן ומקנה אשר הוציאו ממצרים ויש להם עושר ומקנה וקנין משלל מצרים ומשלל עמלק והכל נתברך בידם כענין מעשה ידיו ברכת ומקנהו פרץ בארץ (איוב א י) ועוד ידע ה' לכתך את המדבר הגדול הזה וספק שם כל צרכך במן והשלו ומי הבאר שלא חסרת דבר מן הצריך להולכי ארחות והנה כן היה שקנו מבני עשו אוכל ומזון כמו שאמר (להלן פסוקים כח כט) אכל בכסף תשברני ואכלתי ומים בכסף תתן לי ושתיתי וגו' כאשר עשו לי בני עשו וגו'
@56 **האמים לפנים וגו'** . אתה סבור שזו ארץ רפאים שנתתי לאברהם לפי שהאמים שהם רפאים ישבו בה, אבל לא זו היא, כי אותם רפאים הורשתי מפני בני לוט והושבתים תחתם.
@56 רפאים היו נחשבים אותן אמים כענקים הנקראים רפאים על שם שכל הרואה אותן ידיו מתרפות.
@56 אמים על שם שאימתם מוטלת על הבריות. לשון רש"י.
@56 וכן כתב (בפסוק כ) "ארץ רפאים תחשב אף היא" לפי שהרפאים ישבו בה לפנים אבל לא זו היא שנתתי לאברהם.
@56 ואני תמה בדברי הרב: למה יפרש לנו הכתוב בארץ עמון ומואב שאינה ארץ רפאים שנתן לאברהם? אם לומר שאינה ראויה לישראל ואינה מן הארץ אשר נשבע ה' לאבותיהם לתת להם, והלא הכתוב אינו אומר אלא "כי לבני לוט נתתיה ירושה" (פסוק יט) לומר שאף על פי שהיתה מנחלת אברהם הקב"ה נתנה לבני לוט בעבור אברהם, וכמו שכתב רש"י עצמו (בפסוק ה) שנתן שתים לבני לוט בשכר שהלך אתו למצרים ושתק על מה שאמר על אשתו אחותי היא. ועוד שהרב בעצמו כתב בעשו עשר עממים נתתי לו לאברהם שבעה לכם וקיני וקנזי וקדמוני הן עמון ומואב והר שעיר, אחת מהן לעשו והשתים לבני לוט, ואם כן הרי ארץ עמון ומואב והר שעיר מנחלתו של אברהם היא על כל פנים, ולמה הקב"ה אומר למשה שלא יהא סבור שהיא ארץ הרפאים של אברהם? מה בין קיני וקנזי וקדמוני לרפאים? ועוד כי "רפאים ישבו בה לפנים" (פסוק כ) לומר שהיא שלהם והם היושבים בה לפני כל אדם כמו "לפנים הארץ יסדת" (תהלים קב כו)?
@56 אבל פירוש הפסוקים הפך מדברי הרב, כי בעבור שאמר הקב"ה למשה: אל תצר את מואב כי אני נתתי לבני לוט את ער ירושה, יספר הכתוב כי הארץ ראויה לזרע אברהם לולי שנתנה לבני לוט, ואמר כי הארץ ההיא ישבו בה מעולם עם גדול ורם כענקים ולכך יקראו אותם המואבים אמים לגודל האימה אשר יטילו על רואיהם, והנה השם עשה נס לבני לוט לכבוד אברהם ויכלו להם וירשום מפניהם, ואין ראוי לגזול מהם הארץ אשר נתן ה' להם במעשה נס. "יחשבו" לשון חשיבות ומעלה, כמו "נבזה ולא חשבנוהו" (ישעיהו נג ג) "אשר כסף לא יחשבו" (שם יג יז) "כי במה נחשב הוא" (שם ב כב) וכן רבים, ובלשון חכמים "אדם חשוב".
@56 וזהו שסמך הכתוב לזה (פסוק יב) "ובשעיר ישבו החורים לפנים" יאמר כי בעבור הטעם הזה שהזכיר במואב ימנעם גם כן מארץ שעיר, כי מלפנים היתה אף היא מן החורים, והיא ממתנת אברהם, כי החורי הוא החוי והוא מבני כנען שנאמר (בראשית לו ב) "עשו לקח את נשיו מבנות כנען" וגו' "ואת אהליבמה בת ענה בת צבעון החוי" וצבעון היה מבני שעיר החורי יושבי הארץ (שם פסוק כ). וכן יזכיר בכל מקום בנחלת ישראל החוי עם הכנעני בשבעת הגוים כי הוא נמנה הבן הששי בבני כנען (שם י יז). וכן תראה במלחמת אמרפל שהיה נלחם במלך סדום ועמורה ואדמה וצבויים וצער שהם מלכי כנען והכו את רפאים בעשתרות קרנים והחורי בהררם שעיר (שם יד ה ו) כי החורי והרפאים למלכי כנען היו ויתכן שנקרא "חוי" על שם שהיה נחש עלי דרך ונקרא "חורי" על שם חור פתן (ישעיהו יא ח), כי השמות ישמרו הטעם ויחליפו המלות כמו זרח וצחר (בראשית מו י) מן וצמר צחר (יחזקאל כז יח) אתונות צחורות (שופטים ה י) וכן יעשו לשבח יכנו יעקב שהוא לשון מרמה או לשון עקלקלות ויקראו אותו ישרון מן תם וישר. והנה אמר כי החורים שהם לאברהם ישבו בשעיר לפנים ובני עשו שהם זרע לאברהם ירשו אותם וישבו תחתם במעשה נס שהיו הם עם רב בארצם ועשו בא לגור שם ונתחזק עליהם כאשר עשה ישראל ליתר הגוים של אברהם אשר נתן השם להם בכחו הגדול. והנה הנחיל השם כל העמים ההם לזרעו של אברהם: אחד מהם לעשו והשאר לישראל שהוא הבן הבכור ואין ראוי לגזול מעשו את אשר הורישם האלהים כי השם יקצוף על הגוזל מהם נחלה שהנחילם הוא יתברך כאשר יקצוף על הגוזל מישראל הארץ אחרי שינחילנה להם. וכענין שיאמר (ירמיהו יב יד) "עַל כָּל שְׁכֵנַי הָרָעִים הַנֹּגְעִים בַּנַּחֲלָה אֲשֶׁר הִנְחַלְתִּי אֶת עַמִּי" וגו'
@56 וזה טעם "כאשר עשה ישראל" שהזכיר כאן ועדיין לא נעשה, וכן אמר עוד בבני עמון שהיא מארץ רפאים (פסוק כ) כי גם היא היתה של רפאים בתחלה, והעמונים יקראו להם זמזמים מלשון "זממו אל תפק" (תהלים קמ ט) אלא שנכפל כלומר עם שלא יבצר מהם כל אשר יזמו לעשות.
@66 **תחשב** . שהיא בחשבון ארץ רפאים כלומר שהיא מכללה וכן מן השיחור אשר על פני מצרים ועד גבול עקרון צפונה לכנעני תחשב (יהושע יג ג) וכן בני רמון הבארותי מבני בנימין כי גם בארות תחשב על בנימין ( ד ב) ואפשר שגם כן פירוש "יחשבו אף הם" הכתוב למעלה יאמר האמים אשר ישבו בה לפנים גם הם יחשבו רפאים שהיו מכללם והם כענקים ולכן יקראו אותם אמים והוא הנכון והנה ארץ רפאים היתה גדולה מאד ולקחו מהם מואב ולקחו מהם בני עמון ונשארה ממנה לרפאים עצמם כי עוג היושב בעשתרות מהם כמו שאמר (בראשית יד ה) ויכו את רפאים בעשתרות קרנים וביהושע (יז טו) ובראת לך שם בארץ הפרזי והרפאים ולכן יאמר הכתוב בגבול מואב ועמון כי לרפאים יחשב והמואבים והעמונים הם ששנו להם שמות אחרים אמים וזמזומים
@69 **והעוים הישבים בחצרים עד עזה** . יאמר כי העוים היושבים בערי חצרים אשר אין להם חומה סביב עד עזה שהוא גבול הכנעני כמו שנאמר (בראשית י יט) ויהי גבול הכנעני מצידן באכה גררה עד עזה הכפתורים שיצאו מכפתור השמידום והם יושבים תחתם והנה הכפתורים שהם מבני מצרים (שם פסוקים יג יד) ואינם ממתנת אברהם ארצם היא של ישראל מפני שהכפתורים לכדו אותה מבני כנען והכתוב שאמר על ארץ פלשתים (שם כו ג) כי לך ולזרעך אתן את כל הארצות האל מן הטעם הזה היה כי הארץ ההיא היתה מתחלה לבני כנען ומפני זה הורישו ישראל בימי יהושע חמשת סרני פלשתים העזתי האשדודי האשקלוני הגתי והעקרוני והעוים (יהושע יג ג) שהיו כולם יושבי גבול הכנעני בעזה ובאשקלון ובאשדוד ועקרון ועל שם מקומם הם נקראים כי השמידו העוים שהיו מבני כנען היושבים בגבול הכנעני מצידון בואכה גררה עד עזה וישבו תחתם וצידון גם היא לפלשתים כמו שכתוב (יואל ד ד) וגם מה אתם לי צור וצידון וכל גלילות פלשת ועל דעתי העוים הם החוים כי המנהג בכתוב שיחליפו השמות כאשר אמרנו (לעיל פסוק י) בהיותם מורים על ענין אחד והנחש יעות עצמו בדרך ובבראשית רבה (כו ז) אמר ר' אלעזר ברבי שמעון שהיו בקיאין בעפרות כנחש בגלילא צוחין לחויא עויא ונהגו בו חכמים לקרותו עכנא ולקרותו חכינא ואמרו (רות רבה ה ו) ויעתר לו וישמע תחנתו (דהי"ב לג יג) אמר רבי לוי בערביא צוחין לחתירה עתירה ואמרו (איכה רבה ב ב) איכה יעיב באפו ה' אמר רבי חמא בר' חנינא איך חייב ה' ברוגזו אית אתרא דצוחין לחיבא איבא חוקים עוקים ומורגל הוא בלשון ומה עויא אומר בדבר זה על רבי חייא וכן נהגו רבותינו לומר על "היסח הדעת" שהוא במקום "היסע הדעת" ובירושלמי לעולם "הסיעו" ובמשנה והסיע את לבו מלאכול וכן אמרו המפרשים בעושו ובאו כל הגוים (יואל ד יא) שהוא חושו ובמכילתא (בא ז) ר' יאשיה אומר על תקרי ופסחתי אלא ופסעתי שהמקום ב"ה מדלג על בתי בני ישראל עשאו מלשון פסיעות בחלוף חי"ת בעי"ן ועתה השלים להודיענו כל ארץ החוי שאבדה מהם כי ממנה לעשו והיא אסורה לנו וממנה לכפתורים ונקח אותה מהם ובבראשית רבה (שם) מצאתי כי העוים הם רפאים אמרו בפסוק הנפילים היו בארץ (בראשית ו ד) רפאים הם העוים רפאים שכל מי שרואה אותם לבו רפה כשעוה עוים שהיו בקיאין בעפרות כנחש וכו' ועוד אמרו שם (ב"ר מד כג) במתנתו של אברהם רבי דוסתאי בשם רבי שמואל לפי שאינו מזכיר כאן חוי לפיכך הוא מביא רפאים תחתיהם וכאשר עיינתי בזה מצאתי כי הדבר אמת ויציב ונכון וקיים כי השבעה גוים שירשו ישראל שהזכירם משה רבינו להם כמו שאמר (להלן ז א) ונשל גוים רבים מפניך החתי והגרגשי והאמורי והכנעני והפרזי והחוי והיבוסי שבעה גוים רבים ועצומים והששה מאלו נזכרים במתנתו של אברהם והחוי לא נזכר שם ועל כל פנים הוא הרפאים או מן קיני קנזי וקדמוני ורבותינו (ב"ר שם) כלם אומרים כי קיני קנזי וקדמוני לא נחלו ישראל ועתיד להנחילם להם ובהם נאמר ואם ירחיב ה' אלהיך את גבולך ונתן לך את כל הארץ אשר דבר לתת לאבותיך (להלן יט ח) וכן לא הוזכר בשום מקום שנחלום בימי יהושע אם כן הרפאים שנתן לאברהם הוא החוי שהוא הבן הששי לכנען (בראשית י יז) ואביו קרא לו חוי ובימי אברהם כנו לו רפאים ועל דעתי הוא שם מכונה מן החוי על שם חור פתן ומאורת צפעוני (ישעיהו יא ח) כי הטמונים בעפר יקרא הלשון רפאים כמו הרפאים יחוללו מתחת מים ושוכניהם (איוב כו ה) וארץ רפאים תפיל (ישעיהו כו יט) והנה בני החוי הזה רבו למעלה וכאשר נפוצו משפחות הכנעני נחלה המשפחה הזאת ארצות גדולות ומהם שתקרא ארץ רפאים ומהם חורים ומהם עוים ובכללם כלם חוי וכולם רפאים כאשר בעמנו אפרים יהודה וישראל ובכללם כולם ישראל והשמות האלה כולם מתוארים מן החוי כי כאשר היה שמו חוי כנו לו מן חויא רפאים שהנחש שוכן בחורי עפר והחורי והעוי על שם הנחש כמו כן כאשר פירשתי (לעיל פסוק י) והקב"ה נתן לאברהם הרפאים בכללם ומשה יזכיר לישראל החוי השם הראשון שקרא לו אביו כי ארץ רפאים בימי משה כבר נחלקה וממנה אסורה לישראל והנה הכתוב בא להזכיר בכאן ענין כל ארץ החוי שהם הרפאים וכל הנעשה ממנה אמר תחלה כי האמים גם הם מן הרפאים וירש אותם מואב וחזר ואמר כי החורי אשר הם גם כן מן רפאים ירש אותם עשו וחזר עוד ואמר כי ארץ בני עמון אף היא ארץ רפאים ואסר כל זה לישראל ועוד ספר כי גם כפתורים היוצאים מכפתור לקחו מארצם והיא מותרת לישראל והזכיר יהושע ארץ הפרזי והרפאים (יהושע יז טו) אבל רש"י כתב עוים מפלשתים הם שעמהם נחשבים בספר יהושע (יג ג) העזתי והאשדודי האשקלוני הגתי והעקרוני והעוים ומפני השבועה שנשבע אברהם לאבימלך לא יכלו ישראל ללכת בארצם ולהוציאם מארצם הבאתי עליהם כפתורים והשמידום וישבו תחתם ועכשיו אתם מותרים לקחת מידם ולא נתכוונו אצלי דברים הללו כי הכתוב לא ימנה העוים מפלשתים אבל ימנה חמשת סרני פלשתים ויזכירם ואחרי כן יזכיר העוים בעם אחר יאמר כי מן השיחור אשר על פני מצרים ועד גבול עקרון צפונה הכל תחשב מארץ כנען חמשת סרני פלשתים אשר ימנה וגם העוים שהם גוי אחר ולדברי הרב הנה הותרו העוים שירשו אותם כפתורים ושאר סרני פלשתים מי התירם ולמה יכבשו את כלם כי יהושע הוא המכבש את הפלשתים והעוים ועוד למה תהיה ארץ פלשתים לאברהם כלל ולמה הוצרך אבימלך לבריתו בזה ופלשתים מבני מצרים היו וכן הכפתורים ואינם מעשר עממין אבל הדבר בהפך כי הכפתורים והפלשתים השמידו מן הכנענים כי אבימלך מלך גרר היה והעזתי יושב בעזה וצידון עיר פלשתים ואלה מגבול הכנעני הם שנאמר ויהי גבול הכנעני מצידון באכה גררה עד עזה והנראה בעיני כי פלשתים וכפתורים יחשבו עם אחד וכן אמר הכתוב (ירמיהו מז ד) כי שודד ה' את פלשתים שארית אי כפתור וזה טעם "כפתורים היוצאים מכפתור" כי יצאו מכפתור עם מעט לגור באשר ימצאו והשמידו את העוים היושבים עד עזה שהם מזרע כנען וישבו תחתם בעזה ואשקלון ואשדוד וגת ועקרון והכל מגבולות כנען וחלקו אותה לחמשה סרניהם ושם הגלילות ההם פלשת ונקראו גם הם פלשתים ונשאר לעוים יתר ארצם כאשר הזכיר יהושע וזהו שאמר (שם) פלשתים שארית אי כפתור כי פלשתים הם וזה טעם אשר יצאו משם פלשתים ואת כפתורים (בראשית י יד) כמו שפירשתי שם ומה שאמר הכתוב (עמוס ט ז) הלא את ישראל העליתי מארץ מצרים ופלשתיים מכפתור וארם מקיר יספר מלחמות ה' כי הוא אשר העלה את ישראל מארץ מצרים באותות ובמופתים ובמלחמה והעלה פלשתים מכפתור ארצם כי הוציאם משם לתת להם בנס גדול את העוים והשמידום וישבו תחתם ועזבו כפתור לאחיהם או שהיה הענין כאשר הזכרתי כי העוים בני כנען יושבי הארץ בראשונה היה שמם פלשתים כי שם הארץ פלשת והכפתורים היוצאים מכפתור כאשר השמידום הגלו מהם לכפתור ארצם אשר היא מכלל ארץ מצרים ליד אחיהם וה' גאלם משם וחזרו למקומם לא ידענו באי זה דור מן הדורות והנה פלשתים יושבי ארץ כנען הם ולכך אמר הכתוב (צפניה ב ה) דבר ה' עליכם כנען ארץ פלשתים והאבדתיך מאין יושב וכן ישראל לא הורישו פלשתים עד שעבר זמן השבועה שמתו שלשה דורות מן הפלשתים באותה הארץ של אבימלך וכן אמרו במדרש (מכילתא ריש בשלח) כי קרוב הוא קרובה השבועה שנשבע אברהם לאבימלך עדיין נכדו קיים זהו הראוי והנכון בענין הזה אבל בגמרא בפרק ואלו טרפות (חולין ס) אמרו כדברי רש"י במחלוקת ורב אמר התם עוים מתימן באו ותניא כותיה ותימן זרע אדום כדכתיב (ירמיהו מט ז) לאדום כה אמר ה' צבאות האין עוד חכמה בתימן וזה אפשר הוא ויאמר הכתוב כי העוים שהם מבני עשו קצת ארצם טהרה ביד הכפתורים כעמון ומואב שטהרו בסיחון ומה שכתבתי הוא הטוב והישר
@70 **ראה נתתי בידך את סיחן** . הדבור הזה הוא האמור למטה (פסוק לא) ראה החלותי תת לפניך וקודם לכן שלח לו מלאכים ממדבר קדמות כי אחרי שיצונו השם החל רש והתגר בו מלחמה לא ישלח לו דברי שלום אעברה בארצך כי אם ישמע אליו יהיה עובר על דברי השם ואם ידע שלא ישמע יהיה שליחותו לריק ולא תחשוב לומר כי היא המצוה שנצטוינו (להלן כ י) כי תקרב אל עיר להלחם עליה וקראת אליה לשלום כי שם כתוב (בפסוק יא) והיה כל העם הנמצא בה יהיו לך למס ועבדוך וכאן אם שמע להם לא היו נוגעים בו כלל אבל פירוש "ואשלח מלאכים" כבר שלחתי מלאכים אבל הקדים דברי השם לבאר כי הקשה ה' אלהיך את רוחו (בפסוק ל) לומר כי הכל סבה מאת השם כי כן אמר לי
@71 **וטעם אחל תת פחדך** . כנגד ישראל שייראום כל העמים ואנשי כנען בלב נמס יצאו לקראתם אבל הקשה השם את רוחם לאמר טוב מותנו בחרבם מלהיות להם עבדים כי מה טעם לומר במשה אחל תת פחדך ויראתך על פני העמים תחת כל השמים והוא לא ילחם רק בשני המלכים האלה אבל היא הבטחה לישראל וליהושע כאשר אמר לו (להלן ג כא) עינך הרואות וגו' וזה טעם החל רש לרשת את ארצו (פסוק לא)
@80 **ונחרם את כל עיר מתים והנשים והטף** . שהיו מן האמורי ונצטוו בכך שנאמר (להלן כ טז) רק מערי העמים האלה אשר ה' אלהיך נותן לך נחלה לא תחיה כל נשמה ואף על פי כן פתח להם בשלום שכך היא המצוה כאשר אפרש בעה"י (להלן כ י) אבל לעוג מלך הבשן לא קרא לשלום שהוא יצא אליו למלחמה קודם שבאו לעיר שלו כלל וכבר פירשתי הענין בסדר זאת חקת (במדבר כא כא)
@92 **צידנים יקראו לחרמון שרין** . ובמקום אחר הוא אומר (להלן ד מח) עד הר שיאון הוא חרמון הרי לו ארבע שמות להגיד שבח ארץ ישראל שהיו ארבע מלכיות מתפארות בכך זה אומר על שמי יקרא וזה אומר על שמי יקרא לשון רש"י מדברי אגדה (ספרי עקב לז) ויתכן שיהיה השבח הזה כך אבל עיקר הכתוב לומר כי צידונים בני בכור כנען יקראו לחרמון שריון בהיותו בידם מלפנים והאמורי היושב בה עכשיו אשר מהם ילכדו אותו ישראל יקראו לו שניר והוא שלג בלשון כנען כמו שרש"י מעיד עליו וכן תרגם אונקלוס ובעבור שהוא הר השלג ומפני הקרירות יהיה חרם יקרא חרמון והוא לו שם כנוי ואולי גם לשון שריון בלשון הצידונים שם שיורה על כך ושם ההר שיאון והכתוב שאמר (שיר השירים ד ח) מראש שניר וחרמון יקראנו בשני כנויין מראש השלג והחרם או טעמו מראש שניר ומכל ההר וכן מה שאמר בדברי הימים (א ה כג) ובני חצי שבט מנשה ישבו בארץ מבשן עד בעל חרמון ושניר והר חרמון המה רבו גם כן פירושו ושניר וכל ההר שהוא הר חרמון אבל "בעל חרמון" עיר או מגדל קראו לו בעל או שהיה שם נעבד אחד מהבעלים ויתכן שאחרי היות ישראל בארץ הוחלפו השמות קצת והיה ההר ההוא גדול וקראו לחלק הגבוה אשר בראשו שניר ולחלק השני חרמון או הם הרים אחרים קראו להם כן אחר התורה ורבים כן וכן וחרמונים מהר מצער (תהלים מב ז)
@94 **כי רק עוג מלך הבשן נשאר מיתר הרפאים הנה ערשו ערש ברזל וגו'** . ענין הכתוב שבא להגיד כי עוג זה נקרא מלך האמורי בעבור כי מלך עליהם אבל הוא עצמו מן הרפאים הוא ולהגיד על גבהו וגודלו כי היו הרפאים עם גדול ורם כענקים אמר כי ערשו ערש ברזל לא יסבול אותו ערש עצים כשאר בני אדם והוא בעיר רבה שהיתה עיר מושבו וכאשר השמידו בני עמון את הרפאים כאשר נזכר למעלה (ב כא) ונלכדה עירו ניצל הוא לבדו מידם וזהו שנאמר כי רק עוג נשאר מיתר הרפאים והנה נשארה מטתו שמה ברבה אשר היא עתה לבני עמון והעמונים קיימו אותה לעדות כי השמידו עם גדול ורם והאיש הגבור אשר כגובה ארזים גבהו וחסון הוא כאלונים לכדו ממנו מלכותו וזה טעם "הנה" כלומר הנה העדות קיימת שהיא ערש ברזל וארוכה ורחבה מאד וקיימת היא ברבת בני עמון כי ערשו אשר בעשתרות היתה לשלל ואבדה וטעם באמת איש הגדול בבני אדם כמו וחזקת והיית לאיש (מלכים א ב ב) ועל דעת אונקלוס באמת איש באמת האיש ותרגום מלך וכן את הכבש אחד (במדבר כח ד) בלילה הוא (בראשית יט לג) וכן רבים כלומר באמת עוג עצמו
@96 **כל חבל הארגב לכל הבשן ההוא יקרא ארץ רפאים** . פירוש וכל חבל הארגוב לכל הבשן אשר הוא נקרא ארץ רפאים כלשון וכל ההקדיש שמואל הרואה ושאול בן קיש (דהי"א כו כח) ההושיבו נשים נכריות (עזרא י יז) שהה"א בהם במקום אשר וכן רבים והיה נקרא מכלל ארץ רפאים על שם עוג המולך בה או מפני שהיתה מתחלה לרפאים ונשארה לעוג כי הוא והעם היושב בה מיתר הרפאים
@106 **ואתחנן אל ה' בעת ההוא לאמר** . כאשר הזכיר כבוש ארץ סיחון ועוג ואמר (לעיל פסוק כא) ואת יהושע צויתי בעת ההיא הזכיר כי אני לא אעבור שם כי התחננתי אל השם הנכבד ולא שמע אלי וצוה אותי לחזק את יהושע כי הוא יעבור וטעם בעת ההיא רמז לעת הגזרה שהזכיר (לעיל א לז) גם בי התאנף ה' ולא נזכרה שם התחנה ביום המעשה והנכון כי "בעת ההיא" בעת הנזכרת שכבשתי סיחון ועוג והתחלתי להלחם בעממין שניתנו לישראל וחלקתי הארץ לשני השבטים והיה זה כאשר נאמר לו (במדבר כז יב) עלה אל הר העברים הזה כי אז בקש רחמים על הדבר והתחנן התחנה הזאת וכאשר לא שמע השם בקולו חזר והתפלל יפקוד ה' אלהי הרוחות לכל בשר איש על העדה כמו שנזכר שם (פסוק טז) וזהו וצו את יהושע (להלן פסוק כח) אבל הזכיר שם התפלה אשר נענה עליה וכאן הזכיר זה להודיע כי הארץ היתה חביבה עליו מאד ולא זכה אליה בעבורם וכל זה מתוכחותיו
@107 **ה' אלהים** . רחום בדין לשון רש"י ולא השגיח הרב כי השם הראשון הוא כתוב באל"ף דל"ת והשני הוא כתוב ביו"ד ה"א שבו אמרו כל מקום שנאמר ה' זו מדת רחמים אלהים זו מדת הדין אבל השמות הנזכרים כאן אדון במדת רחמים וכך אמרו בילמדנו אמר לו רבון העולמים אי מתבעי לי בדין הב לי ואי לא מתבעי לי בדין רחם עלי כשם שאמר אברהם ה' אלהים מה תתן לי וגו' וגם באברהם כך הם כתובים הראשון אל"ף דל"ת והשני יו"ד ה"א וענין הפרשה יובן בזה כי אמר "ואתחנן" ולא אמר "ואתפלל" כי ידבר בתחנה ואמר אדון אשר בך הרחמים אתה החלות להראות את עבדך כך היא תחלת נבואתי שהראית לי כבודך דכתיב ויסתר משה פניו כי ירא מהביט אל האלהים (שמות ג ו) עם הגדולה והגבורה והראיתי לדעת מי אל בשמים ובארץ שממנו יהיו כמעשיך הגדולים וכגבורותיך החזקות ומכאן תבין עוד במה התאנף בו השם הנכבד אבל לשון ספרי (ואתחנן כד) כל מקום שנאמר ה' זו מדת רחמים שנאמר ה' אל רחום וחנון אלהים זו היא מדת הדין שנאמר עד האלהים יבוא דבר שניהם והכוונה לפרש כי השם השני בכאן הוא מדת הרחמים והוא השם המיוחד ושאר השמות כולן מדת הדין כמו אלהים שהוא שם גם לדיינים וכל שכן אל"ף דל"ת שהוא לשון אדונים והנה השלים התוכחות בזה שהודיע אותם שגרמו אבותיהם רעה על עצמם וגם עליו גרמו עונש שלא יעברו לארץ אבל הם הבנים יעברו ויירשו אותה אם לא יהיו כאבותם דור סורר ומורה ולכך יתחיל עתה להזהירם בכללי המצות שלא יוסיפו עליהם ולא יגרעו מהם
@114 **לא תוסיפו** . כגון חמש פרשיות בתפילין חמשה מינין בלולב חמש ציציות וכן לא תגרעו לשון רש"י וכך אמרו בספרי (ראה) מנין שלא תוסיף על הלולב ועל הציצית ת"ל לא תוסיפו ומנין שאין פוחתים מהן ת"ל לא תגרעו מנין שאם פתח לברך ברכת כהנים לא יאמר הואיל ופתחתי לברך אומר ה' אלהי אבותיכם יוסף עליכם ת"ל הדבר אפילו דבר לא תוסף עליו אבל לא באלה בלבד אמרו אלא אף הישן בסוכה בשמיני בכונה לוקה כמו שמוזכר במסכת ראש השנה (כח) וכן אם יעשה החג ששה עובר בלאו הזה ולפי דעתי אפילו בדא לעשות מצוה בפני עצמה כגון שעשה חג בחדש שבדא מלבו כירבעם (מלכים א יב לג) עובר בלאו וכך אמרו (מגילה יד) לענין מקרא מגלה מאה ושמונים נביאים עמדו להם לישראל ולא פחתו ולא הוסיפו על מה שכתוב בתורה אפילו אות אחת חוץ ממקרא מגילה מאי דרוש וכו' ובירושלמי (מגילה פ"א ה"ז) שמונים וחמשה זקנים ומהם כמה נביאים היו מצטערים על הדבר אמרו כתוב אלה המצות אשר צוה ה' את משה אלו המצות שנצטוו מפי משה כך אמר לנו משה ואין נביא אחר עתיד לחדש דבר לכם ומרדכי ואסתר רוצים לחדש לנו דבר לא זזו משם נושאין ונותנין בדבר עד שהאיר הקב"ה עיניהם וכו' הרי שהיתה המצוה הזו אסורה להם א"כ היא בכלל לא תוסיף עליו אלא שלא למדנו למוסיף על פי נביא אלא מן הכתוב שאמר "אלה המצות" אין נביא רשאי לחדש בו דבר מעתה ומה שתקנו חכמים משום גדר כגון שניות לעריות וכיוצא בהן זו היא מצוה מן התורה ובלבד שידע שהם משום הגדר הזה ואינן מפי הקב"ה בתורה
@115 **עיניכם הראות** . עתה בא להזהיר בפרטי המצות ויתחיל בעבודת כוכבים שהיא שורש לכולן
@117 וטעם "ראה למדתי אתכם" - ראה שאני מלמד אתכם היום, כמו שאמר (דברים יא יג): "אשר אנכי מצוה אתכם היום", ו(דברים ד ח): "אשר אנכי נותן לפניכם היום".
@117 או יאמר למדתי מפני שהזכיר לעשות כן בקרב הארץ, כלומר, ראה בעת בואך לארץ שלמדתי אתכם חקים ומשפטים כאשר צוני ה' אלהי.
@117 והנה, מתחלה דיבר על הדבר שהיא כלל לכל, עשה ולא תעשה; ועתה יזהיר בחוקים, שהם גזרותיו, ובמשפטים, שהם הדינים, כי אלו הם צריכין חזוק יותר, מפני העלם טעם החוקים, ומפני כי במשפט יעמידו ארץ.
@117 ואמר לעשות כן בקרב הארץ, להזהיר על כולם, כי יש חוקים רבים ומשפטים שאינן נוהגין בחוצה לארץ; או ירמוז שעיקר המצות כולן בארץ, כמו שרמזתי בסוד הארץ (ויקרא יח כה).
@118 ואמר כי בחוקים ובמשפטים תועלות גדולות, שהם תפארת לעושיהם מן האדם, ואפילו שונאיהם ישבחו אותם בהם.
@119 ועוד, שהם תועלת גדולה שאין כמותה, שהשם יהיה קרוב להם בכל קראם אליו, וכן העמים יתבוננו בזה וידעו כי החוקים נעשים בחכמה ובינה לקרבה אל האלהים וייראו מהם, וזהו שאמר כי מי גוי גדול.
@120 ועוד, שהחוקים והמשפטים בעצמם הם צדיקים, ישרים וטובים בישוב העם והמדינות.
@121 **רק השמר לך וגו' פן תשכח את הדברים** .
@121 (קטע:רש"י על דברים ד ט): "אז כשלא תשכחום ותעשום על אמתתם תחשבו חכמים ונבונים ואם תעוותו אותם מתוך שכחה תחשבו שוטים", לשון רש"י.
@121 ואינו נכון כלל, אבל הכתוב הזה לפי דעתי מצות לא תעשה, הזהיר בה מאד, כי כאשר אמר שנזהר בכל המצות ונשמור החוקים והמשפטים לעשותם, חזר ואמר "רק אני מזהירך מאד להשמר ולשמור עצמך מאד מאד לזכור מאין באו אליך המצות, שלא תשכח מעמד הר סיני מכל הדברים אשר ראו עיניך הקולות והלפידים, את כבודו ואת גדלו ודבריו אשר שמעת שם מתוך האש, ותודיע כל הדברים אשר ראו עיניך במעמד הנכבד ההוא לבניך ולבני בניך עד עולם".
@121 ופירש הטעם, כי השם עשה המעמד ההוא כדי שתלמדו ליראה אותו כל הימים ואת בניכם תלמדון לדורות עולם, אם כן עשו אתם ככה ואל תשכחו אותו.
@121 והנה, קודם שיזכיר הדברות שנאמרו שם, הזהיר במצות לא תעשה שלא נשכח דבר מן המעמד ההוא ולא נסירהו מלבנו לעולם, וצוה במצות עשה שנודיע בו לכל זרענו מדור לדור כל מה שהיה שם בראיה ובשמיעה.
@121 והתועלת במצוה הזאת גדולה מאד, שאם היו דברי התורה באים אלינו מפי משה בלבד, אע"פ שנבואתו נתאמתה באותות ובמופתים, אם יקום בקרבנו נביא או חולם חלום ויצונו בהפך מן התורה ונתן אלינו אות או מופת יכנס ספק בלב האנשים; אבל כשתגיע אלינו התורה מפי הגבורה לאזנינו ועינינו הרואות אין שם אמצעי, נכחיש כל חולק וכל מספק, ונשקר אותו, לא יועילהו אות ולא יצילהו מופת מן המיתה בידינו, כי אנחנו היודעים בשקרותו.
@121 זהו שאמר שם (שמות יט ט): "וגם בך יאמינו לעולם", כי כשנעתיק גם כן הדבר לבנינו, ידעו שהיה הדבר אמת בלא ספק כאלו ראוהו כל הדורות, כי לא נעיד שקר לבנינו ולא ננחיל אותם דבר הבל ואין בם מועיל, והם לא יסתפקו כלל בעדותנו שנעיד להם אבל יאמינו בודאי שראינו כולנו בעינינו וכל מה שספרנו להם.
@121 והענין הזה יבוא עוד בפרשת (דברים יג ב): "כי יקום בקרבך נביא או חולם חלום וגו'", וכבר הזכרתיו שם בפרשת "בחדש השלישי" (שמות יט ט).
@124 **וידבר ה' אליכם מתוך האש** . כבר פירשתי הדבר במקומו (שמות יט כ) שהם שמעו דבור השם הגדול יתברך מתוך האש שראו אשו הגדולה והשיגוה והוגד להם בזה בריתו בעשרת הדברים כי בכולן שמעו הקול מתוך האש ושאר המצות צוה אותי בעת ההיא ללמד אתכם כי כבר אני נאמן לנביא לה' במה שראיתם כמו שאמר וגם בך יאמינו לעולם כמו שפירשתי (בפסוק ט)
@127 **ונשמרתם מאד לנפשתיכם** . יזהירם פן יטעו אחר הקול אשר שמעו ויעשו השחתה לקצץ בנטיעות ואמר תחלה תבנית זכר או נקבה באדם שמהם יהיה קול ואחר כן הזכיר כל אשר בארץ בבהמה ובעוף וברמש האדמה ובדגי הים ואחר כן חזר אל צבא השמים
@131 **אשר חלק ה' אלהיך אתם לכל העמים** . כי לכולם כוכב ומזל וגבוהים עליהם מלאכי עליון כגון הנאמר בדניאל שר מלכות פרס ושר מלכות יון ובעבור כן יעשו להם אלהים מהם ויעבדום ואמר ואתכם לקח ה' כי אתם חלק השם לא תקימו עליכם שר או עוזר זולתו כי הוא הוציא אתכם מכור הברזל שהייתם בתוך מצרים בכור אש ועצים והוציא אתכם משם כנגד שריהם שעשה בהם שפטים ולולי שהפילם לא הייתם יוצאים כי היו הם במעלתם שלא תצאו והנה עשה כל זה כדי שתהיו לו נחלה ותהיו לשמו הגדול סגולה מכל העמים
@133 **וטעם וה' התאנף בי על דבריכם** . שהחזיר במקום הזה כלומר אותי צוה ה' בעת ההיא ללמד אתכם המצות לעשותכם אותם בארץ אשר אתם עוברים שמה ועתה קחו מפי תורה כי אנכי מת בארץ הזאת ולא אוכל ללמדם אתכם בארץ ואל תשכחו שם מה שלמדתי אתכם ולא מה שראיתם בסיני ועל דרך האמת יאמר השמרו מאד לנפשותיכם פן תשחיתון כי השם התאנף בי מדאגה מדבר זה פן תשכחו אתם ברית השם אלהיכם באש האוכלת בראש ההר ותעשו תמונת כל וזה טעם אשר צוך ה' אלהיך וכבר נרמז זה בסדר חקת התורה ורש"י כתב אשר צוך ה' אלהיך שלא תעשה והוא פשוטו של מקרא והמשכיל יבין הפסוקים האלה על אמתתם וטעם כי ה' אלהיך אש אכלה הוא כאשר ראיתם בראש ההר והכוונה שהוא מדת הדין המקנא בע"ז ומן הכתוב הזה תבין בכל הנזכר במשנה תורה תמיד "ה' אלהיך"
@137 **כי תוליד בנים ובני בנים ונושנתם** . ענין הכתוב הזה, שיזכיר ויאמר: כי תוליד בנים ובני בנים, ובעבור היותכם ישָנים בארץ ותשבו לבטח, אולי תשכחו את השם; העידותי בכם היום שתאבדו מהר, כי לא יאריך לכם, מאחר שתעבדו עבודה זרה.
@137 והפרשה הזו, אע"פ שהיא אזהרה, לא נאמרה בלשון "אם", והטעם, כי הוא כמתנבא על עניינם, וידבר בלשון ישמש בשני פנים, בלשון אזהרה ובלשון עתיד לבא, יאמר שיעשו ויהיה להם ככה ולא יגזור עליהם. ומפני זה אמרו רבותינו (גיטין פח א) שרמז לגלות בית ראשון במלת "ונושנתם" בגימטריא, והיתה קבלה בידם כי יש בפרשה הזאת רמז לזמן הגלות, וכאשר בא עליהם התבוננו בה בינה.
@137 ואמר "ועשיתם פסל תמונת כל", ולא אמר "ועבדתם אותו" או "והשתחויתם לו" אבל אמר "והשחתם", כי הפסל בכאן תמונת כל, ומפני השחתה יאסור אותו, כאשר פירשתי למעלה.
@139 **ונשארתם מתי מספר בגוים** . יאמר שנשאר מועטים בכל גוי וגוי מכל הגוים אשר ינהג אותנו שם כי בארבע רוחות השמים יפזר אותנו אבל בכללנו רבים אנחנו שבח לאל
@140 **ועבדתם שם אלהים** . משאתם עובדים לעובדיהם אתם עובדים להם לשון רש"י וכבר פירשתי סודו כי היושב בחוצה לארץ כאלו עובד עבודה זרה ומעשה ידי אדם מלמעלה למטה כמו שהזכרתי בסדר אחרי מות (ויקרא יח כה) וטעם ולא יאכלון ולא יריחון לומר שהם אבן דומם כאשר היו מתחילה אין בהם רוח חיים כלל אפילו כחיי האדם כי מתחלה אמר לא יראון ולא ישמעון לומר שאיננו אלוה ולא יראה בעני עובדיו ולא ישמע תפלתם ומצרתם לא יושיעם וחזר ואמר שאפילו חיים גרועים כחיי האדם אין בהם והנה העושה אותם נכבד מהם או יהיה טעם הכתוב כנגד כבוד עליון לומר אשר לא יראו בצרת עובדיהם ולא ישמעון תפלתם ולא יאכלון שלא תצא אש מלפניהם ותאכל את קרבנותם ולא יריחון בריח ניחוחיהם ותפש הכתוב לשון סתם שאין בהם החושים האלו כלל
@142 **ושבת עד ה' אלהיך ושמעת בקלו** . גם זה רמז לגאולת בבל ששבו אל השם והתודו לפניו ושמעו לקול הנביאים אשר הקים להם ולפיכך הבטיחם שלא ישחיתם ולא ישכח ברית אבותם כאשר אמר (ויקרא כו מב) וזכרתי את בריתי יעקוב וגו' ובסוף הספר ירמוז לגאולה העתידה כאשר פירשתי (שם בפסוק טז) ואזכרנו עוד בע"ה (להלן כח מב)
@144 **כי שאל נא לימים ראשונים** . יאמר לא ימחול ולא יאריך השם לכם על ע"ז ועל ההשחתה בפסל וכל תמונה כי עשה עמכם מה שלא עשה כן לכל גוי מעולם שהשמיעך קול אלהים מדבר מתוך האש למען תהיה יראתו על פניכם ותייחדו אותו ולא תשחיתו ולקח אתכם לו גוי מקרב גוי במסות באותות ובמופתים שלא תעבדו לזולתו והנה הראית בעיניך כל זה לדעת כי ה' הוא האלהים הוא אחד ושמו אחד ואין עוד מלבדו כי מן השמים השמיעך את קולו ללמדך בזה מוסר השכל ועל הארץ הראך את אשו הגדולה בוערת עד לב השמים ודבריו כולם שמעת מתוך האש ויוציאך בפניו כמו על פניו (בראשית לב כב) בכחו הגדול אשר בפניו ואחרי שהשם הגדול הוא האלהים בשמים ממעל ועל הארץ מתחת ואין עוד תשמור מצותיו וחקותיו למען ייטב לך בשמים ממעל ולמען תאריך ימים על הארץ מתחת
@153 **אז יבדיל משה שלש ערים** . פירש ר"א ביום שהבדיל משה שלש ערים אז אמר דברי הברית ואינו נכון אבל הוא כפשוטו כי משה אסף כל ישראל לבאר להם התורה ופתח להם בדברי התוכחות וכאשר אמר בפניהם תוכחותיו במה שעשו והאזהרות על ע"ז ועל יחוד השם והשלים להם שישמרו חוקיו ומצותיו למען ייטב להם אז אמר במעמדם לפניהם עתה נקיים המצוה אשר צונו השם ותהיינה בצר במדבר ורמות בגלעד וגולן בבשן ערי מקלט לנוס שמה כל רוצח בשגגה ואע"פ שאינן קולטות עד שיבדלו אותם שבארץ כנען אמר מצוה שבאה לידינו נקיים אותה למען ייטב לנו ואחרי כן קרא בקול גדול אל כל ישראל שהיו שם ואמר אליהם (להלן ה א) שמע ישראל את החקים ואת המשפטים וגו' כי עתה יפתח במצות ובביאור התורה כאשר פירשתי בתחלת סדר אלה הדברים
@159 **ויירשו את ארצו ואת ארץ עוג מלך הבשן מערוער וגו'** . והטעם כי שב להזכיר מה שאמר בתחלת הספר הזה (לעיל א ד) כי ביאור התורה הזה אחרי הכותו את סיחון מלך האמורי אשר יושב בחשבון ואת עוג מלך הבשן אשר יושב בעשתרות באדרעי היה והוסיף בכאן לפרש כי היה הביאור גם אחרי שירשו את כל ארצם כלומר שחלקה להם לשני המטות וחצי המטה
@166 **אנכי עומד בין ה' וביניכם בעת ההוא להגיד לכם את דבר ה'** . כי הוא היה עולה להר ושומע דברי השם ויורד ואומר להם עד שדבר השם עמהם פנים בפנים וזה רמז אל כל מה שנזכר בפרשת בחדש השלישי מתחלת כה תאמר לבית יעקב עד ויאמר אליו ה' לך רד (שמות יט ג-כד) ור"א אמר כי זה אחר מעמד הר סיני והטעם הוא דבר עמכם פנים בפנים ומאותו היום הייתי אני עומד בין השם וביניכם ואינו נכון והנכון בעיני כי ירמוז למה שפירשנו שם (כ ז) כי ישראל לא הבינו מפי הגבורה אלא אנכי ולא יהיה לך ושאר הדברות משה הוא המגיד להם מה שיאמר השם וזהו להגיד לכם את דבר ה' לפרש לכם כל דבור ודבור וטעם בין ה' וביניכם כי בעת הדברות היה הוא קרוב אל מקום השכינה יותר מהם כי הם הרחיקו לעצמם כאשר פירשתי שם (כ טו) וזהו כי יראתם ולא עליתם בהר שלא קרבתם אליו כאשר היה לכם רשות על כן הייתי אני עומד ביניכם ובין מקום הכבוד באמצע כי רחוק היה ביניכם וביניו ומשם הייתי אני מגיד הדברות
@166 "לאמר" - מוסב על דבר ה' עמכם בהר מתוך האש לאמר לשון רש"י ואמר ר"א אל תשית לבך בעבור היות מלת לאמר רחוקה כי כן רבים והמדבר לא הפסיק פסוקים ולא פרשיות ונכון יותר שנדביק להגיד לכם את דבר ה' לאמר כלשון והגדת לבנך ביום ההוא לאמר (שם יג ח) ולדעתי אין צורך כלל אבל טעמו כי יראתם מפני האש ולא עליתם בהר לאמר לא נעלה כי יראנו מפני האש יזכיר כי הם הגידו לו כן בפירוש ולא ממחשבתו יאמר כן
@167 **כאשר צוך ה' אלהיך** . קודם מתן תורה במרה שם שם לו חק ומשפט לשון רש"י ואם כן גם מצות כבוד אב ואם יהיה במרה והרב לא הזכיר שם אלא שבת פרה אדומה ודינין והנראה בעיני על דרך האמת בזה גם בכל משנה תורה כי משה ידבר כמפי הגבורה כמו שאמר (להלן יא יג יד) והיה אם שמוע תשמעו אל מצותי אשר אנכי מצוה אתכם היום לאהבה את ה' אלהיכם ולעבדו בכל לבבכם ובכל נפשכם ונתתי מטר ארצכם בעתו ואין משה הנותן מטר על פני הארץ ולא הנותן עשב בשדה אבל הדבור בתורה בזכור ובמשנה תורה בשמור ולכן יאמר משה בכל מקום במשנה תורה "ה' אלהיך" ובתורה יזכיר שם המיוחד בלבד זולתי בעשרת הדברות כמו שאמר (שמות כ א) וידבר אלהים וגו' והבן זה
@175 **ושורך וחמורך** . לבאר שיאסר גם בעבודת האדמה שהם חיי האדם וכענין שאמר (שם לד כא) בחריש ובקציר תשבות אמר כאן למען ינוח עבדך ואמתך כמוך וזכרת כי עבד היית וגו' לבאר כי בו יצוה במנוחת העבד כמוך בעבור שהיית עבד והניח לך השם וגם אתה תניח לעבדך והנה טעמו כשינוח עבדך ואמתך כמוך תזכור כי עבד היית וגו'
@176 **וטעם על כן צוך לעשות את יום השבת** . צוה שתעשה כן ביום השבת כך פירש ר"א ואינו נכון ואנו אומרים בקדוש היום "כי יום זה תחלה למקראי קדש זכר ליציאת מצרים" כאשר נאמר בו "זכר למעשה בראשית" והרב אמר בספר המורה (ב לא) כי המאמר הראשון הוא כבוד היום והדורו וכאשר אמר (שמות כ יא) על כן ברך ה' את יום השבת ויקדשהו ועל כן הזכיר טעם "כי ששת ימים עשה ה'" אבל בכאן יזהיר אותנו לשמור השבת בעבור היותנו עבדים במצרים עובדים כל היום על כרחנו ולא היתה לנו מנוחה והוא יצונו עתה לשבות ולנוח כדי שנזכיר חסדי השם עלינו בהוציאו אותנו מעבדות למנוחה והנה בשבת בכללה שני טעמים להאמין בחידוש העולם כי יש אלוה בורא ולזכור עוד החסד הגדול שעשה עמנו שאנחנו עבדיו אשר קנה אותנו לו לעבדים גם זה אינו מחוור אצלי כי בהיותנו שובתים ולא נעשה מלאכה ביום השביעי אין לנו בזה זכרון ליציאת מצרים ואין לרואה אותנו בטלים ממלאכה ידיעה בזה רק היא כשאר כל המצות אבל יהיה בו זכר למעשה בראשית שנשבות ביום ששבת השם וינפש והראוי יותר לומר כי בעבור היות יציאת מצרים מורה על אלוה קדמון מחדש חפץ ויכול כאשר פירשתי בדבור הראשון (שם שם ב) על כן אמר בכאן אם יעלה בלבך ספק על השבת המורה על החדוש והחפץ והיכולת תזכור מה שראו עיניך ביציאת מצרים שהיא לך לראיה ולזכר הנה השבת זכר ליציאת מצרים ויציאת מצרים זכר לשבת כי יזכרו בו ויאמרו השם הוא מחדש בכל אותות ומופתים ועושה בכל כרצונו כי הוא אשר ברא הכל במעשה בראשית וזה טעם על כן צוך ה' אלהיך לעשות את יום השבת והנה לא פירש כאן טעם השביתה כי ששת ימים עשה ה' וגו' שכבר הוזכר זה פעמים רבות בתורה אבל אמר בקצרה "ויום השביעי שבת לה' אלהיך" שהוא יתברך שבת בו וינפש ובאר להם כי מיציאת מצרים ידעו שהוא אמר והיה העולם ושבת ממנו ועל דרך האמת נוכל עוד להוסיף בזה כי הדבור הזה בשמור ליראה את השם הנכבד והנורא ועל כן יצונו שנזכור את היד החזקה והזרוע הנטויה שראינו ביציאת מצרים וממנו לנו היראה כמו שאמר (שם יד לא) וירא ישראל את היד הגדולה אשר עשה ה' במצרים וייראו העם את ה' ועל כן צוך ה' אלהיך לעשות את יום השבת שתהא כנסת ישראל בת זוגו לשבת כנרמז בדברי רבותינו (ב"ר יא ט) והמשכיל יבין
@178 **ולא תענה ברעך עד שוא** . לאסור להעיד על חברו אפילו דבר שאינו כלום ולא יתחייב בו כלום בבית דין כגון שיעיד אמר פלוני ליתן לזה מנה ולא קנה מידו כי "שוא" דבר בטל
@180 **מתוך האש הענן והערפל** . ביאור ל"מתוך האש" כי ענן וערפל סביביו קול גדול ולא יסף מתרגמינן ולא פסק לפי שמדת בשר ודם אינן יכולין לדבר דבריהם בנשימה אחת ומדת הקב"ה אינו כן לא היה פוסק ומשלא היה פוסק לא היה מוסיף לפי שקולו חזק וקיים לעולם ד"א לא יסף לא הוסיף להראות באותו פומבי לשון רש"י והכתוב אמר (שמות יט יט) ויהי קול השופר הולך וחזק מאד ואמרו (מכילתא יתרו ד) למה רך בתחלה לשכך את האוזן במה שיכולה לשמוע ואולי בקול השופר היה כן אבל קול השם בעשרת הדברות היה שוה והנכון כי האומר לא פסק עשה יסף מן ונאספה שמחה וגיל (ירמיהו מח לג) תוסף רוחם יגועון (תהלים קד כט) שענינם לדעתו המנע הדבר יאמר כי לא נמנע גדלו ותקפו עד שהשלים כל הדברות וכן אמר ויתנבאו ולא יספו (במדבר יא כה) ועל דרך הפשט ולא יסף שלא יסף להיות עוד גדול כמוהו ועל דרך האמת יאמר כי כל הדברים האלה שמעו קול גדול ולא יסף להשמיע אל כל קהלכם אלא קול אחד כי אותו קול בלבד השיגו הם וכבר פירשתי ענין זה שם (שמות יט כ) וכל הפרשה
@184 **אשר שמע קול אלהים חיים מדבר מתוך האש** . אמר ר"א כי טעם "חיים" להבדיל בין אלהים ובין הצבא כי לא יתנועע הוא מעצמו ויתכן לפרש שהזכיר כן לומר שהשומע קול אלהים שעמו מקור החיים תדבק נפשו ביסודה ולא תחיה עוד חיי בשרים ויהושע אמר (יהושע ג י יא) בזאת תדעון כי אל חי בקרבכם הנה ארון הברית אדון כל הארץ אם כן וישבע בחי העולם (דניאל יב ז) שבועה בשמו הגדול
@185 **ואת תדבר אלינו** . התשתם כחי כנקבה שנצטערתי עליכם ורפיתם את ידי כאשר ראיתי שאינכם חרדים להתקרב אליו מאהבה וכי לא היה יפה ללמוד מפי הגבורה ולא ממני לשון רש"י מדברי אגדה ואם כן יאמר שדאג להם אבל השם הודיעו כי מיראתו עשו וטוב להם והענין כאשר פירשתי שם (שמות כ טו) כי היו חושבים שירצה להשמיעם כל התורה והרצון היה לפניו להשמיעם עשרת הדברות בלבד כאשר בקשו ודע כי עתה בקשו ממשה שלא ישמעו קול השם הנכבד לא ביום הזה ולא בדור מן הדורות לעולם דלאו כל שעתא ושעתא מתרחיש ניסא ואינם חפצים במעמד כזה אבל יאמינו בנביאים ויעשו כל רצון השם על פיהם וכן יאמר להם משה (להלן יח טו טז) נביא מקרבך מאחיך כמוני יקים לך ה' אלהיך אליו תשמעון ככל אשר שאלת מעם ה' אלהיך בחורב וגו' וכל הפרשה ההיא אם כן השאלה הזאת לדורות היתה
@187 **מי יתן והיה לבבם זה להם ליראה אותי** . בעבור היות רשות האדם בידו להצדיק ולהרשיע והכל בידי שמים חוץ מיראת שמים יאמר הכתוב כן והוא כלשון בני אדם ועל דרך האמת הוא כמו ויאמר לאדם הן יראת אדני היא חכמה וסור מרע בינה (איוב כח כח) וכך אמרו בשכרן של מצות (מנחות כט) ראה שחותכין בשרו של ר' עקיבא במקולין אמר לו רבונו של עולם זו תורה וזה שכרה השיב לו הקב"ה שתוק כך עלה במחשבה לפני ותבין זה ממה שאמר (פסוק כח) ואתה פה עמוד עמדי
@189 **ועשו בארץ** . פרשתיו (ויקרא יח כה)
@190 **ושמרתם לעשות כאשר צוה ה' אלהיכם אתכם** . זו אזהרה על עשרת הדברות שצוה אותם השם מפיו ואחרי כן יזהיר בשאר המצות שאמרו הם לשמוע ממשה ולעשות ולכך אמר (להלן ו א) וזאת המצוה החקים והמשפטים אשר צוה ה' אלהיכם ללמד אתכם כי השם הודה לדבריכם וצוה אותי ללמד אתכם שאר כל התורה למען תחיון שימלא מספר ימיכם וטוב לכם בכל הטובה אשר יעד לכם בפרשת אם בחקותי וזולתה והארכתם ימים בארץ שתנחילו אותה לזרעכם לעולם
@193 **למען תירא את ה' אלהיך** . יאמר שצוה השם ללמד אתכם התורה והמצוה והחקים והמשפטים לעשותם בארץ בעבור שתירא את ה' אלהיך כי עיקר כל המצוה יראת ה' זה דעת ר"א ואיננו נכון בעיני שיהיה "למען תירא" ו"למען יאריכון ימיך" האחד טעם המצות בעבור שתירא והשני שנזכר בהם למען שיאריכון ימיך אבל יאמר שצוה השם אותי שתלמדו המצות ותעשו אותם למען שתזכה ותירא את ה' אלהיך לשמור מצותיו אתה ובנך ובן בנך כל ימי היות האדם על פני האדמה לעולם כי בעבור עשות המצות תזכה שיהיו לך בנים יראי השם ויעמדו על פני האדמה לעולם ויעמוד זרעכם ושמכם לפניו כל הימים ולמען יאריכון ימיך בארץ שהיא נחלת ה' והנה הכל לטובתך כי חפץ ה' להצדיקך ולזכות אותך
@194 **ושמרת לעשות אשר ייטב** . הנה מצוך שתשמור לעשות אשר ייטב לך ארץ זבת חלב ודבש דבק עם "לרשתה" (בפסוק א) ואם הוא רחוק או יהיה חסר בי"ת כמו הנמצא בית ה' (מלכים ב יב יא) לשון ר"א ואם כן יחסר עוד מ"אשר תרבון מאד" "בו" או "בעבורו" ואין צורך כי "למען יאריכון ימיך" נמשך לכאן וטעמו "למען אשר ייטב לך" או מלת "אשר" בעצמה תשמש כן כמו ויסירה מגבירה אשר עשתה מפלצת (מלכים א טו יג) בעבור שעשתה וכן באשר את אשתו (בראשית לט ט) בעבור שאת אשתו וכן הכתוב אשר אנכי מצוך היום אשר ייטב לך וגו' ולמען תאריך ימים על האדמה (לעיל ד מ) ושיעור הכתוב ושמעת ישראל ושמרת לעשות למען אשר ייטב לך ואשר תרבון מאד כאשר דבר ה' אלהי אבותיך לתת לך ארץ זבת חלב ודבש וגו' כלומר למען שייטב לך בתתו לך ארץ טובה ורחבה כמו שאמר למטה (פסוק יח) למען אשר ייטב לך ובאת וירשת את הארץ וכמוהו ויתן לו בית ולחם אמר לו (מלכים א יא יח)
@195 **שמע ישראל ה' אלהינו** . גם בזה מצוה שיבאר כי בדבור אנכי ה' אלהיך יהיה היחוד וכמו שאמרו (מכילתא בחדש ה) רבי נתן אומר מכאן תשובה למינים שהם אומרים שתי רשויות הן שכשעמד הקב"ה על הר סיני ואמר אנכי ה' אלהיך מי מיחה כנגדו אבל בא לבאר המצוה הזו והזכיר אותה אחר עשרת הדברות לפי שהוא שרש באמונה וכל מי שאינו מודה בה כופר בעיקר כעובד ע"ז ה' אלהינו ה' אחד ה' שהוא אלהינו ולא אלהי האומות עתיד להיות ה' אחד כמו שנאמר (זכריה יד ט) ביום ההוא יהיה ה' אחד ושמו אחד לשון רש"י ואתה צריך להתבונן בזה כי שנה הכתוב כאן לומר "ה' אלהינו" ולא אמר "אלהיך" כמו שאומר בכל מקום שמע ישראל אתה עובר היום וגו' כי ה' אלהיך (להלן ט א ג) שמע ישראל אתם קרבים היום וגו' כי ה' אלהיכם (להלן כ ג ד) וכן בכל הפרשיות שידבר עם ישראל יזכיר ה' אלהיכם או ה' אלהיך וגם בכאן אמר ואהבת את ה' אלהיך אבל הזכיר ביחוד "ה' אלהינו" כי עשה עם משה את הגדולות ואת הנוראות לעשות לו שם תפארת והנה דל"ת אחד גדולה לרמוז על מה שכתוב (ישעיהו סג יב) בוקע מים מפניהם לעשות לו שם עולם ולכך תקנו בקריאת שמע ברוך שם כבוד מלכותו לעולם ועד ואמרו משל לבת מלך שהריחה ציקי קדרה וכו' (פסחים נו) כי משה אמר בתורה ברמז וחזר ואמר ואהבת את ה' אלהיך כלשון הפרשיות במשנה תורה
@196 **בכל לבבך** . על דעת המדרש (ספרי ואתחנן ו) הלב הנזכר כאן הוא הכח המתאוה כענין תאות לבו נתת לו (תהלים כא ג) אל תחמוד יפיה בלבבך (משלי ו' כה) אם כן בכל נפשך הנפש המשכלת וכן והיתה נפש אדוני צרורה בצרור החיים (שמואל א כה כט) וכדברי רבותינו שדורשין בגמרא (ברכות נד) מכאן יהרג ואל יעבור יהיה "בכל נפשך" תוספת מפני שאמר בכל לבבך ובכל מאדך אמר גם כן בכל נפשך וטעם שתאהבנו כנפשך שתתן אותה באהבה או שנקראו היסורין או האברים חצי הנפש ובהריגה יאמר בכל נפשך ור"א אמר כי "נפשך" המתאוה כמו כנפשך שבעך (להלן כג כה) נפש שבעה תבוס נופת (משלי כז ז) אל תתנני בנפש צרי (תהלים כז יב) "ובכל לבבך" הוא הדעת והוא כנוי לרוח המשכלת כי היא המרכבה הראשונה לו וכמוהו חכם לב יקח מצות (משלי י ח) ודברו קרוב בפירוש "בכל לבבך" ממה שאמר והיו הדברים האלה וגו' על לבבך וטעם ובכל מאדך כלומר מאד מאד והטעם רב רב אהוב אותו ועל דעת רבותינו (ברכות נד) בכל ממונך ויקרא הממון "מאד" כי יכנה אותו ברבוי כמו שקורא לו "המון" טוב מעט לצדיק מהמון רשעים רבים (תהלים לז טז) והנם ככל המון ישראל (מלכים ב ז יג) ויקרא "חיל" ישאו על כתף עירים חיליהם (ישעיהו ל ו) חילך כל אוצרותיך (ירמיהו יז ג) את החיל הזה (להלן ח יז) יאמר בכל רבוי ממונך וכמוהו אשר שב אל ה' בכל לבבו ובכל נפשו ובכל מאדו (מלכים ב כג כה) מפני התנדבו בענין ביעור ע"ז ועשיית הפסח וענין האהבה בארו אותו רבותינו והמפורש שבדבריהם מה שאמרו בספרי (עקב) שמא תאמר הריני לומד תורה בשביל שאקרא חכם בשביל שאשב בישיבה בשביל שאאריך ימים בשביל שאזכה לעולם הבא ת"ל לאהבה וגו' ואשר אמר להם משה תמיד למען ייטב לך ולמען תאריך ימים (לעיל ד מ) ולמען תחיו ובאתם וירשתם את הארץ (לעיל ד א) יזהירם ביראה על דרך התוכחות לומר שאם יחטאו לא יירשו את הארץ או לא יאריכו ימים עליה או שהחסיד צריך להיות אוהב וירא כמו שאמרו (ירושלמי ברכות פ"ט ה"ה) עשה מאהבה ועשה מיראה עשה מאהבה שאין אוהב שונא ועשה מיראה שאם באת לבעוט אל תבעוט וכבר נתבאר זה בדברי החכמים
@198 **ושננתם לבניך** . גם אלה מצות מבוארות נרמזו כבר כי מאחר שצוה במצות חקת עולם לדורותיכם ביני ובין בני ישראל אות היא לעולם (שמות לא יז) זאת בריתי אשר תשמרו ביני וביניכם ובין זרעך אחריך (בראשית יז י) הנה אנחנו מצווים שידעו בנינו המצות ואיך ידעו אותם אם לא נלמדם וכן וקשרתם לאות על ידך והיו לטטפת בין עיניך כבר נאמר (שמות יג ט) ובאר בכאן "וקשרתם" שיהיו מונחים בקשירה וירמוז גם כן לקשר של תפילין שקבלו רבותינו הלכה למשה מסיני (מנחות לה) והוסיף בכאן מצות המזוזה וכתבתם על מזזות ביתך ובשעריך שלא נזכרה ואולי גם זו מבוארת נרמזה שם במצות ולזכרון בין עיניך למען תהיה תורת ה' בפיך וטעם "ובשעריך" ובמזוזות שאר שעריך כגון שערי הערים והמדינות כמו באחד שעריך (להלן טו ז)
@201 **והיה כי יביאך ה' אלהיך וגו'** . יזכיר בכאן כי ברבות הטובה יזכור ימי עניו ומרודו שהיה עבד במצרים ולא ישכח את השם שהוציאו מן העבדות ההוא לטובה הזאת אבל יזכור חסדיו תמיד ויירא אותו ויעבוד לפניו כעבד לאדוניו ועל דעת רבותינו (חולין יז) ירמוז עוד כי הטוב ההוא אשר ימצא בבתים המלאים מותר אפילו היו שם דברים הנאסרים בתורה כגון קדלי דחזירי או כרמים נטועים כלאים או ערלה ואפילו בבורות יתכן שהיה בחציבתן דבר אסור בטיח אשר בהן או הזכיר הבורות דרך מליצה להזכיר רבוי הטובה והשליט אותם בכל הנמצא בארץ במותר ובאסור והנה הותרו להן כל האיסורין זולתי אסור ע"ז כמו שיבאר עוד (להלן ז כה) לא תחמוד כסף וזהב עליהם ולקחת לך וגו' ולכך יזכיר כאן בפרשה שאחרי כן (להלן ז ה) מזבחותיהם תתצו וגו' לאבד ע"ז ומשמשיה ושאר כל הנמצא בארץ מותר והיה ההיתר הזה עד שאכלו שלל אויביהם ויש אומרים בשבע שכבשו וכן נראה בגמרא בפרק ראשון ממסכת חולין (שם) והרב כתב בהלכות מלכים ומלחמותיהם (רמב"ם פ"ח ה"א) חלוצי צבא משיכנסו בגבול הגוים וישבו מהם מותר להם לאכול נבלות וטרפות ובשר חזיר וכיוצא בו אם רעב ולא מצא מה יאכל אלא מאכלים אלו האסורים וכן שותה יין נסך ומפי השמועה למדו ובתים מלאים כל טוב ערפי חזירים וכיוצא בהן ואין זה נכון שלא בשביל פקוח נפש או רעבון בלבד הותר בשעת מלחמה אלא לאחר שכבשו הערים הגדולות והטובות וישבו בהן התיר להם שלל אויביהם ולא בכל חלוצי צבא אלא בארץ אשר נשבע לאבותינו לתת לנו כמו שמפורש בענין וכן יין נסך שהזכיר אינו אמת שבכל איסורי ע"ז היא עצמה ומשמשיה ותקרובת שלה הכל אסור שנאמר (להלן ז כו) שקץ תשקצנו ותעב תתעבנו כי חרם הוא ואם לא נתכוון הרב אלא להתיר סתם יינן במלחמה וכי למה הוצרכנו לדבר זה איסורי תורה הותרו גזרות של דבריהם יהיו אסורות
@204 **וטעם את ה' אלהיך תירא** . כי אחר שצוה באהבה יזכיר ליראה אותו שלא יחטא ויענש ואתו תעבד לעשות כל אשר צוך כעבד שומר מצות אדוניו ויתכן שיהיה זה רמז לעבודת הקרבנות לשמו וכך אמרו בספרי (ראה ס) בפסוק אחרי ה' אלהיכם תלכו ואותו תיראו ואת מצותיו תשמרו ובקולו תשמעו ואותו תעבודו (להלן יג ה) עבודו בתורתו עבודו במקדשו ירצה לפרש כי אחרי שהזהיר בשמירת כל המצות כלן ולשמוע בקולו יהיה "ואותו תעבודו" לעבדו במקדש בקרבנות ובשיר ובהשתחואות שם כי זה יקרא עבודה כמו שאמר (במדבר יח ז) עבודת מתנה אתן את כהונתכם ואמר (שם פסוק כג) ועבד הלוי ודרשו עוד "עבודו בתורתו" ללמוד התורה ולהגות בה וגם היא עבודה לפניו ולפי זה "ואותו תעבוד" ג"כ בקרבנות ור"א אמר את ה' אלהיך תירא שלא תעבור על מצות לא תעשה ואותו תעבוד במצות עשה ואיננו נכון מפני שאמר בכתוב האחר ואותו תיראו ואת מצותיו תשמורו ואותו תעבודו
@204 "ובשמו תשבע" - אינו מצוה שישבע אבל הוא אזהרה כי בשמו בלבד תשבע לא בשם אל אחר על כן כתוב אחריו לא תלכון אחרי אלהים אחרים שלא תלכו אחריהם בדבר מכל אלו שלא תיראו מהם ולא תעבדו אותם ולא תשבעו בשמם אבל בגמרא של מסכת תמורה דרשו אותו בשבועת אמת דשריא אמרו בשמו תשבע דאמר רחמנא למה לי אם אינו ענין לשבועת הדיינין דנפקא ליה משבועת ה' תהיה בין שניהם תנהו ענין לשבועות דעלמא דשריין ואם אינו ענין לשבועה דמצוה דנפקא ליה מן ובו תדבקון (להלן יג ה) תנהו ענין לשבועה דחול וראיתי עוד בתנחומא אמר להן הקב"ה לישראל לא תהיו סבורין שהותר לכם להשבע בשמי אפילו באמת אין אתם רשאין להשבע בשמי אלא אם יהיו בך כל המדות הללו את ה' אלהיך תירא שתהיה כאותן שנקראו יראי אלהים אברהם יוסף איוב ואותו תעבוד שתהא מפנה עצמך לתורה ולמצות ולא יהיה לך עבודה אחרת לכך נאמר ואותו תעבוד ובו תדבק וכי אפשר לו לאדם להדבק בשכינה והלא כבר נאמר (לעיל ד כד) כי ה' אלהיך אש אוכלה הוא אלא לומר לך כל המשיא בתו לתלמיד שקורא ושונה והעושה לו פרקמטיא והמהנהו מנכסיו זהו שאמר ובו תדבק אם יש לך כל מדות אלו אתה רשאי להשבע ואם לאו אי אתה רשאי להשבע עד כאן לשון אגדה זו והנה פירוש הכתוב לדעתם "ובשמו תשבע" רשות שיתיר לנו להשבע בשמו על דרך הכבוד כאלו אמר את ה' אלהיך תירא אבל בשמו תשבע ולא תירא מזה ומפני ששם ההיתר הזה אחר היראה והעבודה דרשו שאין היתר לשבועה אלא לאחר כל המדות הללו או יאמר את ה' אלהיך תירא ותהיה יראתו גדולה על פניך עד שתהיה שמו לך לשבועה כי גם ברצותך לקיים כל דבר תשבע בשמו להרע ולא תמיר ויהיה פירוש "ואותו תעבוד" לדעתם שתהיה לו בכל עת כעבד הקנוי המשרת לפני אדוניו תמיד שעושה מלאכת רבו עיקר וצרכי עצמו עראי עד שיבא מזה מה שאמרו (אבות ב יב) וכל מעשיך יהיו לשם שמים שאפילו צרכי גופו לשם עבודת האל יהיו יאכל ויישן ויעשה צרכיו כדי קיום הגוף לעבוד ה' כענין שאמרו (בראשית רבה ט ו) והנה טוב מאד זו שינה וכי שינה טובה היא מתוך שהוא ישן קמעא הוא עומד ועוסק בתורה ויתכוין בכל צרכי הגוף למקרא שכתוב (תהלים קמו ב) אהללה ה' בחיי אזמרה לאלהי וגו' וזה פירוש נכון
@207 **לא תנסו את ה' אלהיכם** . פירוש כאשר נסיתם במסה שלא תאמר אם יש ה' בקרבנו לעשות לנו נסים או שנצליח בהיותנו עובדים לפניו ונשבע לחם ונהיה טובים נשמור תורתו כי הכוונה שם כך היתה שאם יראו שהשם יתן להם מים בנס מאתו ילכו אחריו במדבר ואם לא יעזבוהו ונחשב להם לעון גדול כי אחרי שנתאמת אצלם באותות ובמופתים כי משה נביא השם ודבר ה' בפיהו אמת אין ראוי לעשות עוד שום דבר לנסיון והעושה כן איננו מנסה הנביא רק השם יתברך הוא מנסה לדעת היד ה' תקצר ולכך אסר לדורות לנסות התורה או הנביאים כי אין ראוי לעבוד השם על דרך הסתפק או שאלת מופת ונסיון כי אין רצון השם לעשות נסים לכל אדם ובכל עת ואין ראוי לעבדו על מנת לקבל פרס אלא אולי ימצא בעבודתו ולכתו בדרכי התורה צער ואסון וראוי שיקבל הכל במשפט צדק ולא כאשר אמרו אוילי עמנו (מלאכי ג יד) וכי הלכנו קדורנית מפני ה' ולכך אמר הכתוב בכאן שמור תשמרו מצותיו ועדותיו שהם הנסים שעשה לכם מכבר להיות לכם לעדות כגון הפסח והמצה והסוכה ותשמרו חקיו אע"פ שלא תדעו טעמם כי באמת ייטב לכם בסוף אין צורך לנסיון בתורה ובמצות אחרי שכבר נתאמת אצלכם שהוא מאתו יתברך וכן בכל דבר נביא המנוסה והמוחזק בנביא אמת באותות ובמופתים כדין התורה לא תנסו את דבריו בכל גמול ובכל עונש שיאמר לכם ולא תסתפקו ביכלתו יתעלה אבל האמינו בתורתו ותאמינו בנביאיו והצליחו והנה הבטיח כי סוף הכבוד לבוא בירושת הארץ ונצוח האויבים כי היא הטובה הגדולה והצריכה לאותו הדור ואחרי כן אמר כי גם לדורות הבאים אין צורך לנסיון בעשיית המצות אלא שישאלו מאבותיהם וזקניהם ויגידו להם אמתת התורה והמצות כאשר יפרש (פסוק כ) כי ישאלך בנך וגמר הפרשה
@209 **ועשית הישר והטוב בעיני ה'** . על דרך הפשט יאמר תשמרו מצות השם ועדותיו וחקותיו ותכוין בעשייתן לעשות הטוב והישר בעיניו בלבד ו למען ייטב לך הבטחה יאמר כי בעשותך הטוב בעיניו ייטב לך כי השם מטיב לטובים ולישרים בלבותם ולרבותינו בזה מדרש יפה אמרו זו פשרה ולפנים משורת הדין והכוונה בזה כי מתחלה אמר שתשמור חקותיו ועדותיו אשר צוך ועתה יאמר גם באשר לא צוך תן דעתך לעשות הטוב והישר בעיניו כי הוא אוהב הטוב והישר וזה ענין גדול לפי שאי אפשר להזכיר בתורה כל הנהגות האדם עם שכניו ורעיו וכל משאו ומתנו ותקוני הישוב והמדינות כלם אבל אחרי שהזכיר מהם הרבה כגון לא תלך רכיל (ויקרא יט טז) לא תקום ולא תטור (שם פסוק יח) ולא תעמוד על דם רעך (שם פסוק טז) לא תקלל חרש (שם פסוק יד) מפני שיבה תקום (שם פסוק לב) וכיוצא בהן חזר לומר בדרך כלל שיעשה הטוב והישר בכל דבר עד שיכנס בזה הפשרה ולפנים משורת הדין וכגון מה שהזכירו בדינא דבר מצרא (ב"מ קח) ואפילו מה שאמרו (יומא פו) פרקו נאה ודבורו בנחת עם הבריות עד שיקרא בכל ענין תם וישר
@211 **וטעם כי ישאלך בנך מחר לאמר מה העדות** . שישאל תחלה על מה יעידו אלה המצות הנקראים "עדות" בעבור שהם זכר לנפלאותיו ועדות בהם כגון המצה והסוכה והפסח והשבת והתפילין והמזוזה ומה החקים כי נעלם טעמם בתורה והמשפטים ישאל מה המשפטים שנעשה במצות האלה שנסקול העושה מלאכה בשבת ונשרוף הבא על אשה ואמה ונכה את הארבעים לזורע כלאים כי משפטי ישוב המדינות בדיני השור והבור והשומרים ושאר הדינין שבתורה צדיקים וטובים הן כל רואיהם יכירון וצוה בתשובת השאלה הזאת שנגיד לשואל כל ענין יציאת מצרים והכוונה בזה הוא הטעם במה שאמר בעשרת הדברות (לעיל ה ו) אשר הוצאתיך מארץ מצרים כי יתכוון שנודיע לבן השואל כי ה' הוא הבורא והחפץ והיכול כאשר נתבאר לנו ביציאת מצרים וזה טעם "לעינינו" כי אנחנו היודעים ועדים מן האותות והמופתים שראינו שם כי השם אלהינו הוא האלהים בשמים ובארץ ואין עוד מלבדו כי כל זה יודע ביציאת מצרים כאשר פירשתי בדבור הראשון (שמות כ ב) והנה ראוי לנו לתת כבוד לשמו כי הוא בוראנו ואשר הגדיל חסדו עמנו ויצונו לעשות את החקים האלה הנזכרים בעדות חקים ומשפטים ליראה אותו בעשותנו העדות זכר לנפלאותיו לטוב לנו בעשיית החקים כי טובים הם אין בהם חק שתהיה בו רעה כלל אע"פ שלא נתברר טעמם לכל
@222 **בך בחר ה' אלהיך להיות לו לעם סגלה** . שאין לך קצין שוטר ומושל בכל מלאכי מעלה אבל אתה סגולת ה' תחת ידו ולכך לא תטעה לעבוד ע"ז מאלהי העמים וכבר הזכרתי זה פעמים רבות וזה טעם לא מרבבם מכל העמים כי היה ראוי שיהיו הרבים למלך כענין שכתוב (משלי יד כח) ברב עם הדרת מלך ויפקיד שרי צבאות בראש הנשארים ואתם המעט ואע"פ כן חשק בכם ויבחר בכם וטעם חשק שנקשר עמכם בקשר אמיץ שלא יפרד מכם לעולם מלשון וחשוקיהם כסף (שמות כז י) ויבחר בכם מכל העמים שתהיו אתם סגולה ונחלה לו כי הבחירה בכל מקום ברירה מן האחרים ואמר הטעם כי מאהבת ה' אתכם בחר בכם שראה אתכם ראויים להתאהב לפניו ונבחרים לאהבה יותר מכל העמים ולא הזכיר בזה טעם מן הבחירה כי הנבחר לאוהב היודע לסבול את אוהבו בכל הבא עליו ממנו וישראל ראויים לכך מכל עם כמו שאמרו (ביצה כה) שלשה עזים הם ישראל באומות כי יעמדו לו בנסיונות או יהודאי או צלוב (שמו"ר מב ט) וטעם בכם בעבור אבותיכם שהגיע ענינם עד שנשבע להם כדי שלא יגרום החטא ותבטל הבטחתם ועל כן הוציא אתכם מארץ מצרים ביד חזקה ויפדך רמז שהכה אותם תחתיך כענין שנאמר (ישעיהו מג ג) נתתי כפרך מצרים כוש וסבא תחתיך
@225 **וידעת** . מיציאת מצרים כי ה' אלהיך הוא האלהים שברא שמים וארץ כאשר פירשתי (לעיל ו כ) ועוד תדע מזה שהוא האל הנאמן שלא ישוב דברו ריקם והוא שומר הברית והחסד לאוהביו ולשומרי מצותיו יראי שמו לאלף דור בזרעם כאשר שמר לך ברית אבותיך ותדע כי הוא משלם לשונאיו רשעם אל פני כל אחד מהם להאבידו כאשר האביד את המצרים ולא אחר להם והמדה הזאת אשר הזכיר אמת לעולם אע"פ שיש רשע מאריך ברעתו לא יהיה לו כן רק מפני המדה הזאת הנזכרת שהוא שומר החסד והנה עשה שום טובה שצריך לשלם לו אם כן אין במדותיו של הקב"ה אלא שתי מדות הללו משלם טובה תחת טובה ומשלם רעה תחת רעה ויתכן כי שונאיו המוחלטים מכחישים באלהותו (ו) אין להם זכות כלל וכמו שאמרו (קהלת רבה ז לב) אמר רבי יאשיה מפני שלשה דברים הקב"ה מאריך אפים לרשעים בעולם הזה שמא יעשו תשובה או עשו מצות שהקב"ה ישלם שכרן בעולם הזה או שמא יצאו מהן צדיקים שכך מצינו שהאריך אפים לאחז ויצא ממנו חזקיהו וגם לאמון ויצא ממנו יאשיהו וגם לשמעי ויצא ממנו מרדכי וכל אלו אינם בכלל שונאיוויש במלת "אל פניו" סוד ברשע וטוב לו והחזיר ושמרת את המצוה וגו' לומר לכן תשמור את המצוה ואת החקים ואת המשפטים שלא תהיה משונאיו האובדים אבל תהיה מאוהביו ושומרי מצותיו הנזכרים לטובה ולחיים
@228 **עקב** . כמו בעבור וכן עקב אשר שמע אברהם בקולי (בראשית כו ה) וכתב רש"י אם המצות הקלות שאדם דש בעקביו תשמעון ישמור לך השם הבטחתו והזכיר הכתוב המשפטים אולי יזהיר במשפטים הקלים כדיני ממונות שלא יבזו אותם והמפרשים אמרו כי טעם "עקב" שכר באחרית וכן בשמרם עקב רב (תהלים יט יב) יאמר והיה אחרית תשמעון המשפטים ותשמרו אותם שישמר השם לך את הברית והחסד ואהבך ונכון הוא כי יקראו בלשון הקדש תחלת כל דבר בלשון "ראש" כענין ראש דברך אמת (שם קיט קס) וכן גדול הדור ראש העם (במדבר כה ד) והמשובח ראש בשמים (שיר השירים ד יד) וכן יקראו אחרית כל דבר "עקב" כי הלשון יתפוס דמיונו באדם והראש תחלה והעקב בו אחרית וסוף וכן יאמר הכתוב (להלן כח יג מד) לראש ולזנב לדמיון גוף בהמה ואונקלוס תרגם חלף כמו חלף עבודתכם (במדבר יח לא) עשאו לשון סבוב נגזר מן והיה העקוב למישור (ישעיהו מ ד) הדרך המעוקל ההולך סביב סביב וכן עקובה מדם (הושע ו ח) מסובבת ומוקפת יאמר והיה סבת שמעכם המשפטים ועשותכם אותם שישמור השם לכם בריתו ויפה פירש ודומה לזה בגלל הדבר הזה (להלן טו י) בסבתו מלשון וגללו את האבן (בראשית כט ג) וכן על דעתי כל לשון עקיבה גלגול וסבוב עקוב הלב (ירמיהו יז ט) ויעקבני זה פעמים (בראשית כז לו) ויהוא עשה בעקבה (מלכים ב י יט) ענין גלגולין וסבות ולכן יקראו יעקב "ישורון" כי היפך העקוב מישור וכן אחורי הרגל שנקרא עקב וידו אוחזת בעקב עשו (בראשית כה כו) יקראנו כן בעבור היותו מעוגל כאשר יקרא הלשון אמצע היד והרגל "כפות" בעבור היותם כמו כפות הזהב ומורגל הוא בלשון כמו שאמרו בספרי (ברכה ב) מימינו אש דת למו (להלן לג ב) כשהיה יוצא הדבור מפי הקב"ה היה יוצא דרך ימינו של קדש לשמאלן של ישראל ועוקב את מחנה ישראל שנים עשר מיל על שנים עשר מיל כלומר מקיף וכן לשונם (ב"ק קיג) באים עליו בעקיפין בסבות וגלגולין כמו עקיבין ששתי האותיות האלה שוות להן כאשר פרשתי כבר (ויקרא יט כ) והזכיר את המשפטים האלה להזהיר מאד במשפטים כי לא יהיה עם רב כלו נזהר במצות כלן שלא יחטאו בהן כלל רק במשפטים יעמידו התורה כמו שנאמר בהן (להלן כא כא) וכל ישראל ישמעו ויראו ועוד כי רבים ירחמו מלסקול האיש ולשרוף אותו אחרי שנעשת העבירה כמו שנאמר (להלן יט יג) לא תחוס עינך ועוד שייראו מן התקיפים ומן המטעים כמו שאמר (לעיל א יז) לא תגורו מפני איש כי המשפט לאלהים הוא ואמר בנביא השקר (להלן יח כב) לא תגור ממנו והזכיר כל אלה במסית (להלן יג ט) לא תאבה לו ולא תשמע אליו ולא תחוס עינך עליו ולא תחמול ולא תכסה עליו ויזהיר לא תשמע אליו מפני הטעאתו ולא תחוס עינך מפני הרחמנות שירחמו רכי הלבב על הנידונים ולא תכסה שלא תשתוק בעבור תקפו ויראת בני משפחתו
@229 **וטעם ואהבך** . כאשר תעשה המשפטים לאהבת השם גם הוא יאהב אותך ויתכן שיהיה "ואהבך" יוצא שמחבב אותך למשפחות הנשפטים ולא ישנאוך עליהם וברכך שלא תאונה אליך רעה בעבור המשפט והרבך שלא תמעט באבדן העוברים אפילו יהיו רבים אובדים כאנשי עיר הנדחת
@231 **והסיר ה' ממך כל חולי** . הנהוג לבא בעולם והזכיר כל מדוי מצרים הרעים להבטיח ונתנם בכל שונאיך או שירמוז כי בעשותם המשפטים ינצלו מהם ואם לא יעשו אותם יבואו עליהם כאשר באו על המצרים כאמור בתוכחות (להלן כח ס) והשיב בך את כל מדוי מצרים וגו' וכבר פירשתי זה בסדר ויהי בשלח (שמות טו כו) והזכיר תחלה במשפטים לכלות ולהכרית עובדי ע"ז ולכך אמר ואכלת את כל העמים שתכריתם כענין שנאמר כי לחמנו הם (במדבר יד ט) כי אכל את יעקב (תהלים עט ז) ואכלוהו ויכלוהו (ירמיהו י כה) וכן רבים ואמר לא תחוס עינך עליהם כאשר הזכרתי (בפסוק יב) כי ברחמנות השופטים (ס"א הטפשים) יאבד כל משפט
@238 **לא תוכל כלתם מהר** . יבטיח שהשם יכריתם כלם וישלח בהם את הצרעה להאביד הנשארים והנסתרים והנה כלם יאבדו אבל אמר שלא יכלה אותם במלחמה ביום אחד ולא שיגרשם מן הארץ בשנה אחת פן תהיה הארץ שממה ורבה עליך חית השדה והוסיף עוד להבטיח שלא יהיו אלה הנשארים רובם אבל השם יהומם מהומה גדולה ורובם יאבדו ביד ישראל וכן אמר (להלן ט ג) הוא ישמידם והוא יכניעם לפניך והורשתם והאבדתם מהר שיאבדו רובם במהרה לא שיכלו עד אשר תפרה ונחלת את הארץ ואמר ונתן מלכיהם בידך והאבדת את שמם עד שלא יהיה להם שם על פני חוץ וכל הנצב בפניהם ישמידו וזה כענין שבא ביהושע (יא כ) כי מאת השם היתה לחזק את לבם לקראת המלחמה את ישראל למען החרימם ולא נשאר להם מלך בארץ כי כל מלכיהם נפלו וכתב רש"י פן תרבה עליך חית השדה והלא אם עושים רצונו אינם מתיראים מן החיה שנאמר (איוב ה כג) וחית השדה השלמה לך אלא גלוי היה לפניו שעתידין לחטוא ודברי רבותינו הם (ספרי) ואף על פי שהפרשה הזאת להבטחה נאמרה כבר הזכרתי (לעיל ד כה) כי משה רבינו במשנה התורה יבטיח ויזהיר וירמוז כי לא תגיע זכותם להכריתם כלם כאחד ושישבית חיה רעה מן הארץ כמובטח להם בפרשת אם בחקתי (ויקרא כו ו) אבל יהיה כאשר אמר שיאבידו את רובם ומלכיהם בתחלה ואחרי כן יאבדו הנשארים
@241 **לא תחמד כסף וזהב עליהם** . יחסר "אשר" לא תחמוד כסף וזהב אשר עליהם והוא נויי ע"ז צוה תחלה לשרוף ע"ז עצמה שהיא "פסילי אלהיהם" ואסר גם כן הנויין שעליהן והזהיר עוד ולא תביא תועבה אל ביתך והיית חרם כמהו לאסור בהנאה כל עניני ע"ז היא ומשמשיה ותקרובת שלה והנויין
@243 **וטעם כל המצוה** . לומר אע"פ שהזהרתי אתכם במשפטים גם כל המצות תשמרון לעשות כי בעשיית כלן תחיון ורביתם בפרי בטן ופרי בהמה ופרי האדמה ככל הנזכר למעלה
@244 **וזכרת את כל הדרך וגו'** . יאמר כי תוכל לדעת שיש בעשיית המצות טובה שלמה ולא יהיה צדיק נעזב ומבקש לחם כי השם מפרנס אותך במדבר במעשה נס גדול בעבור לכתך אחר מצותיו וכבר פירשתיו בפרשת המן (שמות טז ד) טעם למען ענותך לנסותך לדעת את אשר בלבבך התשמר מצותיו אם לא כי היה נסיון גדול להם שלא ידעו עצה לנפשם ויכנסו במדבר הגדול לא מקום לחם ואין בידם כלום מן המן אבל ירד דבר יום ביומו וחם השמש ונמס וירעבו אליו מאד וכל זה עשו לשמור מצות השם ללכת כאשר יצוה והשם היה יכול להוליכם בדרך הערים אשר סביבותיהם אבל הביאם בנסיון הזה כי ממנו יודע שישמרו מצותיו לעולם
@245 **וטעם אשר לא ידעת ולא ידעון אבתיך** . כי לא ידעת במן שתוכלו לחיות בו ימים רבים ולא הגיע אליכם כן בקבלה מאבותיכם או יאמר כי עשה עמכם החסד הגדול הזה אשר אבותיכם הקדושים לא הגיעו אליו כי אף על פי שהלכו אחריו ככל אשר צוה אותם לך לך מארצך וממולדתך ומבית אביך (בראשית יב א) לא הגיע מעלתם שיפרנסם בדגן שמים כאשר עשה לך וכן אמרו במדרש במדבר סיני רבה (א ב) בזכות משה הייתם אוכלים המן מה שלא ראו אבותיך הקדושים שנאמר ולא ידעון אבותיך ופירש כי עשה זה להודיעם כי הוא המחיה האדם בכל אשר יגזור א"כ שמור מצותיו וחיה ויתכן לפרש כי ויענך וירעיבך ויאכילך את המן ענינים שונים יאמר כי ענה אותך בלכתך במדבר ארבעים שנה כענין ענה בדרך כחי (תהלים קב כד) וירעיבך מתחלה כמו שאמרו (שמות טז ג) להמית את הקהל הזה ברעב ואחרי כן האכילך את המן להודיעך כי על כל מוצא פי ה' יחיה האדם וכן המאכילך מן במדבר אשר לא ידעון אבותיך (פסוק טז) וספר הנס שעשה להם ו"למען ענותך" שב אל המוליכך במדבר הגדול והנורא וגו' וצמאון וגו' (פסוק טו) אבל מה שאמר בפרשת המן (שמות טז ד) למען אנסנו הילך בתורתי אם לא שאתן לכם צרכיהם ושאלתם אביא להם ואראה אם ישמעו אלי ברבות הטובה וזה עולה בדרך הפשט אבל הענין הראשון הוא אמת ונכון
@246 **שמלתך לא בלתה מעליך** . ענני כבוד היו שפין בכסותן ומגהצים אותם כמו כלים המגוהצים וכן קטניהם כשהיו גדלין גדל לבושן עמהם לשון רש"י ודברי אגדה (מדרש תהלים כג) אבל ר"א כתב ואחרים אמרו כי הוציאו מלבושים רבים ויתכן שאין בתולדת המן להוליד זיעה וכן אמר ורגלך לא בצקה שנתן להם כח או הוליכם לאט ואין דבריו נכונים כי משה יזכיר להם זה לאמר כי בעשיית המצוה יהיה להם מזון וכסות ויחליפו כח כאשר חיו במן ארבעים שנה והיו להם השמלות וארח ברגלם לא יבא והכל ממעשה הנס כי על כל מוצא פי ה' יחיה האדם ויתפרנס ואם תכסה את הקורה בשמלה חדשה בארבעים שנה תבלה אע"פ שאין בה זיעה אף כי אנוש רמה
@247 **כי כאשר ייסר איש את בנו** . שיתן עליו לטובתו עול מוסר כענין שנאמר (משלי יט יח) יסר בנך כי יש תקוה ואל המיתו אל תשא נפשך כן ה' אלהיך מיסרך מתחלה בענוי המדבר ונסיון המן שתערב לנפשך טובת הארץ ופירותיה על כן אמר אחריו (פסוק ז) כי ה' אלהיך מביאך אל ארץ טובה
@249 **וטעם ארץ נחלי מים** . שהיא כגן רוה לא שישקוה מים ברגל כארץ מצרים כאשר יאמר עוד (להלן יא יא) כי למטר השמים תשתה מים ופירש כי עינות ותהומות יוצאים בבקעה וגם בהר ומשם יזחלו בה נחלים ושיעור הכתוב עינות ועינות תהומות כמו בעזוז עינות תהום (משלי ח כח) מעינות תהום רבה (בראשית ז יא) והענין כי יש מן המעינות שנוזלים מתמצית לחות ההרים מן הגשמים שנבלעים בתוכם או מן האדים העולים להם והם שקרא עיינות כמו אל כל מעיני מים (מלכים א יח ה) למעינו מים (תהלים קיד ח) ויש מהם שיוצאים ממקור התהום והם שקראם "תהומות" כלומר מעינות תהום ואמר כי משניהם בבקעה וגם בהר
@251 **וטעם אשר אבניה ברזל** . כי במקום אשר תחשוב ששם אבנים שם תמצא ברזל כי מעפרה יוקח ובשרם כי בארץ ישראל מחצב נחשת וברזל שהם צורך גדול ליושבי הארץ ולא תחסר כל בה אבל מוצא הכסף והזהב איננו חסרון בארץ ובתרגום ירושלמי ראיתי דאבנהא ברירן היך פרזלא וכו' ר"ל שהכתוב משבח הארץ שימצאו בה מחצבים מן אבנים גדולות אבנים יקרות אבני גזית לבנות מהם בתים וחומות ומגדלים לא כארץ מצרים וארצות רבות שהם שוכני בתי חומר ונעשים ליושביהם קבריהם
@252 **ואמר ואכלת ושבעת וברכת** . כי תזכור עבודת מצרים וענוי המדבר וכאשר תאכל ותשבע בארץ הטובה תברך עליה את השם ורבותינו (ברכות מח) קבלו שזו מצות עשה וטעמו ותברך את ה' אלהיך וכן ועשית מעקה לגגך (להלן כב ח) וכן ועשית פסח לה' אלהיך (להלן טז א) ולקחת מראשית כל פרי האדמה (להלן כו ב) ורבים כן וטעם על הארץ הטובה כמו ועל הארץ הטובה יצוה שתברכהו בכל עת שתשבע על השובע ועל הארץ שנתן לך שינחילנה לך לעולמים ותשבע מטובה והנה חיוב המצוה הזאת בכל מקום
@260 **וזכרת את ה' אלהיך כי הוא הנותן לך כח לעשות חיל** . ידוע כי ישראל גבורים ואנשי חיל למלחמה כי נמשלו לאריות ולזאב יטרף ומלכי כנען במלחמה נצחו אותם על כן אמר אם תחשוב כחי ועצם ידי עשה לי את החיל הזה תזכור השם שהוציא אותך ממצרים ולא היה לך שם כח ועצם יד כלל ותזכור עוד כי במדבר אשר אין לאל ידך לחיות שם עשה לך כל צרכך אם כן גם החיל הזה אשר עשית בכחך השם הוא שנתן לך הכח כאשר עשית אותו ואם תשכח את השם יכלה כחך ושארך ותאבד כאשר אבדו הם כי כל עוזבי ה' יכלו וחזר להביא עוד ראיה אחרת שלא תחשוב כחי ועצם ידי וגו' ואמר (ט א) שמע ישראל דבר אמת מפי כי הגוים האלה הם גדולים ועצומים ממך ואיך תנצחם במלחמה ועוד יש להם ערים גדולות ובצורות לרום השמים ואיך תכבוש אותם ועוד ששם עם גדול ורם בני ענקים שאתה ידעת מן המרגלים שראו אותם ואתה שמעת מימים ראשונים שלא יתיצב אדם לפניהם וכשיתברר לך כל זה יש לך לדעת ולהאמין מן היום הזה כי לא תוכל לעבור עליהם כלל עד שתדע בלבבך כי ה' העובר לפניך הוא אש אוכלה והוא ישמידם ויכניעם לא כח ועצם יד שנתן לך אבל יד ה' עשתה זאת בתקיפין שבהם וזה רמז למה שאמר (יהושע י יא) וה' השליך עליהם אבנים גדולות מן השמים וכן אמר שם (פסוק יד) ולא היה כיום ההוא לפניו ואחריו וגו' כי ה' נלחם לישראל והערים הבצורות שהזכיר כאן רמז לחומת יריחו שנפלה לפני הארון וזהו שאמר דוד (תהלים מד ד) כי לא בחרבם ירשו ארץ וזרועם לא הושיעה למו כי ימינך וזרועך ואור פניך כי רציתם ימין השם וזרועו בתקיפים ואור פניו שרצם בהרוגי המלחמה שנתן להם כח עליהם וזהו שאמר הכתוב עוד (עמוס ב ט) ואנכי השמדתי את האמורי מפניהם אשר כגובה ארזים גבהו וחסון הוא כאלונים ואשמיד פריו ממעל ושרשיו מתחת ייחד האמורי שהיה עצום בהם והשם הוא המשמיד אותו
@265 **וטעם הוא ישמידם והוא יכניעם** . כמו הוא יכניעם והוא ישמידם "יכניעם" ענין שפלות מן הראית כי נכנע אחאב מלפני (מלכים א כא כט) או אז יכנע לבבם הערל (ויקרא כו מא) וכן כלם והטעם כי היו העמים ההם יראים מאד מישראל ובלב רגז וברוח שפלה ורפיון ידים היו יוצאים אליהם למלחמה כמו שאמר (יהושע ה א) ויהי כשמוע כל מלכי האמרי וגו' וכל מלכי הכנעני וגו' וימס לבבם ולא היה בם עוד רוח מפני בני ישראל ויתכן כי "הוא ישמידם" ירמוז אל גוים גדולים ועצומים ו"יכניעם" אל בני ענקים כי עם כל תקפם וגבהם נכנע לבם יותר משאר העם ולא יצאו למלחמה כלל אבל היו נחבאים בהרים ובערי הבצורות כמו שאמר (שם יא כא) ויבא יהושע בעת ההיא ויכרת את הענקים מן ההר מן חברון מן דביר מן ענב ומכל הר יהודה ומכל הר ישראל עם עריהם החרימם יהושע כלומר בעריהם וכן וילך יהודה אל הכנעני היושב בחברון ויכו את ששי ואת אחימן ואת תלמי (שופטים א י)
@266 **אל תאמר בלבבך** . אחרי שהזהיר שלא תחשוב כחי ועוצם ידי עשה לי רק שתדע כי הנצוחים במלחמה השם נתן להם הכח ההוא והתקיפים שבהם והערים הבצורות אשר תלכדו השם בכבודו עשה לכם כן בנס מפורסם מאתו חזר והזכיר לא תחשוב כי עשה ה' עמך כל זה בצדקתך כי לא עשה לכם כן רק ברשעת הגוים האלה והנה זה טעם באבדן הגוים ההם ולא נתן להם טעם ברשת ישראל את הארץ על כן חזר ובאר לא בצדקתך שתהיה צדיק במעשה ולא אפילו בלב ישר שהיה לך רק ברשעת הגוים אבדו הם ובעבור שבועת אבותיך ירשת אותה הארץ כי אין החטא שלך יכול לבטל המתנה שנתן לאבותיך כי בשבועה נתנה להם ורש"י כתב אל תאמר בלבבך צדקתי ורשעת הגוים גרמה לי לא בצדקתך ואיננו נכון ויש על השואל לשאול שהרי אמר (לעיל ז ח) כי מאהבת ה' אתכם והנה הם אהובים למעלה והשם לא יאהב רק את הטובים כי רשע ואוהב חמס שנאה נפשו אם כן גם בצדקתם ירשו ארץ והתשובה כי שם ידבר עם ישראל בכללם וכאן יוכיח הדור ההוא שהיו ממרים את ה' מיום היותם במדבר וטעם ולמען הקים את הדבר שאמר ועבדום וענו אותם ארבע מאות שנה ודור רביעי ישובו הנה (בראשית טו טז)
@270 **ובחרב הקצפתם את ה'** . קודם שיפתח להם בביאור התורה כלל הוכיח אותם בעונות אשר גרמו להם רעה ולא נמחלו והזכיר להם ענין המרגלים ומי מריבה ואחר כן ביאר עשרת הדברות ופרשת יחוד השם והזהירם בענין ע"ז אזהרות רבות והזהיר במצות בכללם ויאמר שהן כולן טובות ובעבורן תבא להן כל הטובה ועתה בא להתחיל בפרטי המצות וקודם שיזכיר אחת מהן בפרט יחזור להוכיח אותם ולפקוד עליהם את כל עונותיהם שעשו מעת שקבלו התורה והלאה כי התלונות שעשו קודם מתן תורה שהמרו על ים בים סוף וילונו במרה ובאלוש לא יזכירם להם כי מעת שקבלו התורה היו יותר חייבים לשמוע בקול השם אשר כרת עמם ברית ולפיכך פתח כאן ובחורב הקצפתם והזכיר להם מעשה העגל וכבר פירשתיו (שמות לב א)
@277 **ואפן וארד מן ההר** . כבר פירשתי במקומו (שם שם יא) כי קודם שירד מן ההר התפלל עליהם ובתפלתו נאמר (שם שם יד) וינחם ה' על הרעה אבל לא הזכיר זה עתה מפני שהוא רוצה להסדיר להם עתה הטורח הגדול והעמל שטרח עליהם כי הביאו אותו לשבור הלוחות ולהתנפל עליהם ארבעים יום וארבעים לילה ולהתפלל גם על אהרן כי התאנף השם עליו מאד ואחרי כן (פסוקים כה-כט) יזכיר התפלה הראשונה שחלה את פני ה' אלהיו טרם רדתו שלא ישמידם
@279 **וטעם ואתפש בשני הלוחות** . גם זה מן התוכחות יאמר היה עונכם גדול מנשוא עד כי בראותי אתכם משחקים לפני העגל לא יכלתי להתאפק ושברתי הלוחות והוצרך להזכיר זה בעבור שירצה להודיעם ענין הלוחות השניות כאשר יפרש ויתכן שירמוז עוד לטובה שעשה עמהם כי סכן בנפשו לשבור לוחות האלהים לטובתם כאשר אמרו רבותינו (שמו"ר מג א) מוטב תדון בפנויה ולא באשת איש
@281 **כי יגרתי מפני האף** . יאמר כי מפני האף והחמה אשר קצף השם מתחלה עליכם להשמיד אתכם יגורתי גם עתה כי עדין יש עליכם להשמיד אתכם מן הקצף הגדול ההוא אף על פי שכבר נחם השם על הרעה אשר דבר לעשות לעמו על כן חזרתי והתנפלתי עליכם ארבעים יום וארבעים לילה עד ששמע אלי גם בפעם ההיא כאשר שמע בפעם הראשונה קודם שירדתי וגם בעד אהרן התפללתי בפעם הזאת שחזרתי שם כי עד שיבער את העגל לא השגיח רק להשיב חמתו מהשחית את העם כרגע
@283 **ואמר ואשלך את עפרו אל הנחל הירד מן ההר** . ולא הזכיר כי השקהו אותם דרך כבודם שלא רצה לאמר להם שעשה בהם מעשה הסוטות
@284 **ובתבערה ובמסה** . בעבור כי בתבערה היו העם כמתאוננים מנסים השם בתואנות הזכיר להם כי הייתם מקציפים את השם בנסיון אשר נסיתם בתבערה כאשר עשיתם כבר פעם אחרת במסה ולא לקחתם מוסר ויפה פירש והנה החטא לנסות את השם הוא חטא גדול ואשמה רבה כאשר הזהיר ממנו (לעיל ו טז) לא תנסו את ה' אלהיכם כאשר נסיתם במסה על כן החזיר אותו להם בכאן וכך הזכיר פעם אחרת חטא המרגלים בקצרה בעבור העון הגדול כי בו ישלים ממרים הייתם עם ה' ואמר מיום דעתי אתכם לרמוז על תלונותיהם קודם מתן תורה
@287 **ואתנפל לפני ה'** . יאמר כי הוצרכתי להתנפל עליכם ארבעים יום וארבעים לילה על החטא הגדול הזה כי מתחלה אמר ה' להשמיד אתכם עד שאתפלל אל ה' ואומר אל תשחת עמך ונחלתך כי זאת היתה תפלתו קודם רדתו מן ההר וממנה נענה בוינחם ה' על הרעה אשר דבר לעשות לעמו (שמות לב יד) ולא הזכיר תפלת הארבעים יום וארבעים לילה כי ארוכה מארץ מדה ורחבה מני ים וטעם השמות הכתובים באל"ף דל"ת יו"ד ה"א פרשתיו (לעיל ג כד)
@290 **מבלי יכלת ה' להביאם אל הארץ אשר דבר להם** . אמר במרגלים (במדבר יד טז) מבלתי יכולת ה' להביא את העם הזה אל הארץ אשר נשבע להם וישחטם במדבר כלומר יאמרו כי כאשר באו והיו קרובים לארץ וראה שאין יכולת בידו כנגד העמים ההם שחטם במדבר אבל בכאן אמר ומשנאתו אותם הוציאם להמיתם במדבר כי היתה השנאה הזאת בהם במצרים טרם שהוציאם משם והטעם בעבור שהיו במעשה העגל עדין קרובים למצרים רחוקים מארץ כנען יאמרו כי גם בהיותם במצרים ראה שאין יכולת בידו להביאם אל הארץ אשר דבר להם באזני המצריים ועל כן שנאם ו לבלתי החל לעיני הגוים אשר נודע אליהם לעיניהם (ו) הוציאם ממצרים להמיתם במדבר במקום שלא יודע מה היה להם וזהו ברעה הוציאם להרג אותם בהרים (שמות לב יב) שחשב עליהם מחשבת רעה טרם שיצאו שהוציאם מתוך עם מצרים להרוג אותם בין ההרים מקום אשר לא יעבור בו איש ולא ישב אדם שם והכונה בטענות כי הגוים ידברו בה' אלהי ישראל לאמר עליו כאלהי גויי הארצות וכענין שנאמר (דניאל י כ) ועתה אשוב להלחם עם שר פרס וכבר הזכרתי מן הענין הזה
@292 **בעת ההיא אמר ה' אלי פסל לך** . אחר שהתנפלתי לפני ה' את ארבעים היום ואת ארבעים הלילה נתרצה אלי שיכתוב לוחות שניות אבל היו הראשונות מעשה אלהים והמכתב מכתב אלהים ובאלו צוה אותי שיהיו מחצב ידי והמכתב יהיה כמכתב הראשון באצבע אלהים וטעם ועשית לך ארון עץ שתשים הלוחות בתוכו בעת שתרד והיה הארון הזה כולו עץ הוא והמכסה אשר עליו מלמעלה כמנהג בכל הארונות והיו הלוחות שם עד שנעשה המשכן ואז עשו הארון המצופה זהב והכפורת אשר עליו זהב טהור ולא אמר לו כן בלוחות הראשונות לפי שהיה גלוי לפניו שישברם וטעם ויהיו שם כאשר צוני ה' (פסוק ה) שהיו שם עד שנעשה המשכן שצוני (שמות כה כא) ונתת את הכפורת על הארון מלמעלה ואל הארון תתן את העדות אשר אתן אליך וזהו הטוב והישר בפסוקים האלה וכתב רש"י ולא זהו ארון שעשה בצלאל שהרי לא נתעסקו במשכן אלא לאחר יום הכפורים כי ברדתו מן ההר צוה להם על מלאכת המשכן ובצלאל עשה המשכן ואח"כ ארון וכלים נמצא זה אחר היה וזהו שהיה יוצא עמהם למלחמה ואותו שעשה בצלאל לא יצא במלחמה אלא בימי עלי ונענשו עליו ונשבה זה לשון הרב ודברי אגדה הם שמצא כתוב בתנחומא ויש לשאול ואחר שהוציא משם הלוחות ונתנם בארון שעשה בצלאל מה היה בזה ולמה הוא יוצא עמהם למלחמה ואומרים ששברי הלוחות היו שם וכן באגדה אבל דברי יחיד הם שכך שנינו במסכת שקלים (ירושלמי פ"ו ה"א) תניא רבי יהודה ברבי אלעאי אומר שני ארונות היו עם ישראל במדבר אחד שהיו שברי הלוחות מונחין בו וכו' ורבנן אמרי אחד היה ופעם אחת יצא בימי עלי ונשבה ודעת רבותינו בכל מקום בתלמוד (ברכות ח ב"ב יד מנחות צט) אינו כן אלא לוחות ושברי לוחות מונחים בארון ועוד אנה יעמוד הארון הזה עם הלוחות הראשונות כל ימי המדבר כי במשכן בבית קדשי הקדשים לאחר הפרוכת אין שם שני ארונות וכן שלמה לא הכניס לבית קדשי הקדשים אלא ארון אחד (מלכים א ח ו-ט)אבל הארון הזה של משה כשנעשה ארונו של בצלאל גנזוהו כדין תשמישי קדושה וזהו הנכון על דעת רבותינו כי על דרך הפשט יתכן כי ועשית לך ארון עץ ירמוז לארון שעשה בצלאל וזה כי מתחלה נצטווה משה על המשכן וכליו והיתה המצוה הראשונה ועשו ארון עצי שטים (שמות כה י) כי היא עיקר הכוונה בכל המשכן להיות השם יושב הכרובים ואחרי כן עשו את העגל וכאשר נתרצה השם למשה ואמר לו שיכתוב על הלוחות האלו כמכתב הראשון צוהו בקצרה שיעשה ללוחות האלה ארון עץ היא המצוה לו ללוחות הראשונות והנה הזכיר לו המצוה הראשונה שבענין המשכן ושהכל תלוי בה ומזה למד משה לעשות המשכן וכליו כאשר נצטווה מתחלה ויהיה פירוש ויהיו שם כאשר צוני ה' שהיו שם לעד לעולם כאשר צוהו ה' מתחלה (שם שם כא-כב) ואל הארון תתן את העדות אשר אתן אליך ונועדתי לך שם ודברתי אתך וגו' והנה ברדתו הניח הלוחות באהל מועד עד שיעשה הארון והמשכן כי אלו לא שבר הלוחות הראשונות באהל מועד יהיו עד עשות בצלאל הארון וכן שברי הלוחות על כרחנו שם היו כי לא החזירם עמו להר וראיה לזה שלא הזכיר משה זו הצואה בסדר כי תשא כי שם הזכיר ארון בצלאל בפירוש וכאן לא הזכיר המשכן וכליו כי הם הרואים אותו ולפיכך הזכיר זה בקצרה ואל יקשה בעיניך שאמר ואעש ארון עצי שטים ואפסל שני לוחות אבנים כי השלים ענין הארון כאחד כי הנה צוהו השם פסל לך וגו' ועלה אלי ההרה ועשית לך ארון עץ שיעלה תחלה בלוחות ואחרי כן יעשה ארון עץ אבל האריך לומר ואכתב על הלוחות את הדברים אשר היו על הלוחות הראשונים אשר שברת ושמתם בארון לומר שיהיו כראשונות במכתב וראוי שיהיו בארון המצוה כראשונות שאועד שמה לבני ישראל ונקדש בכבודי ולכך השלים ואעש ארון להשלים המצוה והמעשה בקצרה ואחרי כן שב להאריך במוקדם וטעם ואפן וארד מן ההר ואשם את הלוחות בארון אשר עשיתי שעשיתיו ברדתי ויהיו שם לעד כאשר צוני ה' להיות כבודו שוכן בתוך בני ישראל
@297 **ובני ישראל נסעו מבארות בני יעקן מוסרה** . מה ענין זה לכאן? ועוד וכי מבארות בני יעקן נסעו למוסרה והלא ממוסרה באו לבני יעקן שנאמר (במדבר לג לא) "ויסעו ממוסרות ויחנו בבני יעקן"? ועוד "שם מת אהרן" והלא בהר ההר מת? צא וחשוב ותמצא שמונה מסעות ממוסרות להר ההר? אלא אף זו מן התוכחות: ועוד זאת עשיתם כשמת אהרן בהר ההר בסוף ארבעים שנה ונסתלקו ענני הכבוד יראתם לכם ממלחמת מלך ערד ונתתם ראש לחזור למצרים וחזרתם לאחוריכם שמונה מסעות עד בני יעקן ומשם למוסרה, שם נלחמו בכם בני לוי והרגו מכם ואתם מהם עד שהחזירו אתכם לדרך, ומשם חזרתם הגדגדה הוא חור הגדגד, ומן הגדגד למוסרה, ובמוסרה עשיתם אבל גדול על מיתתו של אהרן שגרמה לכם זאת ונדמה לכם כאלו הוא מת שם. וסמך משה תוכחה זו לשבירת הלוחות לומר שקשה מיתתן של צדיקים לפני הקדוש ברוך הוא כיום שנשתברו הלוחות, ולהודיעך שקשה לו מה שאמרו "נתנה ראש" לפרוש ממנו כיום שעשו את העגל. בעת ההיא הבדיל ה' את שבט הלוי מוסב לענין הראשון בעת ההיא בשנה הראשונה שיצאתם ממצרים וטעיתם בעגל ובני לוי לא טעו הבדילם המקום מכם. וסמך זה לחזרת בני יעקן לומר שאף בזה לא טעו בה בני לוי אלא עמדו באמונתם כל זה לשון רבינו שלמה מדברי אגדה (ירושלמי יומא פ"א ה"א).
@297 והוצרך רבי אברהם לומר בדרך הפשט כי בארות בני יעקן איננו בני יעקן, ומוסרה איננו מוסרות, אבל קדש נקרא בארות בני יעקן ושם (ב) מדבר הר ההר מוסרה משם נסעו הגדגדה איננו חר הגדגד רק הוא שם כלל לצלמונה ופונון ואובות ויטבתה הוא המקום הנקרא בארה (במדבר כא טז), וזה טעם ארץ נחלי מים, וידבק "ומן הגדגדה יטבתה" עם "ויכהן אלעזר" כי שם ביטבתה כהן אלעזר בכהונה גדולה והקריב קרבנות.
@297 וכל אלה דברי רוח כי איך יתכן שכל המקומות האלה הרבים שיהיו כולם מקומות חדשים שלא נזכרו במסעות?
@297 ועוד: שמנהג הכתוב בכל מקום לשנות מעט בהזכירו השמות פעמים בין בשם מקום בין בשם אדם, וכל שכן בכאן שהם שוים כי מוסרה ומוסרות איננו שנוי והפרש וכן חר הגדגד והגדגדה שם אחד ויטבתה שוה לגמרי?
@297 ועוד: כי בהר ההר כהן אלעזר כשמת אביו כאשר הלבישו הבגדים, כי מיד היה מרובה בבגדים, וזה משפט הכהנים הגדולים אפילו לדורות?
@297 והנראה בעיני כי הר ההר, גדול שבהרים וארוך פרסאות רבות, ושמו מוכיח כי הוא יקרא "הר", ויאמרו לו "ההר" לגודלו וארכו. וכך אמרו רבותינו (במדב"ר יט טז) שהיה הר על גבי הר והיה סוף ההר עד גבול ארץ אדום וראשו קרוב לחשמונה, והיו במישור אשר לפני הר ההר ערים או מקומות הנקראים מוסרות ובני יעקן וחור הגדגד ויטבתה ועברונה ועציון גבר וקדש, ואלו המקומות אין ביניהם מרחק רב כי המחנה הגדול ההוא ביום אחד מהלכים כמו פרסה או פחות מכאן, ונסעו מקדש ויחנו בהר ההר שנכנסו בו במקום שפל אשר היה ברגלי ההר, ואז צוה ה' למשה (במדבר כ כה) "והעל אותם הר ההר" שיעלה למעלה אל ראשו הוא תחלת ההר והנה עלו אל ראשו של הר והגיעו כנגד מוסרות ומת אהרן שם, והוא שנאמר (שם פסוק כח) "וימת אהרן שם בראש ההר" והנה מיתתו במוסרה? ואפשר שהיו המקומות האלה בשמם נחשבים בהר עצמו ויקרא ראש ההר וכנגדו במישור מוסרות, ושם כל אחד מוסרה שיאמרו מוסרה אשר בהר ומוסרה אשר בשפלה. והיו במקום הנקרא חשמונה בארות בשדה, יקראו אותן בארות בני יעקן כי אנשי בני יעקן באים שם להשקות צאנם, והם עשאום כי שם מצאו מים חיים, ומשם נסעו למוסרה ומשם נסעו למוסרות ויסעו ממוסרות ויחנו בבני יעקן שהמקום ההוא זה שמו. וספר הכתוב "משם נסעו הגדגדה, ומן הגדגדה יטבתה ארץ נחלי מים" להודיע שעמדו שם ימים בעבור הנחלים, וקצר במסעיהם שכבר באר אותם אבל אמר כי משם ממוסרה נסעו אל הגדגדה ואל יטבתה שהיא כולה ארץ נחלי מים, כי מן גדגד ועד יטבתה כולה משקה. ויתכן עוד שנאמר כי כאשר עלה אהרן אל ראש ההר וימת בראש ההר כנגד מוסרות או במוסרה עצמה ויקבר שם חזרו ישראל אל מוסרות לבכות ולספוד על קבר איש האלהים, והיו גדוליהם בכל השלשים יום עולים אל ראש ההר וסופדים לקדוש ה', וישובו אל המחנה במוסרה. ואחר השלשים יום נסעו ממוסרה אל חר הגדגד ומן הגדגדה יטבתה כי עתה בשובם הלכו מהרה. וזה דבר נכון מאד בישוב המקראות על אופנן והזכיר כי היה שם המקום יטבתה בעבור שהיה מקום טוב כי שם נחלי מים ושאר המדבר ארץ ציה וצמאון אשר אין שם מים. וטעם הזכירו מיתת אהרן עתה במקום הזה כי אמר (לעיל ט כ) "וָאֶתְפַּלֵּל גַּם בְּעַד אַהֲרֹן בָּעֵת הַהִוא" ולא הגיעו עונש השמד לא בגופו ולא בזרעו כי לא מת עד שנת הארבעים שהיה זקן ושבע ימים וכהן בנו תחתיו. ואמר ובני ישראל נסעו ולא אמר "ואתם" כדרך כל הפרשה, כי בתוכחות ידבר עמהם להוכיח אותם אבל בזה יספר במסעי בני ישראל.
@299 **בעת ההיא הבדיל ה' את שבט הלוי** . מוסב לענין ראשון בעת ההיא בשנה הראשונה שיצאתם ממצרים וטעיתם בעגל ובני לוי לא טעו הבדילם המקום מכם לשון רש"י ואם כן יאמר כי מן העת ההיא הובדלו לפניו יתברך כי לא הבדילם במעשה עד השנה השנית בחדש השני או ירמוז למה שאמר להם (שמות לב כט) מלאו ידכם היום לה' כי יהיה זה לכם מלוא ידים בעבודת כהונה ולויה והנכון בעיני כי "בעת ההיא" השני כראשון (לעיל פסוק א) כי בעת שאמר לו פסל לך שני לוחות אבנים (שמות לד א) נתרצה לישראל ונצטוה על המשכן ואז נתרצה גם לאהרן ונצטוה (שם כח ד) ועשו בגדי קדש לאהרן אחיך ולבניו לקדשו לכהנו לי וצוהו במלואים ולכך אמר כי אלעזר כהן תחת אביו שהיתה בהם משחתם לכהונת עולם לדורותם ועשה הבדלת כל השבט ענין אחד כי מן היום ההוא היה לפניו שיהיו שבטו נתונים נתונים לו לעבוד עבודת המשכן או יאמר כי שבט הלוי נבדל בעת ההיא להיות הכהנים מהם כי גם הם נושאים הארון וכן ויתנה אל הכהנים בני לוי הנושאים את ארון ברית ה' (להלן לא ט) והם שישרתו לשם ויברכו בשמו וטעם עד היום הזה בעבור כהונת אלעזר כאומר אז הבדילם לשרתו ויהי כן עד היום הזה
@300 **וטעם על כן לא היה ללוי** . הוא בעבור שכולם משרתים ועוזרים את הכהנים בעבודתם כי כל דבר המקדש בעבור הקרבנות וכן אמר (במדבר יח ב) וגם את אחיך מטה לוי שבט אביך הקרב אתך וילוו עליך וישרתוך
@301 **ואנכי עמדתי בהר** . על דעת רבותינו (סדר עולם ו) יאמר שעמד בהר כשעלה שם ושני הלוחות בידו כימים הראשונים של לוחות הראשונות ארבעים יום וארבעים לילה וישמע ה' אלי גם בפעם השלישית כי עבר ה' על פניו ויקרא ה' ה' אל רחום וגו' (שמות לד ו) ובקש ממנו (שם שם ט) וסלחת לעוננו ולחטאתנו ונחלתנו ונענה ואמר קום לך למסע לפני העם ויבאו ויירשו את הארץ וזהו וראה כל העם אשר אתה בקרבו את מעשה ה' כי נורא הוא אשר אני עושה עמך (שם שם י) וטעם לא אבה ה' השחיתך שלא רצה שלא תבאו ותירשו את הארץ כטעם ויסף עוד להניחו במדבר ושחתם לכל העם הזה (במדבר לב טו) ועל דרך האמת לא רצה שתהיה משחת ממנו שלא יהיה שמו הגדול עמך וכבר רמזתי זה הענין בסדר כי תשא
@303 **מה ה' אלהיך שואל מעמך** . נמשך אל לטוב לך יאמר איננו שואל מעמך דבר שיהיה לצרכו אלא לצורכך כטעם אם צדקת מה תתן לו (איוב לה ז) רק הכל הוא לטוב לך ואמר הטעם כי לה' אלהיך השמים ושמי השמים הארץ וכל אשר בה וכולם נותנים כבוד לשמו איננו צריך לך רק באבותיך חשק ויבחר בזרעם אחריהם מכל העמים בכם שאתם מבחר זרעם ולא בישמעאל ולא בעשו וטעם כיום הזה כי כן יהיה בכל זרעם לעולם וכבר פירשתי (לעיל ז ז) החשק והבחירה ופירוש שמי השמים גלגלי ארבעה יסודות שהם בכח השמים למטה מהם כענין הארץ וכל אשר עליה (נחמיה ט ו) וכן אמר במזמור הללו את ה' מן השמים הללוהו במרומים (תהלים קמח) והזכיר מלאכיו וצבאיו ושמש וירח וכוכבי אור ואחר כך הללוהו שמי השמים
@307 **ומלתם את ערלת לבבכם** . שיהיה לבבכם פתוח לדעת האמת לא כאשר עשיתם עד היום שלא נתן ה' לכם לב לדעת ועינים לראות ואזנים לשמוע וערפכם לא תקשו עוד שלא תהיו כאבותיכם דור סורר ומורה שישבו עם המצרים וילמדו מעשיהם והם קשים לעזוב דרכם כמו שעשו את העגל וקראם שם (שמות לב ט) עם קשי ערף שלא ישובו מן הטעות שנכנס בלבם לחשוב שיש תועלת בעבודת המלאכים או צבא השמים אבל אתם תדעו ותשכילו ותאמינו כי ה' אלהיכם הוא אלהי האלהים ואדוני האדונים אלהי האלהים הם מלאכי מעלה ואדוני האדונים כל צבא השמים אשר להם ממשלה בשפלים כי הוא האדון אשר שם להם משטרם בארץ ולו הגדולה והגבורה והוא נורא בתפארת עוזו אשר לא ישא פנים לאחד מן האלהים והאדונים להגן על עובדיהם ולא יקח שחד מיד אדם ופירשו בשחד שאפילו חסיד גמור שיעבור עבירה לא יקח ממנו מצוה ממצותיו בשחד לכפר לו אבל יענישהו על חטאיו ויגמול לו ככל טובותיו ואונקלוס תרגם דלית קדמוהי מסב אפין ואף לא לקבלא שוחדא יתכוין לפרש שהוא משבחי השלילות בבורא יתברך יאמר הכתוב שאין השם בענין שישא פנים כי לא יראנו האדם וחי והכל כאין נגדו ומאפס ותהו נחשבו לו ולא בענין שיקח שוחד וממון מאדם כמלכים ושופטי הארץ והנכון בעיני שיאמר אשר לא ישא פנים לגדולי בני אדם בריבם עם קטניהם ולא יקח שוחד מעשיריהם בריבם עם דל כי הוא עושה משפט יתום ואלמנה מן הגדולים וקבע את קובעיהם נפש ואוהב גר לתת לו לחם ושמלה והם כל צרכי האדם והנה הוא יפרנס העניים אשר אין להם אוהב ורע
@310 **כי גרים הייתם בארץ מצרים** . מום שבך אל תאמר לחברך לשון רש"י וכבר פירשתי בסדר ואלה המשפטים (שמות כב כ)
@312 **וטעם הוא תהלתך והוא אלהיך** . הוא יהיה תהלתך שתתן כל תהלתך אליו אותו תהלל תמיד וכבודו לאחר לא תתן ותהלתו לפסילים ולא אל האלהים והאדונים הנזכרים או יאמר הוא תהלתך שבו אתה מהולל על כל העמים כלשון כי תפארת עזמו אתה (תהלים פט יח) ה' עזי ומעזי (ירמיהו טז יט)
@312 "והוא אלהיך" - שיחד שמו עליך שתהיה לו לעם והוא יהיה לך לאלהים ולא כשאר האומות אשר הוא להם אלהי האלהים אשר חלק להם כמו שפירשתי (ויקרא יח כה) כי עשה עמך הגדולות והנוראות שמהם תכיר כי אתה חבלו ונחלתו ועיניו תמיד עליך לטוב
@314 **ושמרת משמרתו** . ליראה אותו שתשמור מחטוא לפניו כי אחר שיצוה באהבה יצוה ביראה ויצוה בחוקים ובמשפטים ובמצות או ושמרת משמרתו שתשמור מה שהשם שומר שהוא שומר את הגרים וחונן דלים ואביונים ועושה משפט יתום ואלמנה וכענין שנאמר במקום אחר (מלכים א ב ג) לשמור את משמרת ה' אלהיך ללכת בדרכיו ואמרו (שבת קלג) מה הוא חנון ורחום אף אתה היה חנון ורחום וכו'
@315 **את גדלו את ידו החזקה וזרועו הנטויה** . אמר ר"א להוציא אתכם ממצרים והאותות והמופתים שעשה לפרעה ואשר עשה לכם במדבר בדבר המן ואיננו נכון בעיני כי עתה לא ידבר רק במוסר אשר ייסר בו השם לעוברי רצונו את גדלו שהיה מתרומם ומתגדל לאמר התפאר עלי (שמות ח ה) למחר יהיה (שם פסוק יט) ושמתי פדות (שם) למען תדע כי לה' הארץ (שם ט כט) ואת ידו החזקה ושלחתי את ידי והכיתי את מצרים (שם ג כ) את היד הגדולה אשר עשה ה' (שם יד לא) וזרועו הנטויה שלא נתן להם ריוח והצלה מאז היתה ידו נטויה עליהם ולא השיב ידו מבלע עד שאבדם ואשר עשה לכם במדבר (פסוק ה) אשר נגף אתכם בעגל ואש תבערה והנחשים השרפים וקברות התאוה ומגפת השטים וגזרת המרגלים שהיתה בהם יד ה' עד בואם אל המקום הזה וקצר בפורענות שעשה להם ואם כן ושמרתם את כל המצוה למען תחזקו כי ידו החזקה מחזקת שומרי מצותיו ולא יחזיק ביד מרעים
@317 **אשר הציף את מי ים סוף וגו' ויאבדם ה' עד היום הזה** . לא הבינותי טעם "עד היום הזה" כי כל המתים בים אבדן עולם הם אובדים ויתכן שהוא חוזר לסוסיו ולרכבו שאבד סוס ורכב ממצרים בכל הדור ההוא כי כל סוס ורכב וכל פרש אשר במצרים הוציא עמו ואבדו כולם והיתה ממלכה שפלה בלא רכב וסוס וחיל ועזוז ואמר ר"א שלא קמו עוד בניהם תחתם להיות כמוהם ר"ל כי השם אבד הרודפים בים ואבד במצרים זרעם ולא נשאר להם שם ושאר כי הם הרשיעו יותר מכל מצרים לרדוף אחרי גאולי השם אבל זה לא נזכר בתורה
@319 **ואשר עשה לדתן ולאבירם** . ולא הזכיר קרח ועדתו שיצאה אש מלפני ה' ותאכל אותם בעבור כי איש זר הקרב להקטיר קטורת הוא מלאוי התורה (במדבר יז ה) ולעולם הוא נענש לדורות כאשר קרה גם לעזיהו (דהי"ב כו יט) על כן לא מנאו באותות המדבר
@323 **לא כארץ מצרים היא** . אלא טובה הימנה ונאמרה הבטחה זו לישראל ביציאתם ממצרים שהיו אומרים שמא לא נבוא אל ארץ טובה ויפה כזאת יכול בגנותה הכתוב מדבר וכך אמר להם לא כארץ מצרים היא אלא רעה הימנה תלמוד לומר וחברון שבע שנים נבנתה (במדבר יג כב) אדם אחד בנאן דרך ארץ אדם בונה את הנאה ואחר כך את הגרוע וכו' לשון רש"י מספרי (עקב יא) ועוד הביא מה שדרשו בגמרא במסכת כתובות (קיב) בענין אחר אפשר אדם בונה בית לבנו קטן ואחר כך לבנו גדול אלא שמבונה אחד משבעה בצוען ופשוטו של מקרא בדרך האזהרות נאמר שאמר להם ושמרתם את כל המצוה וירשתם ארץ זבת חלב ודבש כי ה' יתן מטר ארצכם בעתו והארץ תתן יבולה אבל דעו לכם שאינה כארץ מצרים להשקות אותה ברגל מן היאורים ומן האגמים כגן הירק רק היא ארץ הרים ובקעות למטר השמים תשתה מים לא בענין אחר וצריכה שידרוש ה' אותה תמיד במטר כי היא ארץ צמאה מאד וצריכה מטר כל השנה ואם תעברו על רצון ה' ולא ידרוש אותה בגשמי רצון הנה היא רעה מאד לא תזרע ולא תצמיח ולא יעלה בה כל עשב בהריה ויחזור ויפרש כל זה בפרשה השניה (להלן פסוקים יג-יז) כי אם שמוע תשמעו אל מצותי ונתתי מטר ארצכם בעתו יורה ומלקוש תמיד ואם לא תשמעו ועצר את השמים וגו' ואבדתם מהרה ברעב מעל הארץ הטובה שלא תוכלו לחיות בה בלא מטר והנה הפרשה הזו תזהיר במנהגו של עולם וממנה נלמד כי אע"פ שהכל ברשותו ונקל בעיני ה' יתברך להאביד יושבי ארץ מצרים ולהוביש נהרותם ויאוריהם אבל ארץ כנען תאבד יותר מהרה שלא יתן בה מטרות עוזו החולה צריך זכות ותפלה שירפאהו השם יותר מן הבריא שלא בא עליו החולי וכך המדה בעני ובעשיר ומאיר עיני שניהם ה' ומפני שאמר (פסוק יב) ארץ אשר ה' אלהיך דורש אותה וראוי שיאמר ולמטר השמים תשתה מים כאשר ה' אלהיך ידרוש אותה יהיה מדרש רבותינו (ספרי עקב יב) נרמז בכתוב והלא כל הארצות הוא דורש שנאמר (איוב לח כו) להמטיר על ארץ לא איש כביכול אינו דורש אלא אותה ועל ידי אותה דרישה שדורש אותה דורש כל הארצות תמיד עיני ה' אלהיך בה לראות מה היא צריכה ולחדש בה גזרות עתים לטובה ועתים לרעה כו' כדאיתא במסכת ר"ה (יז) ויש בו סוד עמוק כי הארץ הזאת נדרשת בכל והיא הכל וכל הארצות מתפרנסות ממנה באמת
@326 **בכל לבבכם ובכל נפשכם** . והלא כבר הזכיר בכל לבבך ובכל נפשך אלא אזהרה ליחיד ואזהרה לצבור לשון רש"י מספרי (עקב יג) ובאור הענין כי השם לא יעשה הנסים תמיד לתת מטר הארץ בכל עת יורה ומלקוש ולהוסיף בדגן ובתירוש וביצהר ולהרבות גם העשב בשדה לבהמה או שיעצור השמים וייבשו רק על מעשה רוב העם אבל היחיד הוא בזכותו יחיה והוא בעונו ימות והנה אמר כי בעשותם כל המצות מאהבה שלימה יעשה עמהם את כל הנסים האלה לטובה ואמר כי בעבדם ע"ז יעשה עמהם אות לרעה ודע כי הנסים לא יעשו לטובה או לרעה רק לצדיקים גמורים או לרשעים גמורים אבל הבינונים כדרך מנהגו של עולם יעשה בהם טובה או רעה כדרכם וכעלילותם
@328 **ואכלת ושבעת** . הרי זו ברכה אחרת שתהא ברכה מצויה בפת שבתוך מעיך ואכלת ושבעת לשון רש"י ור"א אמר "ואכלת ושבעת" שב אל דגנך תירושך ויצהרך לא אל הקרוב שהוא "עשב בשדך" והנכון בעיני שהוא שב אל הכל ואכלת ושבעת דגן ותירוש ויצהר וגם בני צאן ובקר ובספרי (עקב טו) ואכלת ושבעת כשבהמתך אוכלת ושובעת עובדת האדמה וכן הוא אומר (משלי יד ד) ורב תבואות בכח שור ד"א מן הולדות אע"פ שאין ראיה לדבר זכר לדבר שנאמר (ירמיהו לא יא) ובאו ורננו במרום ציון ונהרו אל טוב ה' על דגן ועל תירוש ועל יצהר ועל בני צאן ובקר וגו' וזהו הנכון
@331 **ושמתם את דברי אלה** . אף לאחר שתגלו היו מצוינין במצות הניחו תפילין עשו מזוזה כדי שלא יהו עליכם חדשים כשתחזרו וכן הוא אומר (שם שם כ) הציבי לך ציונים לשון רש"י וכבר כתבתי פירוש הענין כי המצות האלה חובת הגוף הם ודינם בכל מקום כמו בארץ אבל יש בו במדרש הזה סוד עמוק וכבר רמזתי ממנו (ויקרא יח כה) והנה החזיר במצות האלה תפילין ודברי תורה ומזוזה כאן פעם שנית לרמוז בהיקש הזה שנהיה חייבים בהם לאחר הגלות בחוצה לארץ ומהם נלמוד לכל המצות שהן חובת הגוף שחיובן בכל מקום ושנהיה פטורין בחוצה לארץ מחובת הקרקע כגון תרומה ומעשרות כך הוא נדרש בספרי (עקב יז) וכוונת המדרש מפני שסמך ושמתם אל ואבדתם אבל עיקר הכתוב בארץ דכתיב (פסוק כא) למען ירבו ימיכם וימי בניכם על האדמה או יאמר "למען ירבו ימיכם" שתשובו ותאריכו בה ימים לעולם ויתכן בדרך הפשט שבא להוסיף בכאן לדבר בם כי שם (לעיל ו ז) צוה ודברת אתה בם בשבתך בביתך וכאן אמר שנלמד אותם את בנינו עד שידברו בם הבנים בכל שעה וכן הוסיף בכאן ולמדתם אותם כי "ושננתם" שיספר להם המצות וכאן עד שילמדו אותם וידעום ויבינו אותם וטעמיהם לדבר עמך בם בכל העתים וכן הוסיף כאן כימי השמים על הארץ שהוא לדור דורים או הם השמים והארץ הראשונים וימי עולם והמשכיל יבין
@335 **ולדבקה בו** . אמר ר"א בסוף והוא סוד גדול ואין הסוד מטעם המקום הזה אולי יאמר לאהבה את ה' ללכת בכל דרכיו עד שתהיו ראויים לדבקה בו בסוף ונאמר ביהושע (כג ז ח) ובשם אלהיהם לא תזכירו ולא תשביעו ולא תעבדום ולא תשתחוו להם כי אם בה' אלהיכם תדבקו כאשר עשיתם עד היום הזה אם כן היא אזהרה מאזהרות ע"ז שלא תפרד מחשבתו מן השם אל אלהים אחרים שלא יחשוב שיהיה בע"ז שום עיקר אלא הכל אפס ואין והנה זה כמו שאמר עוד (להלן יג ה) ואותו תעבודו ובו תדבקון והכוונה להזהיר שלא יעבוד השם וזולתו אלא לה' לבדו יעבוד בלבו ובמעשיו ויתכן שתכלול הדביקה לומר שתהיה זוכר השם ואהבתו תמיד לא תפרד מחשבתך ממנו בלכתך בדרך ובשכבך ובקומך עד שיהיו דבריו עם בני אדם בפיו ובלשונו ולבו איננו עמהם אבל הוא לפני ה' ויתכן באנשי המעלה הזאת שתהיה נפשם גם בחייהם צרורה בצרור החיים כי הם בעצמם מעון לשכינה כאשר רמז בעל ספר הכוזרי וכבר הזכרתי מזה בפרשת העריות (ויקרא יח ד) ומה שאמר יהושע "כאשר עשיתם עד היום" כי בהיותם במדבר וענן ה' עליהם והמן יורד מן השמים והשלו עולה והבאר לפניהם תמיד וכל מעשיהם בידי שמים בדברים נסיים הנה מחשבתם ומעשיהם עם השם תמיד ולכן יזהירם יהושע שגם עתה בארץ בהסתלק מהם המעשים הנפלאים ההם תהיה מחשבתם בהם תמיד לדבקה בשם הנכבד והנורא ולא תפרד כוונתם מן השם
@337 **כל המקום אשר תדרך כף רגלכם בו לכם יהיה מן המדבר וגו'** . על דעת רבותינו הנה הם שתי הבטחות שכל מקום אשר ירצו לכבוש בארץ שנער וארץ אשור וזולתם יהיה שלהם והמצות כולן נוהגות בהם כי הכל ארץ ישראל ומן המדבר והלבנון ועד הים האחרון יהיה גבולכם שאתם חייבים לכבשו ולאבד משם העמים כמו שאמר כאן (פסוק כג) וירשתם גוים גדולים ועצומים מכם ולעקור ע"ז ומשמשיה כמו שהזכיר למעלה (ז ה כה) והבטיח כי לא יתיצב איש בפניכם בין בארץ הנזכרת בין בכל מקום אשר תדרוך כף רגלכם בו ומכאן יצא לרבותינו (חלה פ"ד מ"ז) המחלוקת בסוריא שקורין אותה כיבוש יחיד והטעם כי דוד כבש אותה ברצון נפשו שלא שאל באורים ותומים ולא נמלך בסנהדרין כי היה חייב להוריש כל שבעת הגוים בתחלה ואחרי כן אם ירצה ילך אל ארץ אחרת כאשר הבטיח השם בכאן ומפני שלא נעשה הכבוש ההוא כמצות התורה אמרו מקצתם לא שמיה כבוש ודינו במצות כדין חוצה לארץ וכך היא שנויה בספרי (עקב כד) ומקצתם יאמרו בתלמוד (ע"ז כא) דשמיה כבוש כי אף על פי שלא נעשה כסדר כיון שהלך שם וכבשה נתקיים בו לכם יהיה וארץ ישראל היא
@342 **ונתתה את הברכה על הר גרזים** . כתרגומו ית מברכיא את המברכים על הר גרזים כלפי הר גריזים לשון רש"י ואיננו נכון כפי פשוטו כי עדין לא צוה במברכים אלא פירושו כי אני נותן לפניכם דרך ברכה ודרך קללה וטעם "לפניכם" שתבררו לכם מהן מה שתרצו ואודיע שתהיה לכם הברכה כאשר תעשו המצות והקללה אם לא תקיימו אותן וזה כאשר אמר עוד (להלן ל טו) ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע וגו' ואחר כן אמר בכאן שיתנו הברכה הזאת אשר הוא אומר להם על הר גריזים והקללה על הר עיבל והנה היא נתונה בפה וכן ונתן אותם על ראש השעיר (ויקרא טז כא) כדברי ר"א והנה אמר בכאן בדרך האזהרה שיתנו את הברכה על הר גריזים לברך את העם אם ישמעו אל מצות ה' והקללה על הר עיבל לאמר ארור אשר לא ישמע אל המצות ויסור מן הדרך אשר צוה ה' והיה אפשר שיתנו כל השבטים הברכה וכולם הקללה או שיאמרו הלוים הכל או איש אחד משמיע לכולם ואחרי כן שב לבאר שם (להלן כז יב-יד) ואלה יעמדו לברך את העם על הר גריזים ואלה יעמדו על הקללה ואמר וענו הלוים ופירש כל הענין כי בכאן מפני אזהרתו אשר אמר ראה אנכי נותן וגו' הזכיר מקצת המצוה וחזר לבאר אותה במקומה ויתכן שהיה הר גריזים לדרום שהוא הימין והר עיבל מצפון שנאמר (ירמיהו א יד) מצפון תפתח הרעה
@345 **ושמרתם לעשות את כל החוקים ואת המשפטים** . גם בכאן יזהיר על החוקים ועל המשפטים קודם שאר המצות ויזכיר תחלה המשפט בע"ז ומשמשיה כאשר פירשתי בסדר ואתחנן (לעיל ד ג) ואחרי כן יזכיר משפטים רבים בנביא השקר ומסית ועיר הנדחת ויזכיר בחוקים תחלה הקרבנות במקדש ואח"כ איסור אכילת כל תועבה ושאר המצות
@349 **לא תעשון כן לה' אלהיכם** . להקטיר לשמים בכל מקום כי אם במקום אשר יבחר דבר אחר ונתצתם את מזבחותם ואבדתם את שמם לא תעשון כן אזהרה למוחק את השם ולנותץ אבן אחת מן המזבח או מן העזרה אמר רבי ישמעאל וכי תעלה על דעתך שישראל נותצין המזבחות אלא שלא יעשו כמעשיהם ויגרמו עונותיכם למקדש אבותיכם ליחרב לשון רש"י ודברי רבי ישמעאל סמך של אגדה הם אבל הכתוב כדעת רבותינו אזהרה למוחק את השם ומפורש במסכת מכות (כב) והא איכא מוחק את השם דלקי ואזהרתיה מהכא לא תעשון כן לה' אלהיכם ולשון ספרי (ראה ז) מנין לנותץ אבן אחת וכו' רבי ישמעאל אומר מנין למוחק אות אחת מן השם שעובר בלא תעשה שנאמר ואבדתם את שמם לא תעשון כן רבן גמליאל ברבי אומר וכי תעלה על דעתך וכו' ודברי רבי ישמעאל אינם במחלוקת אבל הם ביאור כי מוחק את השם כנותץ אבן מן המזבח ואם כן יהיה פירוש הכתוב ונתצתם את מזבחותם ואבדתם את שמם מן המקום ההוא ולא תעשון כן לה' אלהיכם לנתוץ את מזבחו ולאבד את שמו אבל תנו כבוד לשמו ולמזבחו ואל המקום אשר יבחר בו לשום שם מזבח לשמו תדרשו ותביאו עולותיכם לפניו
@350 **וטעם לשכנו תדרשו** . שתלכו לו מארץ מרחקים ותשאלו אנה דרך בית השם ותאמרו איש אל רעהו לכו ונעלה אל הר ה' אל בית אלהי יעקב (ישעיהו ב ג) כלשון ציון ישאלו דרך הנה פניהם (ירמיהו נ ה) ובספרי (ראה ח) תדרשו דרוש על פי הנביא יכול תמתין עד שיאמר לך נביא ת"ל לשכנו תדרשו ובאת שמה דרוש ומצא ואח"כ יאמר לך נביא וכן אתה מוצא בדוד וכו' ועל דרך האמת לשכנו תדרשו לכבודו תדרשו ובאת שמה לראות את פני האדון ה' אלהי ישראל וממנו אמרו חכמים "שכינה"
@351 **מעשרתיכם** . מעשר בהמה ומעשר שני לאכול לפנים מן המחיצה ואת תרומת ידכם אלו הבכורים שנאמר בהם (להלן כו ד) ולקח הכהן הטנא מידך לשון רש"י מדברי רבותינו (ספרי יב) ועל דרך הפשט יזכיר הכתוב העולות והזבחים שחייב לאוכלן שם במחיצה לפני ה' והזכיר גם כן שיביא שם המעשר והתרומה שיתן אותם לכהנים וללוים משרתי המקדש וישמחו גם הם עמכם ועם בתיכם כענין שנאמר (מלאכי ג י) הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר השם צבאות אם לא אפתח לכם את ארובות השמים והריקותי לכם ברכה עד בלי די וכן יסדו בבית שני בתרומה ובתרומת המעשר שיביאום למקדש שנאמר (נחמיה י לח) ואת ראשית עריסותינו ותרומותינו ופרי כל עץ תירוש ויצהר נביא לכהנים אל לשכות בית אלהינו ונאמר (שם פסוק לט) לבית אלהינו אל הלשכות לבית האוצר וטעם "תרומת ידכם" מפני שהתרומה לא נתנה בה התורה שיעור אבל היא כאשר תרים ידו וכן מה שאמר (פסוק יז) לא תוכל לאכול בשעריך יזהיר על הישראלי שלא יאכל בשעריו המעשר והבכורות והנדרים והתרומה וחזר והפריש ביניהם (בפסוק יח) כי אם לפני ה' אלהיך תאכלנו אתה ובנך ובתך הנאכל לכם והלוי אשר בשעריך יאכל שם בשעריך הראוי אליו כמו שנאמר בהם (במדבר יח לא) ואכלתם אותו בכל מקום ויקצר הכתוב בדברים המפורשים במקום אחר ואני סובר בפשוטו של מקרא זה כי "תרומת ידכם" מה שירים אדם לה' מכספו ומזהבו לעשות אותו קרבן עולה או זבח והזכיר בקרבן שלשת מינין הנדרים אשר הם הרי עלי קרבן שור או כשב או עז והנדבה אשר יאמר בשור ושה הרי זה עולה ואביא אותה למקדש והתרומה אשר ירים מכל אשר לו כסף או זהב או שהביא בהמתו חולין לעזרה ויאמר לכהנים הרי זו מידי לשם והוא מלשון כל מרים תרומת כסף ונחשת הביאו את תרומת ה' (שמות לה כד) וכן כל תרומת הקדשים אשר ירימו בני ישראל לה' (במדבר יח יט) קרבנות הם וכך אמר בשקלים (שמות ל יג) מחצית השקל בשקל הקדש וגו' תרומה לה' והם לקרבנות (מגילה כט) כי כל מה שירים אדם לה' מכל אשר לו בין לקרבנות בין לבדק הבית כענין ויקחו לי תרומה (שם כה ב) בין לכהנים משרתי ה' הכל יקרא תרומה כענין שכתוב במכס (במדבר לא כט) ונתת לאלעזר הכהן תרומת ה' והיו חולין גמורין בידו וכן ואשקלה להם את הכסף ואת הזהב ואת הכלים תרומת בית אלהינו ההרימו המלך ויועציו (עזרא ח כה) ולא אמר הכתוב "תרומותיכם" שלא נטעה בתרומת הכהנים אבל אמר "תרומת ידכם" מה שתרימו ברצונכם מן הבא בידכם והנה כל הנזכרים בכאן חייבים במחיצה כי פירוש מעשרותיכם מעשר בהמה ומעשר שני הנאכלים לפני השם כי מעשר ראשון מעשר הלוים ומעשר עני להם הוא
@353 **לא תעשון ככל אשר אנחנו עשים פה היום** . אמר רבי אברהם בדרך הפשט כי פירשו בו בעבור שהיו נוסעין ממסע אל מסע ויקריב עולה במסע שירצה ויש מי שיתן בכור צאנו ויש מי שלא יתן כי המצוה תלויה בארץ ואין זאת דעתי רק טעמו שלא היו כולם יראי השם ובעבור שאמר "אנחנו" כי מצות רבות בעולות תלויות בארץ זה לשונו ואינו נכון שאין מדרך הפרשה שידבר בתוכחות ויאמר להם עתה שאינם עושים מצות השם ואיש כל הישר בעיניו יעשה ואיך יאמר משה רבינו אנחנו עושים בעבירות חלילה אבל היה ראוי שיאמר לא תעשו ככל אשר עשיתם עד היום איש כל הישר בעיניו ומה טעם לכלול עם העבירות המצות התלויות בארץ אבל פירוש הכתוב כי ישראל נצטוו במדבר לזבוח כל בקרם וצאנם שלמים לפני המשכן (ויקרא יז ג-ו) אבל באיזה מקום שיהיה המשכן יעשה אותם ואם לא ירצה לאכול שור ושה לא יתחייב להביא קרבן כלל וגם כן אינו חייב להביא בכורות ולא מעשר בהמה ומעשר שני והנה לא יביא בחיוב למשכן כלל ואפילו ברגלים לא נתחייב לבא שם וכן אחרי זריקת הדם והקטר החלב בשלמים יאכל אותם במדבר בכל מקום שירצה כי לא נתן בהם הכתוב מחיצה אבל אוכלים אותם במחנה וחוץ למחנה והנה אין להם בכל ענין הקרבנות חובה רק איש כל הישר בעיניו יעשה על כן צוה בכאן כי אחרי המנוחה והנחלה לא יעשו כן אבל יבואו בחובה למקום ידוע ומיוחד נבחר מהשם ויביאו שם הזבחים והמעשרות והבכורות ויאכלום שם במחיצה לפני השם ומה שאמרו רבותינו (ספרי טז) בדבר הנידר והנדב שקרב בבמה ושאין נידר ונדב שאינו קרב בבמה מדרש מיתור המקרא כמו שהוא מפורש בפרק בתרא דזבחים (קיז)
@365 **כי ירחיב ה' אלהיך את גבלך** . אין טעם הרחבה זאת כאותה שיאמר (להלן יט ח ט) ואם ירחיב ה' אלהיך את גבולך וגו' ויספת לך עוד שלש ערים על השלש האלה שאם כן לא היה בשר תאוה מותר בבואם לארץ אבל שם (להלן יט א) נאמר כי יכרית ה' אלהיך את הגוים אשר ה' אלהיך נותן לך את ארצם והם שבעה הגוים שיזכיר בכל מקום ואז נבדיל שלש ערים וכן עשה יהושע (יהושע כ) ואח"כ אמר כי ירחיב ה' אלהיך את גבולך כאשר נשבע לאבותיך וזה ירמוז לעשרה עממין שנתנו לאברהם אבל כאן אמר "כאשר דבר לך" והם הגוים האלה אשר ה' אלהיך נותן לך את ארצם כי מיד לאחר שכבשו וחלקו הותר להם בשר תאוה ואין טעם "כי ירחק ממך המקום" שיהיה מותר בהרחקת המקום בלבד שאם כן יהיו אסורים יושבי ירושלים בבשר תאוה אבל עם כל ישראל ידבר ויאמר להם כי כאשר ירחיב השם את גבולכם ולא תהיו כולכם יושבים סביב למשכן כאשר אתם היום במדבר יהיה לכם בשר החולין מותר כי א"א שתלכו כולכם ממקום רחוק אל המקום אשר יבחר ה' ותזבחו זבחים שלמים כל מה שתאכלו
@366 **וטעם וזבחת וגו' כאשר צויתיך** . על דעת רבותינו (חולין כח) כאשר צויתיך על פה מהלכה למשה מסיני מלמד שנצטוה משה על הושט ועל הקנה ועל רוב אחד בעוף ועל רוב שנים בבהמה ודע כי שחיטה בלשון הקדש הוא הכרת סימני הצואר ואל תחוש בעבור שאמר וישחטם במדבר (במדבר יד טז) כי היא מליצה שזבח אותם כצאן והנה צוה בקרבנות "ושחט" "ושחטו" שהוא בסימני הצואר והנה מתחלה צוה שיהיה כל מה שהם אוכלים שלמים והם שחוטים כמשפט הקרבנות ועתה כשבא להתיר בשר החולין אמר וזבחת מבקרך ומצאנך כאשר צויתיך בהיותם קרבנות ותאכל אותם חולין בכל תאות נפשך לומר שיתירם חולין בכל מקום ובלבד שיהיו זבוחין כאשר צוה מתחלה בהיותם כולם קרבנות וזהו פשוטו של מקרא זה על הנכון ושמא רבותינו נתכונו בזה כשאמרו בספרי (ראה לט) כאשר צויתיך מה קדשים בשחיטה אף חולין בשחיטה והנה מצות השחיטה מפורשת בכאן ומבוארת מדברי רבותינו בקבלה
@367 **אך כאשר יאכל את הצבי ואת האיל כן תאכלנו** . הוא כמו שיפרש הטמא והטהור יחדו כי מפני שצוה במדבר שלא יאכלו בקר וצאן רק בזבחי שלמים ומוזהר בהם כי הנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו ונכרתה אמר בכאן שיאכל בכל אות נפשו בחולין ושיאכלנו עם הטמא בקערה אחת כאשר הם אוכלין במדבר הצבי והאיל שאינו קרב על המזבח ואין הטעם ב"כצבי וכאיל" שיאכל חלב החולין כאשר יאכל חלב הצבי והאיל כי לא יזכיר רק האיכות כענין שאתם אוכלין הצבי והאיל תאכלו הבשר אשר תזבחו בכל מקום ולא אמר כל אשר יאכל בצבי ובאיל יאכל בו ולכך יפרש בכל מקום (להלן טו כב) הטמא והטהור יחדו (יאכלנו) כצבי וכאיל ולא אמר בשום מקום "יאכלנו כצבי וכאיל" בלבד כדי שלא יהא גם החלב בכלל וטעם "אך" אזהרה מפני כי מתחלה היה אסור לאכול רק השלמים השחוטין במשכן ועתה כשהתיר לשחוט ולאכול בשעריך ובכל אות נפשך יהיה במשמע שיאכל אפילו חולין וגם קדשים כאשר בראשונה שיקריבם שם בבמה ועל כן אמר והזהיר אך כאשר יאכל את הצבי ואת האיל כן תאכלנו שלא תקריב ממנו לא חלב ולא דם ולא תנהג בהם דרך קדשים ולא תזהיר מהם הטמאים כלל והוצרך להזכיר (בפסוק טז) רק הדם לא תאכלו מפני טעמים רבים כי מתחלה אמר באיסור הדם (ויקרא יז יא) ואני נתתיו לכם על המזבח לכפר על נפשותיכם והיה במשמע הזה שהדם שאינו מכפר בבהמה לא יאסר על כן הוצרך לאוסרו בביאור אבל בחלב לא הזכיר כן באיסורו ואין כל הקרב מן האימורין אסור ולא כל שאינו קרב מותר כאשר כתבתי במקומו (שם ג ט) ועוד כי כיון שצוה בכאן שנשחוט והזהיר שנאכל באיכות הצבי והאיל היה במשמע שנכסה הדם כאשר צונו בצבי והאיל (שם יז יג) ועל כל פנים הוצרך להתיר שנשפוך הדם כמים בלא כסוי וזה טעם "על הארץ" לא "בארץ" שיכסנו בעפר וכיון שהוצרך להזכיר היתר הדם הקדים לבאר איסורו ועוד נתירא הכתוב שלא ידונו בדם בעבור כי במדבר בעת שהיו כל בקרם וצאנם שלמים היה הבשר אסור עד שיזרוק הדם על המזבח כי כן הדין בקרבנות והנה הדם בהם מעכב אכילת הבשר וצוה מן הצבי והאיל בעבור שאינם קרבים שנכסה את דמם בעפר וכן מן העוף בעבור שאין העוף קרב לשלמים וא"כ היה מחוייב בבקר ובצאן של בשר תאוה שנכסה אותו או שנאכלנו עם הבשר בנחירה ולא יראה על פני השדה כי ראוי היה שיהא מותר לאכלו בפני עצמו ממה שישפכנו על הארץ שלא יזבחו את זבחיהם לשעירים אשר הם זונים אחריהם על כן אמר שיזבח הבקר והצאן ולא יאכל הדם עם הבשר בנחירה או באבר מן החי וישפוך הדם על הארץ ולא יחוש לו אבל לא יאכלנו לא בפני עצמו ולא עם הבשר ומן הטעם הזה הוצרך להזכיר כן פעם אחרת בבכור בעל מום (להלן טו כג) מפני שהיה הדם מתחילה למזבח והוצרך עתה לומר כשהוא בעל מום שלא ינהגו קדושה בדמו וגם לא היתר אבל ישפכנו כמים ולא יאכלנו והנראה בעיני בטעם הענין הזה כי מתחלה בהיותם במדבר ילל ישימון ושעירים ירקדו שם והיו כולם יוצאי מצרים הרגילים בהם אסר להראות הדם על פני השדה ולזבוח כלל רק לפני משכן ה' להרחיק אותם מן החטא ההוא אבל בבואם לארץ והוצרך להתיר בשר תאוה מפני ריחוק המקום לא חשש אם ישפך בביתם דם הבקר והצאן על הארץ אבל בדם החיה ועוף אשר יצוד בשדה וביער והמנהג לשחטם שם ולהביאם שחוטין אל הבית השאיר המצוה כאשר היתה לכסות דמם בעפר שלא יקריבנו לשעירים ומדרש רבותינו (ספרי מב) ב"רק חזק לבלתי אכל הדם" ו"לא תאכלנו למען ייטב לך" (פסוק כה) מדרש יפה ונאות ללשון הכתוב שהיו להוטין אחריו מאד על כן הוצרך לכל האזהרות האלה וכל שכן שהוצרך להזכיר איסורו אע"פ שלא הזכיר איסור החלב ובאמת שדבר רבותינו זה מספיק לטעם רבוי האזהרות שהכתוב מזהיר ממנו אבל הלשון שאמר "רק חזק לבלתי אכל הדם" אינו מתישב לי בכל זה כי מה חוזק ואומץ יש בהזהר מן הדם והראוי שיאמר לחומרו "השמר לך לבלתי אכול הדם" ומצינו לשון חוזק במצות שאמר הקב"ה ליהושע (יהושע א ז) רק חזק ואמץ מאד לשמור לעשות ככל התורה אשר צוך משה עבדי וכן אמר יהושע לישראל (שם כג ו) וחזקתם מאד לשמור ולעשות את כל הכתוב בספר תורת משה וזה במצות כולן ו"לשמור" ירמוז ללא תעשה ו"לעשות" ירמוז למצות עשה אבל במצוה אחת לא נמצא כן ומה צורך לחיזוק בשב ואל תעשה ממצות לא תעשה אחת אבל נראה לי כי הזכיר בה חיזוק מפני הענין אשר ממנו דבקו בדם במצרים כי היו זובחים את זבחיהם לשעירים תמיד כמו שכתוב (ויקרא יז ז) ולא יזבחו עוד את זבחיהם לשעירים אשר הם זונים אחריהם וכתיב (להלן לב יז) יזבחו לשדים לא אלוה והיתה העבודה ההיא באכילה מן הדם כי היו מקבצים הדם לשדים והם אוכלים עליו וממנו כאלו הם קרואים לשדים לאכול על שולחן השדים ההם ומתחברים עמהם וכבר הוזכר זה בספר מורה הנבוכים (ג מו) ולא שיהיה זה עיקר טעם איסור הדם כי הכתוב מפרש טעמו כי הדם הוא הנפש כאשר בסדר אחרי מות (ויקרא יז יא) אבל מזה היו שטופים בו ורודפין אחריו מאד והנה היו מתנבאים בו ומגידים עתידות ולכך בא הכתוב והזהיר שאם ישמע מאוכלי הדם דבר עתיד ובא האות והמופת אל יפתה לבבו אבל יחזיק בתומתו ובאמונת ה' ואל יאכל מן הדם בשום ענין ואל יכסה המעשה ההוא מדבריהם לא יירא ומפניהם לא יחת כי הבל המה מעשה תעתועים הזהיר בכאן כענין המוזהר בנביא השקר מפני הטעותיו
@373 **שמר ושמעת את כל הדברים האלה** . לא הזכיר בכאן "חקים ומשפטים" או "עדותיו ומצותיו" אבל אמר "את כל הדברים" להכניס בשמירה זו גם הטוב והישר כאשר פירשתי בסדר ואתחנן (לעיל ו יח)
@375 **השמר לך פן תנקש אחריהם אחרי השמדם מפניך** . אחר שתראה שאשמידם מפניך יש לתת לב מפני מה נשתמדו אלו מפני מעשים מקולקלים שבידיהם אף אתה לא תעשה כן שלא יבאו אחרים וישמידוך לשון רש"י ואם כן יהיה זה אזהרה והתראה מלעבוד ע"ז וכן כתב איכה יעבדו לפי שלא ענש על ע"ז אלא על זבוח וקטור ונסוך והשתחואה כמו שכתוב (שמות כב יט) בלתי לה' לבדו דברים הנעשים לגבוה בא ולמדך כאן שאם דרכה של ע"ז לעבדה בדבר אחר כגון פוער לפעור וזורק אבן למרקוליס שהיא עבודתו חייב וחייב על זבוח וקטור ונסוך והשתחואה אפילו שלא כדרכה עכ"ל וזה איננו נכון כי הכתוב אומר לא תעשה כן לה' אלהיך אם כן אינה אזהרה בעבודה לאלהיהם רק שלא לעבוד השם הנכבד בעבודתם כאשר נתן הטעם כי כל תועבת ה' אשר שנא עשו לאלהיהם וגו' אבל פירוש הפרשה כי עד הנה צוה פעמים רבות כי בבואנו אל הארץ נעקור ע"ז ומשמשיה ונאבד את שמם וצוה שנעשה זה מיד כאשר אנחנו יורשים אותם מיד ועתה אמר כי כאשר יכרית ה' הגוים ההם מפנינו וישתקע שם ע"ז מן הארץ ונשב בארצם לבטח לא נחשב בלבנו הנה הכרית השם מפנינו עובדי אלהים אחרים בעבור שהיו עושים כבוד בעבודה שלמה למעשה ידי אדם עץ ואבן ואין ראוי לתת כבודו לאחר ותהלתו לפסילים כי כן אסר זבוח וקטור ונסוך והשתחואה בלתי להשם לבדו והנהוג במלכים כי המתהדר בכבודם לתת עטרה בראשו או ללבוש לבוש מלכות כהם אחת דתו להמית אם כן אעשה אני לשם הנכבד כאשר היו עושים הגוים לאלהיהם וייטב לפניו לכן הזהיר לא תעשה כן כי הדברים המתועבים לפניו היו עושים לאלהיהם ולא אסרם מפני המעשה שהיה נכבד וראוי לעשותו לפני השם לבדו רק מפני הכונה שהיתה בהם לעבוד אלהות כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם שהוא דבר מתועב לפני השם לשפוך דם נקי ואף כי להיות אכזרי על פרי בטן לא ירחמו ועל כן אמר (להלן יג א) את כל הדבר אשר אנכי מצוה אתכם וגו' להזהיר על מעשה הקרבנות ועבודת המקדש שלא תוסיף עליו ולא תגרע ממנו וזה ענין הפרשה הזאת באמת אבל רבותינו (סנהדרין ס) שלמדו מכאן לעובד ע"ז כדרכה שחייב עליה לעולם אפילו פוער עצמו לפעור מפני שהזכיר הכתוב "איכה יעבדו" ללמד כי תקרא עבודה באיכות ההוא ויהיה בכלל ולא תעבדם (שמות כ ה) אבל אם יזרוק אבן לפעור או אפילו דרך כבוד שיחבק וינשק או שיכבד וירבץ לפניו אינו חייב מיתה ועל דרך הפשט הזהיר בראש הסדר (לעיל פסוק ד) "לא תעשון כן לה' אלהיכם" לעובדו כאלהי העמים על ההרים הרמים בקרבנותיו ועתה בפרשה הזאת הזהיר "לא תעשה כן לה' אלהיך" לעבדו במקדשו בעבודות שלהם
@378 (דברים יג ב): "כי יקום בקרבך נביא או חלם חלום" - יקראנו הכתוב "נביא" על פי עצמו, שיאמר הוא "השם דיבר עמי בהקיץ ואני נביאו שלוח לכם שתעשו כן".
@378 וייתכן שירמוז הכתוב למה שהוא אמת, כי בנפשות בקצת האנשים כח נבואיי ידעו בו עתידות, לא ידע האיש מאין יבא בו, אבל יתבודד ותבא בו רוח לאמר "ככה יהיה לעתיד לבא בדבר פלוני". ויקראו לו הפילוסופים "כהין", ולא ידעו סיבת הענין, אך הדבר נתאמת לעיני רואים. אולי הנפש, בהתבודדה, תדבק בשכל הנבדל ותתכוין בו. והאיש הזה יקרא "נביא" כי מתנבא הוא, ועל כן יבוא האות והמופת אשר יאמר אליך.
@378 "ונתן אליך אות או מופת" -
@378 ענין אות, סימן על דבר שיהיה אחרי כן בדמיונו, כענין שנאמר (במדבר ב ב): "איש על דגלו באותות", כי כשיבא הנביא ויאמר "דבר פלוני עתיד להיות" לדמיון שיהיה כך, ייקרא אות, כענין שנאמר (ישעיה ז יד): "לכן יתן אדני הוא לכם אות", שהאל עימנו, משם בן אשת הנביא. והמלה נגזרת מן (דברים לג ב): "אתה".
@378 והמופת ייאמר על דבר מחודש שיעשה לפנינו בשנוי טבעו של עולם, כענין שנאמר (דברי הימים ב לב לא): "לדרוש המופת אשר היה בארץ", (יואל ג ג): "ונתתי מופתים בשמים ובארץ דם ואש". והיא מלה מקוצרת מן "מופלאת", כמו (דברי הימים א יב לח): "שרית ישראל". וישאילהו הלשון לדבר שהוא חוץ מן המנהג, כמו שנאמר (יחזקאל כד כד): "והיה יחזקאל לכם למופת", ואמר (יחזקאל כד כז): "ותדבר ולא תאלם עוד והיית להם למופת", כי מעשיו פלא בעיני הרואים, כדרך (איכה א ט): "ותרד פלאים".
@378 וכן (דניאל ג לב): "אתיא ותמהיא... אתוהי כמה רברבין ותמהוהי כמה תקיפין", האותות והמופתים, כי הפלא והתימה ענין אחד.
@378 והיו ביציאת מצרים אותות, והם הדברים שיאמר להם מתחלה (שמות ח יט): "למחר יהיה האות הזה", והיו שם מופתים, שיעשו בחידוש בלי שיקדימו להודיע בו.
@378 וכן (ישעיה לח כב): "מה אות כי אעלה בית ה'", שיקדים להודיעו, ואמר באות ההוא בעצמו (דברי הימים ב לב לא): "לדרוש המופת אשר היה בארץ", לדעת החידוש ההוא איך נתחדש אצלם.
@378 וכן המטה אשר נהפך לנחש קראו (שמות ד יז): "אות" כאשר הודיע בו לבני ישראל, וקראו (שמות ד כא): "מופת" כאשר עשאו לפני פרעה לחידוש.
@378 וכן (ישעיה כ ג): "כאשר הלך עבדי ישעיהו ערום ויחף שלש שנים אות ומופת על מצרים ועל כוש", כי היה בדבר אות מגיד על מה שיאתה, ופלא במנהג שילך הנביא ככה.
@378 אם כן, "ונתן אליך אות או מופת" פירושו, שיאמר "אני הנביא השלוח אליכם שתעבדו עבודה זרה פלונית, וזה לכם האות, כי למחר יבא הארבה החסיל והגזם, או יתן להם מופת, שישליך לפניהם מטה ויהיה לתנין.
@378 ובספרי אמר: "אות הוא מופת ומופת הוא אות, אלא שדברה תורה בשתי לשונות". אולי כונתם לומר, שאין חלוק בין שניהם ואין הפרש בדינם, ודי היה להזכיר האחד, אלא שרצתה התורה להפליג בענין לומר כל אות ואות שיתן אליך, מכל אותות שבעולם.
@378 והאיש הזה שיקרא עצמו "נביא" ויצוה לעבוד עבודה זרה, על דרך הפשט נביא הע"ז הוא שיאמר "צלם פעור שלחני אליכם שהוא האלהים וצוה שתעבדוהו בכך וכך", והוא שאמר בו הכתוב עוד (דברים יח כ): "ואשר ידבר בשם אלהים אחרים ומת", כי כל מתנבא בשם אלהים אחרים לעבוד אותם יתנבא כי הם לו לאלהיו, והזכירו שם עם נביאי השקר.
@378 אבל העולה בזה מדברי רבותינו (סנהדרין צ א), כי זה הנביא הנזכר בכאן מתנבא בשם ה', יאמר "השם הנכבד שלחני שתעבדו לפעור כי היה השותף עמו במעשה בראשית, או שהוא גדול מכל האלהים לפניו ורוצה שיעבדו אליו". והם ז"ל הזכירו, כי אפילו יאמר שיעבדו לע"ז אפילו שעה אחת בלבד, כגון שיאמרו "עבדו לפעור היום הזה בלבד ותצליחו בדבר פלוני כי כן הרצון לפני השם הנכבד", הוא חייב מיתה, וגם זה הוא כפשוטו של מקרא.
@378 והנה, צוה הכתוב, שלא נשמע למתנבא בשם ה' לעבוד עבודה זרה כלל, ולא נביט באותות ובמופתים שיעשה, והזכיר הטעם, מפני שאנחנו ידענו מיציאת מצרים, שהוא מעשה ממש, לא חיזיון ולא מראה, כי לה' הארץ, והוא המחדש והחפץ והיכול ואין אלהים מלבדו, וידענו ממעמד הר סיני, כי הוא פנים בפנים ציווה אותנו ללכת בדרך הזה, שלא נעבוד לזולתו כלל, וכבודו לאחר לא ניתן, וזה טעם (דברים יג ו): "אשר צוך ה' אלהיך". והנה, "דבר סרה על ה'", שלא ציווהו ככה מעולם, או סרה דבר על כבודו, שאין ראוי לעבוד לאל אחר.
@380 (דברים יג ד): "כי מנסה ה' אלהיכם אתכם"- לאמור כי ענין המופת אשר בא והראהו השם לזה בחלומו או בכיהונו רצון האלהים היה בו לנסותכם באהבתו.
@380 וכבר פירשתי, כי הנסיון יקרא כן מצד המנוסה.
@380 ואמר "לדעת" - שייוודע בפועל מה שהוא בכח וגלוי לפניו.
@380 והנה, מצות כל הפרשה במתנבא לעבוד עבודה זרה, אבל במתנבא בשם ה' לשנות בדברי התורה, רבותינו דרשו בו (סנהדרין צ א), שאם בא לעקור דבר אחד מן התורה, כגון שיתיר החזיר או אחת מן העריות, כמשפט הזה יעשה לו. אבל אם יתיר זה לקצת הימים להוראת שעה, כגון אליהו בהר הכרמל, אנו חייבים לשמוע אליו ולעשות ככל אשר יצונו.
@380 ונראה, שאם יתנבא בשם ה' לצוות מצוה שיחדש, כגון שהיה במקרא מגלה (מגילה יד א), שאינו חייב מיתה, אלא שאין לנו לשמוע אליו, דכתיב (ויקרא כז לד): "אלה המצות", אין נביא רשאי לחדש בהם דבר מעתה. ואולי כיון שלא נאמין לו הנה הוא נביא השקר, ומיתתו בחנק.
@381 **אחרי ה' אלהיכם תלכו** . היא מצוה שנלך אחר עצתו וממנו לבדו נדרוש כל נעלם ונשאל כל עתיד כענין ותלך לדרוש את ה' (בראשית כה כב) כי יבא אלי העם לדרוש אלהים (שמות יח טו) וכן יעשו ישראל עם הנביאים האין פה נביא לה' ונדרשה את ה' מאותו (מלכים ב ג יא) ויגד לנו ה' אלהיך את הדרך אשר בה נלך ואת הדבר אשר נעשה (ירמיהו מב ג) ובספרי אחרי ה' אלהיכם זה ענן והוא מה שפירשנו שנשמע לקול אותותיו ונלך אחרי עצתו ואותו תיראו שתאמינו כי הוא אשר בידו נפש כל חי ובידו להמית ולהחיות ופוקד עון ומשלם שכר ואת מצותיו תשמרו תורת משה
@381 "ובקולו תשמעו" - לעשות כל מה שיצוה אותנו מלבד התורה כמו שאמר שמואל (שמואל א יג יג) נסכלת לא שמרת את מצות ה' והוא מה שפירש עוד (להלן יח טו) נביא מקרבך מאחיך כמוני יקים לך ה' אלהיך אליו תשמעון ואמר (שם פסוק יט) והיה האיש אשר לא ישמע אנכי אדרש מעמו שהוא חייב מיתה בידי שמים וכמו שבא במצות הנביא הכני ופצעני בדבר ה' (מ"א כ לה לז) וכן אמרו בספרי (ראה ס) ובקולו תשמעו בקול נביאיו
@381 "ואתו תעבדו ובו תדבקון" - כבר פירשתיו (לעיל ו יג יא כב) והנה כבר נאמר (לעיל ו יג) את ה' אלהיך תירא ואותו תעבוד אבל החזירו בכאן לשלול שלא נירא מדברי הנביא מפני האות והמופת ולא נעבור על עבודת ה' בעבור דבריו כי מן ה' לבדו נירא ולא מאל אחר ולהוסיף ובקולו תשמעו
@385 **לא תאבה לו** . לא תהא תאב לו ולא תאהבנו לפי שנאמר (ויקרא יט יח) ואהבת לרעך כמוך את זה לא תאהב לשון רש"י מספרי (ראה סז) אבל בגמרא (סנהדרין סא) אמרו הא אבה ושמע חייב וכן הדבר כי אבה לשון רצון ולא אבה ה' אלהיך לשמוע אל בלעם (להלן כג ו) לא רצה לא אבה יבמי (להלן כה ז) ממה שאמר (שם) ואם לא יחפץ והנה לא תאבה לו בלב ולא תשמע אליו שתודה לו לומר כן אעשה אלך ואעבוד עבודה זרה שאמרת והוא חייב מיתה בהודאתו וכן דעת אונקלוס לא תקבל מיניה ואלו הלאוין כמו ולא תתאוה ולא תחמוד (לעיל ה יח) שאם התאוה בלב עובר בלאו הראשון ואם הוסיף לעשות כאשר חשב עובר גם בלאו השני
@385 "ולא תחוס עינך עליו" - לרחם עליו שלא יומת ולא תחמל על הקורבה הנזכרת שיש לו עמך כענין שנאמר (מלאכי ג יז) כאשר יחמול איש על בנו העובד אותו
@385 "ולא תכסה עליו" - מהעיד עליו בב"ד ובספרי (ראה סח) לא תחמול לא תלמד עליו זכות ולא תכסה אם אתה יודע לו חובה אינך רשאי לשתוק והכל טעם אחד כי הכסוי מן מכסה פשעיו (משלי כח יג) וכוסה קלון (שם יב טז) השתיקה מהגיד ואמר ולא יוספו לעשות כדבר הרע הזה כי הוא דבר מצוי יעשה תמיד לולי המשפט אבל ענין הנביא הנזכר איננו בתדירות
@391 **ודרשת וחקרת ושאלת היטב** . הדרישה והחקירה מפורשין בדברי רבותינו (סנהדרין מ) והזכיר הכתוב זה בעיר הנדחת ובעובד ע"ז ולא הזכיר כן בנביא השקר ובמסית כי הנביא מפרסם עצמו באותותיו ובמופתיו ובמסית הכתוב ידבר עם המוסת "כי הרג תהרגנו" והוא היודע ועד כמו שאמר "ולא תחמול ולא תכסה עליו" אבל בעיר הנדחת ובעובד ע"ז שהם מעשים מגיעים אלינו בשמועה הזכיר בהם דרישה וחקירה ולא הוצרך להזכיר כן בשאר חייבי מיתות כי מקל וחומר יודע הדבר ואמר בעדים זוממים (להלן יט יח) ודרשו השופטים היטב בעבור שלא יודע מי משתי הכתות יאמר האמת בלתי אחר חקירה רבה ולענין הדין כלן למדין זה מזה בגזירה שוה ומכלם יצאו לנו שבע חקירות ובדיקות
@392 **החרם אתה ואת כל אשר בה** . אותה הם אנשים הנדחים ואת כל אשר בה הנשים הנגררות אחר האנשים אבל הטף שהם קטנים בזכרים ובנקבות אין ממיתין אותן וכן אמרו בספרי חנן אומר לא יומתו אבות על בנים וגו' בעיר הנדחת הכתוב מדבר אבל בתוספתא של מסכת סנהדרין (פי"ד ה"א) נחלקו בה קטני בני אנשי עיר הנדחת שהודחו עמה אין נהרגין רבי אליעזר אומר נהרגין אמר לו רבי עקיבא מה אני מקיים ונתן לך רחמים ורחמך והרבך (פסוק יח) אם לרחם על הגדולים הרי כבר נאמר החרם אותה ואת כל אשר בה ואת בהמתה ומה אני מקיים ורחמך והרבך אלו קטנים שבתוכה וכו' והנה כל אלו המצות ביאור מה שנאמר בתורה (שמות כב יט) זובח לאלהים יחרם ועתה ביאר החרם מהו במדיחים ובעובדים
@396 **בנים אתם לה' אלהיכם** . גם זו מצוה מבוארת שאמר בתורה (ויקרא כא ה) בכהנים לא יקרחו קרחה בראשם ובבשרם לא ישרטו שרטת ועתה יבאר כי לא בעבור מעלת הכהנים בלבד שהזכיר שם שהם קדושים לאלהיהם צוה בהם זה אבל כל העדה כלם קדושים וכלכם בנים לה' אלהיכם כמו הכהנים אם כן השמרו גם אתם במצוה הזאת כמותם ועל דעת רבותינו בשניהם אינה אלא על המת ויתכן שהיתה המצוה הראשונה בכהנים לאמר שאם היה הכהן מקורח ומגודד איננו ראוי לעבודה כמו שאמר (שם פסוק ו) ולא יחללו שם אלהיהם והנה עבודתם מחוללת וכאן ביאר כי המצוה גם לישראל והוצרכו לשתיהם ורש"י כתב לפי שאתם בניו של מקום אתם ראויים להיות נאים ולא גדודים ומקורחים ואיננו נכון שאם כן תהיה המצוה גם שלא על המת ור"א אמר אחר שתדעו שאתם בנים לה' והוא אוהב אתכם יותר מן האב לבנו לא תתגודדו על כל מה שיעשה כי כל מה שיעשה לטוב הוא ואם לא תבינוהו כאשר לא יבינו הבנים הקטנים מעשה אביהם רק יסמכו עליו כי עם קדוש אתה ואינך כשאר כל הגוים על כן לא תעשה כמעשיהם ולפי דעתי כי טעם "עם קדוש" הבטחה בקיום הנפשות לפניו יתברך יאמר אחרי שאתה עם קדוש וסגלת ה' ולא ישא אלהים נפש וחשב מחשבות לבלתי ידח ממנו נדח אין ראוי לכם להתגודד ולהקרח על נפש ואפילו ימות בנוער ולא יאסור הכתוב הבכי כי הטבע יתעורר לבכות בפירוד האוהבים ונדודם אף בחיים ומכאן סמך לרבותינו (מו"ק כז) באסרם להתאבל על נפש יותר מדאי
@398 **לא תאכל כל תועבה** . הנה רצה להוסיף ביאור במאכלים האסורים ולכך אמר "לא תאכל כל תועבה" להגיד כי כל הנאסרים נתעבים לנפש הטהורה וענין כל תיעוב שנאה ומיאוס כענין כי נתעב דבר המלך (דהי"א כא ו) כל אכל תתעב נפשם (תהלים קז יח) כי המאכלים האסורים גסים יולידו עובי ואטימות בנפש כאשר הזכרתי במקומו (שמות כב ל) ועל כן אמר עוד (פסוק כ) כל עוף טהור תאכלו להגיד כי אלה אשר אסר נתעבים והשאר טהורים וראויים לנפש טהורה ובספרי אמרו רבי שמעון אומר כל עוף טהור תאכלו אלו חגבים טהורים וכל שרץ העוף (פסוק יט) אלו חגבים טמאים ויפה אמר והנה טעם הכתוב כי הזכיר לאסור כל שרץ העוף והם ההולכים על ארבע וחזר ואמר כל עוף טהור תאכלו להתיר מהם אשר לו כרעים ממעל לרגליו הארבה והסלעם והחרגול והחגב ולא הוצרך לפרש זה שכבר הוזכר (ויקרא יא כא כב) אבל הזכיר בכלל דרך קצרה כל עוף טהור תאכלו כלומר אלו הנזכרים מאכלים נתעבים ושאר העופות למיניהם למרביתם תאכלו מהם כל טהור שלא אסרתיו והנה כלל כל הנאסרים לנו שהם כלם תועבה ולא הוצרך לפרוט אחרי כן השרצים וכל הרמש כי דבר ידוע הוא שתתעב אותם נפש כל נקי דעת אבל הזכיר סימני הבהמה והחיה והדגים והעופות והנבלה להודיעך שגם הם מתועבים לנפש ולא הזכיר הטרפה שאיננה תועבה אבל נאסרה מפני הארס או החולי הממית שלא יזיק באוכליו ולרבותינו עוד מדרשים (חולין סג) למה נשנו בבהמה מפני השסועה ובעופות מפני הראה ועוד מדרש (ספרי צח קידושין נז) בכל צפור טהורה תאכלו להתיר משולחת של מצורע וזה אשר לא תאכלו מהם לאסור את השחוטה קבלו כן לרמוז ב"כל צפור טהורה" שהצפור שלא קבלה טומאה מותרת וטומאת המצורע לא תדבק בחיה שאין בעלי חיים בבהמה ובעוף מקבלים טומאה בנוגעם במת או בשרץ אבל השחוטה שראויה לקבל טומאה ידבק בה רוח הטומאה הפורחת מן המצורע ואיננה טהורה והיא בכלל תועבה כי אכילתה נתעבת
@416 **וטעם כי עם קדוש אתה לה' אלהיך** . דבק עם לא תבשל גדי בחלב אמו כי איננו מאכל נתעב אבל יאסור אותו להיותנו קדושים במאכלים או להיותנו קדושים שלא נהיה עם אכזרי לא ירחמו שנחלוב את האם ונוציא ממנה החלב שנבשל בו הבן ואף על פי שכל בשר בחלב יכנס בלאו הזה כי כל מינקת תקרא אם וכל יונק יקרא גדי והוא דרך הבישול והנה בכולם אכזריות וכתב רש"י לא תבשל גדי בחלב אמו שלשה פעמים פרט לחיה ולעופות ולבהמה טמאה והמדרש הזה הוציאו אותו (ספרי קג וחולין קיג) ממלת גדי אבל הלאו עצמו אחד לאיסור אכילה ואחד לאיסור הנאה ואחד לאיסור בישול וכן כתב הרב בסדר ואלה המשפטים (שמות כג יט)
@417 **עשר תעשר** . גם זו מצוה שיבאר כי אמר (ויקרא כז ל) וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא קדש לה' ואמר (שם פסוק לא) ואם גאל יגאל איש ממעשרו חמשיתו יוסף עליו ואין זה מעשר הלוים כי בו נאמר (במדבר יח לא) ואכלתם אותו בכל מקום והוא חולין ומה טעם לפדיונו ועתה באר כי הוא יחייב לעשר כל תבואת זרעך שיאכל אותו הוא עצמו ובניו לפני השם למען תלמד ליראה את השם כי הכהנים והשופטים העומדים שם לפני השם מורי התורה ילמדוהו יראתו ויורוהו התורה והמצות ופירש בטעם הפדיון אשר הזכיר שם בעבור כי לפעמים יהיה המעשר הרבה כי יברכך השם והדרך יהיה רב ממנו וטוב לפדותו בכסף ולהעלות שם כסף הפדיון ולא הזכיר החומש שכבר הוזכר וטעם היוצא השדה וכל היוצא השדה כאשר אמר מזרע הארץ מפרי העץ וטעמו היוצא מן השדה ואין הכונה ב"כל תבואת זרעך" שיעשר כל התבואה מכל אשר זרע ולא כל היוצא מן השדה שנה שנה אבל טעם הכתוב שיעשר במינים המחוייבים במעשר כל תבואתו וכל היוצא בהן מן השדה יזהיר שלא יעשר מן הבא בידו מהם המקצת ויפטור לו המקצת אבל יעשר בין המדות שזרע בין הנתוסף עליהם הכל באמונה ואחר כך (פסוק כג) הזכיר המינים המחוייבים להתעשר מעשר דגנך ותירשך ויצהרך וכן יזכיר בכל מקום (לעיל יב יז) לא תוכל לאכל בשעריך מעשר דגנך ותירשך ויצהרך וגו' וכן אמר בפרשת מתנות כהונה (במדבר יח יב) כל חלב יצהר וכל חלב תירוש ודגן ראשיתם אשר יתנו לה' כי אלו בלבד הם החייבים בתרומה ובמעשרות מן התורה וכן מה שאמר הכתוב (ויקרא כז ל) וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא לא יצוה שיעשר כל זרע הארץ וכל פרי העץ אבל טעמו כל אשר תעשר מזרע הארץ שהוא דגן ומפרי העץ שהוא תירוש ויצהר יהיה לה' וכלשון הזה כתב רש"י (שם) מזרע הארץ דגן ופרי העץ תירוש ויצהר ויקצר הכתוב שם כי איננו מקום המצוה לחייב שיעשר אבל הוא מצוה שיהיה המעשר קדש לה' עד שיפדה בתוספת חומש אבל המצוה בתרומות ומעשרות בכל מקום הן דגן תירוש ויצהר ופירוש דגן בלשון הקדש חמשת המינין הידועין בתבואה ופירוש תירוש היין החדש אשר ישיקו היקבים ויצהר השמן אשר בהן ואין מין אחר בכל הזרעין ובכל פירות האילן חייבין מן התורה כלל לא בתרומות ולא במעשרות ויש ברייתות שנויות בתורת כהנים (בחקותי פרק יב ט) ובספרי (ראה קה) לאסמכתות והן מוטעות אבל הדבר המתבאר בגמרא מן התלמוד הבבלי (ברכות לו) והירושלמי (חלה פ"ד ה"ד) ופשוטו של מקרא כך הוא שאפילו זיתים וענבים מעשר שלהם אינו מן התורה עד שיעשו תירוש ויצהר ותהיה בזה נזהר שכבר טעו בו מגדולי המחברים (עי' רמב"ם הלכות תרומות פ"ב ה"א) וטעם שנה שנה שיעשר אותו שתי שנים זו אחר זו כן קבלת רבותינו (ר"ה יב) ואחר כך (פסוק כח) פירש כי מקצה השלש שנים תוציא מעשר תבואתך של השנה ההיא ותאכילהו לעניים לומר כי השנה השלישית של מעשר עני הוא ואמר תוציא וגו' והנחת בשעריך ללמד על הביעור ושוב יבאר אותו בפרשת כי תכלה לעשר (להלן כו יב) ומדרש חכמים (בתנחומא ראה יח) בלשון עשר תעשר עשר בשביל שתתעשר עשר שלא תתחסר רמז למפרשי ימים להוציא אחד מעשרה לעמלי תורה
@425 **מקץ שבע שנים תעשה שמטה** . הנכון בעיני שיזהיר על שנת השבע עצמה שנעשה אותה שמטה בחריש ובקציר כמו שאמר (שמות כג יא) והשביעית תשמטנה ונטשתה וזה טעם "תעשה שמטה" שתשבות כדרך לעשות את יום השבת (לעיל ה טו) וקצר באסור הזריעה והזמירה שכבר הזכירם בביאור (ויקרא כה ד) אבל הוסיף לבאר כי היא שמטה לה' גם בהשמט כספים וזה טעם כי קרא שמטה לה' שהיא שבת לה' וכל המעשים ישבותו וכבר רמזתי סודה (שם שם ב) וטעם "מקץ" אמר ר"א בתחלת השנה וכן אמרו המדקדקים כלם כי הראש והסוף יקראו קצה שכל דבר יש לו שתי קצוות וכענין שכתוב מן הקצה אל הקצה (שמות כו כח) על שני קצותיו (שם כה יט) על ארבע קצותיו (שם כז ד) ואין דבריהם נכונים אצלי כי ראש שבע שנים הוא השנה הראשונה והוא הקצה שנקרא בהם ראש ואלו אמר הכתוב "מקץ השנה השביעית" היה דברם נכון ועל דעת רבותינו (ספרי קכב) "מקץ" בסוף השבע ולא ידבר הכתוב אלא בשמיטת כספים יאמר מסוף כל שבע שנים הנמנים לכם תעשו שמטה שישמוט כל בעל משה ידו ולכך אמרו (ערכין כח) שאין שביעית משמטת אלא בסופה וכן לדעתם (שם) מקץ שבע שנים במועד שנת השמטה בחג הסכות בסוף השבע אלא שהקץ הנזכר בכאן הוא מיד והקץ הנזכר שם מופלג שהרי פירש במועד שנת השמטה בחג הסכות והנה טעם שניהם "מתכלית" יאמר בכאן מתכלית שבע שנים תעשה שמטה ושם יאמר בו גם כן כאשר תכלינה שבע שנים במועד שנת השמטה תעשה הקהל ועל דרך הפשט יראה לי כי לשון הכתוב כפשוטו הוא ברור ומתוקן כי קץ הוא סוף וכן תרגומו והמספרים וכל דבר יש להן ראש וסוף וראשם וסופם בהם ותאמר בעשרות כי האחד ראש המספר והעשירי סופו אם כן "קץ שבע שנים" שנת השבע שהוא סוף המספר ההוא ובשמטת הארץ הכתוב מדבר כאשר פירשתי למעלה וטעם "מקץ" כמו כרוב אחד מקצה מזה וכרוב אחד מקצה מזה (שמות כה יט) והנה הוא כמו בקץ שבע שנים תעשה שתשבות בו וכן מקץ שבע שנים תשלחו איש את אחיו העברי אשר ימכר לך ועבדך שש שנים (ירמיהו לד יד) פירושו בשנה השביעית שהוא סוף המספר והוא דומה לכתוב שבתורה (שמות כא ב) ובשביעית יצא לחפשי חנם וכן ובשנה השביעית תשלחנו חפשי מעמך (להלן פסוק יב) כי בעבור שאמר "ועבדך שש שנים" לא הוצרך לפרש רק כי בשנת השביעית יפטר והנה על דרך הזה היה נראה כי פירוש הכתוב האחר מקץ שבע שנים במועד שנת השמטה בחג הסוכות שיהיה כמו כן בשנת הקץ בחג הסוכות בראש אותו השנה שנאסרו בה לחרוש ולזרוע שהיא שנת השמטה אבל לא נוכל לומר כן כי רבותינו (סוטה מא) קבלו וראו שהיה ההקהל בחג הסוכות של השנה השמינית היא השנה שאחר השמטה ועל כן אמרו המפרשים כי פירוש "במועד שנת השמטה" במועד השנה הראשונה של מנין השמטה וזה איננו נכון כי לא תקרא בכתוב "שנת השמטה" רק שנת השבתון השנה ההיא שהיא שמטה לה' וכן "שנת היובל" ורבותינו עצמם דקדקו בכך שאמרו (ערכין כד) מי כתיב בשנת היובל משנת היובל כתיב שנה שאחר היובל אבל כך אני אומר כי הקץ והסוף יאמרו בכתוב על אחרית כל דבר ופעמים הם בו ופעמים אחריו חוץ ממנו ומקצה אחיו (בראשית מז ב) מקצה בחוברת (שמות כו ד) ומקצתם יעמדו לפני המלך (דניאל א ה) מקצות כנפיו ועד קצות כנפיו (מלכים א ו כד) כלם אחרית בדבר המחבר ממנו והוא בתוכו קץ כל בשר בא לפני (בראשית ו יג) ובא עד קצו ואין עוזר לו (דניאל יא מה) בא הקץ (יחזקאל ז ב) קץ בא (שם פסוק ו) כלם תכלית הדבר הנזכר והוא אחריו שנקצץ ונחתך וכן הענין בלשון הסוף טוב ללכת אל בית אבל וגו' באשר הוא סוף כל האדם (קהלת ז ב) אחריו שכבר מת ספו תמו מן בלהות (תהלים עג יט) את המעשה אשר עשה האלהים מראש ועד סוף (קהלת ג יא) במעשה עצמו ובלשונם (ב"ב יג) כדי עמוד בתחילתו וכדי היקף בסופו ויהיה פירוש הכתוב מתכלית שבע שנים בחשבון שנת השמטה בחג הסוכות הבא אחר השבע תעשה הקהל ושלא יראה להם שיהיו שבע שנים למנין אחר הזכיר שיהיו השבע בזמן השמטה וכן כי אקח מועד (תהלים עה ג) זמן וכן כל המועדים זמנים והנה הקץ הזה אחרי המספר כאשר פירש "בחג הסוכות" ו"מקץ שבע שנים תעשה שמטה" מכלל המספר ולא הוצרך להאריך ולבאר זה שכבר פירש ששנת השבע היא שנת השמטה ויהיה קץ רחב בשמטת כל השנה כמו שפירשתי על דרך הפשט ויתכן לומר כי הכתוב מונה תחלת שנה מחג הסוכות כמו שאמר (שמות לד כב) וחג האסיף תקופת השנה ואמר (שם כג טז) וחג האסיף בצאת השנה וא"כ יהיה "מקץ שבע שנים" בסוף וחוץ ממנו בסמוך ואמר "במועד שנת השמטה" להיות חשבון השבע בשמטות כמו שפירשתי לא שתגיע השמטה עד החג הזה וראיתי לאחד מן המחברים שכתב מלמד שמוסיפים מחול על הקדש והשמטה היתה נוהגת עד חג הסוכות של שנה שמינית וזה דבר מוכרח בתלמוד (ר"ה יב) בראיות ברורות שאיננו אמת ואפשר לומר כי מה שאמרו רבותינו ב"מקץ שבע שנים תעשה שמטה" שאין משמטת כספים אלא בסופה שהוא מדרש מפני שלא אמר "השנה השביעית תעשה שמטה" ירמוז כי בסוף השבע תעשה שמטה יותר מן ההתחלה ורצונם בקץ הזה חוץ ממנו ויכול אדם לתבוע חובו ביום האחרון של שנת השמטה ולא תשמט עד הלילה שכך מצינו בתוספתא (שביעית ח יא) שכותבין פרוזבול ערב ר"ה של מוצאי שביעית
@427 **את הנכרי תגש** . זו מצות עשה לשון רש"י מספרי (ראה קל) ופירושו מצות עשה באחיך הנכרי תגוש ולא אחיך ולאו שבא מכלל עשה עשה ולפי ששנינו שם (ספרי קכט) לא יגוש ליתן עליו לא תעשה חזרו ושנו את הנכרי תגוש זו מצות עשה לומר שעובר עליו בעשה ולא תעשה וכך אמרו שם (ספרי תצא קכט) לנכרי תשיך (להלן כג כא) מצות עשה ולאחיך לא תשיך זו מצות לא תעשה והוא כמו שפירשנו מצות עשה באחיך וכך פירש שם רש"י לא שיהיה מצוה להלוות לנכרי ברבית כלל וכן מוכח בגמרא בפרק איזהו נשך (ב"מ ע) והרב רבי משה (הל' מלוה ולוה פ"א ה"ב ושם פ"ה ה"א) עשאן שתיהן מצות ממש לנגוש את הנכרי ולהלוותו ברבית טעה בלשון הזה השנוי בספרי ושם הוא מורגל במקומות רבים כל עוף טהור תאכלו מצות עשה כל שרץ העוף מצות לא תעשה וכן הזכירו בספרא (שמיני פרשה ג א) ובספרי (ראה צו) זאת הבהמה אשר תאכלו מצות עשה ודבר ברור הוא
@435 **כי לא יחדל אביון מקרב הארץ** . מפרשים אמרו שלא יחדל האביון מקרב הארץ באחד מכל הזמנים כי לעולם יהיה אביון בארץ שגלוי היה לפניו שלא יעשו מה שאמר להם כי לא יהיה בך אביון אם שמוע תשמע בקול ה' אלהיך לשמור לעשות את כל המצוה ואינו נכון לדעתי כי התורה תרמוז במה שעתיד להיות אבל לא יתנבא עליהם בפירוש שלא יקיימו התורה ויצוה המצוה לעולם וחלילה רק בדרך אזהרה יזכיר הדבר והנכון שיאמר שלא יחדל אביון שיהיה נמנע ולא ימצא עוד לעולם והזכיר זה בעבור שהבטיח שלא יהיה בהם אביון בשמרם כל המצוה אמר אבל ידעתי כי לא יהיו כל הדורות כל ימי עולם כלם שומרים כל המצוה עד שלא נצטרך כלל לצוות על האביון כי אולי בקצת הימים ימצא אביון ואני מצוך עליו אם ימצא ואמר "מקרב הארץ" לרמוז על כל הישוב כי ההבטחה שלא יהיה בנו אביון בארץ אשר ה' אלהינו נותן לנו נחלה אם נקיים שם כל המצות ועתה אמר כי יתכן שימצא אביון באחד מן הזמנים ובאחד מן המקומות אשר תשב בה כי טעם "בארצך" כטעם בכל מושבותיכם (במדבר לה כט) בארץ ובחוצה לארץ וטעם ולאביונך בארצך כאומר לאחיך העני ולכל אביוני ארצך כי בעבור שהמצוה לישראל יזכיר אחיך ויצטרך לפרש אחיך וכל אביוני ארצך לצוות על כלל ישראל ומדרשו (ספרי קמב) להקדים הקודם
@448 **שמור את חדש האביב** . מצות הרגלים מבוארת כי כבר הזכירה (ויקרא כג במדבר כח כט) והנה בתורת כהנים הזכיר בה ענין הקרבנות והקרבתם אשה לה' וכאן לא יזכירם כלל אבל יזהיר את ישראל לעלות בהם אל המקום אשר יבחר ולשמוח לפניו כי כאשר צוה שיביא מעשר שני לפני ה' וכן הבכור ויאכלם שם במקום אשר יבחר ה' הוסיף לבאר כי עוד חייבין שיבואו כלם לפני השם ויחגו לפניו בשלשה רגלים ולשמוח בשלמים שיקריבו לפניו ולא הזכיר זמני חג המצות והסוכות באי זה יום יהיה אך הזכיר חדשיהם דרך קצרה שכבר הזכיר הכל שם
@449 **וטעם וזבחת פסח לה' אלהיך צאן ובקר** . על דרך הפשט כמו שור שה כשבים (לעיל יד ד) ראובן שמעון לוי (שמות א ב) ואמר וזבחת פסח לה' אלהיך וצאן ובקר לכך לא אמר וזבחת פסח לה' אלהיך מן הצאן ומן הבקר כאשר יאמר בכל מקום מן הבקר ומן הצאן תקריבו את קרבנכם (ויקרא א ב) ואם מן הצאן קרבנו (שם פסוק י) אם מן הבקר הוא מקריב (שם ג א) אבל יצוה בכאן בפסח והוא השה שהזכיר כבר וצאן ובקר אילים ועזים ובני בקר לחוג חגיגה ביום הזה כאשר יצוה בשבועות ובסוכות שיאמר (פסוק י) ועשית חג שבעות לה' אלהיך מסת נדבת ידך שיביא בקר וצאן לשלמים כאשר תשיג ידו וכן אמר בסוכות (פסוק טו) שבעת ימים תחג לה' אלהיך וגו' ובסוף כלל את שלשתם ודומה לזה בראשון בארבעה עשר יום לחדש יהיה לכם הפסח חג שבועות ימים מצות יאכל (יחזקאל מה כא) ופירש בחג שבעת ימים וכן מצינו בפסח יאשיהו שאמר (דהי"ב לה ז) צאן כבשים ובני עזים הכל לפסחים ובקר שלשת אלפים ואחר כן אמר (שם פסוק יג) ויבשלו הפסח באש כמשפט והקדשים בשלו בסירות ובדודים ובצלחות ויריצו לכל בני העם הנה פירש כי כבשים ובני עזים הכל לפסחים לא עזים עצמן ולא בקר כדכתיב (שמות יב ה) שה תמים זכר בן שנה יהיה לכם מן הכבשים ומן העזים ופירש כי הבקר אשר הזכיר היו שלשת אלפים והיו קדשים אשר בסירות להריץ לפני העם לאכול לשבעה כענין החגיגה שקבלו רבותינו (פסחים ע) ואונקלוס עשה צאן דבק עם הפסח ולא יתקשר הוי"ו יפה במלת ובקר ועוד כי אין כל הצאן כשר לפסחים והנכון מה שאמרנו ובאר בכאן דברים רבים כי הזכיר במצה שתהיה לחם עני להגיד כי צוה לזכור שיצאו בחפזון והיא עני זכר כי היו במצרים בלחם צר ומים לחץ והנה תרמוז לשני דברים וכן אמרו הא לחמא עניא די אכלו אבהתנא בארעא דמצרים או יאמר שתהיה עוד עשויה כלחם עני ולא שתהיה מצה עשירה כמו שהזכירו רבותינו (פסחים לו) ובאר במצות השאור שלא יראה בכל גבולך כי בתחלה אמר (שמות יב יט) לא ימצא בבתיכם
@451 **וטעם אשר תזבח בערב ביום הראשון** . שלא ילין לבקר מן הבשר שעשית אותו זבח בערב יום הראשון שבשבעת הימים הנזכרים והוא הלילה כמו שהזכיר (פסוק א) הוציאך ה' אלהיך ממצרים לילה כי לא הזכיר בפרשה הזאת יום ארבעה עשר ושחיטת הפסח כלל אבל הזכיר עשיית הפסח בלילה כלומר אכילתו ואכילת המצה עליו והטעם כי זביחת הפסח והקרבתו ביום ארבעה עשר היא מצות הקרבנות והזכיר אותה בתורת הקרבנות (ויקרא כג ה) ולא החזירה כאן כאשר לא החזיר מצות שאר הקרבנות וגם בשלשת הרגלים לא הזכיר כאן שנקריב בהם אשה אבל על אכילת הפסח והמצה הזכיר כאן לישראל וכן שם תזבח את הפסח בערב כבוא השמש (פסוק ו) שם תעשה זבח הפסח בערב בשקוע החמה כי בלילה יאכל ואמר לבאר זה (פסוק ז) ובשלת ואכלת במקום אשר יבחר ה' ופנית בבקר וכבר פירשתי זה בפרשת החדש הזה לכם ראש חדשים (שמות יב ו) ויתכן עוד שנפרש ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר מן הבשר אשר זבחת בערב והוא הערב הקודם לבקר שהוא ביום ארבעה עשר ואמר שם תזבח את הפסח בערב ו כבא השמש מועד צאתך ממצרים ובשלת ואכלת אותו והזכיר סתם "ובשלת" כי כבר פירש שם (שם שם ח ט) צלי אש ולא בשל מבושל במים אם כן ובשלת באש כמשפט
@455 **וביום השביעי עצרת לה' אלהיך לא תעשה מלאכה** . ולא הזכיר היום הראשון באיסור המלאכה וכן לא הזכיר בחג השבועות איסור מלאכת עבודה ולא בסוכות ולא הזכיר מצות הלולב וכן לא הזכיר כאן יום הזכרון ובעשור לחדש והטעם כאשר פירשתי (בפסוק א) כי לא בא עתה רק להזכיר הראיה והשמחה שחייבין כל ישראל ללכת בשלש הרגלים האלה אל המקום אשר יבחר ה' ולחוג שם איש כמתנת ידו כברכת השם אשר נתן לו לשמוח לפניו להודות על כל הטובה אשר גמלנו כרחמיו וכרוב חסדיו והוסיף וביום השביעי עצרת וטעמו ששת ימים תאכל מצות והשביעי עוד עליהם עצרת והטעם שתהיו עוד נעצרים לפניו לאכול המצות ובעבור שאמר עצרת היא ויהיה במשמע להיות נעצר על אכילת המצות בלבד כימים אשר לפניו הוצרך להזהיר שלא תעשה מלאכה וכן אמר בשמיני של חג הסוכות בפרשת המועדות שבתורת כהנים (ויקרא כג לו) שבעת ימים תקריבו אשה לה' ביום השמיני מקרא קדש והקרבתם אשה לה' עצרת היא כל מלאכת עבודה לא תעשו לומר שהוא נעצר על הימים הראשונים בהקרבת האשה והוא אסור עוד בעשיית מלאכת עבודה ועל דרך האמת עצרת היא כנסת ישראל ובא ללמדנו סוד היום אבל איננו שוה לעצרת של שמיני כי השמיני רגל בפני עצמו והקרבן של כנסת ישראל ואיננו כקרבנות של שבעת הימים אבל שביעי של פסח הוא מכלל הרגל ועצרת כי לפעמים תמנה שמינית ולפעמים תהיה בכלל והנה היא כשבת שיש בה זכור ושמור כבוד יום וכבוד לילה והקרבן בשביעי מכלל הרגל ועל כן אמר כאן עצרת לה' אלהיך לא תעשה מלאכה ושם אמר והקרבתם אשה לה' עצרת היא כי האשה עצרת ולכך היא סעודה קטנה והמשכיל יבין ולא הזכיר כאן השמיני של חג שכבר הוזכר ואיננו חייב שנעלה בו לרגל פעם אחרת
@456 **מהחל חרמש בקמה** . טעמו מהחל לכם חרמש בקמה כי כבר הזכיר מתי נתחיל להניף חרמש בקמה בעומר שהיא ראשית קצירנו ומדרשו (ספרי קפו) ללמד על העומר שלא תהא קצירתו אלא בחרמש
@458 **במקום אשר יבחר ה' לשכן שמו שם** . וכן אמר (פסוק טז) שלוש פעמים בשנה יראה כל זכורך וגו' במקום אשר יבחר ולא ידעתי אם לומר כי לאחר שיבנה בית המקדש לא נאסף להקריב קרבנות הרגלים אלא במקום ההוא אשר יבחר ה' כטעם שיאמר (פסוק ה) לא תוכל לזבוח את הפסח באחד שעריך או שיבאר כאן שלא יתחייבו לעלות לרגל עד אשר יבחר השם מקום לשכנו שם
@459 **וזכרת כי עבד היית במצרים** . אמר ר"א שהוא דבק עם ועבדך ואמתך והנכון שהוא כפשוטו שתשמור החקים האלה אשר צוך האדון הפודך מבית עבדים וכן נזכיר בקדוש היום הזה זכר ליציאת מצרים ואמר החקים האלה בחג השבועות בעבור שלא נתפרש בתורה טעם מספר שבעה השבועות ומספר החמשים יום והוא לבדו העצרת וכבר הזכרתי סודם (ויקרא כג טו) צוה בתורה עד האלהים יבא דבר שניהם (שמות כב ח) ונתן בפלילים (שם כא כב) אם כן מצוה שיהיו לישראל פלילים וביאר בכאן שישימו השופטים בכל עריהם כאשר יתן להם השם את הארץ כי בחוצה לארץ אינם חייבים למנות להם ב"ד אבל כאשר יצעק המעוות יעמדו עליו הראויים לשפוט ובמשפטיהם ישפטוהו או יעלה לארץ בזמנה ושם ישפטוהו במקום המשפט והוסיף בכאן שוטרים והם שיהיו נוגשים בדבר המשפט ולפי זה אין ישראל שבחוצה לארץ מצווים למנות להם דיינין בעיירות וכן כתב הרב ר' משה (הל' סנהדרין פ"א ה"ב) אבל במסכת מכות (ז) שנו והיו אלה לכם לחוקת משפט לדורותיכם בכל מושבותיכם מלמד שסנהדרין נוהגת בארץ ובחוצה לארץ אם כן למה נאמר שופטים ושוטרים תתן לך בכל שעריך אלא בארץ אתה מושיב בכל פלך ופלך ובכל עיר ועיר בחוצה לארץ אתה מושיב בכל פלך ופלך ואי אתה מושיב בכל עיר ועיר ונראה מזה שחייבין למנות סנהדרין בחוצה לארץ ולא בכל עיר ועיר כארץ ישראל אלא פלכים פלכים אם כן המצוה הזאת נוהגת בכל זמן בדיני ממונות ובדברים הנדונין בחוצה לארץ אבל בזמן הזה לאחר שבטלה הסמיכה כיון שכל המשפטים בטלים מן התורה דכתיב לפניהם ולא לפני הדיוטות ואנן הדיוטות אנן ואין דיינין בחוצה לארץ אלא תקנה דשליחותיהו עבדינן (גיטין פח) אין אנו חייבים במצות מינוי שופטים מן התורה כלל
@465 **וטעם לשבטיך** . מוסב על תתן לך מלמד שמושיבים ב"ד בכל שבט ושבט ובכל עיר ועיר לשון רש"י וכן במסכת סנהדרין (טז) ולא ידעתי פירוש דבר זה כי כיון שמנינו ב"ד בכל עיר ועיר הרי בתי דינין רבים בכל שבט ושבט אולי בא לומר שאם היתה עיר אחת לשני שבטים כירושלים שיש בה חלק ליהודה ובנימין שיושיב בה שני בתי דינים וכך העלו בפרק חלק (שם קיא) שחולקים עיר אחת לשני שבטים וכן ירושלים היתה ליהודה ובנימין ויתכן לפרש שחייב הכתוב למנות ב"ד על כל השבט והוא ישפוט את כולם ואחרי כן נמנה ב"ד בכל עיר ועיר שישפוט את העיר ואע"פ שכולם שוים במנין שהם כ"ג בדיני נפשות וג' בדיני ממונות אבל הגדולים שבהם בחכמה יתמנו על כל השבט ותחתיהם לכל עיר ועיר ואין בעלי הדין יכולין לכוף זה את זה לדון אלא בפני ב"ד שבעירם לא בפני ב"ד שבעיר אחרת ואפילו היו שני בעלי הדין בעיר אחרת יכול לומר נלך לפני ב"ד שבעירנו אבל ב"ד השבט יכול לכוף כל אנשי שבטו לדון לפניו ואפילו היו הנדונים בעירם יכול לומר לב"ד הגדול של שבט אזילנא וכן אם נסתפקו בתי דינין של עיירות יבאו לפני ב"ד הגדול של שבט וישאלו כדרך שסנהדרי גדולה ממונה על כל בתי דינין של כל ישראל כך יהא ב"ד אחד ממונה על כל שבט ושבט ואם הוצרכו לתקן ולגזור דבר על שבט שלהם גוזרין ומתקנין והיא לשבט כגזרת סנהדרי גדולה על כל ישראל וזה הב"ד הוא המוזכר במסכת הוריות (ה) ששנינו בו הורו בית דין של אחד מן השבטים ועשה אותו השבט על פיהם אותו השבט חייב ושאר השבטים פטורים וכו' ועל דרך הפשט שיעור הכתוב שופטים ושוטרים תתן לך לשבטיך בכל שעריך יאמר שיתנו שופטים לשבטיהם והם ישפטו בכל שעריהם ושופט השבט ישפוט בכל שעריו
@467 **צדק צדק תרדף** . הלך אחר ב"ד יפה למען תחיה וירשת את הארץ כדאי הוא מינוי הדיינין הכשרים להחיות את ישראל ולהושיבן על אדמתם לשון רש"י מספרי (שופטים קמד) וטעם הכפל לומר הדיינין צריכין שישפטו את העם משפט צדק וגם אתה צריך לרדוף הצדק תמיד שתלך ממקומך אל מקום חכמים הגדולים אחרי רבן יוחנן בן זכאי ליבנה אחר רבי לבית שערים ור"א אמר צדק צדק פעמים שירדוף אחרי הצדק שירויח בו או יפסיד או פעם אחר פעם לחזוק אבל במדרשו של ר' נחוניא בן הקנה ידרשו בו סוד אמרו צדק זו מידת דינו של עולם שנאמר צדק צדק תרדוף וכתיב בתריה למען תחיה וירשת את הארץ אם תדין עצמך תחיה אם לאו הוא ידין עליך ותקים בעל כרחך ומאי צדק צדק תרי זימני דכתיב ( כב יג) מנגה נגדו צדק ראשון צדק ממש זו שכינה דכתיב (ישעיהו א כא) צדק ילין בה ומאי צדק שני שמפחיד את הצדיקים ומפרש שם צדק הוי כובע ישועה על ראשו ואין ראש אלא אמת שנאמר (תהלים קיט קס) ראש דברך אמת ואין אמת אלא שלום שנאמר (מלכים ב כ יט) הלא אם שלום ואמת יהיה בימי וגו' אם כן יאמר הכתוב תשפוט אתה בבית דינך ותרדוף צדק צדק ותשיג אותם למען תחיה לעולם הבא בצדק השני שהוא צדק עליון והוא האור הגדול הצפון לצדיקים לעתיד לבא והוא עוזו של הקב"ה וירשת את הארץ בצדק הראשון שהוא ארץ ישראל
@468 **לא תטע לך אשרה** . כל אילן הנטוע על פתחי בית אלהים יקרא אשרה אולי בעבור שהוא שם דרך מראה אותו לעם יקרא כן מלשון תמוך אשורי במעגלותיך (תהלים יז ה) יזהיר הכתוב שלא יטע אילן אצל מזבח ה' לנוי ויחשוב שהוא כבוד והדר למזבח השם ואסר אותו בעבור שהוא מנהג עובדי עבודה זרה לטעת אילנות בפתחי בתי עבודה זרה שלהם וכענין שנאמר (שופטים ו כה) והרסת את מזבח הבעל וגו' ואת האשרה אשר עליה תכרת ורש"י כתב לא תטע לך אשרה לחייבו עליה משעת נטיעתה ואפילו לא עבדה עובר בלא תעשה על נטיעתה ולא תטע כל עץ אצל מזבח ה' אלהיך אזהרה לנוטע ולבונה בהר הבית ואם כן יאמר לא תטע לך אשרה וכל עץ אצל מזבח ה' אבל הבונה בהר הבית אסמכתא מדבריהם כי הכתוב לא אסר אלא הנטיעה לא תטע לך אשרה ולא תטע לך כל עץ אצל מזבח ה' אלהיך
@469 **ולא תקים לך מצבה** . מצבת אבן אחת להקריב עליה אפילו לשמים אשר שנא מזבח אדמה ומזבח אבנים צוה לעשות ואת זו שנא כי חוק היתה לכנענים ואע"פ שהיתה אהובה לו בימי האבות עכשיו שנאה מאחר שעשאוה אלו חוק לע"ז לשון רש"י ואם כן אסר הכתוב האשרה ואסר כל נוטע בהר הבית אע"פ שכוונתו לשמים ואסר המצבה לשמים ושניהם מפני חוקת הכנעניים אבל לא הבינותי החק הזה שהרי הכנעניים גם במזבחות גם במצבות היו נוהגים שהכתוב אומר ונתצתם את מזבחותם ושברתם את מצבותם (לעיל יב ג) כי את מזבחותם תתצון ואת מצבותם תשברון (שמות לד יג) וכן בכל מקום ואולי נאמר שהחזיקו הכנענים במצבות ולא היה להם בית ע"ז שאין שם מצבה להקטיר עליה ולצוק שמן על ראשה וכענין שנאמר בבעל (מלכים ב י כו) ויוציאו את מצבות בית הבעל אבל המזבחות היו במקצתן להקריב גם בהם והנראה בעיני כי היו הכנענים השטופים בע"ז עושים בכל בתי אלהיהם מזבח להקריב עליו הקרבנות ואבן גדולה מוצבת על פתח הבית לעמוד עליה הכומרים ואילן נטוע חוצה לה לאשר דרך הבאים שם וגם היום הנוצרים עושים כן והנה השם הנכבד שנא ומאס כל מעשיהם ואסר המצבה והאשרה ולא השאיר רק המזבח שהוא צורך הקרבנות אשר הוא יתברך צוה בהם והיו נחת רוח לפניו שאמר ונעשה רצונו מאז קודם היות ע"ז בעולם וטעם אשר שנא ביאור כי השם צוה (שמות כ כד כה) מזבח אדמה תעשה לי ואם מזבח אבנים תעשה לי וביאר משה כי באלה יחפוץ להוציא המצבה כי שנאה כי כל מעשיהם שנואין לפניו וצוה את ישראל שלא יעשו כמעשיהם אבל בימי יעקב לא נאמר עדיין ובחקותיהם לא תלכו (ויקרא יח ג) ולכך היה משתמש במצבה לשם שמים כמנהג העובדים והנה זו מצוה מבוארת מן ואם מזבח אבנים תעשה לי אבל מה שאמר בתורה (שם כו א) ופסל ומצבה לא תקימו לכם הם פסל ומצבה להושיב הפסל על המצבה לע"ז כי שם בענין ע"ז דיבר הכתוב אבל יאמר (שם) ואבן משכית לא תתנו בארצכם להשתחוות עליה אפילו לשמים מפני שהוא נראה כעובד לשכיות ההם כטעם האשרה שהיא מחוקות העמים ודע כי מזבח הוא בנין אבנים גבוה ולו קרנות ארבע ולו יסוד סובב יעלו על יסודו ומקריבים בין קרנותיו והמצבה אבן אחת גדולה ירימוה להקטיר או להקריב עליה או להיות הכומרים עומדים עליה והבמה כענין הר ועושים אותה מעפר מקובץ ועליה מזבח בנוי להקריב בו כי כל דבר רם וגבוה יקראו כן אעלה על במתי עב (ישעיהו יד יד) על במותי ארץ (דברים לב יג) גם גב האדם יקרא במה על במותימו תדרך (שם לג כט) וכן אמר הכתוב (מלכים א ג ד) וילך המלך גבעונה לזבוח שם כי היא הבמה הגדולה אלף עולות יעלה שלמה על המזבח ההוא
@470 **לא תזבח לה' אלהיך כל דבר רע** . אזהרה למפגל קדשים על ידי דבור רע ועוד נדרשו בו שאר דרשות בשחיטת קדשים לשון רש"י והנה זו מצוה מבוארת שכבר הזהיר על השוחט בעלי מומים (ויקרא כב כב) וחזר להוסיף המפגל והקרוב כי החזיר האזהרה הזאת בעבור הישראלי המקריב שלא יפגל בשחיטה אבל הכהנים זריזים ומוזהרים הם ודיים בהתראה אחת ולכך לא החזיר מום המקריבים וטעם כי תועבת ה' אלהיך הוא הזבח הזה כי הזובח משחת לה' בוזה הוא כאמור בקבלה (מלאכי א יד) וארור נוכל וגו' ונודר וזובח משחת לה' כי מלך גדול אני ועל פי המדרש (ספרי קמז) תהיה התועבה ברובע ונרבע באתנן ומחיר שהם תועבות
@471 **כי ימצא בקרבך באחד שעריך אשר ה' אלהיך נתן לך** . כבר פירשתי (לעיל יא לב) כי כאשר ידבר במשפטים יזכיר תחילה המשפט בע"ז או בעובדיה ואמר באחד שעריך אשר ה' אלהיך וגו' ולא שיהיה זה בארץ ישראל בלבד שאף העובד בחוצה לארץ בסקילה אבל ענין הכתוב שאמר כי ימצא הדבר באחת מן הערים הרחוקות שיתן לך השם כאשר ירחיב את גבולך והוגד לך ושמעת באיזה עיר שתהיה אתה שם תדרוש הדבר היטב וכאשר תדע שהוא אמת והוצאת אותם אל השער ההוא שעבד בו וסקלתם ואמר (בפסוק ד) נעשתה התועבה הזאת בישראל לחייב אפילו בחוצה לארץ כי בעיר הנדחת אמר (לעיל יג טו) נעשתה התועבה הזאת בקרבך אבל כאן הזכיר "באחד שעריך" שדיבר בהווה כאשר פירשנו ואחר כך הזכיר "בישראל" ללמד שנוהג זה בכל ישראל ועוד הוצרך לומר "באחד שעריך" ללמד שיסקל על שער שעבד בו וזה בארץ כי בחוצה לארץ נסקל על פתח בית דין שנדון בו והמצוה הזו מבוארת שכבר אמר (שמות כב יט) זובח לאלהים יחרם והוא בכל מקום ובכל זמן ולכך ישנה אותה לבאר מה שיצטרך להוסיף במצוה ויקצר בדבר הנזכר ועל דרך האמת יתכן כי הזכיר "באחד שעריך" בעבור שאמר "לעבור בריתו" והיא התועבה הנעשית בישראל יודיע הכתוב הברית בארץ הברית אבל הדר בחוצה לארץ כאילו עובד ע"ז וכבר הזכרתי הענין הזה (ויקרא יח כה) והזכיר איש או אשה כי בעבור קלות דעת האשה תתפתה לעבוד ע"ז באות או מופת שנעשה לפניה והעד נשי ירמיהו (ירמיהו מד) וכן הזכיר באוב וידעוני (ויקרא כ כז) "או אשה" לרגילות הנשים בהם כמו שאמר (שמות כב יז) מכשפה לא תחיה ובספרי (שופטים קמח) דרשו כי בעבור שאמר במדיח (לעיל יג יד) יצאו אנשים בני בליעל ואין הדין ההוא ככה בנשים הוצרך לפרש בעובד שהוא שוה באיש ובאשה וטעם אשר לא צויתי מפורש "()" "סגירה"
@472 **כי ימצא בקרבך באחד שעריך אשר ה' אלהיך נתן לך** . כבר פירשתי (לעיל יא לב) כי כאשר ידבר במשפטים יזכיר תחילה המשפט בע"ז או בעובדיה ואמר באחד שעריך אשר ה' אלהיך וגו' ולא שיהיה זה בארץ ישראל בלבד שאף העובד בחוצה לארץ בסקילה אבל ענין הכתוב שאמר כי ימצא הדבר באחת מן הערים הרחוקות שיתן לך השם כאשר ירחיב את גבולך והוגד לך ושמעת באיזה עיר שתהיה אתה שם תדרוש הדבר היטב וכאשר תדע שהוא אמת והוצאת אותם אל השער ההוא שעבד בו וסקלתם ואמר (בפסוק ד) נעשתה התועבה הזאת בישראל לחייב אפילו בחוצה לארץ כי בעיר הנדחת אמר (לעיל יג טו) נעשתה התועבה הזאת בקרבך אבל כאן הזכיר "באחד שעריך" שדיבר בהווה כאשר פירשנו ואחר כך הזכיר "בישראל" ללמד שנוהג זה בכל ישראל ועוד הוצרך לומר "באחד שעריך" ללמד שיסקל על שער שעבד בו וזה בארץ כי בחוצה לארץ נסקל על פתח בית דין שנדון בו והמצוה הזו מבוארת שכבר אמר (שמות כב יט) זובח לאלהים יחרם והוא בכל מקום ובכל זמן ולכך ישנה אותה לבאר מה שיצטרך להוסיף במצוה ויקצר בדבר הנזכר ועל דרך האמת יתכן כי הזכיר "באחד שעריך" בעבור שאמר "לעבור בריתו" והיא התועבה הנעשית בישראל יודיע הכתוב הברית בארץ הברית אבל הדר בחוצה לארץ כאילו עובד ע"ז וכבר הזכרתי הענין הזה (ויקרא יח כה) והזכיר איש או אשה כי בעבור קלות דעת האשה תתפתה לעבוד ע"ז באות או מופת שנעשה לפניה והעד נשי ירמיהו (ירמיהו מד) וכן הזכיר באוב וידעוני (ויקרא כ כז) "או אשה" לרגילות הנשים בהם כמו שאמר (שמות כב יז) מכשפה לא תחיה ובספרי (שופטים קמח) דרשו כי בעבור שאמר במדיח (לעיל יג יד) יצאו אנשים בני בליעל ואין הדין ההוא ככה בנשים הוצרך לפרש בעובד שהוא שוה באיש ובאשה וטעם אשר לא צויתי מפורש
@475 **על פי שנים עדים או שלשה עדים** . "אם מתקיימת עדות בשנים, למה פרט לך בשלשה? - להקיש שלשה לשנים: מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כולן"; לשון רש"י.
@475 וכן, אם נמצא אחד מהם קרוב או פסול, העדות כולה בטלה, והם כולם נהרגים ומשלמים ממון בהזמתן, שעיקר הכתוב להקיש שלשה לשנים בכל דבריהם, כדעת רבותינו (מכות ה ב).
@475 ועל דרך הפשט, אמר הגאון רב סעדיה: שנים - עדים, או שלשה - מקבלי עדות השנים. ואין בכתוב קבלת עדות, רק עדים. אבל כמדומה לי שטעה הגאון בדינו, כי עדות דיני נפשות לא תקובל רק בפני סנהדרין של עשרים ושלשה.
@475 אבל פשוטו של מקרא לאמר, שיומת המת על פי שנים עדים כשאין שם יותר, או על פי שלשה אם ימצאון שם שלשה; יאמר הכתוב, כאשר הוגד לך ושמעת, תדרוש הדבר היטב על פי כל העדים הנמצאים שם. והנה, אם שמענו שעבר בפני שלשה, נשלח בעבורם ויבואו לבית דין ויעידו כולם, והוא הדין למאה; כי בשמענו דברי כולם יתברר האמת. ואם לא היו שם יותר, או שהלכו להם ואינם נמצאים שם, בשנים די.
@477 **דברי ריבת** . שיהיו חכמי העיר חלוקים בדבר זה מטמא וזה מטהר זה מחייב וזה מזכה לשון רש"י והיא דעת אונקלוס ואיננו נכון אבל כפי מדרשו (ספרי שופטים קנב) בין דם לדם בין דם נדה לדם יולדת ולדם זבה בין דין לדין בין דיני ממונות לדיני נפשות לדיני מכות ובין נגע לנגע בין נגעי אדם לנגעי בתים לנגעי בגדים דברי ריבות השקאת הסוטה ועריפת העגלה וטהרת המצורע והנה טעמו ובין והלמ"ד לדעתם תשמש כמו בי"ת בין דם בדם דין בדין כלומר שיפלא דבר למשפט באחד מכל הדמים ובאחד מכל הדינין וכמוהו לוז שם העיר לראשונה (בראשית כח יט) בראשונה נגפו ה' במעיו לחלי לאין מרפא (דהי"ב כא יח) בחולי באין מרפא ויחפהו זהב טוב לככרים שש מאות (שם ג ח) בככרים וכן רבים או טעמו בין דם לכל הדמים בין דין לכל הדינין וכן וכל ריב אשר יבוא עליכם מאחיכם וגו' בין דם לדם בין תורה למצוה לחוקים ולמשפטים והזהרתם אותם ולא יאשמו לה' (שם יט י) וכפי פשוטו בין דם לדם וגו' בין ענין רציחות או דיני ממון או פצע וחבורה כל דברי ריבות אשר יהיו בשעריך ודיבר הכתוב בהווה כי בענייני המשפטים יהיו המחלוקות יותר משאר ההוראות אבל דין הזקן שוה בכולם ולכך אמר (פסוק יא) ועשית על פי התורה וגו' ועל המשפט וגו' כי "התורה" תרמוז לשאר ההו ראות
@480 **ימין ושמאל** . אפילו אם אומר לך על ימין שהוא שמאל או על שמאל שהוא ימין לשון רש"י וענינו אפילו תחשוב בלבך שהם טועים והדבר פשוט בעיניך כאשר אתה יודע בין ימינך לשמאלך תעשה כמצותם ואל תאמר איך אוכל החלב הגמור הזה או אהרוג האיש הנקי הזה אבל תאמר כך צוה אותי האדון המצוה על המצות שאעשה בכל מצותיו ככל אשר יורוני העומדים לפניו במקום אשר יבחר ועל משמעות דעתם נתן לי התורה אפילו יטעו וזה כענין רבי יהושע עם ר"ג ביום הכיפורים שחל להיות בחשבונו (ר"ה כה) והצורך במצוה הזאת גדול מאד כי התורה נתנה לנו בכתב וידוע הוא שלא ישתוו הדעות בכל הדברים הנולדים והנה ירבו המחלוקות ותעשה התורה כמה תורות וחתך לנו הכתוב הדין שנשמע לבית דין הגדול העומד לפני השם במקום אשר יבחר בכל מה שיאמרו לנו בפירוש התורה בין שקבלו פירושו עד מפי עד ומשה מפי הגבורה או שיאמרו כן לפי משמעות המקרא או כוונתה כי על הדעת שלהם הוא נותן (ס"א לנו) להם התורה אפילו יהיה בעיניך כמחליף הימין בשמאל וכל שכן שיש לך לחשוב שהם אומרים על ימין שהוא ימין כי רוח השם על משרתי מקדשו ולא יעזוב את חסידיו לעולם נשמרו מן הטעות ומן המכשול ולשון ספרי (שופטים קנד) אפילו מראין בעיניך על הימין שהוא שמאל ועל שמאל שהוא ימין שמע להם
@483 **ואמרת אשימה עלי מלך** . על דעת רבותינו (ספרי ראה סז, סנהדרין כ א) כמו "ואמור אשימה עלי מלך", והיא מצות עשה, שיחייב אותנו לומר כן אחר ירושה וישיבה, כלשון (דברים כב ח): "ועשית מעקה לגגך" וזולתם. והזכיר "ואמרת", כי מצוה שיבואו לפני הכהנים הלוים ואל השופט, ויאמרו להם 'רצוננו שנשים עלינו מלך'.
@483 ולפי דעתי עוד, שגם זה מרמיזותיו על העתידות, שכן היה כששאלו להם את שאול, אמרו לשמואל (שמואל א ח ה): "שימה לנו מלך לשפטנו ככל הגוים", וכן כתוב שם (שמואל א ח כ): "והיינו גם אנחנו ככל הגוים ושפטנו מלכנו וגו'", כי מה טעם שתאמר התורה במצוה "ככל הגוים אשר סביבותי", ואין ישראל ראויים ללמד מהם ולא לקנא בעושי עולה! אבל זה רמז לענין שיהיה, ולכך באה הפרשה בלשון הבינוני, כאשר פירשתי כבר.
@484 **וטעם אשר יבחר ה' אלהיך בו** .
@484 על דעת המפרשים, שיהיה נבחר על פי נביא או במשפט האורים, יצוה הכתוב תשים עליך מלך אשר יבחר ה' אלהיך בו, כי הוא יבחר ולא אתה. ובספרי: "שום תשים עליך מלך - מת מנה אחר תחתיו, מלך - ולא מלכה, אשר יבחר ה' אלהיך - על פי נביא".
@484 אם כן, מה טעם להזהיר "לא תוכל לתת עליך איש נכרי", והשם לא יבחר בנכרי?
@484 אבל לדעת רבותינו יש בכתוב הזה תנאי נסתר, יאמר שום תשים עליך המלך שיבחר השם בו אם תוכל לעשות כן שיענך השם בנביאים, אבל איש נכרי לא תוכל לתת עליך לעולם.
@484 ועל דרך הפשט אמרו: שום תשים עליך מלך אשר יבחר ה' אלהיך בו, ולא אשר שנא ה' אלהיך, כי הוא בחר בישראל ולהיות המולך מבחוריו ולא מקרב העמים אשר שנא.
@484 ודעתי בדרך הפשט, כי טעם "אשר יבחר" שכל מולך על עמים מאת האלהים היא לו, כענין שכתוב (דניאל ד כט): "די שליט עלאה במלכות אנשא ולמאן די יצבא יתננה". וכך אמרו (ב"ב צא) אפילו ריש גרגותא מן שמיא מוקמי ליה. יאמר "שום תשים עליך מלך, כל אשר יהיה נגזר מן השמים שימלוך, ואם הוא מקטני שבטי ישראל ומשפחתו הצעירה; אבל איש נכרי לא תמליך עליך לעולם". וכן על דרך הפשט "המקום אשר יבחר ה' אלהיך בו", כל שיבנו שם בית המקדש לה', הכל מרצון ה'.
@485 **לא ירבה לו סוסים** . אלא כדי מרכבתו כדי שלא ישיב את העם מצרימה שהסוסים באים משם שנאמר (מלכים א י כט) ותעלה ותצא מרכבה ממצרים בשש מאות כסף לשון רש"י והוקשה לי בזה כי אמרו בירושלמי בסוף סנהדרין (סוף פ"י) לישיבה אי אתה חוזר אבל אתה חוזר לסחורה לפרקמטיא ולכבוש הארץ ואם ישלח המלך ויקנה משם הסוסים והרכב סחורה היא זו ומותר ויתכן שדרך הכתוב כי הזהיר לא ירבה לו סוסים אפילו מארצו ומארץ שנער או בדרך סחורה המותרת שלא יבטח על רכבו כי רב ועל פרשיו כי עצמו מאוד אבל יהיה מבטחו בשם אלהיו ואחר כך הזהיר על המלך שלא ישיב את העם מצרימה שיהיו לו שם מעבדיו ומעמו שרי מקנה יושבים בערי הרכב למען הרבות סוס כענין שנאמר בשלמה (מלכים א ט יט) ואת כל ערי המסכנות אשר היו לשלמה ואת ערי הרכב וגו' וכן היו לו במצרים כמו שאמר (שם י כח) ומוצא הסוסים אשר לשלמה ממצרים ומקוה סחרי המלך וגו' שלא היה אדם רשאי להוציא ממצרים סוסים שלא ברשות מלך מצרים והיו נותנים לו מכס מהם ונתן פרעה לשלמה מוצא הסוסים לומר שיוציא הוא כרצונו והוא שיתן הרשות לאשר ירצה ויהא המכס שלו והיו לו שם הסוחרים עומדים במצרים קונים הסוסים כולם ושולחים אל אדוניהם כרצונו ומוכרים האחרים לשאר מלכי הארץ והוא שאמר (שם פסוק כט) וכן לכל מלכי החתים ולכל מלכי ארם בידם יוציאו כלומר על ידי סוחרי שלמה יוציאו אותם ולו יתנו המכס וטעם רק לומר אף על פי שתשים עליך מלך ככל הגוים אשר סביבותיך רק לא יהיה כמלכיהם שלא ירבה סוסים כאשר יעשו הם שכל חפצם במלכים למען הרבות להם סוסים ופרשים וטעם וה' אמר לכם כי השם אומר לכם שלא תוסיפון לשוב בדרך מצרים וכן כאשר צוך ה' אלהיך (לעיל ה טז) שהוא מצוה אותך כן או "אמר לכם" שאמר לי כן לצוות אתכם כדרך ויאמר משה כה אמר ה' כחצות הלילה וגו' (שמות יא ד) ועל דרך רבותינו (ירושלמי סוכה פ"ה ה"א) כי כאשר ראיתם את מצרים היום לא תוסיפו לראותם עוד עד עולם (שמות יד יג) מצוה ומשה הזכיר וה' אמר לכם שלא תוסיפון לשוב בדרך הזה עוד וכבר פירשתיו (שם) וטעם המצות הזאת מפני שהיו המצרים והכנענים רעים וחטאים לה' מאד כמו שאמר (ויקרא יח ג) כמעשה ארץ מצרים אשר ישבתם בה לא תעשו וכמעשה ארץ כנען וגו' והנה רצה ה' שלא ילמדו ישראל ממעשיהם והכרית בכנענים כל נשמה (להלן כ טז) ואמר (שמות כג לג) לא ישבו בארצך והזהיר במצרים שלא נשב אנחנו שם בארצם
@488 **והיתה עמו** . התורה הנזכרת וקרא בו בספר הנזכר ועל דרך האמת והיתה עמו התורה עצמה תהיה עמו כדרך וה' נתן חכמה לשלמה (מלכים א ה כו) ואומר וישב שלמה על כסא ה' למלך (דהי"א כט כג)
@489 **לבלתי רום לבבו מאחיו** . נרמז בכאן בתורה איסור הגאות כי הכתוב ימנע את המלך מגאות ורוממות הלב וכל שכן האחרים שאינן ראויים לכך כי בראוי להתרומם ולהתגדל יזהירנו להיות לבבו שפל ככל אחיו הקטנים ממנו כי הגאוה מדה מגונה ונמאסת אצל האלהים אפילו במלך כי לה' לבדו הגדולה והרוממות ולו לבדו התהלה ובו יתהלל האדם כענין המבואר על יד המלך שלמה (משלי טז ה) תועבת השם כל גבה לב וכתיב (ירמיהו ט כג) כי אם בזאת יתהלל המתהלל השכל וידוע אותי וגו'
@490 **אשי ה'** . קדשי המקדש נחלתו אלו קדשי הגבול תרומות ומעשרות אבל נחלה גמורה לא יהיה לו בקרב אחיו ובספרי דרשו ונחלה לא יהיו לו זו נחלת שאר בקרב אחיו זו נחלת שבעה ואיני יודע מה הוא ונראה לי שארץ כנען שמעבר הירדן ואילך נקראת ארץ חמשה עממין ושל סיחון ועוג שני עממין אמורי וכנעני ונחלת שאר לרבות קיני וקנזי וקדמוני שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי (שופטים קסד) ונחלה לא יהיה לו אלו נחלת חמשה בקרב אחיו אלו נחלת שבעה נחלת חמשה שבטים ונחלת שבעה שבטים ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד שכן משה הנחיל לראובן וגד ולחצי שבט מנשה ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה ושבעה אחרים נטלו מאיליהן אחרי מות יהושע מתוך כך הזכיר חמשה לבד ושבעה לבד כל זה לשון רש"י וכבר פירשתי העיקר בפרשת קדש לי (שמות יג ה) כי נחלת חמשה עממין הנזכרים בפסוק כי יביאך ה' אל ארץ הכנעני והחתי והאמורי והחוי והיבוסי אשר נשבע לאבותיך לתת לך ארץ זבת חלב ודבש והם עיקר נחלת ישראל שהיתה ארצם זבת חלב ודבש אבל השנים הנשארים והם הפרזי והגרגשי אין ארצם זבת חלב ודבש ואינה חייבת בבכורים ולכך הזכיר בלויים שלא יטלו חלק עם ישראל בעיקר נחלתם בארץ הטובה שהיא נחלת החמשה וגם לא בנחלת השבעה שהם השנים הנשארים אף על פי שאין ארצם טובה ואינה חשובה בעיני ישראל כל כך ודבר ברור הוא בראיות שכתבתי שם
@492 **וזה יהיה משפט הכהנים** . זו מצוה מחודשת לא נזכרה בתורה כי במדבר שלא היו זובחים שור ושה רק שלמים לא הזכירה להם שאינה נוהגת במוקדשים ועתה כשבאו ליכנס לארץ חדשה להם וזה טעם מאת זבחי הזבח כלומר כאשר יזבחו הזבח שהתרתי לכם (לעיל יב כא) וזבחת מבקרך ומצאנך כאשר צויתיך ואכלת בשעריך והנה לא נתן אותה לאהרן בפרשת ויאמר ה' אל אהרן (במדבר יח ח) אע"פ שנתן לו שם התרומות והבכורים שאינם נוהגים אלא בארץ והטעם כי שם הזכיר כל אשר נתן לו בקדש כי גם החרם קדש הוא אבל הזרוע והלחיים והקיבה וראשית הגז הן חולין גמורין אין בהם זולתי מצות המתנה וכן לא הזכיר שם גזל הגר ועל מדרש רבותינו כולם נרמזות שם ראשיתם זו ראשית הגז אשר יתנו זו הזרוע והלחיים והקיבה לה' זו חלה בספרי (קרח קיז) אם כן גם זו מצוה מבוארת ועל סמך המדרש שאמרו (חולין קלד) זרוע תחת ויקח רמח בידו (במדבר כה ז) לחיים תחת תפלה שנאמר (תהלים קו ל) ויעמוד פינחס ויפלל וגו' הקבה תחת האשה אל קבתה (במדבר כה ח) נרמזו שם על הזכות שעתיד להיות וזיכה לכל השבט בזכות פנחס כאשר זיכה לפנחס להיות כהן עמהם והרב אמר במורה הנבוכים (ג לט) כי הלחיים בעבור היותם ראשית לגוף והזרוע בעבור היותו ראשית האברים המשתרגים בגוף והקיבה ראשית המעים כי הראשית בכולם ינתנו למשרתי עליון לכבודו
@498 **לא תלמד לעשות כתועבת הגוים ההם** . גם זו מצוה מבוארת שכבר אמר (ויקרא יח ג) וכמעשה ארץ כנען אשר אני מביא אתכם שמה לא תעשו ובחקתיהם לא תלכו ועתה יזכיר מעשיהם ויאמר שהם תועבה לפני השם והזכיר מעביר בנו ובתו באש והוא מין ממיני הכשוף על דרך הפשט או המולך על דעת רבותינו (סנהדרין סד) והוא האמת כמו שפירשתי במקומו (ויקרא יח כא) והזכיר מכשף שם כלל לכל הכשפים וחובר חבר ושואל אוב וידעוני והם פרטים בכשוף ואסר אותם גם לשואל ודרש אל המתים כאוב עצמו ובכל ענין שידרוש אליהם והזכיר קוסם קסמים והיא מחשבה בעתידות בכלל מלשון קסם על שפתי מלך במשפט לא ימעל פיו (משלי טז י) כמו שאמר (יהושע יג כב) בלעם בן בעור הקוסם והיה מנחש כמו שאמר בו (במדבר כד א) ולא הלך כפעם בפעם לקראת נחשים וכתיב (שמואל א כח ח) קסמי נא לי באוב והזכיר בפרט מעונן והוא היודע בעננים ומנחש הוא המביט בעופות בכנפיהם או בצפצוף כענין שכתוב (קהלת י כ) כי עוף השמים יוליך את הקול ובעל כנפים יגיד דבר והוא לשון נגזר מלשון חשתי ולא התמהמהתי (תהלים קיט ס) שכל מה שימהר להודיע בעתיד קודם היותו יקרא נחש כלומר נחיש ונקדים לדעת ואמר הכתוב כי תועבת ה' כל עושה אלה ולא אמר "עושה כל אלה" כי הכתוב ידבר על רובם כי המעונן והמנחש אינה תועבה ולא הוריש הכנענים בעבורם כי כל בני אדם יתאוו לדעת עתידות למו ומתעסקין בחכמות רבות כאלה לדעתם ועתה דע והבן בעניני הכשפים כי הבורא יתברך כאשר ברא הכל מאין עשה העליונים מנהיגי התחתונים אשר למטה מהן ונתן כח הארץ וכל אשר עליה בכוכבים ובמזלות לפי הנהגתם ומבטם בהם כאשר הוא מנוסה בחכמת האיצטגנינות ועשה עוד על הכוכבים והמזלות מנהיגים מלאכים ושרים שהם נפש להם והנה הנהגתם מעת היותם עד לעולם ועד גזירת עליונים אשר שם להם אבל היה מנפלאותיו העצומות ששם בכח המנהיגים העליונים דרכי תמורות וכחות להמיר הנהגת אשר למטה מהם שאם יהיה מבט הכוכבים (בפניו) בפנים אשר כנגד הארץ טובה או רעה לארץ או לעם או לאיש ימירו אותם הפנים העליונים עליו להפך במבט עצמו כענין שאמרו תמורת ענג נגע ועשה כן להיות הוא יתברך שמו מהשנא עדניא וזמניא קורא למי הים לעשות בהם כרצונו והופך לבקר צלמות מבלי שינוי טבעו של עולם ושיעשו הכוכבים והמזלות מהלכם כסדרן ועל כן אמר בעל ספר הלבנה החכם בנגרמונסי"א כשהלבנה והיא נקראת גלגל העולם בראש טלה על דרך משל ויהיה פניו מול פלוני תעשה תמונה לדבר פלוני ויוחק בה שם השעה ושם המלאך הממונה עליה מן השמות ההם הנזכרים באותו הספר ותעשה הקטרה פלונית בענין כך וכך יהיה המבט עליה לרעה לנתוש ולנתוץ ולהאביד ולהרוס וכאשר תהיה הלבנה במזל פלוני תעשה תמונה והקטרה בענין פלוני לכל טובה לבנות ולנטוע והנה גם זה הנהגת הלבנה בכח מנהיגיה אבל ההנהגה הפשוטה אשר במהלכה הוא חפץ הבורא יתברך אשר שם בהם מאז וזה היפך וזה סוד הכשפים וכחם שאמרו בהם (חולין ז) שהם מכחישים פמלייא של מעלה לומר שהם היפך הכחות הפשוטים והם הכחשה לפמלייא בצד מהצדדין ועל כן ראוי שתאסור אותם התורה שיונח העולם למנהגו ולטבעו הפשוט שהוא חפץ בוראו וגם זה מטעמי איסור הכלאים כי יבואו מן ההרכבות צמחים יעשו פעולות נכריות יולידו שינויים ממנהגו של עולם לרע או לטוב מלבד שהן עצמן שינוי ביצירה כאשר פירשתי כבר (ויקרא יט יט) ורבים יתחסדו בנחשים לומר שאין בהם אמת כלל כי מי יגיד לעורב ולעגור מה יהיה ואנחנו לא נוכל להכחיש דברים יתפרסמו לעיני רואים ורבותינו גם כן יודו בהם כמו שאמרו בואלה שמות רבה (ויק"ר לב ב קהלת רבה י כג) כי עוף השמים יוליך את הקול (קהלת י כ) זה העורב וחכמת הטיארין העופות בלשון ערב טאי"ר וחכמי העופות יקראו טיארין ועוד מוזכר מזה הענין בגמרא (גיטין מה) אבל יש לענין הזה סוד וכבר הודענו (ויקרא יח כה) כי יש למזלות שרים ינהיגו אותם והם נפשות לכדורי הגלגלים ושרי זנב וטלה הקרובים לארץ והם הנקראים נגידי התלי יודיעו העתידות ומהם נעשים סימנים בעופות שבהם יודיעו עתידות ולא לזמן גדול ולא עתידות רחוקות יגידו רק בעתידות הקרובות לבא יודיעו מהם בקול העוף בקראו בקול מר על מת ומהם בפרישות כנפיו והוא שאמר יוליך את הקול למגידים בקולם ובעל כנפים לרומזים בכנפיהם וכל זה איננו תועבה בעמים אבל חכמה תחשב להם וכך אמרו (במדב"ר יט ג) ותרב חכמת שלמה מחכמת כל בני קדם (מלכים א ה י) מה היתה חכמתן של בני קדם שהיו יודעין וערומים בטייר וכן יאמר הכתוב (ישעיהו ב ו) כי מלאו מקדם ועוננים כפלשתים והנה שלמה למד זה בכלל חכמותיו והידיעה היא הבנת הצפצוף והערמה לסבור ענין בפרישות הכנפים וכאשר כלל הכתוב המעוננים והקוסמים עם התועבות הנזכרות חזר ופירש (בפסוק יד) הגוים האלה אשר אתה יורש אותם אל מעוננים ואל קוסמים ישמעו כי חכמתם לדעת הבאות ואתה לא כן נתן לך ה' אלהיך יאמר הנה אסר לך השם המעשים האלה הנזכרים בעבור שהם תועבות לפניו ובגללם הוריש הגוים ההם מפניך ואסר לך הנחשים והקסמים בעבור שעשה לך מעלה גדולה לתתך עליון על כל גויי הארץ שיקים בקרבך נביא ויתן דבריו בפיו ואתה תשמע ממנו מה יפעל אל ולא תצטרך אתה בעתידות אל קוסם ומנחש שיקבלו אותם מן הכוכבים או מן השפלים בשרי מעלה שאין כל דבריהם אמת ולא יודיעו בכל הצריך אבל הנבואה תודיע חפץ השם ולא יפול דבר מכל דבריה והוא שיפרש (בפסוק כב) הוא הדבר אשר לא דברו ה' והנה אתה חלקו וסגולתו שומע עצתו מפיו והם חלק המזלות הולכים אחריהם וזה טעם לא כן נתן לך ה' אלהיך שלא נתן לך כאשר נתן להם כטעם אשר חלק ה' אלהיך אותם לכל העמים (לעיל ד יט) כאשר פירשתי (ויקרא יח כה) ובספרי (שופטים קעד) אל מעוננים ואל קוסמים ישמעו שמא תאמר להם יש במה לשאול ולי אין לי לשאול תלמוד לומר ואתה לא כן נתן לך ה' אלהיך והנה זו ראיה בכל מה שפירשנו כי הנחשים שורש דבר נמצא בם ולכן היה לישראל טענה במניעה מהם
@502 **וטעם תמים תהיה עם ה' אלהיך** . שנייחד לבבנו אליו לבדו ונאמין שהוא לבדו עושה כל והוא היודע אמתת כל עתיד וממנו לבדו נדרוש העתידות מנביאיו או מאנשי חסידיו רצונו לומר אורים ותומים ולא נדרוש מהוברי שמים ולא מזולתם ולא נבטח שיבואו דבריהם על כל פנים אבל אם נשמע דבר מהם נאמר הכל בידי שמים כי הוא אלהי האלהים עליון על הכל היכול בכל משנה מערכות הכוכבים והמזלות כרצונו מפר אותות בדים וקוסמים יהולל ונאמין שכל הבאות תהיינה כפי התקרב האדם לעבודתו ולפיכך אחר אזהרת שאלת העתידות מקוסם ודורש בעד החיים אל המתים אמר שתהיה תמים עם השם בכל אלה ולא תירא ממגיד עתיד אבל מנביאו תדרוש ואליו תשמע וזה דעת אונקלוס שלים תהא בדחלתא דה' אלהך שלא תהיה חסר ביראתו כי "תמים" הוא השלם בדבר כמו שה תמים (שמות יב ה) שאין בו מום ושום חסרון וזו מצות עשה וכבר הזכרתי זה בפסוק והיה תמים (בראשית יז א)
@504 **נביא מקרבך מאחיך כמני** . טעם "מקרבך" לרמוז שאין נבואה אלא בארץ ישראל ולכך יאמר בה הכתוב (ישעיהו כב א) משא גיא חזיון וכמו שהזכירו רבותינו (מכילתא ריש בא) וכן טעם "מאחיך" כי השם נתן לך מעלה על כל העמים ולא יתן רוחו רק עליכם כמוני שאני מקרב אחיך יקים לך תחתי וכן מנביא לנביא לשון רש"י ואמר רבי אברהם כמוני שאני נביא השם לא מעונן וקוסם ויתכן שיהיה "מקרבך" לומר שתוכל לבטוח בדבריו שהוא מאחיך מקרבך וכן על דעתי "כמוני" שיהיה נאמן לנביא לה' ותאמין בו כאשר אתה מאמין בי ועוד אבאר זה
@505 **ככל אשר שאלת וגו'** . לא השלים הכתוב בכאן השאלה ששאלו כי באמרם לא אוסיף לשמוע את קול ה' לא יזכו לנביאים אבל כאשר אמרו (לעיל ה כד) קרב אתה ושמע את כל אשר יאמר ה' אלהינו ואת תדבר אלינו את כל אשר ידבר ה' אלהינו אליך ושמענו ועשינו אז קבלו להאמין בנביאיו ולשמוע ולעשות ככל אשר יצוה השם על ידם ולכך אמר בכאן נביא מקרבך מאחיך כמוני יקים לך ה' ותאמין בו כאשר אתה מאמין בי כי כן שאלת להיות דברי השם עמכם על ידי ושתשמעו אלי אם כן האמינו גם כן בשאר הנביאים הבאים אחרי כי כמוני כמוהם וזה טעם הטיבו אשר דברו להאמין בנביאי וכן אעשה להם לדורותם ויתכן שהיתה שאלתם שם לדורות וקבלתם שאמרו לשמוע ממשה באמרם "ואת תדבר אלינו ושמענו ועשינו" גם כן לדורות עולם ויהיה טעם "ואת" כמו ואתה וכל נביא השם כמוך כאשר פירשתי שם
@509 **ואשר ידבר בשם אלהים אחרים** . אפילו כיון את ההלכה לאסור את האסור ולהתיר את המותר ומת בחנק לשון רש"י מספרי (שופטים קעז קעח) ואין הענין לומר שאם בא אחד ואמר בחלומי ראיתי והנה פעור אומר לי שתזהרו במצות הלולב שיהא חייב מיתה כי זה פטור הוא ואם אומר שתעשו כן לעבוד לשקוץ ההוא אם כן זהו נביא השקר המתנבא לעבוד ע"ז ואפילו יאמר כן בשם השם הוא נסקל אבל הענין שיאמר ראיתי פעור כי הוא האלהים והוא מצוה שלא לאכול בשר חזיר וכן אם יגיד בשמו כי כזה וכזה עתיד להיות מאחר שיאמר כי הנעבד ההוא הוא האומר ועושה גוזר ומקיים יומת בחנק ולכך אמרו בגמרא (סנהדרין פט) המתנבא בשם ע"ז כגון נביאי הבעל והם שהיו אומרים שהבעל הוא האלהים כמו שכתוב (מלכים א יח כא) אם ה' הוא האלהים לכו אחריו ואם הבעל לכו אחריו והיו מתנבאים בו עלה והצלח ונתן ה' ביד המלך (שם כב טו) ודעתם לומר שהבעל הוא האדון אשר לו השם הנכבד הזה והוא שיתן רמות גלעד ביד אחאב
@510 **וכי תאמר בלבבך איכה נדע את הדבר אשר לא דברו ה'** . עתידים אתם לאמר כשיבוא חנניה בן עזור ומתנבא (ירמיהו כז טז) הנה כלי בית ה' מושבים מבבלה וירמיה עומד וצווח (שם פסוקים יט כב) על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה בבלה יובאו עם גלות צדקיהו לשון רש"י מספרי (שופטים קעח) והדרש הזה מפני שלא אמר "ואם תאמר בלבבך" והוא כמו שהזכרתי (לעיל ד כה) כי התורה תגיד ברמזים העתידות להיות אבל עיקר הכתוב לומר איכה נדע את הדבר אשר לא דברו השם שנהרוג המתנבא הזה וצוה כי כאשר לא יבוא הדבר אז יומת כי לא דברו השם ולא תגור ממנו מפני חכמתו או מפני האות שנתן ובא האות והמופת וכן היה להם לשאול איכה נדע הדבר אשר דברו ה' שנתחייב לשמוע אליו ככל אשר יצוה אבל זו תשובה לשתי השאלות כי בכל נביא נצפה לדבר העתיד להיות אשר יגיד ואם לא בא נדע שהוא נביא שקר ויומת ואם בא יבוא הכל הנה הוא נאמן לנביא לה' ונתחייב לשמוע אליו ככל אשר יצוה בשם ה' כמו שאמר (פסוק טו) "אליו תשמעון" ואפילו לעבור על דברי תורה לפי צורך השעה כגון אליהו בהר הכרמל וזה טעם "כמוני" "כמוך" שיהיה בתחילה נאמן לנביא השם או באות ומופת כענין שנאמר (שמות ד ל לא) ויעש האותות לעיני העם ויאמן העם או שיגיד העתיד להיות ויבוא שגם זה אות וכך אמרו במסכת סנהדרין (פט) והמוותר על דברי נביא מיתתו בידי שמים דכתיב אנכי אדרוש מעמו ואמרין (שם פט) ומנא ידע דאיענש דיהב ליה אות והא מיכה דלא יהב ליה אות ואיענש היכא דמוחזק שאני דאי לא תימא הכי אברהם בהר המוריה היכי שמע ליה יצחק אליהו בהר הכרמל היכי סמכינן עליה ועבדינן שחוטי חוץ אלא היכא דמוחזק שאני ורש"י כתב כבר נצטוו שאם בא להדיחך באחת מכל המצות לא תשמע לו אלא אם כן הוא מומחה לך שהוא צדיק גמור כגון אליהו בהר הכרמל לפי צורך השעה לכך נאמר אליו תשמעון וזה איננו נכון בעיני שאין ההמחאה שהוא צדיק גמור אלא שהוא נביא אמת מוחזק לכל במה שהקדים לאמר עתידות ובאו והוא האות שלו כמו שהזכיר בפרשה הזו או במופת שעשה בפנינו וזאת חזקת הנביאים ואולי נתכוון רש"י ב"צדיק גמור" למה שכתב הרב רבינו משה בהלכות יסודי התורה (פ"ז ה"ז) כשמשלחין את הנביא נותנין לו אות ומופת כדי שידעו העם שהאל שלחו באמת ולא כל העושה אות ומופת מאמינין אותו שהוא נביא אלא אדם שהיינו יודעים בו מתחילה שהוא ראוי לנבואה בחכמתו ובמעשיו שנתעלה בהן על כל בני גילו והיה מהלך בדרכי הנבואה ובקדושתה ופרישותה ואחר כך בא ועשה אות ומופת ואמר שהאל שלחו מצוה לשמוע ממנו שנאמר אליו תשמעון ואפשר שיעשה אות או מופת והוא אינו נביא וזה האות יש לו דברים בגו ואע"פ כן מצוה לשמוע לו הואיל ואדם גדול הוא וחכם וראוי לנבואה מעמידין אותו על חזקתו כמו שנצטוינו לחתוך הדין על פי שנים עדים כשרים ואע"פ שאפשר שהעידו שקר הואיל וכשרים הם אצלנו מעמידין אותם על כשרותן בדברים אלו וכיוצא בהם נאמר (להלן כט כח) הנסתרות לה' אלהינו ונאמר (שמואל א טז ז) האדם יראה לעינים וה' יראה ללבב
@512 **כי יכרית ה' אלהיך את הגוים וגו' שלוש ערים תבדיל לך** . גם זו מצוה מבוארת שכבר צוה בה (שמות כא יג) ועתה הוסיף לבאר משפטיה כי אמר וירשתם וישבת בעריהם ובבתיהם ללמד שלא נתחייבו בה אלא לאחר ירושה וישיבה וכן עשה יהושע והוסיף תכין לך הדרך שיהו סרטיאות מפורשות לתוכה ושיכתוב מקלט מקלט על פרשת הדרכים והוסיף ושלשת את גבול ארצך והוסיף עוד ללמדנו ענין השגגה כמו שאמר (פסוק ה) ואשר יבא את רעהו ביער וגו' ומדרשים רבים שדרשו רבותינו בפרשה
@519 **ואם ירחיב ה' אלהיך את גבלך** . הפרשה הזו עתידה וכבר הזכרתי מזה בפרשת ראה אנכי (לעיל יב כ) כי מתחילה אמר כי יכרית ה' אלהיך את הגוים אשר ה' אלהיך נותן לך את ארצם ו"הגויים אשר ה' אלהיך נותן לך את ארצם" ירמוז לכל השבעה אשר יזכיר בכל מקום וכן יאמר עליהם ונשל את הגוים האל מפניך (לעיל ז כב) וברשעת הגוים האלה (שם ט ד) והוריש ה' את כל הגוים האלה מלפניכם (שם יא כג) רק מערי העמים האלה (להלן כ טז) וכן במקומות רבים וצוה כי לאחר ירושה וישיבה בארצם יבדיל שלש ערים ובהם תשלום המצוה כמו שאמר (במדבר לה יג) שש ערי מקלט תהיינה לכם ואמר (שם פסוק יד) את שלש הערים תתנו מעבר לירדן ואת שלש הערים תתנו בארץ כנען ולא צוה בתורה ביותר משש הערים האלה וכן בכל מצות שבתורה הנוהגות לאחר ירושה וישיבה מתחייבין בהן לאחר ירושת שבעה גוים אלו אבל במצוה הזאת לבדה הוסיף בכאן ואם ירחיב ה' אלהיך את גבולך ולא אמר "כאשר דבר לך" כמו שאמר בכי ירחיב ה' אלהיך את גבולך של בשר תאוה (לעיל יב כ) כי ה' לא הבטיח אותם בשום מקום לתת להם רק שבעת הגוים האלה אבל הזכיר כאן האבות ואם ירחיב ה' אלהיך את גבולך כאשר נשבע לאבותיך ונתן לך את כל הארץ אשר דבר לתת לאבותיך וזה ירמוז לכל עשרה עממין שנאמרו לאברהם והתנה בזה כי תשמור את כל המצוה וגו' והנה דבר ברור הוא כי השבעה גוים עצמם לא יירשו אותם בעברם על התורה כאשר אמר פעמים רבים למען תחיו ובאתם וירשתם את הארץ (לעיל ד א) למען אשר תבא אל הארץ (להלן כז ג) כי אם שמור תשמרון את כל המצוה הזאת והוריש ה' את כל הגוים האלה מלפניכם (לעיל יא כב כג) וכאשר עבר עכן על החרם והוא איש אחד נאמר (יהושע ז יב) ולא יוכלו בני ישראל לקום לפני אויביהם ערף יפנו לפני אויביהם א"כ מה התנאי הזה אשר יתנה בשלשת העממין האלה לבדם ואם ירחיב ה' אלהיך את גבולך כי תשמר את כל המצוה וגו' והטעם בזה כי היה הרצון לפניו יתברך שינחיל אותם בימי משה ויהושע השבעה אשר הבטיחם במצרים ובמדבר כי היה גלוי לפניו שתגיע זכותם לכך ומפני זה חייב אותם בכל המצות בירושה של אלו וחייב אותם בשש ערי מקלט והבדילם יהושע אבל על השלשה הנשארים התנה כי תשמור את כל המצוה לאהבה את השם וללכת בדרכיו וגו' והוא לומר שיקיימו כולם כל התורה כולה ואין שום מצוה תלויה בכך זולתי שלש הערים האלה ומה טעם לאמר כי תשמור ללכת בדרכיו כל הימים תוסיף לך שלש הערים כי מי יודע מה יהיה אחרי כן כל הימים ואמר ר"א כל הימים בלי הפסק ביניהם ואיננו נכון אבל כי תשמר כאשר תגיע זכותך שתשמור כל המצוה לאהבה את השם אהבה שלימה קיימת לעולם שיהיה גלוי לפניו שלא תחטא עוד לעולם אז ירחיב את גבולך ויתן לך כל העמים והוא לימים אשר אמר (להלן ל ו) ומל ה' אלהיך את לבבך ואת לבב זרעך ו"לבב זרעך" יורה על כל הימים העתידים לבוא וכענין שנאמר בקבלה (ירמיה לב לט מ) ונתתי להם לב אחד ודרך אחד ליראה אותי כל הימים לטוב להם ולבניהם אחריהם וכרתי להם ברית עולם אשר לא אשוב מאחריהם להיטיבי אותם ואת יראתי אתן בלבבם לבלתי סור מעלי ואז כאשר יכרות להם ברית עולם יבדילו שלש הערים האלה
@524 **לא תחוס עינך עליו** . שלא תאמר הראשון כבר נהרג למה אנו הורגין את זה ונמצאו שנים הרוגין לשון רש"י מספרי (שופטים קפז) והטעם שלא תאמר כאשר נחוס על דם ההרוג טוב שנחוס על דם החי והנכון כי הכתוב יצוה בחייבי המיתות ובערת הרע מקרבך והיא מצות עשה אבל במרובי התקלות יזהיר עוד במצות לא תעשה שלא ינצלו מידינו לא מפני מוראם ולא שניתן להם רחמים וכך הזכיר במסית (לעיל יג ט) ואמר מכשפה לא תחיה (שמות כב יז) מפני היותה רבת המהומה המוכרת רבים בכשפיה וקצותה את כפה לא תחוס עינך (להלן כה יב) מפני כי הפתאים יהללו אותה בהיותה עוזרת לבעלה או מפני שהבושת מצוי ואין בו חסרון כיס וכן בעדים זוממין צוה (להלן פסוק כא) שלא ירחמו עליהם בעבור שלא נעשה בעדותם דבר או מפני שתקלתם מרובה וטעם וטוב לך כי ביעור הדם הנקי מצוה וטובה גדולה לך להציל ממות נפשך כי הרחמנות על הרוצחים שפיכות דמים מידי הרוצחים ומידי אחרים המתפרצים
@525 **לא תסיג גבול רעך** . אזהרה שלא ישנה תחום החלוקה שחלקו הנשיאים את הארץ לשבטים או ליחיד מהם ועל כן אמר אשר גבלו ראשונים הם אלעזר הכהן ויהושע בן נון ונשיאי המטות ולכך הזכיר בנחלתך אשר תנחל וגו' וטעם המצוה הזאת שלא יחשוב אדם לומר אין חלקי אשר נתנו לי שוה כמו חלק חברי כי טעו החולקים או שיוציא בלבו לעז על הגורלות ולא יהיה זה בעיניו גזל כלל על כן צוה בכאן שלא יחלוק אדם על החלוקה ההיא ולא ישנה הגבולין כלל לא בסתר ולא בגלוי וזו מצוה מבוארת ממה שצוה (במדבר כו נו) על פי הגורל תחלק נחלתו בין רב למעט ואמר (שם לד יז) אלה שמות האנשים אשר ינחלו לכם וגו' ועל דעת רבותינו (ספרי שופטים קפח) שהוא אזהרה לעוקר תחומו של חבירו בארץ שעובר בשני לאוין יהיה טעם "אשר גבלו ראשונים" שלא ישנה התחום הישן בסתר ויאמר בכאן היה מעולם והזהיר הכתוב בהווה כי התחום החדש ניכר וידוע הוא ואין אדם משנה אותו וגם רבותינו עצמם הזכירו (שם) מנין לעוקר תחומין של שבטים שעובר בלא תעשה תלמוד לומר לא תסיג גבול רעך והוא באמת פשוטו של מקרא
@529 **ודרשו השפטים היטב והנה עד שקר העד** . לא פירש הכתוב איך יודע שהוא עד שקר כי בהיות הענין בשני עדים שמעידין על הדבר אפילו יבואו מאה ויכחישו אותם לא יתברר ששקר ענו ולא נוכל לומר שבא הרוג ברגליו כי לא יאמר בזה ודרשו השופטים היטב ועל כן באה הקבלה הנאמנת ופירשה כי ההזמה תהיה כשיאמרו והלא ביום פלוני עמנו הייתם (מכות ה) והטעם מפני שהעדות הזו היא על גופם של עדים והם אינם נאמנים על עצמם לומר לא עשינו כך שהרי יכולים הללו לומר עליהם שהרגו את הנפש או שחללו את השבת
@530 **כאשר זמם** . ולא כאשר עשה מכאן אמרו הרגו אין נהרגין לשון רש"י מדברי רבותינו (מכות ה) והטעם בזה בעבור כי משפט העדים הזוממין בגזרת השליט שהם שנים ושנים והנה כאשר יבואו שנים ויעידו על ראובן שהרג את הנפש ויבואו שנים אחרים ויזימו אותם מעדותם צוה הכתוב שיהרגו כי בזכותו של ראובן שהיה נקי וצדיק בא המעשה הזה אילו היה רשע בן מות לא הצילו השם מיד ב"ד כאשר אמר (שמות כג ז) כי לא אצדיק רשע אבל אם נהרג ראובן נחשוב שהיה אמת כל אשר העידו עליו הראשונים כי הוא בעונו מת ואילו היה צדיק לא יעזבנו ה' בידם כמו שאמר הכתוב (תהלים לז לג) ה' לא יעזבנו בידו ולא ירשיענו בהשפטו ועוד שלא יתן ה' השופטים הצדיקים העומדים לפניו לשפוך דם נקי כי המשפט לאלהים הוא ובקרב אלהים ישפוט והנה כל זה מעלה גדולה בשופטי ישראל וההבטחה שהקב"ה מסכים על ידם ועמהם בדבר המשפט וזה טעם ועמדו שני האנשים אשר להם הריב לפני ה' (פסוק יז) כי לפני ה' הם עומדים בבואם לפני הכהנים והשופטים והוא ינחם בדרך אמת וכבר הזכרתי מזה בסדר ואלה המשפטים (שמות כא ו)
@533 **כי תצא למלחמה וגו' וראית סוס ורכב וגו'** . זו מצוה מחודשת אמרה להם עתה בבואם במלחמות וטעם כי ה' אלהיכם ההלך עמכם להלחם לכם עם איביכם להושיע אתכם יזהירם שלא ירך לבבם ולא ייראו מן האויבים ויאמר שלא יבטחו בזה בגבורתם לחשוב בלבם גבורים אנחנו ואנשי חיל למלחמה רק שישיבו לבם אל השם ויבטחו בישועתו ויחשבו כי לא בגבורת הסוס יחפץ ולא בשוקי האיש ירצה כי רוצה ה' את יראיו את המיחלים לחסדו ואמר להלחם לכם עם אויביכם כי יפילם לפניכם לחרב ואמר להושיע אתכם שהם ינצלו במלחמה ולא יפקד מהם איש כי יתכן שינצחו את אויביהם וימותו גם מהם רבים כדרך המלחמות ועל כן צעק יהושע בנפול מהם בעי כשלשים וששה איש (יהושע ז ז-ט) כי במלחמת מצוה שלו לא היה ראוי שיפול משערת ראשם ארצה כי לה' המלחמה והנה הכהן שהוא העובד את השם יזהירם ביראתו ויבטיחם אבל השוטרים ידברו בנוהג שבעולם פן ימות במלחמה כי בדרך הארץ בכל המלחמות ימותו אנשים גם מכת הנוצחים וצוה על השלשה האלה לשוב כי לבו על ביתו וכרמו ועל אשתו וינוס
@538 **וטעם ולא חללו** . שלא באה השנה הרביעית כי המנהג בכרם בבוא תבואתו שיחולו שם וילכו בו בחלילים וצוה הכתוב (ויקרא יט כד) שיהיה כל פריו קדש הלולים שיהללו את השם הנכבד בשמחה ההיא ויתכן שיהיה פירוש "ולא חללו" שלא עשאו חולין והוא הפדיון שהזכירו רבותינו (מעשר שני פ"ה מ"ד) מלשון כי חילל יהודה קודש ה' (מלאכי ב יא) ולא יחלל זרעו (ויקרא כא טו)
@540 **ויספו השטרים לדבר אל העם ואמרו מי האיש הירא** . על דעת רבי יוסי הגלילי (סוטה מד) כאשר הבטיח הכהן שהשם יושיעם ולא יפקד מהם איש ראוי שיבטחו בו הצדיקים ויזהירו השוטרים את היראים מעבירות שבידם ולכך תלתה לו התורה לחזור על ביתו וכרמו ואשתו לכסות על האחרים שחוזרין בשביל העבירות ויהיה טעם "פן ימות" שהוא יחשוב בלבו כן וינוס ועל דעת רבי עקיבא הוא כמשמעו כי מי שירא אחר הבטחת הכהן איננו בוטח בה' כראוי ולא יעשה לו הנס וטעם "ורך הלבב" שאינו בטבעו לראות מכת חרב והרג כי "הירא" הוא אשר לא יבטח ויחזיר אותו מפני מיעוט בטחונו ו"רך הלבב" מפני חולש טבעו כי ינוס או יתעלף ואמרו בירושלמי (סוטה פ"ח ה"ט) שכולם צריכים להביא ראיה לדבריהם כלומר שיביאו עדים על הבית ועל הכרם והאשה לפני שר הצבא ואז יתן לו רשות לחזור וכן אמרו גם לדעת רבי יוסי הגלילי שצריך להביא ראיה על העבירה שבידו ולולי כן היו מרבית העם חוזרים בטענות שקר אבל לדברי רבי עקיבא ברכות הלב שאיננו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה אמר שאין צריך להביא ראיה שעדיו עמו
@540 "ולא ימס את לבב אחיו" - עשאו בעל הלכות גדולות מצות לא תעשה שלא ימנע מלשוב שלא ימס את לבב אחיו כלבבו והוא כדרך ולא יאכל את בשרו (שמות כא כח)
@541 **ופקדו שרי צבאות בראש העם** . כי התורה תצוה בדרך הארץ ותעשה הנסים עם יראיו בהסתר ואין החפץ לפניו לשנות טבעו של עולם זולתי כאשר אין שם דרך בהצלה אחרת או להודיע שמו לצריו לעתים כאשר היה בקריעת ים סוף וכיוצא בו
@542 **כי תקרב אל עיר להלחם עליה וגו'** . במלחמת הרשות הכתוב מדבר כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחוקות ממך מאד לשון רש"י כתב הרב זה מספרי (שופטים קצט) ששנו שם כלשון הזה במלחמת הרשות הכתוב מדבר והכונה לרבותינו בכתוב הזה אינה אלא לומר שהפרשה בסופה תחלק בין שתי המלחמות אבל קריאת השלום אפילו במלחמת מצוה היא שחייבים לקרא לשלום אפילו לשבעה עממים שהרי משה קרא לשלום לסיחון מלך האמורי ולא היה עובר על עשה ועל לא תעשה שבפרשה כי החרם תחרימם (פסוק יז) ולא תחיה כל נשמה (פסוק טז) אבל הפרש שביניהם כאשר לא תשלים ועשתה מלחמה שצוה הכתוב ברחוקות להכות את כל זכורה ולהחיות להם הנשים והטף בזכרים ובערי העמים האלה צוה להחרים גם הנשים והטף וכך אמרו רבותינו במדרש אלה הדברים רבה (ה יג) והוא עוד בתנחומא ובגמרא ירושלמי (שביעית פ"ו ה"א) אמר רבי שמואל ברבי נחמני יהושע בן נון קיים הפרשה הזו מה עשה יהושע היה שולח פרוסדיטגמא בכל מקום שהיה הולך לכבוש והיה כותב בה מי שמבקש להשלים יבוא וישלים ומי שמבקש לילך לו ילך לו ומי שמבקש לעשות מלחמה יעשה מלחמה הגרגשי פנה הגבעונים שהשלימו עשה להם יהושע שלום שלשים ואחד מלכים שבאו להלחם הפילם הקב"ה וכו' וכך אמר הכתוב בכולם (יהושע יא יט כ) לא היתה עיר אשר השלימה אל בני ישראל בלתי החוי יושבי גבעון את הכל לקחו במלחמה כי מאת ה' היתה לחזק את לבם לקראת המלחמה את ישראל למען החרימם מכלל שאם רצו להשלים היו משלימים עמם ונראה שיש הפרש עוד בשאלת השלום שבערים הרחוקות נשאל להם לשלום ושיהיו לנו למס ויעבדונו אבל בערי (הערים) העמים האלה נשאל להם לשלום ומסים ועבדות על מנת שיקבלו עליהם שלא לעבוד ע"ז ולא הזכיר הכתוב זה בפרשה הזאת שכבר נאסר לנו בעובדי ע"ז (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי כי תעבוד את אלהיהם ויתכן שלא נצטרך להודיע להם רק השלום והמסים והשעבוד ואחרי שיהיו משועבדים לנו נגיד להם שאנו עושים משפטים בע"ז ובעובדיה בין יחיד בין רבים וכן מה שנאמר כאן (פסוק יח) למען אשר לא ילמדו אתכם לעשות ככל תועבותם ואמרו בספרי (שופטים רב) הא אם עשו תשובה אינן נהרגים בשבעת עממים הוא והתשובה הוא שיקבלו עליהם שבע מצות שנצטוו בני נח לא שיתגיירו להיותם גרי צדק ובמסכת סוטה אמרו (לה) שכתבו התורה על האבנים בשבעים לשון וכתבו למטה למען אשר לא ילמדו אתכם לעשות הא אם עשו תשובה מקבלים אותם ורש"י פירש שם להודיע לאומות היושבים חוץ מגבולם של ארץ ישראל שלא נצטוו להחרימם אלא על אותן שבתוך הגבולים כדי שלא ילמדו אותם מעשה קלקולם אבל אותם היושבים חוצה לה אומרים להם אם אתם חוזרים בתשובה נקבל אתכם ושבתוכה אין מקבלין אותם שמחמת יראה הם עושים וזה לשון הרב ואינו נכון כי בערי העמים האלה אשר ה' אלהיך נותן לך נחלה בהם אמר "למען אשר לא ילמדו אתכם" שאם עשו תשובה אינן נהרגין וכן אמר בהם (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי כי תעבד את אלהיהם הא אם עזבו את אלהיהם מותרין לישב שם וזה הענין שעשה המלך שלמה שכתוב בו (מלכים א ט טו-כב) וזה דבר המס אשר העלה המלך שלמה לבנות את בית ה' ואת ביתו ואת המלוא ואת חומת ירושלים וגו' כל העם הנותר מן האמורי החתי הפרזי החוי והיבוסי בניהם אשר נותרו אחריהם בארץ אשר לא יכלו בני ישראל להחרימם ויעלם שלמה למס עובד עד היום הזה ומבני ישראל לא נתן שלמה עבד והענין הזה כתורה עשאו כי קבלו עליהם שבע מצות ודבר ברור הוא כי כיון שנתנם שלמה עושי מלאכתו גברה ידו עליהם ויכול היה להחרימם אלא שהיה מותר לקיימם כמו שכתבנו
@543 **למס ועבדוך** . עד שיקבלו עליהם מסים ושעבוד לשון רבינו שלמה ובספרי (שופטים ר) אמרו מקבלין אנו עלינו מסים ולא שעבוד שעבוד ולא מסים אין שומעין להם עד שיקבלו עליהם זו וזו וענין המסים שיעלה עליהם מלך ישראל או הסנהדרין מס לבנות בית למלך וערי המסכנות אשר לו וכן לבנין בית השם והשעבוד הוא שיוכל כל איש מישראל ליקח מהם לחטוב עציו ולשאוב מימיו ונותן לו שכר הראוי וזה טעם "למס עובד" הכתוב בשלמה (מלכים א ט כא) שקבלו עליהם מסים ועבדות כדין התורה לא כענין שכתוב (שופטים א כח) ויהי כי חזק ישראל וישם את הכנעני למס והורש לא הורישו כי שם איננו מזכיר עבדות אבל כמלך שנותן שוחד למלך תקיף ממנו שלא ילחם בו ודע כי ענין אנשי גבעון היה מפני שלא היו יודעין משפטם של ישראל בקריאת השלום והקדימו קודם שתבא להם פרוסדיטגמא של יהושע ולכך אמרו (יהושע ט כד) ונירא מאד לנפשותינו או שלא רצו מתחילה לשמוע לדברי יהושע ובסוף פחדו ועשו עצמם נכרים דכתיב (שם פסוקים ג ד) ויושבי גבעון שמעו את אשר עשה יהושע ליריחו ולעי ויעשו גם המה בערמה והיה מועיל להם עוד שלא יהיו להם לעבדים אלא יהיו עמם בעלי ברית ומפני זה הקפידו עליהם והיו נהרגין אלמלא שבועת הנשיאים מפני שהיה עליהם לקבל מסים ושעבוד כמו שאמרנו והם כרתו להם ברית להיותם שוים להם ובעלי ברית ועוזרים זה לזה במלחמותיהם ועשו עמהם שלום לפי שהיו סבורין שהם ערים רחוקות מאד מן העמים שאין דעתם לבא עליהם כלל ולפיכך קלל אותם יהושע ואמר (שם פסוק כג) ועתה ארורים אתם שהם מן העמים הארורים אשר אררם ה' ועשה להם כמשפט הראוי להעשות בהם לקיים מה שנאמר למס ועבדוך שיהיו חוטבי עצים ושואבי מים לעדה ולמזבח ה' והוא המס והשעבוד כמו שפירשנו ויש אומרים כי פירוש והיה אם שלום תענך בעת הקריאה אבל אם מאנו מתחילה שוב אין מקבלין אותם והגבעונים מאנו בפרוסדיטגמא ולא היה הדין לקבלם והרב רבי משה כתב (הל' מלכים פ"ו ה"ה) שהקפידו עליהם מפני שכרתו להם ברית והרי הוא אומר (שמות כג לב) לא תכרות להם ולאלהיהם ברית ואינו נכון בעיני כי הגבעונים בודאי קבלו עליהם שלא לעבוד ע"ז כמו שאמרו (יהושע ט ט) באו עבדיך לשם ה' אלהיך ולכך לא הוצרך יהושע אחרי כן לומר להם שיקבלו עליהם לעבוד את השם כיון שכן מותרין היו בברית ההוא כמו שהיו מותרין בישיבת הארץ ששתיהן לא נאסרו אלא קודם התשובה כמו שאמר (שמות כג לג) פן יחטיאו אותך לי וכן אמר לא תכרות להם ולאלהיהם ברית אבל הדבר כמו שאמרנו
@550 **וטעם אשר לא ילמדו אתכם לעשות ככל תועבתם אשר עשו לאלהיהם** . שילמדו אתכם לעבוד השם הנכבד בשריפת בניכם ובנותיכם וכל תועבת ה' אשר שנא וחטאתם לה' אלהיכם שהוא הזהיר אתכם שלא תאמר איכה יעבדו הגוים האלה את אלהיהם ואעשה כן גם אני (לעיל יב ל) והנה התורה הזהירה (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי כי תעבוד את אלהיהם כי יהיה לך למוקש והיא אזהרה בעובדי כוכבים כי אם תכרות להם ולאלהיהם ברית ישבו בארצך ורבים מהם יפתוך לעבוד ע"ז וכאן הוסיף לבאר שלא תחיה כל נשמה כי אפילו היחיד הנשאר ביניכם לעבוד לך יזכיר לך עבודתם לאלהיהם ואולי תתפתה אתה לעשות כן לשם הנכבד ותחטא לפניו יתברך
@551 **כי האדם עץ השדה** . יפה פירש רבי אברהם כי שיעור הכתוב כי ממנו תאכל כי האדם עץ השדה ואותו לא תכרות לבא מפניך במצור וטעם כי האדם עץ השדה כמו כי נפש הוא חובל (להלן כד ו) אבל על דעת רבותינו (ב"ק צא) מותר לכרות עץ מאכל לבנות מצור ולא אמרה תורה רק עץ אשר תדע כי לא עץ מאכל הוא וגו' אלא להקדים ולומר שאילן סרק קודם לאילן מאכל אם כן פירוש הפרשה לדעתם שהזהירה תורה לא תשחית את עצה לכרות אותם דרך השחתה שלא לצורך המצור כמנהג המחנות והטעם כי הנלחמים משחיתים בעיר וסביב הארץ אולי יוכלו לה כענין שנאמר (מלכים ב ג יט) וכל עץ טוב תפילו וכל מעיני מים תסתמו ואתם לא תעשו כן להשחיתה כי תבטחו בשם שיתן אותה בידכם כי האדם עץ השדה הוא ממנו תאכל ותחיה ובו תבוא העיר מפניך במצור לומר אתה תחיה ממנו אחרי שתכבוש העיר וגם בהיותך במחנה לבא מפניך במצור תעשה כן וטעם אותו תשחית וכרת כי מותר אתה לכרות אותו לבנות המצור וגם להשחיתו עד רדתה כי לפעמים תהיה ההשחתה צורך הכבוש כגון שיהו אנשי העיר יוצאים ומלקטין עצים ממנו או נחבאים שם ביער להלחם בכם או שהם לעיר למחסה ולמסתור מאבן נגף
@556 **אל נחל איתן** . קשה שלא נעבד לשון רש"י ורבותינו אמרו (סוטה מו) שהוא נאסר לחרוש ולזרוע בו לעולם אם כן הן אזהרות שהזורע או העובד בו עובר בלאו הזה והטעם אשר יוציאו אותו אל נחל איתן כי לא יעבד בו ולא יזרע לעולם וטעם ונגשו הכהנים בני לוי לאמר כפר לעמך ישראל אשר פדית (פסוק ח) ושיעור הכתובים ונגשו הכהנים בני לוי וכל זקני העיר ההיא הקרובים אל החלל ירחצו את ידיהם וענו ואמרו והרחיצה במקצת מן הנזכרים והעניה במקצתם כדרך ואכלת לפני ה' אלהיך מעשר דגנך תירושך ויצהרך וגו' (לעיל יד כג) וענין העריפה אמר ר"א שהשם צוה לעשות כן על העיר הקרובה כי לולי שעשו עבירה כדומה לה לא נזדמן שיהרג אדם קרוב מהם ומחשבות ה' עמקו לאין קץ אצלנו אבל הרב אמר במורה הנבוכים (ג מ) כי הטעם לגלות על הרוצח ולבער דמו בעבור שברוב הפעמים יהיה הרוצח מן העיר אשר סביבות החלל וכשיצאו הזקנים ויתעסקו במדידה ההיא וזקני העיר ההיא יעידו לפני הבורא שלא התרשלו בתקון הדרכים ושמירתם ושאינם יודעים מי הרג את זה וכשיחקר הענין יאספו הזקנים ויביאו העגלה ירבו בני אדם לדבר בו אולי יגלה הדבר וכבר אמרו (ירושלמי סוטה פ"ט ה"א) שאפילו תבוא שפחה ותאמר פלוני הוא הרוצח לא תערף ואם יודע הרוצח ויחרישו ממנו ויעידו הבורא על נפשותם כי לא ידעוהו יהיה בזה זדון גדול וכל השומע שמץ דבר בענין יבוא ויגיד ויתפרסם הדבר ויהרג או על ידי ב"ד או המלך או גואל הדם ויתחזק הענין בהיות המקום אשר תערף בו העגלה לא יעבד בו ולא יזרע לעולם יכירו בו רואיו וידברו בו והנה לפי הטעם הזה יש בתחבולה הזו תועלת אבל המעשה איננו נרצה בעצמו והיה ראוי עוד שיעשה בשדה טוב ראוי לזריעה שיכירו בו רואיו כי בנחל איתן לא יודע מדוע לא יעבד בו ולפי דעתי יש בו טעם כענין הקרבנות הנעשים בחוץ שעיר המשתלח ופרה אדומה ולפיכך מנו חכמים עגלה ערופה מכלל החוקים
@564 **ועשתה את צפרניה** . תגדלם כדי שתתנוול לשון רש"י כדברי רבי עקיבא (יבמות מח) וכן פירש אונקלוס והנה לדעתם יהיה "ועשתה" כמו ועשת את התבואה (ויקרא כה כא) כי הצמיחה תקרא עשייה אבל בספרי (תצא ז) אמר ראיה לדברי רבי אליעזר ולא עשה רגליו ולא עשה שפמו ( יט כה) והיא ראיה גדולה לכך אני אומר כי כל אלה משפטי אבלות והכל נמשך אל ובכתה את אביה ואת אמה (פסוק יג) וצוה שתגלח ראשה כדרך האבילות כענין ויגז את ראשו (איוב א כ) דאיוב וכן גזי נזרך (ירמיהו ז כט) וכן קציצת הצפרנים אבלות כגלוח הראש ואמר והסירה את שמלת שביה מעליה כלומר תלבש בגדי אבל וישבה בביתך כאלמנה ולא תצא חוץ כלל ובכתה את אביה ואת אמה ותעשה כל זה ירח ימים כי כן דרך האבלים ועל דעת רבותינו (ספרי תצא יא) שאומרים שהכל לכער את יפיה צוה שתסיר הבגדים הנאים מעליה שהגוים ארורים הם בנותיהם מתקשטות במלחמה כדי לזנות אחריהן ותגלח את ראשה שהוא נוול גדול ותקוץ הצפרנים כי מנהג הנשים לגדל אותם ולצבעם במיני הפוך והצבעונים ויקרא הכתוב הקציצה עשייה בעבור כי שער הרגלים והשפם גם הצפרנים לגדלם יקצצו אותם והנראה בעיני כי הוא לשון מקוצר הרגילו לקצר בדבר המובן וטעמו לא עשה את רגליו ואת שפמו המעשה הנעשה בהם ירמוז לגלוח שער הרגלים והשפם או לרחיצת הרגלים עצמן וכן דעת יונתן בן עוזיאל שאמר לא שטף ית רגליה ולא ספר שפמיה וכן ועשתה את צפרניה מעשה הצפרנים והמפרשים (עיין רש"י בראשית א ז) אמרו כי טעם עשיה תקון וכן וימהר לעשות אותו (שם יח ז) והטעם בפרשה הזו מפני שהיא מתגיירת בעל כרחה ואין שואלין אותה אם תחפוץ לעזוב דתה ולהתיהד כאשר נעשה בגרים אבל יאמר לה הבעל שתשמור תורת ישראל בעל כרחה ותעזוב יראתה וזה טעם ובכתה את אביה ואת אמה כי תעזוב את עמה ואת אלהיה והוא מדרשו של רבי עקיבא אין אביה אלא עבודת כוכבים כענין שנאמר (ירמיהו ב כז) אומרים לעץ אבי אתה ולאבן את ילדתני והכלל כי היא מתאבלת על עזבה את דתה ותהיה לעם אחר ויתכן שב"ד מטבילין אותה בעל כרחה כמו שעושים בעבדים ומפני שאינה מתיהדת כמשפט הרחיק אותה הכתוב כל הזמן הזה וטעם האבלות והבכי על דעת רבותינו כדי שתתנוול אולי יעבור חשקו ממנה ור"א אמר כי נתנה לה התורה זמן כמשפט הבוכים על מת לכבוד אביה ואמה שמתו במלחמה והרב אמר במורה הנבוכים (ג מא) לחמלה עליה שתמצא מנוח לנפשה כי יש לעצבים מנוח והשקט בבכייתם ואבלם ובזמן ההוא לא יכריחנה להניח דתה ולא יבעלנה ועל דעתי אין הפנאי לחמול עליה רק שיעקר שם ע"ז מפיה ומלבה ולכבות עוד גחלת הנדוד והפרוד מאביה ומאמה ומעמה שאין הגון לשכב עם אשה אנוסה ומתאבלת כמו שהזכירו רבותינו ז"ל (נדרים כ) בממזרים בני גרושת הלב וכל שכן זאת הצועקת בלבה לאלהיה להצילה ולהשיבה אל עמה ואל אלהיה והנה כאשר יודיעוה שנכריחנה לעזוב את עמה ומולדתה ותתיהד נאמר לה תתנחמי על אביך ועל אמך ועל ארץ מולדתך כי לא תוסיפי לראותם עוד עד עולם אבל תהי אשה לאדוניך כדת משה ויהודית והנה אז ניתן לה זמן שתבכה ותתאבל כמשפט המתאבלים להשקיט ממנה צערה ותשוקתה כי בכל עצב יהיה מותר וניחום אחרי כן והנה בזמן הזה לקחה עצה בנפשה על הגירות ונעקר קצת מלבה ע"ז שלה ועמה ומולדתה כי נחמה עליהם ודבקה באיש הזה שידעה כי תהיה אליו והורגלה עמו ולכך אמר הכתוב והבאתה אל תוך ביתך ודרשו (ספרי ז) ביתך ולא אל בית אחר וכן וישבה בביתך שתשב כל הזמן הזה בבית שהוא משתמש בו (שם ט) אולי תחפוץ ותתרצה בו ועל הכלל כי זה כולו בעבור ההכרח אבל אם רצתה להתגייר בחפץ נפשה בבית דין כמשפט הרי היא מותרת מיד גם לו גם לאביו ולאחיו וכך אמרו בפרק החולץ (יבמות מז) ובכתה את אביה ואת אמה ירח ימים במה דברים אמורים שלא קבלה עליה אבל קבלה עליה מטבילה ומותרת מיד ואפשר כי בכל השבויות במלחמה נעשה כתורה הזאת כי מפני היראה תאמרנה להתגייר ואמר (פסוק יד) ושלחתה לנפשה שתעשה כרצונה ולא נכריחנה לשמור דת משה ויהודית כי המתגיירת ברצון נכריח אותה לשמור התורה ואם תחלל השבת תסקל ואם תאכל החזיר תלקה כדין ישראל המשתמד וגם זאת אם הודית בפיה הגירות בלא הכרח לא נשלח אותה לנפשה שאפילו נחשב שהיתה גירותה מפני היראה דינה כישראלית גמורה שכבר העלינו (יבמות כד) הלכה כולם גרים הם
@565 **ואחר כן תבוא אליה ובעלתה** . אמרו בספרי (תצא יג) אין לך בה אלא מצות בעילה נתכוונו לומר שאין קדושי כסף ושטר תופסין בה וגם הבעילה לא לשם קדושין שדינה עדיין כעובדת כוכבים שאין קדושין תופסין בה אלא שיתיר לו הכתוב בעילתה ומפני שאמר והיתה לך לאשה יורה שהיא אשתו גמורה ואם זנתה תחתיו תדון כאשת איש וכך אמרו בגמרא במסכת קידושין (כב) ולקחת לך לאשה ליקוחין יש לך בה כלומר אחר המעשים הללו ובספרי (שם) והיתה לך לאשה כענין שנאמר שארה כסותה ועונתה לא יגרע א"כ היא אשתו לגמרי כי התורה הקנתה אותה לו ועל דרך הפשט יראה שאסור לבעול אותה עד שיעשה כל התורה הזאת וזה טעם ואחר כן תבוא אליה ובעלתה ומה שאמר וחשקת בה ולקחת לך לאשה שיקחנה להיות לו לאשה אחר המעשים האלה אשר יצוה וכן ואקח אותה לי לאשה (בראשית יב יט) אבל בגמרא במסכת קידושין (כא) אמרו שהוא מותר לבוא עליה ביאה ראשונה וזהו ולקחת לך לאשה ודרשו (שם כב) והבאתה אל תוך ביתך מלמד שלא ילחצנה במלחמה יחברו אותה למעלה ולקחת לך לאשה כשתביאנה אל תוך ביתך והנה הוא שובה אותה במלחמה ומביאה אל ביתו ואל עירו ובועל אותה לשבור את לבו הזונה ואחרי הביאה הראשונה תאסר עליו עד שיעשה לה את כל התורה הזאת וזה דרך הגמרא במקומות רבים אבל ראיתי בירושלמי במסכת סנהדרין (עי' ירושלמי מכות ב ו) רבי יוחנן שלח לרבנין דתמן תרין מילין אתון אמרין בשם רב ולית אינון כן אתם אומרים בשם רב יפת תואר לא הותרה אלא בעילה ראשונה בלבד ואני אומר לא בעילה ראשונה ולא שנייה אלא לאחר כל המעשים הללו ואחר כן תבוא אליה ובעלתה אחר כל המעשים האלו וזהו משמעותו של מקרא
@566 **ושלחתה לנפשה** . אמרו בספרי (תצא יד) ולא לבית אביה ולא ידעתי אם לומר שהיא יהודית ואין מניחין אותה לעזוב תורת ישראל ולשוב אל עמה ואל אלהיה או לומר שלא ישלחנה לבית אביה על ידי שלוחים כי יסייע ידי עוברי עבירה אבל הוא יוציאנה מביתו לגור באשר תמצא כי אולי תשאר בארץ ותלך אחרי הבחורים ותנשא לאחד מהם והנה כיון שהכתוב אומר שישלחנה לנפשה ומזהיר שלא ימכרנה בכסף ולא יתעמר בה כשפחה נלמוד שאינה צריכה ממנו גט אבל הכתוב עשה אותה אשת איש בהיותה עמו וכאשר ישנא אותה ישלחנה כאנוסה ויתכן כי טעם הכתוב לומר שאם יבעלנה ויחפוץ בה תהיה לו לאשה אבל אם יבעלנה ולא תהיה ערבה עליו ולא יחפוץ בה כענין אמנון עם תמר ( יג טו) ישלחנה לנפשה והכל תלוי בבעילה הזאת כי אם אחרי בעילתה תעמוד עמו ימים ויבא עליה אם יחזור וישנא אותה כאיש אשר ישנא את אשתו כבר נעשית אשתו והנה היא יהודית ומתגרשת בגט לא תתעמר בה כמו והתעמר בו ומכרו (להלן כד ז) ועשאו אונקלוס לשון סחורה ורבותינו בספרי (תצא טז) ובגמרא (סנהדרין פה) יעשו אותם לשון שמוש והנה הוא לשון אזהרה שלא ישתמש בה כשפחה כלל ואם נשתמש בה לוקה והנראה בעיני לפי פשוטו כי לא תתעמר הוא כמו לא תתאמר מלשון יתאמרו כל פועלי און (תהלים צד ד) וכן את ה' האמרת היום (להלן כו יז) וכן ובכבודם תתימרו (ישעיהו סא ו) בחלוף האל"ף ביו"ד וכלם רוממות וגדולה האמרת היום רוממת וגדלת אותו להיות לך לאלהים האמירך היום (להלן כו יח) רומם וגדל אותך על כל העמים להיות לו לעם סגולה וכולם נגזרו מן בראש אמיר (ישעיהו יז ו) יאמר לא תתרומם ותתגדל בה להיות אתה אדוניה למוכרה ולהשתמש בה כשפחה וכן יקראו בערבי האדון אמיר ושמוש העי"ן והאל"ף כאחד מורגל בלשון פדעהו מרדת שחת (איוב לג כד) פדאהו כמו שפירשתי (במדבר יב ד) במלת פתע וכן מעשה צעצועים (דהי"ב ג י) כמו באל"ף מן הצאצאים והצפיעות (ישעיהו כב כד) הבנים והבנות כי תרגום כרובים כרביא ובלשון חכמים עומדות אומדות בקיאין בקיעין עדין אדין עורכי הדיינין ארכי עריס אריס ושנינו (שבת עו) חלב כדי גמיעה ושאלו בגמרא (שם עז) גמיעה או גמיאה ותרצו הגמיאיני נא מעט מים (בראשית כד יז) ואעפ"כ אומרים ממנו מגמע לא יגמע ופולט אבל מגמע ובולע (שם קיא) ובמשנה במסכת כלים בתוספתא שנינו מרדא במקום מרדע ואין מקפידין כלל בחלוף שתי אותיות הללו וכן במקומות רבים ורש"י כתב לא תתעמר בה לא תשתמש בה בלשון פרסי קורין לעבודה ושמוש עמירה מיסודו של רבי משה הדרשן למדתי זאת וזה אמת שכן ראיתי בירושלמי תמן צווחין לפעלא טבא עמירא בפרק אמר רבי עקיבא (שבת פ"ט ה"א) ובפרק כל הצלמים (ע"ז פ"ג ה"ו) ומורגל הוא אף בלשון ארמי כמו שכתוב במגלת שושן ושדר מלכא דאתור על כולהון עמירה דנינוה ועל כל דעמרין על יד ימא ועל עמור דכרמלא ודגלעד ואהפיכו פתגמא דנבוכדנצר כולהון עמורייא דארעא ולא תדחלון מיניה וכן במקומות רבים בספר ההוא יקראו יושבי הארץ "עמורי ארעא" כלומר הנעבדים לארץ והמשתמשין בה או שצוה מלך אשור על אנשי המלחמה והם הנקראים "עבדי הארץ" כי הם הנעבדים למלך במלחמותיו הם אנשי מלחמתו ופרשיו כלשון עבדו את כדלעומר (בראשית יד ד) ועבדו בו גוים רבים (ירמיהו כז ז) תחת אשר עניתה אמרו בספרי (תצא טז) אפילו לאחר מעשה יחידי והוא מה שהזכרנו (בפסוק יג) שהם סבורים שמותר לבא עליה ביאה ראשונה מיד שהביאה אל תוך ביתו ומאותה שעה הוא מוזהר עליה בעמור ובמכירה
@568 **לא יוכל לבכר את בן האהובה** . אזהרה שלא יעשה זה וכן כולם לא תוכל לאכול בשעריך (לעיל יב יז) לא תוכל לתת עליך איש נכרי (לעיל יז טו) ואמר אונקלוס בכולם לית לך רשו והטעם לא תתן יכולת לנפשך לעשות ככה והוא מפליג באזהרה וכן כי את הבכר בן השנואה יכיר לתת לו פי שנים מצות עשה שינחילנו פי שנים והנה המשוה את הבכור לאחיו בנחלתו עובר בלא תעשה ועשה ואע"פ שאין דבריו קיימים בדין וכל שכן אם לא רצה להודיע שהוא הבכור וטען שהוא פשוט והנחילו כאחד מבניו מדעתו שהוא הבכור שעובר בהן ואלו מצות מחודשות וממה שאמר הכתוב "על פני בן השנואה הבכור" יראה לי שאין המצוה הזאת והדין הזה נוהג אלא בחיי הבכור אבל אם מת הבכור בחיי אביו אע"פ שהוא יורש חלק בכורתו בקבר ומורישו מן הדין לבניו אם רצה הזקן ואמר יירשו בני כך וכך בנכסי ובניו של בני הבכור יטלו כך וכך בנכסי דבריו קיימין כדרך שהם קיימים במקום שאין שם בכור וכן איננו עובר בלאו הזה אם לא הכיר הבכור לאחר מותו כי לא מצאתי "על פני" רק בחייו על פני אהרן אביהם (במדבר ג ד) על פני תרח (בראשית יא כח) וכן כולם
@570 **בן סורר ומורה** . על דעת רבותינו (סנהדרין סח) אינו קטן שהקטן פטור מכל עונשין שבתורה ומכל המצות אבל הוא המביא שתי שערות והנה יש עליו שני עונשין האחד שהוא מקלה אביו ואמו וממרה בהם והשני שהוא זולל וסובא עובר על מה שנצטוינו (ויקרא יט ב) קדושים תהיו ונאמר עוד (לעיל יג ה) ואותו תעבודו ובו תדבקון כאשר פירשתי (לעיל ו יג) שנצטווינו לדעת השם בכל דרכינו וזולל וסובא לא ידע דרך ה' ועל הכלל אין בו עתה חטא מות ועל שם סופו הוא נדון כמו שהזכירו רבותינו (סנהדרין עא) וזה טעם וכל ישראל ישמעו ויראו כי לא הומת בגודל חטאו אלא ליסר בו את הרבים ושלא יהיה תקלה לאחרים וכן דרך הכתוב שיזהיר כן כאשר ימיתו לגדר כדי שתהיה במיתתם תקנה לאחרים כי הזכיר כן בזקן ממרא (לעיל יז יג) לפי שאין בהוראתו חטא שיהיה ראוי למות בו רק הוא להסיר המחלוקת מן התורה כאשר פירשתי שם (בפסוק יא) וכן בעדים זוממין (לעיל יט כ) שנהרגין ולא הרגו וכן הזכיר במסית (לעיל יג יב) לפי שהוא נהרג בדבורו הרע בלבד אע"פ שלא עבד הניסת ע"ז ולא שמע אליו אבל מיתתו ליסר הנשארים וגם זו מצוה מחודשת או מבוארת מן כבד את אביך ואת אמך (שמות כ יב) ואיש אמו ואביו תיראו (ויקרא יט ג)
@574 **ותלית אתו** . "אמרו רבותינו (סנהדרין מא א): "כל הנסקלין - נתלין". וזה שנאמר "כי קללת אלהים תלוי" - זלזולו של מלך, שהאדם עשוי בדמות דיוקנו של מלך, וישראל בניו הם. משל לשני אחים דומים זה לזה וכו'", לשון רש"י.
@574 ו"כל הנסקלים נתלין" דברי יחיד הם, והלכה כדברי חכמים (שם) שאינו נתלה אלא המגדף והעובד עבודה זרה. וזה טעם (דברים כא כג): "כי קללת אלהים תלוי", שיאמרו, מפני מה זה תלוי? - מפני שבירך את השם או שעבד עבודה זרה פלונית בכך וכך עבודה, וכך וכך אות ומופת ראה בה. והסיפור בה ובעבודתה ייקרא קללה.
@574 או שהוא לשון זילזול, כאשר הזכיר הרב, מן (מלכים א ב ח): "והוא קללני קללה נמרצת", (שמואל א ג יג): "כי מקללים להם בניו", בוזים.
@574 והמשל בשני האחים התאומים יש לו סוד, איננו כאשר חשב הרב בישראל שנקראו בנים למקום.
@574 ועל דרך הפשט יאמר: כי יהיה באיש חטא גדול שראוי להמיתו עליו ולתלותו על עץ לגודל חטאו, אף על פי כן לא תלין נבלתו על העץ, כי הארור מכל האדם והמקולל בהם הוא התלוי, אין בכל המיתות מיתה מנוולת ובזויה כמוה, ואין ראוי שנטמא הארץ ותהיה קללת האלהים בארץ הקדושה, כי שם ציווה את הברכה חיים עד העולם.
@574 ולכן צוה יהושע (יהושע י כ): "ויורידום מעל העצים".
@574 ועל דעתי, הענין בבני שאול המוקעים (שמואל ב כא) מפני שלא היו תלויים בבית דין של ישראל ולא מיד ישראל כלל, אבל דוד נתנם לגבעונים לעשות בהם כרצונם, והם אשר הוקיעום ולא רצו לקברם, לפרסם נקמתם מהם והנשארים ישמעו וייראו. וכאשר נתך עליהם מים מן השמים, אז ידע דוד שנמחל עונם, ונעתר אלהים לארץ, כי פקד ה' את הארץ במטר ויכלה הרעב, ואז צוה וקברו אותם עם אבותם, לכבוד המלכות, לא לחיובו כלל, שלא נצטוינו אלא שלא נטמא אנחנו את הארץ במי שנתלה אותו. והנה, ה' לא רצה עוונם בתלייתם מיד, להודיע כי ה' אוהב גרים, כדברי רבותינו (יבמות עט).
@574 ורבי אברהם אמר: על דרך הפשט, כי אלהים פועל, והקללה תבוא אל מקום קרוב מהתלוי, ויש לו סוד מודבק בנפש, על כן לא תטמא את אדמתך.
@574 והנה, המלין תלוי על העץ עובר בלא תעשה ועשה. ורבותינו (סנהדרין מו) דרשו כן בכל המלין את מתו שלא לכבודו: "מה עץ שהוא נוול אף כל שהוא נוול". והנה, לדעתם "כי קללת אלהים תלוי" לומר, אע"פ שזה ראוי לנוולו לגודל חטאו לא תעשה כן, כי קללת אלהים תלוי.
@574 ועל המשל של שני אחין יהיה כל המלין בטעם הזה, וכן הקללה שהזכיר רבי אברהם ממנה יהיה בכל בית אשר יהיה שם מת, ועל כן יטמא (במדבר יט יד): "כל הבא אל האהל וכל אשר באהל".
@574 "ולא תטמא את אדמתך" - על דעת רבותינו, איננו טעם בלבד בעבור שלא תטמא את אדמתך, שאם-כן יהיה מותר בחוצה לארץ, אבל הוא לאו שני.
@574 והנה, המלין התלוי או אפילו המת בארץ עובר בשני לאוין ועשה, ובחוצה לארץ בעשה ולא תעשה אחד, שהוא למד מן התלוי כאשר פירשתי. ומן הלאו הזה קבר יהושע מלכי כנען ביומן, אף על פי שאין בתלייתן הקללה שהזכירו רבותינו במגדף ועובד עבודה זרה, אבל היה בהם משום טומאת הארץ. או שחשש לקללת אלהים מן המשל של שני האחים, כאשר פירשתי.
@576 **לא תראה את שור אחיך או את שיו נדחים** . זו מצוה מבוארת שאמר בתורה (שמות כג ד) כי תפגע שור אויבך או חמורו תועה השב תשיבנו לו והוסיף בכאן לאמר "נדחים" כי "תועה" שתעה מדרכו ויכול להטותו הדרך בלא עמל גדול ועתה הזכיר "נדחים" שברחו ממנו והרחיקו והזכיר "שה" שהוא כאבד ולכך ביאר בכאן ואם לא קרוב אחיך אליך ולא ידעתו ואספתו אל תוך ביתך ואמר וכן תעשה לחמורו שהוא בהמה טמאה וכן תעשה לשמלתו אע"פ שאין השמלה חביבה על בעליה כבעלי החיים ואין ההפסד בה מצוי כבהם שאפשר שימותו וכן תעשה לכל אבדת אחיך מכל כלי ביתו אף על פי שאינן חביבין כשמלתו אשר יכסה בה ועל מדרש רבותינו (ספרי מה ב"מ ל) הוסיף עוד בכאן דברים רבים כגון והתעלמת פעמים שאתה מתעלם השב אפילו מאה פעמים (ב"מ לא) תשיבם אפילו לגנתו ולחרבתו (שם) והחזירה בסימנים ודברים אחרים נדרשים בפרשה
@577 **ואם לא קרוב אחיך אליך** . שאינו קרוב אצלך כי אינך מתחייב ללכת אל ארץ אחרת עם האבדה להשיבה אליו או שלא ידעת אותו כלל ובספרי (תצא מז) אין לי אלא קרוב רחוק מנין תלמוד לומר ולא ידעתו וא"כ יאמר ואם לא קרוב אחיך אליך בעירך שתשאל עליו ותדענו יהיה עמך עד דרוש אחיך אותו
@581 **כי יקרא קן צפור לפניך** . גם זו מצוה מבוארת מן אותו ואת בנו לא תשחטו ביום אחד (ויקרא כב כח) כי הטעם בשניהם לבלתי היות לנו לב אכזרי ולא נרחם או שלא יתיר הכתוב לעשות השחתה לעקור המין אע"פ שהתיר השחיטה במין ההוא והנה ההורג האם והבנים ביום אחד או לוקח אותם בהיות להם דרור לעוף כאלו יכרית המין ההוא וכתב הרב במורה הנבוכים (ג מח) כי טעם שלוח הקן וטעם אותו ואת בנו לא תשחטו ביום אחד כדי להזהיר שלא ישחוט הבן בעיני האם כי יש לבהמות דאגה גדולה בזה ואין הפרש בין דאגת האדם לדאגת הבהמות על בניהם כי אהבת האם וחנותה לבני בטנה איננו נמשך אחרי השכל והדבור אבל הוא מפעולת כח המחשבה המצויה בבהמות כאשר היא מצויה באדם ואם כן אין עיקר האיסור באותו ואת בנו רק בבנו ואותו אבל הכל הרחקה ויותר נכון בעבור שלא נתאכזר ואמר הרב ואל תשיב עלי ממאמר החכמים (ברכות לג) האומר על קן צפור יגיעו רחמיך כי זו אחת משתי סברות סברת מי שיראה כי אין טעם למצות אלא חפץ הבורא ואנחנו מחזיקים בסברא השניה שיהיה בכל המצות טעם והוקשה עליו עוד מה שמצא בב"ר (מד א) וכי מה איכפת לו להקב"ה בין שוחט מן הצואר לשוחט מן העורף הא לא נתנו המצות אלא לצרף בהם את הבריות שנאמר (משלי ל ה) כל אמרת אלוה צרופה וזה הענין שגזר הרב במצות שיש להם טעם מבואר הוא מאד כי בכל אחד טעם ותועלת ותקון לאדם מלבד שכרן מאת המצוה בהן יתברך וכבר ארז"ל (סנהדרין כא) מפני מה לא נתגלו טעמי תורה וכו' ודרשו (פסחים קיט) ולמכסה עתיק זה המגלה דברים שכסה עתיק יומין ומאי ניהו טעמי תורה וכבר דרשו בפרה אדומה (במדב"ר יט ג ד) שאמר שלמה על הכל עמדתי ופרשה של פרה אדומה חקרתי ושאלתי ופשפשתי אמרתי אחכמה והיא רחוקה ממני (קהלת ז כג) ואמר ר' יוסי בר' חנינא אמר לו הקב"ה למשה לך אני מגלה טעם פרה אדומה אבל לאחרים חקה דכתיב (זכריה יד ו) והיה ביום ההוא לא יהיה אור יקרות וקפאון יקפאון כתיב דברים המכוסים מכם בעולם הזה עתידין להיות צפויים לעולם הבא כהדין סמיא דצפי דכתיב (ישעיהו מב טז) והולכתי עורים בדרך לא ידעו וכתיב (שם) אלה הדברים עשיתים ולא עזבתים שכבר עשיתים לר' עקיבא הנה בארו שאין מניעות טעמי תורה ממנו אלא עורון בשכלנו ושכבר נתגלה טעם החמורה שבהם לחכמי ישראל וכאלה רבות בדבריהם ובתורה ובמקרא דברים רבים מודיעין כן והרב הזכיר מהן אבל אלו ההגדות אשר נתקשו על הרב כפי דעתי ענין אחר להם שרצו לומר שאין התועלת במצות להקב"ה בעצמו יתעלה אבל התועלת באדם עצמו למנוע ממנו נזק או אמונה רעה או מדה מגונה או לזכור הנסים ונפלאות הבורא יתברך ולדעת את השם וזהו "לצרף בהן" שיהיו ככסף צרוף כי הצורף הכסף אין מעשהו בלא טעם אבל להוציא ממנו כל סיג וכן המצות להוציא מלבנו כל אמונה רעה ולהודיענו האמת ולזוכרו תמיד ולשון זו האגדה עצמה הוזכרה בילמדנו (תנחומא שמיני ח) בפרשת זאת החיה וכי מה איכפת לו להקב"ה בין שוחט בהמה ואוכל או נוחר ואוכל כלום אתה מועילו או כלום אתה מזיקו או מה איכפת לו בין אוכל טהורות או אוכל טמאות אם חכמת חכמת לך (משלי ט יב) הא לא נתנו המצות אלא לצרף את הבריות שנאמר (תהלים יב ז) אמרות ה' אמרות טהורות ונאמר כל אמרת אלוה צרופה למה שיהא מגין עליך הנה מפורש בכאן שלא באו לומר אלא שאין התועלת אליו יתעלה שיצטרך לאורה כמחושב מן המנורה ושיצטרך למאכל הקרבנות וריח הקטרת כנראה מפשוטיהם ואפילו הזכר לנפלאותיו שעשה שצוה לעשות לזכר ליציאת מצרים ומעשה בראשית אין התועלת לו רק שנדע אנחנו האמת ונזכה בו עד שנהיה ראויים להיות מגן עלינו כי דבורנו וזכרנו בנפלאותיו מאפס ותוהו נחשבו לו והביא ראיה מן השוחט מן הצואר והעורף לומר שכולם לנו ולא להקב"ה לפי שלא יתכן לומר בשחיטה שיהא בה תועלת וכבוד לבורא יתברך בצואר יותר מהעורף או הניחור אלא לנו הם להדריכנו בנתיבות הרחמים גם בעת השחיטה והביאו ראיה אחרת או מה איכפת לו בין אוכל טהורות והם המאכלים המותרים לאוכל טמאות והם המאכלים האסורים שאמרה בהם התורה (ויקרא יא כח) טמאים המה לכם ורמז שהוא להיותנו נקיי הנפש חכמים משכילי האמת ואמרם אם חכמת חכמת לך הזכירו כי המצות המעשיות כגון שחיטת הצואר ללמדנו המדות הטובות והמצות הגזירות הגדורות במינין לזקק את נפשותינו כמו שאמרה תורה (שם כ כה) ולא תשקצו את נפשותיכם בבהמה ובעוף ובכל אשר תרמוש האדמה אשר הבדלתי לכם לטמא א"כ כלם לתועלתנו בלבד וזה כמו שאמר אליהוא (איוב לה ו) אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו ואמר (שם פסוק ז) או מה מידך יקח וזה דבר מוסכם בכל דברי רבותינו ושאלו בירושלמי בנדרים (פ"ט ה"א) אם פותחין לאדם בכבוד המקום בדברים שבינו לבין המקום והשיבו על השאלה הזאת אי זהו כבוד המקום כגון סוכה שאיני עושה לולב שאיני נוטל תפילין שאיני מניח והיינו כבוד המקום משמע דלנפשיה הוא דמהני כהדא אם צדקת מה תתן לו או מה מידך יקח אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו הנה בארו שאפילו הלולב והסוכה והתפילין שצוה בהן שיהו לאות על ידך ולזכרון בין עיניך כי ביד חזקה הוציאך ה' ממצרים אינן לכבוד ה' יתברך אבל לרחם על נפשותינו וכבר סדרו לנו בתפלת יום הכפורים אתה הבדלת אנוש מראש ותכירהו לעמוד לפניך כי מי יאמר לך מה תעשה ואם יצדק מה יתן לך וכן אמר בתורה (לעיל י יג) לטוב לך כאשר פירשתי (שם פסוק יב) וכן ויצונו ה' לעשות את כל החקים האלה ליראה את ה' אלהינו לטוב לנו כל הימים (לעיל ו כד) והכוונה בכלם לטוב לנו ולא לו יתברך ויתעלה אבל כל מה שנצטוינו שיהיו בריותיו צרופות ומזוקקות בלא סיגי מחשבות רעות ומדות מגונות וכן מה שאמרו (ברכות לג) לפי שעושה מדותיו של הקב"ה רחמים ואינן אלא גזרות לומר שלא חס האל על קן צפור ולא הגיעו רחמיו על אותו ואת בנו שאין רחמיו מגיעין בבעלי הנפש הבהמית למנוע אותנו מלעשות בהם צרכנו שאם כן היה אוסר השחיטה אבל טעם המניעה ללמד אותנו מדת הרחמנות ושלא נתאכזר כי האכזריות תתפשט בנפש האדם כידוע בטבחים שוחטי השורים הגדולים והחמורים שהם אנשי דמים זובחי אדם אכזרים מאד ומפני זה אמרו (קידושין פב) טוב שבטבחים שותפו של עמלק והנה המצות האלה בבהמה ובעוף אינן רחמנות עליהם אלא גזירות בנו להדריכנו וללמד אותנו המדות הטובות וכן יקראו הם כל המצות שבתורה עשה ולא תעשה גזירות כמו שאמרו (מכילתא בחדש ו) במשל המלך שנכנס למדינה אמרו לו עבדיו גזור עליהם גזירות אמר להם כשיקבלו מלכותי אגזור עליהם גזירות כך אמר הקב"ה קבלתם מלכותי אנכי ה' אלהיך (שמות כ ב) קבלו גזירותי לא יהיה לך וכו' (שם פסוק ג) אבל במדרשו של רבי נחוניא בן הקנה בשלוח הקן מדרש שיש במצוה סוד אמר רבי רחמאי מאי דכתיב שלח תשלח את האם ולא אמר את האב אלא שלח תשלח את האם בכבוד אותה בינה שנקראת אם העולם דכתיב (משלי ב ג) כי אם לבינה תקרא מאי ואת הבנים תקח לך אמר רבי רחמאי אותם בנים שגדלה ומאי ניהו שבעת ימי הסוכה ודיני שבעת ימי השבוע וכו' והנה המצוה הזאת רומזת לענין גדול ולכך שכרה מרובה למען ייטב לך והארכת ימים
@583 **ועשית מעקה** . מצות המעקה מחודשת או מבוארת מלא תעמוד על דם רעך (ויקרא יט טז) אבל מצות הכלאים מבוארת שכבר אמר (שם פסוק יט) שדך לא תזרע כלאים והנה במשמע ההוא כל מקום הנזרע והוסיף בכאן כי אם יזרע הכרם כלאים יקדש הזרע אשר יזרע ותבואת הכרם לומר שיאסר בהנאה כהקדש וטעם "פן" כמו כי תקדש וכן ומפתח אהל מועד לא תצאו פן תמותו (שם י ז) וכן ולא תגעו בו פן תמותון (בראשית ג ג) ויתכן שפירושו כמו פן ינכרו צרימו פן יאמרו ידינו רמה (להלן לב כז) כענין שמא לומר לא תזרע אותו כלאים פן יצמח ויאסר עליך הכל כי אינן נאסרין אלא כמו ששנינו (כלאים פ"ז ה"ז) תבואה מתקדשת משתשריש וענבים משיעשו כפול הלבן
@585 **ואמר לא תחרש בשור ובחמר** . והוא הדין לכל מיני הכלאים והיא מצוה מבוארת מן בהמתך לא תרביע כלאים (ויקרא יט יט) שדרך כל עובד אדמתו להביא צמדו ברפת אחת וירכיב אותן וביאר בשעטנז שאיננו רק בצמר ופשתים והזכיר לא תלבש ללמד שאין העליה אסורה אלא בענין לבישה
@588 **כי יקח איש אשה ובא אליה ושנאה** . טעמו: כאשר יקח האיש אשה בלקוחי התורה, שהם הקדושין בכסף, והיא המאורסה אשר יזכיר (פסוק כג);
@588 ואחרי ימים בא אליה ושנאה, שלא היתה עריבה אליו בביאתה;
@588 והשכים בבקר ובא לבית-דין וטען שלא מצאה בתולה; והנה זה מתכוין להוציאה בלא מוהר הבתולות, שהיא הכתובה שכתב לה, ומפני כי בחזקת בתולה נתקדשה אליו הוא טוען עליה שזנתה תחתיו;
@588 ולפיכך אמר הכתוב (דברים כב כ): "ואם אמת היה הדבר" כדברי הבעל, "וסקלוה"; והאמת לא יודע רק על פי שנים עדים.
@588 ולפי שהכתוב יפרש בזנוני הבתולות, כי כאשר תהיה מאורסה תסקל וכאשר לא אורסה היא פטורה, לא הוצרך לפרש כאן "ואם אמת היה שזינתה בארוסיה ושזינתה ברצונה וסקלוה", ואמר ברמז (דברים כב יא): "כי עשתה נבלה בישראל לזנות בית אביה", והנבלה היא בעשותה כן לרצונה.
@588 ו"לזנות" הוא כאשר תשטה אשה תחת אישה, כי הנערה אשר לא אורשה לא תקרא "זונה" בשכבה עם אחד העם, אבל היא מיועדת לו (שמות כב טו).
@592 **ופרשו השמלה** . הרי זה משל מחוורין הדברים כשמלה לשון רש"י והוא מדרשו של רבי ישמעאל בספרי (תצא רלז) ובמכילתא (משפטים יג) ואין צורך כי זאת לפנים בישראל מכניסין החתן והכלה לחופה ובודקין אותן והעדים משמרים להם מבחוץ והם שהחכמים קורין להם שושבינין וכאשר יפרדו נכנסין העדים שם ולוקחין השמלה אשר שכב אותה עליה ויראו הדמים וזה ידוע בתלמוד (כתובות מו ירושלמי שם פ"א ה"א) ובספרי אגדה וקורין השמלה ההיא סודר ולכך יאמר הכתוב שיפרשו אביה ואמה השמלה אשר לקחו מיד העדים ויאמרו אלה בתולי בתי ובודאי שצריך לחוור הדברים בענינים הרבה שהכתוב יקצר בהם אבל לא אמר הרי זה משל אלא המחייב מוציא שם רע אע"פ שלא בעל ופשוטו של מקרא כדברי האומר עד שבעל וכך אמרו בגמרא (שם מו) רבי אלעזר בן יעקב אומר שמלה ממש והלכה כדבריו וכן טעם הפרשה כי אמר הכתוב תחלה ולקח אבי הנערה ואמה והוציאו את בתולי הנערה ידבר בשניהם ואחר כן שב לאב לבדו ואמר אבי הנערה וגו' וחזר ואמר ופרשו השמלה בשניהם והטעם כי התביעה הזאת לאב לבדו הוא שהקנס שלו אבל שתף האם במעשה מפני שענין השמלה הנשים יתעסקו בה והן היודעות והבקיאות בדמים ולאם ראוי שתתפוש ותביא אותה לב"ד אבל טענת "את בתי נתתי לאיש הזה" לאב בלבד היא והאם לאו בעלת דברים דידיה היא או אחר שיסדר האב טענותיו בב"ד יתפוש בשמלה אשר הביאה אשתו תחת כנפות כסותה ויפרשו אותה שניהם בב"ד והנה לא הוזכרה האם בפרשה ולא באה לב"ד כלל אלא מפני ענין השמלה שהוא ממש כאשר פירשתי
@594 **וטעם וענשו אתו מאה כסף** . אחרי המלקות הנדרש מ"ויסרו אותו" (כתובות מו) כי המנהג לכתוב לבתולה מוהר חמשים כסף והנה זה הוציא עליה שם רע בעבור ששנאה ורצה להוציאה בלא כלום ולכן ענשו הכתוב במאה כסף כי התורה תעניש בכפל כענין שנים ישלם (שמות כב ג) אע"פ שהכתובה מדבריהם למי שיתנה עמה או ישאנה סתם אבל המנהג היה לכתוב מוהר לבתולות כמו שנאמר (שם שם טז) כמהר הבתולות והרוב יעשו כן ואם לא היתה כתובה לאשה הזאת למה ישים עליה עלילות דברים מפני שבא עליה ושנאה יכתוב לה גט ויפטר ממנה דכתיב (מלאכי ב טז) כי שנא שלח
@597 **ומתו גם שניהם** . להוציא לעושה מעשה חדודים שאין האשה נהנית מהם גם לרבות הבאים אחריהם לשון רבינו שלמה ולא הבינותי מהו וכי בתולה היא זו שנמעט או נצטרך לרבות הבאים אחריהם מה לי ראשון מה לי שני ושלישי ועוד היה לו לומר הבאים אחריו ובנוסחאות שלנו בספרי (תצא קב) שניהם ולא העושה מעשה חדודין כשהוא אומר גם שניהם לרבות הבאים מאחוריהם והיא ביאה שלא כדרכה וריבה אותה הכתוב בכאן וכל העריות למדות זו מזו ועל דרך הפשט גם שניהם האיש הפושע בחטא יותר שהוא התובע והמפתה והעושה מעשה וגם האשה והזכיר זה הכתוב ופירש גם שניהם האיש השוכב וגם האשה וכן דרך הכתובים לתלות החטא באיש כאשר פירשתי (ויקרא כ יז) בערות אחיו גלה ערירים יהיו ויש אומרים כי טעם האיש השוכב עם האשה והאשה תוספת ביאור כמו יביאה את תרומת ה' (שמות לה ה) אותו את נבוכדנצר (ירמיהו כז ח) ובספרי (שם) האיש השוכב עם האשה אע"פ שהיא קטנה והאשה אע"פ שנבעלה לקטן אם כן טעמו גם שניהם גם כל אחד מהם האיש או האשה המגיע מהם לחיוב
@598 **על דבר אשר ענה את אשת רעהו** . ולא יקרא ענוי רק השוכב באונס וזו כבר חייב אותה כמזנה לרצון אבל ענין הכתוב כי כאשר נראה שהאיש אוחז בה ושוכב עמה נדון האשה כמתרצה בעבור שהיתה יכולה להושע ממנו ונחשב האיש כמענה אותה כי לא פתה ולא דבר על לבה להשמע אליו ולא ידעתי בדין הצעקה אם ראינו נערה שהחזיק בה האיש והיא נלחמת בו בכל כחה ובוכה ואוחזת בבגדיו או בשערותיו להמלט ממנו ולא ידעה לצעוק למה תסקל אלא גם הצעקה בהווה לדון בה מן הסתם בעיר מפותה ובשדה אנוסה
@607 **ממזר** . שם לאיש מוזר מאחיו ויודעיו שלא יודע מאין בא כלשון וישב ממזר באשדוד והכרתי גאון פלשתים (זכריה ט ו) יאמר שלא ישב באשדוד זולתי איש נכרי וזר שיעבור בו כי יכרית גאון פלשתים ממנו והנה הנולד לאיש מאשת אביו הוא ירחיק אותו ולא יודה בו לבשתו ולכלמתו מן המעשה הרע שעשה וגם אמו תשליכנו בלילה כענין האסופי הנזכר בתלמוד (קידושין סט) והנה הוא ממזר בעיר מולדתו וכן כל העריות כדברי רבותינו בקדושין ירושלמי (פ"ג הי"ד) אמר ר' אבהו מהו ממזר מום זר
@609 **על דבר אשר לא קדמו אתכם בלחם ובמים** . מצינו (לעיל ב כח כט) אכל בכסף תשבירני ואכלתי ומים בכסף תתן לי ושתיתי כאשר עשו לי בני עשו היושבים בשעיר והמואבים היושבים בער ורבים אמרו שהם לא קדמו אותם אבל ישראל קנו מהם וזה הבל כי די למחנה שימכרו להם כאשר ירצו לקנות ועוד כי ישראל לא באו בגבול מואב והמואבים הוציאו להם לחם ומים בכסף והכתוב יספר שעשו המואבים כאשר עשו בני עשו ולמה ירחיק המואבי לעולם בעבור זה ולא יתעב האדומי ור"א אמר (לעיל ב כט) כי טעם כאשר עשו לי בני עשו והמואבים על אעברה בארצך בדרך (שם פסוק כז) אבל לא מכרו להם לחם ומים כי הם עברו בהר שעיר ובער רק מלך אדום לא הניחם לעבור דרך מדינתו אשר הוא יושב בה והוא מה שאמר (במדבר כ יח) לא תעבר בי גם זה הבל כי הם אמרו אל מלך אדום אעברה בארצך וימאן אדום נתן את ישראל עבור בגבולו (שם פסוק כא) הנה לא נכנסו כלל בגבול אדום וכן כתוב (שם כא ד) ויסעו מהר ההר דרך ים סוף לסבב את ארץ אדום כי הוצרכו לשוב לאחור דרך ים סוף מהר ההר שהוא על גבול ארץ אדום ולא באו בארץ אדום עצמה כלל ויפתח אמר בביאור (שופטים יא טז-יח) כי בעלותם ממצרים וילך ישראל במדבר עד ים סוף ויבא קדשה וישלח ישראל מלאכים אל מלך אדום לאמר אעברה נא בארצך ולא שמע מלך אדום וגם אל מלך מואב שלח ולא אבה וישב ישראל בקדש וילך במדבר ויסב את ארץ אדום ואת ארץ מואב וגו' ויחנון בעבר ארנון ולא באו בגבול מואב הנה זה מפורש שלא באו כלל בארץ אדום ולא בארץ מואב ואלו באו שם היו מוכרין להם לחם ומים כי אין המנהג לנותן רשות לעם הצבא לעבור בארצו שלא ימכר להם לחם ומים והנראה אלי כי הכתוב הרחיק שני האחים האלה שהיו גמולי חסד מאברהם שהציל אביהם ואמם מן החרב והשבי (בראשית יד טז) ובזכותו שלחם השם מתוך ההפכה (שם יט כט) והיו חייבין לעשות טובה עם ישראל והם עשו עמהם רעה האחד שכר עליו בלעם בן בעור והם המואבים והאחד לא קדם אותו בלחם ובמים כאשר קרבו למולו כמו שכתוב (לעיל ב יח יט) אתה עובר היום את גבול מואב את ער וקרבת מול בני עמון והנה הכתוב הזהירם (שם פסוק יט) אל תצורם ואל תתגר בם והם לא קדמו אותם כלל כי היה הכתוב אומר "כאשר עשו לי בני עשו המואבים והעמונים" אבל לא הזכיר עמון שלא קדמו אותם והנה עמון הרשיע בזה יותר מכולם כי בני עשו והמואבים כאשר ידעו שהוזהרו ישראל שלא יתגרו בהם הוציאו לחם ומים חוץ לגבולם ועמון לא אבה לעשות כן וזה טעם "אשר לא קדמו" שלא יצאו לקראתם בלחם ובמים כאשר עשו האחרים ולכך הקדים הכתוב "עמוני" והקדים להזכיר פשעו על דבר אשר לא קדמו אתכם ואחרי כן הזכיר "מואבי" וחטאתו ורבותינו דרשו (יבמות עו) עמוני ולא עמונית מואבי ולא מואבית מפני שהאיש דרכו לקדם ואין האשה דרכה לקדם שתוציא מזון חוץ לגבול הארץ וכן הזכירו בירושלמי (שם פ"ח ה"ג) ובמגילת רות רבתי (ד ח) מפני שדרך האיש לשכור ואין דרך האשה לשכור
@611 **לא תדרש שלמם** . מכלל שנאמר (להלן פסוק יז) עמך ישב בקרבך יכול אף זה כן ת"ל לא תדרוש שלומם לשון רש"י והמדרש הזה בספרי (תצא רנא) מטובתם מכלל שנאמר שם בטוב לו לא תוננו הוציא את אלו מאותה טובה אבל לא תדרוש שלומם נדרש בספרי לפי שנאמר (לעיל כ י) כי תקרב אל עיר וקראת אליה לשלום יכול אף עמון ומואב כן ת"ל לא תדרוש שלומם וכן בתנחומא והנראה אלי כי מלחמת עמון ומואב אסרה הכתוב עלינו לדורות והכתוב שאמר (לעיל ב ט יט) "אל תתגר בם" אינה מצוה לשעה בלבד אבל היא מצות לא תעשה לדורות זהו שאמר (שם) כי לבני לוט נתתיה ירושה והנה ארצם להם לעולם כי היא נחלה שהנחילם השם אם כן הכתוב שאמר "לא תדרוש" יצוה אם נלחם עליהם בעיר שכבשו הם מן העמים שלא נקרא להם לשלום וכן אם יבואו הם להלחם בארצנו מותר לנו לרדוף אחריהם ולכבוש מהם המדינות להכות יושבי הערים שעשו עמנו הרעה כמו שעשה יפתח (שופטים יא לג) ויכם מערוער ועד בואך מנית עשרים עיר וכן עשה דוד לכל ערי בני עמון ( יב לא) בעבור שהם פרצו הגדר תחלה ונלחמו בו ואז לא נצטרך לקרא בשלומם ונכה בנלחמים בנו כל עיר מתים הנשים והטף אם נרצה ואמרו במדרש רבה (במדב"ר כא ו) והכיתם כל עיר מבצר וכל עיר מבחור וכל עץ טוב תפילו וכל מעיני מים תסתומו (מלכים ב ג יט) אמרו לו הכתוב אומר (לעיל כ יט) לא תשחית את עצה ואתה אומר כן אמר להם על כל האומות צוה וזו קלה ובזויה היא שנאמר (מלכים ב ג יח) ונקל זאת בעיני ה' ונתן את מואב בידכם שנאמר לא תדרוש שלומם וטובתם אלו אילנות טובים וכל זה להזיקם ולצערם אבל הארץ תשאר למשפחה ההיא שהיא נחלה שהנחילם השם וזה הענין מוזכר באגדות בבראשית רבה (עד יג) ובמדרש תילים (ס א) ועל דרך הפשט טעם לא תדרוש שלומם וטובתם כאומר אע"פ שהם בני משפחתכם ואברהם אביכם אהב את אביהם כאח לו יונק שדי אמו לא תהיו אתם לו כאחים דורשי שלום וטובה כי הם הפרו ברית אחוה ותהיה מופרת לעולם והנה השם שמר לבני לוט זכות אביהם שליוה את נביאו בדרך אשר שלחו ה' ולכך הנחילם מנחלת אברהם והעניש את בניו בחטאם שלא ידבקו בישראל וכן המצרים הרחיקם שלשה דורות מפני רשעם אשר עשו עמנו רעות רבות וצרות אבל לא יתעב אותם לעולם בעבור שהיינו גרים בארצם ונמלטנו עמהם בימי הרעב בכבוד שעשו לאבינו והמליכו עליהם ממנו קצין ומושל וכן עשה עם אדום שמר להם זכות אבות שהיו מזרע קדש והרחיקם שלשה דורות בעבור שיצאו לקראתינו בחרב ולא זכרו ברית אחים והקבלה מן רבותינו (יבמות עח) כי אין דור שלישי מימי משה אבל כאשר יתגייר אחד מהם יבא הדור השלישי שלו בקהל ה'
@614 **ונשמרת מכל דבר רע** . שהשטן מקטרג בשעת הסכנה לשון רש"י והנכון בעיני בענין המצוה הזאת כי הכתוב יזהיר בעת אשר החטא מצוי בו והידוע במנהגי המחנות היוצאות למלחמה כי יאכלו כל תועבה יגזלו ויחמסו ולא יתבוששו אפילו בניאוף וכל נבלה הישר בבני אדם בטבעו יתלבש אכזריות וחמה כצאת מחנה על אויב ועל כן הזהיר בו הכתוב ונשמרת מכל דבר רע ועל דרך הפשט היא אזהרה מכל הנאסר ובספרי (תצא קיט) ונשמרת מכל דבר רע שומע אני בטומאות ובטהרות ובמעשרות הכתוב מדבר ת"ל ערוה אין לי אלא ערוה מנין לרבות עבודת גלולים וגלוי עריות ושפיכות דמים וקללת השם ת"ל ונשמרת מכל דבר רע או יכול בטומאות ובטהרות ובמעשרות הכתוב מדבר ת"ל ערוה מה ערוה מיוחדת מעשה שגלו עליו כנענים ומסלק את השכינה אף כל מעשה שגלו עליו כנענים ומסלק את השכינה כשהוא אומר "דבר" אף על לשון הרע וגם זה מן הטעם שפירשנו כי מלבד האזהרות שבאו באלה העבירות החמורות יוסיף לאו במחנה שנשמר בו מכל אלו העבירות שלא תסתלק השכינה מישראל אשר שם כאשר אמר כי ה' אלהיך מתהלך בקרב מחנך והנה העושה העבירות הגדולות במחנה כאותם שכתוב בהם (ירמיהו ז ל) שמו שקוציהם בבית אשר נקרא שמי עליו לטמאו ועוד שלא יגברו עלינו האויבים אם נעשה כמעשים הגורמים להם שיגלו מפנינו וזהו ולתת אויביך לפניך (שם) והוסיפו בו לשון הרע כדי שלא ירבו ביניהם מחלוקת ויכו ביניהם מכה רבה מאד יותר מן האויבים
@620 **וטעם לא תסגיר עבד אל אדניו** . דבק למעלה שאם יברח העבד מאדוניו אשר יצאת עליו מחנה וינצל אל מחנך לא תסגירנו לו בממון אשר יתן לך ולפי שאמר במקום אשר יבחר נראה שהוא מצוה שיהיה בן חורין ולא נעבוד בו אנחנו והטעם במצוה הזו כי עמנו יעבוד את השם ואיננו הגון שנחזירנו אל אדוניו לעבוד ע"ז ועוד שיתכן שילמד דרך מבוא העיר כי בענין כזה ילכדו מדינות רבות על ידי העבדים והשבויים הבורחים משם ורבותינו אמרו (גיטין מה) אפילו בעבד כנעני של ישראל שברח מחוצה לארץ לארץ שגם זה יעמוד לפני יושבי ארץ השם וינצל מעבוד היושבים על אדמה טמאה ושאין כל המצות נוהגות שם
@622 **לא תהיה קדשה מבנות ישראל** . מקודשת ומזומנת לזנות ולא יהיה קדש מבני ישראל מזומן למשכב לשון רש"י והנה אם הלאו הזה אזהרה באשה הנשכבת ויזהיר בהיותה מקודשת ומזומנת לזנות אם כן אין הפנויה הנבעלת במקרה ובהצנע מחייבי הלאוין וכן הקדש למה יזכיר בהיותו קדש ומזומן ואפילו הנבעל בחדרי חדרים יש בו כרת ומיתת ב"ד ועוד שהיה ראוי שיאמר לא תהיה בכם קדשה ולא יהיה בכם קדש כי "מבנות ישראל" ו"מבני ישראל" כאלו בעם אחר ידבר והנראה בעיני בלאו הזה כי הוא אזהרה לב"ד שלא יניחו אחת מבנות ישראל להיות יושבת בפרשת דרכים בעינים על הדרך לזמה או שתתקן לה קובה של זונות כמנהג ארצות זרים יושבות על הפתח בתופים ובכנורות כענין שכתוב (ישעיהו כג טז) קחי כנור סובי עיר זונה נשכחה הטיבי נגן הרבי שיר למען תזכרי וכן יזהיר לב"ד על הקדש ועל דרך הפשט אפילו שישכב עם הנשים בקובה אשר יעשה לו מזומנת לזמה או שישב בעינים על הדרך הזהירם לבית דין ויראה לי שכן דעת אונקלוס אבל צירף לזה העבד והשפחה הבאים בישראל דרך נשואין מפני שהכל יודעין בעבד הזה שנשא בת ישראל שאין לו בה קדושין והיא עמו כאשה עם בעלה אם כן היא קדשה לעיני השמש וראיתי בספרי (תצא קכו) לא תהיה קדשה מבנות ישראל אין אתה מוזהר עליה באומות ולא יהיה קדש אין אתה מוזהר עליו באומות שהיה בדין ומה אם קדשה קלה אתה מוזהר עליה בישראל קדש חמור אינו דין שתהא מוזהר עליו בישראל או חלוף אם קדש חמור אי אתה מוזהר עליו באומות קדשה קלה אינו דין שלא תהא מוזהר עליה באומות וכו' ונראה מזה שאין מדרשם כדברי אונקלוס שהרי לדבריו אין חומר בקדש יותר מן הקדשה ועוד מהו זה שאומרים אין אתה מוזהר עליו באומות וכן אם היה מדרשם בקדש לזכר הנשכב כמדרשו של רבי ישמעאל במסכת סנהדרין (נד) גם בזה לא יתכן שיאמרו אי אתה מוזהר עליו באומות שהנשכב מן הגוי בסקילה הוא אבל נראה שדעת בעל הברייתא הזו כענין שהזכרנו יזהיר לב"ד שלא תעמוד האשה על אם הדרך לזנות כי שם תנאפנה מאיסורי הביאות קרובים ורחוקים ולכן מכסות פניהן לזנות גם מאחיהם וקרוביהם והוא מה שאמר (בראשית לח טו) ויחשבה לזונה כי כסתה פניה וכן יזהיר לב"ד על המזומן להיות נשכב מן הזכרים כענין שכתוב (מלכים א יד כד) וגם קדש היה בארץ עשו ככל התועבות הגוים ומלבד האזהרה בעושי העבירה יזהיר כאן בבית דין שלא יניחו להיות קדש בעינים על הדרך כידוע מהם בארץ מצרים שעומדים על הדרך מכוסי הפנים כנשים לעשות התועבה הזאת ודרשו בברייתא הזו שאין אנו מוזהרים באחרים זולתנו אם יעשו עם רעיהם כן שלא הוזהרנו אנחנו בגוים אלא בענין ע"ז בלבד ולשון קדש וקדשה על דעת המפרשים לשון הזמנה כי מצאו אני צויתי למקודשי (ישעיהו יג ג) וכן הקדיש קרואיו (צפניה א ז) קדשו עליה מלחמה (ירמיהו ו ד) ולפי דעתי כולם מלשון קדושה כי הפורש מן הזנות נקרא קדוש כמו שנאמר (ויקרא כא ז) אשה זונה וחללה לא יקחו ואשה גרושה מאישה לא יקחו כי קדוש הוא לאלהיו והנה הנשמרת מן הערוה והזמה קדושה והנפרדת מן הקדושה ונטמאת בזמה נקראה קדשה קרוב למה שנוהג הלשון לומר ובכל תבואתי תשרש (איוב לא יב) ודשנו את המזבח (במדבר ד יג) כי הזונה המפורסמת טמאת השם רבת המהומה נפרדת מכל קדושה ואין שם זה בה רק בהיותה מזומנת לתועבה הזאת שאין לה שעת הכושר וקדושה כלל ולשון "הקדיש קרואיו" מליצה כי העושה משתה מקדש קרואיו ומטהר אותם שלא יטמאו השולחן והלחם כענין שאמר (שמואל א כ כו) בלתי טהור הוא כי לא טהור וכן (ירמיהו ו ד) קדשו עליה מלחמה שיטהרו אותם כמטהר קרואיו שלא יבדלו החברים מהם
@623 **לא תביא אתנן זונה** . הזונות יעשו באתנן שלהם מצות חושבות לכפר על חטאתן כמו שיזכירו רבותינו (ויק"ר ג א) במשל שלהן גייפא בתפוחייא ומפלגא לבאישייא ולכך אסרה תורה אתנן לכל נדר כי עתה יוסיפו לחטוא בהן וכן ענין מחיר כלב בעבור כי הצדים בכלבים ושומרי החומות יגדלו כלבים עזי נפש מזיקים את הרבים וידירו במחיריהם להיות כופר לנפשם וכן המנהג עד היום בפרשים אנשי הציד שיעמידו צורת כלביהם בשעוה לפני ע"ז שיצליחו בהם והמפרשים אמרו מפני שהוא דרך בזיון.
@623 ואמר (דברים כג יט): "גם שניהם" - לרבות שנוייהם, כגון חטין ועשאן סולת, לשון רש"י. אבל בגמרא (בבא קמא סה ב) אמרו, שבית שמאי אוסרין ובית הלל מתירין, אלא הם ולא ולדותיהם הם ולא שנוייהם.
@623 וטעם "גם שניהם", בעבור שהאחד באמת תועבה גדולה והוא האתנן כי בו נעשתה תועבת הזמה, אמר שגם שניהם יתעב ה';
@623 וכמוהו (משלי יז טו): "מצדיק רשע ומרשיע צדיק תועבת ה' גם שניהם", יתלה הקטן בגדול.
@623 וכן (דברים כב כב): "ומתו גם שניהם", כמו שפירשתי.
@623 או טעמו, שהזהיר כבר על פסולי הקרבן במומין ואמר בהם (דברים יז א): "לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום כל דבר רע כי תועבת ה' אלהיך הוא", הוסיף בכאן לומר כי גם האתנן והמחיר, שגופם תמים, גם הם תועבת ה' אלהיך כמותם, והוא הנכון.
@623 וכן (משלי כ יב): "אוזן שומעת ועין רואה ה' עשה גם שניהם", ירמוז לאדם בכללו, יאמר שה' יצר את האדם ועשה גם אלו בו.
@623 וכן (משלי כ י): "אבן ואבן איפה ואיפה תועבת ה' גם שניהם", ירמוז לגוזל וחומס וכל עושק, שהם תועבות גדולות מאלו ולא יזכירם.
@624 **לא תשיך לאחיך** . גם זו מצוה מבוארת (ויקרא כה לו לז) יוסיף בכאן אזהרה גם ללוה מה שאין כן בכל דיני ממונות שאם רצה הוא לזוק בנכסיו רשאי אבל מפני רגילות החטא הזה יזהיר בו גם הלוה וביאר בכאן שיהיה רבית הנכרי מותר ולא הזכיר כן בגזל ובגנבה כמו שאמרו (ב"ק קיג) גזל גוי אסור אבל הרבית שהוא נעשה לדעת שניהם וברצונם לא נאסר אלא מצד האחוה והחסד כמו שצוה (ויקרא יט יח) ואהבת לרעך כמוך וכמו שאמר (לעיל טו ט) השמר לך פן יהיה דבר עם לבבך בליעל וגו' ועל כן אמר למען יברכך ה' אלהיך כי חסד ורחמים יעשה עם אחיו כאשר ילונו בלא רבית ותחשב לו לצדקה וכן השמיטה חסד באחים לכך אמר (שם פסוק ג) את הנכרי תגוש וקבע לו ברכה כי הכתוב לא יזכיר הברכה רק בצדקה ובחסדים לא בגזל ובגנבה ובאונאה והזכיר נשך כסף נשך אכל לבאר שהלוה סאה חטין בסאה וחצי יהיה נשך גמור אפילו לא יהיה שוה סאה וחצי בעת הפרעון כדמי סאה שהלוהו וביאר עוד כל דבר אשר ישך אפילו באבני הבנין ושאר הנלוים אולי יעלה על הדעת שאין הנשך רק בכסף שכל הדברים נקנין בו ובאוכל שהוא חיי האדם אבל בשאר הדברים נלך אחר שום הכסף לעת ההלואה והפרעון ורבותינו (ספרי קכט) עשו "לנכרי תשיך" לאו הבא מכלל עשה באחיך מפני שהוא מיותר שכבר אמר לא תשיך לאחיך
@627 **וכי תחדל לנדר לא יהיה בך חטא** . בעבור שהמקריבים עולה וזבחים לאלהים יש להם שכר טוב כענין שכתוב (תהלים סו טו) עולות מחים אעלה לך עם קטרת אילים אעשה בקר עם עתודים סלה אבוא ביתך בעולות (שם פסוק יג) ואף בקרבנות הבאים בנדבה כתוב (ויקרא א ד) ונרצה לו לכפר עליו ואומר ריח ניחוח לה' ואם כן הרי הנדרים זרוז במצוה וכתוב (תהלים קטז יח) נדרי לה' אשלם נגדה נא לכל עמו לפיכך יאמר הכתוב השמר בנדריך כי אע"פ שהם זרוז בקרבנות השם אשר הם לך לרצון אם תדור תבא לידי חטא אם לא תשלם או שתאחר לשלמו ואם לא תדור לא תמצא חטא בענין כלל כי אפילו לא תקריב קרבן כל ימיך לא יהיה בך חטא אם כן תשמור מוצא שפתיך כאשר תוציא הדבר מפיך ועשית אחרי כן כאשר דברת להשלים כל אשר נדבה רוחך להוציא מפיך ועל הדרך הזה אמר שלמה (קהלת ה ג ד) כאשר תדר נדר לאלהים אל תאחר לשלמו כי אין חפץ בכסילים וגו' טוב אשר לא תדור משתדור ולא תשלם יאמר שאין חפץ בכסילים החושבים לעשות מצוה כאשר ידרו נדרים רבים להיות להם זרוז למצוה שחשבו לעשות ולא יחשבו בלבם ולא דעת ולא תבונה לאמר אולי לא תמצא ידי להשלים כל אלה אבל יחשוב כי הרצון אשר היה לו בעת נדרו יחשב לו לטובה ולפיכך יזהיר עוד (שם שם ה) אל תתן את פיך לחטיא את בשרך ואל תאמר לפני המלאך כי שגגה היא כלומר שלא תרבה בנדרים וכאשר לא תקריבם תאמר לפני המלאך האכזרי אשר ישולח בך כי שגגה היא שהייתי סבור להקריבם ובלב שלם נדרת אותם עתה לא מצאה ידך לעשות כן כי האלהים יקצוף על קול נדריך וחבל המלאך הנזכר את מעשה ידיך
@634 **אחרי אשר הטמאה** . לרבות סוטה הנסתרת לשון רש"י ופירושו אשה שזנתה תחת בעלה אבל הסוטה הנסתרת בלבד לא נודע שהיא טמאה ואינו עובר עליה בלאו הזה וכך מפורש בפרק ראשון של יבמות (יא) מאי ונסתרה נבעלה ואמאי קרי ליה נסתרה לישנא מעליא נקט ושאלו נבעלה בהדיא כתיב בה טומאה (במדבר ה יג) ונסתרה והיא נטמאה למיקם עלה בלאו ואם כן יאמר הכתוב לא יוכל בעלה הראשון אשר שלחה לשוב לקחתה ואחרי אשר הטמאה והנה הם שני לאוין יזהיר במחזיר גרושתו משנשאת ויזהיר במחזיר אשתו שנטמאה בזנות ועל דרך הפשט אחרי אשר הוטמאה לבעל הראשון ירמוז כי כאשר ידעה איש אחר תחשב לו טמאה ואלו מצות מחודשות בגט ובחזירה וטעם הלאו הזה כדי שלא יחליפו נשותיהן זה לזה יכתוב לה גט בערב ובבוקר היא שבה אליו וזה טעם ולא תחטיא את הארץ כי זה סבה לחטאים גדולים ובספרי (תצא קלו) ולא תחטיא את הארץ להזהיר ב"ד על כך
@635 **ולא יעבר עליו לכל דבר** . דבר הצבא לכל דבר שהוא צורך הצבא לא לספק מים ומזון ולא לתקן דרכים אבל החוזרים מעורכי המלחמה על פי כהן כגון בנה בית חדש ולא חנכו ארש אשה ולא לקחה מספיקין מים ומזון ומתקנין את הדרכים לשון רש"י מדברי רבותינו (ספרי קלז סוטה מד) ואם כן יהיה "עליו" על הצבא הנזכר יאמר שלא יעבור האיש הזה על הצבא לכל דבר לא להיות פקיד על אנשי הצבא או מצביא את עם הארץ או לכל הצריך להם כגון סיפוק מים לא ישגיח עליהם רק בשמחתו והוא פירוש נכון
@638 **השמר בנגע הצרעת** . גם זו מצוה מבוארת יוסיף לאו בקוצץ בהרתו או גם בנמנע מהראות נגעו לכהן ובדין הנגעים עצמם לא הזכיר כאן אלא הזהיר בכאן רק ככל אשר יורו אתכם הכהנים הלוים כאשר צויתים לפי שהכהנים זריזים הם ודי להם במה שצוה אותם כמו שפירשתי כבר (בתחלת הספר)
@639 **זכור את אשר עשה ה' אלהיך למרים** . אם באת ליזהר שלא תלקה בצרעת לא תספר לשון הרע לשון רש"י ולפי דעתי שהיא מצות עשה ממש כמו זכור את יום השבת לקדשו (שמות כ ח) זכור את היום הזה אשר יצאתם ממצרים (שם יג ג) זכור את אשר עשה לך עמלק (להלן כה יז) כולם מצוה אם כן גם זה כמותם והיא אזהרה מלדבר לשון הרע יצוה במצות עשה שנזכור העונש הגדול שעשה ה' לצדקת הנביאה שלא דברה אלא באחיה גמול חסדה אשר אהבתו כנפשה ולא דברה בפניו שיבוש ולא בפני רבים רק בינה לבין אחיה הקדוש בצנעה וכל מעשיה הטובים לא הועילוה גם אתה אם תשב באחיך תדבר בבן אמך תתן דופי לא תנצל ולשון ספרא (בחקותי פרשה א ב ג) כשהוא אומר ולא תעשו את כל המצות האלה (ויקרא כו יד) הרי מה שכתוב בתורה אמור אם כן למה נאמר ואם לא תשמעו לי להיות עמלים בתורה וכן הוא אומר זכור את יום השבת לקדשו יכול בלבך כשהוא אומר שמור הרי שמירת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך וכן הוא אומר זכור אל תשכח וגו' וכן הוא אומר זכור את אשר עשה ה' אלהיך למרים יכול בלבך כשהוא אומר השמר בנגע הצרעת לשמר מאד ולעשות (פסוק ח) הרי שמירת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך וכן הוא אומר זכור את אשר עשה לך עמלק יכול בלבך כשהוא אומר לא תשכח הרי שכחת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך ופירושה כי אצלם השמר בנגע הצרעת מנגע הצרעת לשמר מאד שלא תבואך ולעשות בה ככל אשר יורו אתכם הכהנים ו זכור את אשר עשה ה' אלהיך למרים שתהא מזכיר זה בפה תמיד ומכאן נראה שרבותינו יעשו אותה מצוה לא ספור ועצה בלבד להנצל מן הנגעים ואיך יתכן שלשון הרע שהוא שקול כשפיכות דמים לא תהיה בו בתורה לא תעשה גמור או לאו הבא מכלל עשה אבל בכתוב הזה אזהרה גדולה בו להמנע ממנו בין בגלוי בין בסתר בין במתכוין להזיק ולהבזות בין שאין מתכוין להזיק כלל וזו מצוה מכלל תרי"ג מצות ושכחה בעל הלכות גדולות וכל המונים המצות אחריו
@642 **ואם איש עני הוא** . יקרא עני כאשר אין לו עבוט אחר כיוצא בו הא אלו היו לו שני כלים מאותו המין נוטל אחד ומחזיר אחד בין שהוא עני או עשיר בנכסים רבים
@644 **לא תעשק שכיר עני ואביון** . ידבר הכתוב בהוה שהעניים והאביונים והגרים משכירים עצמם וכן אם כסף תלוה את עמי את העני עמך (שמות כב כד) וכן לגר ליתום ולאלמנה יהיה (להלן פסוק יט) שהם העניים ברוב וכן בהרבה מקומות ידבר בהוה כמו לא תחסם שור בדישו (להלן כה ד) לא תחרש בשור ובחמור יחדיו (לעיל כב י) ובספרי (תצא קמה) אמרו אם כן למה נאמר עני ואביון ממהר אני ליפרע על ידי עני ואביון יותר מכל אדם ודרשו מגרך זה גר צדק לעבור עליו בשני לאוין
@645 **וטעם ביומו תתן שכרו ולא תבוא עליו השמש** . על דרך הפשט ביאור ממה שנאמר בתורה (ויקרא יט יג) לא תלין פעולת שכיר אתך עד בקר כי דרך הכתובים לדבר בהוה והמנהג לשכור הפועל ביום אחד ולערב הוא יוצא טרם בא השמש ויצוה הכתוב לפרעו ביומו בהשלים מלאכתו מיד ושלא תבוא עליו השמש כדי שיקנה בשכרו לו ולאשתו ולבניו מה שיאכלו בלילה כי עני הוא כרובי הנשכרים ואל השכר הזה הוא נושא נפשו שיקנה בו מזון להחיות נפשו ילמד אותנו בכאן כי מה שאמר בתורה לא תלין פעולת שכיר אתך עד בקר הכונה בו שתפרענו ביומו שאם לא תפרענו בצאתו ממלאכתו מיד הנה ילך לביתו וישאר שכרו אתך עד בקר וימות הוא ברעב בלילה וכן כי היא כסותה לבדה היא שמלתו לעורו במה ישכב (שמות כב כו) יזכיר טעם המצוה ברובי הלאוין ורבותינו פירשו (ב"מ קי) כי הכתוב בתורה "עד בקר" בשכיר יום ושב לבאר בכאן דין שכיר לילה והנה לכל אחד זמן לפרעון שנים עשר שעות והוא האמת בקבלה והנאות בטעם נכון
@648 **וזכרת כי עבד היית** . על מנת כן פדיתיך לשמור חקותי אפילו בדבר שיש בו חסרון כיס לשון רש"י והנכון שהוא חוזר על אזהרת הגר וכבר פירשתי טעמו (שמות כב כ)
@653 **כי יהיה ריב בין אנשים** . על דרך קבלת רבותינו (מכות יג) שהמלקות הוא בחייבי הלאוין מה ענין לו בריב אשר בין שני האנשים האוכל נבלה בביתו לוקה וכן הזורע שדהו או כרמו כלאים והבא על אחת מהנשים האסורות בלאו וכל שאר הלאוין ועוד מה טעם והצדיקו את הצדיק לפיכך דרשוהו בעדים זוממין (שם ב) יאמר הכתוב כי כאשר יהיה ריב בין שני אנשים ונגשו אל המשפט ושפטום על פי שני עדים כאשר נצטוו ואחרי כן יצדיקו את הצדיק וירשיעו את הרשע שלא כמשפט הראשון והיה אם בן הכות הרשע שלא נוכל לקיים בו ועשיתם לו כאשר זמם לעשות לאחיו ויהיה זה כגון שהעידו עליו שהוא בן גרושה או עבד או ממזר או שהעידו עליו שעבר על אחד מן הלאוין ילקה ארבעים ויתכן שיהיה ריב בין אנשים וילקה בו כגון שחבל בו בפחות משוה פרוטה או שקלל חבירו בשם או שמשכן אותו בדברים שעושים בהם אוכל נפש וכיוצא בהם ודבר הכתוב בהווה כי בעל הריב יגישנו לבית דין ועל ידו ילקה וטעם הארבעים כפי מדרשו (תנחומא ישן במדבר כח) לפי שעבר על התורה שנתנה בארבעים יום וגרם מיתה לעצמו שנוצר לארבעים יום ילקה ארבעים ויצא ידי עונשין ענין היבום וסודו והחליצה וטעמה כבר הזכרתים (בראשית לח ח)
@658 **וטעם והיה הבכור אשר תלד יקום על שם אחיו המת** . איננו כפשוטו שיקראו הבן הראשון בשם המת ראובן או שמעון כמוהו שהרי בבעז נאמר כן (רות ד י) ולא יכרת שם המת מעם אחיו ומשער מקומו ולא קראו אותו מחלון אבל הכתוב הזה על דרך האמת הבטחה והנה הוא כפשוטו וסמכו בו רבותינו (ספרי קנו יבמות כד) מדרש שיהא גדול האחים מיבם ושהאילונית אינה מתיבמת וכן אשת הסריס ששמו מחוי וזה כולו אסמכתא כי האילונית ואשת הסריס מגופיה דקרא נפקי
@669 **זכור את אשר עשה לך עמלק** . כבר הזכרתי (לעיל כד ט) המדרש שדרשו בו בספרא (בחקותי פרשה א ג) יכול בלבך כשהוא אומר לא תשכח הרי שכחת הלב אמורה הא מה אני מקיים זכור שתהא שונה בפיך וכן בספרי (תצא קסו) זכור את אשר עשה לך עמלק בפה לא תשכח בלב ולא ידעתי מה היא הזכירה הזו בפה אם לאמר שנקרא פרשת עמלק בציבור ונמצינו למדין מן התורה בשניה זכור (מגילה כט) ויהיה סמך למקרא מגלה מן התורה והנכון בעיני שהוא לומר שלא תשכח מה שעשה לנו עמלק עד שנמחה את שמו מתחת השמים ונספר זה לבנינו ולדורותינו לומר להם כך עשה לנו הרשע ולכך נצטוינו למחות את שמו וכן במעשה מרים נצטוינו להודיעו לבנינו ולספר בו לדורות ואע"פ שהיה ראוי גם להסתירו שלא לדבר בגנותן של צדיקים אבל צוה הכתוב להודיעו ולגלותו כדי שתהא אזהרת לשון הרע שומה בפיהם מפני שהוא חטא גדול וגורם רעות רבות ובני אדם נכשלים בו תמיד כמו שאמרו (ב"ב קסה) והכל באבק לשון הרע
@673 **ולקחת מראשית כל פרי האדמה אשר תביא מארצך** . שתקח מראשית כל הפרי אשר תביא אל הבית מארצך אשר ה' אלהיך נותן לך יצוה שיפריש הפרי בשדה ויקרא עליו שם ויביאנו לביתו וישים אותו בכלי ראוי להוליכו לבית הבחירה ולא נתן הכתוב שיעור בהם אלא אפילו גרגיר אחד מכל המין ההוא פוטר כל השדה כדין תרומה שחטה אחת פוטרת את הכרי
@673 "והלכת אל המקום אשר יבחר ה' אלהיך" - כפי פשוטו יזהיר שלא תקריב בכורים באחד משעריך משנבחר הבית כי כמו שהזהיר בשחוטי חוץ בקרבנות כן יזהיר בבכורים אבל חובת הבכורים לאחר שכבשו וחלקו מיד כדברי רש"י (בפסוק א) ובספרי (תבוא ב) והלכת אל המקום אשר יבחר ה' אלהיך לשכן שמו שם זה שילה ובית עולמים ושמא יאמרו כי הבמות אסורות בשני הזמנים האלו אבל גם בנוב וגבעון יקריבו הבכורים אבל בבמת יחיד אינן קריבין דמזבח כתיב ואולי ממה שכתוב (שמות כג יט) ראשית בכורי אדמתך תביא בית ה' אלהיך לא קרבו באהל ובמשכן אלא בשילה שהיה שם בית אבנים ובבית העולמים
@674 **וטעם אל הכהן אשר יהיה בימים ההם** . אל הכהן אשר יהיה שם בימים ההם כי הם נתונים לאנשי משמר ככל הקרבנות לא שיוליך עמו כהן מעירו להקריב בכוריו ורש"י כתב אין לך אלא כהן שיהיה בימיך כמות שהוא ולא הבינותי זה כי בענין הזקן ראוי לומר "אל השופט אשר יהיה בימים ההם" (לעיל יז ט) אע"פ שאינו גדול וחכם כשופטים הראשונים אשר היו לפנינו מן העולם צריך לשמוע לו יפתח בדורו כשמואל בדורו אבל בהקרבת הבכורים למי יביאם אם לא לכהן אשר יהיה בימיו וכן ראיתי בספרי (תבוא ג) ובאת אל הכהן אשר יהיה זו היא שר' יוסי הגלילי אומר וכי תעלה על דעתך כהן שאינו בימיך אלא כהן שהוא מוחזק וכשר לך באותן הימים היה קרוב ונתרחק כשר וכן הוא אומר (קהלת ז י) אל תאמר מה היה שהימים הראשונים היו טובים מאלה וגו' ונראה שהם ידרשו בזה שאם הקריב בכורים או עולה וקרבנות בכהן שהוא בחזקת כשר ולאחר זמן נמצא שהוא בן גרושה הקרבנות כשרין כמו שמוזכר בפרק האחרון של קידושין (סו) ויכנס בו עוד שאם היה קרוב ונתרחק כשר וזה לענין הזקן שאינו נדון על פי קרוב ואינו ענין בבכורים
@674 "הגדתי היום" - בפרי הזה שהבאתי הגדתי והודיתי לשם אלהיך שהביאני לארץ אשר נשבע לאבותינו לתת לנו והנה השם מקיים דבריו ואני מודה ומשבח לשמו וטעם הגדתי כמו ספרתי וכן ויגד משה את דברי העם אל ה' (שמות יט ט) ספור או יהיה פירושו הגדתי לך הכהן ולכל העומדים האלה וההגדה הזו היא לה' אלהיך כלומר לשמו כי באתי אל הארץ אשר נשבע לאבותינו כי הוא הביאני אליו לעבדו בארץ
@685 **לא אכלתי באני ממנו** . אע"פ שהוידוי בכל המעשרות כמדרש וגם נתתיו ללוי ולגר וליתום ולאלמנה (ספרי יג מעשר שני פ"ג ה"י) אבל "לא אכלתי באוני ממנו" יחזור על הקדש לבדו שהוא מעשר שני ונטע רבעי והם שאסורין באונן ובטומאה ולא נתתי ממנו למת לעשות לו ארון ותכריכין לשון רש"י ולא הבינותי זה שהרי מפורש בכתוב (לעיל יד כה כו) שמעשר שני אין מחללין אותו חוץ לירושלים אלא על כסף צורה ובירושלים יתן הכסף על דבר הראוי לאכילה בבקר ובצאן וביין ובשכר ויאכל לפני ה' והרב רבי משה כתב בחבורו (הל' מעשר שני פ"ג ה"י) מעשר שני ניתן לאכילה ושתייה שנאמר ואכלת שם לפני ה' אלהיך וסיכה כשתייה ואסור להוציאו בשאר צרכיו כגון שיקח בו כלים ובגדים ועבדים שנאמר ולא נתתי ממנו למת כלומר לא הוצאתי אותו בדבר שאינו מקיים את הגוף עשה מלת "למת" בכאן כנוי לדברים אשר לא יחיה האדם בהם ואלו דברי הבאי ואחרים מפרשים שמתודה שלא נתן ממנו על ארון ותכריכין אפילו למת שהוא מצוה וכל שכן לחי בטלית וחלוק ובספרי (תבוא יד) ולא נתתי ממנו למת לעשות לו ארון ותכריכין דברי רבי אליעזר אמר לו רבי עקיבא אם למת אסור אף לחי אסור ומה ת"ל לא נתתי ממנו שלא החלפתיו אפילו בדבר טהור פירוש רבי עקיבא דורש ולא נתתי ממנו שלא עשיתי ממנו חליפין אפילו בדבר טהור הראוי לאכילה כענין ששנינו (מעשר שני פ"א מ"א) אין מוכרין אותו ואין מחליפין אותו ולא יאמר אדם לחבירו בירושלים הא לך יין ותן לי שמן ויהיה "למת" על דעתו מחובר למעלה לא אכלתי ממנו באוני למת שאין אנינות אלא למת וראיתי בירושלמי (מעשר שני פ"ב ה"א) רבי אליעזר בשם רבי סימאי אומר לא נתתי ממנו למת מה אנן קיימין אם להביא ארון ותכריכין דבר שאסור לחי לחי אסור כל שכן למת איזה דבר שמותר לחי ואסור למת זו סיכה גם זה לא ידעתי מהו שאם סך בשמן מעשר למת הרי בערו בטומאה וכבר התודה עליו "לא בערתי ממנו בטמא" ובגמרא בפרק הערל (יבמות עד) אמר רבי שמעון בן לקיש משום רבי סימאי מנין למעשר שני שנטמא שמותר לסוכו שנאמר ולא נתתי ממנו למת למת הוא דלא נתתי הא לחי דומיא דמת נתתי איזהו דבר ששוה בחיים ובמתים הוי אומר זו סיכה ושם הקשו ואימא ליקח לו ארון ותכריכין ופירושו שיהיה מותר בחי ליקח לו חלוק כשנטמא כיון דלא קרינא ביה ואכלת שם לפני ה' אלהיך ופירקו "ממנו" מגופו נשאר עכשיו כי הוידוי ב"לא נתתי ממנו למת" מחובר עם "לא בערתי ממנו בטמא" יתודה עליו שלא אכל ממנו טמא ולא נתן מן הטמא למת לסוך אותו אבל במשנה (מעשר שני פ"ה מי"ב) שנינו כדברי רבי אליעזר לא נתתי ממנו למת לא לקחתי ממנו ארון ותכריכין למת לא נתתיו לאוננים אחרים ומשמעות זה שהם דורשים בו שלא נתנו למת לא לגופו של מת בארון ותכריכין ולא לאוננים שלו שהוא מתודה על אנינות שלו ושל אחרים ומפני אנינות של אחרים יתודה על הארון והתכריכין אע"פ שאפילו לחי אסור
@686 **אשר נתת לנו כאשר נשבעת לאבתינו** . לתת לנו וקיימת ארץ זבת חלב ודבש לשון רש"י ואם כן שיעור הכתוב ואת האדמה אשר נתת לנו ארץ זבת חלב ודבש כאשר נשבעת לאבותינו ור"א אמר כי טעמו להיותה כן תמיד כלומר וברך את האדמה אשר נתת לנו להיותה ארץ זבת חלב ודבש ואין צורך בכל זה כי בכלל הדבור או השבועה הנתינה אומר אדם לחברו "נשבעת לי שדה שלך" "אמרת לי מנה" וכן כאשר דבר ה' אלהי אבותיך לך ארץ זבת חלב ודבש (לעיל ו ג) וכבר פירשנו (שם) וכן ויתן לו בית ולחם אמר לו וארץ נתן לו (מלכים א יא יח) ולא יקשה בעיניך בכאן כי לא נזכר בשבועות האבות "ארץ זבת חלב ודבש" כי מאחר שהארץ ההיא בעת ההיא ארץ זבת חלב ודבש הנה נשבע להם בארץ זבת חלב ודבש או "לאבותינו" יוצאי מצרים שנאמר להם (שמות ג ח) אל ארץ זבת חלב ודבש כענין וירעו לנו מצרים ולאבותינו (במדבר כ טו)
@687 **היום הזה ה' אלהיך מצוך לעשות** . הנה השלים משה לבאר את התורה ולחדש כל המצות אשר צוה אותו השם לחדש להם ולכך אמר היום הזה ה' אלהיך מצוך לעשות את החקים האלה ואת המשפטים כי כבר השלמתי לך הכל והזכיר ושמרת ועשית אותם בכל לבבך ובכל נפשך והלב והנפש כבר פירשתים (לעיל ו ה)
@688 **וטעם את ה' האמרת היום** . כיון שקבלתם עליכם כל התורה בפירושיה ובדקדוקיה ובחדושיה הנה גדלתם השם ורוממתם אותו שיהיה הוא לבדו לכם לאלהים לא תודו באל אחר כלל
@688 "וללכת בדרכיו" - שתעשו הטוב והישר ותגמלו חסד איש את רעהו ולשמר חקיו ומצותיו ומשפטיו יזכיר בפרט החוקים והמשפטים כאשר פירשתי (לעיל ד ה) ויכלול במצותיו כל המצות מצות עשה ולא תעשה ולשמע בקלו ככל אשר יצוה לכם משאר המעשים על ידי או על יד שאר הנביאים כאשר פירשתי (לעיל יג ה) ויתכן שיהו "מצותיו" מצות עשה ו"לשמוע בקולו" המניעות כלומר מצות לא תעשה
@689 **ואמר וה' האמירך היום** . כי היום הזה לכם כיום סיני והשם רומם וגדל אתכם בקבול התורה שתהיו לו לעם סגולה מכל העמים ולשמר כל מצותיו כי לכם לבדכם יתן תורתו ויצוה אתכם בכל המצות הרצויות לפניו לא לעם אחר כענין שכתוב (תהלים קמז יט כ) מגיד דבריו ליעקב חקיו ומשפטיו לישראל לא עשה כן לכל גוי
@690 **ולתתך עליון על כל הגוים אשר עשה לתהלה** . שיהללוך כל עמי הארץ בהיות ה' קרוב בכל קראך אליו ולשם שיצא לך שם בגוים בהדרו אשר שם עליך כי אתה נעלה על כלם ולתפארת כי תתפאר עליהם לעשות בהם כל אשר תחפוץ תגזור אומר ויקם לך כענין פן יתפאר עלי ישראל לאמר ידי הושיעה לי (שופטים ז ב) ולהיותך עם קדוש לדבקה בו בסוף ועל דרך האמת לתהלה כי אלהי ישראל הוא תהלתך ושמו הגדול הוא אלהיך ובזה תפארתך כענין שנאמר כי תפארת עוזמו אתה (תהלים פט יח) תפארת ישראל (איכה ב א)
@691 **וטעם ויצו משה וזקני ישראל** . כי אחרי שהשלים משה דבריו צוה לזקנים שידברו גם הם עמו ויזהירו בעם לשמור כל המצות כי כל עם הולך בעצת זקניו וכתיב אשר אנכי מצוה אתכם ולא "אנחנו" כי עיקר הדיבור למשה והזקנים ירימו קולם לאמר לעם שמעו והאזינו ועשו וכן וידבר משה והכהנים הלוים אל כל ישראל וגו' (פסוק ט) כי אמרו הכהנים לעם הסכת ושמע ישראל ומשה אמר היום הזה נהיית לעם אבל ר"א אמר כי שמור את כל המצוה מצות האבנים אשר יזכיר ואיננו נכון
@693 **וכתבת עליהן את כל דברי התורה הזאת** . אמר ר"א בשם הגאון שכתבו עליהם מנין המצות כמו הכתובות בהלכות גדולות כעין אזהרות וטעם "באר היטב" (פסוק ח) הכתיבה ורבותינו אמרו (סוטה לב) בשבעים לשון ומצינו בספר תאגי שהיתה כל התורה כתובה בהן מבראשית עד לעיני כל ישראל בתאגיה וזיוניה ומשם נעתקו התאגין בכל התורה ויתכן שהיו האבנים גדולות מאד או שהיה ממעשה הנסים
@693 "למען אשר תבא אל הארץ" - אמר רבי אברהם כי השם יעזרך אם החלות לשמור מצותיו כי זאת היא המצוה הראשונה לביאתם לארץ ולפי דעתי "למען אשר תבא" רמז לכל דברי התורה יאמר שתכתוב על האבנים כל דברי התורה הזאת בעברך בירדן מיד למען אשר באת אל הארץ כי בעבור התורה באת שמה וכן למען ינוח עבדך ואמתך כמוך וזכרת כי עבד היית (לעיל ה יד טו) ינוח עבדך ואמתך כמוך למען תזכור כי עבד היית או טעמו תכתוב עליהם את כל דברי התורה הזאת להיות לך לזכרון למען אשר תבא אל הארץ ותכבוש אותה ותירש את כל העמים ההם בהיותך זוכר התורה ושומר כל מצותיה
@710 **וטעם כי גלה כנף אביו** . דרך כבוד לאב כי בתורה הזכיר (ויקרא כ יא) ערות אביו גלה וכן הזכיר באשת אחיו ואשת אחי אביו ערותם כי שם יחייב עונש גדול מיתה או כרת והוצרך לנבל הרעה שעשו על כן הזכיר בהם הערוה אבל בכאן להיותו לאלה די להזכיר כי גלה כנף אביו כי בגלוי כנף האב בלבד מחוייב קללה כי מקלה את כבודו וכל מקלה את אביו ארור וכן לא יקח איש את אשת אביו ולא יגלה כנף אביו (לעיל כג א) דרך כבוד שלא יקרב אליה כי אין ראוי לגלות כנפו אשר פרש על אשה דרך חופה כטעם ופרשת כנפך על אמתך (רות ג ט) ולא כמי שמרבה בו אנוסת אביו (יבמות צז)
@716 **אשר לא יקים את דברי התורה הזאת** . כאן כלל את כל התורה כולה וקבלוה עליהם באלה ובשבועה לשון רש"י ולפי דעתי כי הקבלה הזאת שיודה במצות בלבו ויהיו בעיניו אמת ויאמין שהעושה אותן יהיה לו שכר וטובה והעובר עליהן יענש ואם יכפור באחת מהן או תהיה בעיניו בטלה לעולם הנה הוא ארור אבל אם עבר על אחת מהן כגון שאכל החזיר והשקץ לתאותו או שלא עשה סוכה ולולב לעצלה איננו בחרם הזה כי לא אמר הכתוב אשר לא יעשה את דברי התורה הזאת אלא אמר אשר לא יקים את דברי התורה הזאת לעשות כטעם קיימו וקבלו היהודים (אסתר ט כז) והנה הוא חרם המורדים והכופרים ובירושלמי בסוטה (פ"ז ה"ד) ראיתי אשר לא יקים וכי יש תורה נופלת רבי שמעון בן יקים אומר זה החזן רבי שמעון בן חלפתא אומר זה בית דין של מטן דמר רב יהודה ורב הונא בשם שמואל על הדבר הזה קרע יאשיהו ואמר עלי להקים אמר רבי אסי בשם רבי תנחום בר חייא למד ולימד ושמר ועשה והיה ספק בידו להחזיק ולא החזיק הרי זה בכלל ארור ידרשו בהקמה הזאת בית המלך והנשיאות שבידם להקים את התורה ביד המבטלים אותה ואפילו היה הוא צדיק גמור במעשיו והיה יכול להחזיק התורה ביד הרשעים המבטלים אותה הרי זו ארור וזה קרוב לענין שפירשנו ואמרו על דרך אגדה זה החזן שאינו מקים ספרי התורה להעמידן כתקנן שלא יפלו ולי נראה על החזן שאינו מקים ספר תורה על הצבור להראות פני כתיבתו לכל כמו שמפורש במסכת סופרים (יד יד) שמגביהין אותו ומראה פני כתיבתו לעם העומדים לימינו ולשמאלו ומחזירו לפניו ולאחריו שמצוה לכל אנשים והנשים לראות הכתוב ולכרוע ולומר וזאת התורה אשר שם משה וגו' (לעיל ד מד) וכן נוהגין
@725 **יקימך ה' לו לעם קדוש כאשר נשבע לך** . יקרא שבועה הברית אשר כרת עמהם בהר סיני על כל הדברים האלו כי שם נאמר (שמות יט ו) ואתם תהיו לי ממלכת כהנים וגוי קדוש או שהברית אשר כרת עם אברהם (בראשית יז ז) להיות לך לאלהים ולזרעך אחריך יכלול זה וכן אמר (להלן כט יב) למען הקים אותך היום לו לעם והוא יהיה לך לאלהים כאשר דבר לך וכאשר נשבע לאבותיך לאברהם ליצחק וליעקב כי לכולם בא בברית
@729 **וטעם לראש ולא לזנב** . ביאורו לראש לכל העמים ולא לזנב לאחד מכל הגוים כי יתכן שיהיה לראש על עמים רבים וזנב לעם אחד נכבד ממנו והנכון שיתנך לראש מעתה ולא לזנב עד עולם באחד מכל העתים וכן רק למעלה תמיד ולא תהיה למטה לעולם
@730 **ולא תסור מכל הדברים** . נמשך עם "כי תשמע" (פסוק יג) שיבואו עליך כל הברכות האלה כאשר תשמע למצותיו וכאשר לא תסור ימין ושמאל מכל הדברים אשר אנכי מצוך בענין עבודה זרה שאם תלך אחרי אלהים אחרים לעבדם כבר סרת מכל מצותיו ואין חפץ כלל בכל המצות שתעשה ואיננו כדברי בעל ההלכות שמנאו מצות לא תעשה
@734 **פרי בטנך** . ואחר כך טנאך ומשארתך (פסוקים ד ה) כי פרי הבטן הטוב והחביב יותר ובקללה אחר אותו כי העונש יגיעהו תחלה לנכסיו ואם לא ישוב ישיגהו בפרי בטנו וכן הקדים בברכות נגיפת האויבים קודם הברכה באסמיך ובכל משלח ידך (פסוקים ז ח) כי נצוח האויבים הוא להם הכבוד והצורך הגדול בכבוש הארצות ובישיבתם לבטח בין העמים ובקללות הקדים המארה בכל משלח ידך ואחר הנגיפה מפניהם (פסוקים כ כה) כי הוא העונש שיגיע אליהם באחרונה וכן יגלו בסוף
@758 **הצלצל** . על דעת רש"י מין ממיני הארבה וא"כ ראוי היה שיצרף אותו עם פסוק הארבה והתולעת (פסוקים לח לט) ויותר נראה שיהיה צלצל שם למחנה האויב אמר (בפסוק מא) בנים ובנות תוליד ולא יהיו לך לעבוד אותך ולכלכל את שיבתך כי ילכו בשבי לפני האויב ואמר כל עצך ופרי אדמתך אשר לא ישאו לך פירות כאשר הזכיר יירש האויב הבא עליך כי השנה שיבואו עליך יתנו להם חילם והם יאכלום ויקרא החיל "צלצל" בעבור שישמיעו קול מלחמה במחנה וקול שופר ורעם שרים ותרועה מלשון צלצלי שמע וצלצלי תרועה (תהלים קנ ה) ובמנענעים ובצלצלים ( ו ה) וכן ארץ צלצל כנפים (ישעיהו יח א) ארץ המשמעת צלצול כנפיה שהולכות למרחקים כאשר ידאה הנשר ובגמרא (ב"ק קטז) נטלוה מסיקין מאן דתני מסיקין לא משתבש דכתיב יירש הצלצל ומתרגמינן יחסנינה סקאה ומאן דתני מציקים לא משתבש דכתיב במצור ובמצוק כי הוא אצלם שם למביאי האדם במצור ובמצוק ודע כי התוכחות במארה ובמהומה ובמגערת ובדבר והעץ ופרי האדמה ושאר כל התוכחות הם כולם עד כלותו אותך מעל האדמה אשר אתה בא שמה לרשתה אבל אחרי הגלות לא יקלל אותם רק לעבוד שם אלהים אחרים עץ ואבן אבל פעמים שיחזור להוכיחם בארץ כאשר אמר (פסוק לו) יולך השם אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת אתה ואבותיך ועבדת שם אלהים אחרים והוא הגלות שגלינו לרומי על לכת אגריפס המלך שם ואחרי כן ישוב ויאמר (פסוק לח) זרע רב תוציא השדה וגו' ואלה התוכחות בהיותם בארץ כי כן יאמר אחריו (פסוק סג) ונסחתם מעל האדמה שהוא הגלות ועל דעתי גם זה מרמיזותיו אמר יולך ה' אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת על לכת אגריפס המלך לרומי גם יתכן שירמוז למלך אחר קודם לאגריפס והוא אריסתובלוס שתפסו שר צבא רומי ויוליכהו שמה בנחושתים והיו למשל ולשנינה בכל העמים שהיו תמהים על גבורתם אשר מעולם איך נפלו גבורים ויאבדו כלי מלחמתם ואחרי כן בא אגריפס שנית עם שליח מלך רומי בארץ וכבש בארץ יהודה מדינות גדולות מאד ואז נתקיים מה שאמר (פסוק מח) ועבדת את אויביך אשר ישלחנו ה' בך ברעב ובצמא וגו' ואמר ישא ה' עליך גוי מרחוק (פסוק מט) כי באו אספסינוס וטיטוס בנו עם חיל גדול מרומיים בארץ ולכדו כל ערי יהודה הבצורות והצר להם מאד כאשר ידוע בספרים שלכדו גם חומות ירושלים ולא נשאר רק בית המקדש וחומת העזרה והיו אוכלים בשר בניהם ובנותיהם וכאשר נלכדה גם היא אז נתקיים ונסחתם מעל האדמה ואז שבו הרומיים לארצם ובידם גלות ירושלים וביד עמים רבים אשר אתם מיון ומצרים וארם ויתר עמים רבים ונתקיים (פסוק סד) והפיצך ה' בכל העמים וגו' והכתובים הבאים אחר כן עונשם בגלות וכן והיו חייך תלאים לך מנגד (פסוק סו) מפני פחדותינו בגלות ביד העמים הגוזרים עלינו גזירות תמיד והנכון שהוא רמז לדורות ההם שהיו בזמן חרבן הבית השני כי היו מתנכלים להם להאבידם לגמרי על כן אמר אחריו (פסוק סח) והשיבך ה' מצרים באניות שהיה זה כאשר כלו להוציאם מן הארץ ורבותינו אמרו (פתיחתא דאסתר רבה) ולמה למצרים לפי שכעור ורע לעבד כשהוא חוזר לרבו הראשון אם כן הזכיר מצרים דרך תוכחות אבל אחרי היותנו בגלות בארצות אויבינו לא נתקללו מעשה ידינו ולא אלפינו ועשתרות צאננו ולא כרמינו וזיתינו ואשר נזרע בשדה אבל אנחנו בארצות כשאר העמים יושבי הארץ ההיא או בטוב מהם שרחמיו עלינו כי ישיבתנו בגלות היא בהבטחה שאמר לנו (ויקרא כו מד) ואף גם זאת בהיותם בארץ אויביהם לא מאסתים ולא געלתים לכלותם להפר בריתי אתם כי אני ה' אלהיהם וכבר פירשתי בסדר אם בחקותי (שם שם טז) סוד הברית הזאת וכי הוא על זמן גלותנו היום ביד החיה הרביעית ואחר כן יבטיח בגאולה ממנו
@786 **וטעם ויקרא משה אל כל ישראל** . כי אחרי שהשלים לאמר להם דברי הברית קראם עוד שמע ישראל אתם ראיתם וגו' כי לא הלכו מלפניו שהכל מחובר הוא
@790 **לחם לא אכלתם ויין ושכר לא שתיתם** . הטעם לא אכלתם ממנו שתוכלו לחיות ממנו כי עיקר מחיתם במן היתה למען תדעו כי אני ה' אלהיכם המחיה אתכם במעשה הנס ואין טעמו שלא אכלו לחם כלל כמו לחם לא אכלתי ומים לא שתיתי (לעיל ט ט) כי בקצת העתים היה לישראל במדבר לחם כמו שכתוב (שם ב כח כט) אכל בכסף תשבירני ואכלתי ומים בכסף תתן לי ושתיתי כאשר עשו לי בני עשו היושבים בשעיר והמואבים היושבים בער ורבותינו הזכירו (יומא עה) דברים שתגרי אומות העולם מביאים להם במדבר ואפשר עוד כי מעת שירד המן עד בואם אל שעיר לא אכלו לחם כלל כי הלכו במדבר הגדול והנורא אבל בשנת הארבעים קרבו לישוב ונאמר להם (לעיל ב ד ו) ואת העם צו לאמר אתם עוברים בגבול אחיכם בני עשו אכל תשברו מאתם ושם (פסוק ז) כתוב זה ארבעים שנה ה' אלהיך עמך לא חסרת דבר ומן העת ההיא היו האדומים והמואבים מקדימים אותם בלחם ובמים והיו גדולי ישראל קונים מהם ואוכלים לתענוג לא לצורך ולא לשבעה ועיקר המחיה שלהם במן
@794 **אתם נצבים היום לפני ה' אלהיכם** . שאתם עומדים ומזומנים לפני השם כדי לעמוד בבריתו כי לקבל התורה בבאורה נאספו אליו או שהיו עומדים לפני הארון והברית הוא השבועה והאלה אשר יזכיר לעברך בברית ה' אלהיך ובאלתו ויתכן שכרת עוד עמם ברית כברית הראשונה אשר כרת אתם בהר סיני (שמות כד ה-ח) שהקריב עליהם עולה ולקח חצי הדם לזרוק על המזבח וחצי הדם זרק על העם אבל לא הוצרך להזכיר זה ועל דרך האמת כבר הודעתיך הברית הזאת וטעם ראשיכם שבטיכם ראשיכם ראשי שבטיכם כמו והנבואה עודד הנביא על דעת ר"א ועל דעתי הכתוב יכלול ויפרוט והכלל ראשיכם וכל שבטיכם וחזר ופרט זקניכם ושטריכם שהם ראשיכם כי זקן ונשוא פנים הוא הראש וכן אמר (להלן לא כח) הקהילו אלי את כל זקני שבטיכם ושוטריכם כי כל איש אשר לו שררה ומנוי על הצבור יקרא ראש נאמר בנשיאים (במדבר א טז) "ראשי אלפי ישראל" כי הם במעלה הגדולה לכל אלפי ישראל ונאמר במרגלים (שם יג ג) "ראשי בני ישראל "המה" שהם ראשים בבני ישראל לא ראשים לכל בני ישראל וכלם בכלל ראשיכם וחזר ואמר כל איש ישראל שהם שבטיכם והזכיר עוד הטף והנשים והגרים וחוטבי עצים ושואבי מים אשר להם מערב רב והביא שם הטף להביאם בברית כי אפילו עם הדורות העתידים יכרות ברית או כדי לזכותם כטעם שאמרו בהקהל (חגיגה ג) ורבותינו אמרו (יבמות עט) שבאו קצת כנענים בימי משה כדרך שבאו בימי יהושע ונתנם חוטבי עצים ושואבי מים לעדה ולמשכן ה' ואין הכונה לומר שרמו אותו אבל באו אליו להשלים עמו כי כן המשפט כאשר ביארנו (לעיל כ י יא) וכך מצאתי במדרש תנחומא (נצבים ב) ללמדך שבאו אצל משה ולא קבלם כלומר שלא יכלו לרמותו לכרות להם ברית אבל עשאם מיד חוטבי עצים ושואבי מים
@799 **ואת אשר איננו פה עמנו** . וגם עם הדורות העתידים להיות
@800 **כי אתם ידעתם** . וגו' ותראו את שקוציהם לפי שראיתם את האומות עובדי עבודת כוכבים ושמא השיא לב אחד מכם ללכת אחריהם
@802 **פן יש בכם וגו'** . לפיכך אני צריך להשביעכם לשון רש"י ויפה פירש והטעם לומר אני צריך להביאכם באלה ובשבועה עתה בברית הזאת מיראתי אולי נפתה לב קצתכם לשקוצי מצרים כאשר עשיתם בעגל או לשקוצי עמון ומואב אשר ראיתם בדרך כאשר היה לכם בבעל פעור כי בברית הראשונה של שעת מתן תורה לא היו שם אלות וקללות והזכיר איש או אשה מפני שהאשה דעתה קלה עליה וכן יעשה בענין ע"ז (לעיל יז ב) והזכיר יחידים ומשפחה ושבט שהוא עם רב ולא אמר על כולם דרך כבוד או שלא יתכן שיהיה לב כולם פונה היום לע"ז כי לא היו באים בברית השם ובאלתו כי מי יכריחם אבל משפחה או שבט יבואו בברית מפני פחד הרוב ואמר פן יש בכם וגו' אשר לבבו פנה היום על הנפתה כבר לע"ז והוא בלבו מאמין בה היום הזה או פן יש בכם שרש רע שיפרח וישגה ובימים הבאים יוציא פרחים רעים ויצמיח מרורות וזה על אשר איננו פה עמנו היום כי האב שרש והבן נצר משרשיו יפרה והזכיר השרש לומר כי הוא יכול להביא באלה הדורות הבאים שהשרש אשר ממנו יצמחו הוא לפניו היום והוא בא בברית ובאלה הזאת ואמר פרה ראש לרמוז כי משרש מתוק לא יצא מר וכל אשר לבבו שלם עם השם הנכבד ולא הרהר כלל בע"ז לא יוליד מודה בה ואל תקשה עלי בזה מן הכתוב (יחזקאל יח י) והוליד בן פריץ כי אמת הדבר וסוד גדול לא אוכל לפרש בו
@802 "וראש ולענה" - עשבים מרים או ממיתים ושמם כן בלשון הקדש או הם כנויים יקראו האחד "ראש" שהוא ראש המרורים מר מכולם והשני יקראו "לענה" מענין לענות מפני (שמות י ג) כי האוכל אותו נגש ונענה לענות נפשו יאכלנו
@803 **והתברך בלבבו לאמר** . כשישמע האחרים מתקללים באלות האלה הוא יתברך במחשבתו ויאמר בלבו שלום יהיה לי מכל אלה כאשר אלך בתאות לבי והשם לא יסלח לו אבל יעשן עליו אפו אז כשיחטא לדור או לדורות או יהיה טעם "כי" לאמר יהיה לי שלום בעבור שאינני מקבל עלי השבועה כי בשרירות לבי אלך כל ימי וכל חפצי אעשה ולא יאבה ה' בעבור שאיננו מקבל אלתו לסלוח לו אבל יעשן עליו אפו כיון שבא בבריתו לפני עם כל ישראל התאוה הגוברת ומתחזקת בלב תקרא שרירות כלשון חכמים (בבא בתרא קס) שריר וקיים וכן בשרירי בטנו (איוב מ טז) ופירוש למען ספות הרוה את הצמאה להוסיף השבעה עם המתאוה כי נפש שבעה תקרא רוה כענין ורויתי נפש הכהנים דשן ועמי את טובי ישבעו (ירמיהו לא יג) והיתה נפשם כגן רוה (שם פסוק יא) והמתאוה תקרא צמאה צמאה לך נפשי (תהלים סג ב) והטעם כי נפש האדם הרוה שאיננה מתאוה לדברים הרעים לה כאשר תבא בלבו קצת התאוה והוא ימלא תאותו אז יוסיף בנפשו תאוה יתירה ותהיה צמאה מאד לדבר ההוא שאכל או שעשה יותר מבראשונה ותתאוה עוד לדברים רעים שלא היתה מתאוה להם מתחלה כי המתאוה לזמת הנשים היפות כשיהיה שטוף בזמתן תבואהו תאוה לבוא על הזכר ועל הבהמה וכיוצא בזה בשאר התאוות וכענין שהזכירו חכמים (סוכה נב) משביעו רעב מרעיבו שבע ולכך יאמר הכתוב בהולך בשרירות לבו שהוא אם ימלא נפשו בתאוות השרירות והחזקות עליו אשר היא צמאה להם יוסיף נפשו הרוה עם הצמאה כי יתאוה ויצמא למה שהיה שבע ממנו וכאשר השביע נפשו בו ולפי שהזכיר "שרש פורה" אמר בלשון הזה כי יוסיף השרש הוא כפתו אשר היא רוה ורעננה עם הצמאה ותשובנה כולם צמאות ואין "למען" במקום הזה טעם שאלך בשרירות לבי בעבור שאספה הרוה עם הצמאה אבל הוא כמו "לספות" יאמר הכתוב כי בעבור זה יהיה כך כי בכל סבה עם עלול יאמר "למען" בין שיעשה אדם הגורם לרצותו בעלול כמו למען (אשר) ייטב לך בין שיהיה אדם הגורם כן שלא מדעתו כמו למען למוג לב (יחזקאל כא כ) למען יאשמו (שם ו ו) כספם וזהבם עשו לי עצבים למען יכרת (הושע ח ד) ורבים כאלה וזה הטוב והישר בעיני בפסוק הזה מכל הנכתב עליו בהרבה פנים גם יתכן לפרש שהוא שב אל שרש פורה וראש ולענה יאמר כי יתברך בלבבו לאמר שלום יהיה לי למען שיוסיף פארתו הרוה אשר תגדל ותצמיח הלענה וראש על הצמאה אשר לא היתה צומחת או יהיה "הרוה" כנוי ללענה הנזכרת שיוסיף הלענה הרוה הצומחת וגדלה מאד על הצמאה אשר לא היתה גדלה רק מעט ותהיינה שתיהן צומחות והכונה בזה לומר כי כל אשר ישמע האלה ויתברך ממנה ויתחזק בשרירותו סעיפיו ישיבוהו לחטוא ויצמיחו פשעים יותר מבראשונה וגם זה פירוש נכון
@804 **יעשן אף ה' וקנאתו באיש ההוא** . אלת היחיד איש או אשה ומחה ה' את שמו אלת המשפחה כי שם אחד לראש בית אבותם והבדילו ה' לרעה לשבט מכל שבטי ישראל הנשארים
@806 **ואמר הדור האחרון בניכם אשר יקומו** . כי שבטי ישראל בדור הראשון כבר ידעו זה כי הם שמעו אלות הברית ויתכן כי הכתוב הזה יחזור על שרש פורה ראש ולענה כי כשיקרה זה בדורות הבאים אז ישאלו כן
@810 **אלהים אשר לא ידעום** . לא ידעו בהם גבורת אלהות ולא חלק להם ולא נתנם לחלקם ואונקלוס תרגמו ולא אוטיב להון לא הטיב להם שום טובה ולשון "חלק" אותו אלוה שבחרו להם לא חלק להם שום נחלה וחלק לשון רש"י והנכון אלהים אשר לא ידעום באלהים כלומר שלא ידעו אותם בכח אלהות שימצא להם מעצמו ולא חלקם ה' אלהי אבותם להם שלא נתן אותם שרים על ישראל כאשר שמם על האומות וכבר פירשתי זה (ויקרא יח כה)
@812 **ויתשם ה' מעל אדמתם** . כי יגלה השבט העושה הרע בעיני ה' כענין ויגלם לראובני ולגדי (דברי הימים א ה כו) והנכון כי עתה ירמוז לגלות כל ישראל להיותם כלם רעים ויגלו גלות שלימה וכן בפרשה הבאה אחרי כן (להלן ל א) והיה כי יבאו עליך כל הדברים האלה על גלות כל ישראל יהיה כמו שאמר (שם) בכל הגוים אשר הדיחך ה' אלהיך שמה וגו' והפרשה כולה
@813 **הנסתרות לה' אלהינו** . על דעת המפרשים יאמר כי השם אלהינו לו לעשות משפט בעובדי עבודה זרה בסתר כי כל התעלומות גלויות לפניו והנגלות עלינו ועל בנינו לעשות להם את כל דברי התורה הזאת להכות עובדי עובדה זרה כדין התורה וגם כפי המדרש (סנהדרין מג) כן הוא ודעתי בדרך הפשט כי "הנסתרות" הם החטאים הנסתרים מן העושים אותם כמו שגיאות מי יבין מנסתרות נקני (תהלים יט יג) יאמר הנסתרות לשם לבדו הם אין לנו בהן עון אשר חטא אבל הנגלות שהם הזדונות לנו ולבנינו עד עולם לעשות את כל דברי התורה הזאת חוקת עולם שכך קבלנו על אשר ישנו פה ועל אשר איננו פה לדורות עולם ולפי שהביא באלה לעשות כל המצוה הוציא מן החרם העושה בשגגה שלא יתקלל באלה הזאת ודברי אונקלוס מטין כן שאמר דמטמרן קדם ה' אלהנא ואם כדברי המפרשים ראוי לו לומר דמטמרין לה' אלהנא
@814 **והיה כי יבאו עליך כל הדברים האלה** . כבר הזכרתי (ויקרא כו טז) כי הפרשה הזאת עתידה כי כל עניניה לא היו ולא נבראו אבל הם עתידין להיות
@815 **וטעם ושבת עד ה' אלהיך ושמעת בקלו ככל אשר אנכי מצוך היום אתה ובניך** . שתשוב אל ה' בכל לבבך ובכל נפשך ותקבל עליך ועל בניך לדורותם לעשות ככל אשר אנכי מצוך היום כאשר עשו בגאולה השנית דכתיב (נחמיה י ל) ובאים באלה ובשבועה ללכת בתורת האלהים אשר נתנה ביד משה עבד האלהים ולשמור ולעשות את כל מצות ה' אדנינו ומשפטיו וחקיו או יהיה "מצוך אתה ובניך" כמו מצוך לך ולבניך כענין ואתה צוית (בראשית מה יט) וכן וירעו אותנו (לעיל כו ו) לנו ולפי דעתי יש בו סוד גדול כי ירמוז למה שאמרו (יבמות סג) אין בן דוד בא עד שיכלו כל הנשמות שבגוף וכבר דברתי בו
@819 **ומל ה' אלהיך את לבבך** . זהו שאמרו (שבת קד) הבא לטהר מסייעין אותו מבטיחך שתשוב אליו בכל לבבך והוא יעזור אותך ונראה מן הכתובים ענין זה שאומר כי מזמן הבריאה היתה רשות ביד האדם לעשות כרצונו צדיק או רשע וכל זמן התורה כן כדי שיהיה להם זכות בבחירתם בטוב ועונש ברצותם ברע אבל לימות המשיח תהיה הבחירה בטוב להם טבע לא יתאוה להם הלב למה שאינו ראוי ולא יחפוץ בו כלל והיא המילה הנזכרת כאן כי החמדה והתאוה ערלה ללב ומול הלב הוא שלא יחמוד ולא יתאוה וישוב האדם בזמן ההוא לאשר היה קודם חטאו של אדם הראשון שהיה עושה בטבעו מה שראוי לעשות ולא היה לו ברצונו דבר והפכו כמו שפירשתי בסדר בראשית (ב ט) וזהו מה שאמר הכתוב בירמיה (לא ל- לב) הנה ימים באים נאם ה' וכרתי את בית ישראל ואת בית יהודה ברית חדשה לא כברית אשר כרתי את אבותם וגו' כי זאת הברית אשר אכרות את בית ישראל אחרי הימים ההם נתתי את תורתי בקרבם ועל לבם אכתבנה וזהו בטול יצר הרע ועשות הלב בטבעו מעשהו הראוי ולכך אמר עוד (שם פסוקים לב לג) והייתי להם לאלהים והמה יהיו לי לעם ולא ילמדו עוד איש את רעהו ואיש את אחיו לאמר דעו את ה' כי כולם ידעו אותי למקטנם ועד גדולם ובידוע כי יצר לב האדם רע מנעוריו וצריכים ללמד אותם אלא שיתבטל יצרם בזמן ההוא לגמרי וכן נאמר ביחזקאל (לו כו כז) ונתתי לכם לב חדש ורוח חדשה אתן בקרבכם וגו' ועשיתי את אשר בחקי תלכו והלב החדש ירמוז לטבעו והרוח לחפץ ולרצון וזהו שאמרו רבותינו (שבת קנא) והגיעו שנים אשר תאמר אין לי בהם חפץ (קהלת יב א) אלו ימות המשיח שאין בהם לא זכות ולא חובה כי בימי המשיח לא יהיה באדם חפץ אבל יעשה בטבעו המעשה הראוי ולפיכך אין בהם לא זכות ולא חובה כי הזכות והחובה תלויים בחפץ
@824 **וטעם כי המצוה הזאת** . על כל התורה כולה והנכון כי על כל התורה יאמר (לעיל ח א) "כל המצוה אשר אנכי מצוך היום" אבל "המצוה הזאת" על התשובה הנזכרת כי והשבות אל לבבך (בפסוק א) ושבת עד ה' אלהיך (בפסוק ב) מצוה שיצוה אותנו לעשות כן ונאמרה בלשון הבינוני לרמוז בהבטחה כי עתיד הדבר להיות כן והטעם לאמר כי אם יהיה נדחך בקצה השמים ואתה ביד העמים תוכל לשוב אל ה' ולעשות ככל אשר אנכי מצוך היום כי אין הדבר נפלא ורחוק ממך אבל קרוב אליך מאד לעשותו בכל עת ובכל מקום וזה טעם בפיך ובלבבך לעשותו שיתודו את עונם ואת עון אבותם בפיהם וישובו בלבם אל ה' ויקבלו עליהם היום התורה לעשותה לדורות כאשר הזכיר (לעיל פסוק ב) אתה ובניך בכל לבבך כמו שפירשתי (שם)
@828 **ראה נתתי לפניך היום** . יחזור להזהירם עוד להגיד להם כי שני הדרכים בידם וברשותם ללכת באשר יחפצו בה ואין מונע ומעכב בידם לא מן התחתונים ולא מן העליונים ויעיד בהם את השמים ואת הארץ פעם שנית (פסוק יט) אחר שאמר (לעיל ד כו) העידתי בכם היום את השמים ואת הארץ כי אבד תאבדון מהר כי עתה יאמר העדותי בכם היום את השמים ואת הארץ כי החיים והמות נתתי לפניך שהם הברכה והקללה וכי יעצתיך שתבחר בחיים למען תחיה אתה וזרעך והנה הוא כמחתים העדים בסוף דבריו כולם
@834 **וילך משה** . כאשר השלים כל דבריו אז הלכו כל הנצבים לפניו והטף והנשים איש לאהליו ולא הוצרך הכתוב להזכיר זה כי כבר אמר (לעיל כט ט יא) אתם נצבים היום כלכם לפני ה' אלהיכם וגו' לעברך בברית ה' אלהיך ואחר עברם בברית ילכו מפניו ויאמר הכתוב עתה כי משה הלך ממחנה לויה אל מחנה ישראל לכבדם כמי שירצה להפטר מחבירו ובא ליטול רשות ממנו
@835 **ויאמר אלהם בן מאה ועשרים שנה אנכי היום** . וזה לנחם אותם על ענינו כלומר אני זקן ואין לכם עוד תועלת ממני ועוד כי השם צוני שלא אעבור שם ואל תפחדו ואל תיראו כי ה' יעבור עמכם לא יסלק שכינתו מכם בעבורי ויהושע הוא העובר לפניכם במקומי ואע"פ שמשה רבינו היה בתקפו ובבריאותו כאשר העיד הכתוב (להלן לד ז) לא כהתה עינו ולא נס לחה אמר להם כן לנחמם ורש"י כתב לא אוכל עוד לצאת ולבוא לפי שה' אמר אלי לא תעבור את הירדן ואינו נכון ועל דעת ר"א לצאת ולבוא למלחמה כי חלשו כחותיו בזקנותו וגם זה איננו נכון ורבותינו אמרו (סוטה יג) מלמד שנסתתמו ממנו מעיינות חכמה והיה זה במעשה נס שלא ידאג לתת גדולה ליהושע בפניו
@842 **ויכתב משה את התורה הזאת** . מתחלת בראשית עד לעיני כל ישראל ואע"פ שבכאן (פסוק יא) כתוב תקרא את התורה הזאת נגד כל ישראל והוא רומז לספר הזה של אלה הדברים על דעת רבותינו (סוטה מא) אבל בזה חזר ובאר (פסוק כד) ויהי ככלות משה לכתב את דברי התורה הזאת על ספר עד תמם וזה יכלול כל התורה כולה
@845 **למען ישמעו ולמען ילמדו** . האנשים והנשים כי גם הן שומעות ולומדות ליראה את ה' ובניהם אשר לא ידעו ישמעו ולמדו הם הטף כי ישמעו וישאלו והאבות ירגילום ויחנכו אותם כי אין הטף הזה יונקי שדים אבל הם קטני השנים הקרובים להתחנך וזה טעם ולמדו ליראה בעתיד כי למעלה אמר ולמדו ויראו אבל רבותינו אמרו (חגיגה ג) האנשים ללמוד והנשים לשמוע והטף למה בא ליתן שכר למביאיהם
@847 **ואצונו** . ואזרזנו לשון רש"י ואין צורך כי דבר השם (להלן פסוק כג) "חזק ואמץ כי אתה תביא" מצוה היא ואילו היה מתעצל ולא יעשה כן היה חייב מיתה ויתכן שיהיה פירוש "ואצונו" שאמנה אותו נגיד ומצוה על ישראל כמו שפירשתי בפסוק וצויתה אותו לעיניהם (במדבר כז יט)
@848 **וירא ה' באהל בעמוד ענן** . הטעם כי עמוד הענן היה על הפתח והשם היה נראה באהל וזהו הכבוד על דעת ר"א ועל דעתי הוא כמו וירד ה' בעמוד ענן ויעמד פתח האהל (במדבר יב ה) והנה כבוד ה' נראה בענן (שמות טז י) והטעם כי רצה לדבר עם משה שישמע יהושע ושם יצוה את יהושע עצמו והנה למשה נאמר (שם כה כב) ונועדתי לך שם ודברתי אתך מעל הכפרת אבל יהושע לא היה במעלה ההיא ואסור היה ליכנס באהל כלל והנה ויעמד עמוד הענן על פתח האהל שב לבאר כי היה הענן ובו הכבוד על פתח האהל חופף עליו והנה הוא באהל
@849 **אלהי נכר הארץ** . גויי הארץ לשון רש"י ואיננו כן אבל האלהים שהוא נכר בארץ הזאת כי השם הנכבד נקרא אלהי הארץ כענין שנאמר (מלכים ב יז כו) כי לא ידעו את משפט אלהי הארץ וכן וידברו אל אלהי ירושלים כעל אלהי עמי הארץ (דברי הימים ב לב יט) וכתיב (הושע ט ג) לא ישבו בארץ ה' והזכיר זה רבי אברהם וכבר פירשתיו (ויקרא יח כה) וטעם אשר הוא בא שמה בקרבו שהוא בא בקרב עמו ועבדיו או "בקרבו" בקרב הארץ כמו ולא נשא אותם הארץ (בראשית יג ו) נעתם ארץ (ישעיהו ט יח) כדברי רבי אברהם
@850 **וטעם ואמר ביום ההוא הלא על כי אין אלהי בקרבי** . איננו וידוי גמור כענין והתודו את עונם אבל הוא הרהור וחרטה שיתחרטו על מעלם ויכירו כי אשמים הם וטעם ואנכי הסתר אסתיר פני פעם אחרת כי בעבור שהרהרו ישראל בלבם כי חטאו לאלהים ועל כי אין אלהיהם בקרבם מצאום הרעות האלה היה ראוי לרוב חסדי השם שיעזרם ויצילם שכבר כפרו בע"ז וכענין שאמר (ירמיהו ב לה) הנני נשפט אותך על אמרך לא חטאתי ולכך אמר כי על כל הרעה הגדולה שעשו לבטוח בע"ז יסתיר עוד פנים מהם לא כמסתר פנים הראשון שהסתיר פני רחמיו ומצאום רעות רבות וצרות רק שיהיו בהסתר פני הגאולה ויעמדו בהבטחת פני רחמיו (ויקרא כו מד) ואף גם זאת בהיותם בארץ אויביהם לא מאסתים ולא געלתים וגו' עד שיוסיפו על החרטה הנזכרת וידוי גמור ותשובה שלימה כמו שנזכר למעלה (ל ב) ושבת עד ה' אלהיך וגו'
@852 **ועתה כתבו לכם את השירה הזאת** . על דרך הפשט למשה ויהושע שניהם יצוה שיכתבוה כי רצה לעשות יהושע נביאו בחיי משה והנה משה כתבה ויהושע עומד עמו וקורא ורואה וזה טעם ויכתב משה (פסוק כב) ולמדה את בני ישראל למשה שהוא העיקר כי ממנו ישמעו וילמדו כי גם יהושע היה מלמד עמו כמו שאמר בסוף (להלן לב מד) הוא והושע בן נון וטעם השירה הזאת השירה אשר אגיד לך עתה והיא האזינו ויקראה שירה כי ישראל יאמרוה תמיד בשיר ובזמרה וכן נכתבה כשירה כי השירים יכתבו בהם הפסק במקומות הנעימה
@854 **וטעם כי ידעתי את יצרו אשר הוא עשה היום** . כטעם כי עתה ידעתי כי ירא אלהים אתה (בראשית כב יב) שהיא הידיעה בפועל כי הידיעה בעתיד ידיעה בכח ואם לא חטאו ישראל במדבר ולא נודע יצרו בפועל לא היה הגון שיעיד בהם שירה לומר הגלוי לפניו שתחטאו ואעידה בכם שתמצאנה אתכם רעות רבות וצרות כזה וכזה אבל היה הראוי שיתן להם התורה בידיעה סתם אם תאבו ושמעתם טוב הארץ תאכלו ואם תמאנו ומריתם חרב תאוכלו אבל עתה שנודע גם להם יצרם הרע ולבם הזונה יגיד להם כל הקורות אותם כענין שנאמר (ישעיה מח ד ה) מדעתי כי קשה אתה וגיד ברזל ערפך ומצחך נחושה ואגיד לך מאז בטרם תבוא השמעתיך
@856 **ויצו את יהושע בן נון** . מוסב למעלה כלפי שכינה כמו שמפורש אל הארץ אשר נשבעתי להם ואנכי אהיה עמך לשון רש"י ויפה פירש ועל דעת ר"א (בפסוק טו) ויצו את יהושע משה במצות השם ועל כן אמר אשר נשבעתי להם וכן מצינו שאמר משה ונתתי מטר ארצכם בעתו (לעיל יא יד) וכן ונתתי עשב בשדך לבהמתך (שם פסוק טו) וכן למען תדעו כי אני ה' אלהיכם (לעיל כט ה) וכן ישלח ה' בך את המארה מפני רוע מעלליך אשר עזבתני (לעיל כח כ) וכבר דברתי בהם (לעיל ה יב)
@857 **וטעם ויהי ככלות משה לכתב** . כי מתחלה כתב את התורה ויתנה אל הכהנים כאשר נאמר למעלה (פסוק ט) ולא אמר להם אנה יניחו אותה ואחרי כן נצטוה בשירה הזאת ויכתוב אותה וילמדה את בני ישראל בו ביום והנה הוסיף אותה על התורה ויהי ככלות משה לכתוב הכל בספר התורה אז צוה את הכהנים לקוח את ספר התורה הזה ושמתם אותו מצד ארון ברית ה' אלהיכם שיהיה מונח בארון מן הצד כי מעתה לא יגעו בו כלל להוסיף או לגרוע וזה טעם ויהי ככלות משה לכתב וגו' עד תמם ועל כן אמר ר"א (בפסוק א) כי וזאת הברכה מוקדמת ומקומה למעלה כאשר נאמר וילך משה וידבר את כל הדברים האלה אל כל ישראל ויתכן כי אחרי שכתב השירה וילמדה את בני ישראל איש איש לשבטיהם שהביאם לפניו אל בית המדרש כתבה בספר התורה וצוה את הכהנים לקוח את ספר התורה לומר שגם השירה תהיה מונחת בארון עם התורה שהיא מכלל התורה כי היא שם לעד ואמר להם שיקהילו אליו עוד כל זקני השבטים והשוטרים והעם יאספו עמהם כי כן נאמר בסוף (להלן לב מד) ויבא משה וידבר את כל דברי השירה הזאת באזני העם והנה עשו הכהנים כן ויקהילו אליו כל העם והעיד בהם את השמים ואת הארץ בהקהל באזני הכהנים וכל העם ואז אמר לו השם יתברך (שם פסוק מט) עלה אל הר העברים הזה ונתחייב לעשות כן מיד ועמד וברך אותם וזאת הברכה ויכתוב אותה בסוף הספר שנתן לכהנים ואז עשו הכהנים מה שצוה אותם ונתנו הספר שלם מצד ארון הברית והנה הכל כסדר האמור בתורה
@864 **האזינו השמים** . על דרך הפשט צדקו דברי ר"א כי הכתובים יתנו עדיהם בכל הדברים שהם קיימים ועומדים וכן שמעו הרים את ריב ה' (מיכה ו ב) וגם אבן יהושע כי שם כתיב (יהושע כד כז) כי היא שמעה ועל דרך האמת הם השמים והארץ הראשונים הנזכרים בבראשית כי הם יבואו בברית עם ישראל על כן אמר שיאזינו השמים וישמעו התנאים ואיך יעשה בהם
@865 **ואמר יערף כמטר לקחי** . כי מה שלקח מן השמים ואמרתו על הארץ יערף על ישראל ותזל עליהם כטל כי שם ה' אקרא בשמים הבו גדל לאלהינו בארץ ועם כל ישראל ידבר וכן אבן יהושע רמז על הארץ הזאת כי משם רועה אבן ישראל וכבר פירשתיו (בראשית מט כד) וכן אבן מאסו הבונים היתה לראש פנה מאת ה' היתה זאת וגו' (תהלים קיח כב כג) ועל כן אמר יהושע (יהושע כד כז) האבן הזאת תהיה בנו לעדה וכן כי הנה האבן אשר נתתי לפני יהושע על אבן אחת שבעה עינים וגו' (זכריה ג ט) והמשכיל יבין
@867 **הצור תמים פעלו** . רמז למדת הדין ואמר "תמים פעלו" כי הפועל הבא ממנו תמים ושלם לא ימוט ולא ישתנה לעולם כי כל דרכיו משפט הרחמים הם ולא תבוא בפועל חסרון אך במשפט כי המשפט לאל אמונה ואין עול בצור והמשפט צדיק והצור ישר
@868 **שחת לו לא בניו מומם** . המום יקרא השחתה כמו שנאמר (ויקרא כב כה) כי משחתם בהם מום בם וכן וזובח משחת לה' (מלאכי א יד) יאמר כי מומם של ישראל שחת לצור עמו ונחלתו וקראם "לא בניו" כאשר יקראם בניו בעת רצון ואמר כי הם דור עקש ופתלתל כי העקשות הפך הישר כענין שנאמר (מיכה ג ט) ואת כל הישרה יעקשו והפתלתל הפך הצדיק ואחרי שהוא צדיק וישר והעם בהפך מזה אינם בניו אבל הם משחיתים לו ושיעור הכתוב שחת לו מומם את לא בניו דור עקש ופתלתל והנה הטעם שלא בא חסרון מעלתם מפועל הצור כי הוא תמים ולא יבוא בו חסרון לעולם אבל מומם הוא המשחית אותם לפני אביהם וטעם "לא בניו" כמו ואמרתי ללא עמי עמי אתה (הושע ב כה) וכן הם קנאוני בלא אל (פסוק כא) במי שאיננו אל וישבעו בלא אלהים (ירמיהו ה ז) או יאמר שחת לו מומם שאינם בניו כי הם דור עקש ופתלתל הפך ממנו
@869 **עם נבל ולא חכם** . ששכחו הטוב שעשה להם ולא חכם להבין את הנולד שיש בידו להטיב ולהרע לשון רש"י ואונקלוס תרגם עמא דקבילו אורייתא עשאו מן נבל תבל (שמות יח יח) שפירש בו מלאה תלאה יאמר עם שנלאו בעשיית התורה ולא יתחכמו שהיא לטוב להם כל הימים וכן אמר בגוי נבל (פסוק כא) בעמא טפשא שנלאו להיות חכמים או בעלי דת ור"א אמר נבל במעשה ולא חכם בלב ולפי דעתי העושה טובת חנם יקרא נדיב ומשלם רעה למי שהטיב עמו יקרא נבל והוא שאמר (ישעיהו לב ה) לא יקרא עוד לנבל נדיב כי הוא הפכו ולכך אמרו על נבל הכרמלי (שמואל א כה כה) כשמו כן הוא נבל שמו ונבלה עמו כי דוד עשה עמו טובה גדולה ושמר את כל אשר לו והוא לא רצה לשלם לו גמול ויעט במלאכיו ויבזהו וזהו טעם הכתוב בחבריו של איוב (איוב מב ח) לבלתי עשות עמכם נבלה כי היו הם מלמדים זכות על מעשה השם הנכבד והנורא שהוא במשפט ואם ירע להם תראה נבלה ויתכן שיקרא כן בעבור שהוא נופל מבני אדם כאשר יאמר כאלה נובלת עליה (ישעיהו א ל) כמו נופלת עליה ויקראו המתה "נבלה" שנפלה לארץ ומתה כמו שאמר (שופטים יד ח) לראות את מפלת האריה אם כן יאמר הכתוב הזאת תגמלו את השם על הטובות שעשה עמכם עם נבל שהוא משלם רעה תחת טובה ולא חכם לדעת כי לנפשם גמלו הרעה הזאת לא לאל כענין שנאמר (איוב לה ו ז) אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו אם צדקת מה תתן לו או מה מידך יקח הלא האל הוא אביך כי הולידך וגדלך והוא קנך ששמך קנין כי הוציאך מאין והיית יש וכל יש יש לו קנין כענין שנאמר ה' קנני ראשית דרכו (משלי ח כב) וכן קונה שמים וארץ (בראשית יד יט) כאשר פירשתיו והוא צור עשך ויכוננך כלשון ויכוננו ברחם אחד (איוב לא טו)
@870 **שאל אביך** . רמז למבינים וכן זקניך והטעם כמו שאמר (לעיל ד יט) אשר חלק ה' אלהיך אותם וגו' כי לכל חלק במטה חלק למעלה וטעם למספר בני ישראל כי צורת יעקב חקוקה בכסא הכבוד והוא סוד גדול והעד כי חלק ה' עמו וזאת מעלה גדולה שלא עשה כן לכל גוי על כן אמר הלה' תגמלו זאת עם נבל ולא חכם שנפל ממעלתו באולתו וזה טעם אביך קנך כי קנהו לכבודו וילמדהו כאשר יפרש במעשה האב עם הבן לשון ר"א ודברי פי חכם חן ואם כן יהיה פירוש זכר ימות עולם שיתנו לב לזכור ששת ימי בראשית הטובה שעשה להם בעת היצירה כמו שיאמר בהנחל עליון גוים וגו' בינו שנות דר ודר שיבינו לדעת מה שנעשה להם בדורות מעת ששרתה שכינה ביניהם כאשר יספר ימצאהו בארץ מדבר וגו' ורש"י כתב ימצאהו בארץ מדבר אותם מצא לו נאמנים בארץ המדבר שקבלו עליהם תורתו ומלכותו ועולו מה שלא עשו ישמעאל ועשו ובתהו ילל ישמון ארץ ציה ושממה מקום יללת תנינים ובנות יענה אף שם נמשכו אחר האמונה ולא אמרו למשה היאך נצא למדבר וזה איננו מטעם הפרשה כי הכתוב מוכיח את ישראל ומזכיר הטובות אשר עשה השם עמהם והם גמלו להם רעה תחת טובה
@873 **וטעם כאישון עינו** . רמז לניצור יאמר שינצור השם אותו כאשר יצור הוא עצמו את עינו או תחסר מלת "איש" יצרנהו כאיש אישון עינו כי מן הסתם באיש ידבר וכן רבים
@875 **ה' בדד ינחנו** . השם ישכון בישראל בטח בדד ואין עמו כנוי לשם או לישראל והענין כי אין לישראל שר ומושל מכל בני אלהים שינחנו או יעזור בהנחותו בלתי השם לבדו כי הוא חלקו ונחלתו כאשר הזכיר וכבר כתבתי זה (ויקרא יח כה) ובספרי (האזינו יב) ה' בדד ינחנו אמר להם הקב"ה כדרך שישבתם יחידים בעולם הזה ולא נהניתם מן האומות כלום כך אני עתיד להושיבכם יחידים לעתיד לבוא ואין אחד מן האומות נהנה מכם כלום ואין עמו אל נכר שלא תהא רשות לאחד משרי אומות העולם לבוא ולשלוט בכם כענין שנאמר ואני יוצא והנה שר יון בא (דניאל י כ) ושר מלכות פרס עומד לנגדי (שם פסוק יג) אבל אגיד לך את הרשום בכתב אמת וגו' (שם פסוק כא)
@878 **וינבל צור ישועתו** . גנוהו ובזוהו כמו שנאמר (יחזקאל ח טז) אחוריהם אל היכל ה' ופניהם קדמה אין נבול גדול מזה לשון רש"י ור"א אומר וינבל שגרם לחלל את השם שלא יוכל להושיעו וגם זה איננו נכון בעיני כי אינו מטעם המקום שעדיין יספר את חטאיהם ולא יזכיר עונש ונקמה שיעשה בהם עד ויאמר אסתירה פני מהם והנכון בעיני מה שהזכרתי למעלה (פסוק ו) כי הנבלה תשלום רעה תחת טובה יאמר שנטש אלוה שבראו בעבור זרים וינבל בפיו ובמחשבתו צור שהיה מושיעו לאמר שאין בעבודתו רק גמול רע בעבדם הזרים ישבעו לחם ובעבדם את הצור יהיו נבזים ושפלים לכל העמים כאשר אמרו סכלינו (מלאכי ג יד טו) שוא עבוד אלהים ומה בצע כי שמרנו משמרתו וכי הלכנו קדורנית מפני השם צבאות ועתה אנחנו מאשרים זדים וגו' וכאשר תאמרנה הנשים הארורות (ירמיהו מד יח) ומן אז חדלנו לקטר למלכת השמים וגו' חסרנו כל וכן אל תנאץ למען שמך אל תנבל כסא כבודך (שם יד כא) שיאמרו עליו שהוא משלם רעה תחת טובה לעמו ועבדיו כמו שאמר (שם) אל תפר בריתך אתנו
@879 **בתועבת יכעיסהו** . הבעירו חמתו בתועבות ומעשים מכוערים כגון משכב זכר וכשפים שיש בהם תועבה לשון רש"י וכן איתא בספרי (האזינו שיח) אבל אין בשירה תוכחת אלא על ע"ז בלבד וטעם בזרים נמשך אל אלוה עשהו יקניאוהו באלהים זרים כלשון אלהים אחרים וטעם בתועבות השדים לשרוף את בניהם באש לאלהים אחרים שכל זה מתועב לפניו כמו שנאמר (לעיל יב לא) כי כל תועבת ה' אשר שנא עשו לאלהיהם כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם וכתיב (ירמיהו לב לה) אשר לא צויתים (ולא דברתי) ולא עלתה על לבי לעשות התועבה הזאת
@880 **יזבחו לשדים לא אלה** . פירשתיו (ויקרא יז ז)
@882 **מכעס בניו ובנתיו** . הזכיר הכתוב הבנות בכאן שלא כמנהג כאשר אמר למעלה (פסוק ה) לא בניו וכן בכל מקום יזכיר הבנים והבנות הן בכלל אבל זה מרמזותיו כי יהיה בדור החורבן רשע הנשים ופשעיהם גדול מאד להכעיסו כי היו נצמדות לע"ז ביותר והן שמפתות את האנשים לעבדה כאשר מפורש בדברי ירמיהו (מד טו) ויענו כל האנשים היודעים כי מקטרות נשיהם לאלהים אחרים וכל הנשים העומדות קהל גדול והן שהעיזו פניהם בנביא לאמר לו (שם פסוק יז) עשה נעשה את כל הדבר אשר יצא מפינו לקטר למלכת השמים וכתוב עוד שם (פסוק ה) מפורש להכעסני במעשי ידיכם לקטר לאלהים אחרים וכתוב עוד שם (פסוק ט) השכחתם את רעות אבותיכם ואת רעות מלכי יהודה ואת רעות נשיו ואת רעותיכם ואת רעות נשיכם וביחזקאל (ח יג יד) נאמר עוד תשוב תראה תועבות גדולות אשר המה עושים ויבא אותי אל פתח שער בית ה' וגו' והנה שם הנשים יושבות מבכות את התמוז
@883 **ויאמר** . ה' אל לבו או אל המלאכים אסתירה פני מהם כדרך לשון בני האדם וכן אעלים עיני מכם (ישעיהו א טו) והטעם כי כאשר יבקשוני לא ימצאוני אראה מה אחריתם יש אומרים אני אסתיר את פני מהם בעבור שאני רואה מה יעשו באחרונה והנכון שהוא כמשמעו עד שאראה מה יעשו בצר להם דברי ר"א ואין טעם "ויאמר" רק המחשבה והרצון לפניו לעשות כן כדרך "ויאמר אלהים" במעשה בראשית וכבר פירשתי (בראשית א ג) וטעם "פני" על דרך האמת פירשתיו (שמות ג ב שם כ ג) והנה "אסתירה פני" שאסלק שכינתי וטעם אראה מה אחריתם כטעם ארדה נא ואראה (בראשית יח כא) וכבר פירשתיו כי דור תהפכת המה ולא יעמדו בפני בנים לא אמן בם כי אין להם אומן ומגדל והמשכיל יבין והנה עד הנה בשירה זו משה ישיר בה והוא מדבר בלשון עצמו ומן הכתוב הזה ואילך שהזכיר וירא ה' וינאץ וגו' ויאמר אסתירה פני כולם דברי השם הנכבד הם קנאוני כעסוני וכל השירה כן
@884 **הם קנאוני בלא אל** . בדבר שאין אלוה לשון רש"י ואם כן ירמוז לשדים הנזכרים והנכון שיאמר הם קנאוני בלא אל אמת כי אין אלוה מבלעדי ה' ומושיע אין בלתו כענין שנאמר (דהי"ב טו ג) וימים רבים לישראל ללא אלהי אמת כעסוני בהבליהם השדים ואני אקניאם בלא עם הכשדים שנאמר בהם (ישעיהו כג יג) הן ארץ כשדים זה העם לא היה שפירושו העם שלא היה נחשב לגוי והקב"ה גדל אותם לרדות בהם את עולמו כמו שאמר (ירמיהו נא כ) מפץ אתה לי כלי מלחמה בגוי נבל אכעיסם עשו שהוא נבל ולא זכר ברית אחים וירמוז לשני הגלויות
@889 **אפאיהם** . אמרו המדקדקים אפזרם בכל פאה ואם כן יהיה טעם "אמרתי" שהיה הרצון לפניו במדת הדין שיהיו ככה לעולם מפוזרים בכל פאה ושיהיה זכרם מאנוש נשבת לעד לולי כעס אויב אגור ועל דעתי היא מלה מורכבת כאשר הזכירו בספרי (האזינו כו) אף אי הם אבל טעמה שאשיתם במקום פאה ובענין שיאמרו עליהם גם אי הם לומר שלא ישאר להם שם ושאר בגוים ולא יודע מקומם איה והנה ירמוז לגלות עשרת השבטים שגלו לנהר גוזן (מלכים ב יז ו) הוא שהחכמים קורין סמבטיון כי נקרא גוזן מלשון ויגז שלוים (במדבר יא לא) אתה גוזי (תהלים עא ו) כי העומדים אחריו מוסרים מבני אדם וקורין אותו סמבטיון מפני שביתתו בשבת כי יום השבת בלשון ההוא סבט כאשר הוא בערבי ונהוג בלשונם להוסיף בתארים "יון" אזוביון חוריון מוליון וכן הרבה אשביתה מאנוש זכרם גלותנו בין העמים אנחנו יהודה ובנימין שאין לנו זכר בעמים ולא נחשב לעם ואומה כלל והנה יאמר הכתוב כי היה במדת הדין להיותנו כן בגלות לעולם לולי כעס אויב ויורה זה כי בגלותנו עתה תמה זכות אבות ואין לנו הצלה מיד העמים רק בעבור שמו הגדול ית' כענין שאמר ביחזקאל (כ מא מד) וקבצתי אתכם מן הארצות אשר נפוצותם בם ונקדשתי בכם לעיני הגוים וידעתם כי אני ה' בעשותי אתכם למען שמי לא כדרכיכם הרעים וכעלילותיכם הנשחתות בית ישראל וכן נאמר עוד (שם פסוק ט) ואעש למען שמי לבלתי החל לעיני הגוים וגו' ולכך הזכיר משה בתפלתו (במדבר יד טו) ואמרו הגוים אשר שמעו את שמעך לאמר וגו' והשם יתברך הודה לו בזה (שם פסוק כ) ויאמר ה' סלחתי כדברך והטעם בטענה הזאת איננו כרוצה להראות כחו בין שונאיו כי כל הגוים כאין נגדו מאפס ותוהו נחשבו לו אבל השם ברא את האדם בתחתונים שיכיר את בוראו ויודה לשמו ושם הרשות בידו להרע או להטיב וכאשר חטאו ברצונם וכפרו בו כולם לא נשאר רק העם הזה לשמו ופרסם בהם באותות ובמופתים כי הוא אלהי האלהים ואדוני האדונים ונודע בזה לכל העמים והנה אם ישוב ויאבד זכרם ישכחו העמים את אותותיו ואת מעשיו ולא יסופר עוד בהם ואם אדם יזכיר כן יחשבו כי היה כח מכחות המזלות והכוכבים וחלף ועבר והנה תהיה כוונת הבריאה באדם בטלה לגמרי שלא ישאר בהם יודע את בוראו רק מכעיס לפניו ועל כן ראוי מדין הרצון שהיה בבריאת העולם שיהיה רצון מלפניו להקים לו לעם כל הימים כי הם הקרובים אליו והיודעים אותו מכל העמים וזה טעם כי ידין ה' עמו ועל עבדיו יתנחם (פסוק לו) שיזכור ה' ברחמים כי הם עמו מאז ויזכור כי הם עבדיו שעמדו לו בגלותם כעבדים לסבול הצרות והשעבוד וכענין שנאמר (ישעיהו סג ח) ויאמר אך עמי המה בנים לא ישקרו וכבר רמזתי בבריאת האדם סוד נשגב ונעלם צריך ממנו שנהיה לו לעם והוא יהיה לנו לאלהים כענין שנאמר (ישעיהו מג ז) כל הנקרא בשמי ולכבודי בראתיו וגו'
@891 **כי גוי אבד עצות המה** . וכל הפרשה על האויב הנזכר כדברי רבי נחמיה (ספרי כח) וטעם כי לא כצורנו צורם גם כן דברי האויב יאמר הכתוב שהיה להם לחשוב ולהשכיל זאת הנעשה בישראל כי הוא פעל השם על עונם ויבינו ממנה לאחרית נפשם כי כן יעשה בסוף לכל הגוים כי הם מורדים בשם יותר מישראל ישכיל ויאמרו איכה ירדוף אחד אלף מישראל אם לא כי צורם מכרם כי צורם הוא תקיף ובעל היכולת לעזור ולהציל יותר מצורנו ואיבינו פלילים היו בנו מתחלה לעשות בנו שפטים כרצונם ועתה למה בורחים מפנינו אלף מפני גערת איש אחד לולי צורם התקיף שמכרם והביא מורך בלבבם ונפלו ורודף אין פלילים מלשון אשר פללת לאחותך (יחזקאל טז נב) ויעמוד פנחס ויפלל (תהלים קו ל)
@895 **כי מגפן סדם גפנם** . יאמר כי העובדי גלולים אובדי עצות המה ולא ישכילו ולא יבינו ולא יחשבו רק רע כל היום כי משרש רע היו ולא יעשו רק פרי רע ומר האוכל ממנו ימות והענין כי ישראל מודים ומתודים ועושים תשובה בעת צרתם לאמר ולמה מצאתנו כל זאת (שופטים ו יג) אבל העובד כוכבים אובד עצות אין לו עצה ולא תבונה רק הולך אחר ע"ז שלו וכופר בשם הנכבד לעולם כי כן ירש מאבותיו והנה הוא משרש פורה ראש ולענה ואין בהם תועלת לעולם אבל ישראל ששרשם טוב אם יכרת ועוד יחליף ויעשה פרי טוב
@897 **הלא הוא כמס עמדי** . ראש הפתן האכזרי שלהם שמתי באוצרותי להאכילם מפרי מעשיהם כי לי נקם ושלם לנקום נקמת ישראל מידם ולי שלם לשלם להם כפעלם שכחשו בי לעת תמוט רגלם כשתתמלא סאתם כענין כי לא שלם עון האמורי עד הנה (בראשית טו טז) ור"א אמר שטעמו וגם רשע ליום רעה (משלי טז ד) והוא סוד גדול
@900 **ואמר אי אלהימו** . האויב יאמר איה אלהי ישראל כענין למה יאמרו הגוים איה נא אלהיהם (תהלים קטו ב) אשר חלב זבחימו יאכלו כי היו ישראל תדירים בעבודת הקרבנות והנסכים מכל גוי לאלהיו והזכיר לשון רבים יאכלו וישתו אלהימו שהוא לשון הרבים ואצל העמים רבים הם ולכך חזר ואמר ראו עמים כולם אני אני הוא יחיד ואין אלהים עמדי לעזור לי ואין כנגדי להציל ולמחות בידי מלעשות כל רצוני להמית ולמחוץ ולהחיות ולרפוא
@903 **כי אשא אל שמים ידי** . על דרך הפשט ענין שבועה בכסאו ואמר "אשא" כי כל נשבע נושא ידו ונוגע בחפץ אשר הוא נשבע בו ועל דרך האמת בעבור כי בעת הגלות השליך משמים ארץ תפארת ישראל יאמר שישאנה עתה בעת רצון אל השמים העליונים והיא היד הגדולה הנלחמת לישראל וזה טעם ואמרתי חי אנכי לעולם כי אני מחיה ידי החזקה בהיותי משנן ברק חרבי וסומך אותם לאחוז במשפטן של ישראל ולהשיב נקם לצרי כי אז יהיה השם שלם והכסא שלם והמשכיל יבין והנה השירה הזאת אשר היא בנו לעד אמת ונאמן תגיד כל המוצאות אותנו בביאור הזכירה תחלה החסד שעשה עמנו הקב"ה מאז שלקחנו לחלקו והזכירה הטובות שעשה לנו במדבר ואשר הנחילנו ארצות הגוים הגדולים והעצומים ורוב הטובה והעושר והכבוד אשר הנחילנו בה וכי מרוב כל טובה מרדו בה' לעבוד ע"ז והזכירה הכעס אשר היה מלפניו עליהם עד ששלח בהם בארצם דבר ורעב וחיה רעה וחרב ואחרי כן פזר אותם בכל רוח ופאה וידוע כי כל זה נתקיים ויהי כן ואמרה השירה כי בסוף ישיב נקם לצריו ולמשנאיו ישלם והטעם כי הם עשו כל הרעות עמנו לשנאתו של הקב"ה כי לא ישנאו את ישראל בעבור שעשו ע"ז כהם רק בעבור שלא יעשו כמעשיהם ויעבדו את הקב"ה וישמרו את מצותיו ולא יתחתנו בהם ולא יאכלו מזבחיהם ויבוזו ע"ז שלהם ויבערו אותה ממקומותיהם וכענין שאמר (תהלים מד כג) כי עליך הורגנו כל היום אם כן לשנאתו של הקב"ה יעשו בנו כל הרעות האלה והם צריו ומשנאיו ועליו להנקם מהם וזה דבר ברור כי על הגאולה העתידה יבטיח כי בבנין בית שני לא הרנינו גוים עמו רק לעגו עליהם (נחמיה ג לד) מה היהודים האמללים עושים והיו גדוליהם עבדים בהיכל מלך בבל וכולם משועבדים לו ובימים ההם לא השיב נקם לצריו ולא כפר אדמתו עמו והנה אין בשירה הזאת תנאי בתשובה ועבודה רק היא שטר עדות שנעשה הרעות ונוכל ושהוא יתברך יעשה בנו בתוכחות חימה אבל לא ישבית זכרנו וישוב ויתנחם ויפרע מן האויבים בחרבו הקשה והגדולה והחזקה ויכפר על חטאתינו למען שמו אם כן השירה הזאת הבטחה מבוארת בגאולה העתידה על כרחן של מינין וכך הזכירו בספרי (האזינו מג) גדולה שירה זו שיש בה עכשיו ויש בה לשעבר ויש בה לעתיד לבוא ויש בה בעולם הזה ויש בה לעולם הבא ולזה רמז הכתוב שאמר (פסוק מד) ויבא משה וידבר את כל דברי השירה הזאת באזני העם הזכיר "כל" להגיד שהיא כוללת כל העתידות למו ואם היא קטנה בדבור כי ביאר להם עניניה הרבים ואלו היתה השירה הזאת מכתב אחד מן החוזים בכוכבים שהגיד מראשית אחרית כן היה ראוי להאמין בה מפני שנתקיימו כל דבריה עד הנה לא נפל דבר אחד ואף כי אנחנו נאמין ונצפה בכל לב לדברי האלהים מפי נביאו הנאמן בכל ביתו אשר לא היה לפניו ואחריו כמוהו עליו השלום
@916 **איש האלהים** . להגיד כי ברכתו מקויימת כי איש האלהים היה ותפלת ישרים רצונו והנה יקרא הכתוב למשה רבינו "איש האלהים" וכן שאר הנביאים ואליהו וזולתם ולא יאמר הכתוב "איש ה'" אבל יאמר משה עבד ה' (להלן לד ה) והטעם ידוע לכל משכיל וכן על דרך האמת וזאת היא הברכה כי מאת ה' היתה זאת (תהלים קיח כג) וכן ביעקב נאמר (בראשית מט כח) וזאת אשר דבר להם אביהם זאת הברכה הוא שאמר דוד (תהלים קיט נו) זאת היתה לי כי פקודיך נצרתי ירמוז לציון עיר דוד כי שם צוה ה' את הברכה חיים עד העולם והמשכיל יבין ולזה הסוד נתכוונו רבותינו במדרש שאמרו בבראשית רבה (ק יג) וזאת אשר דבר להם אביהם עתיד אדם כיוצא בי לברך אתכם וממקום שפסקתי אני משם הוא מתחיל כיון שעמד משה רבינו פתח להם בוזאת הברכה מאותו מקום שפסק להם אביהם הוי וזאת אשר דבר להם אביהם אמר להם הברכות הללו אימתי מגיעות אתכם משעה שתקבלו את התורה שכתוב בה וזאת התורה וגו' כי המלה הזאת תרמוז לברכה שהיא התורה והיא הברית דכתיב (בראשית יז י) זאת בריתי וכבר הזכרתי זה (ויקרא טז ג)
@917 **ה' מסיני בא** . יאמר כי השם מסיני בא לישראל כי משם השכין שכינתו בתוכם ושוב לא נסתלקה מהם והענין כי ירד הכבוד בהר סיני כמו שנאמר (שמות יט כ) וירד ה' על הר סיני אל ראש ההר ויקרא ה' למשה וגו' ושם היה כל הימים שהיה משה עולה ויורד כמו שנאמר (שם כד יז) ומראה כבוד ה' כאש אוכלת בראש ההר וגו' וכאשר נתנו לו הלוחות האחרונות שכן הכבוד באהל מועד כמו שנאמר (שם לג ט) והיה כבא משה האהלה ירד עמוד הענן ועמד פתח האהל ודבר עם משה וכתיב (שם פסוק יא) ודבר ה' אל משה פנים אל פנים וגו' וכאשר הוקם המשכן שכן הכבוד במשכן שנאמר (שם מ לד) ויכס הענן את אהל מועד וכבוד ה' מלא את המשכן ומשם היו לו כל הדברות כל ימי המדבר וזרח משעיר למו כי אחרי נסעם מסיני במסע ראשון שכן הענן במדבר פארן ומשם שלח מרגלים שנאמר (שם יג ג) וישלח אותם משה ממדבר פארן ונתנדה העם ולא היה הדבור עם משה עד שבאו לשעיר בגבול בני עשו בסוף הארבעים (לעיל ב ב) כמו שנאמר שם (פסוק ז) כי ה' אלהיך ברכך בכל מעשה ידך ידע לכתך את המדבר הגדול הזה זה ארבעים שנה ה' אלהיך עמך והנה אז בבואם בשעיר היה השם להם לאור עולם ושלמו ימי אבלם וצוה אותם להשמר משעיר ועמון ומואב ואמר שיחלו לרשת את ארצם וירשו ארץ סיחון ועוג שני מלכי האמורי הגדולים הופיע מהר פארן שנסתכל בהם ושם ענינם למאור פניו מהר פארן והטעם כי תחלת הכנסם במדבר הגדול היה מפארן כמו שנאמר (במדבר י יב) ויסעו וגו' ממדבר סיני וישכן הענן במדבר פארן והנה השם הופיע עליהם לראות מה הם צריכים במדבר הגדול והנורא מלשון ועל עצת רשעים הופעת (איוב י ג) נסתכלת וראית באורך הגדול כל סתרי מחשבותיהם ואתה מרבבת קדש מימינו אש דת למו יאמר כי בא הכבוד לישראל מרבבות קדושי עליון אשר ירדו עמו על ההר כענין שנאמר (תהלים סח יח) רכב אלהים רבותים אלפי שנאן ה' בם סיני בקדש מימינו אש דת למו פירוש מימין תפארתו היה להם אש דת לא מיד המלאכים הנזכרים רק מימין השם בעצמו ובכבודו ויתכן כי "מרבבות קדש" מרבוי קדושתו כי קדוש קדוש קדוש ה' צבאות בכל מיני קדושה וטעם "אש דת למו" כמו "דת אש" כמו שאמר (לעיל ה כא) ואת קולו שמענו מתוך האש או טעמו כמו "אש ודת למו" יזכיר שהראה להם האש העליונית והשמיעם הדת וזה כענין שנאמר (לעיל ד לו) ועל הארץ הראך את אשו הגדולה ודבריו שמעת מתוך האש ועל דרך האמת יגיד גם כן שהאש שהוא הדת היא מימינו כי מדת הדין כלולה ברחמים ועל דעת רבותינו טעם הכתוב כי מסיני בא לתת תורה לישראל שנגלה להם משם וזרח משעיר להם לישראל כי נגלה על בני עשו לתת להם התורה וכאשר לא רצו בני עשו לקבל אותה האיר פניו לישראל ונתנה להם בימינו ובזרועו ואור פניו כי רצם והופיע והראה להם יפעתו והדרת פניו מהר פארן כאשר לא רצו בני ישמעאל בתורה יזכיר כי היה זכות לישראל גדולה כאשר לא רצו שאר האומות לקבל את התורה והנה הזכיר כל זרע אברהם שאחד מהם לא היה חפץ בתורה זולתי ישראל אבל על כל האומות גם כן נגלה לתת אותה להם ולא רצו בה כפי הבא בקבלת רבותינו (ע"ז ב)
@918 **אף חבב עמים** . פירשו בו שהוא מלשון ארמית ותהון קדמי חביבין (שמות יט ה) יאמר אף חובב את ישראל שהוא עמים רבים כענין אחריך בנימין בעממיך (שופטים ה יד) וכל קדושיו של ישראל הם הלוים הם בידך כי הקרבתם אליך להיות חונים סביבות הארון והנראה אלי כי "חובב" מגזרת לטמון בחובי עוני (איוב לא לג) מענין חדר בחדר להחבא (דהי"ב יח כד) ושם חביון עזו (חבקוק ג ד) יאמר גם אתה בידיך מחביא ומסתיר עמים כל קדושי ישראל הנזכר ירמוז כי כל העדה כלם קדושים והשם יסתירם בידו כטעם ואשים דברי בפיך ובצל ידי כסיתיך (ישעיהו נא טז) כענין סתרי ומגני אתה (תהלים קיט קיד) וכן ויתיעצו על צפוניך (שם פג ד) וזה רמז למה שאמר (במדבר יד יד) אשר עין בעין נראה אתה ה' ועננך עומד עליהם וכן אמר בשירה (לעיל לב י) יסובבנהו יבוננהו יצרנהו כאישון עינו והם תכו כמו הכו כאשר בא תרגלתי לאפרים (הושע יא ג) במקום הרגלתי וכאשר הומרה ה"א הנקבה בתי"ו באם אתן שנת לעיני (תהלים קלב ד) עושה רע מאת (קהלת ח יב) וכן רבים יאמר שהם מוכים בכל מכה במדבר ללכת אחריך בכל אשר תלך לא יחושו לרעב ולצמאון ומכת נחש ועקרב רק יצאו לרגליך ואחריך ירוצו וזה כענין שנאמר (ירמיהו ב ב) זכרתי לך חסד נעוריך אהבת כלולותיך לכתך אחרי במדבר בארץ לא זרועה ישא מדברתיך כמו לא תשא את שם ה' אלהיך לשוא (שמות כ ז) ובל אשא את שמותם על שפתי (תהלים טז ד) ישא ביום ההוא לאמר (ישעיהו נ ז) מדברותיך כמו ומדברך נאוה (שיר השירים ד ג) יאמר שישא דבריך על שפתיו ויהגה בהם תמיד
@919 **תורה צוה לנו משה** . הטעם שישא תמיד ויאמר תורה צוה לנו משה והיא תהיה מורשה לקהלת יעקב כי לדורות עולם כל בני יעקב יירשוה וישמרו אותה כי לא תשכח מפי זרעו ודרשו רבותינו (מדרש תהלים א) שלא אמר מורשה בית יעקב או זרע יעקב ואמר "קהלת יעקב" לרמז שיקהלו רבים עליהם ותהיה התורה לעולם מורשה ליעקב ולכל הנקהלים עליו הם הגרים הנלוים על ה' לשרתו ונספחו על בית יעקב ונקראו כלם קהלתו
@920 **ויהי בישרון מלך** . רמז אל השם הנזכר שהיה למלך על ישראל בהיותם ישרים ונאספו כל ראשי העם וכל שבטי ישראל יחד וגם זה הכתוב דבוק והטעם כי ישראל יאמרו תמיד התורה אשר צוה לנו משה תהיה ירושה לכל קהלת יעקב לעדי עד לא נחליף ולא נמיר אותה לעולם ויאמרו שהיה השם למלך על ישראל בהתאסף ראשינו זקנינו ושופטינו וכל שבטי ישראל שכולנו יחד קבלנו מלכותו עלינו לדור ודור ואנחנו חייבין לשמור תורתו ומלכותו לעולמים וזו המצוה הוא דבור אנכי והיא קבלת מלכות שמים כאשר פירשתי שם (שמות כ ב) והנה הזכיר התורה בכלל ומלכות שמים בפרט שכל המודה במלכות שמים כופר בע"ז ומודה בכל התורה כולה ורמזו כי הם וראשיהם קבלו מלכות שמים מפי הגבורה וראו שהוא מלך ישראל וגואלו והתורה קבלו מפי משה שקבלו עליהם ועל זרעם להאמין בו ולעשות כל אשר יצוה מטעם המלך כאשר אמרו (לעיל ה כד) ואת תדבר אלינו את כל אשר ידבר ה' אלהינו אליך ושמענו ועשינו וזה הפירוש ברור ונכון בכתוב הזה על דרך שהזכירו בגמרא במסכת ראש השנה (לב) אלא מלכיות תלתא הוא דהויין ה' ימלוך לעולם ועד (שמות טו יח) ה' אלהיו עמו ותרועת מלך בו (במדבר כג כא) ויהי בישורון מלך וכן שנינו בספרי (ברכה שמו) מושב זקנים בישיבה של מטה שמו הגדול משתבח למעלה שנאמר ויהי בישרון מלך בהתאסף ראשי עם יחד שבטי ישראל אין אסיפה אלא זקנים שנאמר (במדבר יא טז) אספה לי וגו' יחד שבטי ישראל כשהן עשויין אגודה אחת ולא כשהן עשויין אגודות אגודות וכן הוא אומר (עמוס ט ו) הבונה בשמים מעלותיו וגו' ובמדרש רבה (במדב"ר טו יד) נמי אמרו כביכול כסאו מבוסס למעלה בזמן שישראל עשויין אגודה אחת לכך נאמר הבונה בשמים מעלותיו ואגודתו על ארץ יסדה וכן ויהי בישורון מלך בהתאסף ראשי עם וגו' וגם זה על הדרך שפירשתי ידרשו שהיה מלך עליהם מפני שנתאספו ויחדו כולם קבלו מלכותו עליהם וכן יהיה מורשה לקהלת יעקב והמלך הוא הקב"ה וכן נהגנו לומר בתקיעתא דברי רב אבל יש במקצת האגדות שמפרשין אותו על משה אומרים משה מלך שנאמר ויהי בישורון מלך בהתאסף וגו' וא"כ (ס"א וג"כ) אמר הכתוב תורה צוה לנו משה להיותה מורשה לקהלת יעקב והוא היה מלך עלינו ועל כל שבטינו יחד וראוי לנו לעשות דבריו ומצותיו כי מלך גדול וחכם היה עלינו יספר הכתוב גם בכבוד השליח שהיה גדול וראוי להאמין בו והנכון והאמת מה שפירשנו והנה הזכיר כי השם שוכן בישראל והנה קבלו תורתו ומלכותו כל שבטיהם יחד עליהם ועל זרעם לדורותם אם כן הנם ראויים לברכה
@921 **יחי ראובן** . אמר ר"א כי החל מראובן שהוא הבכור ולא הזכיר שמעון בעבור עון פעור כי העובדים היו שמעונים ומספרם לעד גם נשיאם נהרג וכן דעת רש"י והמפרשים ולפי דעתי אין מספרם ראיה בעבור כי עדיין יחסרו שלשה עשר אלף ויותר מלבד המתים במגפה וגם משאר השבטים יחסרו קצת כי בני גד חסרו חמשת אלפים ובני אפרים שמונת אלפים ועוד כי הכתוב שאומר (במדבר כה ג) ויצמד ישראל לבעל פעור ואמר (שם פסוק ד) קח את כל ראשי העם נראה שהיו בהם מכל השבטים וכל דייניהם ישפוטו בם וכן אמר (שם פסוק יא) ולא כליתי את בני ישראל בקנאתי ואל תשיב עלי מדבר עכן שאמר (יהושע ז יא) חטא ישראל כי שם לא נתגלה החטא ויזכירם סתם וכן המוכה איננו ראיה כי היה נשיא בית אב בהם לא נשיא השבט והנועדים על ה' בעדת קרח גדולים ונכבדים ממנו שהיו נשיאי עדה ולא הלכו כל שבטיהם אחריהם והמזמור הזכיר דתן ואבירם וענינם בשמם (תהלים קו יז) תפתח ארץ ותבלע דתן ותכס על עדת אבירם והזכיר ויצמדו לבעל פעור (שם פסוק כח) עם וימאסו בארץ חמדה (שם פסוק כד) לכלל העם וחלילה שימנע משה מלברך את שמעון ולא ימחה שבט מישראל שכבר כלו הנצמדים לבעל פעור כמו שאמר (לעיל ד ג) כי כל האיש אשר הלך אחרי בעל פעור השמידו ה' אלהיך מקרבך ואלה הנשארים כולם כתיב בהם (שם פסוק ד) ואתם הדבקים בה' אלהיכם חיים כולכם היום ולמה לא יברכם והנה כולם עשו את העגל וחטאו במרגלים ונתכפר להם וברכם וראיתי במדרש רבה (במדב"ר כא ט) ששה משפחות נחסרו על הזנות בעצת בלעם ומנה משפחה אחת לשמעון וחמשה מבני בנימין והנה לדעתם בנימין חטא יותר משמעון באותו החטא והוא בכלל הברכה והנכון בעיני כי הכתוב לא ימנה בשבטי ישראל רק שנים עשר וכך אמר בברכת יעקב (בראשית מט כח) כל אלה שבטי ישראל שנים עשר והנה יעקב הזכיר בניו השנים עשר והזכיר יוסף בשבט אחד ומשה ראה להזכיר ביוסף שני שבטים כמו שאמר (פסוק יז) והם רבבות אפרים והם אלפי מנשה והיה זה בעבור שני דברים האחד כי אחר שצוה הקדוש ברוך הוא ועשאם שני שבטים בחנכת המזבח ובדגלים ובנחלת הארץ הנה הוא צריך למנותם שנים בברכתם ועוד שהזכיר יהושע המנחילם את הארץ והוא מאפרים הקטן והוצרך להזכיר אחיו שגדול ממנו והנה רצה לברך את לוי כי מברכתו יתברכו כל ישראל שיהיו קרבנותיו לרצון להם לפני השם והוצרך להשאיר אחד מן השבטים שאינן נימנין בשום מקום רק שנים עשר כנגד שנים עשר מזלות ברקיע ושנים עשר חדשים בשנה ושנים עשר גבולי אלכסונין שאמרו במדרש שהם הן זרועות עולם וכמו שהזכירו חכמים במסכת ברכות (לב) אמר הקב"ה לנביא לך ואמור לכנסת ישראל בתי שנים עשר מזלות בראתי ברקיע כנגד שנים עשר שבטים וכן בהר גריזים והר עיבל (לעיל כז יב) שמנה לוי לא נגזר שם יוסף לשני שבטים וכן תראה בחלוק יחזקאל (מח ד ה) שמנה בחלוקת הארץ יוסף לשני שבטים ולא הזכיר לוי וכשמנה תוצאות העיר הזכיר (שם פסוק לא) שער לוי אחד ולא מנה שבט יוסף לשני שבטים אבל אמר (שם פסוק לב) שער יוסף אחד כי לעולם לא ימנו שבטי ישראל רק שנים עשר וכבר זכרתי זה בסדר ויקח קרח (במדבר יז יז) והנה השאיר שמעון שלא היה שבטו גדול ולא היתה בו ברכת יעקב אביהם מרובה אבל חלקם ביעקב והפיצם בישראל (בראשית מט ז) והנה יתברכו גם הם מברכת שאר השבטים אשר המה בתוכם וסדר זאת הברכה היתה ברוח הקדש על דרך נחלתם החל מראובן כי לקח נחלתו בראשונה ועוד כי הוא הבכור ומשה התפלל עליו שלא ימחה שמו בחטאו ולכך נתן לו בברכתו משפט הבכורה ואחר כן הקדים יהודה כי הוא הנוחל הראשון בארץ ולנגיד ממנו והוא העולה בתחלה למלחמה אשר בה יברך אותו והנה ברכתו כוללת כל ישראל ואחר כן ברך לוי החונים עם בני יהודה (ס"א ועיר ירושלים) בירושלים ושם יהיו קרבנותם לרצון ואחרי כן ברך בנימין שהיתה נחלתם עם בני יהודה ועיר ירושלים ובית המקדש בין בני יהודה ובין בני בנימין והלוים יחנו עם שניהם ואחרי כן ברך בני יוסף כי כן היתה נחלתם שנאמר (יהושע יח יא) ויעל גורל מטה בני בנימין למשפחותם ויצא גבול גורלם בין בני יהודה ובין בני יוסף ואחרי כן השלים לברך בני הגבירות והקדים זבולון ליששכר כאשר עשה יעקב (בראשית מט יג יד) וכן נפל גורלם השלישי לבני זבולון (יהושע יט י) והגורל הרביעי לבני יששכר (שם פסוק יז) ואחרי כן ברך בני השפחות דן ונפתלי ואשר כסדר תולדותם והוא הדגל שלהם והקדים גד לכל בני השפחות כי לקח נחלתו תחלה עם ראובן המוקדם והוא היה מדגל הראובני וטעם יחי ראובן שיחיה שבטו ולא ימות לעולם ויהי מתיו מספר כמו ולא למדתי חכמה ודעת קדושים אדע (משלי ל ג) ואל יהיו מתיו מספר שלא יהיו מעטים שכל דבר שיספר הוא מעט וכן ואני מתי מספר (בראשית לד ל) לשון ר"א ויותר נכון לפרש יחי ראובן בישראל ואל ימות שלא יכרת שבטו באחד מכל הזמנים ויהי פקודיו במספר בני ישראל לעולם יתפלל עליו שלא יגרום חטאו והכעס הגדול אשר כעס עליו אביו בחללו יצועיו להכרית שמו מישראל וזה כענין שנאמר שם (שם לה כב) וילך ראובן וישכב את בלהה פילגש אביו וישמע ישראל ויהיו בני יעקב שנים עשר כי הודיע שלא יצא בחטאו מן המספר וכן פירש רש"י וטעם "מתיו" שכל אנשיו יזכו בזה ולא יכרת אפילו מקצת השבט בחטאו ואולי "מתיו" רמז לראשי משפחותיו הארבע ויהיה טעם "מספר" כמו במספר וכן לזנות בית אביה (לעיל כב כא) ירחצו מים (שמות ל כ) ורבים כן או טעמו שיהיו מתיו מספר ישראל שימנה ראשון כמשפט הבכור כי האחד הוא המספר כי ממנו הכל ואונקלוס תרגם ויקבלון בנוהי אחסנתהון במנינהון יתכוין למה שפירשנו יאמר שיחיה ראובן ולא יכרת ויהיו מתיו במספרם לעולם לא ימחה שבטו מישראל ולא ימנו ביותר מספרם להיותן שני שבטים שלל ממנו הבכורה והבטיחו בשבט אחד לעולם ויש מפרשים כי הברכה הזאת על כבוש הארץ יאמר שיחיה ראובן בעברם חלוצים למלחמה לפני בני ישראל והטעם שיתגברו ולא ינוצחו כטעם ועל חרבך תחיה (בראשית כז מ) ואל ימות שלא יפלו מהם במלחמה ויהי מתיו מספר שיחזרו לאהליהם במספרם ולא יפקד מהם איש וכן בברכת גד חבירו הזכיר זה הענין והפירוש הזה קרוב אבל הראשון נכון יותר בעיני כי ברכת משה כדרך אשר הזכיר יעקב וכענין ההוא ועל דרך האמת יחי ואל ימות מטעם פוקד עון אבות על בנים ושם (שמות כ ה) רמזתי סודו והועילה ברכת משה לכפר לו מעשה בלהה שלא יכרת וימות בו לעולם אבל פקד עליו עם שאר השבטים מעשה יוסף כפי הבא בפרקי היכלות
@922 **וזאת ליהודה** . וכן אמר ליהודה שיחיה ולא ימות והוסיף לו עוד שמע ה' קול יהודה דעת רבי אברהם וזה איננו נכון על פירושנו כי אין יהודה בכרת הזה שיתפלל עליו כן כאשר לא הזכיר זה בשאר השבטים אבל הוא כפשוטו וזאת הברכה אשר ליהודה ועל דרך האמת ייחד המדה הזאת ליהודה בעבור כי להם המלחמה וממנו המלכות לעולם והיא העזר מצריו והוא סוד הכתוב שאמר ( א יח) ללמד בני יהודה קשת הנה כתובה על ספר הישר כי הוא הקשת הנראה בענן שנאמר בה (בראשית ט יז) זאת אות הברית שמע ה' קול יהודה יתפלל עליו בצאתו למלחמה כי הוא יעלה בתחלה ולנגיד ממנו שילחם באויבי ישראל וכן אמר יעקב (שם מט ח) ידך בערף אויביך ואל עמו תביאנו שישוב לשלום ידיו רב לו יהיו ידיו רב לו שלא יצטרך לעזר אחר זולתי עזרת השם שיענהו בתפלתו ככל הכתוב בדברי אונקלוס וכן דעת המפרשים ועל דעתי עוד ירמוז למלחמתו הראשונה אל הכנעני שאמר השם יהודה יעלה בתחלה (שופטים א ב) ואמר "ידיו רב" שיקח מצריו ויכבוש מהם ארצות רבות יותר מן הראוי לו בנחלתו ירמוז שינחיל מנחלתו לשמעון אחיו הוא שנאמר (יהושע יט ט) מחבל בני יהודה נחלת בני שמעון כי היה חלק בני יהודה רב מהם וינחלו בני שמעון בתוך נחלתם והנה הזכיר שמעון ברמז עם יהודה
@923 **וללוי אמר** . על לוי אמר לשון רש"י (ס"א ר"א וכן) דעת המפרשים והוא כלשון אמרי לי אחי הוא (בראשית ב יג) וישאלו אנשי המקום לאשתו (שם כו ז) והרבה כן ולפי דעתי כי בעבור שהזכיר משה בברכתו שם ראובן ויהודה יחי ראובן קול יהודה ולא יזכיר שם שאר השבטים בברכתם יזכיר הכתוב וללוי אמר לבנימין אמר יגיד כי השבטים לפניו ויקרא ללוי וישים עיניו עליו ויאמר תומיך ואוריך וכן בכל שבט ושבט פנים בפנים יברך אותם אשר נסיתו במסה שנסית אותו בנסיון והטעם שהיה חסיד בכל אשר נסית אותו ולא נמצא בו דופי חוץ ממי מריבה שכבר הענשתו עליו כי העגל לכבוד השם עשהו לשון ר"א ובספרי (ברכה שמט) אשר נסיתו במסה הרבה נסיתו ונמצא שלם בכל הנסיונות תריבהו על מי מריבה סקופים נסקפת לו על מי מריבה אם משה אמר (במדבר כ י) שמעו נא המורים אהרן ומרים מה עשו והנכון בעיני בדרך הפשט כי "במסה" כפשוטו הוא המקום אשר נסו השם ברפידים (שמות יז ז) יאמר תומיך ואוריך יהיו לעולם לאיש חסידך ולזרעו אחריו אשר נסית אותו במסה כאשר חטאו בני ישראל וינסו את השם על המים ולא היה בתוך העדה הנועדים שם על השם כי האמין בשם ובדברו שיוציא להם מים מצור החלמיש ובפעם השנית תריבהו ותעניש אותו על מי מריבה של ישראל כי בעבור מריבתם היה עליו העונש ולא שמעל הוא בה' כי גם מתחלה האמין כי אתה ההפכי הצור אגם מים אף כי בפעם הזאת שכבר ראה כן ירמוז משה כי החטא ההוא היה מפני העם כי בעבור מריבתם חשבו משה ואהרן שיצטרכו לעשות מה שעשו שמא נסתלקה השכינה בעבור ענשם והוא שנאמר (תהלים קו לב) ויקציפו על מי מריבה וירע למשה בעבורם וטעם "תריבהו" כמו ריבה ה' את יריבי (שם לה א) ששלמת לו משפט הריב שרבו בני ישראל את ה' ויתכן שיהיה פירושו כמו שאמר בספרי שהם סקופים כלומר עלילות ירמוז למיעוט החטא וגודל העונש כדרך בקרובי אקדש (ויקרא י ג) וכן דעת אונקלוס שאמר דנסיתוהי בנסיתא והוה שלים מריב בני ישראל ומנסותם את ה' וכיון שהיה שלם בפעם הראשונה כל שכן בשניה שהיה מאמין בדבר השם ובחנת לבו על מי מריבה ומצאת לבבו נאמן לפניך כי גלוי וידוע לפני כסא כבודך שהוא מאמין בך ובדבריך אבל בשביל ישראל היה העונש עליו כמו שפירשתי בפסוק גם בי התאנף ה' בגללכם (לעיל א לז) והנה מתחלה דבר בכהנים כי אמר ללוי שיהיו האורים והתומים לאיש חסידו מהם ואחרי כן בכל השבט שנסה אותם בעגל ובמצרים ובמדבר ועל כן יורו משפטיו ליעקב וכן דעת אונקלוס שאמר כשירין אילין דילפין דינך וגו' או על העתיד ידבר בהם כדברי ר"א וירו משפטיך על כולם וישימו קטורה על הכהנים מהם
@926 **וטעם ברך ה' חילו** . שיהיו חיל גדול והטעם שירבו ולא ימעטו בבואם אל הקדש כטעם אל תכריתו את שבט משפחות הקהתי (במדבר ד יח) וכן נאמר באזהרות שלהן (שם פסוק יט) ולא ימותו ואונקלוס אמר נכסוהי מלשון ואת כל מקנהם ואת כל חילם (שם לא ט) יתכוין למה שאמרו רבותינו (יומא כו) בקטורת שהיא מברכת והוא דבק אל ישימו קטורה באפך כי ממנה יתברך חילו כמו ששנינו (שם) חדשים לקטורת ובספרי (ברכה שנב) ברך ה' חילו בנכסים מכאן אמרו רוב כהנים עשירים הם משום אבא דורש אמרו נער הייתי גם זקנתי ולא ראיתי צדיק נעזב (תהלים לז כה) זה זרעו של אהרן
@927 **ידיד ה' ישכן לבטח עליו** . יקרא לבנימין ידיד ה' יאמר בנימין שהוא ידיד השם ישכון בארצו לבטח על השם והשם יהיה חופף עליו כל הימים ומשרה שכינתו בתוך ארצו ובין כתפיו ירמוז למה שדרשו בו רבותינו (זבחים נד) ועל דרך האמת ידיד ה' ישכון על בנימין ויהיה זה לבטח לבנימין שיבטחו בה' עדי עד כי ביה ה' צור עולמים והוא יהיה חופף ומגין על בנימין כל היום ולא יבושו בעת צרה ובין כתפיו של בנימין ישכון לעד ומכאן נקרא שלמה ידידיה בעבור ה' ( יב כה) ובנה ידידות משכנותיו כאשר נקרא שלמה גם כן לומר שמדתו שלימה בשלום ולפיכך נכתב בה"א ואמרו במדרש של ר' נחוניא בן הקנה אמר לו הקב"ה הואיל ושמך כשם כבודי אתן לך את בתי דכתיב (מלכים א ה כו) וה' נתן חכמה לשלמה ולא פירש והיכן פירש להלן (שם ג כח) כי ראו כי חכמת אלהים בקרבו לעשות משפט וגו' ונכון הדבר שירמוז בשלש השכינות הללו על שלשה מקדשים יאמר במקדש ראשון ישכון לבטח עליו כענין שנאמר (דהי"ב ז א) וכבוד ה' מלא את הבית ואמר על בית שני חופף עליו כל היום שלא שרתה בו השכינה רק היתה מכסה ומגינה עליו או חופף ממש כמו שהוזכר בפרקי היכלות ובין כתפיו שכן לימות המשיח כי ביום ההוא יקראו לירושלים כסא ה' (ירמיהו ג יז) ועל דרך זה נדרש בספרי (ברכה שנב)
@928 **ממגד שמים** . מגד לשון מעדנים ומתק וממגד תבואת שמש שהיתה ארצו פתוחה לחמה וממתקת את הפירות גרש ירחים יש פירות שהלבנה מבשלתן והן קשואין ודלועין גרש ירחים שהארץ מגרשת ומוציאה מחדש לחדש לשון רש"י ואם כן יהיה עם פרי מגדים (שיר השירים ד יג) פרי ממתקים יברך אותו שתהיה ארצו ממתק השמים שיהיה מן הטל ותהיה מבורכת מן התהום שתהיה רובצת תחת ארצו להיות עינות ותהומות יוצאים בבקעה ובהר ויתכן שהפירות יקראו מגדים ויאמר שתהיה ארצו מבורכת מפרי השמים שהוא הטל ובעבור היות המגדים בטל יקרא מגד ותהיה מבורכת מתהום תחתיה וברכתו כעין יעקב שאמר (בראשית מט כה) ברכות שמים מעל ברכות תהום רובצת תחת וטעם "גרש ירחים" המגדים אשר יגרשו הירחים כי כל האילנות בחדשיהם יציצו ויפרחו לשאת ענף ולעשות פרי וזה טעם לחדשיו יבכר (יחזקאל מז יב) בחדשיו הידועים לפרי ההוא יבכר לפני כל שאר האילנות
@931 **וממגד ארץ ומלאה** . ממגד ארץ המישור ומאשר היא מלאה כי הזכיר ההרים והגבעות ויזכיר הבקעה וארץ המישור כדברי רבי אברהם ועל דעתי מגד ארץ ומלואה ברכות שדים ורחם כי כל האדם וכל הרמש אשר הוא חי יקרא מלואה וכן ירעם הים ומלואו (תהלים צו יא) כי אם מלאתיך אדם כילק (ירמיהו נא יד) והנה זה כטעם ברוך פרי בטנך ופרי אדמתך ופרי בהמתך (לעיל כח ד) ורצון שכני סנה נמשך למעלה ומרצון שוכני סנה ויקרא השם הנכבד "שוכני סנה" כי שם נראה אליו בתחלה ושכן ימים רבים על הר סיני שהוא מקום סנה ומסיני בא ושכן בישראל וטעם הכתוב שתהיה ארצו מבורכת מרצון השם כטעם רצית ה' ארצך (תהלים פה ב) וארצה בו ואכבדה (חגי א ח) וטעם "תבואתה" הברכה הזאת תבוא לראש יוסף ולקדקד נזיר אחיו או טעמו רצון שוכני סנה תבוא לראש יוסף ואל תתמה על החפץ שיכנה אותו בלשון נקבה כי כן בלשון ארמית ורעות מלכא (עזרא ה יז) ולשון חכמים חפצת נפשו ועל דרך האמת יאמר שהרצון ששכן בסנה היא תבוא לראש יוסף שבה ירים ראש והזכיר סמוך במקום מוכרת וכמוהו רבים או יסמוך אל השם הנכבד הנזכר ורצון ה' השוכן בסנה תבוא לראש יוסף וזאת ברכת יעקב (בראשית מט כה) מאל אביך ויעזרך ואת שדי ויברכך
@932 **בכור שורו הדר לו** . יש בכור שהוא לשון גדולה ומלכות אף אני בכור אתנהו (תהלים פט כח) וכן בני בכורי ישראל (שמות ד כב) מלך היוצא ממנו הוא יהושע כחו קשה כשור לכבוש כמה מלכים וקרני ראם קרניו שור כחו קשה ואין קרניו נאות ראם קרניו נאות ואין כחו קשה נתן ליהושע כחו של שור ויופי קרני ראם והם רבבות אפרים אותם המנוגחים הם הרבבות שהרגם יהושע הבא מאפרים והם אלפי מנשה האלפים שהרג גדעון במדין שנאמר (שופטים ח י) וזבח וצלמונע בקרקר וכמה אלפים נמנו שם לשון רש"י והנה הכתוב מבולבל מאד בפירוש הזה כי "קרני ראם קרניו" כנוי לבכור השור שהוא יהושע ואם כן איך ינגח בהם אלפי מנשה שהם הרוגי גדעון ולשון ספרי (ברכה שנג) לפי שלא פירש לנו כמה הרג יהושע בכנענים תלמוד לומר וזבח וצלמונע בקרקר הכל קל"ה אלף לכך נאמר והם אלפי מנשה וכונתם בזה לדרוש כי גם "בהם ינגח יחדו אפסי ארץ" רמז ליהושע ואמר שאפסי ארץ אלה שינגח הם הרבבות שהרג אפרים הוא יהושע והם האלפים שהרג מנשה אחרי כן שכולם הרגם יהושע ובניהם הקמים אחריהם הרג מנשה בקצתם אלפים וכן שנו שם בהם עמים ינגח יחדו וכי מה כבש יהושע והלא לא כבש אלא שלשים ואחד מלך מלמד שכבש מלכים ושלטונות שהיו מסוף העולם ועד סופו יחדו אפסי ארץ וכי מה ארצות כבש יהושע והלא לא כבש אלא פרטום (חלק) זה קטן אלא כל מלכים ששעבד היו מלכים ושלטונות ופשוטו של מקרא כי בעבור שבירך יוסף בתבואות דמה אותו לשור כי ורב תבואות בכח שור (משלי יד ד) ואמר שיהיה לבכור אשר יוליד הדר מלכות ירמוז ליהושע שהוא ראשון לבית יוסף ויהיה לו גדולה ומלכות וקרני ראם קרניו של שור הנזכר ובקרניו ינגח יחדו אפסי ארץ ואמר כי קרניו שהם שנים הם רבבות אפרים והם אלפי מנשה הקרן הימין לאפרים והשמאל למנשה והנה הזכיר בברכתו שהיו לרבבות ולאלפים כטעם רבבות אלפי ישראל (במדבר י לו)
@933 **וטעם שמח זבולן בצאתך** . בעת צאתך באניות סוחר ירמוז כי לחוף ימים ישכון ואתה יששכר באהליך ירמוז כי ראה מנוחה כי טוב ואת ארצו כי נעמה כברכת יעקב
@935 **ברוך מרחיב גד** . מלמד שהיה תחומו של גד מרחיב כלפי מזרח לשון רש"י מספרי (ברכה שנה) ור"א פירש כי בעבור שידמה אותו לאריה אמר ברוך המרחיב גד שנתן לו גבורה וכל רואיו יברחו ממנו ואין מי יצר לו והנכון שהוא על נחלתו כי שני השבטים אשר לקחו נחלתם בעבר הירדן לא לקחו אותה בגורל אבל נתן להם משה כל ממלכות סיחון ועוג ונחלתם רחבה ונסבה למעלה מכל השבטים ולא הזכיר בראובן זה כי די בתפלתו ואפשר גם כן כי לקחו בני גד יותר מבני ראובן כי היו גבורים ונתן להם כל הספר והערים אשר בנו רבות מאשר לראובן ועוד כי הם אשר בקשו הארץ ההיא תחלה כאשר פירשתי שם (במדבר לב ב) והנה הם סבת הרחבה הזאת
@938 **נפתלי שבע רצון** . שהיתה ארצו שבעה כל רצון יושביה לשון רש"י והנכון שהוא נמשך אל השם הנכבד יאמר שבע ומלא רצון השם הנכבד וברכתו אבל במדרש של רבי נחוניה בן הקנה אמרו בכתוב הזה אמר רבי אמורא מאי דכתיב ומלא ברכת ה' ים ודרום ירשה כך אמר משה אם תלך בחקותי תירש העולם הבא שהוא נמשל לים שנאמר (איוב יא ט) ורחבה מני ים והעולם הזה שהוא נמשל לדרום שנאמר (יהושע טו יט) כי ארץ הנגב נתתני ומתרגמינן ארעא דרומא ומאי דכתיב ירשה ירש היה לו לומר אלא אפילו הקב"ה בכלל והיינו רש יה למה הדבר דומה למלך שהיו לו שני אוצרות והקצה האחד מהם לסוף ימים רבים אמר לבנו טול מה שיש בשני אוצרות הללו אמר הבן שמא לא יתן לי מה שהקצה אמר לו טול הכל והיינו דכתיב ים ודרום ירשה יה רש הכל נתון לך ולואי תשמור דרכיו ועוד אמרו ומלא ברכת ה' ים ודרום ירשה אין ים אלא תורה שנאמר ורחבה מני ים וכל המדרש שם אם כן יהיה סוד הכתוב נפתלי שבע הרצון הממלא ברכת ה' שהיא הים הכלולה בכל מן הכל כענין שכתוב (קהלת א ז) כל הנחלים הולכים אל הים והוא ביתו של מלך משל למבקשים לראות את המלך שואלים אנה ביתו של מלך ואחר כך שואלים אנה המלך וגם העולם הזה הנגוב והיבש מן הרצון יירש בי"ה והמשכיל יבין
@939 **ברוך מבנים אשר** . אם המ"ם תבוא ליתרון כמ"ם תבורך מנשים (שופטים ה כד) הנחמדים מזהב ומפז רב (תהלים יט יא) וחברותיה יהיה תימה איך ימעט משה שאר השבטים לאמר שיבורך אשר יותר מכל בני יעקב ועוד שלא תתקיים ברכתו כי לא היה כן ורש"י כתב ראיתי בספרי (ברכה שנח) אין לך בכל השבטים שנתברך מבנים כאשר ואיני יודע כיצד והנה רבותינו נתכוונו לפרש "ברוך מבנים" שיהיה מבורך בבנים רבים שיוליד כמ"ם מבורכת ה' ארצו ממגד שמים מטל (פסוק יג) ולכך אמרו שכל שאר השבטים ברך אותם בגבורה או בנחלתם ואשר לבדו נתברך בבנים וגרסת הנוסחאות שלנו בספרי אין לך שנתברך בבנים כאשר אבל קיום הברכה הזאת לא נתבאר ואולי היא ממה שכתוב בדברי הימים (א ז מ) כל אלה בני אשר ראשי בית האבות ברורים גבורי חילים ראשי הנשיאים והתיחסם בצבא במלחמה מספרם אנשים עשרים וששה אלף ולא נאמר שם בשאר השבטים כשבח הזה ועל דרך הפשט ברוך מבנים אשר כטעם יהי רצוי אחיו יאמר שיהיה אשר מבורך מפי כל בני יעקב אביהם ורצוי לכל אחיו והטעם כי ארצו שמנה ומשם יבואו כל מעדני מלך לכל השבטים וכולם יאמרו תמיד יברך ה' הארץ הזאת אשר תוציא כפירות האלה ויהיה מ"ם "מבנים" כמ"ם מה' יצא הדבר (בראשית כד נ) מאל אביך (שם מט כה) ואונקלוס תרגם בריך מברכת בניא אשר נראה שרצה לומר כי יבואו מכל השבטים לאשר לקנות השמן ויהיו יהודה וישראל רוכליו בחטי מנית ופנג ודבש וצרי וכל זמרת הארץ שיביאו הכל וימכרו לו ויקנו השמן והנה הוא מבורך מכל הטוב הנמצא לכל השבטים והוא טעם "רצוי אחיו" שימכרו לו ויקנו ממנו לרצון להם ושוב מצאתי בבראשית רבה (עא יג) ותאמר לאה באשרי כי אשרוני בנות (בראשית ל יג) אמר רבי לוי לא לן אשר באכסניא מימיו ירש אשר גבי פלטריות מה שלא ירש יהודה ארצות ובני אשר ימנה וישוה וישוי ובריעה וסרח אחותם וגו' הוא אבי ברזית (דהי"א ז ל לא) רבי לוי ורבי סימון אמרו שהיו בנותיהם נאות והיו נשואות לכהנים שנמשחו בשמן זית וכו'
@940 **ברזל ונחשת מנעלך** . היה אשר בסוף ארץ ישראל כמו שכתוב בו (יהושע יט כו) ופגע בכרמל הימה וכתיב (שם פסוק כט) והיו תוצאותיו הימה ונאמר בו (שופטים א לא) אשר לא הוריש את יושבי עכו שהוא על ים הגדול כמו שאמרו (ב"ר כג יא) בראשונה עלה עד עכו ובשניה עד יפו ואם כן הנה ארצו מנעול ארץ ישראל ולכך אמר ברזל ונחשת מנעלך שיהיו לו דלתות נחושה ובריחי ברזל וכל הארץ נעולה בהם והוא רמז שישמור ה' כל הארץ מאויב ומתנקם או יאמר שלא יבואו זרים לשלול השמן כי לכל הארץ יובא מארצו באניות סוחר וכימיך דבאך הנראה לי במלה הזאת שהיא כמו זבאך כי האותיות האלה יתחלפו תמיד יאמר שבתה מדהבה (ישעיהו יד ד) במקום מזהבה וכל הארמית כן בכל לשון זביחה (שמות כ כא) וכן כל לשון זכירה (בראשית ח ח) וכן זהב (שם ב יא) זקן (ויקרא כא ה) זנב (שופטים טו ד) זרה הלאה (במדבר יז ב) ורבים ובלשון זיבה עצמה זב וזבה בכל לשונם יתחלפו לדל"ת כן ואמר ימי נזעכו (איוב יז א) במקום נדעכו וכן זחלתי ואירא (שם לב ו) כמו דחלתי ויאמר הכתוב וכימיך יהיה זבאך שתהיה ארצך זבת השמן הנזכר ואתה תהיה בו טובל רגלך כל ימיך לעולם גם אפשר ונכון הוא מה שפירשו בו שהוא הפוך מן דאבון נפש (לעיל כח סה) ויקראו ימי הזקנה דאבון כי הם ימי הרעה והצער ויקראו זמן הבחרות "ימיו" כי הם שלו לשמוח בהם ולהיטיב לבו הנה הטעם וכימי ילדותיך תהיה זקנתך וזה רמז שתתקיים שלותו וכבודו עוד כל ימי הארץ וראיתי בתרגום ירושלמי כיומי עולימתהון כיומי סיבתהון הוא הדבר שפירשתי
@945 **ויראהו ה' את כל הארץ** . כל ארץ ישראל אשר מעבר לירדן ואחרי כן הזכיר שהראה לו את גלעד עד דן והנה משה היה בחלקו של ראובן וחצי הר הגלעד ועריו היה לבני ראובן והחצי למנשה על כן פירושו מן הגלעד עד דן או היה גלעד בלבנון בארץ ישראל כדכתיב (ירמיהו כב ו) גלעד אתה לי ראש הלבנון והזכיר "עד דן" שהוא סוף תחום ארץ ישראל דכתיב ( כד ב) שוט נא בכל שבטי ישראל מדן ועד באר שבע והזכיר אפרים ומנשה שהיו בצפונה של ארץ ישראל וארץ יהודה שהוא בדרום כדכתיב (יהושע יח ה) יהודה יעמוד על גבולו מנגב ובית יוסף יעמדו על גבולם מצפון ויהודה נטל כל דרומה של ארץ ישראל מן הירדן ועד הים (ס"א הגדול ומנשה ואפרים כל צפונה ג"כ מן הירדן ועד הים) ודן נטל בצפונית מערבית והזכיר נפתלי הסמוך ליהודה ממזרח (שם יט לד) ולא הזכיר אשר ויששכר כי היו בתוך אפרים ומנשה דכתיב (שם יז י) ובאשר יפגעון מצפון וביששכר ממזרח ולא הזכיר שמעון כי מחלק בני יהודה נחלת שמעון (שם יט א) ולא הזכיר בנימין שהיה גבול גורלם בין בני יהודה ובין בני יוסף הנזכרים סמוך להם והזכיר עד הים האחרון לזבולון שהיה על חוף ימים או שהיה בכלל הנגב והככר ויזכיר בקעת ירחו בעבור היותה בקעה עמוקה ולא היתה נראית מראש ההר אבל הראהו במעשה נס והכלל שהראהו כל נחלת ישראל דכתיב (פסוק ד) זאת הארץ אשר נשבעתי וגו' ולרבותינו בספרי (ברכה שנז) מדרשים במקומות האלה אשר יזכיר בכתוב וטעם המראה הזאת אשר הראהו בעבור שהיתה הארץ מלאה כל טוב צבי לכל הארצות ומאשר היה גלוי לפניו רוב האהבה שהיה משה רבינו אוהב את ישראל שמחו ברבות הטובה בראות עיניו
@954 **אשר ידעו ה' פנים אל פנים** . שהיה לבו גס בו ומדבר אליו בכל שעה ושעה שירצה כענין שנאמר ועתה אעלה אל ה' (שמות לב ל) עמדו ואשמעה מה יצוה ה' לכם (במדבר ט ח) לשון רש"י ואיננו נכון כי היה אומר אשר ידע את השם פנים אל פנים אבל הוא מלשון ואדעך בשם (שמות לג יז) ואתה אמרת ידעתיך בשם (שם פסוק יב) יאמר שלא קם נביא עוד בישראל כמשה אשר גדלו השם להיות אליו פנים אל פנים בדבור וכן מה אדם ותדעהו (תהלים קמד ג) שתעשה לו כבוד לשום דעתך עליו כמו מה אנוש כי תגדלנו (איוב ז יז) ויתכן כי בעבור ששני אנשים המתראים פנים אל פנים נודעים זה לזה בראיה ההיא אמר "ידעו ה' פנים אל פנים" כי לא רצה להזכיר שידעו משה כן לכבוד של מעלה ואל תתמה במה שאמר בשבח משה אשר ידעו ה' פנים אל פנים ואמר (שמות לג יא) ודבר ה' אל משה פנים אל פנים ובכל ישראל נאמר גם כן (לעיל ה ד) פנים בפנים דבר ה' עמכם כי שם באר "מתוך האש" לומר ששמעו קולו מתוך האש בלבד ולא ראו הפנים וכן פירש (לעיל ד לו) ועל הארץ הראך את אשו הגדולה ודבריו שמעת מתוך האש ועל דרך האמת שידעו השם פנים אל פנים לדבקה בו בעת שתבוא הרוח במשה רבינו וכן היה בעת מתן תורה אבל לא השיגו הם אלא לקול מתוך האש והנה באר שכל נבואותיו של משה כיום מתן תורה ושאר הנביאים היתה עליהם יד ה' והבן זה
@955 **וטעם לכל האתת** . דבק עם ולא קם נביא עוד בישראל כמשה לכל האותות או יאמר שידעו השם פנים אל פנים באותות ובמופתים שכולם נעשו בשמו הגדול כמו שאמר (לעיל ד לז) ויוציאך בפניו בכחו הגדול וכבר פירשתי (לעיל יג ב) כי האותות הם הדברים שהזהיר בהם בתחלה כמו למחר יהיה האות הזה (שמות ח יט) ויאמר על כל הדבר שיקדים הנביא לאמר כן יבוא ויאתה לעתיד והמופתים הם הדברים שיעשו בשנוי התולדות כמו המטה אשר נהפך לנחש (שם ז ט) והנה גם לשאר הנביאים נעשו אותות ומופתים כאליהו ואלישע שעשו מופתים רבים אבל ההפלגה למשה רבינו בהם אמרו במדרש כל הנביאים כולם היו עושים נסים על ידי תפלה כחמה ליהושע ובן הצרפית ועצירת גשמים לאליהו ובן השונמית לאלישע אבל משה מיד היה עושה ואין המדרש הזה ברור והרב אמר במורה הנבוכים (ב לה) כי ההפלגה למשה רבינו הוא מה שאמר "לפרעה לכל עבדיו ולכל ארצו" ו"לעיני כל ישראל" כי היו לעיני החולקים עליו והמסכימים עמו אבל שאר הנביאים יעשו אותם ליחידים מבני אדם כענין שנאמר (מלכים ב ח ד) ספרה נא לי את כל הגדולות אשר עשה אלישע ואיננו נכון בעיני כי עצירת הגשמים לאליהו העצירה והביאה נתפרסמו מאד וגם היה בגזרה ממנו חי ה' אם יהיה השנים האלה טל ומטר כי אם לפי דברי (מלכים א יז א) ובהמשך ענין שלש השנים נתגלה מאד ובגוים נשמע וכתיב אם יש גוי וממלכה אשר לא שלח אדני וגו' וסוף הענין ההוא מגולה ומפורסם לחולקים עליו ולמסכימים עמו במעמד אחד דכתיב (שם פסוק יט) שלח קבץ אלי את כל ישראל אל הר הכרמל ואת נביאי הבעל ארבע מאות וגו' וכן עמידת השמש ליהושע היה באמת לעיני כל ישראל וראו אותה כל מלכי כנען הנלחמים בו והנשארים ורבותינו (ב"ר ו יד) יזכירו כן שראו אותם מסוף העולם ועד סופו והכתוב מפליג בו מאד (יהושע י יד) ולא היה כיום ההוא לפניו ואחריו לשמוע ה' בקול איש ובקריעת הירדן ובקריעת ים סוף לא נעשה ליחידים רק לכל ישראל וכתוב בה עוד (שם ה א) ויהי כשמוע כל מלכי האמורי אשר בעבר הירדן ימה וכל מלכי הכנעני אשר הוביש ה' את מי הירדן אבל לפי פשוטו של מקרא הכל קשור ומחובר יאמר שלא קם נביא עוד בישראל כמשה אשר ידעו השם פנים אל פנים ולעשות אותות ומופתים ביד חזקה ומורא גדול כמשה ואם עשו מקצת מהם לא הגיעו לרובם ולא למעלה הגדולה שבהם כי לא היה כיום סיני לפניו ואחריו וכן לא הגיעו אותות הנביאים לזמן הגדול אשר הגיע הוא עליו השלום כי אות המן תמידי ארבעים שנה ועמוד האש והענן גם הבאר והשלו על דעת רבותינו (תענית ט) ולכתם המדבר הגדול והנורא נחש שרף ועקרב וצמאון אשר אין מים ולא חסרו דבר ועל דרך האמת יאמר כי אותותיו ומופתיו של משה היו פנים אל פנים כמו שפירשתי (בפסוק י)
@956 **ולכל היד החזקה** . קריעת ים סוף שנאמר בו (שמות יד לא) וירא ישראל את היד הגדולה ולכל המורא הגדול מעמד הר סיני שנאמר בו (שם כ כ) לבעבור תהיה יראתו על פניכם ולפיכך הזכיר באלו שנעשו לעיני כל ישראל שכבר הזכיר כל הנעשה לפרעה ולכל עבדיו ולכל ארצו ובספרי (בסופו) ולכל היד החזקה זו מכת בכורות שנאמר בו (שמות ו א) כי ביד חזקה ישלחם ולכל המורא הגדול זו קריעת ים סוף ד"א ולכל המורא הגדול זו מתן תורה ועל דרך האמת "היד החזקה" זו מדת הדין כלשון היתה עלי יד ה' (יחזקאל לז א שם מ א) וכן כי יד ה' עשתה זאת (ישעיהו מא כ) ולכן יאמרו במשפט (רות א יג) כי יצאה בי יד ה' "והמורא הגדול" מדת הרחמים כענין שכתוב (ישעיהו ח יג) אותו תקדישו והוא מוראכם ולזה מתכוונים בספרי במכת בכורות ובקריעת ים סוף כי כתוב בם (שם סג יד) לעשות לך שם תפארת וטעם אשר עשה משה שהכין והראה זה לעיני כל העם כלשון ואת הנפש אשר עשו בחרן (בראשית יב ה) וימהר לעשות אותו (שם יח ז) לעשות את יום השבת (לעיל ה טו) כי משה לא עשה היד החזקה והמורא הגדול רק הכין אותם ובעבורו נעשו לעיני כל ישראל נשלמו חמשה הספרים האלה אשר קצרה בהם חכמת אגור ואיתיאל ואלפי ברכות והודאות לאל אשר גמלני כרחמיו וכרוב חסדיו ויבא אשר לבבי שואל והוא למען שמו יואל ובא לציון גואל במהרה בימינו יעמוד מיכאל לבנות הבית והאריאל ויקיים מקרא שכתוב על ידי יחזקאל (לז כח) וידעו הגוים כי אני השם מקדש את ישראל בהיות מקדשי בתוכם לעולם וברוך ה' אלהי ישראל מן העולם ועד העולם
